export function filterMergedDeskTailMarkers<T extends { time: number | UTCTimestamp }>(
  markers: ReadonlyArray<T>,
  candles: Candle[],
  timeframe: string
): T[] {
  return filterMergedDeskTailRocketRows(
    markers.map((m) => ({ ...m, time: Number(m.time) })),
