      0,
      Math.min(chartCandles.length - 1, chartCandles.length - 1 - (src.length - 1 - srcIdx))
    );
    const chartT = Number(chartCandles[chartIdx]?.time);
    return Number.isFinite(chartT) ? ({ ...r, time: chartT } as T) : r;
  });
}

export function dedupeMergedDeskRocketsOnePerBar<T extends { time: number; direction: 'LONG' | 'SHORT' }>(
  rows: ReadonlyArray<T>,
  chartBias?: 'LONG' | 'SHORT' | null
): T[] {
  const byBar = new Map<number, T>();
  for (const r of rows) {
    const t = Number(r.time);
    if (!Number.isFinite(t)) continue;
    const prev = byBar.get(t);
    if (!prev) {
      byBar.set(t, r);
      continue;
    }
    if (prev.direction === r.direction) continue;
    const pick = chartBias ?? prev.direction;
    byBar.set(t, r.direction === pick ? r : prev);
  }
  return [...byBar.values()].sort((a, b) => a.time - b.time);
}

