function candleIndexAtOrBeforeBar(candles: Candle[], t: number): number {
  if (!candles.length || !Number.isFinite(t)) return 0;
  let lo = 0;
  let hi = candles.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (Number(candles[mid]!.time) <= t) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

