/**
 * 통합·분석 — 스윙 피벗(고/저) 캔들 시가·가격에 정확히 맞춘 추세선·평행 채널.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import { normalizeChartTimeframe } from '@/lib/constants';
import { mergedWorkCandles } from '@/lib/mergedAnalysisOverlayTimes';
import {
  mergedDesk4hReferencePivotWindowForTf,
  mergedDesk4hReferenceSwingChannelLookback,
} from '@/lib/mergedDesk4hReference';
import { sanitizeChartCandlesForSeries } from '@/lib/volumeHistogramIntelligence';

export type CandlePivot = { i: number; price: number; time: number };

function workCandles(candles: Candle[], timeframe: string): Candle[] {
  return sanitizeChartCandlesForSeries(mergedWorkCandles(candles, timeframe), timeframe);
}

function pivotHigh(candles: Candle[], i: number, L: number, R: number): boolean {
  const h = candles[i]!.high;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || candles[j]!.high >= h) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= candles.length || candles[j]!.high > h) return false;
  }
  return true;
}

function pivotLow(candles: Candle[], i: number, L: number, R: number): boolean {
  const lo = candles[i]!.low;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || candles[j]!.low <= lo) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= candles.length || candles[j]!.low < lo) return false;
  }
  return true;
}

function channelLookback(timeframe: string): number {
  const tf = normalizeChartTimeframe(timeframe);
  if (tf === '1M') return 24;
  if (tf === '1w') return 34;
  if (tf === '1d') return 60;
  return mergedDesk4hReferenceSwingChannelLookback();
}

export function collectSwingPivots(
  candles: Candle[],
  timeframe: string
): { highs: CandlePivot[]; lows: CandlePivot[] } {
  const safe = workCandles(candles, timeframe);
  const lookback = Math.min(channelLookback(timeframe), safe.length - 4);
  if (lookback < 12) return { highs: [], lows: [] };

  const { L, R } = mergedDesk4hReferencePivotWindowForTf(timeframe);
  const start = Math.max(L, safe.length - lookback);
  const highs: CandlePivot[] = [];
  const lows: CandlePivot[] = [];

  for (let i = start + L; i < safe.length - R; i++) {
    if (pivotHigh(safe, i, L, R)) {
      highs.push({ i, price: safe[i]!.high, time: Number(safe[i]!.time) });
    }
    if (pivotLow(safe, i, L, R)) {
      lows.push({ i, price: safe[i]!.low, time: Number(safe[i]!.time) });
    }
  }
  return { highs, lows };
}

function pickTrendPair(pivots: CandlePivot[], minBars = 6): [CandlePivot, CandlePivot] | null {
  if (pivots.length < 2) return null;
  const p2 = pivots[pivots.length - 1]!;
  for (let k = pivots.length - 2; k >= 0; k--) {
    const p1 = pivots[k]!;
    if (p2.i - p1.i >= minBars) return [p1, p2];
  }
  return [pivots[pivots.length - 2]!, p2];
}

function priceOnLine(p1: CandlePivot, p2: CandlePivot, idx: number): number {
  const slope = (p2.price - p1.price) / Math.max(1, p2.i - p1.i);
  return p1.price + slope * (idx - p1.i);
}

function extendPivotLine(
  p1: CandlePivot,
  p2: CandlePivot,
  candles: Candle[],
  iEnd: number
): { time1: number; price1: number; time2: number; price2: number } {
  const t1 = p1.time;
  const t2 = Number(candles[iEnd]!.time);
  return {
    time1: t1,
    price1: p1.price,
    time2: t2,
    price2: priceOnLine(p1, p2, iEnd),
  };
}

export type CandleTrendChannelGeom = {
  upper: [CandlePivot, CandlePivot];
  lower: [CandlePivot, CandlePivot];
  upperEnd: { time: number; price: number };
  lowerEnd: { time: number; price: number };
  midEnd: { time: number; price: number };
};

export function computeCandleTrendChannelGeom(
  candles: Candle[],
  timeframe: string
): CandleTrendChannelGeom | null {
  const safe = workCandles(candles, timeframe);
  const { highs, lows } = collectSwingPivots(candles, timeframe);
  const hiPair = pickTrendPair(highs);
  const loPair = pickTrendPair(lows);
  if (!hiPair || !loPair) return null;

  const iEnd = safe.length - 1;
  const [h1, h2] = hiPair;
  const [l1, l2] = loPair;
  const upperEnd = extendPivotLine(h1, h2, safe, iEnd);
  const lowerEnd = extendPivotLine(l1, l2, safe, iEnd);
  const midPrice1 = (h1.price + l1.price) / 2;
  const midPrice2 = (upperEnd.price2 + lowerEnd.price2) / 2;

  return {
    upper: [h1, h2],
    lower: [l1, l2],
    upperEnd: { time: upperEnd.time2, price: upperEnd.price2 },
    lowerEnd: { time: lowerEnd.time2, price: lowerEnd.price2 },
    midEnd: { time: upperEnd.time2, price: midPrice2 },
  };
}

/** 피벗 고점·저점을 지나는 추세선 + 평행 채널 (캔들 시각·가격 스냅) */
export function buildCandleAnchoredSwingChannel(
  candles: Candle[],
  timeframe: string
): OverlayItem[] {
  const safe = workCandles(candles, timeframe);
  const geom = computeCandleTrendChannelGeom(candles, timeframe);
  if (!geom) return [];

  const [h1, h2] = geom.upper;
  const [l1, l2] = geom.lower;
  const upperLine = extendPivotLine(h1, h2, safe, safe.length - 1);
  const lowerLine = extendPivotLine(l1, l2, safe, safe.length - 1);
  const midPrice1 = (h1.price + l1.price) / 2;
  const midPrice2 = geom.midEnd.price;

  const tip = '캔들 피벗 추세선 — 스윙 고·저점 통과(조건부 참고)';

  const trend = (
    id: string,
    label: string,
    t1: number,
    p1: number,
    t2: number,
    p2: number,
    color: string,
    dash?: string
  ): OverlayItem => ({
    id,
    kind: 'trendLine',
    label,
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 1,
    time1: t1 as UTCTimestamp,
    price1: p1,
    time2: t2 as UTCTimestamp,
    price2: p2,
    confidence: 78,
    color,
    lineLabelColor: '#e2e8f0',
    category: 'chartPrimeTrendChannels',
    lineDash: dash,
    lineStrokeWidth: 2,
    noProject: true,
    overlayZoneExtraClass: 'merged-desk-candle-trend merged-swing-channel',
    labelTooltip: tip,
  });

  const band: OverlayItem = {
    id: 'merged-swing-channel-band',
    kind: 'channelBand',
    label: '스윙 채널',
    x1: 0,
    y1: 0.5,
    x2: 1,
    y2: 0.5,
    time1: h1.time as UTCTimestamp,
    time2: upperLine.time2 as UTCTimestamp,
    price1: upperLine.price1,
    price2: lowerLine.price2,
    confidence: 62,
    color: 'rgba(56,189,248,0.08)',
    category: 'chartPrimeTrendChannels',
    structureBias: upperLine.price2 >= upperLine.price1 ? 'bullish' : 'bearish',
    channelBand: {
      time1: h1.time,
      time2: upperLine.time2,
      priceHigh1: upperLine.price1,
      priceHigh2: upperLine.price2,
      priceLow1: lowerLine.price1,
      priceLow2: lowerLine.price2,
    },
    overlayZoneExtraClass: 'merged-desk-candle-trend merged-swing-channel',
    labelTooltip: tip,
  };

  return [
    band,
    trend(
      'merged-swing-channel-upper',
      '채널 상단',
      upperLine.time1,
      upperLine.price1,
      upperLine.time2,
      upperLine.price2,
      'rgba(56,189,248,0.72)',
      '6 4'
    ),
    trend(
      'merged-swing-channel-mid',
      '채널 중심',
      h1.time,
      midPrice1,
      upperLine.time2,
      midPrice2,
      'rgba(148,163,184,0.55)',
      '3 5'
    ),
    trend(
      'merged-swing-channel-lower',
      '채널 하단',
      lowerLine.time1,
      lowerLine.price1,
      lowerLine.time2,
      lowerLine.price2,
      'rgba(56,189,248,0.72)',
      '6 4'
    ),
    trend(
      'merged-desk-candle-trend-upper-anchor',
      '',
      h1.time,
      h1.price,
      h2.time,
      h2.price,
      'rgba(56,189,248,0.35)',
      '2 6'
    ),
    trend(
      'merged-desk-candle-trend-lower-anchor',
      '',
      l1.time,
      l1.price,
      l2.time,
      l2.price,
      'rgba(56,189,248,0.35)',
      '2 6'
    ),
  ];
}

/**
 * 통합·분석 — 핵심 지지 구간 · 어디서 지지 · 반등 목표(T1~Tmax) 분석·차트.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import { normalizeChartTimeframe } from '@/lib/constants';
import type { MergedBounceScenario } from '@/lib/mergedAnalysisBounceTargets';
import type { MergedKeyZone } from '@/lib/mergedAnalysisKeyZones';
import {
  mergedAnalysisChartZoneTimesSnapped,
  mergedWorkCandles,
  MERGED_ARES_ZONE_CAPTION_CLASS,
} from '@/lib/mergedAnalysisOverlayTimes';
import {
  buildCandleAnchoredSwingChannel,
  computeCandleTrendChannelGeom,
} from '@/lib/mergedDeskCandleTrendline';

export type MergedDeskSupportReboundAnalysis = {
  summaryKo: string;
  detailKo: string;
  supportPrice: number | null;
  supportLabelKo: string;
  reboundTargets: Array<{ label: string; price: number; sourceKo: string }>;
  overlays: OverlayItem[];
};

function fmtPx(p: number): string {
  const a = Math.abs(p);
  if (a >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (a >= 1) return p.toFixed(1);
  return p.toFixed(3);
}

function pickNearestSupportZone(
  keyZones: MergedKeyZone[],
  close: number,
  atr: number
): MergedKeyZone | null {
  const demand = keyZones
    .filter((z) => z.kind === 'demand')
    .filter((z) => z.price <= close + atr * 0.35)
    .sort((a, b) => {
      const da = Math.abs(close - a.price);
      const db = Math.abs(close - b.price);
      if (Math.abs(da - db) > atr * 0.05) return da - db;
      return b.score - a.score;
    });
  return demand[0] ?? null;
}

function estimateAtr(candles: Candle[], endIdx: number, period = 14): number {
  const start = Math.max(1, endIdx - period + 1);
  let sum = 0;
  let n = 0;
  for (let i = start; i <= endIdx; i++) {
    const c = candles[i]!;
    const p = candles[i - 1]!.close;
    sum += Math.max(c.high - c.low, Math.abs(c.high - p), Math.abs(c.low - p));
    n++;
  }
  return n > 0 ? sum / n : Math.abs(candles[endIdx]?.close ?? 1) * 0.01;
}

export function buildMergedDeskSupportReboundAnalysis(params: {
  candles: Candle[];
  timeframe: string;
  keyZones: MergedKeyZone[];
  bounceScenarios: MergedBounceScenario[];
}): MergedDeskSupportReboundAnalysis {
  const tf = normalizeChartTimeframe(params.timeframe);
  const work = mergedWorkCandles(params.candles, tf);
  if (work.length < 20) {
    return {
      summaryKo: '지지·반등 분석 — 데이터 부족',
      detailKo: '',
      supportPrice: null,
      supportLabelKo: '',
      reboundTargets: [],
      overlays: buildCandleAnchoredSwingChannel(params.candles, params.timeframe),
    };
  }

  const close = work[work.length - 1]!.close;
  const atr = estimateAtr(work, work.length - 1);
  const channelGeom = computeCandleTrendChannelGeom(params.candles, params.timeframe);
  const activeBounce =
    params.bounceScenarios.find((s) => s.active && s.direction === 'up') ??
    params.bounceScenarios.find((s) => s.direction === 'up') ??
    null;
  const supportZone = pickNearestSupportZone(params.keyZones, close, atr);

  const supportPrice =
    activeBounce?.anchorPrice ??
    supportZone?.price ??
    channelGeom?.lowerEnd.price ??
    null;
  const supportLabelKo =
    activeBounce?.labelKo ??
    supportZone?.labelKo ??
    '채널 하단 지지';

  const reboundFromScenario =
    activeBounce?.targets.map((t) => ({
      label: t.label,
      price: t.price,
      sourceKo: t.sourceKo,
    })) ?? [];

  const reboundTargets = [...reboundFromScenario];
  if (channelGeom && reboundTargets.length < 3) {
    const mid = channelGeom.midEnd.price;
    const upper = channelGeom.upperEnd.price;
    if (mid > close && !reboundTargets.some((t) => Math.abs(t.price - mid) < atr * 0.2)) {
      reboundTargets.push({ label: 'T채널중', price: mid, sourceKo: '채널 중심선' });
    }
    if (upper > close && !reboundTargets.some((t) => Math.abs(t.price - upper) < atr * 0.2)) {
      reboundTargets.push({ label: 'T채널상', price: upper, sourceKo: '채널 상단 추세선' });
    }
  }

  reboundTargets.sort((a, b) => a.price - b.price);

  const nextTarget = reboundTargets.find((t) => t.price > close + atr * 0.05) ?? reboundTargets[0];
  const supportDistPct =
    supportPrice != null && close > 0 ? ((close - supportPrice) / close) * 100 : null;

  const summaryKo =
    supportPrice != null && nextTarget
      ? `지지 ${fmtPx(supportPrice)} (${supportLabelKo}) · 반등 ${nextTarget.label} ${fmtPx(nextTarget.price)}`
      : '핵심 지지·반등 — 구간 탐색 중';

  const detailKo = [
    supportPrice != null
      ? `지지가 ${fmtPx(supportPrice)}${supportDistPct != null ? ` (현재가 대비 ${supportDistPct.toFixed(1)}%)` : ''}`
      : null,
    reboundTargets.length
      ? `반등 목표 ${reboundTargets.map((t) => `${t.label} ${fmtPx(t.price)}`).join(' → ')}`
      : null,
    activeBounce?.statusKo,
  ]
    .filter(Boolean)
    .join(' · ');

  const { t1, t2 } = mergedAnalysisChartZoneTimesSnapped(work, tf);
  const overlays: OverlayItem[] = [...buildCandleAnchoredSwingChannel(params.candles, params.timeframe)];

  if (supportPrice != null && supportZone) {
    overlays.push({
      id: `merged-desk-support-rebound-zone-${Math.round(supportPrice)}`,
      kind: 'demandZone',
      label: `지지 ${fmtPx(supportPrice)}`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: (supportZone.time1 || t1) as UTCTimestamp,
      time2: t2,
      price1: supportZone.top,
      price2: supportZone.bot,
      confidence: 88,
      color: 'rgba(45,212,191,0.14)',
      category: 'scenario',
      zoneFillPreserve: true,
      overlayZoneExtraClass: [
        'merged-desk-support-rebound',
        'merged-ares-key-zone',
        MERGED_ARES_ZONE_CAPTION_CLASS,
      ].join(' '),
      labelTooltip: `${supportLabelKo} · ${detailKo} (조건부 참고)`,
    });
  }

  for (const t of reboundTargets.slice(0, 4)) {
    overlays.push({
      id: `merged-desk-support-rebound-${t.label}-${Math.round(t.price)}`,
      kind: 'keyLevel',
      label: `반등 ${t.label} ${fmtPx(t.price)}`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: t1,
      time2: t2,
      price1: t.price,
      price2: t.price,
      confidence: 86,
      color: t.label.includes('채널') ? '#7dd3fc' : '#2dd4bf',
      category: 'structure',
      lineDash: t.label === 'Tmax' || t.label === 'T채널상' ? '4 4' : '10 6',
      lineStrokeWidth: t.label === 'T1' || t.label === 'T채널중' ? 2.2 : 1.8,
      overlayZoneExtraClass: 'merged-desk-support-rebound merged-ares-bounce-line merged-ares-bounce-line--up',
      labelTooltip: `${t.label} ${fmtPx(t.price)} · ${t.sourceKo}`,
    });
  }

  if (supportPrice != null) {
    overlays.push({
      id: `merged-desk-support-rebound-pin`,
      kind: 'label',
      label: `▼ 지지 ${fmtPx(supportPrice)}`,
      x1: 0.5,
      y1: 0.5,
      time1: (supportZone?.time2 ?? Number(work[work.length - 1]!.time)) as UTCTimestamp,
      price1: supportPrice,
      confidence: 90,
      color: '#2dd4bf',
      labelBackgroundColor: 'rgba(6,78,59,0.92)',
      labelTextColor: '#ecfdf5',
      category: 'labels',
      overlayZoneExtraClass: 'merged-desk-support-rebound-pin',
      labelTooltip: summaryKo,
    });
  }

  return {
    summaryKo,
    detailKo,
    supportPrice,
    supportLabelKo,
    reboundTargets,
    overlays,
  };
}

