/** 스윙 피벗 기반 평행 채널 — 상·중·하단 */
export function buildMergedSwingParallelChannel(params: {
  candles: Candle[];
  timeframe: string;
}): OverlayItem[] {
  const safe = swingWorkCandles(params.candles, params.timeframe);
  const lookback = Math.min(swingChannelLookback(params.timeframe), safe.length - 4);
  if (lookback < 12 || safe.length < lookback) return [];

  const { L, R } = swingPivotWindow(params.timeframe);
  const start = safe.length - lookback;
  const highs: Array<{ i: number; price: number; time: number }> = [];
  const lows: Array<{ i: number; price: number; time: number }> = [];

  for (let i = start + L; i < safe.length - R; i++) {
    if (pivotHigh(safe, i, L, R)) {
      highs.push({ i, price: safe[i]!.high, time: Number(safe[i]!.time) });
    }
    if (pivotLow(safe, i, L, R)) {
      lows.push({ i, price: safe[i]!.low, time: Number(safe[i]!.time) });
    }
  }

  if (highs.length < 2 || lows.length < 2) return [];

  const h1 = highs[highs.length - 2]!;
  const h2 = highs[highs.length - 1]!;
  const l1 = lows[lows.length - 2]!;
  const l2 = lows[lows.length - 1]!;

  const slopeH = (h2.price - h1.price) / Math.max(1, h2.i - h1.i);
  const slopeL = (l2.price - l1.price) / Math.max(1, l2.i - l1.i);
  const slope = (slopeH + slopeL) / 2;
  const midAnchorIdx = l2.i;
  const midAnchorPrice = (l2.price + h2.price) / 2;
  const halfWidth = Math.max(Math.abs(h2.price - l2.price) / 2, Math.abs(slope) * 2, safe[safe.length - 1]!.close * 0.001);

  const iEnd = safe.length - 1;
  const iStart = Math.max(0, safe.length - lookback);
  const tStart = Number(safe[iStart]!.time);
  const tEnd = Number(safe[iEnd]!.time);

  const upper1 = priceAtIndex(safe, iStart, slope, midAnchorIdx, midAnchorPrice) + halfWidth;
  const upper2 = priceAtIndex(safe, iEnd, slope, midAnchorIdx, midAnchorPrice) + halfWidth;
  const lower1 = priceAtIndex(safe, iStart, slope, midAnchorIdx, midAnchorPrice) - halfWidth;
  const lower2 = priceAtIndex(safe, iEnd, slope, midAnchorIdx, midAnchorPrice) - halfWidth;
  const mid1 = priceAtIndex(safe, iStart, slope, midAnchorIdx, midAnchorPrice);
  const mid2 = priceAtIndex(safe, iEnd, slope, midAnchorIdx, midAnchorPrice);

  const tip = '스윙 채널 — 피벗 평행(1~7일+ 참고·비보장)';

  const band: OverlayItem = {
    id: 'merged-swing-channel-band',
    kind: 'channelBand',
    label: '스윙 채널',
    x1: 0,
    y1: 0.5,
    x2: 1,
    y2: 0.5,
    time1: tStart,
    time2: tEnd,
    price1: upper1,
    price2: lower2,
    confidence: 62,
    color: 'rgba(56,189,248,0.08)',
    category: 'chartPrimeTrendChannels',
    structureBias: slope >= 0 ? 'bullish' : 'bearish',
    channelBand: {
      time1: tStart,
      time2: tEnd,
      priceHigh1: upper1,
      priceHigh2: upper2,
      priceLow1: lower1,
      priceLow2: lower2,
    },
    overlayZoneExtraClass: 'merged-swing-channel',
    labelTooltip: tip,
  };

  const line = (id: string, label: string, p1: number, p2: number, color: string, dash?: string): OverlayItem => ({
    id,
    kind: 'keyLevel',
    label,
    x1: 0,
    y1: 0.5,
    x2: 1,
    y2: 0.5,
    time1: tStart,
    time2: tEnd,
    price1: p1,
    price2: p2,
    confidence: 70,
    color,
    lineLabelColor: '#e2e8f0',
    category: 'keyLevel',
    lineDash: dash,
    labelTooltip: tip,
  });

  return [
    band,
    line('merged-swing-channel-upper', '채널 상단', upper1, upper2, 'rgba(56,189,248,0.55)', '6 4'),
    line('merged-swing-channel-mid', '채널 중심', mid1, mid2, 'rgba(148,163,184,0.45)', '3 5'),
    line('merged-swing-channel-lower', '채널 하단', lower1, lower2, 'rgba(56,189,248,0.55)', '6 4'),
  ];
}

