function buildDirectionSignalLabel(
  candles: Candle[],
  plan: UnifiedDeskTradePlan
): OverlayItem | null {
  if (plan.direction === 'NEUTRAL' || plan.entry <= 0) return null;
  const entryT = findEntryCandleTime(candles, plan, []);
  if (entryT == null) return null;

  const idx = candles.findIndex((c) => Number(c.time) === entryT);
  const bar = idx >= 0 ? candles[idx]! : candles[candles.length - 1]!;
  const isLong = plan.direction === 'LONG';
  const pinPrice = isLong ? bar.low : bar.high;

  return tvPinLabel({
    id: `merged-ares-mlsp-tv-signal-${plan.direction.toLowerCase()}-${entryT}`,
    label: isLong ? 'Long' : 'Short',
    time1: entryT,
    price1: pinPrice,
