/**
 * 통합·분석 Mirage TV zone — 형성 캔들(time1) → 마지막 봉 우측 픽셀 연장.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import { normalizeChartTimeframe } from '@/lib/constants';
import {
  mergedDeskLastCandleZoneTimes,
  snapMergedOverlayTimeToCandles,
} from '@/lib/mergedAnalysisOverlayTimes';

/** OB id `merged-ares-mlsp-tv-ob-bull-1739…` 에서 형성 봉 시각 */
export function parseMirageZoneFormationTime(
  item: Pick<OverlayItem, 'id' | 'time1'> | null | undefined
): number | null {
  if (!item) return null;
  const id = String(item.id || '');
  const obMatch = id.match(/merged-ares-mlsp-tv-ob-(?:bull|bear)-(\d+)$/);
  if (obMatch?.[1]) {
    const t = Number(obMatch[1]);
    if (Number.isFinite(t) && t > 0) return t;
  }
  const t1 = Number(item.time1);
  return Number.isFinite(t1) && t1 > 0 ? t1 : null;
}

function barStepMs(candles: Candle[]): number {
  const n = candles.length;
  if (n < 2) return 0;
  const d = Number(candles[n - 1]!.time) - Number(candles[n - 2]!.time);
  return Number.isFinite(d) && d > 0 ? d : 0;
}

/** align 단계 — time1=형성 봉, time2=마지막 봉 (우측 연장은 ChartView 픽셀) */
export function alignMirageTvZoneOverlayTimes(
  raw: OverlayItem,
  candles: Candle[],
  timeframe: string
): OverlayItem {
  const n = candles.length;
  if (n < 2) return raw;
  const tf = normalizeChartTimeframe(timeframe);
  const tLast = Number(snapMergedOverlayTimeToCandles(Number(candles[n - 1]!.time), candles));
  let tStart = parseMirageZoneFormationTime(raw) ?? tLast;
  tStart = Number(snapMergedOverlayTimeToCandles(tStart, candles));

  const step = barStepMs(candles);
  const tooNarrow = step > 0 ? tStart >= tLast - step * 0.6 : tStart >= tLast;

  if (tooNarrow || !Number.isFinite(tStart)) {
    const tail = mergedDeskLastCandleZoneTimes(candles, tf);
    if (tail) {
      tStart = Number(snapMergedOverlayTimeToCandles(Number(tail.t1), candles));
    } else {
      const idx = Math.max(0, n - Math.min(28, n - 1));
      tStart = Number(snapMergedOverlayTimeToCandles(Number(candles[idx]!.time), candles));
    }
  }

  if (tStart > tLast) {
    tStart = Number(snapMergedOverlayTimeToCandles(tLast, candles));
  }

  return {
    ...raw,
    time1: tStart as UTCTimestamp,
    time2: tLast as UTCTimestamp,
    zoneSpanOnly: false,
    x1: 0,
    x2: 1,
  };
}

export function resolveMirageZoneScreenSpan(params: {
  item: OverlayItem;
  candleSeries: Candle[];
  timeframe: string;
  timeToX: (t: number) => number;
  safeXLastBar: number;
  chartRightPx: number;
}): { xLeft: number; xRight: number } | null {
  const { item, candleSeries, timeframe, timeToX, safeXLastBar, chartRightPx } = params;
  if (!Number.isFinite(safeXLastBar) || candleSeries.length < 2) return null;

  const tForm = parseMirageZoneFormationTime(item);
  if (tForm == null) return null;

  let xLeft = timeToX(tForm);
  const xRight = Math.min(chartRightPx, safeXLastBar);
  const minW = Math.max(40, Math.round(chartRightPx * 0.06));

  if (!Number.isFinite(xLeft) || xRight - xLeft < minW) {
    const tail = mergedDeskLastCandleZoneTimes(candleSeries, timeframe);
    if (tail) {
      const xTail = timeToX(Number(tail.t1));
      if (Number.isFinite(xTail)) {
        xLeft = Number.isFinite(xLeft) ? Math.min(xLeft, xTail) : xTail;
      }
    }
  }

  if (!Number.isFinite(xLeft)) return null;

  const left = Math.min(xLeft, xRight - 8);
  const right = Math.max(xRight, left + 8);
  return { xLeft: left, xRight: right };
}

