 */
import type { Candle, OverlayItem } from '@/types';
import type { IChartApi, ISeriesApi, Logical } from 'lightweight-charts';
import { mergedDeskLastCandleZoneTimes } from '@/lib/mergedAnalysisOverlayTimes';

function candleIndexAtOrBefore(candles: Candle[], t: number): number {
  if (!candles.length) return 0;
  let lo = 0;
  let hi = candles.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (Number(candles[mid]!.time) <= t) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/** OB id `merged-ares-mlsp-tv-ob-bull-1739…` 에서 형성 봉 시각 */
export function parseMirageZoneFormationTime(
  item: Pick<OverlayItem, 'id' | 'time1'> | null | undefined
): number | null {
  if (!item) return null;
  const id = String(item.id || '');
  const obMatch = id.match(/merged-ares-mlsp-tv-ob-(?:bull|bear)-(\d+)$/);
  if (obMatch?.[1]) {
    const t = Number(obMatch[1]);
    if (Number.isFinite(t) && t > 0) return t;
  }
  const t1 = Number(item.time1);
  return Number.isFinite(t1) && t1 > 0 ? t1 : null;
}

export type MirageZoneFacePixelSpan = { xLeft: number; xRight: number };

/**
 * time→X 스냅 실패 시에도 logical 봉 인덱스로 좌·우 픽셀을 구한다.
 * xRight = 마지막 봉 중심 + 반봉폭 (우측 연장).
 */
export function resolveMirageZoneFacePixels(params: {
  item: OverlayItem;
  candles: Candle[];
  timeframe: string;
  timeScale: ReturnType<IChartApi['timeScale']>;
  series: ISeriesApi<'Candlestick'>;
  timeToX: (t: number) => number;
  chartRightPx: number;
}): MirageZoneFacePixelSpan | null {
  const { item, candles, timeframe, timeScale: ts, timeToX, chartRightPx } = params;
  const n = candles.length;
  if (n < 2) return null;

  const tForm = parseMirageZoneFormationTime(item);
  if (tForm == null) return null;

  let idxStart = candleIndexAtOrBefore(candles, tForm);
  const tail = mergedDeskLastCandleZoneTimes(candles, timeframe);
  if (tail) {
    idxStart = Math.min(idxStart, candleIndexAtOrBefore(candles, Number(tail.t1)));
  }
  const idxEnd = n - 1;
  if (idxStart > idxEnd) idxStart = Math.max(0, idxEnd - 1);

  const xAtIdx = (idx: number): number => {
    const clamped = Math.max(0, Math.min(n - 1, idx));
    try {
      const x = ts.logicalToCoordinate(clamped as unknown as Logical);
      if (x != null && Number.isFinite(Number(x))) return Number(x);
    } catch {
      /* ignore */
    }
    return timeToX(Number(candles[clamped]!.time));
  };

  let xLeft = xAtIdx(idxStart);
  let xRight = xAtIdx(idxEnd);

  const barW =
    idxEnd > 0 ? Math.max(6, Math.abs(xAtIdx(idxEnd) - xAtIdx(idxEnd - 1))) : 10;
  xRight += barW * 0.48;

  if (!Number.isFinite(xLeft)) xLeft = xAtIdx(Math.max(0, idxEnd - 12));
  if (!Number.isFinite(xRight)) xRight = xAtIdx(idxEnd) + barW;

  const minW = Math.max(56, chartRightPx * 0.12);
  if (xRight - xLeft < minW) {
    const widenIdx = Math.max(0, idxEnd - Math.max(12, Math.floor(n * 0.22)));
    xLeft = Math.min(xLeft, xAtIdx(widenIdx));
  }

  xLeft = Math.max(0, xLeft);
  xRight = Math.min(chartRightPx, Math.max(xRight, xLeft + minW));

  if (!Number.isFinite(xLeft) || !Number.isFinite(xRight) || xRight <= xLeft) {
    return null;
  }
  return { xLeft, xRight };
}

/** screenOverlays 파이프라인용 래퍼 */
export function resolveMirageZoneScreenSpan(params: {
  item: OverlayItem;
  candleSeries: Candle[];
  timeframe: string;
  timeScale: ReturnType<IChartApi['timeScale']>;
  series: ISeriesApi<'Candlestick'>;
  timeToX: (t: number) => number;
  safeXLastBar: number;
  chartRightPx: number;
}): MirageZoneFacePixelSpan | null {
  const span = resolveMirageZoneFacePixels({
    item: params.item,
    candles: params.candleSeries,
    timeframe: params.timeframe,
    timeScale: params.timeScale,
    series: params.series,
    timeToX: params.timeToX,
    chartRightPx: params.chartRightPx,
  });
  if (!span) return null;
  const xRight = Math.min(params.chartRightPx, Math.max(params.safeXLastBar, span.xRight));
  return { xLeft: span.xLeft, xRight };
}

