    parts.push(`거래소 체결 ${tape.tapeLabelKo} (${tape.tapeScore})`);
  }

  if (tagKo === '분석중') {
    parts.push('형성 직후 — 거래소·과거 표본 수집 중');
  }

  parts.push('선반영 참고 · 검증 필요');

  return {
    reboundPct: hist.reboundPct,
    holdPct: hist.holdPct,
    tapeScore: tape.tapeScore,
    tapeLabelKo: tape.tapeLabelKo,
    tagKo,
    detailKo: parts.join(' · '),
