function baseCaption(label: string): string {
  const raw = String(label || '').trim();
  if (!raw) return '존';
  return raw.split('·')[0]!.trim();
}

/** 학습 로그 → zone 면 클래스·짧은 태그 (확정 수익 아님) */
export function applyMirageZoneLearningToOverlays(
  overlays: OverlayItem[],
  symbol: string,
  timeframe: string
): OverlayItem[] {
  const weights = buildMirageZoneLearningWeights(symbol, timeframe);
  if (!Object.keys(weights).length) return overlays;
  return overlays.map((raw) => {
    if (!isMergedDeskMirageTvZoneOverlay(raw) || String(raw.kind) !== 'zone') return raw;
    const w = weights[String(raw.id || '')];
    if (!w || w.sampleCount < 1) return raw;
    const base = baseCaption(String(raw.label || ''));
    const extra = String(raw.overlayZoneExtraClass || '')
      .trim()
      .split(/\s+/)
      .filter(
        (c) =>
          c &&
          !c.startsWith('merged-ares-mlsp-tv-learn-')
      );
    extra.push(w.weightClass);
    const prior = String(raw.labelTooltip || '').trim();
    return {
      ...raw,
      label: `${base}·${w.tagKo}`,
      labelTooltip: prior
        ? `${prior} · 로그집계 ${w.sampleCount}건 — 조건부 참고`
        : `로그집계 ${w.sampleCount}건 — 조건부 참고`,
      overlayZoneExtraClass: extra.join(' '),
      zoneFillPreserve: true,
    };
  });
}

