'use client';

import type { OverlayItem } from '@/types';
import type { MirageZoneProactiveIntel } from '@/lib/mergedDeskMirageZoneExchangeIntel';
import {
  isMirageZoneFaceEnglish,
  mirageZoneFaceKoFromEn,
} from '@/lib/mergedDeskMirageZoneCompactLabel';
import type { MirageZoneFaceLang } from '@/lib/mergedDeskMirageZoneCompactLabel';

type Props = {
  zoneId: string;
  overlay: OverlayItem;
  intel: MirageZoneProactiveIntel | null;
  symbol: string;
  timeframe: string;
  faceLang?: MirageZoneFaceLang;
  onClose: () => void;
};

function fmtPx(p: number): string {
  if (p >= 1000) return p.toLocaleString(undefined, { maximumFractionDigits: 1 });
  if (p >= 1) return p.toFixed(2);
  return p.toFixed(4);
}

function parseReactiveKo(label: string): string | null {
  const parts = String(label || '')
    .split('·')
    .map((s) => s.trim());
  if (parts.length < 2) return null;
  const tail = parts[parts.length - 1]!;
  if (['분석', '안착', '확정', '안착실패', '재시도', '재시도실패', 'BOS', 'CHOCH'].includes(tail)) {
    return tail;
  }
  return null;
}

const ROLE_KO: Record<string, string> = {
  ob_bull: '수요 오더블럭',
  ob_bear: '공급 오더블럭',
  support: '지지',
  resistance: '저항',
  neutral: '존',
};

export function MergedDeskMirageZoneIntelHud({
  zoneId,
  overlay,
  intel,
  symbol,
  timeframe,
  faceLang,
  onClose,
}: Props) {
  const p1 = Number(overlay.price1);
  const p2 = Number(overlay.price2);
  const top = Math.max(p1, p2);
  const bot = Math.min(p1, p2);
  const center = (top + bot) / 2;
  const roleExtra = String(overlay.overlayZoneExtraClass || '');
  let roleKo = ROLE_KO.neutral;
  if (roleExtra.includes('ob-bull')) roleKo = ROLE_KO.ob_bull;
  else if (roleExtra.includes('ob-bear')) roleKo = ROLE_KO.ob_bear;
  else if (roleExtra.includes('resist')) roleKo = ROLE_KO.resistance;
  else if (roleExtra.includes('support')) roleKo = ROLE_KO.support;

  const faceIsEn = faceLang === 'en' || isMirageZoneFaceEnglish(overlay);
  const enChip = faceIsEn
    ? `${overlay.zoneFaceBase ?? ''}${overlay.zoneFaceSignal ? `·${overlay.zoneFaceSignal}` : ''}`.trim() ||
      String(overlay.label || '').trim()
    : null;
  const koShort =
    overlay.zoneFaceDetailKo ||
    (faceIsEn && enChip
      ? mirageZoneFaceKoFromEn(
          String(overlay.zoneFaceBase || enChip.split('·')[0] || ''),
          overlay.zoneFaceSignal
        )
      : null) ||
    intel?.tagKo ||
    String(overlay.label || '').replace(/·/g, ' · ');
  const reactiveKo = parseReactiveKo(String(overlay.labelTooltip || overlay.label || ''));
  const inval = intel?.invalidationPrice ?? null;

  return (
    <div className="merged-desk-mirage-zone-intel-hud" aria-label="Mirage zone 인텔">
      <div className="merged-desk-mirage-zone-intel-hud__head">
        <div>
          <div className="merged-desk-mirage-zone-intel-hud__title">Zone 설명</div>
          <div className="merged-desk-mirage-zone-intel-hud__sub">
            {symbol} · {timeframe} · {roleKo}
          </div>
        </div>
        <button type="button" className="tool-chip tool-chip-button" onClick={onClose}>
          닫기
        </button>
      </div>

      {enChip && (
        <div className="merged-desk-mirage-zone-intel-hud__enChip" title="차트 영어 라벨">
          {enChip}
        </div>
      )}

      <div className="merged-desk-mirage-zone-intel-hud__caption">{koShort}</div>
      <div className="merged-desk-mirage-zone-intel-hud__range">
        {fmtPx(bot)} – {fmtPx(top)} (중심 {fmtPx(center)})
      </div>

      {faceIsEn && (
        <div className="merged-desk-mirage-zone-intel-hud__hint">
          영어 라벨 탭 → 한글 설명 (조건부 참고 · 검증 필요)
        </div>
      )}

      <div className="merged-desk-mirage-zone-intel-hud__section">
        <div className="merged-desk-mirage-zone-intel-hud__sectionLabel">한글 상세</div>
        <div className="merged-desk-mirage-zone-intel-hud__tag">{intel?.tagKo ?? koShort}</div>
        {intel?.deepFaceKo && intel.deepFaceKo.length > 0 && (
          <div className="merged-desk-mirage-zone-intel-hud__line">
            심층 {intel.deepFaceKo.join(' · ')}
          </div>
        )}
        <div className="merged-desk-mirage-zone-intel-hud__line">
          {intel?.histSummaryKo ?? '과거 통계 수집 중'}
        </div>
        {intel?.tapeScore != null && (
          <div className="merged-desk-mirage-zone-intel-hud__line">체결 {intel.tapeLabelKo}</div>
        )}
        {intel?.depthLabelKo !== '호가—' && (
          <div className="merged-desk-mirage-zone-intel-hud__line">
            호가 {intel.depthLabelKo} · {intel.bidAskBiasKo}
          </div>
        )}
        {intel?.phaseProbPct != null && (
          <div className="merged-desk-mirage-zone-intel-hud__line">
            페이즈 {intel.phaseLabelKo}
            {intel.phaseAligned ? '' : ' · 역방향'}
          </div>
        )}
        {intel?.mtfAligned && (
          <div className="merged-desk-mirage-zone-intel-hud__line">MTF {intel.mtfLabelKo}</div>
        )}
        {intel?.detailKo && (
          <div className="merged-desk-mirage-zone-intel-hud__detail">{intel.detailKo}</div>
        )}
      </div>

      {reactiveKo && (
        <div className="merged-desk-mirage-zone-intel-hud__section">
          <div className="merged-desk-mirage-zone-intel-hud__sectionLabel">후반영 (터치 후)</div>
          <div className="merged-desk-mirage-zone-intel-hud__tag">{reactiveKo}</div>
        </div>
      )}

      {inval != null && (
        <div className="merged-desk-mirage-zone-intel-hud__section merged-desk-mirage-zone-intel-hud__section--warn">
          <div className="merged-desk-mirage-zone-intel-hud__sectionLabel">무효화</div>
          <div className="merged-desk-mirage-zone-intel-hud__line">
            종가 {fmtPx(inval)} 이탈 시 시나리오 무효
          </div>
        </div>
      )}

      <div className="merged-desk-mirage-zone-intel-hud__foot">
        조건부 참고 · 확정 수익 아님
      </div>
      <div className="merged-desk-mirage-zone-intel-hud__id">{zoneId}</div>
    </div>
  );
}

