/**
 * Mirage zone — 초보자용 한글 설명 (영어 라벨 탭 시 작은 카드).
 */
import type { OverlayItem } from '@/types';
import type { MirageZoneProactiveIntel, ZoneRole } from '@/lib/mergedDeskMirageZoneExchangeIntel';
import { mirageZoneEnTokenToKo } from '@/lib/mergedDeskMirageZoneCompactLabel';

const ROLE_TITLE: Record<ZoneRole, string> = {
  support: '받침 구간',
  resistance: '막힘 구간',
  ob_bull: '매수 많았던 구간',
  ob_bear: '매도 많았던 구간',
  neutral: '가격 구간',
};

const ROLE_INTRO: Record<ZoneRole, string> = {
  support: '가격이 내려올 때 여기서 다시 오를 수 있는 자리예요.',
  resistance: '가격이 올라올 때 여기서 막히거나 내려올 수 있어요.',
  ob_bull: '예전에 매수 주문이 몰렸던 가격대예요.',
  ob_bear: '예전에 매도 주문이 몰렸던 가격대예요.',
  neutral: '차트에서 눈여겨볼 가격 범위예요.',
};

const TOKEN_EASY: Record<string, string> = {
  받침가능: '과거에 여기서 가격이 다시 올라온 경우가 많았어요.',
  받침관찰: '받침이 될지 지켜보는 중이에요.',
  받침약: '받침이 약해 보여요. 한 번 더 확인이 필요해요.',
  받침유지: '아래쪽 지지가 유지되는 편이에요.',
  받침흔들: '받침이 조금 흔들리는 모습이에요.',
  위막힘: '과거에 여기서 가격이 내려간 경우가 많았어요.',
  위압력관찰: '위에서 막힐지 지켜보는 중이에요.',
  막힘약: '막힘이 약해 보여요.',
  위압력유지: '위쪽 압력이 유지되는 편이에요.',
  막힘흔들: '막힘이 조금 흔들리는 모습이에요.',
  마감확인: '이 가격대에 안착한 것으로 보여요.',
  마감대기: '아직 이 가격대에 완전히 안착했는지 기다리는 중이에요.',
  마감깨짐: '안착에 실패하고 가격이 벗어났어요.',
  구조전환↑: '하락 흐름이 끝나고 오름 쪽으로 바뀔 수 있어요.',
  구조전환↓: '오름 흐름이 끝나고 내림 쪽으로 바뀔 수 있어요.',
  구조바뀜↑: '차트 방향이 오름 쪽으로 바뀌는 신호예요.',
  구조바뀜↓: '차트 방향이 내림 쪽으로 바뀌는 신호예요.',
  예전거래많음: '예전에 이 가격대에서 거래가 아주 많았어요.',
  거래많았음: '예전에 이 근처에서 거래가 꽤 있었어요.',
  상승장맞음: '큰 흐름이 오름 쪽과 맞아 보여요.',
  하락장맞음: '큰 흐름이 내림 쪽과 맞아 보여요.',
  횡보장: '큰 방향 없이 오르내리는 구간이에요.',
  장세안맞음: '지금 큰 흐름과 이 구간 역할이 잘 안 맞아요.',
  매수유입: '최근 체결에서 매수가 더 많아 보여요.',
  매도유입: '최근 체결에서 매도가 더 많아 보여요.',
  매수압력: '매수 쪽 힘이 조금 더 있어 보여요.',
  매도압력: '매도 쪽 힘이 조금 더 있어 보여요.',
  수급혼조: '매수·매도가 섞여 있어 방향이 애매해요.',
  표본수집: '아직 판단할 데이터가 부족해요.',
};

function easyTokenLine(token: string): string | null {
  const t = token.trim();
  if (!t) return null;
  if (TOKEN_EASY[t]) return TOKEN_EASY[t]!;
  const fromEn = mirageZoneEnTokenToKo(t);
  if (fromEn !== t && TOKEN_EASY[fromEn]) return TOKEN_EASY[fromEn]!;
  return null;
}

function simplifyHist(hist: string): string {
  return hist
    .replace(/거절/g, '위에서 막힘')
    .replace(/반등/g, '아래서 받침')
    .replace(/터치/g, '도달')
    .replace(/표본 부족/g, '아직 기록이 적어요')
    .replace(/추가 봉 필요/g, '시간이 조금 더 필요해요');
}

function tapeEasy(intel: MirageZoneProactiveIntel): string | null {
  if (intel.tapeLabelKo === '매수우세') return '지금 체결은 매수가 더 활발해 보여요.';
  if (intel.tapeLabelKo === '매도우세') return '지금 체결은 매도가 더 활발해 보여요.';
  if (intel.tapeLabelKo.includes('매수')) return '매수 체결이 조금 더 많아 보여요.';
  if (intel.tapeLabelKo.includes('매도')) return '매도 체결이 조금 더 많아 보여요.';
  return null;
}

function depthEasy(intel: MirageZoneProactiveIntel): string | null {
  if (intel.bidAskBiasKo.includes('매수')) return '호가창에서 매수 쪽이 조금 두껍게 쌓여 있어요.';
  if (intel.bidAskBiasKo.includes('매도')) return '호가창에서 매도 쪽이 조금 두껍게 쌓여 있어요.';
  return null;
}

export type MirageZoneBeginnerCard = {
  title: string;
  enLabel: string | null;
  lines: string[];
  priceLine: string | null;
  warnLine: string | null;
};

export function buildMirageZoneBeginnerCard(params: {
  role: ZoneRole;
  overlay: OverlayItem;
  intel: MirageZoneProactiveIntel | null;
  enLabel?: string | null;
  bot: number;
  top: number;
}): MirageZoneBeginnerCard {
  const { role, overlay, intel, bot, top } = params;
  const enLabel =
    params.enLabel?.trim() ||
    `${overlay.zoneFaceBase ?? ''}${overlay.zoneFaceSignal ? `·${overlay.zoneFaceSignal}` : ''}`.trim() ||
    null;

  const lines: string[] = [ROLE_INTRO[role]];
  const seen = new Set<string>();

  const push = (line: string) => {
    const s = line.trim();
    if (!s || seen.has(s)) return;
    seen.add(s);
    lines.push(s);
  };

  const tagParts = String(intel?.tagKo || overlay.zoneFaceDetailKo || '')
    .split('·')
    .map((s) => s.trim())
    .filter(Boolean);
  for (const p of intel?.deepFaceKo ?? []) tagParts.push(p);
  for (const part of tagParts) {
    const easy = easyTokenLine(part);
    if (easy) push(easy);
    if (lines.length >= 5) break;
  }

  if (intel?.histSummaryKo && lines.length < 5) {
    push(simplifyHist(intel.histSummaryKo));
  }
  if (intel && lines.length < 5) {
    const t = tapeEasy(intel);
    if (t) push(t);
  }
  if (intel && lines.length < 5) {
    const d = depthEasy(intel);
    if (d) push(d);
  }
  if (intel?.mtfAligned && lines.length < 5) {
    push('여러 시간봉 흐름과도 맞아 보여요.');
  }

  if (lines.length < 2) {
    push('가격이 이 구간에 오면 어떻게 반응하는지 지켜보면 돼요.');
  }

  const fmt = (p: number) =>
    p >= 1000 ? p.toLocaleString(undefined, { maximumFractionDigits: 0 }) : p.toFixed(2);

  const priceLine = `가격대 ${fmt(bot)} ~ ${fmt(top)}`;

  let warnLine: string | null = null;
  const inval = intel?.invalidationPrice;
  if (inval != null && Number.isFinite(inval)) {
    const expectBull = role === 'support' || role === 'ob_bull';
    warnLine = expectBull
      ? `${fmt(inval)} 아래로 끝까지 내려가면 받침 실패로 볼 수 있어요.`
      : `${fmt(inval)} 위로 끝까지 올라가면 막힘 실패로 볼 수 있어요.`;
  }

  return {
    title: ROLE_TITLE[role],
    enLabel,
    lines: lines.slice(0, 4),
    priceLine,
    warnLine,
  };
}

'use client';

import type { OverlayItem } from '@/types';
import type { MirageZoneProactiveIntel } from '@/lib/mergedDeskMirageZoneExchangeIntel';
import { inferMirageZoneRole } from '@/lib/mergedDeskMirageZoneExchangeIntel';
import { buildMirageZoneBeginnerCard } from '@/lib/mergedDeskMirageZoneBeginnerKo';

type Props = {
  zoneId: string;
  overlay: OverlayItem;
  intel: MirageZoneProactiveIntel | null;
  onClose: () => void;
};

export function MergedDeskMirageZoneIntelHud({ overlay, intel, onClose }: Props) {
  const p1 = Number(overlay.price1);
  const p2 = Number(overlay.price2);
  const top = Math.max(p1, p2);
  const bot = Math.min(p1, p2);
  const role = inferMirageZoneRole(overlay);

  const enLabel =
    `${overlay.zoneFaceBase ?? ''}${overlay.zoneFaceSignal ? `·${overlay.zoneFaceSignal}` : ''}`.trim() ||
    String(overlay.label || '').trim();

  const card = buildMirageZoneBeginnerCard({
    role,
    overlay,
    intel,
    enLabel,
    bot,
    top,
  });

  return (
    <div
      className="merged-desk-mirage-zone-mini-card"
      role="dialog"
      aria-label="Zone 한글 설명"
      onClick={(e) => e.stopPropagation()}
    >
      <div className="merged-desk-mirage-zone-mini-card__head">
        {card.enLabel && (
          <span className="merged-desk-mirage-zone-mini-card__en">{card.enLabel}</span>
        )}
        <button
          type="button"
          className="merged-desk-mirage-zone-mini-card__close"
          onClick={onClose}
          aria-label="닫기"
        >
          ×
        </button>
      </div>
      <div className="merged-desk-mirage-zone-mini-card__title">{card.title}</div>
      <ul className="merged-desk-mirage-zone-mini-card__list">
        {card.lines.map((line) => (
          <li key={line}>{line}</li>
        ))}
      </ul>
      {card.priceLine && (
        <div className="merged-desk-mirage-zone-mini-card__price">{card.priceLine}</div>
      )}
      {card.warnLine && (
        <div className="merged-desk-mirage-zone-mini-card__warn">{card.warnLine}</div>
      )}
      <div className="merged-desk-mirage-zone-mini-card__foot">참고용 · 확정 수익 아님</div>
    </div>
  );
}

