input.contents:
/**
 * 통합·분석 Super AI — assets 353 전체 자료 기반 실시간 차트 작도.
 * (교육·참고용 — 확정 수익·투자 권유 아님)
 */
import type { AnalyzeResponse, Candle, OverlayItem } from '@/types';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import type { UnifiedDeskTradePlan } from '@/lib/unifiedDeskTradePlan';
import {
  applyAssetsDrawTemplate,
  buildLiveStructureFeatures,
  matchAssetsImagesToLive,
  type AssetsChartAiMatch,
} from '@/lib/assetsChartAiDraw';
import {
  getAssetsImageCatalog,
  getChartableAssetsEntries,
  type AssetsImageCatalogEntry,
} from '@/lib/assetsImageCatalog';
import { snapMergedOverlayTimeToCandles } from '@/lib/mergedAnalysisOverlayTimes';

export type MergedDeskAssetsSuperAiBrief = {
  titleKo: string;
  summaryKo: string;
  catalogTotal: number;
  catalogChartable: number;
  matchedAllCount: number;
  confidencePct: number;
  liveBiasKo: string;
  topRefs: AssetsChartAiMatch[];
  adaptiveLines: string[];
  drawCount: number;
  fusedZoneCount: number;
};

export type MergedDeskAssetsSuperAiPack = {
  overlays: OverlayItem[];
  brief: MergedDeskAssetsSuperAiBrief | null;
  matches: AssetsChartAiMatch[];
  allMatches: AssetsChartAiMatch[];
};

function pivotLows(candles: Candle[], wing = 2): Array<{ idx: number; price: number }> {
  const out: Array<{ idx: number; price: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.low >= candles[i - j]!.low || candles[i]!.low >= candles[i + j]!.low) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.low });
  }
  return out;
}

function pivotHighs(candles: Candle[], wing = 2): Array<{ idx: number; price: number }> {
  const out: Array<{ idx: number; price: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.high <= candles[i - j]!.high || candles[i]!.high <= candles[i + j]!.high) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.high });
  }
  return out;
}

function liveAnchors(candles: Candle[]) {
  const last = candles[candles.length - 1]!;
  const lows = pivotLows(candles.slice(-120), 2);
  const highs = pivotHighs(candles.slice(-120), 2);
  const support = lows.length ? lows[lows.length - 1]!.price : last.low;
  const resistance = highs.length ? highs[highs.length - 1]!.price : last.high;
  const close = last.close;
  return { support, resistance, close };
}

/** 353 전체 스코어 (차트 불가 UI 자료 포함 — 브리핑·매칭 통계) */
function scoreAllCatalogEntries(
  live: ReturnType<typeof buildLiveStructureFeatures>
): AssetsChartAiMatch[] {
  const cat = getAssetsImageCatalog();
  return cat.entries
    .map((entry) => {
      const { score, reasons } = scoreEntry(entry, live);
      return {
        id: entry.id,
        titleKo: entry.titleKo,
        score,
        reasonKo: reasons.length ? reasons.join('·') : '태그 유사',
        category: entry.category,
        tags: entry.tags,
      };
    })
    .filter((m) => m.score >= 0.12)
    .sort((a, b) => b.score - a.score);
}

function scoreEntry(
  entry: AssetsImageCatalogEntry,
  live: ReturnType<typeof buildLiveStructureFeatures>
): { score: number; reasons: string[] } {
  const reasons: string[] = [];
  let score = 0;
  const sf = entry.structureFeatures;
  const w = 0.11;

  if (sf.bos && live.bos) {
    score += w;
    reasons.push('BOS');
  }
  if (sf.choch && live.choch) {
    score += w;
    reasons.push('CHOCH');
  }
  if ((sf.fvg ?? 0) > 0 && (live.fvg ?? 0) > 0) {
    score += w;
    reasons.push('FVG');
  }
  if ((sf.ob ?? 0) > 0 && (live.ob ?? 0) > 0) {
    score += w;
    reasons.push('OB');
  }
  if (sf.sweep && live.sweep) {
    score += w;
    reasons.push('스윕');
  }

  const lp = String(live.pattern || '');
  const rp = String(sf.pattern || '');
  if (rp && lp && (lp === rp || lp.includes(rp) || rp.includes(lp))) {
    score += w * 1.4;
    reasons.push('패턴');
  } else if (rp && entry.chartable) {
    score += w * 0.2;
  }

  if (sf.bias && live.bias && sf.bias === live.bias) {
    score += w;
    reasons.push('방향');
  }

  if (entry.category === 'smc_candle' && (live.bos || live.choch)) score += 0.06;
  if (entry.category === 'tv_chart' && live.bias !== 'neutral') score += 0.04;
  if (entry.tags.some((t) => t === 'smc' || t === 'bos') && live.bos) score += 0.05;

  return { score: Math.min(1, score + 0.04), reasons };
}

function pickDiverseDrawRefs(matches: AssetsChartAiMatch[], max = 3): AssetsChartAiMatch[] {
  const chartableIds = new Set(getChartableAssetsEntries().map((e) => e.id));
  const pool = matches.filter((m) => chartableIds.has(m.id) && m.score >= 0.26);
  const out: AssetsChartAiMatch[] = [];
  const seenCat = new Set<string>();
  const seenPat = new Set<string>();

  for (const m of pool) {
    if (out.length >= max) break;
    const entry = getChartableAssetsEntries().find((e) => e.id === m.id);
    if (!entry?.drawTemplate?.elements?.length) continue;
    const cat = entry.category;
    const pat = String(entry.structureFeatures.pattern || cat);
    if (out.length >= 1 && seenCat.has(cat) && seenPat.has(pat) && m.score < 0.42) continue;
    seenCat.add(cat);
    seenPat.add(pat);
    out.push(m);
  }

  if (!out.length && pool[0]) out.push(pool[0]);
  return out;
}

function priceBucket(p: number): number {
  if (!(p > 0)) return 0;
  const step = Math.max(p * 0.0025, 1e-8);
  return Math.round(p / step);
}

function dedupeOverlays(items: OverlayItem[]): OverlayItem[] {
  const seen = new Map<string, OverlayItem>();
  for (const o of items) {
    const p1 = Number(o.price1 ?? 0);
    const p2 = Number(o.price2 ?? p1);
    const mid = o.kind === 'zone' ? (p1 + p2) / 2 : p1;
    const key = `${o.kind}:${priceBucket(mid)}:${String(o.label || '').slice(0, 12)}`;
    const prev = seen.get(key);
    const conf = Number(o.confidence ?? 0);
    if (!prev || conf > Number(prev.confidence ?? 0)) seen.set(key, o);
  }
  return [...seen.values()];
}

function remapToSuperAiPrefix(overlays: OverlayItem[], refId: string, weight: number): OverlayItem[] {
  return overlays.map((o) => {
    const id = String(o.id || '').replace(`merged-desk-assets-ai-${refId}`, 'super');
    return {
      ...o,
      id: id.startsWith('merged-desk-super-ai-') ? id : `merged-desk-super-ai-${refId}-${id.split('-').pop()}`,
      confidence: Math.min(0.95, (Number(o.confidence ?? 0.7) + weight) / 2),
      category: 'assetsChartAi',
      overlayZoneExtraClass: [
        String(o.overlayZoneExtraClass || ''),
        'merged-desk-super-ai',
        `merged-desk-super-ai-ref-${refId}`,
      ]
        .filter(Boolean)
        .join(' '),
    };
  });
}

function buildAdaptiveLiveZones(
  candles: Candle[],
  live: ReturnType<typeof buildLiveStructureFeatures>,
  tradePlan?: UnifiedDeskTradePlan | null
): OverlayItem[] {
  const { support, resistance, close } = liveAnchors(candles);
  const tEnd = Number(candles[candles.length - 1]!.time);
  const t1 = snapMergedOverlayTimeToCandles(Number(candles[Math.max(0, candles.length - 48)]!.time), candles);
  const pad = close * 0.004;
  const out: OverlayItem[] = [];

  const bull = live.bias === 'bullish' || tradePlan?.direction === 'LONG';
  const bear = live.bias === 'bearish' || tradePlan?.direction === 'SHORT';

  if (bull || !bear) {
    out.push({
      id: 'merged-desk-super-ai-live-demand',
      kind: 'zone',
      label: '',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: tEnd,
      price1: support + pad,
      price2: support - pad,
      confidence: 0.78,
      color: 'rgba(34,197,94,0.16)',
      category: 'assetsChartAi',
      overlayZoneExtraClass: 'merged-desk-super-ai merged-desk-super-ai-live-demand',
      zoneFillPreserve: true,
    });
  }
  if (bear || !bull) {
    out.push({
      id: 'merged-desk-super-ai-live-supply',
      kind: 'zone',
      label: '',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: tEnd,
      price1: resistance + pad,
      price2: resistance - pad,
      confidence: 0.78,
      color: 'rgba(239,68,68,0.14)',
      category: 'assetsChartAi',
      overlayZoneExtraClass: 'merged-desk-super-ai merged-desk-super-ai-live-supply',
      zoneFillPreserve: true,
    });
  }

  if (live.bos || live.choch) {
    const structPx = (support + resistance) / 2;
    out.push({
      id: 'merged-desk-super-ai-live-struct',
      kind: 'keyLevel',
      label: live.choch ? 'AI·CH' : 'AI·BOS',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: tEnd,
      price1: structPx,
      price2: structPx,
      lineDash: '5 4',
      confidence: 0.74,
      category: 'assetsChartAi',
      overlayZoneExtraClass: 'merged-desk-super-ai merged-desk-super-ai-live-struct',
    });
  }

  return out;
}

function buildSuperAiHeadLabel(
  candles: Candle[],
  brief: Omit<MergedDeskAssetsSuperAiBrief, 'drawCount' | 'fusedZoneCount'>
): OverlayItem {
  const last = candles[candles.length - 1]!;
  const t = snapMergedOverlayTimeToCandles(Number(last.time), candles);
  return {
    id: 'merged-desk-super-ai-head-label',
    kind: 'label',
    label: `SUPER ${brief.confidencePct}%`,
    x1: 0,
    y1: 0,
    time1: t,
    price1: last.high * 1.001,
    confidence: brief.confidencePct / 100,
    category: 'assetsChartAi',
    overlayZoneExtraClass: 'merged-desk-super-ai-head-label',
    labelBackgroundColor: 'rgba(49,46,129,0.92)',
    labelTextColor: '#c4b5fd',
  };
}

export function buildMergedDeskAssetsSuperAiPack(params: {
  candles: Candle[];
  analysis?: AnalyzeResponse | null;
  smcLeading?: MergedSmcLeadingContext | null;
  tradePlan?: UnifiedDeskTradePlan | null;
  enabled?: boolean;
}): MergedDeskAssetsSuperAiPack {
  const empty: MergedDeskAssetsSuperAiPack = {
    overlays: [],
    brief: null,
    matches: [],
    allMatches: [],
  };

  if (params.enabled === false || params.candles.length < 24) return empty;

  const cat = getAssetsImageCatalog();
  const live = buildLiveStructureFeatures({
    analysis: params.analysis,
    smcLeading: params.smcLeading,
    dominantPatternType: params.analysis?.dominantPattern?.type ?? null,
    dominantPatternBias: params.analysis?.dominantPattern?.bias ?? null,
  });

  const allMatches = scoreAllCatalogEntries(live);
  const chartMatches = matchAssetsImagesToLive(live, 12, 0.24);
  const drawRefs = pickDiverseDrawRefs(chartMatches.length ? chartMatches : allMatches, 3);

  if (!drawRefs.length && allMatches.length < 3) return empty;

  const hasPlan =
    (params.tradePlan?.entry ?? 0) > 0 && params.tradePlan?.direction !== 'NEUTRAL';

  let overlays: OverlayItem[] = [];
  for (const ref of drawRefs) {
    const entry = getChartableAssetsEntries().find((e) => e.id === ref.id);
    if (!entry) continue;
    const raw = applyAssetsDrawTemplate(entry, params.candles, { skipTradeLevels: hasPlan });
    overlays.push(...remapToSuperAiPrefix(raw, ref.id, ref.score));
  }

  overlays.push(...buildAdaptiveLiveZones(params.candles, live, params.tradePlan));
  overlays = dedupeOverlays(overlays).slice(0, 14);

  const avgScore =
    drawRefs.length > 0
      ? drawRefs.reduce((s, r) => s + r.score, 0) / drawRefs.length
      : allMatches.slice(0, 5).reduce((s, r) => s + r.score, 0) / Math.max(1, Math.min(5, allMatches.length));

  const confidencePct = Math.round(Math.min(92, Math.max(28, avgScore * 100 + drawRefs.length * 4)));

  const liveBiasKo =
    live.bias === 'bullish' ? '상승' : live.bias === 'bearish' ? '하락' : '관망';

  const adaptiveLines = [
    `353자료 중 ${allMatches.length}개 구조·태그 유사`,
    `실시간 ${liveBiasKo} + 스윙 받침·막힘에 맞춰 zone 조정`,
    drawRefs.length
      ? `참조 ${drawRefs.map((r) => r.titleKo).join(' · ')}`
      : '참조 자료 매칭 수집 중',
  ];

  const briefBase = {
    titleKo: 'Super AI · assets 작도',
    summaryKo: `assets ${cat.total}장 기반 · ${drawRefs.length}참조 융합 · ${liveBiasKo} — 조건부 참고`,
    catalogTotal: cat.total,
    catalogChartable: cat.chartable,
    matchedAllCount: allMatches.length,
    confidencePct,
    liveBiasKo,
    topRefs: drawRefs.length ? drawRefs : allMatches.slice(0, 3),
    adaptiveLines,
  };

  overlays.push(buildSuperAiHeadLabel(params.candles, briefBase));

  return {
    overlays,
    brief: {
      ...briefBase,
      drawCount: overlays.length,
      fusedZoneCount: overlays.filter((o) => o.kind === 'zone').length,
    },
    matches: chartMatches.slice(0, 8),
    allMatches: allMatches.slice(0, 24),
  };
}

/** Zone 미니카드 — Super AI 한 줄 */
export function superAiZoneHintKo(brief: MergedDeskAssetsSuperAiBrief | null): string | null {
  if (!brief) return null;
  return `Super AI가 assets ${brief.catalogTotal}장 중 ${brief.matchedAllCount}개를 보고, 지금 차트에 맞게 zone을 그렸어요.`;
}

