/**
 * assets 353 — 이미지 추출 없이, 자료에 담긴 구조·패턴 지식을
 * 라이브 캔들(OHLCV)에 적용 → 작도 + LONG/SHORT 판정.
 * (조건부 참고 — 확정 수익·투자 권유 아님)
 */
import type { AnalyzeResponse, Candle, OverlayItem } from '@/types';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import type { UnifiedDeskTradePlan } from '@/lib/unifiedDeskTradePlan';
import { getDominantPattern, runPatternVision } from '@/lib/patternVision/patternVisionEngine';
import { buildLiveStructureFeatures } from '@/lib/assetsChartAiDraw';
import {
  getAssetsImageCatalog,
  type AssetsImageCatalogEntry,
} from '@/lib/assetsImageCatalog';
import { snapMergedOverlayTimeToCandles } from '@/lib/mergedAnalysisOverlayTimes';
import { OVERLAY_COLORS } from '@/lib/overlayColors';

export type Assets353Direction = 'LONG' | 'SHORT' | 'NEUTRAL';

export type Assets353Verdict = {
  direction: Assets353Direction;
  longPct: number;
  shortPct: number;
  confidencePct: number;
  edgePct: number;
  headlineKo: string;
  actionKo: string;
  invalidationKo: string;
  reasonsKo: string[];
  matchedCount: number;
  catalogTotal: number;
  topKnowledgeKo: string[];
};

export type Assets353CandleKnowledgePack = {
  verdict: Assets353Verdict;
  overlays: OverlayItem[];
  overlayCount: number;
};

const CATEGORY_WEIGHT: Record<string, number> = {
  smc_candle: 1.35,
  tv_chart: 1.2,
  chinese_chart: 1.15,
  edu_forex: 1.05,
  harmonic: 1.1,
  screenshot: 0.85,
  unknown: 0.7,
  fulink_ui: 0.35,
};

function pivotLows(candles: Candle[], wing = 2): Array<{ idx: number; price: number }> {
  const out: Array<{ idx: number; price: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.low >= candles[i - j]!.low || candles[i]!.low >= candles[i + j]!.low) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.low });
  }
  return out;
}

function pivotHighs(candles: Candle[], wing = 2): Array<{ idx: number; price: number }> {
  const out: Array<{ idx: number; price: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.high <= candles[i - j]!.high || candles[i]!.high <= candles[i + j]!.high) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.high });
  }
  return out;
}

function knowledgeSimilarity(
  live: ReturnType<typeof buildLiveStructureFeatures>,
  entry: AssetsImageCatalogEntry
): number {
  const sf = entry.structureFeatures;
  let score = 0;
  const w = 0.1;
  if (sf.bos && live.bos) score += w;
  if (sf.choch && live.choch) score += w;
  if ((sf.fvg ?? 0) > 0 && (live.fvg ?? 0) > 0) score += w;
  if ((sf.ob ?? 0) > 0 && (live.ob ?? 0) > 0) score += w;
  if (sf.sweep && live.sweep) score += w;
  const lp = String(live.pattern || '');
  const rp = String(sf.pattern || '');
  if (rp && lp && (lp === rp || lp.includes(rp) || rp.includes(lp))) score += w * 1.5;
  else if (rp && entry.chartable) score += w * 0.15;
  if (sf.bias && live.bias && sf.bias === live.bias) score += w;
  if (entry.category === 'smc_candle' && (live.bos || live.choch)) score += 0.05;
  return Math.min(1, score + 0.03);
}

function biasFromPattern(pattern: string): 'bullish' | 'bearish' | 'neutral' {
  const p = pattern.toLowerCase();
  if (/double_top|head_shoulders|rising_wedge|desc_triangle|bear/.test(p)) return 'bearish';
  if (/double_bottom|inverse|falling_wedge|asc_triangle|bull/.test(p)) return 'bullish';
  return 'neutral';
}

function vote353Knowledge(
  live: ReturnType<typeof buildLiveStructureFeatures>,
  analysis?: AnalyzeResponse | null
): {
  longW: number;
  shortW: number;
  matched: Array<{ id: string; titleKo: string; score: number; bias: string }>;
} {
  const cat = getAssetsImageCatalog();
  let longW = 0;
  let shortW = 0;
  const matched: Array<{ id: string; titleKo: string; score: number; bias: string }> = [];

  for (const entry of cat.entries) {
    const sim = knowledgeSimilarity(live, entry);
    if (sim < 0.14) continue;
    const cw = CATEGORY_WEIGHT[entry.category] ?? 0.8;
    const w = sim * cw;
    const sf = entry.structureFeatures;
    let bias = sf.bias ?? 'neutral';
    if (bias === 'neutral' && sf.pattern) {
      const pb = biasFromPattern(String(sf.pattern));
      if (pb !== 'neutral') bias = pb;
    }
    if (bias === 'bullish') longW += w;
    else if (bias === 'bearish') shortW += w;
    matched.push({ id: entry.id, titleKo: entry.titleKo, score: sim, bias });
  }

  if (analysis?.verdict === 'LONG') longW += 0.45;
  else if (analysis?.verdict === 'SHORT') shortW += 0.45;

  const ls = analysis?.longScore ?? 0;
  const ss = analysis?.shortScore ?? 0;
  if (ls > ss + 8) longW += 0.25;
  else if (ss > ls + 8) shortW += 0.25;

  if (live.bias === 'bullish') longW += 0.2;
  else if (live.bias === 'bearish') shortW += 0.2;

  matched.sort((a, b) => b.score - a.score);
  return { longW, shortW, matched };
}

function resolveVerdict(
  longW: number,
  shortW: number,
  matched: Array<{ id: string; titleKo: string; score: number; bias: string }>,
  candles: Candle[],
  analysis?: AnalyzeResponse | null
): Assets353Verdict {
  const total = longW + shortW + 1e-9;
  const longPct = Math.round((longW / total) * 100);
  const shortPct = Math.round((shortW / total) * 100);
  const edge = Math.abs(longPct - shortPct);
  const cat = getAssetsImageCatalog();

  let direction: Assets353Direction = 'NEUTRAL';
  if (longPct >= 56 && edge >= 10) direction = 'LONG';
  else if (shortPct >= 56 && edge >= 10) direction = 'SHORT';

  const confidencePct = Math.min(88, Math.max(32, 40 + edge * 0.85 + Math.min(matched.length, 40) * 0.3));

  const topKnowledgeKo = matched.slice(0, 5).map((m) => m.titleKo.replace(/ 참조$/, ''));
  const reasonsKo: string[] = [
    `353자료 ${matched.length}개 패턴·구조와 현재 캔들이 맞음`,
    direction === 'LONG'
      ? `롱 쪽 가중 ${longPct}% (숏 ${shortPct}%)`
      : direction === 'SHORT'
        ? `숏 쪽 가중 ${shortPct}% (롱 ${longPct}%)`
        : `롱 ${longPct}% · 숏 ${shortPct}% — 방향 불명확`,
  ];

  if (analysis?.settlementZone?.state === 'confirmed') {
    reasonsKo.push(
      analysis.settlementZone.direction === 'LONG' ? '마감·안착 상방 확인' : '마감·안착 하방 확인'
    );
  }

  const last = candles[candles.length - 1]!;
  let invalidationKo = '무효화 — 핵심 구간 이탈 시 시나리오 재검토';
  if (direction === 'LONG') {
    const sup = pivotLows(candles.slice(-80), 2).pop()?.price ?? last.low;
    invalidationKo = `${sup.toFixed(0)} 아래 종가 마감 시 롱 시나리오 약화`;
  } else if (direction === 'SHORT') {
    const res = pivotHighs(candles.slice(-80), 2).pop()?.price ?? last.high;
    invalidationKo = `${res.toFixed(0)} 위 종가 마감 시 숏 시나리오 약화`;
  }

  const headlineKo =
    direction === 'LONG'
      ? `▲ 롱 — assets 지식 + 캔들 구조 (${longPct}%)`
      : direction === 'SHORT'
        ? `▼ 숏 — assets 지식 + 캔들 구조 (${shortPct}%)`
        : `◆ 관망 — 롱 ${longPct}% / 숏 ${shortPct}%`;

  const actionKo =
    direction === 'LONG'
      ? '받침 zone 터치 후 반등·마감 확인 시 롱 시나리오'
      : direction === 'SHORT'
        ? '막힘 zone 터치 후 하락·마감 확인 시 숏 시나리오'
        : '방향 확정 전 zone 반응만 관찰';

  return {
    direction,
    longPct,
    shortPct,
    confidencePct,
    edgePct: edge,
    headlineKo,
    actionKo,
    invalidationKo,
    reasonsKo,
    matchedCount: matched.length,
    catalogTotal: cat.total,
    topKnowledgeKo,
  };
}

function tWin(candles: Candle[], startBars = 48): { t1: number; t2: number } {
  const n = candles.length;
  const t2 = Number(candles[n - 1]!.time);
  const t1 = snapMergedOverlayTimeToCandles(
    Number(candles[Math.max(0, n - startBars)]!.time),
    candles
  );
  return { t1, t2 };
}

/** 라이브 캔들만으로 작도 — assets 지식(패턴 종류) + 방향 */
function drawLiveFromKnowledge(params: {
  candles: Candle[];
  direction: Assets353Direction;
  verdict: Assets353Verdict;
  smcLeading?: MergedSmcLeadingContext | null;
  tradePlan?: UnifiedDeskTradePlan | null;
  analysis?: AnalyzeResponse | null;
}): OverlayItem[] {
  const { candles, direction, smcLeading, tradePlan, analysis } = params;
  const n = candles.length;
  if (n < 24) return [];

  const { t1, t2 } = tWin(candles);
  const last = candles[n - 1]!;
  const lows = pivotLows(candles.slice(-100), 2);
  const highs = pivotHighs(candles.slice(-100), 2);
  const support = lows.length ? lows[lows.length - 1]!.price : last.low;
  const resistance = highs.length ? highs[highs.length - 1]!.price : last.high;
  const pad = last.close * 0.0035;
  const out: OverlayItem[] = [];

  const push = (o: OverlayItem) => {
    if (out.length >= 16) return;
    out.push({
      ...o,
      category: 'assetsChartAi',
      overlayZoneExtraClass: `merged-desk-super-ai merged-desk-super-ai-live ${o.overlayZoneExtraClass || ''}`.trim(),
    });
  };

  if (direction !== 'SHORT') {
    push({
      id: 'merged-desk-super-ai-knowledge-demand',
      kind: 'zone',
      label: 'SUP',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: support + pad,
      price2: support - pad,
      confidence: 0.8,
      color: 'rgba(34,197,94,0.18)',
      zoneFillPreserve: true,
    });
  }
  if (direction !== 'LONG') {
    push({
      id: 'merged-desk-super-ai-knowledge-supply',
      kind: 'zone',
      label: 'RES',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: resistance + pad,
      price2: resistance - pad,
      confidence: 0.8,
      color: 'rgba(239,68,68,0.15)',
      zoneFillPreserve: true,
    });
  }

  const ch = smcLeading?.lastChoch;
  if (ch && Number.isFinite(ch.price)) {
    push({
      id: 'merged-desk-super-ai-knowledge-choch',
      kind: ch.tag === 'BOS' ? 'bos' : 'choch',
      label: ch.tag === 'BOS' ? 'BOS' : 'CH',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(ch.time, candles),
      time2: t2,
      price1: ch.price,
      price2: ch.price,
      confidence: 0.78,
      lineDash: '5 4',
    });
  }

  const visible = candles.slice(-Math.min(n, 120));
  const patterns = analysis?.detectedVisionPatterns?.length
    ? (analysis.detectedVisionPatterns as import('@/types/patternVision').PatternVisionResult[])
    : runPatternVision(visible);
  const dom = getDominantPattern(patterns);
  if (dom) {
    const neck = dom.lines.find((l) => l.role === 'neckline');
    if (neck) {
      const np = (neck.startPrice + neck.endPrice) / 2;
      push({
        id: 'merged-desk-super-ai-knowledge-neck',
        kind: 'keyLevel',
        label: 'Neck',
        x1: 0,
        y1: 0,
        time1: t1,
        time2: t2,
        price1: np,
        price2: np,
        lineDash: '5 4',
        confidence: dom.confidence / 100,
      });
    }
  }

  const hasPlan = (tradePlan?.entry ?? 0) > 0 && tradePlan?.direction !== 'NEUTRAL';
  if (!hasPlan && direction !== 'NEUTRAL') {
    const entry = direction === 'LONG' ? support + pad * 0.5 : resistance - pad * 0.5;
    const stop = direction === 'LONG' ? support - pad * 2 : resistance + pad * 2;
    const risk = Math.abs(entry - stop);
    const tp = direction === 'LONG' ? entry + risk * 2 : entry - risk * 2;
    push({
      id: 'merged-desk-super-ai-knowledge-entry',
      kind: 'entry',
      label: 'Entry',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: entry,
      price2: entry,
      color: OVERLAY_COLORS.entry,
      confidence: 0.72,
    });
    push({
      id: 'merged-desk-super-ai-knowledge-stop',
      kind: 'stop',
      label: 'SL',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: stop,
      price2: stop,
      color: OVERLAY_COLORS.stop,
      confidence: 0.72,
    });
    push({
      id: 'merged-desk-super-ai-knowledge-tp',
      kind: 'target',
      label: 'TP',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: tp,
      price2: tp,
      color: OVERLAY_COLORS.target,
      confidence: 0.72,
    });
  }

  push({
    id: 'merged-desk-super-ai-knowledge-verdict-label',
    kind: 'label',
    label: direction === 'LONG' ? '▲ LONG' : direction === 'SHORT' ? '▼ SHORT' : '◆ WAIT',
    x1: 0,
    y1: 0,
    time1: t2,
    price1: last.high * 1.0012,
    confidence: params.verdict.confidencePct / 100,
    labelBackgroundColor:
      direction === 'LONG'
        ? 'rgba(6,78,59,0.92)'
        : direction === 'SHORT'
          ? 'rgba(127,29,29,0.92)'
          : 'rgba(51,65,85,0.92)',
    labelTextColor: '#f8fafc',
  });

  return out;
}

/** assets 353 지식 → 라이브 캔들 작도 + LONG/SHORT */
export function runAssets353CandleKnowledgeEngine(params: {
  candles: Candle[];
  analysis?: AnalyzeResponse | null;
  smcLeading?: MergedSmcLeadingContext | null;
  tradePlan?: UnifiedDeskTradePlan | null;
}): Assets353CandleKnowledgePack {
  const emptyVerdict: Assets353Verdict = {
    direction: 'NEUTRAL',
    longPct: 50,
    shortPct: 50,
    confidencePct: 0,
    edgePct: 0,
    headlineKo: '◆ 데이터 수집 중',
    actionKo: '캔들·분석 대기',
    invalidationKo: '—',
    reasonsKo: [],
    matchedCount: 0,
    catalogTotal: 353,
    topKnowledgeKo: [],
  };

  if (params.candles.length < 24) {
    return { verdict: emptyVerdict, overlays: [], overlayCount: 0 };
  }

  const live = buildLiveStructureFeatures({
    analysis: params.analysis,
    smcLeading: params.smcLeading,
    dominantPatternType: params.analysis?.dominantPattern?.type ?? null,
    dominantPatternBias: params.analysis?.dominantPattern?.bias ?? null,
  });

  const { longW, shortW, matched } = vote353Knowledge(live, params.analysis);
  const verdict = resolveVerdict(longW, shortW, matched, params.candles, params.analysis);
  const overlays = drawLiveFromKnowledge({
    candles: params.candles,
    direction: verdict.direction,
    verdict,
    smcLeading: params.smcLeading,
    tradePlan: params.tradePlan,
    analysis: params.analysis,
  });

  return { verdict, overlays, overlayCount: overlays.length };
}

