} from '@/lib/assets353Playbooks';
import { buildAssets353LiveDrawOverlays } from '@/lib/assets353LiveDrawAi';

export type Assets353Direction = 'LONG' | 'SHORT' | 'NEUTRAL';

export type Assets353MatchedKnowledge = {
  id: string;
  titleKo: string;
  score: number;
  bias: string;
  playbookId: string;
