/**
 * assets 353 SMC 차트 작도 — BOS·CH·OB·FVG·$$$·스윕·Entry/SL/TP.
 * 라이브 캔들만 사용 (이미지 좌표 추출 없음).
 */
import type { Candle, OverlayItem } from '@/types';
import type { Assets353Direction, Assets353Verdict } from '@/lib/assets353CandleKnowledgeEngine';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import { snapMergedOverlayTimeToCandles } from '@/lib/mergedAnalysisOverlayTimes';
import { OVERLAY_COLORS } from '@/lib/overlayColors';
import {
  atrRecent,
  collectOrderBlocks,
  rangeFromPivots,
  resolveStructureMarkPhase,
  structureMarksFu,
} from '@/lib/smcDeskOverlay';

const PREFIX = 'merged-desk-super-ai';
const CAT = 'assetsChartAi' as const;
const SWING_L = 2;
const MAX_OVERLAYS = 28;

type StructureMark = ReturnType<typeof structureMarksFu>[number];

type LiveFvg = {
  top: number;
  bot: number;
  time: number;
  bias: 'bullish' | 'bearish';
  idx: number;
};

type LiquidityPool = {
  price: number;
  time: number;
  side: 'buy' | 'sell';
};

type SweepMark = {
  price: number;
  time: number;
  side: 'high' | 'low';
};

function tWin(candles: Candle[], startBars = 56): { t1: number; t2: number } {
  const n = candles.length;
  const t2 = Number(candles[n - 1]!.time);
  const t1 = snapMergedOverlayTimeToCandles(
    Number(candles[Math.max(0, n - startBars)]!.time),
    candles
  );
  return { t1, t2 };
}

function pushOverlay(out: OverlayItem[], o: OverlayItem) {
  if (out.length >= MAX_OVERLAYS) return;
  out.push({
    ...o,
    category: CAT,
    overlayZoneExtraClass: `merged-desk-super-ai merged-desk-super-ai-smc ${o.overlayZoneExtraClass || ''}`.trim(),
  });
}

function markLabel(tag: StructureMark['tag']): string {
  if (tag === 'CHOCH') return 'CH';
  if (tag === 'MSB') return 'MSS';
  return 'BOS';
}

function markColor(bull: boolean, tag: StructureMark['tag']): string {
  if (tag === 'CHOCH') return bull ? OVERLAY_COLORS.chochBullish : OVERLAY_COLORS.chochBearish;
  return bull ? OVERLAY_COLORS.bosBullish : OVERLAY_COLORS.bosBearish;
}

function detectFvgs(candles: Candle[], lookback = 100): LiveFvg[] {
  const out: LiveFvg[] = [];
  const start = Math.max(2, candles.length - lookback);
  for (let i = start; i < candles.length; i++) {
    const c0 = candles[i - 2]!;
    const c2 = candles[i]!;
    if (c0.high < c2.low) {
      out.push({ top: c2.low, bot: c0.high, time: Number(c2.time), bias: 'bullish', idx: i });
    }
    if (c0.low > c2.high) {
      out.push({ top: c0.low, bot: c2.high, time: Number(c2.time), bias: 'bearish', idx: i });
    }
  }
  return out.slice(-5);
}

function pivotHighs(candles: Candle[], wing = SWING_L) {
  const out: Array<{ idx: number; price: number; time: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.high <= candles[i - j]!.high || candles[i]!.high <= candles[i + j]!.high) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.high, time: Number(candles[i]!.time) });
  }
  return out;
}

function pivotLows(candles: Candle[], wing = SWING_L) {
  const out: Array<{ idx: number; price: number; time: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.low >= candles[i - j]!.low || candles[i]!.low >= candles[i + j]!.low) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.low, time: Number(candles[i]!.time) });
  }
  return out;
}

function detectLiquidityPools(candles: Candle[], tolPct = 0.0016): LiquidityPool[] {
  const slice = candles.slice(-90);
  const out: LiquidityPool[] = [];
  const highs = pivotHighs(slice, SWING_L);
  const lows = pivotLows(slice, SWING_L);

  for (let i = 0; i < highs.length; i++) {
    for (let j = i + 1; j < highs.length; j++) {
      const a = highs[i]!;
      const b = highs[j]!;
      const mid = (a.price + b.price) / 2;
      if (mid > 0 && Math.abs(a.price - b.price) / mid <= tolPct) {
        out.push({ price: mid, time: b.time, side: 'buy' });
      }
    }
  }
  for (let i = 0; i < lows.length; i++) {
    for (let j = i + 1; j < lows.length; j++) {
      const a = lows[i]!;
      const b = lows[j]!;
      const mid = (a.price + b.price) / 2;
      if (mid > 0 && Math.abs(a.price - b.price) / mid <= tolPct) {
        out.push({ price: mid, time: b.time, side: 'sell' });
      }
    }
  }
  return out.slice(-4);
}

function detectSweeps(candles: Candle[], pools: LiquidityPool[]): SweepMark[] {
  const out: SweepMark[] = [];
  const recent = candles.slice(-40);
  const offset = candles.length - recent.length;

  for (const pool of pools) {
    for (let i = 0; i < recent.length; i++) {
      const c = recent[i]!;
      if (pool.side === 'buy') {
        if (c.high > pool.price * 1.0003 && c.close < pool.price) {
          out.push({ price: pool.price, time: Number(c.time), side: 'high' });
          break;
        }
      } else if (c.low < pool.price * 0.9997 && c.close > pool.price) {
        out.push({ price: pool.price, time: Number(c.time), side: 'low' });
        break;
      }
    }
  }

  const highs = pivotHighs(candles.slice(-60), SWING_L);
  const lows = pivotLows(candles.slice(-60), SWING_L);
  for (let hi = 0; hi < highs.length - 1; hi++) {
    const ref = highs[hi]!;
    for (let i = ref.idx + 1; i < candles.length; i++) {
      const c = candles[i]!;
      if (c.high > ref.price && c.close < ref.price) {
        out.push({ price: ref.price, time: Number(c.time), side: 'high' });
        break;
      }
    }
  }
  for (let lo = 0; lo < lows.length - 1; lo++) {
    const ref = lows[lo]!;
    for (let i = ref.idx + 1; i < candles.length; i++) {
      const c = candles[i]!;
      if (c.low < ref.price && c.close > ref.price) {
        out.push({ price: ref.price, time: Number(c.time), side: 'low' });
        break;
      }
    }
  }

  return out.slice(-3);
}

function drawStructureMarks(
  out: OverlayItem[],
  candles: Candle[],
  marks: StructureMark[],
  t2: number
) {
  const n = candles.length;
  for (const [i, mk] of marks.slice(-6).entries()) {
    const bull = mk.bias === 'bullish';
    const lbl = markLabel(mk.tag);
    const hex = markColor(bull, mk.tag);
    const phase = resolveStructureMarkPhase(mk, candles, n);
    const failed = phase === 'failed';
    const tMark = snapMergedOverlayTimeToCandles(Number(candles[mk.index]!.time), candles);
    const kind = mk.tag === 'CHOCH' ? 'choch' : 'bos';

    pushOverlay(out, {
      id: `${PREFIX}-smc-${kind}-${mk.index}-${i}`,
      kind,
      label: lbl,
      x1: 0,
      y1: 0,
      time1: tMark,
      time2: t2,
      price1: mk.price,
      price2: mk.price,
      confidence: failed ? 0.55 : 0.85,
      color: failed ? 'rgba(148,163,184,0.55)' : hex,
      lineDash: mk.tag === 'CHOCH' ? '6 4' : '4 3',
      structureBias: mk.bias,
      noProject: true,
    });

    pushOverlay(out, {
      id: `${PREFIX}-smc-${kind}-lbl-${mk.index}`,
      kind: 'label',
      label: lbl,
      x1: 0,
      y1: 0,
      time1: tMark,
      price1: mk.price * (bull ? 1.0008 : 0.9992),
      confidence: 0.8,
      labelBackgroundColor: bull ? 'rgba(22,101,52,0.9)' : 'rgba(127,29,29,0.9)',
      labelTextColor: '#f8fafc',
    });
  }
}

function drawOrderBlocks(
  out: OverlayItem[],
  candles: Candle[],
  start: number,
  atrVal: number,
  t2: number,
  preferBias?: 'bullish' | 'bearish'
) {
  const obs = collectOrderBlocks(candles, start, atrVal, 4);
  const sorted = [...obs].sort((a, b) => {
    if (preferBias === 'bullish') return (b.bull ? 1 : 0) - (a.bull ? 1 : 0);
    if (preferBias === 'bearish') return (a.bull ? 1 : 0) - (b.bull ? 1 : 0);
    return b.leftIdx - a.leftIdx;
  });

  for (const [i, ob] of sorted.slice(0, 3).entries()) {
    const t0 = snapMergedOverlayTimeToCandles(Number(candles[ob.leftIdx]!.time), candles);
    pushOverlay(out, {
      id: `${PREFIX}-smc-ob-${ob.leftIdx}-${i}`,
      kind: 'ob',
      label: 'OB',
      x1: 0,
      y1: 0,
      time1: t0,
      time2: t2,
      price1: ob.top,
      price2: ob.bot,
      confidence: 0.78,
      color: ob.bull ? 'rgba(34,197,94,0.18)' : 'rgba(239,68,68,0.16)',
      zoneFillPreserve: true,
      structureBias: ob.bull ? 'bullish' : 'bearish',
      overlayZoneExtraClass: ob.bull ? 'merged-desk-super-ai-ob-bull' : 'merged-desk-super-ai-ob-bear',
    });
  }
}

function drawFvgs(
  out: OverlayItem[],
  candles: Candle[],
  fvgs: LiveFvg[],
  t2: number,
  direction: Assets353Direction
) {
  const want = direction === 'LONG' ? 'bullish' : direction === 'SHORT' ? 'bearish' : null;
  for (const [i, fvg] of fvgs.entries()) {
    if (want && fvg.bias !== want) continue;
    pushOverlay(out, {
      id: `${PREFIX}-smc-fvg-${fvg.idx}-${i}`,
      kind: 'zone',
      label: fvg.bias === 'bearish' ? 'IFVG' : 'FVG',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(fvg.time, candles),
      time2: t2,
      price1: fvg.top,
      price2: fvg.bot,
      confidence: 0.74,
      color: fvg.bias === 'bullish' ? 'rgba(56,189,248,0.14)' : 'rgba(251,146,60,0.14)',
      zoneFillPreserve: true,
      overlayZoneExtraClass: 'merged-desk-super-ai-fvg',
    });
  }
}

function drawLiquidityAndSweeps(
  out: OverlayItem[],
  candles: Candle[],
  pools: LiquidityPool[],
  sweeps: SweepMark[],
  t1: number,
  t2: number
) {
  for (const [i, pool] of pools.entries()) {
    pushOverlay(out, {
      id: `${PREFIX}-smc-liq-${i}`,
      kind: 'keyLevel',
      label: '$$$',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(pool.time, candles),
      time2: t2,
      price1: pool.price,
      price2: pool.price,
      confidence: 0.72,
      lineDash: '2 5',
      color: 'rgba(250,204,21,0.7)',
    });
  }

  for (const [i, sw] of sweeps.entries()) {
    pushOverlay(out, {
      id: `${PREFIX}-smc-sweep-${i}`,
      kind: 'label',
      label: 'x',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(sw.time, candles),
      price1: sw.price * (sw.side === 'high' ? 1.001 : 0.999),
      confidence: 0.7,
      labelBackgroundColor: 'rgba(239,68,68,0.85)',
      labelTextColor: '#fff',
      overlayZoneExtraClass: 'merged-desk-super-ai-sweep',
    });
  }
}

function drawPoiZones(
  out: OverlayItem[],
  candles: Candle[],
  swingHigh: number,
  swingLow: number,
  tStart: number,
  t2: number,
  direction: Assets353Direction
) {
  const eq = (swingHigh + swingLow) / 2;
  const pad = (swingHigh - swingLow) * 0.02;
  pushOverlay(out, {
    id: `${PREFIX}-smc-poi-htf`,
    kind: 'zone',
    label: 'POI',
    x1: 0,
    y1: 0,
    time1: snapMergedOverlayTimeToCandles(tStart, candles),
    time2: t2,
    price1: swingHigh + pad,
    price2: swingLow - pad,
    confidence: 0.6,
    color: 'rgba(148,163,184,0.08)',
    zoneFillPreserve: true,
    overlayZoneExtraClass: 'merged-desk-super-ai-poi-htf',
  });

  if (direction === 'LONG') {
    pushOverlay(out, {
      id: `${PREFIX}-smc-poi-ltf-disc`,
      kind: 'zone',
      label: 'LTF',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(tStart, candles),
      time2: t2,
      price1: eq,
      price2: swingLow - pad,
      confidence: 0.65,
      color: 'rgba(34,197,94,0.1)',
      zoneFillPreserve: true,
    });
  } else if (direction === 'SHORT') {
    pushOverlay(out, {
      id: `${PREFIX}-smc-poi-ltf-prem`,
      kind: 'zone',
      label: 'LTF',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(tStart, candles),
      time2: t2,
      price1: swingHigh + pad,
      price2: eq,
      confidence: 0.65,
      color: 'rgba(239,68,68,0.1)',
      zoneFillPreserve: true,
    });
  }
}

function drawTradeSetup(
  out: OverlayItem[],
  candles: Candle[],
  direction: Assets353Direction,
  marks: StructureMark[],
  t1: number,
  t2: number,
  swingHigh: number,
  swingLow: number
) {
  if (direction === 'NEUTRAL') return;
  const last = candles[candles.length - 1]!;
  const atr = atrRecent(candles, 14) || last.close * 0.004;
  const lastCh = [...marks].reverse().find((m) => m.tag === 'CHOCH');
  const lows = pivotLows(candles.slice(-80), SWING_L);
  const highs = pivotHighs(candles.slice(-80), SWING_L);
  const support = lows.length ? lows[lows.length - 1]!.price : swingLow;
  const resistance = highs.length ? highs[highs.length - 1]!.price : swingHigh;

  let entry: number;
  let stop: number;
  let target: number;

  if (direction === 'LONG') {
    entry = lastCh ? lastCh.price + atr * 0.15 : support + atr * 0.2;
    stop = support - atr * 0.5;
    target = swingHigh;
  } else {
    entry = lastCh ? lastCh.price - atr * 0.15 : resistance - atr * 0.2;
    stop = resistance + atr * 0.5;
    target = swingLow;
  }

  const risk = Math.abs(entry - stop);
  if (risk <= 0) return;
  if (direction === 'LONG' && target <= entry) target = entry + risk * 2;
  if (direction === 'SHORT' && target >= entry) target = entry - risk * 2;

  pushOverlay(out, {
    id: `${PREFIX}-smc-entry`,
    kind: 'entry',
    label: 'Entry',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: entry,
    price2: entry,
    color: OVERLAY_COLORS.entry,
    confidence: 0.76,
  });
  pushOverlay(out, {
    id: `${PREFIX}-smc-sl`,
    kind: 'stop',
    label: 'SL',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: stop,
    price2: stop,
    color: OVERLAY_COLORS.stop,
    confidence: 0.76,
  });
  pushOverlay(out, {
    id: `${PREFIX}-smc-tp`,
    kind: 'target',
    label: 'TP',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: target,
    price2: target,
    color: OVERLAY_COLORS.target,
    confidence: 0.76,
  });
}

function drawVerdictOnChart(out: OverlayItem[], candles: Candle[], verdict: Assets353Verdict) {
  const last = candles[candles.length - 1]!;
  const t2 = Number(last.time);
  const dir = verdict.direction;
  const voteTag = `L${verdict.longPct}·S${verdict.shortPct}`;

  pushOverlay(out, {
    id: `${PREFIX}-smc-verdict`,
    kind: 'label',
    label:
      dir === 'LONG'
        ? `▲ LONG ${verdict.longPct}% · ${voteTag}`
        : dir === 'SHORT'
          ? `▼ SHORT ${verdict.shortPct}% · ${voteTag}`
          : `◆ WAIT · ${voteTag}`,
    x1: 0,
    y1: 0,
    time1: t2,
    price1: last.high * 1.0018,
    confidence: verdict.confidencePct / 100,
    labelBackgroundColor:
      dir === 'LONG' ? 'rgba(6,78,59,0.94)' : dir === 'SHORT' ? 'rgba(127,29,29,0.94)' : 'rgba(51,65,85,0.94)',
    labelTextColor: '#f8fafc',
    overlayZoneExtraClass: 'merged-desk-super-ai-head-label',
  });

  if (verdict.invalidationPrice != null && dir !== 'NEUTRAL') {
    const { t1, t2: te } = tWin(candles);
    pushOverlay(out, {
      id: `${PREFIX}-smc-inv`,
      kind: 'keyLevel',
      label: 'INV',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: te,
      price1: verdict.invalidationPrice,
      price2: verdict.invalidationPrice,
      confidence: 0.75,
      lineDash: '8 4',
      color: 'rgba(251,191,36,0.8)',
    });
  }
}

/** SMC 이미지(353자료) 스타일 — 차트 작도 전부 */
export function buildAssets353SmcChartOverlays(params: {
  candles: Candle[];
  direction: Assets353Direction;
  verdict: Assets353Verdict;
  smcLeading?: MergedSmcLeadingContext | null;
}): OverlayItem[] {
  const { candles, direction, verdict } = params;
  if (candles.length < 24) return [];

  const n = candles.length;
  const start = Math.max(SWING_L, n - 120);
  const { t1, t2 } = tWin(candles);
  const out: OverlayItem[] = [];

  const range = rangeFromPivots(candles, SWING_L, start, n - 2);
  let swingHigh = range?.swingHigh ?? Math.max(...candles.slice(start).map((c) => c.high));
  let swingLow = range?.swingLow ?? Math.min(...candles.slice(start).map((c) => c.low));
  const tStart = range?.tStart ?? Number(candles[start]!.time);
  const atrVal = atrRecent(candles, Math.min(50, n - 1));

  const marks = structureMarksFu(candles, SWING_L, 12);
  const fvgs = detectFvgs(candles);
  const pools = detectLiquidityPools(candles);
  const sweeps = detectSweeps(candles, pools);

  const preferBias =
    direction === 'LONG' ? 'bullish' : direction === 'SHORT' ? 'bearish' : undefined;

  drawPoiZones(out, candles, swingHigh, swingLow, tStart, t2, direction);
  drawStructureMarks(out, candles, marks, t2);
  drawOrderBlocks(out, candles, start, atrVal, t2, preferBias);
  drawFvgs(out, candles, fvgs, t2, direction);
  drawLiquidityAndSweeps(out, candles, pools, sweeps, t1, t2);

  if (params.smcLeading?.obs?.length) {
    for (const ob of params.smcLeading.obs.slice(-2)) {
      pushOverlay(out, {
        id: `${PREFIX}-smc-leading-ob-${ob.id}`,
        kind: 'ob',
        label: 'OB',
        x1: 0,
        y1: 0,
        time1: snapMergedOverlayTimeToCandles(ob.time, candles),
        time2: t2,
        price1: ob.high,
        price2: ob.low,
        confidence: 0.8,
        color: ob.bias === 'bullish' ? 'rgba(34,197,94,0.16)' : 'rgba(239,68,68,0.14)',
        zoneFillPreserve: true,
        structureBias: ob.bias,
      });
    }
  }

  drawTradeSetup(out, candles, direction, marks, t1, t2, swingHigh, swingLow);
  drawVerdictOnChart(out, candles, verdict);

  const topScenario = verdict.topMatches[0]?.scenarioKo;
  if (verdict.topPlaybookLabel || topScenario) {
    const last = candles[n - 1]!;
    const sub =
      verdict.topPlaybookLabel && topScenario
        ? `${verdict.topPlaybookLabel} · ${topScenario.slice(0, 24)}`
        : verdict.topPlaybookLabel || topScenario!.slice(0, 28);
    pushOverlay(out, {
      id: `${PREFIX}-smc-playbook`,
      kind: 'label',
      label: sub,
      x1: 0,
      y1: 0,
      time1: t1,
      price1: last.close,
      confidence: 0.65,
      labelBackgroundColor: 'rgba(15,23,42,0.88)',
      labelTextColor: '#a78bfa',
    });
  }

  return out;
}

/**
 * assets 353 SMC 차트 작도 — BOS·CH·OB·FVG·$$$·스윕·Entry/SL/TP.
 * 라이브 캔들만 사용 (이미지 좌표 추출 없음).
 */
import type { Candle, OverlayItem } from '@/types';
import type { Assets353Direction, Assets353Verdict } from '@/lib/assets353CandleKnowledgeEngine';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import { snapMergedOverlayTimeToCandles } from '@/lib/mergedAnalysisOverlayTimes';
import { OVERLAY_COLORS } from '@/lib/overlayColors';
import {
  atrRecent,
  collectOrderBlocks,
  rangeFromPivots,
  resolveStructureMarkPhase,
  structureMarksFu,
} from '@/lib/smcDeskOverlay';

const PREFIX = 'merged-desk-super-ai';
const CAT = 'assetsChartAi' as const;
const SWING_L = 2;
const MAX_OVERLAYS = 28;

type StructureMark = ReturnType<typeof structureMarksFu>[number];

type LiveFvg = {
  top: number;
  bot: number;
  time: number;
  bias: 'bullish' | 'bearish';
  idx: number;
};

type LiquidityPool = {
  price: number;
  time: number;
  side: 'buy' | 'sell';
};

type SweepMark = {
  price: number;
  time: number;
  side: 'high' | 'low';
};

function tWin(candles: Candle[], startBars = 56): { t1: number; t2: number } {
  const n = candles.length;
  const t2 = Number(candles[n - 1]!.time);
  const t1 = snapMergedOverlayTimeToCandles(
    Number(candles[Math.max(0, n - startBars)]!.time),
    candles
  );
  return { t1, t2 };
}

function pushOverlay(out: OverlayItem[], o: OverlayItem) {
  if (out.length >= MAX_OVERLAYS) return;
  out.push({
    ...o,
    category: CAT,
    overlayZoneExtraClass: `merged-desk-super-ai merged-desk-super-ai-smc ${o.overlayZoneExtraClass || ''}`.trim(),
  });
}

function markLabel(tag: StructureMark['tag']): string {
  if (tag === 'CHOCH') return 'CH';
  if (tag === 'MSB') return 'MSS';
  return 'BOS';
}

function markColor(bull: boolean, tag: StructureMark['tag']): string {
  if (tag === 'CHOCH') return bull ? OVERLAY_COLORS.chochBullish : OVERLAY_COLORS.chochBearish;
  return bull ? OVERLAY_COLORS.bosBullish : OVERLAY_COLORS.bosBearish;
}

function detectFvgs(candles: Candle[], lookback = 100): LiveFvg[] {
  const out: LiveFvg[] = [];
  const start = Math.max(2, candles.length - lookback);
  for (let i = start; i < candles.length; i++) {
    const c0 = candles[i - 2]!;
    const c2 = candles[i]!;
    if (c0.high < c2.low) {
      out.push({ top: c2.low, bot: c0.high, time: Number(c2.time), bias: 'bullish', idx: i });
    }
    if (c0.low > c2.high) {
      out.push({ top: c0.low, bot: c2.high, time: Number(c2.time), bias: 'bearish', idx: i });
    }
  }
  return out.slice(-5);
}

function pivotHighs(candles: Candle[], wing = SWING_L) {
  const out: Array<{ idx: number; price: number; time: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.high <= candles[i - j]!.high || candles[i]!.high <= candles[i + j]!.high) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.high, time: Number(candles[i]!.time) });
  }
  return out;
}

function pivotLows(candles: Candle[], wing = SWING_L) {
  const out: Array<{ idx: number; price: number; time: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.low >= candles[i - j]!.low || candles[i]!.low >= candles[i + j]!.low) {
        ok = false;
        break;
      }
    }
    if (ok) out.push({ idx: i, price: candles[i]!.low, time: Number(candles[i]!.time) });
  }
  return out;
}

function detectLiquidityPools(candles: Candle[], tolPct = 0.0016): LiquidityPool[] {
  const slice = candles.slice(-90);
  const out: LiquidityPool[] = [];
  const highs = pivotHighs(slice, SWING_L);
  const lows = pivotLows(slice, SWING_L);

  for (let i = 0; i < highs.length; i++) {
    for (let j = i + 1; j < highs.length; j++) {
      const a = highs[i]!;
      const b = highs[j]!;
      const mid = (a.price + b.price) / 2;
      if (mid > 0 && Math.abs(a.price - b.price) / mid <= tolPct) {
        out.push({ price: mid, time: b.time, side: 'buy' });
      }
    }
  }
  for (let i = 0; i < lows.length; i++) {
    for (let j = i + 1; j < lows.length; j++) {
      const a = lows[i]!;
      const b = lows[j]!;
      const mid = (a.price + b.price) / 2;
      if (mid > 0 && Math.abs(a.price - b.price) / mid <= tolPct) {
        out.push({ price: mid, time: b.time, side: 'sell' });
      }
    }
  }
  return out.slice(-4);
}

function detectSweeps(candles: Candle[], pools: LiquidityPool[]): SweepMark[] {
  const out: SweepMark[] = [];
  const recent = candles.slice(-40);

  for (const pool of pools) {
    for (let i = 0; i < recent.length; i++) {
      const c = recent[i]!;
      if (pool.side === 'buy') {
        if (c.high > pool.price * 1.0003 && c.close < pool.price) {
          out.push({ price: pool.price, time: Number(c.time), side: 'high' });
          break;
        }
      } else if (c.low < pool.price * 0.9997 && c.close > pool.price) {
        out.push({ price: pool.price, time: Number(c.time), side: 'low' });
        break;
      }
    }
  }

  const highs = pivotHighs(candles.slice(-60), SWING_L);
  const lows = pivotLows(candles.slice(-60), SWING_L);
  for (let hi = 0; hi < highs.length - 1; hi++) {
    const ref = highs[hi]!;
    for (let i = ref.idx + 1; i < candles.length; i++) {
      const c = candles[i]!;
      if (c.high > ref.price && c.close < ref.price) {
        out.push({ price: ref.price, time: Number(c.time), side: 'high' });
        break;
      }
    }
  }
  for (let lo = 0; lo < lows.length - 1; lo++) {
    const ref = lows[lo]!;
    for (let i = ref.idx + 1; i < candles.length; i++) {
      const c = candles[i]!;
      if (c.low < ref.price && c.close > ref.price) {
        out.push({ price: ref.price, time: Number(c.time), side: 'low' });
        break;
      }
    }
  }

  return out.slice(-3);
}

function drawStructureMarks(
  out: OverlayItem[],
  candles: Candle[],
  marks: StructureMark[],
  t2: number
) {
  const n = candles.length;
  for (const [i, mk] of marks.slice(-6).entries()) {
    const bull = mk.bias === 'bullish';
    const lbl = markLabel(mk.tag);
    const hex = markColor(bull, mk.tag);
    const phase = resolveStructureMarkPhase(mk, candles, n);
    const failed = phase === 'failed';
    const tMark = snapMergedOverlayTimeToCandles(Number(candles[mk.index]!.time), candles);
    const kind = mk.tag === 'CHOCH' ? 'choch' : 'bos';

    pushOverlay(out, {
      id: `${PREFIX}-smc-${kind}-${mk.index}-${i}`,
      kind,
      label: lbl,
      x1: 0,
      y1: 0,
      time1: tMark,
      time2: t2,
      price1: mk.price,
      price2: mk.price,
      confidence: failed ? 0.55 : 0.85,
      color: failed ? 'rgba(148,163,184,0.55)' : hex,
      lineDash: mk.tag === 'CHOCH' ? '6 4' : '4 3',
      structureBias: mk.bias,
      noProject: true,
    });

    pushOverlay(out, {
      id: `${PREFIX}-smc-${kind}-lbl-${mk.index}`,
      kind: 'label',
      label: lbl,
      x1: 0,
      y1: 0,
      time1: tMark,
      price1: mk.price * (bull ? 1.0008 : 0.9992),
      confidence: 0.8,
      labelBackgroundColor: bull ? 'rgba(22,101,52,0.9)' : 'rgba(127,29,29,0.9)',
      labelTextColor: '#f8fafc',
    });
  }
}

function drawOrderBlocks(
  out: OverlayItem[],
  candles: Candle[],
  start: number,
  atrVal: number,
  t2: number,
  preferBias?: 'bullish' | 'bearish'
) {
  const obs = collectOrderBlocks(candles, start, atrVal, 4);
  const sorted = [...obs].sort((a, b) => {
    if (preferBias === 'bullish') return (b.bull ? 1 : 0) - (a.bull ? 1 : 0);
    if (preferBias === 'bearish') return (a.bull ? 1 : 0) - (b.bull ? 1 : 0);
    return b.leftIdx - a.leftIdx;
  });

  for (const [i, ob] of sorted.slice(0, 3).entries()) {
    const t0 = snapMergedOverlayTimeToCandles(Number(candles[ob.leftIdx]!.time), candles);
    pushOverlay(out, {
      id: `${PREFIX}-smc-ob-${ob.leftIdx}-${i}`,
      kind: 'ob',
      label: 'OB',
      x1: 0,
      y1: 0,
      time1: t0,
      time2: t2,
      price1: ob.top,
      price2: ob.bot,
      confidence: 0.78,
      color: ob.bull ? 'rgba(34,197,94,0.18)' : 'rgba(239,68,68,0.16)',
      zoneFillPreserve: true,
      structureBias: ob.bull ? 'bullish' : 'bearish',
      overlayZoneExtraClass: ob.bull ? 'merged-desk-super-ai-ob-bull' : 'merged-desk-super-ai-ob-bear',
    });
  }
}

function drawFvgs(
  out: OverlayItem[],
  candles: Candle[],
  fvgs: LiveFvg[],
  t2: number,
  direction: Assets353Direction
) {
  const want = direction === 'LONG' ? 'bullish' : direction === 'SHORT' ? 'bearish' : null;
  for (const [i, fvg] of fvgs.entries()) {
    if (want && fvg.bias !== want) continue;
    pushOverlay(out, {
      id: `${PREFIX}-smc-fvg-${fvg.idx}-${i}`,
      kind: 'zone',
      label: fvg.bias === 'bearish' ? 'IFVG' : 'FVG',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(fvg.time, candles),
      time2: t2,
      price1: fvg.top,
      price2: fvg.bot,
      confidence: 0.74,
      color: fvg.bias === 'bullish' ? 'rgba(56,189,248,0.14)' : 'rgba(251,146,60,0.14)',
      zoneFillPreserve: true,
      overlayZoneExtraClass: 'merged-desk-super-ai-fvg',
    });
  }
}

function drawLiquidityAndSweeps(
  out: OverlayItem[],
  candles: Candle[],
  pools: LiquidityPool[],
  sweeps: SweepMark[],
  t2: number
) {
  for (const [i, pool] of pools.entries()) {
    pushOverlay(out, {
      id: `${PREFIX}-smc-liq-${i}`,
      kind: 'keyLevel',
      label: '$$$',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(pool.time, candles),
      time2: t2,
      price1: pool.price,
      price2: pool.price,
      confidence: 0.72,
      lineDash: '2 5',
      color: 'rgba(250,204,21,0.7)',
    });
  }

  for (const [i, sw] of sweeps.entries()) {
    pushOverlay(out, {
      id: `${PREFIX}-smc-sweep-${i}`,
      kind: 'label',
      label: 'x',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(sw.time, candles),
      price1: sw.price * (sw.side === 'high' ? 1.001 : 0.999),
      confidence: 0.7,
      labelBackgroundColor: 'rgba(239,68,68,0.85)',
      labelTextColor: '#fff',
      overlayZoneExtraClass: 'merged-desk-super-ai-sweep',
    });
  }
}

function drawPoiZones(
  out: OverlayItem[],
  candles: Candle[],
  swingHigh: number,
  swingLow: number,
  tStart: number,
  t2: number,
  direction: Assets353Direction
) {
  const eq = (swingHigh + swingLow) / 2;
  const pad = (swingHigh - swingLow) * 0.02;
  pushOverlay(out, {
    id: `${PREFIX}-smc-poi-htf`,
    kind: 'zone',
    label: 'POI',
    x1: 0,
    y1: 0,
    time1: snapMergedOverlayTimeToCandles(tStart, candles),
    time2: t2,
    price1: swingHigh + pad,
    price2: swingLow - pad,
    confidence: 0.6,
    color: 'rgba(148,163,184,0.08)',
    zoneFillPreserve: true,
    overlayZoneExtraClass: 'merged-desk-super-ai-poi-htf',
  });

  if (direction === 'LONG') {
    pushOverlay(out, {
      id: `${PREFIX}-smc-poi-ltf-disc`,
      kind: 'zone',
      label: 'LTF',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(tStart, candles),
      time2: t2,
      price1: eq,
      price2: swingLow - pad,
      confidence: 0.65,
      color: 'rgba(34,197,94,0.1)',
      zoneFillPreserve: true,
    });
  } else if (direction === 'SHORT') {
    pushOverlay(out, {
      id: `${PREFIX}-smc-poi-ltf-prem`,
      kind: 'zone',
      label: 'LTF',
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(tStart, candles),
      time2: t2,
      price1: swingHigh + pad,
      price2: eq,
      confidence: 0.65,
      color: 'rgba(239,68,68,0.1)',
      zoneFillPreserve: true,
    });
  }
}

function drawTradeSetup(
  out: OverlayItem[],
  candles: Candle[],
  direction: Assets353Direction,
  marks: StructureMark[],
  t1: number,
  t2: number,
  swingHigh: number,
  swingLow: number
) {
  if (direction === 'NEUTRAL') return;
  const last = candles[candles.length - 1]!;
  const atr = atrRecent(candles, 14) || last.close * 0.004;
  const lastCh = [...marks].reverse().find((m) => m.tag === 'CHOCH');
  const lows = pivotLows(candles.slice(-80), SWING_L);
  const highs = pivotHighs(candles.slice(-80), SWING_L);
  const support = lows.length ? lows[lows.length - 1]!.price : swingLow;
  const resistance = highs.length ? highs[highs.length - 1]!.price : swingHigh;

  let entry: number;
  let stop: number;
  let target: number;

  if (direction === 'LONG') {
    entry = lastCh ? lastCh.price + atr * 0.15 : support + atr * 0.2;
    stop = support - atr * 0.5;
    target = swingHigh;
  } else {
    entry = lastCh ? lastCh.price - atr * 0.15 : resistance - atr * 0.2;
    stop = resistance + atr * 0.5;
    target = swingLow;
  }

  const risk = Math.abs(entry - stop);
  if (risk <= 0) return;
  if (direction === 'LONG' && target <= entry) target = entry + risk * 2;
  if (direction === 'SHORT' && target >= entry) target = entry - risk * 2;

  pushOverlay(out, {
    id: `${PREFIX}-smc-entry`,
    kind: 'entry',
    label: 'Entry',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: entry,
    price2: entry,
    color: OVERLAY_COLORS.entry,
    confidence: 0.76,
  });
  pushOverlay(out, {
    id: `${PREFIX}-smc-sl`,
    kind: 'stop',
    label: 'SL',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: stop,
    price2: stop,
    color: OVERLAY_COLORS.stop,
    confidence: 0.76,
  });
  pushOverlay(out, {
    id: `${PREFIX}-smc-tp`,
    kind: 'target',
    label: 'TP',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: target,
    price2: target,
    color: OVERLAY_COLORS.target,
    confidence: 0.76,
  });
}

function drawVerdictOnChart(out: OverlayItem[], candles: Candle[], verdict: Assets353Verdict) {
  const last = candles[candles.length - 1]!;
  const t2 = Number(last.time);
  const dir = verdict.direction;
  const voteTag = `L${verdict.longPct}·S${verdict.shortPct}`;

  pushOverlay(out, {
    id: `${PREFIX}-smc-verdict`,
    kind: 'label',
    label:
      dir === 'LONG'
        ? `▲ LONG ${verdict.longPct}% · ${voteTag}`
        : dir === 'SHORT'
          ? `▼ SHORT ${verdict.shortPct}% · ${voteTag}`
          : `◆ WAIT · ${voteTag}`,
    x1: 0,
    y1: 0,
    time1: t2,
    price1: last.high * 1.0018,
    confidence: verdict.confidencePct / 100,
    labelBackgroundColor:
      dir === 'LONG' ? 'rgba(6,78,59,0.94)' : dir === 'SHORT' ? 'rgba(127,29,29,0.94)' : 'rgba(51,65,85,0.94)',
    labelTextColor: '#f8fafc',
    overlayZoneExtraClass: 'merged-desk-super-ai-head-label',
  });

  if (verdict.invalidationPrice != null && dir !== 'NEUTRAL') {
    const { t1, t2: te } = tWin(candles);
    pushOverlay(out, {
      id: `${PREFIX}-smc-inv`,
      kind: 'keyLevel',
      label: 'INV',
      x1: 0,
      y1: 0,
      time1: t1,
      time2: te,
      price1: verdict.invalidationPrice,
      price2: verdict.invalidationPrice,
      confidence: 0.75,
      lineDash: '8 4',
      color: 'rgba(251,191,36,0.8)',
    });
  }
}

/** SMC 이미지(353자료) 스타일 — 차트 작도 전부 */
export function buildAssets353SmcChartOverlays(params: {
  candles: Candle[];
  direction: Assets353Direction;
  verdict: Assets353Verdict;
  smcLeading?: MergedSmcLeadingContext | null;
}): OverlayItem[] {
  const { candles, direction, verdict } = params;
  if (candles.length < 24) return [];

  const n = candles.length;
  const start = Math.max(SWING_L, n - 120);
  const { t1, t2 } = tWin(candles);
  const out: OverlayItem[] = [];

  const range = rangeFromPivots(candles, SWING_L, start, n - 2);
  const swingHigh = range?.swingHigh ?? Math.max(...candles.slice(start).map((c) => c.high));
  const swingLow = range?.swingLow ?? Math.min(...candles.slice(start).map((c) => c.low));
  const tStart = range?.tStart ?? Number(candles[start]!.time);
  const atrVal = atrRecent(candles, Math.min(50, n - 1));

  const marks = structureMarksFu(candles, SWING_L, 12);
  const fvgs = detectFvgs(candles);
  const pools = detectLiquidityPools(candles);
  const sweeps = detectSweeps(candles, pools);

  const preferBias =
    direction === 'LONG' ? 'bullish' : direction === 'SHORT' ? 'bearish' : undefined;

  drawPoiZones(out, candles, swingHigh, swingLow, tStart, t2, direction);
  drawStructureMarks(out, candles, marks, t2);
  drawOrderBlocks(out, candles, start, atrVal, t2, preferBias);
  drawFvgs(out, candles, fvgs, t2, direction);
  drawLiquidityAndSweeps(out, candles, pools, sweeps, t2);

  if (params.smcLeading?.obs?.length) {
    for (const ob of params.smcLeading.obs.slice(-2)) {
      pushOverlay(out, {
        id: `${PREFIX}-smc-leading-ob-${ob.id}`,
        kind: 'ob',
        label: 'OB',
        x1: 0,
        y1: 0,
        time1: snapMergedOverlayTimeToCandles(ob.time, candles),
        time2: t2,
        price1: ob.high,
        price2: ob.low,
        confidence: 0.8,
        color: ob.bias === 'bullish' ? 'rgba(34,197,94,0.16)' : 'rgba(239,68,68,0.14)',
        zoneFillPreserve: true,
        structureBias: ob.bias,
      });
    }
  }

  drawTradeSetup(out, candles, direction, marks, t1, t2, swingHigh, swingLow);
  drawVerdictOnChart(out, candles, verdict);

  const topScenario = verdict.topMatches[0]?.scenarioKo;
  if (verdict.topPlaybookLabel || topScenario) {
    const last = candles[n - 1]!;
    const sub =
      verdict.topPlaybookLabel && topScenario
        ? `${verdict.topPlaybookLabel} · ${topScenario.slice(0, 24)}`
        : verdict.topPlaybookLabel || topScenario!.slice(0, 28);
    pushOverlay(out, {
      id: `${PREFIX}-smc-playbook`,
      kind: 'label',
      label: sub,
      x1: 0,
      y1: 0,
      time1: t1,
      price1: last.close,
      confidence: 0.65,
      labelBackgroundColor: 'rgba(15,23,42,0.88)',
      labelTextColor: '#a78bfa',
    });
  }

  return out;
}

