input.contents:
/**
 * SMC 차트 작도 — 트레이너/TV 스타일 (작은 라벨·얇은 선·정돈 zone).
 * BOS·CH·MSS·OB·FVG·$$$·진입/손절/익절 · 롱/숏.
 */
import type { Candle, OverlayItem } from '@/types';
import type { Assets353Direction, Assets353Verdict } from '@/lib/assets353CandleKnowledgeEngine';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import { snapMergedOverlayTimeToCandles } from '@/lib/mergedAnalysisOverlayTimes';
import { OVERLAY_COLORS } from '@/lib/overlayColors';
import {
  atrRecent,
  collectOrderBlocks,
  rangeFromPivots,
  resolveStructureMarkPhase,
  structureMarksFu,
} from '@/lib/smcDeskOverlay';

const PREFIX = 'merged-desk-smc';
const CAT = 'assetsChartAi' as const;
const SWING_L = 2;
const MAX = 14;
const SMC_LINE = 'merged-desk-smc-line merged-desk-smc-draw';
const SMC_ZONE = 'merged-desk-smc-zone merged-desk-smc-draw';

type Mark = ReturnType<typeof structureMarksFu>[number];

function tWin(candles: Candle[], bars = 48): { t1: number; t2: number } {
  const n = candles.length;
  return {
    t1: snapMergedOverlayTimeToCandles(Number(candles[Math.max(0, n - bars)]!.time), candles),
    t2: Number(candles[n - 1]!.time),
  };
}

function push(out: OverlayItem[], o: OverlayItem) {
  if (out.length >= MAX) return;
  out.push({ ...o, category: CAT });
}

function dirKo(bull: boolean): { arrow: string; text: string } {
  return bull ? { arrow: '↑', text: '상승' } : { arrow: '↓', text: '하락' };
}

function structLabel(tag: Mark['tag'], bull: boolean): string {
  const { arrow, text } = dirKo(bull);
  const base = tag === 'CHOCH' ? 'CH' : tag === 'MSB' ? 'MSS' : 'BOS';
  return `${base} ${arrow} ${text}`;
}

function detectFvgs(candles: Candle[], lookback = 80) {
  const out: Array<{ top: number; bot: number; time: number; bias: 'bullish' | 'bearish'; idx: number }> = [];
  const start = Math.max(2, candles.length - lookback);
  for (let i = start; i < candles.length; i++) {
    const c0 = candles[i - 2]!;
    const c2 = candles[i]!;
    if (c0.high < c2.low) {
      out.push({ top: c2.low, bot: c0.high, time: Number(c2.time), bias: 'bullish', idx: i });
    }
    if (c0.low > c2.high) {
      out.push({ top: c0.low, bot: c2.high, time: Number(c2.time), bias: 'bearish', idx: i });
    }
  }
  return out;
}

function pivotHighs(candles: Candle[], wing = SWING_L) {
  const out: Array<{ price: number; time: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.high <= candles[i - j]!.high || candles[i]!.high <= candles[i + j]!.high) ok = false;
    }
    if (ok) out.push({ price: candles[i]!.high, time: Number(candles[i]!.time) });
  }
  return out;
}

function pivotLows(candles: Candle[], wing = SWING_L) {
  const out: Array<{ price: number; time: number }> = [];
  for (let i = wing; i < candles.length - wing; i++) {
    let ok = true;
    for (let j = 1; j <= wing; j++) {
      if (candles[i]!.low >= candles[i - j]!.low || candles[i]!.low >= candles[i + j]!.low) ok = false;
    }
    if (ok) out.push({ price: candles[i]!.low, time: Number(candles[i]!.time) });
  }
  return out;
}

function liquidityPools(candles: Candle[]) {
  const highs = pivotHighs(candles.slice(-70), SWING_L);
  const lows = pivotLows(candles.slice(-70), SWING_L);
  const out: Array<{ price: number; time: number; bull: boolean }> = [];
  const tol = 0.0014;
  for (let i = 0; i < highs.length; i++) {
    for (let j = i + 1; j < highs.length; j++) {
      const mid = (highs[i]!.price + highs[j]!.price) / 2;
      if (mid > 0 && Math.abs(highs[i]!.price - highs[j]!.price) / mid <= tol) {
        out.push({ price: mid, time: highs[j]!.time, bull: false });
      }
    }
  }
  for (let i = 0; i < lows.length; i++) {
    for (let j = i + 1; j < lows.length; j++) {
      const mid = (lows[i]!.price + lows[j]!.price) / 2;
      if (mid > 0 && Math.abs(lows[i]!.price - lows[j]!.price) / mid <= tol) {
        out.push({ price: mid, time: lows[j]!.time, bull: true });
      }
    }
  }
  return out.slice(-2);
}

function pickMarks(marks: Mark[]): Mark[] {
  const choch = [...marks].reverse().find((m) => m.tag === 'CHOCH');
  const bos = [...marks].reverse().find((m) => m.tag === 'BOS' || m.tag === 'MSB');
  const out: Mark[] = [];
  if (choch) out.push(choch);
  if (bos && bos.index !== choch?.index) out.push(bos);
  return out;
}

function drawStructure(out: OverlayItem[], candles: Candle[], marks: Mark[], t2: number) {
  const n = candles.length;
  for (const mk of pickMarks(marks)) {
    const bull = mk.bias === 'bullish';
    const failed = resolveStructureMarkPhase(mk, candles, n) === 'failed';
    const t1 = snapMergedOverlayTimeToCandles(Number(candles[mk.index]!.time), candles);
    const kind = mk.tag === 'CHOCH' ? 'choch' : 'bos';
    const lineClass =
      mk.tag === 'CHOCH'
        ? `merged-ares-smc-choch-line ${SMC_LINE} merged-ares-smc-choch-line--${bull ? 'bull' : 'bear'}${failed ? ' merged-ares-smc-choch-line--failed' : ''}`
        : `${SMC_LINE} merged-desk-smc-bos-line merged-desk-smc-bos-line--${bull ? 'bull' : 'bear'}`;

    push(out, {
      id: `${PREFIX}-struct-${mk.index}`,
      kind,
      label: structLabel(mk.tag, bull),
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: mk.price,
      price2: mk.price,
      confidence: failed ? 0.5 : 0.82,
      lineStrokeWidth: 1.5,
      lineDash: mk.tag === 'CHOCH' ? '5 4' : undefined,
      structureBias: mk.bias,
      noProject: true,
      overlayZoneExtraClass: lineClass,
      lineLabelColor: bull ? '#4ade80' : '#f87171',
    });
  }
}

function drawOb(
  out: OverlayItem[],
  candles: Candle[],
  start: number,
  atrVal: number,
  t2: number,
  direction: Assets353Direction,
  smcLeading?: MergedSmcLeadingContext | null
) {
  const prefer = direction === 'LONG' ? 'bullish' : direction === 'SHORT' ? 'bearish' : undefined;
  let obTop: number | null = null;
  let obBot: number | null = null;
  let obTime = t2;
  let obBull = direction === 'LONG';

  if (smcLeading?.obs?.length) {
    const ob = [...smcLeading.obs]
      .reverse()
      .find((o) => !prefer || o.bias === prefer) ?? smcLeading.obs[smcLeading.obs.length - 1]!;
    obTop = ob.high;
    obBot = ob.low;
    obTime = snapMergedOverlayTimeToCandles(ob.time, candles);
    obBull = ob.bias === 'bullish';
  } else if (atrVal > 0) {
    const obs = collectOrderBlocks(candles, start, atrVal, 3);
    const pick =
      obs.find((o) => (prefer === 'bullish' ? o.bull : prefer === 'bearish' ? !o.bull : true)) ??
      obs[obs.length - 1];
    if (pick) {
      obTop = pick.top;
      obBot = pick.bot;
      obTime = snapMergedOverlayTimeToCandles(Number(candles[pick.leftIdx]!.time), candles);
      obBull = pick.bull;
    }
  }

  if (obTop == null || obBot == null) return;
  push(out, {
    id: `${PREFIX}-ob`,
    kind: 'ob',
    label: 'OB',
    x1: 0,
    y1: 0,
    time1: obTime,
    time2: t2,
    price1: obTop,
    price2: obBot,
    confidence: 0.75,
    zoneSpanOnly: true,
    zoneFillPreserve: true,
    structureBias: obBull ? 'bullish' : 'bearish',
    overlayZoneExtraClass: `${SMC_ZONE} ${obBull ? 'merged-ares-smc-ob--demand' : 'merged-ares-smc-ob--supply'}`,
    zoneFaceBase: 'OB',
    zoneFaceLang: 'en',
  });
}

function drawFvg(
  out: OverlayItem[],
  candles: Candle[],
  direction: Assets353Direction,
  t2: number
) {
  const fvgs = detectFvgs(candles);
  const want = direction === 'LONG' ? 'bullish' : direction === 'SHORT' ? 'bearish' : null;
  const fvg = [...fvgs].reverse().find((f) => !want || f.bias === want) ?? fvgs[fvgs.length - 1];
  if (!fvg) return;
  push(out, {
    id: `${PREFIX}-fvg`,
    kind: 'zone',
    label: fvg.bias === 'bearish' ? 'IFVG' : 'FVG',
    x1: 0,
    y1: 0,
    time1: snapMergedOverlayTimeToCandles(fvg.time, candles),
    time2: t2,
    price1: fvg.top,
    price2: fvg.bot,
    confidence: 0.7,
    zoneSpanOnly: true,
    zoneFillPreserve: true,
    overlayZoneExtraClass: `${SMC_ZONE} merged-desk-smc-fvg`,
    zoneFaceBase: fvg.bias === 'bearish' ? 'IFVG' : 'FVG',
    zoneFaceLang: 'en',
  });
}

function drawLiquidity(out: OverlayItem[], candles: Candle[], t2: number) {
  for (const [i, liq] of liquidityPools(candles).entries()) {
    const { arrow, text } = dirKo(liq.bull);
    push(out, {
      id: `${PREFIX}-liq-${i}`,
      kind: 'keyLevel',
      label: `$$$ ${arrow} ${text}`,
      x1: 0,
      y1: 0,
      time1: snapMergedOverlayTimeToCandles(liq.time, candles),
      time2: t2,
      price1: liq.price,
      price2: liq.price,
      confidence: 0.68,
      lineStrokeWidth: 1,
      lineDash: '3 5',
      color: 'rgba(251,191,36,0.65)',
      lineLabelColor: '#fbbf24',
      noProject: true,
      overlayZoneExtraClass: SMC_LINE,
    });
  }
}

function drawTrade(
  out: OverlayItem[],
  candles: Candle[],
  direction: Assets353Direction,
  marks: Mark[],
  t1: number,
  t2: number,
  swingHigh: number,
  swingLow: number
) {
  if (direction === 'NEUTRAL') return;
  const last = candles[candles.length - 1]!;
  const atr = atrRecent(candles, 14) || last.close * 0.004;
  const lastCh = [...marks].reverse().find((m) => m.tag === 'CHOCH');
  const support = pivotLows(candles.slice(-60), SWING_L).pop()?.price ?? swingLow;
  const resistance = pivotHighs(candles.slice(-60), SWING_L).pop()?.price ?? swingHigh;

  let entry: number;
  let stop: number;
  let target: number;
  if (direction === 'LONG') {
    entry = lastCh ? lastCh.price + atr * 0.12 : support + atr * 0.15;
    stop = support - atr * 0.45;
    target = swingHigh;
  } else {
    entry = lastCh ? lastCh.price - atr * 0.12 : resistance - atr * 0.15;
    stop = resistance + atr * 0.45;
    target = swingLow;
  }
  const risk = Math.abs(entry - stop);
  if (risk <= 0) return;
  if (direction === 'LONG' && target <= entry) target = entry + risk * 2;
  if (direction === 'SHORT' && target >= entry) target = entry - risk * 2;

  const rail = 'merged-desk-trade-rail-prominent merged-desk-smc-draw';
  push(out, {
    id: `${PREFIX}-entry`,
    kind: 'entry',
    label: '진입',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: entry,
    price2: entry,
    color: OVERLAY_COLORS.entry,
    lineStrokeWidth: 1.5,
    overlayZoneExtraClass: rail,
  });
  push(out, {
    id: `${PREFIX}-sl`,
    kind: 'stop',
    label: '손절',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: stop,
    price2: stop,
    color: OVERLAY_COLORS.stop,
    lineStrokeWidth: 1.5,
    overlayZoneExtraClass: rail,
  });
  push(out, {
    id: `${PREFIX}-tp`,
    kind: 'target',
    label: '익절',
    x1: 0,
    y1: 0,
    time1: t1,
    time2: t2,
    price1: target,
    price2: target,
    color: OVERLAY_COLORS.target,
    lineStrokeWidth: 1.5,
    overlayZoneExtraClass: rail,
  });
}

function drawVerdict(out: OverlayItem[], candles: Candle[], verdict: Assets353Verdict, t2: number) {
  const dir = verdict.direction;
  const label =
    dir === 'LONG' ? `▲ LONG ${verdict.longPct}%` : dir === 'SHORT' ? `▼ SHORT ${verdict.shortPct}%` : `◆ WAIT`;
  const last = candles[candles.length - 1]!;
  push(out, {
    id: `${PREFIX}-verdict`,
    kind: 'keyLevel',
    label,
    x1: 0,
    y1: 0,
    time1: snapMergedOverlayTimeToCandles(t2, candles),
    time2: t2,
    price1: last.close,
    price2: last.close,
    confidence: verdict.confidencePct / 100,
    lineStrokeWidth: 0,
    color: 'transparent',
    lineLabelColor: dir === 'LONG' ? '#4ade80' : dir === 'SHORT' ? '#f87171' : '#94a3b8',
    noProject: true,
    overlayZoneExtraClass: 'merged-desk-smc-verdict merged-desk-smc-draw',
  });
}

/** 트레이너 스타일 SMC 작도 */
export function buildAssets353SmcChartOverlays(params: {
  candles: Candle[];
  direction: Assets353Direction;
  verdict: Assets353Verdict;
  smcLeading?: MergedSmcLeadingContext | null;
}): OverlayItem[] {
  const { candles, direction, verdict, smcLeading } = params;
  if (candles.length < 24) return [];

  const n = candles.length;
  const start = Math.max(SWING_L, n - 100);
  const { t1, t2 } = tWin(candles);
  const range = rangeFromPivots(candles, SWING_L, start, n - 2);
  const swingHigh = range?.swingHigh ?? Math.max(...candles.slice(start).map((c) => c.high));
  const swingLow = range?.swingLow ?? Math.min(...candles.slice(start).map((c) => c.low));
  const atrVal = atrRecent(candles, Math.min(50, n - 1));
  const marks = structureMarksFu(candles, SWING_L, 12);
  const out: OverlayItem[] = [];

  drawStructure(out, candles, marks, t2);
  drawOb(out, candles, start, atrVal, t2, direction, smcLeading);
  drawFvg(out, candles, direction, t2);
  drawLiquidity(out, candles, t2);
  drawTrade(out, candles, direction, marks, t1, t2, swingHigh, swingLow);
  drawVerdict(out, candles, verdict, t2);

  return out;
}

