        ok?: boolean;
        match?: VolumeZoneBurstMatch | null;
        mtfPack?: VolumeZoneBurstMtfPack | null;
      };
      if (cancelled) return;
      if (data?.ok) {
        setVolumeZoneBurstMatch(data.match ?? null);
        setVolumeZoneBurstMtf(data.mtfPack ?? null);
