/**
 * Bitget 고래 거래량 — 현재 vs 과거 유사 이벤트 비교
 */
import type { Candle } from '@/types';
import {
  candleFingerprint,
  fingerprintLabelKo,
  matchCurrentWhaleVolume,
  sideKo,
  whaleHorizonsForTf,
  whaleTiersForTf,
  type BitgetWhaleVolumeCatalog,
  type WhaleCandleFingerprint,
  type WhaleCatalogBucket,
  type WhaleVolumeLiveMatch,
  type WhaleVolumeSide,
} from '@/lib/bitgetWhaleVolumeCatalog';
import { wadBuyVolume, wadSellVolume, smaTotalVolumeAt } from '@/lib/volumeHistogramIntelligence';

const FLAT_PCT = 0.12;

export type WhaleHistoryCompareRow = {
  time: number;
  dateKo: string;
  price: number;
  tierBtc: number;
  volBtc: number;
  side: WhaleVolumeSide;
  sideKo: string;
  fingerprintKo: string;
  similarityPct: number;
  outcomes: Array<{
    bars: number;
    usd: number;
    pct: number;
    dir: 'long' | 'short' | 'flat';
  }>;
};

export type WhaleTierCompareRow = {
  tierBtc: number;
  side: WhaleVolumeSide;
  sideKo: string;
  eventCount: number;
  longPct: number;
  shortPct: number;
  medianUsd: number | null;
};

export type BitgetWhaleVolumeComparePack = {
  symbol: string;
  timeframe: string;
  listingFromKo: string;
  totalBars: number;
  catalogEvents: number;
  current: WhaleVolumeLiveMatch;
  bucket: WhaleCatalogBucket | null;
  tierBreakdown: WhaleTierCompareRow[];
  similarHistory: WhaleHistoryCompareRow[];
  aggregateLongPct: number;
  aggregateShortPct: number;
  headlineKo: string;
  summaryKo: string;
};

function eventVolumes(c: Candle) {
  const buy = wadBuyVolume(c);
  const sell = wadSellVolume(c);
  const total = Math.max(0, c.volume || 0);
  return { buy, sell, total, bull: c.close >= c.open, bear: c.close < c.open };
}

function volumeForSide(ev: ReturnType<typeof eventVolumes>, side: WhaleVolumeSide): number {
  if (side === 'buy') return ev.buy;
  if (side === 'sell') return ev.sell;
  return ev.total;
}

function nearestTier(volBtc: number, tiers: number[]): number | null {
  if (volBtc < tiers[0]! * 0.85) return null;
  let best = tiers[0]!;
  for (const t of tiers) {
    if (volBtc >= t * 0.88) best = t;
  }
  return best;
}

function qualifiesSide(ev: ReturnType<typeof eventVolumes>, side: WhaleVolumeSide, tier: number): boolean {
  const v = volumeForSide(ev, side);
  if (v < tier * 0.88) return false;
  if (side === 'bull' && !ev.bull) return false;
  if (side === 'bear' && !ev.bear) return false;
  return true;
}

function classifyOutcome(pct: number): 'long' | 'short' | 'flat' {
  if (pct > FLAT_PCT) return 'long';
  if (pct < -FLAT_PCT) return 'short';
  return 'flat';
}

function fingerprintSimilarity(a: WhaleCandleFingerprint, b: WhaleCandleFingerprint): number {
  let score = 0;
  if (a.body === b.body) score += 40;
  else if (
    (a.body === 'small' && b.body === 'medium') ||
    (a.body === 'medium' && b.body === 'small') ||
    (a.body === 'medium' && b.body === 'large') ||
    (a.body === 'large' && b.body === 'medium')
  )
    score += 18;
  if (a.wick === b.wick) score += 30;
  else if (a.wick === 'balanced' || b.wick === 'balanced') score += 12;
  if (a.rvol === b.rvol) score += 30;
  else if (
    (a.rvol === 'high' && b.rvol === 'extreme') ||
    (a.rvol === 'extreme' && b.rvol === 'high') ||
    (a.rvol === 'normal' && b.rvol === 'high') ||
    (a.rvol === 'high' && b.rvol === 'normal')
  )
    score += 14;
  return Math.min(100, score);
}

function formatDateKo(tsSec: number): string {
  try {
    return new Date(tsSec * 1000).toLocaleString('ko-KR', {
      year: '2-digit',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch {
    return String(tsSec);
  }
}

function percentileSorted(sorted: number[], p: number): number {
  if (!sorted.length) return NaN;
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}

function buildTierBreakdown(
  candles: Candle[],
  timeframe: string,
  primaryH: number
): WhaleTierCompareRow[] {
  const sorted = [...candles].sort((a, b) => a.time - b.time);
  const tiers = whaleTiersForTf(timeframe);
  const n = sorted.length;
  const maxH = primaryH + 2;
  if (n < maxH + 20) return [];

  const sides: WhaleVolumeSide[] = ['buy', 'sell', 'bull', 'bear'];
  const rows: WhaleTierCompareRow[] = [];

  for (const tier of tiers) {
    for (const side of sides) {
      const usds: number[] = [];
      let longN = 0;
      let shortN = 0;
      for (let i = 20; i < n - maxH; i++) {
        const ev = eventVolumes(sorted[i]!);
        if (!qualifiesSide(ev, side, tier)) continue;
        const c0 = sorted[i]!;
        const c1 = sorted[i + primaryH];
        if (!c1 || c0.close <= 0) continue;
        const usd = c1.close - c0.close;
        const pct = ((c1.close / c0.close) - 1) * 100;
        usds.push(usd);
        const cls = classifyOutcome(pct);
        if (cls === 'long') longN++;
        else if (cls === 'short') shortN++;
      }
      const count = usds.length;
      if (count < 3) continue;
      const dirN = longN + shortN || 1;
      let longPct = Math.round((longN / dirN) * 100);
      let shortPct = 100 - longPct;
      longPct = Math.max(35, Math.min(65, longPct));
      shortPct = 100 - longPct;
      rows.push({
        tierBtc: tier,
        side,
        sideKo: sideKo(side),
        eventCount: count,
        longPct,
        shortPct,
        medianUsd: percentileSorted([...usds].sort((a, b) => a - b), 0.5),
      });
    }
  }
  return rows.sort((a, b) => b.eventCount - a.eventCount).slice(0, 24);
}

function findSimilarHistory(
  candles: Candle[],
  timeframe: string,
  current: WhaleVolumeLiveMatch,
  maxRows = 16
): WhaleHistoryCompareRow[] {
  const sorted = [...candles].sort((a, b) => a.time - b.time);
  const horizons = whaleHorizonsForTf(timeframe);
  const primaryH = current.primaryHorizon;
  const maxH = Math.max(...horizons, primaryH);
  const n = sorted.length;
  const lastIdx = n - 1;
  if (n < maxH + 25) return [];

  const candidates: WhaleHistoryCompareRow[] = [];

  for (let i = 20; i < n - maxH; i++) {
    if (i >= lastIdx - 1) continue;
    const c = sorted[i]!;
    const ev = eventVolumes(c);
    if (current.tierBtc !== nearestTier(volumeForSide(ev, current.side), whaleTiersForTf(timeframe))) continue;
    if (!qualifiesSide(ev, current.side, current.tierBtc)) continue;

    const fp = candleFingerprint(sorted, i);
    const sim = fingerprintSimilarity(current.fingerprint, fp);
    if (sim < 42) continue;

    const outcomes = horizons.map((h) => {
      const c1 = sorted[i + h];
      const usd = c1 ? c1.close - c.close : 0;
      const pct = c1 && c.close > 0 ? ((c1.close / c.close) - 1) * 100 : 0;
      return { bars: h, usd, pct, dir: classifyOutcome(pct) };
    });

    candidates.push({
      time: c.time,
      dateKo: formatDateKo(c.time),
      price: c.close,
      tierBtc: current.tierBtc,
      volBtc: Math.round(volumeForSide(ev, current.side)),
      side: current.side,
      sideKo: sideKo(current.side),
      fingerprintKo: fingerprintLabelKo(fp),
      similarityPct: sim,
      outcomes,
    });
  }

  candidates.sort((a, b) => b.similarityPct - a.similarityPct || b.time - a.time);
  const out: WhaleHistoryCompareRow[] = [];
  const seen = new Set<number>();
  for (const row of candidates) {
    if (seen.has(row.time)) continue;
    seen.add(row.time);
    out.push(row);
    if (out.length >= maxRows) break;
  }
  return out;
}

export function buildBitgetWhaleVolumeComparePack(params: {
  symbol: string;
  timeframe: string;
  candles: Candle[];
  catalog: BitgetWhaleVolumeCatalog;
}): BitgetWhaleVolumeComparePack | null {
  const { symbol, timeframe, candles, catalog } = params;
  const current = matchCurrentWhaleVolume(candles, catalog);
  if (!current) return null;

  const similarHistory = findSimilarHistory(candles, timeframe, current, 16);
  const tierBreakdown = buildTierBreakdown(candles, timeframe, current.primaryHorizon);

  let longN = 0;
  let shortN = 0;
  const primaryH = current.primaryHorizon;
  for (const row of similarHistory) {
    const o = row.outcomes.find((x) => x.bars === primaryH) ?? row.outcomes[0];
    if (!o) continue;
    if (o.dir === 'long') longN++;
    else if (o.dir === 'short') shortN++;
  }
  const histN = longN + shortN;
  let aggregateLongPct = current.longPct;
  let aggregateShortPct = current.shortPct;
  if (histN >= 5) {
    aggregateLongPct = Math.round((longN / histN) * 100);
    aggregateShortPct = 100 - aggregateLongPct;
    aggregateLongPct = Math.max(35, Math.min(65, aggregateLongPct));
    aggregateShortPct = 100 - aggregateLongPct;
  }

  const dirKo =
    aggregateLongPct >= 55 && aggregateLongPct - aggregateShortPct >= 6
      ? '롱'
      : aggregateShortPct >= 55 && aggregateShortPct - aggregateLongPct >= 6
        ? '숏'
        : '혼조';

  return {
    symbol,
    timeframe,
    listingFromKo: catalog.listingFromKo,
    totalBars: catalog.totalBars,
    catalogEvents: catalog.eventCount,
    current,
    bucket: current.bucket,
    tierBreakdown,
    similarHistory,
    aggregateLongPct,
    aggregateShortPct,
    headlineKo: `📊 ${current.tierBtc}BTC ${current.sideKo} · 유사 ${similarHistory.length}건 · ${dirKo} L${aggregateLongPct}%`,
    summaryKo: `${catalog.listingFromKo}~ ${catalog.totalBars.toLocaleString()}봉 · 카탈로그 ${catalog.buckets.length}버킷 · ${current.fingerprintKo}`,
  };
}

import { NextRequest, NextResponse } from 'next/server';
import { normalizeChartTimeframe } from '@/lib/constants';
import { readBitgetFuturesCsv } from '@/lib/bitgetFuturesCsv';
import { buildBitgetWhaleVolumeComparePack } from '@/lib/bitgetWhaleVolumeCompare';
import {
  BITGET_WHALE_CATALOG_TFS,
  buildBitgetWhaleVolumeCatalog,
  buildWhaleVolumeMtfPack,
  matchCurrentWhaleVolume,
} from '@/lib/bitgetWhaleVolumeCatalog';
import {
  readBitgetWhaleVolumeCatalog,
  writeBitgetWhaleVolumeCatalog,
} from '@/lib/bitgetWhaleVolumeCatalogStore';

export const dynamic = 'force-dynamic';
export const maxDuration = 120;

async function loadCatalog(symbol: string, tf: string, rebuild: boolean) {
  if (!rebuild) {
    const cached = await readBitgetWhaleVolumeCatalog(symbol, tf);
    if (cached && cached.totalBars >= 80) return cached;
  }
  const candles = await readBitgetFuturesCsv(symbol, tf);
  if (candles.length < 80) return null;
  const catalog = buildBitgetWhaleVolumeCatalog({ symbol, timeframe: tf, candles });
  if (catalog.buckets.length >= 5) {
    await writeBitgetWhaleVolumeCatalog(catalog).catch(() => undefined);
  }
  return catalog;
}

/** 현재 vs 과거 유사 거래량·캔들 비교 (Bitget CSV + 카탈로그) */
export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const symbol = (searchParams.get('symbol') || 'BTCUSDT').toUpperCase();
  const timeframe = normalizeChartTimeframe(searchParams.get('timeframe') || '15m');
  const mtf = searchParams.get('mtf') === '1';
  const rebuild = searchParams.get('rebuild') === '1';

  try {
    const catalog = await loadCatalog(symbol, timeframe, rebuild);
    if (!catalog) {
      return NextResponse.json({ ok: false, error: 'catalog/csv insufficient' }, { status: 400 });
    }
    const candles = await readBitgetFuturesCsv(symbol, timeframe);
    const compare = buildBitgetWhaleVolumeComparePack({
      symbol,
      timeframe,
      candles,
      catalog,
    });
    if (!compare) {
      return NextResponse.json({ ok: false, error: 'no current whale match' }, { status: 404 });
    }

    let mtfPack = null;
    if (mtf) {
      const rows = await Promise.all(
        BITGET_WHALE_CATALOG_TFS.map(async (tf) => {
          try {
            const cat = await loadCatalog(symbol, tf, false);
            if (!cat) return { tf, match: null, ok: false as const, error: 'no catalog' };
            const cs = await readBitgetFuturesCsv(symbol, tf);
            const match = cs.length >= 25 ? matchCurrentWhaleVolume(cs, cat) : null;
            return { tf, match, ok: true as const };
          } catch (e) {
            return {
              tf,
              match: null,
              ok: false as const,
              error: e instanceof Error ? e.message : 'failed',
            };
          }
        })
      );
      mtfPack = buildWhaleVolumeMtfPack({ symbol, rows });
    }

    return NextResponse.json({
      ok: true,
      symbol,
      timeframe,
      compare,
      mtfPack,
      dataSource: {
        csvBars: candles.length,
        catalogBuckets: catalog.buckets.length,
        listingFromKo: catalog.listingFromKo,
      },
    });
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : 'bitget-whale-volume-compare failed';
    return NextResponse.json({ ok: false, error: msg }, { status: 500 });
  }
}

'use client';

import type { BitgetWhaleVolumeComparePack } from '@/lib/bitgetWhaleVolumeCompare';
import type { WhaleVolumeMtfPack } from '@/lib/bitgetWhaleVolumeCatalog';

type Props = {
  compare: BitgetWhaleVolumeComparePack;
  mtfPack: WhaleVolumeMtfPack | null;
  onClose: () => void;
};

export function BitgetWhaleVolumeComparePanel({ compare, mtfPack, onClose }: Props) {
  const cur = compare.current;
  const primaryH = cur.primaryHorizon;

  return (
    <div
      className="bitget-whale-compare-panel"
      role="dialog"
      aria-label="고래 거래량 분석 비교"
      onClick={(e) => e.stopPropagation()}
    >
      <div className="bitget-whale-compare-panel__head">
        <span className="bitget-whale-compare-panel__title">📊 거래량 분석 · 과거 비교</span>
        <button type="button" className="bitget-whale-compare-panel__close" onClick={onClose}>
          ×
        </button>
      </div>

      <div className="bitget-whale-compare-panel__hero">
        <div className="bitget-whale-compare-panel__hero-line">
          <strong>현재</strong> · {cur.tierBtc} BTC · {cur.sideKo} · {cur.fingerprintKo}
        </div>
        <div className="bitget-whale-compare-panel__pct">
          <span className="bitget-whale-compare-panel__long">롱 {compare.aggregateLongPct}%</span>
          <span className="bitget-whale-compare-panel__short">숏 {compare.aggregateShortPct}%</span>
        </div>
        <div className="bitget-whale-compare-panel__meta">
          {compare.listingFromKo}~ · {compare.totalBars.toLocaleString()}봉 · 유사 {compare.similarHistory.length}건
          {cur.sampleLowTrust ? ' · 저표본' : ''}
        </div>
      </div>

      {mtfPack && (
        <>
          <div className="bitget-whale-compare-panel__section">MTF 비교 (15m · 1h · 4h · 1d)</div>
          <div className="bitget-whale-compare-panel__mtf">
            {mtfPack.rows.map((r) => (
              <div key={r.tf} className={`bitget-whale-compare-panel__mtf-row${r.ok ? ' is-ok' : ''}`}>
                <span>{r.tfKo}</span>
                {r.match ? (
                  <>
                    <span>{r.match.tierBtc}BTC</span>
                    <span>L{r.match.longPct}%</span>
                    <span>S{r.match.shortPct}%</span>
                    <span>{r.match.dominant === 'LONG' ? '▲' : r.match.dominant === 'SHORT' ? '▼' : '—'}</span>
                  </>
                ) : (
                  <span className="bitget-whale-compare-panel__muted">{r.error ?? '—'}</span>
                )}
              </div>
            ))}
          </div>
        </>
      )}

      <div className="bitget-whale-compare-panel__section">BTC 티어별 과거 통계 (+{primaryH}봉)</div>
      <div className="bitget-whale-compare-panel__tier-table">
        {compare.tierBreakdown.slice(0, 12).map((row) => (
          <div
            key={`${row.tierBtc}-${row.side}`}
            className={`bitget-whale-compare-panel__tier-row${
              row.tierBtc === cur.tierBtc && row.side === cur.side ? ' is-current' : ''
            }`}
          >
            <span>{row.tierBtc} BTC</span>
            <span>{row.sideKo}</span>
            <span>n{row.eventCount}</span>
            <span>L{row.longPct}%</span>
            <span>S{row.shortPct}%</span>
            <span>
              {row.medianUsd != null
                ? row.medianUsd >= 0
                  ? `+$${Math.round(row.medianUsd)}`
                  : `−$${Math.round(Math.abs(row.medianUsd))}`
                : '—'}
            </span>
          </div>
        ))}
      </div>

      <div className="bitget-whale-compare-panel__section">유사 과거 이벤트 (캔들·거래량 일치)</div>
      <div className="bitget-whale-compare-panel__hist">
        {compare.similarHistory.length === 0 && (
          <div className="bitget-whale-compare-panel__muted">동일 티어·유사 지문 과거 사례 없음</div>
        )}
        {compare.similarHistory.map((row) => {
          const o = row.outcomes.find((x) => x.bars === primaryH) ?? row.outcomes[0];
          return (
            <div key={row.time} className="bitget-whale-compare-panel__hist-row">
              <span className="bitget-whale-compare-panel__hist-date">{row.dateKo}</span>
              <span>{row.volBtc} BTC</span>
              <span title={row.fingerprintKo}>일치{row.similarityPct}%</span>
              <span className={o?.dir === 'long' ? 'bitget-whale-compare-panel__long' : o?.dir === 'short' ? 'bitget-whale-compare-panel__short' : ''}>
                {o
                  ? `${o.pct >= 0 ? '+' : ''}${o.pct.toFixed(1)}% ${o.usd >= 0 ? '+' : ''}$${Math.round(o.usd)}`
                  : '—'}
              </span>
            </div>
          );
        })}
      </div>

      <div className="bitget-whale-compare-panel__foot">
        Bitget BTCUSDT.P CSV + 카탈로그 — 조건부 참고 · 확정 수익 아님
      </div>
    </div>
  );
}

