/**
 * 캔들 구간 + 거래량 스파이크 → 차트·볼륨 지표식 신호
 */
import type { UTCTimestamp } from 'lightweight-charts';
import type { Candle } from '@/types';
import { normalizeChartTimeframe } from '@/lib/constants';
import type { WhaleVolumeLiveMatch, WhaleVolumeMtfPack } from '@/lib/bitgetWhaleVolumeCatalog';
import type { SingleCandleCompare, RangeSegmentCompare } from '@/lib/bitgetWhaleVolumeCompare';
import {
  buildWhaleVolumeSignal,
  type WhaleSignalDir,
  type WhaleSignalTag,
} from '@/lib/whaleVolumeSignalIndicator';
import { detectVolumeRangePhases, type VolumeRangePhase } from '@/lib/volumeRangeAccumDist';
import { analyzeCandleVolumeJoint, scoreGreenTrapSegment } from '@/lib/volumeCandleJoint';
import { evalBarVolumeShock, RVOL_SHOCK_MIN, type BarVolumeShock } from '@/lib/volumeShockMetrics';
import type { VolumeShockForecastResult } from '@/lib/volumeShockForecast';
import { sanitizeChartCandlesForSeries, type VolumePanelMarker } from '@/lib/volumeHistogramIntelligence';

export type WhaleSegmentVolumeSignal = {
  id: string;
  fromIdx: number;
  toIdx: number;
  volIdx: number;
  timeFrom: number;
  timeTo: number;
  timeVol: number;
  priceHigh: number;
  priceLow: number;
  tag: WhaleSignalTag;
  dir: WhaleSignalDir;
  /** 캔들 위 초단문 */
  chartTag: string;
  /** 거래량 막대 위 초단문 */
  volTag: string;
  forecastPct: number | null;
  forecastBars: number;
  color: string;
  strength: number;
  kind: 'range_vol' | 'vol_burst' | 'live';
  phase?: 'accumulation' | 'distribution';
  isLive: boolean;
};

const LONG_C = '#34d399';
const SHORT_C = '#fb7185';
const NEUT_C = '#fbbf24';
const BEAM_L = '#22d3ee';
const BEAM_S = '#f97316';
const TRAP_C = '#f472b6';

function tagColor(tag: WhaleSignalTag, dir: WhaleSignalDir): string {
  if (tag.startsWith('TRAP')) return TRAP_C;
  if (tag.includes('BEAM')) return dir === 'long' ? BEAM_L : BEAM_S;
  if (dir === 'long') return LONG_C;
  if (dir === 'short') return SHORT_C;
  return NEUT_C;
}

function chartTagFrom(tag: WhaleSignalTag): string {
  switch (tag) {
    case 'LONG BEAM':
      return '▲BEAM';
    case 'SHORT BEAM':
      return '▼BEAM';
    case 'BIG LONG':
      return '▲BIG';
    case 'BIG SHORT':
      return '▼BIG';
    case 'TRAP↓':
      return '⚠TRAP↓';
    case 'TRAP↑':
      return '⚠TRAP↑';
    case 'LONG':
      return '▲L';
    case 'SHORT':
      return '▼S';
    default:
      return '◆W';
  }
}

function volTagFrom(tag: WhaleSignalTag, pct: number | null, rvol?: number): string {
  const p = pct != null && Number.isFinite(pct) ? `${pct >= 0 ? '+' : ''}${pct.toFixed(1)}%` : '';
  const rv = rvol != null && rvol >= 1.5 ? `${rvol.toFixed(1)}×` : '';
  const core = chartTagFrom(tag);
  return [core, rv, p].filter(Boolean).join(' ');
}

function forwardPct(rows: Candle[], idx: number, bars: number): number | null {
  const c0 = rows[idx];
  const c1 = rows[idx + bars];
  if (!c0 || !c1 || c0.close <= 0) return null;
  return ((c1.close / c0.close) - 1) * 100;
}

function phaseToTag(
  phase: VolumeRangePhase,
  trap: boolean,
  volBtc: number
): { tag: WhaleSignalTag; dir: WhaleSignalDir } {
  if (trap) return { tag: 'TRAP↓', dir: 'short' };
  if (phase.phase === 'accumulation') {
    return volBtc >= 5000 ? { tag: 'BIG LONG', dir: 'long' } : { tag: 'LONG', dir: 'long' };
  }
  if (phase.phase === 'distribution') {
    return volBtc >= 5000 ? { tag: 'BIG SHORT', dir: 'short' } : { tag: 'SHORT', dir: 'short' };
  }
  return { tag: 'WAIT', dir: 'neutral' };
}

function shockToTag(shock: BarVolumeShock, rvol: number): { tag: WhaleSignalTag; dir: WhaleSignalDir } {
  if (rvol >= 2.8) {
    return shock.side === 'long'
      ? { tag: 'LONG BEAM', dir: 'long' }
      : { tag: 'SHORT BEAM', dir: 'short' };
  }
  return shock.side === 'long' ? { tag: 'LONG', dir: 'long' } : { tag: 'SHORT', dir: 'short' };
}

function signalFromPhase(
  rows: Candle[],
  phase: VolumeRangePhase,
  focusH: number,
  lastIdx: number
): WhaleSegmentVolumeSignal | null {
  const seg = rows.slice(phase.fromIdx, phase.toIdx + 1);
  if (seg.length < 4) return null;

  let volIdx = phase.toIdx;
  let maxVol = 0;
  for (let i = phase.fromIdx; i <= phase.toIdx; i++) {
    const v = rows[i]!.volume || 0;
    if (v >= maxVol) {
      maxVol = v;
      volIdx = i;
    }
  }

  const trap = scoreGreenTrapSegment(seg);
  const volBtc = Math.round(maxVol);
  const { tag, dir } = phaseToTag(phase, trap.isTrap, volBtc);
  if (dir === 'neutral') return null;

  const hi = Math.max(...seg.map((c) => c.high));
  const lo = Math.min(...seg.map((c) => c.low));
  const fwd =
    phase.breakPct ??
    forwardPct(rows, phase.toIdx, focusH) ??
    forwardPct(rows, volIdx, focusH);

  const strength = Math.round(phase.score * 12 + (phase.toIdx === lastIdx ? 4 : 0) + (trap.isTrap ? 2 : 0));

  return {
    id: `range-${phase.fromIdx}-${phase.toIdx}`,
    fromIdx: phase.fromIdx,
    toIdx: phase.toIdx,
    volIdx,
    timeFrom: rows[phase.fromIdx]!.time as number,
    timeTo: rows[phase.toIdx]!.time as number,
    timeVol: rows[volIdx]!.time as number,
    priceHigh: hi,
    priceLow: lo,
    tag,
    dir,
    chartTag: chartTagFrom(tag),
    volTag: volTagFrom(tag, fwd),
    forecastPct: fwd,
    forecastBars: focusH,
    color: tagColor(tag, dir),
    strength,
    kind: 'range_vol',
    phase: phase.phase === 'neutral' ? undefined : phase.phase,
    isLive: phase.toIdx >= lastIdx - 1,
  };
}

function signalFromShock(
  rows: Candle[],
  idx: number,
  shock: BarVolumeShock,
  focusH: number,
  lastIdx: number
): WhaleSegmentVolumeSignal | null {
  const win = Math.min(8, idx);
  const fromIdx = Math.max(0, idx - win);
  const seg = rows.slice(fromIdx, idx + 1);
  const hi = Math.max(...seg.map((c) => c.high));
  const lo = Math.min(...seg.map((c) => c.low));
  const { tag, dir } = shockToTag(shock, shock.rvol);
  const fwd = forwardPct(rows, idx, focusH);

  return {
    id: `burst-${idx}`,
    fromIdx,
    toIdx: idx,
    volIdx: idx,
    timeFrom: rows[fromIdx]!.time as number,
    timeTo: rows[idx]!.time as number,
    timeVol: rows[idx]!.time as number,
    priceHigh: hi,
    priceLow: lo,
    tag,
    dir,
    chartTag: chartTagFrom(tag),
    volTag: volTagFrom(tag, fwd, shock.rvol),
    forecastPct: fwd,
    forecastBars: focusH,
    color: tagColor(tag, dir),
    strength: Math.round(shock.rvol * 8 + (idx === lastIdx ? 6 : 0)),
    kind: 'vol_burst',
    isLive: idx === lastIdx,
  };
}

function dedupeSignals(list: WhaleSegmentVolumeSignal[]): WhaleSegmentVolumeSignal[] {
  const sorted = [...list].sort((a, b) => b.strength - a.strength || b.toIdx - a.toIdx);
  const out: WhaleSegmentVolumeSignal[] = [];
  for (const s of sorted) {
    const overlap = out.some(
      (o) =>
        !(s.toIdx < o.fromIdx - 2 || s.fromIdx > o.toIdx + 2) ||
        (Math.abs(s.volIdx - o.volIdx) <= 2 && s.tag === o.tag)
    );
    if (!overlap) out.push(s);
    if (out.length >= 10) break;
  }
  return out.sort((a, b) => a.toIdx - b.toIdx);
}

/** 구간·거래량·고래 매칭 → 차트/볼륨 신호 */
export function detectWhaleSegmentVolumeSignals(params: {
  candles: Candle[];
  timeframe: string;
  volumeShock?: VolumeShockForecastResult | null;
  whaleMatch?: WhaleVolumeLiveMatch | null;
  singleCandle?: SingleCandleCompare | null;
  rangeSegment?: RangeSegmentCompare | null;
  mtfPack?: WhaleVolumeMtfPack | null;
  maxSignals?: number;
}): WhaleSegmentVolumeSignal[] {
  const {
    candles,
    timeframe,
    volumeShock,
    whaleMatch,
    singleCandle,
    rangeSegment,
    mtfPack,
    maxSignals = 10,
  } = params;

  const rows = sanitizeChartCandlesForSeries(candles);
  const n = rows.length;
  if (n < 12) return [];

  const tf = normalizeChartTimeframe(timeframe);
  const focusH = whaleMatch?.primaryHorizon ?? 4;
  const lastIdx = n - 1;
  const hits: WhaleSegmentVolumeSignal[] = [];

  const phases = detectVolumeRangePhases(rows, tf, 120, focusH);
  for (const phase of phases) {
    const sig = signalFromPhase(rows, phase, focusH, lastIdx);
    if (sig) hits.push(sig);
  }

  if (volumeShock) {
    const lookback = 48;
    for (let i = n - 1; i >= Math.max(0, n - lookback); i--) {
      const shock = evalBarVolumeShock(rows, i, volumeShock);
      if (!shock) continue;
      if (i !== lastIdx && !(shock.tags.includes('P99') || shock.rvol >= RVOL_SHOCK_MIN * 1.2)) continue;
      const sig = signalFromShock(rows, i, shock, focusH, lastIdx);
      if (sig) hits.push(sig);
    }
  }

  const live = buildWhaleVolumeSignal({
    match: whaleMatch ?? null,
    singleCandle,
    rangeSegment,
    mtfPack,
  });

  if (live && whaleMatch && whaleMatch.sampleCount >= 2) {
    const win = rangeSegment?.bars ?? 8;
    const fromIdx = Math.max(0, lastIdx - win + 1);
    const seg = rows.slice(fromIdx, lastIdx + 1);
    hits.push({
      id: `live-${lastIdx}`,
      fromIdx,
      toIdx: lastIdx,
      volIdx: lastIdx,
      timeFrom: rows[fromIdx]!.time as number,
      timeTo: rows[lastIdx]!.time as number,
      timeVol: rows[lastIdx]!.time as number,
      priceHigh: Math.max(...seg.map((c) => c.high)),
      priceLow: Math.min(...seg.map((c) => c.low)),
      tag: live.tag,
      dir: live.dir,
