      volTag: live.volLabel,
      forecastPct: live.forecastPct,
      forecastBars: live.forecastBars,
      color: live.color,
      strength: 100 + live.strength * 5,
      kind: 'live',
      isLive: true,
    });
  }

  return dedupeSignals(hits).slice(-maxSignals);
}

