}): WhaleSegmentDrawGeom[] {
  const { signals, resolveTimeX, priceToY, chartHeight, volPanelTopRatio = 0.82 } = params;
  const yVolBase = chartHeight * volPanelTopRatio + 6;

  const out: WhaleSegmentDrawGeom[] = [];
  for (const s of signals) {
    const x1 = resolveTimeX(s.timeFrom);
    const x2 = resolveTimeX(s.timeTo);
    const xVol = resolveTimeX(s.timeVol);
    if (!Number.isFinite(x1) || !Number.isFinite(x2) || !Number.isFinite(xVol)) continue;

    const yTop = priceToY(s.priceHigh);
    const yBot = priceToY(s.priceLow);
    if (yTop == null || yBot == null) continue;

    const xMid = (x1 + x2) / 2;
    const pad = 6;
    const boxTop = Math.min(yTop, yBot) - pad;
    const boxBot = Math.max(yTop, yBot) + pad;
    const arrowTipY =
      s.dir === 'long' ? boxTop - 14 : s.dir === 'short' ? boxBot + 14 : (boxTop + boxBot) / 2;

    out.push({
      id: s.id,
      x1: Math.min(x1, x2) - 4,
      x2: Math.max(x1, x2) + 4,
      yTop: boxTop,
      yBot: boxBot,
      xVol,
      yVol: yVolBase,
      xMid,
      arrowTipY,
      chartTag: s.chartTag,
      volTag: s.volTag,
      color: s.color,
      dir: s.dir,
      isLive: s.isLive,
    });
  }
  return out;
}

export function buildWhaleSegmentVolumeMarkers(signals: WhaleSegmentVolumeSignal[]): VolumePanelMarker[] {
  return signals.map((s) => ({
    time: s.timeVol as UTCTimestamp,
    position: 'aboveBar' as const,
    shape: 'square' as const,
    color: s.color,
    text: s.volTag,
    size: s.isLive ? 2 : 1,
  }));
}

