/** 차트에 그릴 신호 — live 1개 + 과거(마지막 봉과 분리) */
export function thinWhaleSegmentSignalsForDraw(
  signals: WhaleSegmentVolumeSignal[],
  lastIdx: number,
  opts?: { maxPast?: number; minBarGap?: number; liveClearance?: number }
): WhaleSegmentVolumeSignal[] {
  const maxPast = opts?.maxPast ?? 2;
  const minBarGap = opts?.minBarGap ?? 8;
  const liveClearance = opts?.liveClearance ?? 6;
  const live = signals.filter((s) => s.isLive).sort((a, b) => b.strength - a.strength);
  const past = signals
    .filter((s) => !s.isLive && s.toIdx < lastIdx - liveClearance)
    .sort((a, b) => b.strength - a.strength || b.toIdx - a.toIdx);
  const bestLive = live[0] ?? null;
  const pickedPast: WhaleSegmentVolumeSignal[] = [];
  for (const s of past) {
    if (pickedPast.length >= maxPast) break;
    const tooClose = pickedPast.some((p) => Math.abs(p.volIdx - s.volIdx) < minBarGap);
    if (tooClose) continue;
    pickedPast.push(s);
  }
  const out = bestLive ? [bestLive, ...pickedPast] : pickedPast;
  return out.sort((a, b) => a.toIdx - b.toIdx);
}

function pctLabel(pct: number | null): string {
  if (pct == null || !Number.isFinite(pct)) return '';
  return `${pct >= 0 ? '+' : ''}${pct.toFixed(1)}%`;
}

export function buildWhaleSegmentDrawGeom(params: {
  signals: WhaleSegmentVolumeSignal[];
  resolveTimeX: (t: number) => number;
  priceToY: (p: number) => number | null;
  chartHeight: number;
  volPanelTopRatio?: number;
}): WhaleSegmentDrawGeom[] {
  const { signals, resolveTimeX, priceToY, chartHeight, volPanelTopRatio = 0.82 } = params;
  const yVolBase = chartHeight * volPanelTopRatio + 8;
  const live = signals.find((s) => s.isLive);
  const past = signals.filter((s) => !s.isLive);

  const out: WhaleSegmentDrawGeom[] = [];

  if (live) {
    const x1 = resolveTimeX(live.timeFrom);
    const x2 = resolveTimeX(live.timeTo);
    const xVol = resolveTimeX(live.timeVol);
    const yTop = priceToY(live.priceHigh);
    const yBot = priceToY(live.priceLow);
    if (Number.isFinite(x1) && Number.isFinite(x2) && Number.isFinite(xVol) && yTop != null && yBot != null) {
      const pad = 4;
      const boxTop = Math.min(yTop, yBot) - pad;
      const boxBot = Math.max(yTop, yBot) + pad;
      const xMid = (x1 + x2) / 2;
      const lanceX = Math.max(x1, x2) + 18;
      const bodyH = Math.max(28, Math.min(56, boxBot - boxTop + 16));
      const lanceTop = live.dir === 'long' ? boxTop - 6 : (boxTop + boxBot) / 2 - bodyH / 2;
      const lanceBot = lanceTop + bodyH;

      out.push({
        id: live.id,
        mode: 'live_lance',
        x1: Math.min(x1, x2),
        x2: Math.max(x1, x2),
        yTop: boxTop,
        yBot: boxBot,
        xVol,
        yVol: yVolBase,
        xMid,
        lanceX,
        lanceTop,
        lanceBot,
        chartTag: live.chartTag,
        volTag: live.volTag,
        pctLabel: pctLabel(live.forecastPct),
        color: live.color,
        dir: live.dir,
        isLive: true,
        laneOffset: 0,
        yBracket: boxBot + 3,
      });
    }
  }

  past.forEach((s, laneIdx) => {
    const x1 = resolveTimeX(s.timeFrom);
    const x2 = resolveTimeX(s.timeTo);
    const xVol = resolveTimeX(s.timeVol);
    const yTop = priceToY(s.priceHigh);
    const yBot = priceToY(s.priceLow);
    if (!Number.isFinite(x1) || !Number.isFinite(x2) || !Number.isFinite(xVol) || yTop == null || yBot == null) {
      return;
    }
    const boxTop = Math.min(yTop, yBot) - 3;
    const boxBot = Math.max(yTop, yBot) + 3;
    const xMid = (x1 + x2) / 2;
    const laneOffset = laneIdx % 2 === 0 ? -16 : 16;
    const lanceX = xMid + laneOffset;
    const lanceTop = s.dir === 'long' ? boxTop - 4 : boxBot - 20;
    const lanceBot = lanceTop + 20;

    out.push({
      id: s.id,
      mode: 'past_lane',
      x1: Math.min(x1, x2),
      x2: Math.max(x1, x2),
      yTop: boxTop,
      yBot: boxBot,
      xVol,
      yVol: yVolBase + laneIdx * 4,
      xMid,
      lanceX,
      lanceTop,
      lanceBot,
      chartTag: s.chartTag,
      volTag: s.volTag,
      pctLabel: pctLabel(s.forecastPct),
      color: s.color,
      dir: s.dir,
      isLive: false,
      laneOffset,
      yBracket: boxBot + 5 + laneIdx * 3,
    });
  });

  return out;
}

