'use client';

import type { WhaleSegmentDrawGeom } from '@/lib/whaleVolumeSegmentSignals';

type Props = {
  geoms: WhaleSegmentDrawGeom[];
};

function LiveLance({ g }: { g: WhaleSegmentDrawGeom }) {
  const isLong = g.dir === 'long';
  const isShort = g.dir === 'short';
  const lanceW = 7;
  const lanceH = g.lanceBot - g.lanceTop;
  const connY = g.yVol - 2;
  const connPath = `M ${g.xVol} ${connY} L ${g.lanceX} ${connY} L ${g.lanceX} ${g.lanceBot}`;

  return (
    <g className="whale-seg-lance whale-seg-lance--live" style={{ ['--seg-color' as string]: g.color }}>
      {/* 구간 — 캔들 아래 얇은 브래킷만 (박스 없음) */}
      <path
        d={`M ${g.x1} ${g.yBracket} H ${g.x2}`}
        className="whale-seg-lance__bracket"
      />
      <path
        d={`M ${g.x1} ${g.yBracket} V ${g.yBracket + 4} M ${g.x2} ${g.yBracket} V ${g.yBracket + 4}`}
        className="whale-seg-lance__bracket-cap"
      />

      {/* 거래량 → 랜스 L자 연결 (캔들 관통 X) */}
      <path d={connPath} className="whale-seg-lance__conn" />
      <circle cx={g.xVol} cy={g.yVol} r={5} className="whale-seg-lance__vol-dot" />

      {/* 오른쪽 랜스 — 캔들 밖 */}
      <rect
        x={g.lanceX - lanceW / 2}
        y={g.lanceTop}
        width={lanceW}
        height={lanceH}
        rx={3}
        className="whale-seg-lance__bar"
      />
      {isLong && (
        <path
          d={`M ${g.lanceX - 6} ${g.lanceTop - 2} L ${g.lanceX} ${g.lanceTop - 10} L ${g.lanceX + 6} ${g.lanceTop - 2}`}
          className="whale-seg-lance__head"
        />
      )}
      {isShort && (
        <path
          d={`M ${g.lanceX - 6} ${g.lanceBot + 2} L ${g.lanceX} ${g.lanceBot + 10} L ${g.lanceX + 6} ${g.lanceBot + 2}`}
          className="whale-seg-lance__head"
        />
      )}

      <text x={g.lanceX + 10} y={(g.lanceTop + g.lanceBot) / 2 + 4} className="whale-seg-lance__tag">
        {g.chartTag}
      </text>
      {g.pctLabel && (
        <text x={g.lanceX + 10} y={(g.lanceTop + g.lanceBot) / 2 + 16} className="whale-seg-lance__pct">
          {g.pctLabel}
        </text>
      )}
    </g>
  );
}

function PastLane({ g }: { g: WhaleSegmentDrawGeom }) {
  const tagX = g.xMid + g.laneOffset;
  const tagY = g.dir === 'long' ? g.yTop - 8 : g.yBot + 16;

  return (
    <g className="whale-seg-lane whale-seg-lane--past" style={{ ['--seg-color' as string]: g.color }}>
      <path d={`M ${g.x1} ${g.yBracket} H ${g.x2}`} className="whale-seg-lane__bracket" />
      <circle cx={g.xVol} cy={g.yVol} r={3.5} className="whale-seg-lane__vol-dot" />
      <line x1={g.xVol} y1={g.yVol} x2={tagX} y2={tagY - 4} className="whale-seg-lane__hair" />
      <text x={tagX} y={tagY} className="whale-seg-lane__tag" textAnchor="middle">
        {g.chartTag}
      </text>
    </g>
  );
}

/** live=오른쪽 랜스 1개 · past=아래 브래킷+레인 (마지막 캔들 겹침 없음) */
export function WhaleVolumeSegmentDrawLayer({ geoms }: Props) {
  if (!geoms.length) return null;

  const live = geoms.find((g) => g.mode === 'live_lance');
  const past = geoms.filter((g) => g.mode === 'past_lane');

  return (
    <svg className="whale-segment-draw-layer" aria-hidden>
      {past.map((g) => (
        <PastLane key={g.id} g={g} />
      ))}
      {live && <LiveLance g={live} />}
    </svg>
  );
}

