  | '강반등'
  | '약하락'
  | '중하락'
  | '강하락'
  | '횡보';

export type MoveDir = 'long' | 'short' | 'neutral';

export type WhaleMoveTierPack = {
  tier: MoveTierKo;
  dir: MoveDir;
  tierLabel: string;
  pctLabel: string;
  rangeLabel: string;
  entryKo: string;
