      <path
        d={`M ${g.x1} ${g.yBracket} V ${g.yBracket + 4} M ${g.x2} ${g.yBracket} V ${g.yBracket + 4}`}
        className="whale-seg-lance__bracket-cap"
      />

      {/* 진입선 · 목표선 */}
      <line x1={g.x1} y1={g.entryY} x2={g.lanceX - 6} y2={g.entryY} className="whale-seg-lance__entry-line" />
      <line x1={g.x1} y1={g.targetY} x2={g.lanceX - 6} y2={g.targetY} className="whale-seg-lance__target-line" />
      <text x={g.x1 - 4} y={g.entryY - 3} className="whale-seg-lance__entry-label" textAnchor="end">
        진입
      </text>
      <text x={g.x1 - 4} y={g.targetY - 3} className="whale-seg-lance__target-label" textAnchor="end">
        목표
      </text>

      <path d={connPath} className="whale-seg-lance__conn" />
      <circle cx={g.xVol} cy={g.yVol} r={5} className="whale-seg-lance__vol-dot" />

      <rect
        x={g.lanceX - lanceW / 2}
        y={g.lanceTop}
        width={lanceW}
        height={g.lanceBot - g.lanceTop}
        rx={3}
        className="whale-seg-lance__bar"
      />
      {isLong && (
        <path
          d={`M ${g.lanceX - 6} ${g.lanceTop - 2} L ${g.lanceX} ${g.lanceTop - 10} L ${g.lanceX + 6} ${g.lanceTop - 2}`}
          className="whale-seg-lance__head"
        />
      )}
      {isShort && (
        <path
          d={`M ${g.lanceX - 6} ${g.lanceBot + 2} L ${g.lanceX} ${g.lanceBot + 10} L ${g.lanceX + 6} ${g.lanceBot + 2}`}
          className="whale-seg-lance__head"
        />
