      <text x={g.lanceX + 10} y={g.lanceTop + 12} className="whale-seg-lance__tag">
        {g.chartLine1}
      </text>
      <text x={g.lanceX + 10} y={g.lanceTop + 26} className="whale-seg-lance__tag-sub">
        {g.chartLine2}
      </text>
