export function buildWhaleSegmentDrawGeom(params: {
  signals: WhaleSegmentVolumeSignal[];
  resolveTimeX: (t: number) => number;
  priceToY: (p: number) => number | null;
  chartHeight: number;
  volPanelTopRatio?: number;
}): WhaleSegmentDrawGeom[] {
  const { signals, resolveTimeX, priceToY, chartHeight, volPanelTopRatio = 0.82 } = params;
  const yVolBase = chartHeight * volPanelTopRatio + 10;
  const live = signals.find((s) => s.isLive);
  const past = signals.filter((s) => !s.isLive);
  const out: WhaleSegmentDrawGeom[] = [];

  const pushGeom = (
    s: WhaleSegmentVolumeSignal,
    mode: 'range_box_live' | 'range_box_past',
    yVolOffset: number,
    arrowScale: number
  ) => {
    const x1 = resolveTimeX(s.timeFrom);
    const x2 = resolveTimeX(s.timeTo);
    const volFrom = s.volClusterFromIdx != null ? resolveTimeX(s.timeFrom) : resolveTimeX(s.timeVol);
    const volTo = s.volClusterToIdx != null ? resolveTimeX(s.timeTo) : resolveTimeX(s.timeVol);
    const volX1 = s.volClusterFromIdx != null ? resolveTimeX(s.timeFrom) : resolveTimeX(s.timeVol);
    const volX2 = s.volClusterToIdx != null ? resolveTimeX(s.timeTo) : resolveTimeX(s.timeVol);
    // vol cluster times from indices — use timeFrom/timeTo of cluster bars if we had times; fallback vol bar
    const vx1 = resolveTimeX(s.timeFrom);
    const vx2 = resolveTimeX(s.timeTo);
    const yTop = priceToY(s.priceHigh);
    const yBot = priceToY(s.priceLow);
    if (!Number.isFinite(x1) || !Number.isFinite(x2) || yTop == null || yBot == null) return;

    const boxTop = Math.min(yTop, yBot) - 5;
    const boxBot = Math.max(yTop, yBot) + 5;
    const med = Math.abs(s.forecastPct ?? 0);
    const arrowLen = Math.min(120, Math.max(48, 40 + med * 14)) * arrowScale;
    const { entryY, targetY } = geomFieldsFromSignal(s, priceToY);

    out.push({
      id: s.id,
      mode,
      x1: Math.min(x1, x2),
      x2: Math.max(x1, x2),
      yTop: boxTop,
      yBot: boxBot,
      volX1: Math.min(volX1, volX2, vx1, vx2),
      volX2: Math.max(volX1, volX2, vx1, vx2),
      yVol: yVolBase + yVolOffset,
      arrowLen,
      chartLine1: s.move.chartLine1,
      chartLine2: s.move.chartLine2,
      volLine: s.move.volLine,
      entryY,
      targetY,
      color: s.move.color,
      dir: s.move.dir,
      isLive: s.isLive,
      verdictKo: s.verdictKo ?? '횡보',
      segKind: s.segKind ?? '횡보박스',
      beamKo: s.beamKo ?? '관망',
    });
  };

  if (live) pushGeom(live, 'range_box_live', 0, 1);
  past.forEach((s, i) => pushGeom(s, 'range_box_past', i * 6, 0.72));

  return out;
}

