'use client';

import type { WhaleSegmentDrawGeom } from '@/lib/whaleVolumeSegmentSignals';

type Props = {
  geoms: WhaleSegmentDrawGeom[];
};

function ArrowHead({ x, y, up }: { x: number; y: number; up: boolean }) {
  const s = up ? -1 : 1;
  return (
    <path
      d={`M ${x} ${y} L ${x - 7} ${y + s * 10} L ${x + 7} ${y + s * 10} Z`}
      className="whale-seg-box__arrow-head"
    />
  );
}

/** 사용자 표시: 횡보박스 + 방향화살 + 거래량 원 */
function RangeBoxSignal({ g, dim }: { g: WhaleSegmentDrawGeom; dim?: boolean }) {
  const boxW = Math.max(8, g.x2 - g.x1);
  const boxH = Math.max(8, g.yBot - g.yTop);
  const cx = g.x2 + 6;
  const cy = (g.yTop + g.yBot) / 2;
  const isLong = g.dir === 'long' || g.verdictKo === '상승';
  const isShort = g.dir === 'short' || g.verdictKo === '하락';
  const arrowLen = g.arrowLen;
  const ax = cx + arrowLen;
  const ay = isLong ? cy - arrowLen * 0.85 : isShort ? cy + arrowLen * 0.85 : cy;
  const volCx = (g.volX1 + g.volX2) / 2;
  const volRx = Math.max(12, (g.volX2 - g.volX1) / 2 + 8);
  const labelX = ax + 8;
  const labelY = isLong ? ay - 6 : isShort ? ay + 14 : cy - 8;

  return (
    <g
      className={`whale-seg-box ${dim ? 'whale-seg-box--past' : 'whale-seg-box--live'}`}
      style={{ ['--seg-color' as string]: g.color }}
    >
      {/* 구간 박스 — 횡보·매집·분산 */}
      <rect
        x={g.x1}
        y={g.yTop}
        width={boxW}
        height={boxH}
        rx={3}
        className="whale-seg-box__rect"
      />
      <text x={g.x1 + 4} y={g.yTop - 4} className="whale-seg-box__seg-label">
        {g.segKind}
      </text>

      {/* 진입 · 목표 (박스 내부 점선) */}
      <line x1={g.x1} y1={g.entryY} x2={g.x2} y2={g.entryY} className="whale-seg-box__entry" />
      <line x1={g.x1} y1={g.targetY} x2={g.x2 + arrowLen * 0.35} y2={g.targetY} className="whale-seg-box__target" />

      {/* 방향 화살 — 구간 이탈 후 상승/하락 */}
      <line x1={cx} y1={cy} x2={ax} y2={ay} className="whale-seg-box__arrow" />
      <ArrowHead x={ax} y={ay} up={isLong} />

      {/* 거래량 원 — 구간 내 거래량 클러스터 */}
      <ellipse cx={volCx} cy={g.yVol} rx={volRx} ry={16} className="whale-seg-box__vol-ring" />
      <line x1={volCx} y1={g.yVol - 16} x2={cx} y2={cy} className="whale-seg-box__vol-link" />
      <text x={volCx} y={g.yVol + 22} textAnchor="middle" className="whale-seg-box__vol-tag">
        {g.volLine}
      </text>

      {/* 판정 라벨 */}
      <text x={labelX} y={labelY} className="whale-seg-box__verdict">
        {g.verdictKo === '상승' ? '▲' : g.verdictKo === '하락' ? '▼' : '—'} {g.verdictKo}
        {g.beamKo !== '관망' ? ` · ${g.beamKo}` : ''}
      </text>
      <text x={labelX} y={labelY + 13} className="whale-seg-box__tag">
        {g.chartLine1}
      </text>
      <text x={labelX} y={labelY + 26} className="whale-seg-box__tag-sub">
        {g.chartLine2}
      </text>
    </g>
  );
}

/** 구간분석 → 상승/하락 · 롱빔/숏빔 — 카드 없음, 캔들·거래량 직접 표시 */
export function WhaleVolumeSegmentDrawLayer({ geoms }: Props) {
  if (!geoms.length) return null;

  const live = geoms.find((g) => g.mode === 'range_box_live');
  const past = geoms.filter((g) => g.mode === 'range_box_past');

  return (
    <svg className="whale-segment-draw-layer" aria-hidden>
      <defs>
        <filter id="whale-seg-glow" x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="1.2" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
      {past.map((g) => (
        <RangeBoxSignal key={g.id} g={g} dim />
      ))}
      {live && <RangeBoxSignal g={live} />}
    </svg>
  );
}

