'use client';

import type { WhaleSegmentDrawGeom } from '@/lib/whaleVolumeSegmentSignals';

type Props = {
  geoms: WhaleSegmentDrawGeom[];
};

function ArrowHead({ x, y, up }: { x: number; y: number; up: boolean }) {
  const s = up ? -1 : 1;
  return (
    <path
      d={`M ${x} ${y} L ${x - 6} ${y + s * 9} L ${x + 6} ${y + s * 9} Z`}
      className="whale-seg-box__arrow-head"
    />
  );
}

function PastRangeBox({ g }: { g: WhaleSegmentDrawGeom }) {
  const boxW = Math.max(8, g.x2 - g.x1);
  const boxH = Math.max(8, g.yBot - g.yTop);
  const volCx = (g.volX1 + g.volX2) / 2;
  const volRx = Math.max(10, (g.volX2 - g.volX1) / 2 + 6);

  return (
    <g className="whale-seg-box whale-seg-box--past" style={{ ['--seg-color' as string]: g.color }}>
      <rect x={g.x1} y={g.yTop} width={boxW} height={boxH} rx={2} className="whale-seg-box__rect" />
      <line x1={g.x1} y1={g.entryY} x2={g.x2} y2={g.entryY} className="whale-seg-box__entry" />
      <line x1={g.x1} y1={g.targetY} x2={g.x2} y2={g.targetY} className="whale-seg-box__target" />
      <text x={g.x1 + 3} y={g.entryY - 3} className="whale-seg-box__price-tag">
        {g.entryPriceLabel}
      </text>
      <ellipse cx={volCx} cy={g.yVol} rx={volRx} ry={13} className="whale-seg-box__vol-ring" />
      <text x={volCx} y={g.yVol + 18} textAnchor="middle" className="whale-seg-box__vol-tag">
        {g.volLine}
      </text>
    </g>
  );
}

/** live: 구간 박스는 캔들 위 · 정보박스는 마지막 봉 오른쪽 빈 공간 */
function LiveRangeBox({ g }: { g: WhaleSegmentDrawGeom }) {
  const boxW = Math.max(8, g.x2 - g.x1);
  const boxH = Math.max(8, g.yBot - g.yTop);
  const cy = (g.yTop + g.yBot) / 2;
  const isLong = g.dir === 'long' || g.verdictKo === '상승';
  const isShort = g.dir === 'short' || g.verdictKo === '하락';
  const volCx = (g.volX1 + g.volX2) / 2;
  const volRx = Math.max(10, (g.volX2 - g.volX1) / 2 + 6);

  const ibx = g.infoBoxX;
  const ibw = g.infoBoxW;
  const bridgeY = cy;
  const stripX = ibx + ibw / 2;
  const arrowTipY = isLong ? bridgeY - g.arrowLen * 0.75 : isShort ? bridgeY + g.arrowLen * 0.75 : bridgeY - 24;

  const box1Y = bridgeY - 52;
  const box2Y = bridgeY + 8;
  const boxH1 = 44;
  const boxH2 = 36;

  const verdictIcon = g.verdictKo === '상승' ? '▲' : g.verdictKo === '하락' ? '▼' : '—';
  const movePct = g.chartLine1.includes('%') ? g.chartLine1.split(' ').slice(-1)[0] : '';

  return (
    <g className="whale-seg-box whale-seg-box--live" style={{ ['--seg-color' as string]: g.color }}>
      {/* 구간 박스 — 마지막 봉까지 포함 가능, 텍스트는 박스 밖 */}
      <rect x={g.x1} y={g.yTop} width={boxW} height={boxH} rx={3} className="whale-seg-box__rect" />
      <text x={g.x1 + 4} y={g.yTop - 5} className="whale-seg-box__seg-label">
        {g.segKind}
      </text>

      {/* 구간 맞춤 분석가격 — 진입·목표 수평선 + 가격 라벨 */}
      <line x1={g.x1} y1={g.entryY} x2={ibx + ibw} y2={g.entryY} className="whale-seg-box__entry" />
      <line x1={g.x1} y1={g.targetY} x2={ibx + ibw} y2={g.targetY} className="whale-seg-box__target" />
      <text x={g.x1 + 3} y={g.entryY - 4} className="whale-seg-box__price-tag whale-seg-box__price-tag--entry">
        {g.entryPriceLabel}
      </text>
      <text x={g.x1 + 3} y={g.targetY - 4} className="whale-seg-box__price-tag whale-seg-box__price-tag--target">
        {g.targetPriceLabel}
      </text>

      {/* 마지막 봉 → 정보박스 연결 (캔들 위 텍스트 없음) */}
      <line x1={g.xLastBarRight + 2} y1={bridgeY} x2={ibx - 4} y2={bridgeY} className="whale-seg-box__bridge" />
      <line x1={stripX} y1={bridgeY} x2={stripX} y2={arrowTipY} className="whale-seg-box__arrow" />
      <ArrowHead x={stripX} y={arrowTipY} up={isLong} />

      {/* 정보박스 ① — 구간 판정 · 하락폭 */}
      <rect x={ibx} y={box1Y} width={ibw} height={boxH1} rx={5} className="whale-seg-box__info" />
      <text x={ibx + 8} y={box1Y + 14} className="whale-seg-box__info-verdict">
        {verdictIcon} {g.verdictKo}
        {g.beamKo !== '관망' ? ` · ${g.beamKo}` : ''}
      </text>
      <text x={ibx + 8} y={box1Y + 28} className="whale-seg-box__info-line">
        {g.chartLine1}
      </text>
      <text x={ibx + 8} y={box1Y + 40} className="whale-seg-box__info-sub">
        하락폭 {movePct || g.move?.pctLabel || '—'} · {g.forecastEtaKo}
      </text>

      {/* 정보박스 ② — 진입가 · 구간 */}
      <rect x={ibx} y={box2Y} width={ibw} height={boxH2} rx={5} className="whale-seg-box__info whale-seg-box__info--entry" />
      <text x={ibx + 8} y={box2Y + 14} className="whale-seg-box__info-line">
        {g.entryPriceLabel}
      </text>
      <text x={ibx + 8} y={box2Y + 28} className="whale-seg-box__info-sub">
        {g.chartLine2}
      </text>

      {/* 거래량 원 — 구간 클러스터 (마지막 봉 마커 대신) */}
      <ellipse cx={volCx} cy={g.yVol} rx={volRx} ry={15} className="whale-seg-box__vol-ring" />
      <line
        x1={volCx}
        y1={g.yVol - 15}
        x2={Math.min(volCx, g.x2)}
        y2={g.yBot + 4}
        className="whale-seg-box__vol-link"
      />
      <text x={volCx} y={g.yVol + 22} textAnchor="middle" className="whale-seg-box__vol-tag">
        정보박스 {g.verdictKo} {movePct || ''}
      </text>
    </g>
  );
}

/** 구간분석 → 상승/하락 · 정보박스는 마지막 캔들 오른쪽 */
export function WhaleVolumeSegmentDrawLayer({ geoms }: Props) {
  if (!geoms.length) return null;

  const live = geoms.find((g) => g.mode === 'range_box_live');
  const past = geoms.filter((g) => g.mode === 'range_box_past');

  return (
    <svg className="whale-segment-draw-layer" aria-hidden>
      <defs>
        <filter id="whale-seg-glow" x="-20%" y="-20%" width="140%" height="140%">
          <feGaussianBlur stdDeviation="1.2" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>
      {past.map((g) => (
        <PastRangeBox key={g.id} g={g} />
      ))}
      {live && <LiveRangeBox g={live} />}
    </svg>
  );
}

