'use client';

import type { WhaleBeamIntelPack } from '@/lib/whaleVolumeBeamIntel';

type Props = {
  intel: WhaleBeamIntelPack | null;
  loading?: boolean;
};

function fmtPrice(p: number): string {
  if (!Number.isFinite(p) || p <= 0) return '—';
  return p >= 1000 ? p.toLocaleString('en-US', { maximumFractionDigits: 0 }) : p.toFixed(2);
}

function forecastEtaKo(timeframe: string, bars: number): string {
  const map: Record<string, number> = { '15m': 15, '1h': 60, '4h': 240, '1d': 1440 };
  const mins = (map[timeframe] ?? 60) * Math.max(1, bars);
  if (mins < 90) return `${mins}분 이내`;
  if (mins < 1440) return `${Math.round(mins / 60)}시간 이내`;
  return `${Math.round(mins / 1440)}일 이내`;
}

/** ①번 위치 — 차트 우측 여백 고정 레일 (캔들·가격축과 절대 겹치지 않음) */
export function WhaleBeamIntelRail({ intel, loading }: Props) {
  const live = intel?.live;
  const oracle = intel?.oracle;
  if (!live && !loading) return null;

  const verdictIcon = live?.verdictKo === '상승' ? '▲' : live?.verdictKo === '하락' ? '▼' : '—';
  const moveLabel =
    live?.verdictKo === '상승' ? '상승폭' : live?.verdictKo === '하락' ? '하락폭' : '변동폭';
  const eta =
    live && intel ? forecastEtaKo(intel.timeframe, live.forecastBars) : '';
  const dirClass =
    live?.verdictKo === '상승'
      ? 'whale-beam-rail--long'
      : live?.verdictKo === '하락'
        ? 'whale-beam-rail--short'
        : 'whale-beam-rail--neutral';

  return (
    <div className={`whale-beam-intel-rail ${dirClass}`} aria-label="고래 DNA 미래 시나리오">
      <div className="whale-beam-rail__badge">{oracle?.railTitleKo ?? 'WHALE·ORACLE ①'}</div>

      {loading && !live ? (
        <div className="whale-beam-rail__card whale-beam-rail__card--scan">
          <span className="whale-beam-rail__scan-dot" />
          Bitget DNA 스캔 중…
        </div>
      ) : live ? (
        <>
          <div className="whale-beam-rail__card whale-beam-rail__card--verdict">
            <div className="whale-beam-rail__verdict">
              {verdictIcon} {live.verdictKo}
              {live.beamKo !== '관망' ? ` · ${live.beamKo}` : ''}
            </div>
            <div className="whale-beam-rail__line">{live.move.chartLine1}</div>
            <div className="whale-beam-rail__sub">
              {moveLabel} {live.move.pctLabel} · {eta}
            </div>
          </div>

