            <div className="whale-beam-rail__line">{live.move.entryKo} {fmtPrice(live.entryPrice)}</div>
            <div className="whale-beam-rail__sub">
              목표 {fmtPrice(live.targetPrice)} ({live.move.pctLabel})
            </div>
          </div>

