/**
 * Bitget 고래 DNA — 캔들·거래량 시리즈 마커 전용 (카드/패널 없음)
 */
import type { UTCTimestamp } from 'lightweight-charts';
import type { Candle } from '@/types';
import type { VolumePanelMarker } from '@/lib/volumeHistogramIntelligence';
import type { WhaleSegmentVolumeSignal } from '@/lib/whaleVolumeSegmentSignals';

export type WhaleCandleMarker = {
  time: UTCTimestamp;
  position: 'aboveBar' | 'belowBar';
  shape: 'arrowUp' | 'arrowDown' | 'circle';
  color: string;
  text: string;
  size: 1 | 2 | 3;
};

function dirOf(s: WhaleSegmentVolumeSignal): 'long' | 'short' | 'neutral' {
  if (s.verdictKo === '상승' || s.dir === 'long') return 'long';
  if (s.verdictKo === '하락' || s.dir === 'short') return 'short';
  return 'neutral';
}

/** 캔들 — 화살 아이콘만, 긴 글자 없음 */
export function buildWhaleBeamCandleMarkers(
  signals: WhaleSegmentVolumeSignal[],
  candles: Candle[]
): WhaleCandleMarker[] {
  if (!candles.length || !signals.length) return [];
  const lastIdx = candles.length - 1;
  const out: WhaleCandleMarker[] = [];

  for (const s of signals) {
    const d = dirOf(s);
    if (d === 'neutral' && s.beamKo === '관망') continue;

    if (s.isLive) {
      // 구간 끝(마지막 봉 직전) — 마지막 캔들 위 글자·겹침 방지
      const boxEndIdx = Math.max(s.fromIdx, s.toIdx - 1);
      const breakC = candles[boxEndIdx];
      if (breakC) {
        out.push({
          time: breakC.time as UTCTimestamp,
          position: 'aboveBar',
          shape: d === 'long' ? 'arrowUp' : 'arrowDown',
          color: s.move.color,
          text: '',
          size: 2,
        });
      }
      continue;
    }

    const c = candles[s.volIdx];
    if (!c || s.volIdx >= lastIdx - 2) continue;
    out.push({
      time: c.time as UTCTimestamp,
      position: d === 'short' ? 'aboveBar' : 'belowBar',
      shape: d === 'long' ? 'arrowUp' : 'arrowDown',
      color: s.move.color,
      text: '',
      size: 1,
    });
  }
  return out;
}

/** 거래량 막대 — 짧은 한글 (막대 위) */
export function buildWhaleBeamVolumeMarkers(
  signals: WhaleSegmentVolumeSignal[],
  candles: Candle[]
): VolumePanelMarker[] {
  if (!candles.length || !signals.length) return [];
  const out: VolumePanelMarker[] = [];

  for (const s of signals) {
    const d = dirOf(s);
    const arrow = d === 'long' ? '▲' : d === 'short' ? '▼' : '·';
    const tier = s.move.tierLabel ?? '';
    const pct = s.move.pctLabel ?? '';
    const beam = s.beamKo && s.beamKo !== '관망' ? s.beamKo : '';
    const label = beam
      ? `${beam}${pct}`
      : `${arrow}${tier}${pct}`.replace(/\s+/g, '').slice(0, 14);

    const peakIdx = s.volIdx;
    const from = s.volClusterFromIdx ?? peakIdx;
    const to = s.volClusterToIdx ?? peakIdx;

    if (s.isLive) {
      for (let i = from; i <= to; i++) {
        const c = candles[i];
        if (!c) continue;
        out.push({
          time: c.time as UTCTimestamp,
          position: 'aboveBar',
          shape: d === 'long' ? 'arrowUp' : 'arrowDown',
          color: s.move.color,
          text: i === peakIdx ? label : '',
          size: i === peakIdx ? 2 : 1,
        });
      }
      continue;
    }

    const c = candles[peakIdx];
    if (!c) continue;
    out.push({
      time: c.time as UTCTimestamp,
      position: 'aboveBar',
      shape: 'circle',
      color: s.move.color,
      text: label,
      size: 1,
    });
  }
  return out;
}

