/**
 * CSV/API 고래 신호 → 차트 캔들 시간 동기화 (인덱스 불일치 방지)
 */
import type { Candle } from '@/types';
import type { WhaleSegmentVolumeSignal } from '@/lib/whaleVolumeSegmentSignals';

function idxForTime(candles: Candle[], t: number): number {
  const n = candles.length;
  if (n === 0) return -1;
  for (let i = n - 1; i >= 0; i--) {
    const ct = Number(candles[i]!.time);
    if (ct === t) return i;
    if (ct < t) return i;
  }
  return 0;
}

function idxRangeForTimes(candles: Candle[], tFrom: number, tTo: number): { from: number; to: number } {
  const a = idxForTime(candles, tFrom);
  const b = idxForTime(candles, tTo);
  return { from: Math.min(a, b), to: Math.max(a, b) };
}

/** API/CSV 인덱스 → 현재 차트 candles 기준으로 재매핑 */
export function syncWhaleSignalsToChart(
  signals: WhaleSegmentVolumeSignal[],
  candles: Candle[]
): WhaleSegmentVolumeSignal[] {
  if (!candles.length || !signals.length) return signals;

  return signals.map((s) => {
    const volIdx = idxForTime(candles, Number(s.timeVol));
    const fromIdx = idxForTime(candles, Number(s.timeFrom));
    const toIdx = idxForTime(candles, Number(s.timeTo));
    const boxTo = s.timeBoxTo != null ? idxForTime(candles, Number(s.timeBoxTo)) : toIdx;
    const vFrom = s.timeVolFrom != null ? idxForTime(candles, Number(s.timeVolFrom)) : volIdx;
    const vTo = s.timeVolTo != null ? idxForTime(candles, Number(s.timeVolTo)) : volIdx;
    const rg = idxRangeForTimes(candles, Number(s.timeVolFrom ?? s.timeFrom), Number(s.timeVolTo ?? s.timeTo));

    return {
      ...s,
      fromIdx: Math.max(0, fromIdx),
      toIdx: Math.max(0, toIdx),
      volIdx: Math.max(0, volIdx),
      volClusterFromIdx: Math.max(0, rg.from),
      volClusterToIdx: Math.max(0, rg.to),
      timeBoxTo: s.timeBoxTo ?? s.timeTo,
    };
  });
}

export function thinWhaleSignalsByChartTime(
  signals: WhaleSegmentVolumeSignal[],
  candles: Candle[],
  opts?: { maxPast?: number; minBarGap?: number; liveClearance?: number }
): WhaleSegmentVolumeSignal[] {
  const maxPast = opts?.maxPast ?? 3;
  const minBarGap = opts?.minBarGap ?? 10;
  const liveClearance = opts?.liveClearance ?? 8;
  if (!candles.length) return signals;

  const lastT = Number(candles[candles.length - 1]!.time);
  const clearanceT =
    candles.length > liveClearance
      ? Number(candles[candles.length - 1 - liveClearance]!.time)
      : 0;

  const live = signals.filter((s) => s.isLive).sort((a, b) => b.strength - a.strength);
  const past = signals
    .filter((s) => !s.isLive && Number(s.timeTo) < clearanceT)
    .sort((a, b) => b.strength - a.strength || Number(b.timeTo) - Number(a.timeTo));

  const bestLive = live[0] ?? null;
  const pickedPast: WhaleSegmentVolumeSignal[] = [];
  for (const s of past) {
    if (pickedPast.length >= maxPast) break;
    const tooClose = pickedPast.some(
      (p) => Math.abs(Number(p.timeVol) - Number(s.timeVol)) < minBarGap * 60
    );
    if (tooClose) continue;
    pickedPast.push(s);
  }
  const out = bestLive ? [bestLive, ...pickedPast] : pickedPast;
  return out.sort((a, b) => Number(a.timeFrom) - Number(b.timeFrom));
}

/**
 * Bitget 고래 DNA — 캔들·거래량 시리즈 마커 전용 (카드/패널 없음)
 */
import type { UTCTimestamp } from 'lightweight-charts';
import type { Candle } from '@/types';
import type { VolumePanelMarker } from '@/lib/volumeHistogramIntelligence';
import type { WhaleSegmentVolumeSignal } from '@/lib/whaleVolumeSegmentSignals';

export type WhaleCandleMarker = {
  time: UTCTimestamp;
  position: 'aboveBar' | 'belowBar';
  shape: 'arrowUp' | 'arrowDown' | 'circle';
  color: string;
  text: string;
  size: 1 | 2 | 3;
};

function dirOf(s: WhaleSegmentVolumeSignal): 'long' | 'short' | 'neutral' {
  if (s.verdictKo === '상승' || s.move.dir === 'long') return 'long';
  if (s.verdictKo === '하락' || s.move.dir === 'short') return 'short';
  return 'neutral';
}

function candleAtTime(candles: Candle[], t: number): Candle | null {
  for (let i = candles.length - 1; i >= 0; i--) {
    const ct = Number(candles[i]!.time);
    if (ct === t) return candles[i]!;
    if (ct < t) return candles[i] ?? null;
  }
  return candles[0] ?? null;
}

function candlesInTimeRange(candles: Candle[], tFrom: number, tTo: number): Candle[] {
  const lo = Math.min(tFrom, tTo);
  const hi = Math.max(tFrom, tTo);
  return candles.filter((c) => {
    const t = Number(c.time);
    return t >= lo && t <= hi;
  });
}

/** 캔들 — 화살 아이콘만 (마지막 봉 위 글자 없음) */
export function buildWhaleBeamCandleMarkers(
  signals: WhaleSegmentVolumeSignal[],
  candles: Candle[]
): WhaleCandleMarker[] {
  if (!candles.length || !signals.length) return [];
  const lastT = Number(candles[candles.length - 1]!.time);
  const out: WhaleCandleMarker[] = [];

  for (const s of signals) {
    const d = dirOf(s);
    if (d === 'neutral' && s.beamKo === '관망') continue;

    const breakT = Number(s.timeBoxTo ?? s.timeTo);
    const breakC = candleAtTime(candles, breakT);
    if (!breakC) continue;
    if (s.isLive && breakT >= lastT) continue;

    out.push({
      time: breakC.time as UTCTimestamp,
      position: d === 'short' ? 'aboveBar' : 'belowBar',
      shape: d === 'long' ? 'arrowUp' : 'arrowDown',
      color: s.move.color,
      text: '',
      size: s.isLive ? 2 : 1,
    });
  }
  return out;
}

/** 거래량 막대 — 짧은 한글 (막대 위) */
export function buildWhaleBeamVolumeMarkers(
  signals: WhaleSegmentVolumeSignal[],
  candles: Candle[]
): VolumePanelMarker[] {
  if (!candles.length || !signals.length) return [];
  const out: VolumePanelMarker[] = [];

  for (const s of signals) {
    const d = dirOf(s);
    const arrow = d === 'long' ? '▲' : d === 'short' ? '▼' : '·';
    const tier = s.move.tierLabel ?? '';
    const pct = s.move.pctLabel ?? '';
    const beam = s.beamKo && s.beamKo !== '관망' ? s.beamKo : '';
    const label = beam
      ? `${beam}${pct}`
      : `${arrow}${tier}${pct}`.replace(/\s+/g, '').slice(0, 14);

    const tFrom = Number(s.timeVolFrom ?? s.timeFrom);
    const tTo = Number(s.timeVolTo ?? s.timeVol);
    const cluster = candlesInTimeRange(candles, tFrom, tTo);
    const peakT = Number(s.timeVol);

    if (s.isLive) {
      for (const c of cluster) {
        const t = Number(c.time);
        out.push({
          time: c.time as UTCTimestamp,
          position: 'aboveBar',
          shape: 'square',
          color: s.move.color,
          text: t === peakT ? label : '',
          size: t === peakT ? 2 : 1,
        });
      }
      continue;
    }

    const c = candleAtTime(candles, peakT);
    if (!c) continue;
    out.push({
      time: c.time as UTCTimestamp,
      position: 'aboveBar',
      shape: 'square',
      color: s.move.color,
      text: label,
      size: 1,
    });
  }
  return out;
}

