'use client';

import type { WhaleSegmentDrawGeom } from '@/lib/whaleVolumeSegmentSignals';

type Props = {
  geoms: WhaleSegmentDrawGeom[];
};

const BEAM_LONG = '#22d3ee';
const BEAM_SHORT = '#f97316';

function WhaleSegGlowDef() {
  return (
    <defs>
      <filter id="whale-seg-glow" x="-40%" y="-40%" width="180%" height="180%">
        <feGaussianBlur stdDeviation="2.2" result="blur" />
        <feMerge>
          <feMergeNode in="blur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
    </defs>
  );
}

/** 이미지 ①~④ — 세로 BEAM 랜스 (카드·우측 레일 없음, 차트 캔들 위 직접) */
function BeamLance({ g, live }: { g: WhaleSegmentDrawGeom; live: boolean }) {
  const isShort = g.dir === 'short' || g.verdictKo === '하락' || g.beamKo === '숏빔';
  const isLong = g.dir === 'long' || g.verdictKo === '상승' || g.beamKo === '롱빔';
  const axisX = g.breakX;
  const boxW = Math.max(8, g.x2 - g.x1);
  const volCx = (g.volX1 + g.volX2) / 2;
  const volRx = Math.max(10, (g.volX2 - g.volX1) / 2 + 6);

  const beamTopY = g.yTop - 20;
  const beamBotY = g.yBot + 20;
  const axisTop = Math.min(beamTopY - 14, g.targetY, g.entryY) - 6;
  const axisBot = Math.max(beamBotY + 18, g.targetY, g.yVol + 36) + 22;

  const dirLabel = isShort ? '▼ SHORT' : isLong ? '▲ LONG' : '◆ WAIT';
  const sub = [g.beamKo !== '관망' ? g.beamKo : '', g.pctLabel].filter(Boolean).join(' · ');
  const dirLine = sub ? `${dirLabel} · ${sub}` : `${dirLabel} —`;

  const arrowLen = Math.min(72, Math.max(36, g.arrowLen));
  const arrowTipY = isShort
    ? Math.min(g.targetY, g.breakY + arrowLen)
    : isLong
      ? Math.max(g.targetY, g.breakY - arrowLen)
      : g.breakY + (g.arrowUp ? -arrowLen : arrowLen);

  const cls = live ? 'whale-seg-lance whale-seg-lance--live' : 'whale-seg-lance whale-seg-lance--past';

  return (
    <g className={cls} style={{ ['--seg-color' as string]: g.color }}>
      {/* ① 세로 점선 축 (이탈 봉 X) */}
      <line x1={axisX} y1={axisTop} x2={axisX} y2={axisBot} className="whale-seg-lance__conn" />

      {/* 횡보 구간 박스 */}
      <rect
        x={g.x1}
        y={g.yTop}
        width={boxW}
        height={Math.max(8, g.yBot - g.yTop)}
        rx={3}
        className="whale-seg-box__rect"
      />

      {/* 진입·목표 가로 점선 */}
      <line x1={g.x1} y1={g.entryY} x2={g.lineEndX} y2={g.entryY} className="whale-seg-lance__entry-line" />
      <line x1={g.x1} y1={g.targetY} x2={g.lineEndX} y2={g.targetY} className="whale-seg-lance__target-line" />

      {/* ① ▲ BEAM — 구간 상단 */}
      <text
        x={axisX + 7}
        y={beamTopY}
        className="whale-seg-lance__tag"
        fill={isLong ? BEAM_LONG : BEAM_LONG}
        opacity={isLong || live ? 1 : 0.55}
      >
        ▲ BEAM
      </text>

      {/* ③ ▼ BEAM — 구간 하단 */}
      <text
        x={axisX + 7}
        y={beamBotY}
        className="whale-seg-lance__tag"
        fill={BEAM_SHORT}
        opacity={isShort || live ? 1 : 0.55}
      >
        ▼ BEAM
      </text>

      {/* ② 이탈 화살 + S/L 마크 */}
      <line
        x1={axisX}
        y1={g.breakY}
        x2={axisX}
        y2={arrowTipY}
        className="whale-seg-lance__dir-arrow"
        stroke={isShort ? '#fb7185' : isLong ? BEAM_LONG : g.color}
        strokeWidth={live ? 2.8 : 2}
      />
      <polygon
        points={
          isLong
            ? `${axisX},${arrowTipY - 2} ${axisX - 6},${arrowTipY + 8} ${axisX + 6},${arrowTipY + 8}`
            : `${axisX},${arrowTipY + 2} ${axisX - 6},${arrowTipY - 8} ${axisX + 6},${arrowTipY - 8}`
        }
        fill={isShort ? '#fb7185' : isLong ? BEAM_LONG : g.color}
        className="whale-seg-lance__head"
      />
      {(isShort || isLong) && (
        <text
          x={axisX + 9}
          y={isLong ? g.breakY - 6 : g.breakY + 14}
          className="whale-seg-lance__tag-sub"
          fill={isShort ? '#fb7185' : BEAM_LONG}
          fontWeight={900}
        >
          {isShort ? 'S' : 'L'}
        </text>
      )}

      {/* ④ 목표 원 (세로축 × 목표가 Y) */}
      <circle cx={axisX} cy={g.targetY} r={live ? 5.5 : 4} className="whale-seg-lance__vol-dot" />
      <text x={axisX + 8} y={g.targetY + 3} className="whale-seg-lance__target-label">
        {g.targetPriceLabel.replace(/^목표\s*/, '')}
      </text>

      {/* 거래량 클러스터 — 막대 위 타원 + 연결 */}
      <ellipse cx={volCx} cy={g.yVol} rx={volRx} ry={live ? 14 : 11} className="whale-seg-box__vol-ring" />
      <line x1={volCx} y1={g.yVol - 14} x2={axisX} y2={g.yBot + 4} className="whale-seg-lance__conn" />

      {/* 하단 방향 라벨 ▼ SHORT — */}
      <text x={axisX + 7} y={axisBot - 2} className="whale-seg-lance__tag" fill={g.color}>
        {dirLine}
      </text>
    </g>
  );
}

/** SVG — BEAM 랜스 ①~④ (플로팅 카드·우측 정보창 없음) */
export function WhaleVolumeSegmentDrawLayer({ geoms }: Props) {
  if (!geoms.length) return null;

  const live = geoms.find((g) => g.mode === 'range_box_live');
  const past = geoms.filter((g) => g.mode === 'range_box_past');

  return (
    <svg className="whale-segment-draw-layer" aria-hidden>
      <WhaleSegGlowDef />
      {past.map((g) => (
        <BeamLance key={g.id} g={g} live={false} />
      ))}
      {live && <BeamLance g={live} live />}
    </svg>
  );
}

