'use client';

import type { WhaleSegmentDrawGeom } from '@/lib/whaleVolumeSegmentSignals';

const BEAM_LONG = '#22d3ee';
const BEAM_SHORT = '#f97316';

export type WhaleBeamMarginMeta = {
  tierBtc?: number;
  sampleCount?: number;
  listingFromKo?: string;
};

type Props = {
  geom: WhaleSegmentDrawGeom | null | undefined;
  meta?: WhaleBeamMarginMeta | null;
  chartHeight: number;
  volPanelTopRatio?: number;
};

/** 통합·분석 — 우측 여백(미래 구간) BEAM 오라클. 마지막 캔들 위 겹침 없음 */
export function WhaleBeamMarginOracle({ geom, meta, chartHeight, volPanelTopRatio = 0.82 }: Props) {
  if (!geom || geom.layout !== 'margin_oracle') return null;
  const ml = geom.marginLeft ?? 0;
  const mr = geom.marginRight ?? ml + 92;
  const w = Math.max(72, mr - ml);
  const panelH = chartHeight * volPanelTopRatio;

  const isShort = geom.dir === 'short' || geom.verdictKo === '하락' || geom.beamKo === '숏빔';
  const isLong = geom.dir === 'long' || geom.verdictKo === '상승' || geom.beamKo === '롱빔';
  const axisX = w / 2;

  const ys = [geom.yTop, geom.yBot, geom.entryY, geom.targetY].filter((y) => Number.isFinite(y));
  const yMin = Math.min(...ys, geom.breakY) - 28;
  const yMax = Math.max(...ys, geom.breakY) + 36;
  const spineTop = Math.max(12, yMin);
  const spineBot = Math.min(panelH - 8, yMax);

  const dirLabel = isShort ? '▼ SHORT' : isLong ? '▲ LONG' : '◆ WAIT';
  const sub = [geom.beamKo !== '관망' ? geom.beamKo : '', geom.pctLabel].filter(Boolean).join(' · ');

  const arrowTipY = isShort
    ? Math.min(geom.targetY, geom.breakY + geom.arrowLen * 0.55)
    : isLong
      ? Math.max(geom.targetY, geom.breakY - geom.arrowLen * 0.55)
      : geom.breakY;

  return (
    <div
      className="whale-beam-margin-oracle"
      style={{ left: ml, width: w, height: panelH }}
      aria-hidden
    >
      <svg className="whale-beam-margin-oracle__svg" width={w} height={panelH}>
        <rect x={1} y={spineTop - 8} width={w - 2} height={spineBot - spineTop + 16} rx={6} className="whale-beam-margin-oracle__panel" />

        <text x={axisX} y={spineTop - 2} textAnchor="middle" className="whale-beam-margin-oracle__brand">
          BITGET DNA
        </text>

        {/* 세로 BEAM 축 */}
        <line x1={axisX} y1={spineTop + 6} x2={axisX} y2={spineBot - 4} className="whale-beam-margin-oracle__spine" />

        {/* ① ▲ BEAM */}
        <text x={axisX} y={geom.yTop - 6} textAnchor="middle" className="whale-beam-margin-oracle__beam whale-beam-margin-oracle__beam--long">
          ▲ BEAM
        </text>

        {/* ③ ▼ BEAM */}
        <text x={axisX} y={geom.yBot + 14} textAnchor="middle" className="whale-beam-margin-oracle__beam whale-beam-margin-oracle__beam--short">
          ▼ BEAM
        </text>

        {/* ② 방향 화살 */}
        <line
          x1={axisX}
          y1={geom.breakY}
          x2={axisX}
          y2={arrowTipY}
          className="whale-beam-margin-oracle__dir-line"
          stroke={isShort ? '#fb7185' : isLong ? BEAM_LONG : geom.color}
        />
        <polygon
          points={
            isLong
              ? `${axisX},${arrowTipY - 1} ${axisX - 7},${arrowTipY + 10} ${axisX + 7},${arrowTipY + 10}`
              : `${axisX},${arrowTipY + 1} ${axisX - 7},${arrowTipY - 10} ${axisX + 7},${arrowTipY - 10}`
          }
          fill={isShort ? '#fb7185' : isLong ? BEAM_LONG : geom.color}
        />
        {(isShort || isLong) && (
          <text
            x={axisX + 11}
            y={isLong ? geom.breakY - 4 : geom.breakY + 12}
            className="whale-beam-margin-oracle__side-mark"
            fill={isShort ? '#fb7185' : BEAM_LONG}
          >
            {isShort ? 'S' : 'L'}
          </text>
        )}

        {/* ④ 목표 */}
        <circle cx={axisX} cy={geom.targetY} r={6} className="whale-beam-margin-oracle__target-ring" />
        <text x={axisX} y={geom.targetY + 18} textAnchor="middle" className="whale-beam-margin-oracle__target-txt">
          {geom.targetPriceLabel.replace(/^목표\s*/, '')}
        </text>

        {/* 진입 틱 */}
        <circle cx={axisX} cy={geom.entryY} r={2.5} fill={geom.color} opacity={0.85} />
        <text x={axisX + 10} y={geom.entryY + 3} className="whale-beam-margin-oracle__entry-txt">
          {geom.entryPriceLabel}
        </text>

        {/* 하단 방향 */}
        <text x={axisX} y={spineBot + 2} textAnchor="middle" className="whale-beam-margin-oracle__footer" fill={geom.color}>
          {sub ? `${dirLabel} · ${sub}` : `${dirLabel} —`}
        </text>

        {meta?.tierBtc != null && (
          <text x={axisX} y={spineBot + 14} textAnchor="middle" className="whale-beam-margin-oracle__meta">
            {meta.tierBtc}BTC · n{meta.sampleCount ?? '—'}
            {meta.listingFromKo ? ` · ${meta.listingFromKo}~` : ''}
          </text>
        )}
      </svg>
    </div>
  );
}

