import type { WhaleSegmentDrawGeom } from '@/lib/whaleVolumeSegmentSignals';
import { WhaleBeamMarginOracle, type WhaleBeamMarginMeta } from '@/app/components/WhaleBeamMarginOracle';

type Props = {
  geoms: WhaleSegmentDrawGeom[];
  marginMeta?: WhaleBeamMarginMeta | null;
  chartHeight?: number;
  volPanelTopRatio?: number;
};

function PastMiniBox({ g }: { g: WhaleSegmentDrawGeom }) {
  const boxW = Math.max(6, g.x2 - g.x1);
  return (
    <g className="whale-seg-box whale-seg-box--past" style={{ ['--seg-color' as string]: g.color }}>
      <rect x={g.x1} y={g.yTop} width={boxW} height={Math.max(6, g.yBot - g.yTop)} rx={2} className="whale-seg-box__rect" />
    </g>
  );
}

/** 가격 Y → 우측 여백까지 얇은 연결선 (캔들 위 글자 없음) */
function MarginConnectors({ g }: { g: WhaleSegmentDrawGeom }) {
  const ax = g.chartAnchorX ?? g.x2;
  const ml = g.marginLeft ?? ax;
  if (!Number.isFinite(ax) || !Number.isFinite(ml)) return null;
  const levels = [
    { y: g.yTop, cls: 'whale-beam-margin-oracle__hair--top' },
    { y: g.yBot, cls: 'whale-beam-margin-oracle__hair--bot' },
    { y: g.entryY, cls: 'whale-beam-margin-oracle__hair--entry' },
    { y: g.targetY, cls: 'whale-beam-margin-oracle__hair--target' },
  ];
  return (
    <g className="whale-beam-margin-connectors">
      {levels.map((lv) =>
        Number.isFinite(lv.y) ? (
          <line key={lv.cls} x1={ax} y1={lv.y} x2={ml} y2={lv.y} className={`whale-beam-margin-oracle__hair ${lv.cls}`} />
        ) : null
      )}
      <line x1={ax} y1={g.breakY} x2={ml} y2={g.breakY} className="whale-beam-margin-oracle__hair whale-beam-margin-oracle__hair--break" />
    </g>
  );
}

/** inline — 과거 구간만 캔들 위 / live margin — 연결선만 */
function InlineBeamLance({ g }: { g: WhaleSegmentDrawGeom }) {
  const isShort = g.dir === 'short' || g.verdictKo === '하락' || g.beamKo === '숏빔';
  const isLong = g.dir === 'long' || g.verdictKo === '상승' || g.beamKo === '롱빔';
  const axisX = g.breakX;
  const boxW = Math.max(8, g.x2 - g.x1);
  const beamTopY = g.yTop - 20;
  const beamBotY = g.yBot + 20;
  const dirLabel = isShort ? '▼ SHORT' : isLong ? '▲ LONG' : '◆ WAIT';
  const sub = [g.beamKo !== '관망' ? g.beamKo : '', g.pctLabel].filter(Boolean).join(' · ');

  return (
    <g className="whale-seg-lance whale-seg-lance--live" style={{ ['--seg-color' as string]: g.color }}>
      <rect x={g.x1} y={g.yTop} width={boxW} height={Math.max(8, g.yBot - g.yTop)} rx={3} className="whale-seg-box__rect" />
      <line x1={axisX} y1={beamTopY - 14} x2={axisX} y2={beamBotY + 22} className="whale-seg-lance__conn" />
      <text x={axisX + 7} y={beamTopY} className="whale-seg-lance__tag" fill="#22d3ee">
        ▲ BEAM
      </text>
      <text x={axisX + 7} y={beamBotY} className="whale-seg-lance__tag" fill="#f97316">
        ▼ BEAM
      </text>
      <circle cx={axisX} cy={g.targetY} r={5.5} className="whale-seg-lance__vol-dot" />
      <text x={axisX + 7} y={beamBotY + 18} className="whale-seg-lance__tag" fill={g.color}>
        {sub ? `${dirLabel} · ${sub}` : dirLabel}
      </text>
    </g>
  );
}

export function WhaleVolumeSegmentDrawLayer({
  geoms,
  marginMeta,
  chartHeight = 480,
  volPanelTopRatio = 0.82,
}: Props) {
  if (!geoms.length) return null;

  const live = geoms.find((g) => g.mode === 'range_box_live');
  const past = geoms.filter((g) => g.mode === 'range_box_past');
  const liveMargin = live?.layout === 'margin_oracle';

  return (
    <>
      <svg className="whale-segment-draw-layer" aria-hidden>
        {past.map((g) => (
          <PastMiniBox key={g.id} g={g} />
        ))}
        {live && liveMargin && <MarginConnectors g={live} />}
        {live && !liveMargin && <InlineBeamLance g={live} />}
      </svg>
      {liveMargin && (
        <WhaleBeamMarginOracle
          geom={live}
          meta={marginMeta}
          chartHeight={chartHeight}
          volPanelTopRatio={volPanelTopRatio}
        />
      )}
    </>
  );
}

