input.contents:
/**
 * Bitget 고래 DNA — 우측 여백(마지막 봉 다음) 오라클 좌표 (통합·분석)
 */
import type { WhaleSegmentVolumeSignal } from '@/lib/whaleVolumeSegmentSignals';

export type WhaleBeamRightOracleGeom = {
  id: string;
  chartHeight: number;
  volPanelTop: number;
  priceAxisReserve: number;
  /** 횡보 구간 (캔들 위 — 글자 없음) */
  box: { x1: number; x2: number; yTop: number; yBot: number };
  anchorX: number;
  /** 마지막 봉 우측 ~ 가격축 직전 */
  colLeft: number;
  colRight: number;
  colCenter: number;
  entryY: number;
  targetY: number;
  breakY: number;
  arrowLen: number;
  arrowUp: boolean;
  color: string;
  dir: 'long' | 'short' | 'neutral';
  beamKo: string;
  verdictKo: string;
  pctLabel: string;
  entryPriceLabel: string;
  targetPriceLabel: string;
  footerLine: string;
  tierBtc?: number;
  sampleCount?: number;
  listingFromKo?: string;
};

function fmtPrice(p: number): string {
  if (!Number.isFinite(p) || p <= 0) return '—';
  if (p >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  return p.toFixed(2);
}

function dirOf(s: WhaleSegmentVolumeSignal): 'long' | 'short' | 'neutral' {
  if (s.verdictKo === '상승' || s.move.dir === 'long') return 'long';
  if (s.verdictKo === '하락' || s.move.dir === 'short') return 'short';
  return 'neutral';
}

export function buildWhaleBeamRightOracleGeom(params: {
  signal: WhaleSegmentVolumeSignal;
  resolveTimeX: (t: number) => number;
  priceToY: (p: number) => number | null;
  chartWidth: number;
  chartHeight: number;
  lastBarTime?: number;
  prevBarTime?: number;
  priceAxisReserve?: number;
  volPanelTopRatio?: number;
}): WhaleBeamRightOracleGeom | null {
  const {
    signal: s,
    resolveTimeX,
    priceToY,
    chartWidth,
    chartHeight,
    lastBarTime,
    prevBarTime,
    priceAxisReserve = 62,
    volPanelTopRatio = 0.82,
  } = params;

  const x1 = resolveTimeX(s.timeFrom);
  const boxEndT = s.timeBoxTo ?? s.timeTo;
  const x2raw = resolveTimeX(boxEndT);
  const yTop = priceToY(s.priceHigh);
  const yBot = priceToY(s.priceLow);
  if (!Number.isFinite(x1) || !Number.isFinite(x2raw) || yTop == null || yBot == null) return null;

  const boxTop = Math.min(yTop, yBot) - 5;
  const boxBot = Math.max(yTop, yBot) + 5;
  const x2 = Math.max(x1, x2raw);

  let lastX = lastBarTime != null ? resolveTimeX(lastBarTime) : x2;
  let prevX = prevBarTime != null ? resolveTimeX(prevBarTime) : lastX - 14;
  if (!Number.isFinite(lastX)) lastX = x2;
  if (!Number.isFinite(prevX)) prevX = lastX - 14;
  const barW = Math.max(8, lastX - prevX);

  const colRight = Math.max(x2 + barW, chartWidth - priceAxisReserve - 6);
  let colLeft = Math.max(x2 + barW * 0.35, lastX + barW * 0.45);
  if (colRight - colLeft < 56) colLeft = colRight - 80;
  const colCenter = (colLeft + colRight) / 2;

  const close = s.priceClose;
  const med = s.forecastPct ?? 0;
  const entryPrice =
    s.entryPrice ??
    (s.move.dir === 'long' ? s.priceLow : s.move.dir === 'short' ? s.priceHigh : close);
  const targetPrice =
    s.targetPrice ?? (close > 0 ? close * (1 + med / 100) : close);
  const entryY = priceToY(entryPrice) ?? priceToY(close) ?? boxBot;
  const targetY = priceToY(targetPrice) ?? entryY;

  const dir = dirOf(s);
  const isUp = dir === 'long' || s.verdictKo === '상승';
  const breakY = isUp ? boxTop - 8 : boxBot + 8;
  const arrowLen = Math.min(80, Math.max(36, 32 + Math.abs(med) * 10));

  const dirLabel = dir === 'short' ? '▼ SHORT' : dir === 'long' ? '▲ LONG' : '◆ WAIT';
  const sub = [s.beamKo && s.beamKo !== '관망' ? s.beamKo : '', s.move.pctLabel ?? ''].filter(Boolean).join(' · ');
  const footerLine = sub ? `${dirLabel} · ${sub}` : `${dirLabel} —`;

  return {
    id: s.id,
    chartHeight,
    volPanelTop: chartHeight * volPanelTopRatio,
    priceAxisReserve,
    box: { x1: Math.min(x1, x2), x2: Math.max(x1, x2), yTop: boxTop, yBot: boxBot },
    anchorX: x2,
    colLeft,
    colRight,
    colCenter,
    entryY,
    targetY,
    breakY,
    arrowLen,
    arrowUp: isUp,
    color: s.move.color,
    dir,
    beamKo: s.beamKo ?? '관망',
    verdictKo: s.verdictKo ?? '횡보',
    pctLabel: s.move.pctLabel ?? '—',
