    targetPriceLabel: `목표 ${fmtPrice(targetPrice)} (${s.move.pctLabel ?? '—'})`,
    footerLine,
  };
}

'use client';

import type { WhaleBeamRightOracleGeom } from '@/lib/whaleBeamRightOracleGeom';

const BEAM_LONG = '#22d3ee';
const BEAM_SHORT = '#f97316';

type Props = {
  oracle: WhaleBeamRightOracleGeom | null;
};

/** 통합·분석 — 마지막 봉 우측 여백 BEAM DNA (캔들·마지막봉 글자 없음) */
export function WhaleVolumeSegmentDrawLayer({ oracle }: Props) {
  if (!oracle) return null;

  const g = oracle;
  const w = g.chartHeight > 0 ? '100%' : 480;
  const h = g.chartHeight;
  const colW = Math.max(56, g.colRight - g.colLeft);
  const isShort = g.dir === 'short' || g.verdictKo === '하락' || g.beamKo === '숏빔';
  const isLong = g.dir === 'long' || g.verdictKo === '상승' || g.beamKo === '롱빔';

  const ys = [g.box.yTop, g.box.yBot, g.entryY, g.targetY, g.breakY];
  const spineTop = Math.max(16, Math.min(...ys) - 24);
  const spineBot = Math.min(g.volPanelTop - 12, Math.max(...ys) + 28);

  const arrowTipY = isShort
    ? Math.min(g.targetY, g.breakY + g.arrowLen * 0.5)
    : isLong
      ? Math.max(g.targetY, g.breakY - g.arrowLen * 0.5)
      : g.breakY + (g.arrowUp ? -g.arrowLen * 0.5 : g.arrowLen * 0.5);

  return (
    <svg className="whale-segment-draw-layer" width="100%" height={h} aria-hidden>
      <defs>
        <filter id="whale-seg-glow" x="-40%" y="-40%" width="180%" height="180%">
          <feGaussianBlur stdDeviation="2.2" result="blur" />
          <feMerge>
            <feMergeNode in="blur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
      </defs>

      {/* 횡보 박스 — 글자 없음 */}
      <rect
        x={g.box.x1}
        y={g.box.yTop}
        width={Math.max(6, g.box.x2 - g.box.x1)}
        height={Math.max(6, g.box.yBot - g.box.yTop)}
        rx={3}
        className="whale-seg-box__rect whale-seg-box--live"
        style={{ ['--seg-color' as string]: g.color }}
      />

      {/* 박스 → 여백 연결 (가격선) */}
      {[
        { y: g.box.yTop, cls: 'whale-beam-margin-oracle__hair--top' },
        { y: g.box.yBot, cls: 'whale-beam-margin-oracle__hair--bot' },
        { y: g.entryY, cls: 'whale-beam-margin-oracle__hair--entry' },
        { y: g.targetY, cls: 'whale-beam-margin-oracle__hair--target' },
        { y: g.breakY, cls: 'whale-beam-margin-oracle__hair--break' },
      ].map((lv) => (
        <line
          key={lv.cls}
          x1={g.anchorX}
          y1={lv.y}
          x2={g.colLeft}
          y2={lv.y}
          className={`whale-beam-margin-oracle__hair ${lv.cls}`}
        />
      ))}

      {/* 우측 여백 패널 */}
      <rect
        x={g.colLeft}
        y={spineTop - 10}
        width={colW}
        height={spineBot - spineTop + 20}
        rx={7}
        className="whale-beam-margin-oracle__panel"
      />

      <text x={g.colCenter} y={spineTop - 2} textAnchor="middle" className="whale-beam-margin-oracle__brand">
        BITGET DNA
      </text>

      <line
        x1={g.colCenter}
        y1={spineTop + 4}
        x2={g.colCenter}
        y2={spineBot - 2}
        className="whale-beam-margin-oracle__spine"
      />

      <text
        x={g.colCenter}
        y={g.box.yTop - 4}
        textAnchor="middle"
        className="whale-beam-margin-oracle__beam whale-beam-margin-oracle__beam--long"
      >
        ▲ BEAM
      </text>

      <text
        x={g.colCenter}
        y={g.box.yBot + 16}
        textAnchor="middle"
        className="whale-beam-margin-oracle__beam whale-beam-margin-oracle__beam--short"
      >
        ▼ BEAM
      </text>

      <line
        x1={g.colCenter}
        y1={g.breakY}
        x2={g.colCenter}
        y2={arrowTipY}
        className="whale-beam-margin-oracle__dir-line"
        stroke={isShort ? '#fb7185' : isLong ? BEAM_LONG : g.color}
        strokeWidth={2.6}
      />
      <polygon
        points={
          isLong
            ? `${g.colCenter},${arrowTipY - 1} ${g.colCenter - 7},${arrowTipY + 10} ${g.colCenter + 7},${arrowTipY + 10}`
            : `${g.colCenter},${arrowTipY + 1} ${g.colCenter - 7},${arrowTipY - 10} ${g.colCenter + 7},${arrowTipY - 10}`
        }
        fill={isShort ? '#fb7185' : isLong ? BEAM_LONG : g.color}
      />
      {(isShort || isLong) && (
        <text
          x={g.colCenter + 12}
          y={isLong ? g.breakY - 4 : g.breakY + 14}
          className="whale-beam-margin-oracle__side-mark"
          fill={isShort ? '#fb7185' : BEAM_LONG}
        >
          {isShort ? 'S' : 'L'}
        </text>
      )}

      <circle cx={g.colCenter} cy={g.targetY} r={6} className="whale-beam-margin-oracle__target-ring" />
      <text x={g.colCenter} y={g.targetY + 18} textAnchor="middle" className="whale-beam-margin-oracle__target-txt">
        {g.targetPriceLabel.replace(/^목표\s*/, '')}
      </text>

      <circle cx={g.colCenter} cy={g.entryY} r={2.5} fill={g.color} opacity={0.9} />
      <text x={g.colCenter + 10} y={g.entryY + 3} className="whale-beam-margin-oracle__entry-txt">
        {g.entryPriceLabel}
      </text>

      <text x={g.colCenter} y={spineBot + 4} textAnchor="middle" className="whale-beam-margin-oracle__footer" fill={g.color}>
        {g.footerLine}
      </text>

      {g.tierBtc != null && (
        <text x={g.colCenter} y={spineBot + 16} textAnchor="middle" className="whale-beam-margin-oracle__meta">
          {g.tierBtc}BTC · n{g.sampleCount ?? '—'}
          {g.listingFromKo ? ` · ${g.listingFromKo}~` : ''}
        </text>
      )}
    </svg>
  );
}

