input.contents:
/**
 * Bitget 고래 DNA — 우측 여백 오라클 좌표 (마지막 캔들 X와 겹치지 않음)
 */
import type { WhaleSegmentVolumeSignal } from '@/lib/whaleVolumeSegmentSignals';

export type WhaleBeamRightOracleGeom = {
  id: string;
  chartHeight: number;
  volPanelTop: number;
  priceAxisReserve: number;
  box: { x1: number; x2: number; yTop: number; yBot: number };
  /** 횡보 박스 우측 — 가로 연결선 시작 */
  anchorX: number;
  colLeft: number;
  colRight: number;
  colCenter: number;
  entryY: number;
  targetY: number;
  color: string;
  dir: 'long' | 'short' | 'neutral';
  beamKo: string;
  verdictKo: string;
  pctLabel: string;
  entryPriceLabel: string;
  targetPriceLabel: string;
  footerLine: string;
  /** 과거 DNA 비교 */
  longPct: number;
  shortPct: number;
  similarCount: number;
  forecastBars: number;
  forecastPct: number | null;
  tierBtc?: number;
  sampleCount?: number;
  listingFromKo?: string;
  compareKo?: string;
};

function fmtPrice(p: number): string {
  if (!Number.isFinite(p) || p <= 0) return '—';
  if (p >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  return p.toFixed(2);
}

function dirOf(s: WhaleSegmentVolumeSignal): 'long' | 'short' | 'neutral' {
  if (s.verdictKo === '상승' || s.move.dir === 'long') return 'long';
  if (s.verdictKo === '하락' || s.move.dir === 'short') return 'short';
  return 'neutral';
}

export function buildWhaleBeamRightOracleGeom(params: {
  signal: WhaleSegmentVolumeSignal;
  resolveTimeX: (t: number) => number;
  priceToY: (p: number) => number | null;
  chartWidth: number;
  chartHeight: number;
  lastBarTime?: number;
  prevBarTime?: number;
  priceAxisReserve?: number;
  volPanelTopRatio?: number;
  longPct?: number;
  shortPct?: number;
  similarCount?: number;
  compareKo?: string;
}): WhaleBeamRightOracleGeom | null {
  const {
    signal: s,
    resolveTimeX,
    priceToY,
    chartWidth,
    chartHeight,
    lastBarTime,
    prevBarTime,
    priceAxisReserve = 62,
    volPanelTopRatio = 0.82,
    longPct = 50,
    shortPct = 50,
    similarCount = s.forecastBars ? 0 : 0,
    compareKo,
  } = params;

  const x1 = resolveTimeX(s.timeFrom);
  const boxEndT = s.timeBoxTo ?? s.timeTo;
  const x2raw = resolveTimeX(boxEndT);
  const yTop = priceToY(s.priceHigh);
  const yBot = priceToY(s.priceLow);
  if (!Number.isFinite(x1) || !Number.isFinite(x2raw) || yTop == null || yBot == null) return null;

  const boxTop = Math.min(yTop, yBot) - 5;
  const boxBot = Math.max(yTop, yBot) + 5;
  const x2 = Math.max(x1, x2raw);

  let lastX = lastBarTime != null ? resolveTimeX(lastBarTime) : x2;
  let prevX = prevBarTime != null ? resolveTimeX(prevBarTime) : lastX - 14;
  if (!Number.isFinite(lastX)) lastX = x2;
  if (!Number.isFinite(prevX)) prevX = lastX - 14;
  const barW = Math.max(8, lastX - prevX);

  /** 가격축 직전 고정 — 마지막 봉 위 세로선 방지 */
  const colW = 92;
  const colRight = chartWidth - priceAxisReserve - 4;
  const colLeft = Math.max(lastX + barW + 6, colRight - colW);
  const colCenter = (colLeft + colRight) / 2;

  const close = s.priceClose;
  const med = s.forecastPct ?? 0;
  const entryPrice =
    s.entryPrice ??
    (s.move.dir === 'long' ? s.priceLow : s.move.dir === 'short' ? s.priceHigh : close);
  const targetPrice =
    s.targetPrice ?? (close > 0 ? close * (1 + med / 100) : close);
  const entryY = priceToY(entryPrice) ?? priceToY(close) ?? boxBot;
  const targetY = priceToY(targetPrice) ?? entryY;

  const dir = dirOf(s);
  const beamLabel = s.beamKo && s.beamKo !== '관망' ? s.beamKo : dir === 'long' ? '롱빔' : dir === 'short' ? '숏빔' : '관망';
  const dirLabel = dir === 'short' ? '▼ 숏' : dir === 'long' ? '▲ 롱' : '◆ 관망';
  const pct = s.move.pctLabel ?? '—';
  const footerLine = `${dirLabel} · ${beamLabel} · ${pct}`;

  return {
    id: s.id,
    chartHeight,
    volPanelTop: chartHeight * volPanelTopRatio,
    priceAxisReserve,
    box: { x1: Math.min(x1, x2), x2: Math.max(x1, x2), yTop: boxTop, yBot: boxBot },
    anchorX: x2,
    colLeft,
    colRight,
    colCenter,
    entryY,
    targetY,
    color: s.move.color,
    dir,
    beamKo: s.beamKo ?? '관망',
    verdictKo: s.verdictKo ?? '횡보',
    pctLabel: pct,
    entryPriceLabel: `${s.move.entryKo} ${fmtPrice(entryPrice)}`,
    targetPriceLabel: `${fmtPrice(targetPrice)} (${pct})`,
    footerLine,
    longPct,
    shortPct,
    similarCount: similarCount || 0,
    forecastBars: s.forecastBars,
    forecastPct: s.forecastPct,
    compareKo,
  };
}

'use client';

import type { WhaleBeamRightOracleGeom } from '@/lib/whaleBeamRightOracleGeom';

type Props = {
  oracle: WhaleBeamRightOracleGeom | null;
};

function fmtPct(n: number | null | undefined): string {
  if (n == null || !Number.isFinite(n)) return '—';
  return `${n >= 0 ? '+' : ''}${n.toFixed(1)}%`;
}

/** 우측 여백 — DNA 비교·롱빔/숏빔 (세로 점선·캔들 겹침 없음) */
export function WhaleVolumeSegmentDrawLayer({ oracle }: Props) {
  if (!oracle) return null;

  const g = oracle;
  const h = g.chartHeight;
  const colW = Math.max(56, g.colRight - g.colLeft);
  const panelTop = Math.min(g.box.yTop, g.entryY, g.targetY) - 18;
  const panelBot = Math.max(g.box.yBot, g.entryY, g.targetY) + 52;
  const panelH = Math.min(g.volPanelTop - 8, panelBot) - Math.max(12, panelTop);

  const isLong = g.dir === 'long' || g.verdictKo === '상승' || g.beamKo === '롱빔';
  const isShort = g.dir === 'short' || g.verdictKo === '하락' || g.beamKo === '숏빔';
  const beamHead = isLong ? '▲ 롱빔' : isShort ? '▼ 숏빔' : '◆ 관망';
  const futureLine = `+${g.forecastBars}봉 ${fmtPct(g.forecastPct)} (참고)`;

  return (
    <svg className="whale-segment-draw-layer" width="100%" height={h} aria-hidden>
      {/* 횡보 구간 — 점선 박스만, 세로선 없음 */}
      <rect
        x={g.box.x1}
        y={g.box.yTop}
        width={Math.max(6, g.box.x2 - g.box.x1)}
        height={Math.max(6, g.box.yBot - g.box.yTop)}
        rx={3}
