  const futureLine = `+${d.forecastBars}봉 ${fmtPct(d.forecastPct)}${fmtBand(d.p25Pct, d.p75Pct)}`;

  let y = 14;
  const line = (text: string, cls: string, dy = 14) => {
    const cy = y;
