input.contents:
/**
 * 통합·분석 — 현재 지지 붕괴 시 하방 핵심 지지 zone + CHoCH/BOS 하방 시
 * 하락 깊이·지지 후 반등 목표를 세트(동일 색) zone·점선으로 표시 (조건부 참고).
 */
import type { AnalyzeResponse, Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import { normalizeChartTimeframe } from '@/lib/constants';
import type { MergedBounceScenario } from '@/lib/mergedAnalysisBounceTargets';
import type { MergedCriticalZone } from '@/lib/mergedAnalysisCriticalZones';
import type { MergedKeyZone } from '@/lib/mergedAnalysisKeyZones';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import {
  detectProjectedDownsideSupports,
  type ProjectedDownsideSupport,
} from '@/lib/mergedDeskProjectedDownsideSupports';
import {
  mergedDeskAnalysisZoneTimes,
  mergedWorkCandles,
  MERGED_ARES_ZONE_CAPTION_CLASS,
} from '@/lib/mergedAnalysisOverlayTimes';

export type DownsideBounceSet = {
  id: string;
  supportPrice: number;
  bounceT1: number;
  bounceTmax: number;
  labelKo: string;
  sourceKo: string;
  color: string;
};

const SET_PALETTE = [
  { stroke: '#22d3ee', fill: 'rgba(34,211,238,0.16)', tag: '①' },
  { stroke: '#60a5fa', fill: 'rgba(96,165,250,0.15)', tag: '②' },
  { stroke: '#a78bfa', fill: 'rgba(167,139,250,0.14)', tag: '③' },
  { stroke: '#fbbf24', fill: 'rgba(251,191,36,0.12)', tag: '④' },
] as const;

function fmtPx(p: number): string {
  const a = Math.abs(p);
  if (a >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (a >= 1) return p.toFixed(1);
  return p.toFixed(3);
}

function estimateAtr(candles: Candle[], endIdx: number, period = 14): number {
  const start = Math.max(1, endIdx - period + 1);
  let sum = 0;
  let n = 0;
  for (let i = start; i <= endIdx; i++) {
    const c = candles[i]!;
    const p = candles[i - 1]!.close;
    sum += Math.max(c.high - c.low, Math.abs(c.high - p), Math.abs(c.low - p));
    n++;
  }
  return n > 0 ? sum / n : Math.abs(candles[endIdx]?.close ?? 1) * 0.01;
}

function pickNearestDemand(
  keyZones: MergedKeyZone[],
  close: number,
  atr: number
): MergedKeyZone | null {
  return (
    keyZones
      .filter((z) => z.kind === 'demand' && z.price <= close + atr * 0.2)
      .sort((a, b) => Math.abs(close - a.price) - Math.abs(close - b.price))[0] ?? null
  );
}

function isBearishBreakContext(smc: MergedSmcLeadingContext | null | undefined): boolean {
  if (!smc?.active) return false;
  if (smc.legDirection === 'down') return true;
  const choch = smc.lastChoch;
  if (choch?.bias === 'bearish' && choch.tag === 'CHOCH') return true;
  if (choch?.bias === 'bearish' && choch.phase !== 'failed') return true;
  const recentBearBos = smc.marks
    .slice(-6)
    .some((m) => m.tag === 'BOS' && m.bias === 'bearish' && !m.developing);
  return recentBearBos && smc.bosCountInLeg >= 1;
}

function bounceTargetsFromSupport(
  supportPrice: number,
  referenceHigh: number,
  atr: number
): { t1: number; tmax: number } {
  const drop = Math.max(referenceHigh - supportPrice, atr * 1.2);
  const t1 = supportPrice + drop * 0.382;
  const tmax = Math.min(referenceHigh - atr * 0.08, supportPrice + drop * 0.618);
  return {
    t1: Math.max(supportPrice + atr * 0.15, t1),
    tmax: Math.max(t1 + atr * 0.2, tmax),
  };
}

function buildSetRow(
  support: ProjectedDownsideSupport,
  idx: number,
  referenceHigh: number,
  atr: number
): DownsideBounceSet {
  const pal = SET_PALETTE[Math.min(idx, SET_PALETTE.length - 1)]!;
  const { t1, tmax } = bounceTargetsFromSupport(support.price, referenceHigh, atr);
  return {
    id: support.id,
    supportPrice: support.price,
    bounceT1: t1,
    bounceTmax: tmax,
    labelKo: `${pal.tag} ${support.labelKo.replace(/^하방 핵심지지 · /, '')}`,
    sourceKo: support.sourceKo,
    color: pal.stroke,
  };
}

export type MergedDeskDownsideBouncePlanPack = {
  summaryKo: string;
  detailKo: string;
  bearBreak: boolean;
  sets: DownsideBounceSet[];
  overlays: OverlayItem[];
};

export function buildMergedDeskDownsideBouncePlanPack(params: {
  candles: Candle[];
  timeframe: string;
  keyZones?: MergedKeyZone[];
  criticalZones?: MergedCriticalZone[];
  bounceScenarios?: MergedBounceScenario[];
  smcLeading?: MergedSmcLeadingContext | null;
  analysis?: AnalyzeResponse | null;
  vrvp?: { poc?: number | null; vaLow?: number | null; vaHigh?: number | null } | null;
  whaleMemoryZones?: Array<{ price1: number; price2: number; confidence?: number }>;
}): MergedDeskDownsideBouncePlanPack {
  const tf = normalizeChartTimeframe(params.timeframe);
  const work = mergedWorkCandles(params.candles, tf);
  if (work.length < 24) {
    return { summaryKo: '', detailKo: '', bearBreak: false, sets: [], overlays: [] };
  }

  const close = work[work.length - 1]!.close;
  const lastT = Number(work[work.length - 1]!.time);
  const atr = estimateAtr(work, work.length - 1);
  const smc = params.smcLeading;
  const bearBreak = isBearishBreakContext(smc);
  const nearestDemand = pickNearestDemand(params.keyZones ?? [], close, atr);
  const supportAtRisk =
    nearestDemand != null && close <= nearestDemand.top + atr * 1.1 && close >= nearestDemand.bot - atr * 0.5;

  const supports = detectProjectedDownsideSupports({
    candles: params.candles,
    timeframe: params.timeframe,
    keyZones: params.keyZones,
    criticalZones: params.criticalZones,
    bounceScenarios: params.bounceScenarios,
    vrvp: params.vrvp,
    analysis: params.analysis,
    whaleMemoryZones: params.whaleMemoryZones,
  });

  if (!supports.length) {
    return {
      summaryKo: '하방 지지·반등 zone — 탐색 중',
      detailKo: '',
      bearBreak,
      sets: [],
      overlays: [],
    };
  }

  const cap = bearBreak || supportAtRisk ? 4 : 3;
  const picked = supports.slice(0, cap);
  const referenceHigh =
    smc?.bounceHint?.legHigh ??
    work.slice(-Math.min(80, work.length)).reduce((m, c) => Math.max(m, c.high), close);
  const sets = picked.map((s, i) => buildSetRow(s, i, referenceHigh, atr));

  const zoneCtx = {
    anchorTime: nearestDemand?.time1 ?? null,
    legHigh: referenceHigh,
    legLow: picked[picked.length - 1]?.price ?? close - atr * 4,
    direction: 'down' as const,
  };
  const { t1: zoneT1, t2: zoneT2 } = mergedDeskAnalysisZoneTimes(work, tf, zoneCtx);

  const overlays: OverlayItem[] = [];

  if (nearestDemand && (supportAtRisk || bearBreak)) {
    const pal = SET_PALETTE[0]!;
    overlays.push({
      id: 'merged-desk-downside-plan-current-support',
      kind: 'demandZone',
      label: `현재 지지 ${fmtPx(nearestDemand.price)}`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: zoneT1,
      time2: zoneT2,
      price1: nearestDemand.top,
      price2: nearestDemand.bot,
      confidence: 82,
      color: 'rgba(248,113,113,0.12)',
      category: 'scenario',
      zoneFillPreserve: true,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-current',
        MERGED_ARES_ZONE_CAPTION_CLASS,
      ].join(' '),
      lineLabelColor: '#f87171',
      labelTooltip: bearBreak
        ? 'CHoCH/BOS 하방 — 현재 지지 붕괴 시 아래 zone 참고 (조건부)'
        : '현재 지지 구간 — 이탈 시 하방 zone 참고 (조건부)',
    });
  }

  for (let i = 0; i < picked.length; i++) {
    const support = picked[i]!;
    const set = sets[i]!;
    const pal = SET_PALETTE[Math.min(i, SET_PALETTE.length - 1)]!;
    const setClass = `merged-desk-downside-plan-set-${i + 1}`;

    overlays.push({
      id: `merged-desk-downside-plan-zone-${i}-${Math.round(support.price)}`,
      kind: 'demandZone',
      label: `${pal.tag} 지지 ${fmtPx(support.price)}`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: zoneT1,
      time2: zoneT2,
      price1: support.top,
      price2: support.bot,
      confidence: Math.min(92, 70 + Math.round(support.score * 0.2)),
      color: pal.fill,
      category: 'scenario',
      zoneFillPreserve: true,
      lineDash: support.pureProjection ? '6 4' : undefined,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-zone',
        setClass,
        MERGED_ARES_ZONE_CAPTION_CLASS,
        support.pureProjection ? 'merged-desk-downside-plan-zone--proj' : 'merged-desk-downside-plan-zone--hist',
      ].join(' '),
      lineLabelColor: pal.stroke,
      labelBackgroundColor: `color-mix(in srgb, ${pal.stroke} 22%, rgba(15,23,42,0.92))`,
      labelTextColor: '#f8fafc',
      labelTooltip: `${set.labelKo} · ${set.sourceKo} · 반등 T1 ${fmtPx(set.bounceT1)} · Tmax ${fmtPx(set.bounceTmax)} (조건부 참고)`,
    });

    const connT1 = Math.max(zoneT1, lastT - atr * 0);
    overlays.push({
      id: `merged-desk-downside-plan-conn-t1-${i}-${Math.round(set.bounceT1)}`,
      kind: 'trendLine',
      label: '',
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 1,
      time1: connT1 as UTCTimestamp,
      time2: lastT as UTCTimestamp,
