import type { MergedCriticalZone } from '@/lib/mergedAnalysisCriticalZones';
import type { MergedKeyZone } from '@/lib/mergedAnalysisKeyZones';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import {
  detectProjectedDownsideSupports,
  type ProjectedDownsideSupport,
} from '@/lib/mergedDeskProjectedDownsideSupports';
import { mergedWorkCandles } from '@/lib/mergedAnalysisOverlayTimes';

export type DownsideBounceSet = {
  id: string;
  supportPrice: number;
  bounceT1: number;
  bounceTmax: number;
  labelKo: string;
  sourceKo: string;
  color: string;
};

const SET_PALETTE = [
  { stroke: '#22d3ee', fill: 'rgba(34,211,238,0.14)', path: 'rgba(34,211,238,0.07)', tag: '①' },
  { stroke: '#60a5fa', fill: 'rgba(96,165,250,0.13)', path: 'rgba(96,165,250,0.06)', tag: '②' },
  { stroke: '#a78bfa', fill: 'rgba(167,139,250,0.12)', path: 'rgba(167,139,250,0.06)', tag: '③' },
  { stroke: '#fbbf24', fill: 'rgba(251,191,36,0.11)', path: 'rgba(251,191,36,0.05)', tag: '④' },
] as const;

function fmtPx(p: number): string {
  const a = Math.abs(p);
  if (a >= 1000) return p.toLocaleString('en-US', { maximumFractionDigits: 0 });
  if (a >= 1) return p.toFixed(1);
  return p.toFixed(3);
}

function estimateAtr(candles: Candle[], endIdx: number, period = 14): number {
  const start = Math.max(1, endIdx - period + 1);
  let sum = 0;
  let n = 0;
  for (let i = start; i <= endIdx; i++) {
    const c = candles[i]!;
    const p = candles[i - 1]!.close;
    sum += Math.max(c.high - c.low, Math.abs(c.high - p), Math.abs(c.low - p));
    n++;
  }
  return n > 0 ? sum / n : Math.abs(candles[endIdx]?.close ?? 1) * 0.01;
}

function pickNearestDemand(
  keyZones: MergedKeyZone[],
  close: number,
  atr: number
): MergedKeyZone | null {
  return (
    keyZones
      .filter((z) => z.kind === 'demand' && z.price <= close + atr * 0.2)
      .sort((a, b) => Math.abs(close - a.price) - Math.abs(close - b.price))[0] ?? null
  );
}

function isBearishBreakContext(smc: MergedSmcLeadingContext | null | undefined): boolean {
  if (!smc?.active) return false;
  if (smc.legDirection === 'down') return true;
  const choch = smc.lastChoch;
  if (choch?.bias === 'bearish' && choch.tag === 'CHOCH') return true;
  if (choch?.bias === 'bearish' && choch.phase !== 'failed') return true;
  const recentBearBos = smc.marks
    .slice(-6)
    .some((m) => m.tag === 'BOS' && m.bias === 'bearish' && !m.developing);
  return recentBearBos && smc.bosCountInLeg >= 1;
}

function bounceTargetsFromSupport(
  supportPrice: number,
  referenceHigh: number,
  atr: number
): { t1: number; tmax: number } {
  const drop = Math.max(referenceHigh - supportPrice, atr * 1.2);
  const t1 = supportPrice + drop * 0.382;
  const tmax = Math.min(referenceHigh - atr * 0.08, supportPrice + drop * 0.618);
  return {
    t1: Math.max(supportPrice + atr * 0.15, t1),
    tmax: Math.max(t1 + atr * 0.2, tmax),
  };
}

function buildSetRow(
  support: ProjectedDownsideSupport,
  idx: number,
  referenceHigh: number,
  atr: number
): DownsideBounceSet {
  const pal = SET_PALETTE[Math.min(idx, SET_PALETTE.length - 1)]!;
  const { t1, tmax } = bounceTargetsFromSupport(support.price, referenceHigh, atr);
  return {
    id: support.id,
    supportPrice: support.price,
    bounceT1: t1,
    bounceTmax: tmax,
    labelKo: `${pal.tag} ${support.labelKo.replace(/^하방 핵심지지 · /, '')}`,
    sourceKo: support.sourceKo,
    color: pal.stroke,
  };
}

/** 과거 스윙 터치 시각 — 마지막 봉이 아닌 구조 앵커 */
function findHistoricalTouchTime(work: Candle[], price: number, atr: number): number {
  const tol = Math.max(atr * 0.55, Math.abs(price) * 0.0045);
  const n = work.length;
  const scanStart = Math.max(0, n - Math.min(n, 160));
  let bestIdx = -1;
  let bestScore = -Infinity;
  for (let i = scanStart; i < n - 3; i++) {
    const c = work[i]!;
    const touched = c.low <= price + tol && c.high >= price - tol;
    if (!touched) continue;
    const recency = i / n;
    const wick = Math.min(c.high - c.low, tol * 2);
    const score = recency * 0.65 + (1 - Math.abs(c.low - price) / Math.max(wick, 1e-9)) * 0.35;
    if (score > bestScore) {
      bestScore = score;
      bestIdx = i;
    }
  }
  if (bestIdx >= 0) return Number(work[bestIdx]!.time);
  let loIdx = scanStart;
  let loDiff = Infinity;
  for (let i = scanStart; i < n - 3; i++) {
    const d = Math.abs(work[i]!.low - price);
    if (d < loDiff) {
      loDiff = d;
      loIdx = i;
    }
  }
  return Number(work[loIdx]!.time);
}

function findLegHighTime(work: Candle[], legHigh: number): number {
  let idx = work.length - 1;
  let diff = Infinity;
  for (let i = Math.max(0, work.length - 120); i < work.length; i++) {
    const d = Math.abs(work[i]!.high - legHigh);
    if (d < diff) {
      diff = d;
      idx = i;
    }
  }
  return Number(work[idx]!.time);
}

function planHorizonTimes(
  work: Candle[],
  tf: string,
  breakTime: number | null,
  anchorTimes: number[]
): { t1: UTCTimestamp; t2: UTCTimestamp } {
  const tEnd = Number(work[work.length - 1]!.time);
  const candidates = [breakTime, ...anchorTimes].filter(
    (t): t is number => t != null && Number.isFinite(t) && t < tEnd
  );
  let tStart = candidates.length ? Math.min(...candidates) : Number(work[Math.max(0, work.length - 48)]!.time);
  const tfNorm = normalizeChartTimeframe(tf);
  const minSpan =
    tfNorm === '1w' || tfNorm === '1M'
      ? 86400 * 14
      : tfNorm === '1d'
        ? 86400 * 5
        : tfNorm === '4h'
          ? 86400 * 2
          : 86400;
  if (tEnd - tStart < minSpan) {
    tStart = tEnd - minSpan;
    const firstT = Number(work[0]!.time);
    if (tStart < firstT) tStart = firstT;
  }
  return { t1: tStart as UTCTimestamp, t2: tEnd as UTCTimestamp };
}

export type MergedDeskDownsideBouncePlanPack = {
  summaryKo: string;
  detailKo: string;
  bearBreak: boolean;
  sets: DownsideBounceSet[];
  overlays: OverlayItem[];
};

export function buildMergedDeskDownsideBouncePlanPack(params: {
  candles: Candle[];
  timeframe: string;
  keyZones?: MergedKeyZone[];
  criticalZones?: MergedCriticalZone[];
  bounceScenarios?: MergedBounceScenario[];
  smcLeading?: MergedSmcLeadingContext | null;
  analysis?: AnalyzeResponse | null;
  vrvp?: { poc?: number | null; vaLow?: number | null; vaHigh?: number | null } | null;
  whaleMemoryZones?: Array<{ price1: number; price2: number; confidence?: number }>;
}): MergedDeskDownsideBouncePlanPack {
  const tf = normalizeChartTimeframe(params.timeframe);
  const work = mergedWorkCandles(params.candles, tf);
  if (work.length < 24) {
    return { summaryKo: '', detailKo: '', bearBreak: false, sets: [], overlays: [] };
  }

  const close = work[work.length - 1]!.close;
  const lastT = Number(work[work.length - 1]!.time) as UTCTimestamp;
  const atr = estimateAtr(work, work.length - 1);
  const smc = params.smcLeading;
  const bearBreak = isBearishBreakContext(smc);
  const nearestDemand = pickNearestDemand(params.keyZones ?? [], close, atr);
  const supportAtRisk =
    nearestDemand != null && close <= nearestDemand.top + atr * 1.1 && close >= nearestDemand.bot - atr * 0.5;

  const supports = detectProjectedDownsideSupports({
    candles: params.candles,
    timeframe: params.timeframe,
    keyZones: params.keyZones,
    criticalZones: params.criticalZones,
    bounceScenarios: params.bounceScenarios,
    vrvp: params.vrvp,
    analysis: params.analysis,
    whaleMemoryZones: params.whaleMemoryZones,
  });

  if (!supports.length) {
    return {
      summaryKo: '하방 지지·반등 zone — 탐색 중',
      detailKo: '',
      bearBreak,
      sets: [],
      overlays: [],
    };
  }

  const cap = 3;
  const picked = supports.slice(0, cap);
  const referenceHigh =
    smc?.bounceHint?.legHigh ??
    work.slice(-Math.min(80, work.length)).reduce((m, c) => Math.max(m, c.high), close);
  const sets = picked.map((s, i) => buildSetRow(s, i, referenceHigh, atr));

  const breakTime =
    smc?.lastChoch?.time != null
      ? Number(smc.lastChoch.time)
      : bearBreak
        ? findLegHighTime(work, referenceHigh)
        : null;
  const anchorTimes = picked.map((s) => findHistoricalTouchTime(work, s.price, atr));
  const { t1: planT1, t2: planT2 } = planHorizonTimes(work, tf, breakTime, anchorTimes);

  const overlays: OverlayItem[] = [];

  if (nearestDemand && (supportAtRisk || bearBreak)) {
    const watchT1 = Math.max(
      planT1,
      Number(work[Math.max(0, work.length - Math.min(36, work.length))]!.time)
    ) as UTCTimestamp;
    overlays.push({
      id: 'merged-desk-downside-plan-current-support',
      kind: 'demandZone',
      label: `감시 ${fmtPx(nearestDemand.price)}`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: watchT1,
      time2: planT2,
      price1: nearestDemand.top,
      price2: nearestDemand.bot,
      confidence: 82,
      color: 'rgba(248,113,113,0.1)',
      category: 'scenario',
      zoneFillPreserve: true,
      zoneSpanOnly: true,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-current',
        'merged-desk-downside-plan-support',
      ].join(' '),
      lineLabelColor: '#f87171',
      labelTooltip: '현재 지지 — 붕괴 시 아래 shelf zone 참고 (조건부)',
    });
  }

  for (let i = 0; i < picked.length; i++) {
    const support = picked[i]!;
    const set = sets[i]!;
    const pal = SET_PALETTE[Math.min(i, SET_PALETTE.length - 1)]!;
    const setClass = `merged-desk-downside-plan-set-${i + 1}`;
    const anchorT = anchorTimes[i]! as UTCTimestamp;
    const shelfT1 = Math.min(planT1, anchorT) as UTCTimestamp;
    const compactLabel = `${pal.tag} ${fmtPx(support.price)} → ${fmtPx(set.bounceT1)}`;

    overlays.push({
      id: `merged-desk-downside-plan-zone-${i}-${Math.round(support.price)}`,
      kind: 'demandZone',
      label: compactLabel,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: shelfT1,
      time2: planT2,
      price1: support.top,
      price2: support.bot,
      confidence: Math.min(92, 70 + Math.round(support.score * 0.2)),
      color: pal.fill,
      category: 'scenario',
      zoneFillPreserve: true,
      zoneSpanOnly: true,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-support',
        'merged-desk-downside-plan-zone',
        setClass,
        support.pureProjection ? 'merged-desk-downside-plan-zone--proj' : 'merged-desk-downside-plan-zone--hist',
      ].join(' '),
      lineLabelColor: pal.stroke,
      labelBackgroundColor:
        i === 0
          ? 'rgba(8,78,99,0.88)'
          : i === 1
            ? 'rgba(30,58,138,0.88)'
            : 'rgba(76,29,149,0.88)',
      labelTextColor: '#f8fafc',
      labelTooltip: `${set.labelKo} · ${set.sourceKo} · Tmax ${fmtPx(set.bounceTmax)} (조건부)`,
    });

    const pathLo = Math.min(support.price, set.bounceT1, set.bounceTmax);
    const pathHi = Math.max(support.price, set.bounceT1, set.bounceTmax);
    const pathPad = Math.max(atr * 0.08, Math.abs(support.price) * 0.0015);
    overlays.push({
      id: `merged-desk-downside-plan-path-${i}`,
      kind: 'demandZone',
      label: '',
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: anchorT,
      time2: planT2,
      price1: pathHi + pathPad,
      price2: pathLo - pathPad,
      confidence: 68,
      color: pal.path,
      category: 'scenario',
      zoneFillPreserve: true,
      zoneSpanOnly: true,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-path',
        setClass,
      ].join(' '),
      labelTooltip: `${pal.tag} 지지 → 반등 경로 (조건부)`,
    });

    overlays.push({
      id: `merged-desk-downside-plan-conn-${i}`,
      kind: 'trendLine',
      label: '',
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 1,
      time1: anchorT,
      time2: lastT,
      price1: support.price,
      price2: set.bounceT1,
      confidence: 74,
      color: pal.stroke,
      category: 'scenario',
      lineDash: '6 5',
      lineStrokeWidth: 1.35,
      noProject: true,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-connector',
        setClass,
      ].join(' '),
      labelTooltip: `${compactLabel} (조건부)`,
    });

    overlays.push({
      id: `merged-desk-downside-plan-bounce-t1-${i}`,
      kind: 'keyLevel',
      label: '',
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: shelfT1,
      time2: planT2,
      price1: set.bounceT1,
      price2: set.bounceT1,
      confidence: 72,
      color: pal.stroke,
      category: 'scenario',
      lineDash: '5 6',
      lineStrokeWidth: 1.1,
      noProject: true,
      overlayZoneExtraClass: [
        'merged-desk-downside-plan',
        'merged-desk-downside-plan-bounce',
        'merged-desk-downside-plan-bounce-t1',
        setClass,
      ].join(' '),
      labelTooltip: `${pal.tag} 반등 T1 ${fmtPx(set.bounceT1)}`,
    });

    if (Math.abs(set.bounceTmax - set.bounceT1) > atr * 0.25) {
      overlays.push({
        id: `merged-desk-downside-plan-bounce-tmax-${i}`,
        kind: 'keyLevel',
        label: '',
        x1: 0,
        y1: 0,
        x2: 1,
        y2: 0,
        time1: shelfT1,
        time2: planT2,
        price1: set.bounceTmax,
        price2: set.bounceTmax,
        confidence: 76,
        color: pal.stroke,
        category: 'scenario',
        lineDash: '2 7',
        lineStrokeWidth: 0.95,
        noProject: true,
        overlayZoneExtraClass: [
          'merged-desk-downside-plan',
          'merged-desk-downside-plan-bounce',
          'merged-desk-downside-plan-bounce-tmax',
          setClass,
        ].join(' '),
        labelTooltip: `${pal.tag} 반등 Tmax ${fmtPx(set.bounceTmax)}`,
      });
    }
  }

  const top = sets[0];
  const deep = sets[sets.length - 1];
  const summaryKo = bearBreak
    ? `CHoCH/BOS↓ · ${top ? fmtPx(top.supportPrice) : '—'} → ${deep ? fmtPx(deep.supportPrice) : '—'} · 반등 shelf`
    : supportAtRisk
      ? `지지 위험 · ${sets.map((s) => fmtPx(s.supportPrice)).join(' → ')}`
      : `하방 shelf ${sets.map((s) => fmtPx(s.supportPrice)).join(' → ')}`;

  const detailKo = sets
    .map(
      (s, i) =>
        `${SET_PALETTE[Math.min(i, SET_PALETTE.length - 1)]!.tag} ${fmtPx(s.supportPrice)} → T1 ${fmtPx(s.bounceT1)}`
    )
    .join(' · ');

  return { summaryKo, detailKo, bearBreak, sets, overlays };
}

