  absorb: { color: '#a78bfa', fill: 'rgba(167,139,250,0.18)', label: '흡수·함정' },
  breakout_long: { color: '#4ade80', fill: 'rgba(74,222,128,0.24)', label: '▲ 돌파·매수' },
  breakout_short: { color: '#fb7185', fill: 'rgba(251,113,133,0.22)', label: '▼ 이탈·매도' },
  neutral: { color: '#64748b', fill: 'rgba(100,116,139,0.12)', label: '혼조' },
};

function barKind(
  c: Candle,
  buyPct: number,
  rvol: number,
  netBarPct: number
): VolumeAiZoneKind {
  const absNet = Math.abs(netBarPct);
  if (rvol >= 2.2 && absNet < 0.35) return 'absorb';
  if (buyPct >= 0.58 && netBarPct > 0.15 && rvol >= 1.35) return 'breakout_long';
  if (buyPct <= 0.42 && netBarPct < -0.15 && rvol >= 1.35) return 'breakout_short';
  if (buyPct >= 0.56) return 'accum';
  if (buyPct <= 0.44) return 'dist';
  return 'neutral';
}

function mergeKind(a: VolumeAiZoneKind, b: VolumeAiZoneKind): VolumeAiZoneKind {
  if (a === b) return a;
  if (a === 'neutral') return b;
  if (b === 'neutral') return a;
  if ((a === 'accum' && b === 'breakout_long') || (b === 'accum' && a === 'breakout_long')) return 'breakout_long';
  if ((a === 'dist' && b === 'breakout_short') || (b === 'dist' && a === 'breakout_short')) return 'breakout_short';
  if (a === 'absorb' || b === 'absorb') return 'absorb';
  if ((a === 'accum' && b === 'dist') || (a === 'dist' && b === 'accum')) return 'absorb';
  return a;
}

function signalForZone(z: Omit<VolumeAiZone, 'signal'>): VolumeAiSignal | null {
  const s = z.strength;
  if (z.kind === 'breakout_long' && s >= 0.42) {
    return {
      id: `${z.id}-sig`,
      time: z.timeTo,
      idx: z.toIdx,
      dir: 'long',
      tagKo: 'AI·BUY',
      color: '#4ade80',
      score: s,
    };
  }
  if (z.kind === 'breakout_short' && s >= 0.42) {
    return {
      id: `${z.id}-sig`,
      time: z.timeTo,
      idx: z.toIdx,
      dir: 'short',
      tagKo: 'AI·SELL',
      color: '#fb7185',
      score: s,
    };
  }
  if (z.kind === 'absorb' && s >= 0.38 && z.avgRvol >= 1.8) {
    return {
      id: `${z.id}-sig`,
      time: z.timeTo,
      idx: z.toIdx,
      dir: 'trap',
      tagKo: 'TRAP',
      color: '#facc15',
      score: s,
    };
  }
  if (z.kind === 'accum' && z.bars >= 4 && s >= 0.35) {
    return {
      id: `${z.id}-sig`,
      time: z.timeTo,
      idx: z.toIdx,
      dir: 'watch',
      tagKo: 'B·존',
      color: '#22d3ee',
      score: s,
    };
  }
  if (z.kind === 'dist' && z.bars >= 4 && s >= 0.35) {
    return {
      id: `${z.id}-sig`,
      time: z.timeTo,
      idx: z.toIdx,
      dir: 'watch',
      tagKo: 'S·존',
      color: '#f97316',
      score: s,
    };
  }
  return null;
}

export function buildVolumeAiZonePack(candles: Candle[], timeframe?: string): VolumeAiZonePack {
  const rows = sanitizeChartCandlesForSeries(candles, timeframe);
  const n = rows.length;
  if (n < 12) {
    return { zones: [], signals: [], liveZone: null, headlineKo: '거래량 AI — 데이터 부족' };
  }

  const rvolPeriod = 20;
  const barMeta: Array<{
    kind: VolumeAiZoneKind;
    buyPct: number;
    sellPct: number;
    rvol: number;
    netPct: number;
    vol: number;
  }> = [];

  for (let i = 0; i < n; i++) {
    const c = rows[i]!;
    const split = estimateBarBuySell(c);
    const vol = Math.max(0, c.volume || 0);
    const sma = i >= rvolPeriod - 1 ? smaTotalVolumeAt(rows, i, rvolPeriod) : vol;
    const rvol = sma > 0 ? vol / sma : 1;
    const o = c.open;
    const netBarPct = o > 0 ? ((c.close - o) / o) * 100 : 0;
    barMeta.push({
      kind: barKind(c, split.buyPct, rvol, netBarPct),
      buyPct: split.buyPct,
      sellPct: split.sellPct,
      rvol,
      netPct: netBarPct,
      vol,
    });
  }

  const rawZones: VolumeAiZone[] = [];
  let i = Math.max(0, n - 220);
  let zi = 0;
  while (i < n) {
    let kind = barMeta[i]!.kind;
    if (kind === 'neutral') {
      i++;
      continue;
    }
    const start = i;
    let buySum = 0;
    let sellSum = 0;
    let rvolSum = 0;
    let volSum = 0;
    let netSum = 0;
    while (i < n) {
      const m = barMeta[i]!;
      const nextKind = mergeKind(kind, m.kind);
      if (i > start && m.kind === 'neutral' && kind !== 'neutral') break;
      if (i > start && nextKind !== kind && m.kind !== 'neutral') break;
      kind = nextKind;
      buySum += m.buyPct;
      sellSum += m.sellPct;
      rvolSum += m.rvol;
      volSum += m.vol;
      netSum += m.netPct;
      i++;
      if (i - start >= 14) break;
    }
    const bars = i - start;
    if (bars < 2) continue;
    const buyPct = buySum / bars;
    const sellPct = sellSum / bars;
    const avgRvol = rvolSum / bars;
    const netPct = netSum / bars;
    const edge = Math.abs(buyPct - sellPct);
    const strength = Math.min(1, edge * 1.8 + Math.min(1.2, avgRvol - 1) * 0.35);
    if (strength < 0.22 && kind !== 'breakout_long' && kind !== 'breakout_short') continue;

    const st = ZONE_STYLE[kind];
    const fromIdx = start;
    const toIdx = i - 1;
    const zBase = {
      id: `vol-ai-zone-${zi++}`,
      kind,
      timeFrom: Number(rows[fromIdx]!.time),
      timeTo: Number(rows[toIdx]!.time),
      fromIdx,
      toIdx,
      bars,
      buyPct,
      sellPct,
      avgRvol,
      netPct,
      strength,
      labelKo: st.label,
      detailKo: `${st.label} · B${Math.round(buyPct * 100)}% · RVOL${avgRvol.toFixed(1)}× · ${bars}봉`,
      color: st.color,
      fill: st.fill,
    };
    const signal = signalForZone(zBase);
    rawZones.push({ ...zBase, signal });
  }

  const zones = rawZones.slice(-10);
  const signals = zones.map((z) => z.signal).filter(Boolean) as VolumeAiSignal[];
  const liveZone = zones.find((z) => z.toIdx >= n - 2) ?? zones[zones.length - 1] ?? null;

  let headlineKo = '거래량 AI zone — 혼조';
  if (liveZone) {
    headlineKo = `${liveZone.labelKo} · ${liveZone.detailKo} (조건부)`;
  }

  return { zones, signals, liveZone, headlineKo };
}

export function buildVolumeAiZoneMarkers(
  candles: Candle[],
  pack: VolumeAiZonePack,
  maxMarks = 16
): VolumePanelMarker[] {
  if (!pack.signals.length) return [];
  const rows = sanitizeChartCandlesForSeries(candles);
  const out: VolumePanelMarker[] = [];
  const picked = [...pack.signals].sort((a, b) => b.score - a.score).slice(0, maxMarks);
  for (const s of picked) {
    const c = rows[s.idx];
    if (!c) continue;
    out.push({
      time: c.time as UTCTimestamp,
      position: 'aboveBar',
      shape: 'square',
      color: s.color,
      text: s.tagKo,
      size: s.dir === 'long' || s.dir === 'short' ? 2 : 1,
    });
  }
  return out.sort((a, b) => Number(a.time) - Number(b.time));
}

export type VolumeAiZoneScreenGeom = {
  id: string;
  x1: number;
  x2: number;
  yTop: number;
  yBot: number;
  labelKo: string;
  detailKo: string;
  color: string;
  fill: string;
  kind: VolumeAiZoneKind;
  isLive: boolean;
  signalTag?: string;
};

export function projectVolumeAiZonesToScreen(params: {
  pack: VolumeAiZonePack;
  candles: Candle[];
  resolveTimeX: (t: number) => number;
  chartHeight: number;
  volPanelTopRatio?: number;
  maxVolLookback?: number;
}): VolumeAiZoneScreenGeom[] {
  const {
    pack,
    candles,
    resolveTimeX,
    chartHeight,
    volPanelTopRatio = 0.82,
    maxVolLookback = 120,
  } = params;
  const rows = sanitizeChartCandlesForSeries(candles);
  if (!rows.length || !pack.zones.length) return [];

  const volTop = chartHeight * volPanelTopRatio;
  const volBot = chartHeight - 4;
  const volH = Math.max(24, volBot - volTop);
  const n = rows.length;
  const from = Math.max(0, n - maxVolLookback);
  let maxVol = 1;
  for (let i = from; i < n; i++) {
    maxVol = Math.max(maxVol, Math.max(0, rows[i]!.volume || 0));
  }

  const lastIdx = n - 1;
  return pack.zones
    .map((z) => {
      const x1raw = resolveTimeX(z.timeFrom);
      const x2raw = resolveTimeX(z.timeTo);
      if (!Number.isFinite(x1raw) || !Number.isFinite(x2raw)) return null;

      let segMax = 0;
      for (let i = z.fromIdx; i <= z.toIdx && i < n; i++) {
        segMax = Math.max(segMax, Math.max(0, rows[i]!.volume || 0));
      }
      const h = Math.max(10, (segMax / maxVol) * (volH - 6));
      const yBot = volBot;
      const yTop = volBot - h;

      return {
        id: z.id,
        x1: Math.min(x1raw, x2raw),
        x2: Math.max(x1raw, x2raw) + 6,
        yTop,
        yBot,
        labelKo: z.labelKo,
        detailKo: z.detailKo,
        color: z.color,
        fill: z.fill,
        kind: z.kind,
        isLive: z.toIdx >= lastIdx - 1,
        signalTag: z.signal?.tagKo,
      };
    })
    .filter(Boolean) as VolumeAiZoneScreenGeom[];
}

