'use client';

import type { VolumeAiZoneScreenGeom } from '@/lib/volumeAiZoneEngine';

type Props = {
  zones: VolumeAiZoneScreenGeom[];
  headlineKo?: string;
};

/** Bitget Vol — 거래량 패널 하단 가로 shelf zone (세로선·텍스트 스택 없음) */
export function VolumeAiZoneDrawLayer({ zones }: Props) {
  if (!zones.length) return null;

  const live = zones.filter((z) => z.isLive);
  const past = zones.filter((z) => !z.isLive).slice(-5);
  const draw = [...past, ...live.slice(-1)];

  return (
    <svg className="volume-ai-zone-draw-layer" width="100%" height="100%" aria-hidden>
      {draw.map((z) => {
        const w = Math.max(18, z.x2 - z.x1);
        const h = Math.max(6, z.yBot - z.yTop);
        const cx = z.x1 + w / 2;
        const showLabel = w >= 36 && z.labelKo;
        return (
          <g
            key={z.id}
            className={`volume-ai-zone volume-ai-zone--${z.kind}${z.isLive ? ' volume-ai-zone--live' : ''}`}
          >
            <rect
              x={z.x1}
              y={z.yTop}
              width={w}
              height={h}
              rx={2}
              fill={z.fill}
              stroke={z.color}
              strokeWidth={z.isLive ? 1.2 : 0.75}
              strokeDasharray={z.kind === 'absorb' ? '3 2' : undefined}
              opacity={z.isLive ? 0.92 : 0.62}
            />
            {z.isLive && (
              <line
                x1={z.x1}
                y1={z.yTop}
                x2={z.x2}
                y2={z.yTop}
                className="volume-ai-zone__lip"
                stroke={z.color}
                strokeWidth={1.4}
                strokeLinecap="round"
              />
            )}
            {showLabel && (
              <text x={cx} y={z.yTop + h / 2 + 3} textAnchor="middle" className="volume-ai-zone__label">
                {z.labelKo}
              </text>
            )}
          </g>
        );
      })}
    </svg>
  );
}

