      zones: [],
      signals: [],
      volPanelTop: chartH * volPanelTopRatio,
      volPanelBot: chartH - 4,
      legendKo: pack.headlineKo,
    };
  }

  const volPanelTop = chartH * volPanelTopRatio;
  const volPanelBot = chartH - 4;
  const legendH = 15;
  const zoneTop = volPanelTop + 3;
  const zoneBot = volPanelBot - legendH - 2;
  const n = rows.length;
  const lastIdx = n - 1;
  const prevBar = rows.length >= 2 ? rows[lastIdx - 1]! : null;
  const lastX = resolveTimeX(Number(rows[lastIdx]!.time));
  const prevX = prevBar ? resolveTimeX(Number(prevBar.time)) : null;
  const estBarW =
    prevX != null && Number.isFinite(lastX) && Number.isFinite(prevX)
      ? Math.max(4, Math.abs(lastX - prevX))
      : 8;
  const MIN_ZONE_PX = Math.max(estBarW * 1.8, 14);

  const zones = pack.zones
    .map((z) => {
      const x1raw = resolveTimeX(z.timeFrom);
      const x2raw = resolveTimeX(z.timeTo);
      if (!Number.isFinite(x1raw) || !Number.isFinite(x2raw)) return null;

      let x1 = Math.min(x1raw, x2raw);
      let x2 = Math.max(x1raw, x2raw);
      if (x2 - x1 < MIN_ZONE_PX) {
        const cx = (x1 + x2) / 2;
        x1 = cx - MIN_ZONE_PX / 2;
        x2 = cx + MIN_ZONE_PX / 2;
