                ? '매도·분산'
                : z.kind === 'absorb'
                  ? '흡수·함정'
                  : z.labelKo;

      return {
        id: z.id,
        x1,
        x2,
        yTop: zoneTop,
        yBot: zoneBot,
        labelKo: shortLabel,
        detailKo: z.detailKo,
        color: z.color,
        fill: z.fill,
        kind: z.kind,
        isLive: z.toIdx >= lastIdx - 1,
      };
    })
    .filter(Boolean) as VolumeAiZoneScreenGeom[];

  const signalY = zoneTop + 7;
  const signals: VolumeAiSignalScreenGeom[] = [];
  for (const s of pack.signals.slice(-8)) {
    const x = resolveTimeX(Number(rows[s.idx]?.time ?? s.time));
    if (!Number.isFinite(x)) continue;
    signals.push({ id: s.id, x, y: signalY, dir: s.dir, color: s.color });
  }

  return {
    zones,
    signals,
    volPanelTop,
    volPanelBot,
    legendKo: pack.liveZone
      ? `${pack.liveZone.labelKo} · B${Math.round(pack.liveZone.buyPct * 100)}% · RVOL ${pack.liveZone.avgRvol.toFixed(1)}× · ${pack.liveZone.bars}봉 (조건부)`
      : pack.headlineKo,
  };
}

