'use client';

import type {
  VolumeAiSignalScreenGeom,
  VolumeAiZoneScreenGeom,
} from '@/lib/volumeAiZoneEngine';

type Props = {
  zones: VolumeAiZoneScreenGeom[];
  signals?: VolumeAiSignalScreenGeom[];
  legendKo?: string;
  volPanelTop: number;
  volPanelBot: number;
};

function signalShape(s: VolumeAiSignalScreenGeom) {
  const r = 4;
  if (s.dir === 'long') {
    return (
      <polygon
        points={`${s.x},${s.y - r} ${s.x - r},${s.y + r * 0.6} ${s.x + r},${s.y + r * 0.6}`}
        fill={s.color}
        className="volume-ai-zone__sig"
      />
    );
  }
  if (s.dir === 'short') {
    return (
      <polygon
        points={`${s.x},${s.y + r} ${s.x - r},${s.y - r * 0.6} ${s.x + r},${s.y - r * 0.6}`}
        fill={s.color}
        className="volume-ai-zone__sig"
      />
    );
  }
  return <circle cx={s.x} cy={s.y} r={3.2} fill={s.color} className="volume-ai-zone__sig" />;
}

/** Bitget Vol — 거래량 패널 배경 zone · 상단 시그널 · 하단 범례 (가격 차트 세로선 없음) */
export function VolumeAiZoneDrawLayer({
  zones,
  signals = [],
  legendKo,
  volPanelTop,
  volPanelBot,
}: Props) {
  if (!zones.length && !legendKo) return null;

  const past = zones.filter((z) => !z.isLive).slice(-6);
  const live = zones.filter((z) => z.isLive).slice(-1);
  const draw = [...past, ...live];
  const legendY = volPanelBot - 13;
  const legendText = legendKo && legendKo.length > 88 ? `${legendKo.slice(0, 88)}…` : legendKo;

  return (
    <svg className="volume-ai-zone-draw-layer" width="100%" height="100%" aria-hidden>
      <defs>
        <clipPath id="vol-ai-panel-clip">
          <rect x={0} y={volPanelTop} width="100%" height={Math.max(20, volPanelBot - volPanelTop)} />
        </clipPath>
      </defs>
      <g clipPath="url(#vol-ai-panel-clip)">
        {draw.map((z) => {
          const w = Math.max(12, z.x2 - z.x1);
          const h = Math.max(8, z.yBot - z.yTop);
          const cx = z.x1 + w / 2;
          const showLabel = w >= 52 && z.labelKo;
          return (
            <g
              key={z.id}
              className={`volume-ai-zone volume-ai-zone--${z.kind}${z.isLive ? ' volume-ai-zone--live' : ''}`}
            >
              <rect
                x={z.x1}
                y={z.yTop}
                width={w}
                height={h}
                rx={2}
                fill={z.fill}
                stroke={z.color}
                strokeWidth={z.isLive ? 1.1 : 0.6}
                strokeDasharray={z.kind === 'absorb' ? '4 3' : undefined}
                opacity={z.isLive ? 0.38 : 0.22}
              />
              <line
                x1={z.x1}
                y1={z.yTop}
                x2={z.x2}
                y2={z.yTop}
                stroke={z.color}
                strokeWidth={z.isLive ? 1.6 : 0.9}
                strokeLinecap="round"
                opacity={z.isLive ? 0.85 : 0.45}
              />
              {showLabel && (
                <text x={cx} y={z.yTop + 11} textAnchor="middle" className="volume-ai-zone__label">
                  {z.labelKo}
                </text>
              )}
            </g>
          );
        })}
        {signals.map((s) => (
          <g key={s.id}>{signalShape(s)}</g>
        ))}
      </g>
      {legendText && (
        <g className="volume-ai-zone__legend">
          <rect
            x={6}
            y={legendY - 1}
            width={Math.min(420, 420)}
            height={13}
            rx={3}
            className="volume-ai-zone__legend-bg"
          />
          <text x={10} y={legendY + 8} className="volume-ai-zone__legend-txt">
            VOL AI · {legendText}
          </text>
        </g>
      )}
    </svg>
  );
}

