input.contents:
/**
 * Bitget Vol — 거래량 패널 롱 / 롱익절 / 숏 구간 (캔들·거래량 시간 정렬)
 */
import type { UTCTimestamp } from 'lightweight-charts';
import type { Candle } from '@/types';
import { estimateBarBuySell } from '@/lib/volumeDirectionStats';
import { sanitizeChartCandlesForSeries, smaTotalVolumeAt } from '@/lib/volumeHistogramIntelligence';

/** 롱 매수우세 · 롱익절 분산 · 숏 매도우세 */
export type VolumeAiZoneKind = 'long' | 'long_tp' | 'short' | 'neutral';

export type VolumeAiZone = {
  id: string;
  kind: VolumeAiZoneKind;
  timeFrom: number;
  timeTo: number;
  fromIdx: number;
  toIdx: number;
  bars: number;
  buyPct: number;
  sellPct: number;
  avgRvol: number;
  netPct: number;
  strength: number;
  labelKo: string;
  detailKo: string;
  color: string;
  fill: string;
};

export type VolumeAiZonePack = {
  zones: VolumeAiZone[];
  liveZone: VolumeAiZone | null;
  headlineKo: string;
};

const ZONE_STYLE: Record<
  Exclude<VolumeAiZoneKind, 'neutral'>,
  { color: string; fill: string; label: string }
> = {
  long: { color: '#22c55e', fill: 'rgba(34,197,94,0.32)', label: '롱' },
  long_tp: { color: '#fbbf24', fill: 'rgba(251,191,36,0.34)', label: '롱익절' },
  short: { color: '#ef4444', fill: 'rgba(239,68,68,0.32)', label: '숏' },
};

function regimeBar(
  buyPct: number,
  sellPct: number,
  rvol: number,
  netBarPct: number
): VolumeAiZoneKind {
  const hot = rvol >= 1.2;
  if (hot && sellPct >= 0.52 && netBarPct > 0.05) return 'long_tp';
  if (hot && sellPct >= 0.54 && netBarPct >= -0.15 && netBarPct <= 0.12) return 'long_tp';
  if (buyPct >= 0.54 && (netBarPct >= -0.08 || hot)) return 'long';
  if (sellPct >= 0.54 && (netBarPct <= 0.08 || hot)) return 'short';
  return 'neutral';
}

export function buildVolumeAiZonePack(candles: Candle[], timeframe?: string): VolumeAiZonePack {
  const rows = sanitizeChartCandlesForSeries(candles, timeframe);
  const n = rows.length;
  if (n < 8) {
    return { zones: [], liveZone: null, headlineKo: '' };
  }

  const rvolPeriod = 20;
  const barMeta: Array<{
    kind: VolumeAiZoneKind;
    buyPct: number;
    sellPct: number;
    rvol: number;
    netPct: number;
  }> = [];

  for (let i = 0; i < n; i++) {
    const c = rows[i]!;
    const split = estimateBarBuySell(c);
    const vol = Math.max(0, c.volume || 0);
    const sma = i >= rvolPeriod - 1 ? smaTotalVolumeAt(rows, i, rvolPeriod) : vol;
    const rvol = sma > 0 ? vol / sma : 1;
    const o = c.open;
    const netBarPct = o > 0 ? ((c.close - o) / o) * 100 : 0;
    barMeta.push({
      kind: regimeBar(split.buyPct, split.sellPct, rvol, netBarPct),
      buyPct: split.buyPct,
      sellPct: split.sellPct,
      rvol,
      netPct: netBarPct,
    });
  }

  const rawZones: VolumeAiZone[] = [];
  let i = Math.max(0, n - 180);
  let zi = 0;

  while (i < n) {
    let kind = barMeta[i]!.kind;
    if (kind === 'neutral') {
      i++;
      continue;
    }
    const start = i;
    let buySum = 0;
    let sellSum = 0;
    let rvolSum = 0;
    let netSum = 0;
    while (i < n) {
      const m = barMeta[i]!;
      if (i > start && m.kind !== kind) break;
      if (m.kind === 'neutral' && i > start) break;
      buySum += m.buyPct;
      sellSum += m.sellPct;
      rvolSum += m.rvol;
      netSum += m.netPct;
      i++;
      if (i - start >= 18) break;
    }
    const bars = i - start;
    const buyPct = buySum / bars;
    const sellPct = sellSum / bars;
    const avgRvol = rvolSum / bars;
    const netPct = netSum / bars;
    const edge = Math.abs(buyPct - sellPct);
    const strength = Math.min(1, edge * 2 + Math.min(1, avgRvol - 1) * 0.4);
    const minBars = avgRvol >= 1.35 ? 1 : 2;
    if (bars < minBars || strength < 0.14) continue;

    const st = ZONE_STYLE[kind as Exclude<VolumeAiZoneKind, 'neutral'>];
    const fromIdx = start;
    const toIdx = i - 1;
    rawZones.push({
      id: `vol-regime-${zi++}`,
      kind,
      timeFrom: Number(rows[fromIdx]!.time),
      timeTo: Number(rows[toIdx]!.time),
      fromIdx,
      toIdx,
      bars,
      buyPct,
      sellPct,
      avgRvol,
      netPct,
      strength,
      labelKo: st.label,
      detailKo: `${st.label} · B${Math.round(buyPct * 100)} S${Math.round(sellPct * 100)} · RVOL${avgRvol.toFixed(1)}×`,
      color: st.color,
      fill: st.fill,
    });
  }

  const zones = rawZones.slice(-12);
  const liveZone = zones.find((z) => z.toIdx >= n - 1) ?? null;
  const headlineKo = liveZone ? liveZone.labelKo : '';

  return { zones, liveZone, headlineKo };
}

export type VolumeAiZoneScreenGeom = {
  id: string;
  x1: number;
  x2: number;
  yTop: number;
  yBot: number;
  labelKo: string;
  color: string;
  fill: string;
  kind: VolumeAiZoneKind;
  isLive: boolean;
};

export type VolumeAiZoneScreenPack = {
  zones: VolumeAiZoneScreenGeom[];
  volPanelTop: number;
  volPanelBot: number;
  liveLabel: string;
};

export function projectVolumeAiZonesToScreen(params: {
  pack: VolumeAiZonePack;
  candles: Candle[];
  resolveTimeX: (t: number) => number;
  resolveBarSpanX: (fromIdx: number, toIdx: number) => { x1: number; x2: number } | null;
  chartHeight: number;
  volPanelTopRatio?: number;
}): VolumeAiZoneScreenPack {
  const {
    pack,
    candles,
    resolveBarSpanX,
    chartHeight: chartH,
    volPanelTopRatio = 0.82,
  } = params;

  const volPanelTop = chartH * volPanelTopRatio;
  const volPanelBot = chartH - 2;
  const zoneTop = volPanelTop + 2;
  const zoneBot = volPanelBot - 16;

  const rows = sanitizeChartCandlesForSeries(candles);
  const lastIdx = rows.length - 1;

  const zones = pack.zones
    .map((z) => {
      const span = resolveBarSpanX(z.fromIdx, z.toIdx);
      if (!span || span.x2 - span.x1 < 4) return null;
      return {
        id: z.id,
        x1: span.x1,
        x2: span.x2,
        yTop: zoneTop,
        yBot: zoneBot,
        labelKo: z.labelKo,
        color: z.color,
        fill: z.fill,
        kind: z.kind,
        isLive: z.toIdx >= lastIdx - 0,
      };
    })
    .filter(Boolean) as VolumeAiZoneScreenGeom[];

  return {
    zones,
    volPanelTop,
    volPanelBot,
    liveLabel: pack.liveZone?.labelKo ?? '',
  };
}

/** @deprecated markers unused — zones only */
export function buildVolumeAiZoneMarkers(): never[] {
  return [];
}

'use client';

import type { VolumeAiZoneScreenGeom } from '@/lib/volumeAiZoneEngine';

type Props = {
  zones: VolumeAiZoneScreenGeom[];
  volPanelTop: number;
  volPanelBot: number;
  liveLabel?: string;
};

const LEGEND = [
  { kind: 'long', label: '롱', color: '#22c55e' },
  { kind: 'long_tp', label: '롱익절', color: '#fbbf24' },
  { kind: 'short', label: '숏', color: '#ef4444' },
] as const;

/** Bitget Vol — 거래량 패널 롱/롱익절/숏 구간 (캔들 폭에 맞춤) */
export function VolumeAiZoneDrawLayer({ zones, volPanelTop, volPanelBot, liveLabel }: Props) {
  if (!zones.length) return null;

  const legendY = volPanelBot - 11;

  return (
    <svg className="volume-ai-zone-draw-layer" width="100%" height="100%" aria-hidden>
      <defs>
        <clipPath id="vol-regime-panel-clip">
          <rect x={0} y={volPanelTop} width="100%" height={Math.max(24, volPanelBot - volPanelTop)} />
        </clipPath>
      </defs>
      <g clipPath="url(#vol-regime-panel-clip)">
        {zones.map((z) => {
          const w = Math.max(8, z.x2 - z.x1);
          const h = Math.max(10, z.yBot - z.yTop);
          const cx = z.x1 + w / 2;
          const showLabel = w >= 22;
          return (
            <g
              key={z.id}
              className={`volume-ai-zone volume-ai-zone--${z.kind}${z.isLive ? ' volume-ai-zone--live' : ''}`}
            >
              <rect
                x={z.x1}
                y={z.yTop}
                width={w}
                height={h}
                fill={z.fill}
                stroke={z.color}
                strokeWidth={z.isLive ? 1.2 : 0.7}
                opacity={z.isLive ? 0.55 : 0.38}
              />
              {showLabel && (
                <text x={cx} y={z.yTop + h / 2 + 4} textAnchor="middle" className="volume-ai-zone__tag">
                  {z.labelKo}
                </text>
              )}
            </g>
          );
        })}
      </g>
      <g className="volume-ai-zone__legend-row">
        {LEGEND.map((item, i) => (
          <g key={item.kind} transform={`translate(${8 + i * 52}, ${legendY})`}>
            <rect x={0} y={0} width={8} height={8} rx={1} fill={item.color} opacity={0.9} />
            <text x={11} y={7} className="volume-ai-zone__legend-chip">
              {item.label}
            </text>
          </g>
        ))}
        {liveLabel && (
          <text x={170} y={legendY + 7} className="volume-ai-zone__legend-live">
            현재 · {liveLabel}
          </text>
        )}
      </g>
    </svg>
  );
}

