/**
 * Bitget Vol — 고점·저점 거래량 + 상승/하락 구간 (캔들 스윙 정렬)
 */
import type { Candle } from '@/types';
import { normalizeChartTimeframe } from '@/lib/constants';
import { estimateBarBuySell } from '@/lib/volumeDirectionStats';
import { sanitizeChartCandlesForSeries, smaTotalVolumeAt } from '@/lib/volumeHistogramIntelligence';

export type VolumeAiZoneKind = 'up' | 'down' | 'low_base' | 'high_sell' | 'neutral';

export type VolumeAiZone = {
  id: string;
  kind: VolumeAiZoneKind;
  layer: 'trend' | 'pivot';
  timeFrom: number;
  timeTo: number;
  fromIdx: number;
  toIdx: number;
  bars: number;
  buyPct: number;
  sellPct: number;
  avgRvol: number;
  netPct: number;
  labelKo: string;
  color: string;
  fill: string;
};

export type VolumeAiZonePack = {
  zones: VolumeAiZone[];
  liveZone: VolumeAiZone | null;
  headlineKo: string;
};

const STYLE: Record<
  Exclude<VolumeAiZoneKind, 'neutral'>,
  { color: string; fill: string; label: string; layer: 'trend' | 'pivot' }
> = {
  up: { color: '#22c55e', fill: 'rgba(34,197,94,0.22)', label: '상승', layer: 'trend' },
  down: { color: '#ef4444', fill: 'rgba(239,68,68,0.22)', label: '하락', layer: 'trend' },
  low_base: { color: '#22d3ee', fill: 'rgba(34,211,238,0.42)', label: '저점·바닥', layer: 'pivot' },
  high_sell: { color: '#f97316', fill: 'rgba(249,115,22,0.42)', label: '고점·매도', layer: 'pivot' },
};

type Pivot = { idx: number; side: 'high' | 'low'; price: number };

function swingWing(timeframe?: string): number {
  const tf = normalizeChartTimeframe(timeframe ?? '4h');
  const map: Record<string, number> = {
    '1m': 4,
    '3m': 4,
    '5m': 4,
    '15m': 4,
    '1h': 3,
    '4h': 3,
    '1d': 3,
    '1w': 2,
    '1M': 2,
    '1Y': 2,
  };
  return map[tf] ?? 3;
}

function pivotHigh(rows: Candle[], i: number, L: number, R: number): boolean {
  const hi = rows[i]!.high;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || rows[j]!.high >= hi) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= rows.length || rows[j]!.high > hi) return false;
  }
  return true;
}

function pivotLow(rows: Candle[], i: number, L: number, R: number): boolean {
  const lo = rows[i]!.low;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || rows[j]!.low <= lo) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= rows.length || rows[j]!.low < lo) return false;
  }
  return true;
}

function wickRejectLow(c: Candle): boolean {
  const body = Math.abs(c.close - c.open);
  const lower = Math.min(c.open, c.close) - c.low;
  const range = c.high - c.low;
  return range > 0 && lower > body * 0.9 && lower > range * 0.35;
}

function wickRejectHigh(c: Candle): boolean {
  const body = Math.abs(c.close - c.open);
  const upper = c.high - Math.max(c.open, c.close);
  const range = c.high - c.low;
  return range > 0 && upper > body * 0.9 && upper > range * 0.35;
}

function windowVolStats(rows: Candle[], from: number, to: number, rvolPeriod: number) {
  let buySum = 0;
  let sellSum = 0;
  let rvolSum = 0;
  let volSum = 0;
  const bars = to - from + 1;
  for (let i = from; i <= to; i++) {
    const c = rows[i]!;
    const split = estimateBarBuySell(c);
    const vol = Math.max(0, c.volume || 0);
    const sma = i >= rvolPeriod - 1 ? smaTotalVolumeAt(rows, i, rvolPeriod) : vol;
    const rvol = sma > 0 ? vol / sma : 1;
    buySum += split.buyPct;
    sellSum += split.sellPct;
    rvolSum += rvol;
    volSum += vol;
  }
  const o0 = rows[from]!.open;
  const c1 = rows[to]!.close;
  const netPct = o0 > 0 ? ((c1 - o0) / o0) * 100 : 0;
  return {
    buyPct: buySum / bars,
    sellPct: sellSum / bars,
    avgRvol: rvolSum / bars,
    netPct,
    volSum,
    bars,
  };
}

function findPivots(rows: Candle[], wing: number, fromIdx: number): Pivot[] {
  const out: Pivot[] = [];
  const L = wing;
  const R = wing;
  for (let i = fromIdx; i < rows.length - R; i++) {
    if (pivotLow(rows, i, L, R)) out.push({ idx: i, side: 'low', price: rows[i]!.low });
    if (pivotHigh(rows, i, L, R)) out.push({ idx: i, side: 'high', price: rows[i]!.high });
  }
  out.sort((a, b) => a.idx - b.idx);
  const deduped: Pivot[] = [];
  for (const p of out) {
    const last = deduped[deduped.length - 1];
    if (last && last.idx === p.idx) continue;
    if (last && p.idx - last.idx <= 1 && last.side !== p.side) {
      if (p.side === 'high' && p.price >= last.price) deduped[deduped.length - 1] = p;
      else if (p.side === 'low' && p.price <= last.price) deduped[deduped.length - 1] = p;
      continue;
    }
    if (last && last.side === p.side && p.idx - last.idx < wing) {
      if (p.side === 'high' && p.price >= last.price) deduped[deduped.length - 1] = p;
      if (p.side === 'low' && p.price <= last.price) deduped[deduped.length - 1] = p;
      continue;
    }
    deduped.push(p);
  }
  return deduped;
}

function analyzeLowPivot(rows: Candle[], idx: number, wing: number, rvolPeriod: number): VolumeAiZoneKind {
  const cluster = Math.max(2, wing);
  const from = Math.max(0, idx - cluster);
  const to = Math.min(rows.length - 1, idx + cluster);
  const st = windowVolStats(rows, from, to, rvolPeriod);
  const pivot = rows[idx]!;
  const windowLo = Math.min(...rows.slice(from, to + 1).map((c) => c.low));
  const atBottom = pivot.low <= windowLo * 1.002;

  const mid = Math.floor((from + to) / 2);
  const first = windowVolStats(rows, from, mid, rvolPeriod);
  const second = windowVolStats(rows, mid + 1, to, rvolPeriod);
  const buyImproving = second.buyPct > first.buyPct + 0.04;

  const bottoming =
    atBottom &&
    st.avgRvol >= 1.1 &&
    (st.buyPct >= 0.5 || buyImproving || wickRejectLow(pivot) || st.netPct > -1.5);

  return bottoming ? 'low_base' : 'neutral';
}

function analyzeHighPivot(rows: Candle[], idx: number, wing: number, rvolPeriod: number): VolumeAiZoneKind {
  const cluster = Math.max(2, wing);
  const from = Math.max(0, idx - cluster);
  const to = Math.min(rows.length - 1, idx + cluster);
  const st = windowVolStats(rows, from, to, rvolPeriod);
  const pivot = rows[idx]!;
  const windowHi = Math.max(...rows.slice(from, to + 1).map((c) => c.high));
  const atTop = pivot.high >= windowHi * 0.998;

  const heavySell =
    atTop &&
    st.avgRvol >= 1.08 &&
    (st.sellPct >= 0.52 || wickRejectHigh(pivot) || (st.netPct < 0.5 && st.sellPct >= 0.48));

  return heavySell ? 'high_sell' : 'neutral';
}

function pushZone(
  out: VolumeAiZone[],
  zi: { n: number },
  kind: VolumeAiZoneKind,
  fromIdx: number,
  toIdx: number,
  rows: Candle[],
  stats: ReturnType<typeof windowVolStats>
) {
  if (kind === 'neutral' || fromIdx > toIdx) return;
  const st = STYLE[kind];
  out.push({
    id: `vol-swing-${zi.n++}`,
    kind,
    layer: st.layer,
    timeFrom: Number(rows[fromIdx]!.time),
    timeTo: Number(rows[toIdx]!.time),
    fromIdx,
    toIdx,
    bars: toIdx - fromIdx + 1,
    buyPct: stats.buyPct,
    sellPct: stats.sellPct,
    avgRvol: stats.avgRvol,
    netPct: stats.netPct,
    labelKo: st.label,
    color: st.color,
    fill: st.fill,
  });
}

export function buildVolumeAiZonePack(candles: Candle[], timeframe?: string): VolumeAiZonePack {
  const rows = sanitizeChartCandlesForSeries(candles, timeframe);
  const n = rows.length;
  if (n < 12) {
    return { zones: [], liveZone: null, headlineKo: '' };
  }

  const wing = swingWing(timeframe);
  const rvolPeriod = 20;
  const fromScan = Math.max(wing + 2, n - 160);
  const pivots = findPivots(rows, wing, fromScan);
  const zones: VolumeAiZone[] = [];
  let zi = 0;

  for (let p = 0; p < pivots.length; p++) {
    const pv = pivots[p]!;
    const cluster = Math.max(2, wing);
    const from = Math.max(0, pv.idx - cluster);
    const to = Math.min(n - 1, pv.idx + cluster);
    const st = windowVolStats(rows, from, to, rvolPeriod);

    if (pv.side === 'low') {
      const kind = analyzeLowPivot(rows, pv.idx, wing, rvolPeriod);
      if (kind === 'low_base') pushZone(zones, { n: zi }, kind, from, to, rows, st);
      zi++;
    } else {
      const kind = analyzeHighPivot(rows, pv.idx, wing, rvolPeriod);
      if (kind === 'high_sell') pushZone(zones, { n: zi }, kind, from, to, rows, st);
      zi++;
    }
  }

  for (let p = 0; p + 1 < pivots.length; p++) {
    const a = pivots[p]!;
    const b = pivots[p + 1]!;
    if (a.side === b.side) continue;
    const fromIdx = a.idx;
    const toIdx = b.idx;
    const st = windowVolStats(rows, fromIdx, toIdx, rvolPeriod);
    const priceUp = b.price > a.price;
    const kind: VolumeAiZoneKind =
      a.side === 'low' && b.side === 'high' && priceUp
        ? 'up'
        : a.side === 'high' && b.side === 'low' && !priceUp
          ? 'down'
          : priceUp
            ? 'up'
            : 'down';
    if (toIdx - fromIdx >= 2) pushZone(zones, { n: zi }, kind, fromIdx, toIdx, rows, st);
    zi++;
  }

  const lastPivot = pivots[pivots.length - 1];
  if (lastPivot && lastPivot.idx < n - 1) {
    const fromIdx = lastPivot.idx;
    const toIdx = n - 1;
    const st = windowVolStats(rows, fromIdx, toIdx, rvolPeriod);
    const kind: VolumeAiZoneKind =
      lastPivot.side === 'low'
        ? st.netPct >= -0.5
          ? 'up'
          : 'down'
        : st.netPct <= 0.5
          ? 'down'
          : 'up';
    pushZone(zones, { n: zi }, kind, fromIdx, toIdx, rows, st);
  }

  const sorted = zones.sort((a, b) => {
    if (a.layer !== b.layer) return a.layer === 'trend' ? -1 : 1;
    return a.fromIdx - b.fromIdx;
  });

  const trimmed = sorted.slice(-14);
  const liveZone = trimmed.find((z) => z.toIdx >= n - 1 && z.layer === 'trend') ?? trimmed[trimmed.length - 1] ?? null;
  const lastPivotZone = trimmed.filter((z) => z.layer === 'pivot').slice(-1)[0];
  let headlineKo = liveZone?.labelKo ?? '';
  if (lastPivotZone) headlineKo = `${headlineKo}${headlineKo ? ' · ' : ''}${lastPivotZone.labelKo}`;

  return { zones: trimmed, liveZone, headlineKo };
}

export type VolumeAiZoneScreenGeom = {
  id: string;
  x1: number;
  x2: number;
  yTop: number;
  yBot: number;
  labelKo: string;
  color: string;
  fill: string;
  kind: VolumeAiZoneKind;
  layer: 'trend' | 'pivot';
  isLive: boolean;
};

export type VolumeAiZoneScreenPack = {
  zones: VolumeAiZoneScreenGeom[];
  volPanelTop: number;
