export function projectVolumeAiZonesToScreen(params: {
  pack: VolumeAiZonePack;
  candles: Candle[];
  resolveBarSpanX: (fromIdx: number, toIdx: number) => { x1: number; x2: number } | null;
  chartHeight: number;
  volPanelTopRatio?: number;
}): VolumeAiZoneScreenPack {
  const { pack, resolveBarSpanX, chartHeight: chartH, volPanelTopRatio = 0.82 } = params;

  const volPanelTop = chartH * volPanelTopRatio;
  const volPanelBot = chartH - 2;
  const trendTop = volPanelTop + 2;
  const trendBot = volPanelBot - 16;
  const pivotTop = volPanelTop + (trendBot - trendTop) * 0.22;
  const pivotBot = volPanelBot - 18;

  const lastIdx = sanitizeChartCandlesForSeries(params.candles).length - 1;

  const zones = pack.zones
    .map((z) => {
      const span = resolveBarSpanX(z.fromIdx, z.toIdx);
      if (!span || span.x2 - span.x1 < 4) return null;
      const isPivot = z.layer === 'pivot';
      return {
        id: z.id,
        x1: span.x1,
        x2: span.x2,
        yTop: isPivot ? pivotTop : trendTop,
        yBot: isPivot ? pivotBot : trendBot,
        labelKo: z.labelKo,
        color: z.color,
        fill: z.fill,
        kind: z.kind,
        layer: z.layer,
        isLive: z.toIdx >= lastIdx,
      };
    })
    .filter(Boolean) as VolumeAiZoneScreenGeom[];

  return {
    zones,
    volPanelTop,
    volPanelBot,
    liveLabel: pack.headlineKo,
  };
}

