/** Bitget Vol — 고점/저점 거래량 + 상승·하락 구간 */
export function VolumeAiZoneDrawLayer({ zones, volPanelTop, volPanelBot, liveLabel }: Props) {
  if (!zones.length) return null;

  const legendY = volPanelBot - 11;
  const trends = zones.filter((z) => z.layer === 'trend');
  const pivots = zones.filter((z) => z.layer === 'pivot');

  const drawZone = (z: VolumeAiZoneScreenGeom) => {
    const w = Math.max(8, z.x2 - z.x1);
    const h = Math.max(8, z.yBot - z.yTop);
    const cx = z.x1 + w / 2;
    const isPivot = z.layer === 'pivot';
    const showLabel = isPivot || w >= 36;
    return (
      <g
        key={z.id}
        className={`volume-ai-zone volume-ai-zone--${z.kind}${z.isLive ? ' volume-ai-zone--live' : ''}`}
      >
        <rect
          x={z.x1}
          y={z.yTop}
          width={w}
          height={h}
          fill={z.fill}
          stroke={z.color}
          strokeWidth={isPivot ? 1.4 : 0.8}
          opacity={isPivot ? 0.72 : z.isLive ? 0.42 : 0.28}
        />
        {showLabel && (
          <text x={cx} y={z.yTop + (isPivot ? h / 2 + 4 : 11)} textAnchor="middle" className="volume-ai-zone__tag">
            {z.labelKo}
          </text>
        )}
      </g>
    );
  };

  return (
    <svg className="volume-ai-zone-draw-layer" width="100%" height="100%" aria-hidden>
      <defs>
        <clipPath id="vol-swing-panel-clip">
          <rect x={0} y={volPanelTop} width="100%" height={Math.max(24, volPanelBot - volPanelTop)} />
        </clipPath>
      </defs>
      <g clipPath="url(#vol-swing-panel-clip)">
        {trends.map(drawZone)}
        {pivots.map(drawZone)}
      </g>
      <g className="volume-ai-zone__legend-row">
        {LEGEND.map((item, i) => (
          <g key={item.label} transform={`translate(${6 + i * 46}, ${legendY})`}>
            <rect x={0} y={0} width={7} height={7} rx={1} fill={item.color} opacity={0.95} />
            <text x={10} y={6.5} className="volume-ai-zone__legend-chip">
              {item.label}
            </text>
          </g>
        ))}
        {liveLabel && (
          <text x={196} y={legendY + 6.5} className="volume-ai-zone__legend-live">
            {liveLabel.length > 48 ? `${liveLabel.slice(0, 48)}…` : liveLabel}
          </text>
        )}
      </g>
    </svg>
  );
}

