/**
 * Bitget Vol — 거래량 구간 분석 (1·2번 박스형: 거래량↑·매도↑·저점·상승/하락)
 */
import type { Candle } from '@/types';
import { normalizeChartTimeframe } from '@/lib/constants';
import { estimateBarBuySell } from '@/lib/volumeDirectionStats';
import { sanitizeChartCandlesForSeries, smaTotalVolumeAt } from '@/lib/volumeHistogramIntelligence';

export type VolumeAiZoneKind =
  | 'low_surge'
  | 'range_heavy'
  | 'vol_up'
  | 'sell_up'
  | 'buy_up'
  | 'high_sell'
  | 'up'
  | 'down';

export type VolumeAiZone = {
  id: string;
  kind: VolumeAiZoneKind;
  layer: 'cluster' | 'trend';
  segNo?: number;
  timeFrom: number;
  timeTo: number;
  fromIdx: number;
  toIdx: number;
  bars: number;
  buyPct: number;
  sellPct: number;
  avgRvol: number;
  volTrendPct: number;
  sellTrendPct: number;
  buyTrendPct: number;
  netPct: number;
  labelKo: string;
  detailKo: string;
  color: string;
  fill: string;
};

export type VolumeAiZonePack = {
  zones: VolumeAiZone[];
  liveZone: VolumeAiZone | null;
  headlineKo: string;
};

type BarMeta = {
  buyPct: number;
  sellPct: number;
  buyVol: number;
  sellVol: number;
  vol: number;
  rvol: number;
  netPct: number;
};

const STYLE: Record<
  VolumeAiZoneKind,
  { color: string; fill: string; base: string }
> = {
  low_surge: { color: '#22d3ee', fill: 'rgba(34,211,238,0.28)', base: '저점·거래량↑' },
  range_heavy: { color: '#a78bfa', fill: 'rgba(167,139,250,0.22)', base: '횡보·거래량↑' },
  vol_up: { color: '#4ade80', fill: 'rgba(74,222,128,0.2)', base: '거래량↑' },
  sell_up: { color: '#f97316', fill: 'rgba(249,115,22,0.28)', base: '매도↑' },
  buy_up: { color: '#22c55e', fill: 'rgba(34,197,94,0.22)', base: '매수↑' },
  high_sell: { color: '#fb7185', fill: 'rgba(251,113,133,0.32)', base: '고점·매도↑' },
  up: { color: '#16a34a', fill: 'rgba(22,163,74,0.18)', base: '상승' },
  down: { color: '#dc2626', fill: 'rgba(220,38,38,0.18)', base: '하락' },
};

function swingWing(timeframe?: string): number {
  const tf = normalizeChartTimeframe(timeframe ?? '4h');
  const map: Record<string, number> = {
    '1m': 4,
    '3m': 4,
    '5m': 4,
    '15m': 4,
    '1h': 3,
    '4h': 3,
    '1d': 3,
    '1w': 2,
    '1M': 2,
    '1Y': 2,
  };
  return map[tf] ?? 3;
}

function buildBarMeta(rows: Candle[], rvolPeriod: number): BarMeta[] {
  return rows.map((c, i) => {
    const split = estimateBarBuySell(c);
    const vol = Math.max(0, c.volume || 0);
    const sma = i >= rvolPeriod - 1 ? smaTotalVolumeAt(rows, i, rvolPeriod) : vol;
    const rvol = sma > 0 ? vol / sma : 1;
    const o = c.open;
    const netPct = o > 0 ? ((c.close - o) / o) * 100 : 0;
    return {
      buyPct: split.buyPct,
      sellPct: split.sellPct,
      buyVol: split.buyVol,
      sellVol: split.sellVol,
      vol,
      rvol,
      netPct,
    };
  });
}

function trendPct(first: number, second: number): number {
  if (first <= 0) return second > 0 ? 100 : 0;
  return ((second - first) / first) * 100;
}

function segmentTrends(rows: Candle[], meta: BarMeta[], from: number, to: number) {
  const mid = Math.floor((from + to) / 2);
  let v1 = 0;
  let v2 = 0;
  let s1 = 0;
  let s2 = 0;
  let b1 = 0;
  let b2 = 0;
  let buySum = 0;
  let sellSum = 0;
  let rvolSum = 0;
  for (let i = from; i <= to; i++) {
    const m = meta[i]!;
    buySum += m.buyPct;
    sellSum += m.sellPct;
    rvolSum += m.rvol;
    if (i <= mid) {
      v1 += m.vol;
      s1 += m.sellVol;
      b1 += m.buyVol;
    } else {
      v2 += m.vol;
      s2 += m.sellVol;
      b2 += m.buyVol;
    }
  }
  const bars = to - from + 1;
  const o0 = rows[from]!.open;
  const c1 = rows[to]!.close;
  const netPct = o0 > 0 ? ((c1 - o0) / o0) * 100 : 0;
  return {
    buyPct: buySum / bars,
    sellPct: sellSum / bars,
    avgRvol: rvolSum / bars,
    netPct,
    volTrendPct: trendPct(v1, v2),
    sellTrendPct: trendPct(s1, s2),
    buyTrendPct: trendPct(b1, b2),
  };
}

function isLocalLow(rows: Candle[], from: number, to: number, lookback: number): boolean {
  const segLo = Math.min(...rows.slice(from, to + 1).map((c) => c.low));
  const ctxFrom = Math.max(0, from - lookback);
  const ctxLo = Math.min(...rows.slice(ctxFrom, from).map((c) => c.low));
  return segLo <= ctxLo * 1.008;
}

function isLocalHigh(rows: Candle[], from: number, to: number, lookback: number): boolean {
  const segHi = Math.max(...rows.slice(from, to + 1).map((c) => c.high));
  const ctxFrom = Math.max(0, from - lookback);
  const ctxHi = Math.max(...rows.slice(ctxFrom, from).map((c) => c.high));
  return segHi >= ctxHi * 0.992;
}

function isRangeSegment(rows: Candle[], from: number, to: number, maxSpanPct: number): boolean {
  const seg = rows.slice(from, to + 1);
  const hi = Math.max(...seg.map((c) => c.high));
  const lo = Math.min(...seg.map((c) => c.low));
  const mid = (hi + lo) / 2;
  if (mid <= 0) return false;
  return (hi - lo) / mid <= maxSpanPct;
}

/** RVOL·거래량 클러스터 (표시 1·2번 같은 구간) */
function detectVolumeClusters(
  rows: Candle[],
  meta: BarMeta[],
  fromScan: number
): Array<{ from: number; to: number }> {
  const n = rows.length;
  const clusters: Array<{ from: number; to: number }> = [];
  let i = fromScan;
  while (i < n) {
    const hot = meta[i]!.rvol >= 1.15 || meta[i]!.vol > 0;
    if (!hot || meta[i]!.rvol < 1.08) {
      i++;
      continue;
    }
    const start = i;
    let peakRvol = meta[i]!.rvol;
    while (i < n) {
      const m = meta[i]!;
      if (i > start + 16) break;
      if (m.rvol < 0.82 && i > start + 2) break;
      if (m.rvol < 0.95 && i > start + 5) break;
      peakRvol = Math.max(peakRvol, m.rvol);
      i++;
    }
    const end = i - 1;
    const bars = end - start + 1;
    const avgRvol =
      meta.slice(start, end + 1).reduce((s, x) => s + x.rvol, 0) / Math.max(1, bars);
    if (bars >= 3 && avgRvol >= 1.05) {
      clusters.push({ from: start, to: end });
    }
  }
  return clusters;
}

function classifyCluster(
  rows: Candle[],
  meta: BarMeta[],
  from: number,
  to: number,
  wing: number
): { kind: VolumeAiZoneKind; labelKo: string; detailKo: string } {
  const tr = segmentTrends(rows, meta, from, to);
  const lookback = Math.max(12, wing * 4);
  const atLow = isLocalLow(rows, from, to, lookback);
  const atHigh = isLocalHigh(rows, from, to, lookback);
  const range = isRangeSegment(rows, from, to, 0.045);

  const volUp = tr.volTrendPct >= 12 || tr.avgRvol >= 1.35;
  const sellUp = tr.sellTrendPct >= 10 || (tr.sellPct >= 0.54 && tr.sellTrendPct >= 5);
  const buyUp = tr.buyTrendPct >= 10 || (tr.buyPct >= 0.54 && tr.buyTrendPct >= 5);

  const tags: string[] = [];
  if (volUp) tags.push('거래량↑');
  if (sellUp) tags.push('매도↑');
  if (buyUp) tags.push('매수↑');

  let kind: VolumeAiZoneKind = 'vol_up';
  if (atLow && volUp) {
    kind = 'low_surge';
    if (!tags.includes('거래량↑')) tags.unshift('거래량↑');
  } else if (atHigh && sellUp) {
    kind = 'high_sell';
  } else if (range && tr.avgRvol >= 1.1) {
    kind = 'range_heavy';
    if (!tags.length) tags.push('거래량↑');
  } else if (sellUp && !buyUp) {
    kind = 'sell_up';
  } else if (buyUp && !sellUp) {
    kind = 'buy_up';
  } else if (volUp) {
    kind = 'vol_up';
  } else if (sellUp) {
    kind = 'sell_up';
  }

  const labelKo =
    kind === 'low_surge'
      ? `저점·${tags.filter((t) => t !== '저점').join('·') || '거래량↑'}`
      : kind === 'high_sell'
        ? '고점·매도↑'
        : kind === 'range_heavy'
          ? `횡보·${tags.join('·') || '거래량↑'}`
          : tags.length
            ? tags.join('·')
            : STYLE[kind].base;

  const detailKo = [
    labelKo,
    `RVOL${tr.avgRvol.toFixed(1)}×`,
    `Vol${tr.volTrendPct >= 0 ? '+' : ''}${tr.volTrendPct.toFixed(0)}%`,
    `매도${tr.sellTrendPct >= 0 ? '+' : ''}${tr.sellTrendPct.toFixed(0)}%`,
    `${to - from + 1}봉`,
  ].join(' · ');

  return { kind, labelKo, detailKo };
}

function pivotHigh(rows: Candle[], i: number, L: number, R: number): boolean {
  const hi = rows[i]!.high;
  for (let j = i - L; j < i; j++) if (j < 0 || rows[j]!.high >= hi) return false;
  for (let j = i + 1; j <= i + R; j++) if (j >= rows.length || rows[j]!.high > hi) return false;
  return true;
}

function pivotLow(rows: Candle[], i: number, L: number, R: number): boolean {
  const lo = rows[i]!.low;
  for (let j = i - L; j < i; j++) if (j < 0 || rows[j]!.low <= lo) return false;
  for (let j = i + 1; j <= i + R; j++) if (j >= rows.length || rows[j]!.low < lo) return false;
  return true;
}

function findPivots(rows: Candle[], wing: number, fromIdx: number) {
  const out: Array<{ idx: number; side: 'high' | 'low'; price: number }> = [];
  for (let i = fromIdx; i < rows.length - wing; i++) {
    if (pivotLow(rows, i, wing, wing)) out.push({ idx: i, side: 'low', price: rows[i]!.low });
    if (pivotHigh(rows, i, wing, wing)) out.push({ idx: i, side: 'high', price: rows[i]!.high });
  }
  return out.sort((a, b) => a.idx - b.idx);
}

export function buildVolumeAiZonePack(candles: Candle[], timeframe?: string): VolumeAiZonePack {
  const rows = sanitizeChartCandlesForSeries(candles, timeframe);
  const n = rows.length;
  if (n < 10) return { zones: [], liveZone: null, headlineKo: '' };

  const wing = swingWing(timeframe);
  const rvolPeriod = 20;
  const meta = buildBarMeta(rows, rvolPeriod);
  const fromScan = Math.max(wing + 2, n - 140);
  const zones: VolumeAiZone[] = [];
  let zi = 0;

  const clusters = detectVolumeClusters(rows, meta, fromScan);
  let segNo = 1;
  for (const cl of clusters.slice(-6)) {
    const { kind, labelKo, detailKo } = classifyCluster(rows, meta, cl.from, cl.to, wing);
    const tr = segmentTrends(rows, meta, cl.from, cl.to);
    const st = STYLE[kind];
    zones.push({
      id: `vol-cl-${zi++}`,
      kind,
      layer: 'cluster',
      segNo: segNo++,
      timeFrom: Number(rows[cl.from]!.time),
      timeTo: Number(rows[cl.to]!.time),
      fromIdx: cl.from,
      toIdx: cl.to,
      bars: cl.to - cl.from + 1,
      buyPct: tr.buyPct,
      sellPct: tr.sellPct,
      avgRvol: tr.avgRvol,
      volTrendPct: tr.volTrendPct,
      sellTrendPct: tr.sellTrendPct,
      buyTrendPct: tr.buyTrendPct,
      netPct: tr.netPct,
      labelKo,
      detailKo,
      color: st.color,
      fill: st.fill,
    });
  }

  const pivots = findPivots(rows, wing, fromScan);
  for (let p = 0; p + 1 < pivots.length; p++) {
    const a = pivots[p]!;
    const b = pivots[p + 1]!;
    if (a.side === b.side) continue;
    const fromIdx = a.idx;
    const toIdx = b.idx;
    if (toIdx - fromIdx < 4) continue;
    const tr = segmentTrends(rows, meta, fromIdx, toIdx);
    const priceUp = b.price > a.price;
    const kind: VolumeAiZoneKind =
      a.side === 'low' && b.side === 'high' && priceUp
        ? 'up'
        : a.side === 'high' && b.side === 'low'
          ? 'down'
          : priceUp
            ? 'up'
            : 'down';
    const st = STYLE[kind];
    const extra =
      tr.volTrendPct >= 10
        ? '·거래량↑'
        : tr.sellTrendPct >= 10
          ? '·매도↑'
          : tr.buyTrendPct >= 10
            ? '·매수↑'
            : '';
    zones.push({
      id: `vol-tr-${zi++}`,
      kind,
      layer: 'trend',
      timeFrom: Number(rows[fromIdx]!.time),
      timeTo: Number(rows[toIdx]!.time),
      fromIdx,
      toIdx,
      bars: toIdx - fromIdx + 1,
      buyPct: tr.buyPct,
      sellPct: tr.sellPct,
      avgRvol: tr.avgRvol,
      volTrendPct: tr.volTrendPct,
      sellTrendPct: tr.sellTrendPct,
      buyTrendPct: tr.buyTrendPct,
      netPct: tr.netPct,
      labelKo: `${st.base}${extra}`,
      detailKo: `${st.base} · ${toIdx - fromIdx + 1}봉 · Vol${tr.volTrendPct >= 0 ? '+' : ''}${tr.volTrendPct.toFixed(0)}%`,
      color: st.color,
      fill: st.fill,
    });
  }

  const sorted = zones.sort((a, b) => a.fromIdx - b.fromIdx);
  const trimmed = sorted.slice(-10);
  const liveCluster = trimmed.filter((z) => z.layer === 'cluster' && z.toIdx >= n - 2).slice(-1)[0];
  const liveTrend = trimmed.filter((z) => z.layer === 'trend' && z.toIdx >= n - 1).slice(-1)[0];
  const liveZone = liveCluster ?? liveTrend ?? trimmed[trimmed.length - 1] ?? null;
  const headlineKo = liveZone?.detailKo ?? '';

  return { zones: trimmed, liveZone, headlineKo };
}

export type VolumeAiZoneScreenGeom = {
  id: string;
  x1: number;
  x2: number;
  labelKo: string;
  detailKo: string;
  color: string;
  fill: string;
  kind: VolumeAiZoneKind;
  layer: 'cluster' | 'trend';
  segNo?: number;
  isLive: boolean;
  barSpan: number;
};

export type VolumeAiZoneScreenPack = {
  zones: VolumeAiZoneScreenGeom[];
  volPanelTop: number;
  volPanelBot: number;
  liveLabel: string;
};

export function projectVolumeAiZonesToScreen(params: {
  pack: VolumeAiZonePack;
  candles: Candle[];
  resolveBarSpanX: (fromIdx: number, toIdx: number) => { x1: number; x2: number } | null;
  chartHeight: number;
  volPanelTopRatio?: number;
}): VolumeAiZoneScreenPack {
  const { pack, resolveBarSpanX, chartHeight: chartH, volPanelTopRatio = 0.82 } = params;
  const volPanelTop = chartH * volPanelTopRatio;
  const volPanelBot = chartH - 2;
  const lastIdx = sanitizeChartCandlesForSeries(params.candles).length - 1;
  const minPx = 28;

  const zones = pack.zones
    .map((z) => {
      const span = resolveBarSpanX(z.fromIdx, z.toIdx);
      if (!span) return null;
      const w = span.x2 - span.x1;
      if (w < minPx) return null;
      if (z.layer === 'trend' && z.bars < 4) return null;
      return {
        id: z.id,
        x1: span.x1,
        x2: span.x2,
        labelKo: z.segNo ? `${z.segNo} ${z.labelKo}` : z.labelKo,
        detailKo: z.detailKo,
        color: z.color,
        fill: z.fill,
        kind: z.kind,
        layer: z.layer,
        segNo: z.segNo,
        isLive: z.toIdx >= lastIdx - 1,
        barSpan: z.bars,
      };
    })
    .filter(Boolean) as VolumeAiZoneScreenGeom[];

  return {
    zones,
    volPanelTop,
    volPanelBot,
    liveLabel: pack.headlineKo,
  };
}

export function buildVolumeAiZoneMarkers(): never[] {
  return [];
}

export function applyVolumeRegimeBarColors(
  base: import('lightweight-charts').HistogramData<import('lightweight-charts').UTCTimestamp>[],
  pack: VolumeAiZonePack | null,
  candles: Candle[]
): import('lightweight-charts').HistogramData<import('lightweight-charts').UTCTimestamp>[] {
  if (!pack?.zones.length) return base;
  const rows = sanitizeChartCandlesForSeries(candles);
  const tintByIdx = new Map<number, VolumeAiZone>();
  const rankOf = (z: VolumeAiZone) => (z.layer === 'cluster' ? 100 : 20) + z.bars;
  for (const z of pack.zones) {
    for (let i = z.fromIdx; i <= z.toIdx && i < rows.length; i++) {
      const prev = tintByIdx.get(i);
      if (!prev || rankOf(z) >= rankOf(prev)) tintByIdx.set(i, z);
    }
  }
  return base.map((bar, i) => {
    const z = tintByIdx.get(i);
    if (!z) return bar;
    return { ...bar, color: z.color };
  });
}

'use client';

import type { VolumeAiZoneScreenGeom } from '@/lib/volumeAiZoneEngine';

type Props = {
  zones: VolumeAiZoneScreenGeom[];
  liveLabel?: string;
};

const LEGEND = [
  { label: '저점·거래량↑', color: '#22d3ee' },
  { label: '횡보·거래량↑', color: '#a78bfa' },
  { label: '매도↑', color: '#f97316' },
  { label: '상승/하락', color: '#22c55e' },
] as const;

/** 거래량 구간 박스 (1·2번 표시처럼) — 가로만, 거래량 패널 안 */
export function VolumeAiZoneDrawLayer({ zones, liveLabel }: Props) {
  if (!zones.length) return null;

  const clusters = zones.filter((z) => z.layer === 'cluster');
  const trends = zones.filter((z) => z.layer === 'trend');

  const drawBox = (z: VolumeAiZoneScreenGeom, y: number, h: number, thick: boolean) => {
    const w = Math.max(28, z.x2 - z.x1);
    const cx = z.x1 + w / 2;
    const pad = 2;
    return (
      <g key={z.id} className={`volume-seg-box volume-seg-box--${z.kind}`}>
        <rect
          x={z.x1 - pad}
          y={y}
          width={w + pad * 2}
          height={h}
          fill={z.fill}
          stroke={z.color}
          strokeWidth={thick ? 1.6 : 1}
          rx={3}
          opacity={thick ? 0.55 : 0.35}
        />
        {w >= 40 && (
          <text x={cx} y={y + 11} textAnchor="middle" className="volume-seg-box__label">
            {z.labelKo}
          </text>
        )}
      </g>
    );
  };

  return (
    <div className="volume-regime-panel" aria-hidden>
      <svg className="volume-regime-panel__svg" width="100%" height="100%">
        {trends.map((z) => drawBox(z, 4, 10, false))}
        {clusters.map((z) => drawBox(z, 18, 22, true))}
      </svg>
      <div className="volume-regime-panel__legend">
        {LEGEND.map((item) => (
          <span key={item.label} className="volume-regime-panel__chip">
            <i style={{ background: item.color }} />
            {item.label}
          </span>
        ))}
        {liveLabel ? <span className="volume-regime-panel__live">{liveLabel}</span> : null}
      </div>
    </div>
  );
}

