export function buildVolumeAiZonePack(candles: Candle[], timeframe?: string): VolumeAiZonePack {
  const rows = sanitizeChartCandlesForSeries(candles, timeframe);
  const n = rows.length;
  if (n < 10) return { zones: [], liveZone: null, headlineKo: '' };

  const wing = swingWing(timeframe);
  const rvolPeriod = 20;
  const meta = buildBarMeta(rows, rvolPeriod);
  const fromScan = Math.max(wing + 2, n - 140);
  const zones: VolumeAiZone[] = [];
  let zi = 0;

  const clusters = detectVolumeClusters(rows, meta, fromScan);
  let segNo = 1;
  for (const cl of clusters.slice(-6)) {
    const { kind, labelKo, detailKo } = classifyCluster(rows, meta, cl.from, cl.to, wing);
    const tr = segmentTrends(rows, meta, cl.from, cl.to);
    const st = STYLE[kind];
    zones.push({
      id: `vol-cl-${zi++}`,
      kind,
      layer: 'cluster',
      segNo: segNo++,
      timeFrom: Number(rows[cl.from]!.time),
      timeTo: Number(rows[cl.to]!.time),
      fromIdx: cl.from,
      toIdx: cl.to,
      bars: cl.to - cl.from + 1,
      buyPct: tr.buyPct,
      sellPct: tr.sellPct,
      avgRvol: tr.avgRvol,
      volTrendPct: tr.volTrendPct,
      sellTrendPct: tr.sellTrendPct,
      buyTrendPct: tr.buyTrendPct,
      netPct: tr.netPct,
      labelKo,
      detailKo,
      color: st.color,
      fill: st.fill,
    });
  }

  const pivots = findPivots(rows, wing, fromScan);
  for (let p = 0; p + 1 < pivots.length; p++) {
    const a = pivots[p]!;
    const b = pivots[p + 1]!;
    if (a.side === b.side) continue;
    const fromIdx = a.idx;
    const toIdx = b.idx;
    if (toIdx - fromIdx < 4) continue;
    const tr = segmentTrends(rows, meta, fromIdx, toIdx);
    const priceUp = b.price > a.price;
    const kind: VolumeAiZoneKind =
      a.side === 'low' && b.side === 'high' && priceUp
        ? 'up'
        : a.side === 'high' && b.side === 'low'
          ? 'down'
          : priceUp
            ? 'up'
            : 'down';
    const st = STYLE[kind];
    const extra =
      tr.volTrendPct >= 10
        ? '·거래량↑'
        : tr.sellTrendPct >= 10
          ? '·매도↑'
          : tr.buyTrendPct >= 10
            ? '·매수↑'
            : '';
    zones.push({
      id: `vol-tr-${zi++}`,
      kind,
      layer: 'trend',
      timeFrom: Number(rows[fromIdx]!.time),
      timeTo: Number(rows[toIdx]!.time),
      fromIdx,
      toIdx,
      bars: toIdx - fromIdx + 1,
      buyPct: tr.buyPct,
      sellPct: tr.sellPct,
      avgRvol: tr.avgRvol,
      volTrendPct: tr.volTrendPct,
      sellTrendPct: tr.sellTrendPct,
      buyTrendPct: tr.buyTrendPct,
      netPct: tr.netPct,
      labelKo: `${st.base}${extra}`,
      detailKo: `${st.base} · ${toIdx - fromIdx + 1}봉 · Vol${tr.volTrendPct >= 0 ? '+' : ''}${tr.volTrendPct.toFixed(0)}%`,
      color: st.color,
      fill: st.fill,
    });
  }

  const sorted = zones.sort((a, b) => a.fromIdx - b.fromIdx);
  const trimmed = sorted.slice(-10);
  const liveCluster = trimmed.filter((z) => z.layer === 'cluster' && z.toIdx >= n - 2).slice(-1)[0];
  const liveTrend = trimmed.filter((z) => z.layer === 'trend' && z.toIdx >= n - 1).slice(-1)[0];
  const liveZone = liveCluster ?? liveTrend ?? trimmed[trimmed.length - 1] ?? null;
  const headlineKo = liveZone?.detailKo ?? '';

  return { zones: trimmed, liveZone, headlineKo };
}

