'use client';

import type { VolumeLiveCompare } from '@/lib/volumeAiZoneEngine';

type Props = {
  live: VolumeLiveCompare;
  fullscreen?: boolean;
};

function chip(label: string, value: number, decimals = 0) {
  const sign = value >= 0 ? '+' : '';
  const cls =
    value >= 12 ? 'volume-compare-strip__val--up' : value <= -12 ? 'volume-compare-strip__val--down' : '';
  return (
    <span className="volume-compare-strip__chip">
      <span className="volume-compare-strip__key">{label}</span>
      <span className={`volume-compare-strip__val ${cls}`}>
        {sign}
        {value.toFixed(decimals)}%
      </span>
    </span>
  );
}

/** 거래량 패널 하단 — 현재봉 vs 과거 20봉 AI 비교 */
export function VolumeCompareStrip({ live, fullscreen }: Props) {
  return (
    <div
      className={`volume-compare-strip${fullscreen ? ' volume-compare-strip--fs' : ''}`}
      aria-label="거래량 AI 비교"
      title={live.headlineKo}
    >
      <span className="volume-compare-strip__title">AI Vol</span>
      {chip('Vol', live.volVsPastPct)}
      {chip('매도', live.sellVsPastPct)}
      {chip('매수', live.buyVsPastPct)}
      {chip('가격', live.priceVsPrevPct, 2)}
      <span className="volume-compare-strip__rvol">RVOL {live.rvol.toFixed(2)}×</span>
    </div>
  );
}

