export type VolumeAiExplainMetric = {
  code: string;
  label: string;
  value: string;
  tone: 'up' | 'down' | 'neutral';
  hint: string;
};

export function buildVolumeZoneExplainCard(zone: VolumeAiZone): {
  title: string;
  subtitle: string;
  metrics: VolumeAiExplainMetric[];
  footnote: string;
} {
  const toneOf = (v: number): 'up' | 'down' | 'neutral' =>
    v >= 8 enough ? 'up' : v <= -8 ? 'down' : 'neutral';
  const pct = (v: number, d = 0) => `${v >= 0 ? '+' : ''}${v.toFixed(d)}%`;

  const title = zone.segNo ? `${zone.segNo}번 · ${zone.labelKo}` : zone.labelKo;
  const subtitle = `${zone.bars}봉 · RVOL ${zone.avgRvol.toFixed(2)}×`;

  const metrics: VolumeAiExplainMetric[] = [
    {
      code: 'V',
      label: '거래량',
      value: pct(zone.volVsPastPct),
      tone: toneOf(zone.volVsPastPct),
      hint: '직전 20봉 평균 대비 이 구간 거래량 증감',
    },
    {
      code: 'S',
