'use client';

import type { VolumeAiZoneScreenGeom } from '@/lib/volumeAiZoneEngine';

type Props = {
  zones: VolumeAiZoneScreenGeom[];
  volPanelTop: number;
  volPanelBot: number;
  selectedZoneId?: string | null;
  onZoneClick?: (zoneId: string) => void;
};

/** 거래량 패널 구간 박스 — 클릭 시 설명 카드 */
export function VolumeAiZoneDrawLayer({
  zones,
  volPanelTop,
  volPanelBot,
  selectedZoneId,
  onZoneClick,
}: Props) {
  const clusters = zones.filter((z) => z.layer === 'cluster');
  if (!clusters.length) return null;

  const h = Math.max(20, volPanelBot - volPanelTop - 4);

  return (
    <div
      className="volume-regime-panel volume-regime-panel--interactive"
      style={{ top: volPanelTop, height: h, bottom: 'auto' }}
    >
      <svg className="volume-regime-panel__svg" width="100%" height="100%">
        {clusters.map((z) => {
          const w = Math.max(24, z.x2 - z.x1);
          const selected = selectedZoneId === z.id;
          return (
            <g key={z.id} className={`volume-seg-box volume-seg-box--${z.kind}${selected ? ' volume-seg-box--selected' : ''}`}>
              <rect
                className="volume-seg-box__hit"
                x={z.x1 - 2}
                y={4}
                width={w + 4}
                height={h - 8}
                fill={z.fill}
                stroke={z.color}
                strokeWidth={selected ? 2.2 : 1.5}
                rx={3}
                opacity={selected ? 0.72 : 0.45}
                onClick={() => onZoneClick?.(z.id)}
              />
              <line x1={z.x1 - 2} y1={4} x2={z.x2 + 2} y2={4} stroke={z.color} strokeWidth={2} pointerEvents="none" />
              {z.segNo != null && w >= 18 && (
                <text
                  x={z.x1 + 6}
                  y={16}
                  className="volume-seg-box__num"
                  pointerEvents="none"
                >
                  {z.segNo}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

