export function comparePlainShort(pct: number): string {
  const abs = Math.abs(pct).toFixed(0);
  if (pct >= 8) return `${abs}%↑`;
  if (pct <= -8) return `${abs}%↓`;
  return '비슷';
}

/** 거래량 막대 위 표시 — 쉬운 한국어 라벨 */
export function buildVolumeVisibleLabel(z: VolumeAiZone, widthPx: number): string {
  const vol = comparePlainShort(z.volVsPastPct);
  const volTail = vol === '비슷' ? '' : `·거래${vol}`;

  if (widthPx >= 80) {
    return `${z.segNo ? `${z.segNo}. ` : ''}${z.labelKo}${volTail}`;
  }
  if (widthPx >= 48) {
    return `${z.segNo ? `${z.segNo} ` : ''}${z.plainShortKo}${volTail}`;
  }
  return `${z.segNo ?? '·'} ${z.plainShortKo}`;
}

