export function buildVolumeSegmentMarkers(
  candles: Candle[],
  pack: VolumeAiZonePack
): import('@/lib/volumeHistogramIntelligence').VolumePanelMarker[] {
  const rows = sanitizeChartCandlesForSeries(candles);
  if (!pack.zones.length || !rows.length) return [];
  const out: import('@/lib/volumeHistogramIntelligence').VolumePanelMarker[] = [];
  const usedTimes = new Set<number>();

  for (const z of pack.zones.filter((x) => x.layer === 'cluster')) {
    const mid = Math.floor((z.fromIdx + z.toIdx) / 2);
    const c = rows[mid];
    if (!c) continue;
    const t = Number(c.time);
    if (usedTimes.has(t)) continue;
    usedTimes.add(t);
    out.push({
      time: c.time as import('lightweight-charts').UTCTimestamp,
      position: 'aboveBar',
      shape: 'square',
      color: z.color,
      text: shortVolumeMarkerText(z),
      size: z.segNo != null ? 1 : 0,
    });
  }

  for (const z of pack.zones.filter((x) => x.layer === 'trend' && x.bars >= 4)) {
    const c = rows[z.fromIdx];
    if (!c) continue;
    const t = Number(c.time);
    if (usedTimes.has(t)) continue;
    usedTimes.add(t);
    const mk = shortVolumeMarkerText(z);
    if (!mk) continue;
    out.push({
      time: c.time as import('lightweight-charts').UTCTimestamp,
      position: 'aboveBar',
      shape: 'square',
      color: z.color,
      text: mk,
      size: 0,
    });
  }

  return out.sort((a, b) => Number(a.time) - Number(b.time));
}

/** 차트 마커 — 번호만 (상세는 클릭 카드) */
export function shortVolumeMarkerText(z: VolumeAiZone): string {
  if (z.segNo != null) return String(z.segNo);
  if (z.kind === 'up') return '↑';
  if (z.kind === 'down') return '↓';
  return '';
}

