'use client';

import type { VolumeAiZoneScreenGeom } from '@/lib/volumeAiZoneEngine';

type Props = {
  zones: VolumeAiZoneScreenGeom[];
  volPanelTop: number;
  volPanelBot: number;
  selectedZoneId?: string | null;
  onZoneClick?: (zoneId: string) => void;
};

const LABEL_H = 22;

/** 거래량 막대 위 HTML 라벨 + 구간 박스 (차트 마커 보조) */
export function VolumeAiZoneDrawLayer({
  zones,
  volPanelTop,
  volPanelBot,
  selectedZoneId,
  onZoneClick,
}: Props) {
  const labeled = zones.filter((z) => z.layer === 'cluster' || (z.layer === 'trend' && z.barSpan >= 4));
  if (!labeled.length) return null;

  const h = Math.max(20, volPanelBot - volPanelTop - 4);
  const labelTop = Math.max(4, volPanelTop - LABEL_H);

  return (
    <div className="volume-ai-labels-root" aria-hidden={false}>
      {labeled.map((z) => {
        const cx = (z.x1 + z.x2) / 2;
        const selected = selectedZoneId === z.id;
        return (
          <button
            key={`lbl-${z.id}`}
            type="button"
            className={`volume-zone-label volume-zone-label--${z.kind}${selected ? ' volume-zone-label--on' : ''}${z.isLive ? ' volume-zone-label--live' : ''}`}
            style={{
              top: labelTop,
              left: cx,
              maxWidth: Math.max(72, z.widthPx + 24),
              borderColor: `${z.color}99`,
            }}
            title={z.plainSummaryKo || z.labelKo}
            onClick={() => onZoneClick?.(z.id)}
          >
            <span className="volume-zone-label__text">{z.visibleLabelKo}</span>
          </button>
        );
      })}
      <div
        className="volume-regime-panel volume-regime-panel--interactive"
        style={{ top: volPanelTop, height: h, bottom: 'auto' }}
      >
        <svg className="volume-regime-panel__svg" width="100%" height="100%" aria-hidden>
          {zones
            .filter((z) => z.layer === 'cluster')
            .map((z) => {
              const w = Math.max(24, z.x2 - z.x1);
              const selected = selectedZoneId === z.id;
              return (
                <g
                  key={z.id}
                  className={`volume-seg-box volume-seg-box--${z.kind}${selected ? ' volume-seg-box--selected' : ''}`}
                >
                  <rect
                    className="volume-seg-box__hit"
                    x={z.x1 - 2}
                    y={4}
                    width={w + 4}
                    height={h - 8}
                    fill={z.fill}
                    stroke={z.color}
                    strokeWidth={selected ? 2.2 : 1.5}
                    rx={3}
                    opacity={selected ? 0.72 : 0.45}
                    onClick={() => onZoneClick?.(z.id)}
                  />
                  <line
                    x1={z.x1 - 2}
                    y1={4}
                    x2={z.x2 + 2}
                    y2={4}
                    stroke={z.color}
                    strokeWidth={2}
                    pointerEvents="none"
                  />
                </g>
              );
            })}
        </svg>
      </div>
    </div>
  );
}

