/** RVOL·거래량 클러스터 (표시 1·2번 같은 구간) */
function detectVolumeClusters(
  rows: Candle[],
  meta: BarMeta[],
  fromScan: number
): Array<{ from: number; to: number }> {
  const n = rows.length;
  const clusters: Array<{ from: number; to: number }> = [];
  let i = fromScan;
  while (i < n) {
    const hot = meta[i]!.rvol >= 1.15 || meta[i]!.vol > 0;
    if (!hot || meta[i]!.rvol < 1.08) {
      i++;
      continue;
    }
    const start = i;
    let peakRvol = meta[i]!.rvol;
    while (i < n) {
      const m = meta[i]!;
      if (i > start + 16) break;
      if (m.rvol < 0.82 && i > start + 2) break;
      if (m.rvol < 0.95 && i > start + 5) break;
      peakRvol = Math.max(peakRvol, m.rvol);
      i++;
    }
    const end = i - 1;
    const bars = end - start + 1;
    const avgRvol =
      meta.slice(start, end + 1).reduce((s, x) => s + x.rvol, 0) / Math.max(1, bars);
    if (bars >= 2 && avgRvol >= 0.92) {
      clusters.push({ from: start, to: end });
    }
  }
  return clusters;
}

