  volPanelBot: number;
  selectedZoneId?: string | null;
  onZoneClick?: (zoneId: string) => void;
};

const RAIL_H = 24;

/** 거래량 패널 — 얇은 구간 밑줄 + 번호 뱃지 (막대 위 긴 글자 없음) */
export function VolumeAiZoneDrawLayer({
  zones,
  volPanelTop,
  volPanelBot,
  selectedZoneId,
  onZoneClick,
}: Props) {
  const clusters = zones.filter((z) => z.layer === 'cluster');
  if (!clusters.length) return null;

  const panelH = Math.max(20, volPanelBot - volPanelTop - RAIL_H - 4);
  const barTop = volPanelTop + RAIL_H + 2;
  const underlineY = barTop + panelH - 3;

  return (
    <div className="volume-ai-labels-root" aria-hidden={false}>
      <div
        className="volume-regime-panel volume-regime-panel--interactive volume-regime-panel--clean"
        style={{ top: barTop, height: panelH, bottom: 'auto' }}
      >
        <svg className="volume-regime-panel__svg volume-regime-panel__svg--clean" width="100%" height="100%" aria-hidden>
          {clusters.map((z) => {
            const w = Math.max(8, z.x2 - z.x1);
            const cx = (z.x1 + z.x2) / 2;
            const selected = selectedZoneId === z.id;
            const accent = z.verdictColor ?? z.color;
            return (
              <g
                key={z.id}
                className={`volume-seg-box volume-seg-box--${z.kind}${selected ? ' volume-seg-box--selected' : ''}`}
              >
                <rect
                  className="volume-seg-box__hit"
                  x={z.x1 - 1}
                  y={0}
                  width={w + 2}
                  height={panelH}
                  fill={selected ? `${accent}28` : `${accent}12`}
                  stroke={selected ? accent : `${accent}55`}
                  strokeWidth={selected ? 1.5 : 1}
                  rx={2}
                  opacity={selected ? 0.95 : 0.7}
                  onClick={() => onZoneClick?.(z.id)}
                />
                <line
                  x1={z.x1 - 1}
                  y1={panelH - 1}
                  x2={z.x2 + 1}
                  y2={panelH - 1}
                  stroke={accent}
                  strokeWidth={selected ? 3 : 2}
                  pointerEvents="none"
                />
                {z.segNo != null && (
                  <g
                    className="volume-seg-box__badge"
                    transform={`translate(${cx}, ${panelH - 10})`}
                    pointerEvents="none"
                  >
                    <circle r={7} fill="rgba(2,6,23,0.92)" stroke={accent} strokeWidth={1.2} />
                    <text
                      className="volume-seg-box__num"
                      textAnchor="middle"
                      dominantBaseline="central"
                      fontSize={8}
                      fill={accent}
                    >
                      {z.segNo}
                    </text>
                  </g>
                )}
              </g>
            );
          })}
          {clusters.map((z) => {
            const selected = selectedZoneId === z.id;
            if (!selected) return null;
            const accent = z.verdictColor ?? z.color;
            return (
              <line
                key={`ul-${z.id}`}
                x1={z.x1 - 2}
                y1={underlineY - barTop}
                x2={z.x2 + 2}
                y2={underlineY - barTop}
                stroke={accent}
                strokeWidth={3}
                strokeLinecap="round"
                opacity={0.9}
                pointerEvents="none"
              />
            );
          })}
        </svg>
      </div>
    </div>
  );
}

