        confidence: pct / 100,
        overlayZoneExtraClass: `${String(o.overlayZoneExtraClass || '')} ${df.cls}`.trim(),
      });
      continue;
    }

    if (id === 'merged-ares-mlsp-tv-major-support') {
      const bot = Math.min(Number(o.price1), Number(o.price2));
      const pct = computeSrHoldPct(candles, bot, 'support');
      const df = dirFace(true);
      out.push({
        ...o,
        label: `${df.prefix} · Support ${pct}%`,
        labelTooltip: `Support hold ${pct}%`,
        zoneFaceBase: `${df.prefix} · Support ${pct}%`,
        zoneFaceSignal: df.signal,
        zoneFaceLang: 'en' as const,
        structureBias: 'bullish',
        confidence: pct / 100,
        overlayZoneExtraClass: `${String(o.overlayZoneExtraClass || '')} ${df.cls}`.trim(),
      });
      continue;
    }

    if (id.includes('merged-ares-mlsp-tv-sr-res-') && kind === 'trendLine') {
      const pct = computeSrHoldPct(candles, Number(o.price1), 'resistance');
      out.push({ ...o, label: `Resistance ${pct}%`, labelTooltip: `Resistance ${pct}%`, confidence: pct / 100 });
      continue;
    }

    if (id.includes('merged-ares-mlsp-tv-sr-sup-') && kind === 'trendLine' && !id.includes('liq')) {
      const pct = computeSrHoldPct(candles, Number(o.price1), 'support');
      out.push({ ...o, label: `Support ${pct}%`, labelTooltip: `Support ${pct}%`, confidence: pct / 100 });
      continue;
    }

    if (id.includes('merged-ares-mlsp-tv-fvg')) {
      const bull = id.includes('bullish') || o.structureBias === 'bullish';
      const df = dirFace(bull);
      out.push({
        ...o,
        label: `${df.prefix} · FVG`,
        zoneFaceBase: `${df.prefix} · FVG`,
        zoneFaceSignal: 'GAP',
        zoneFaceLang: 'en' as const,
        structureBias: bull ? 'bullish' : 'bearish',
        overlayZoneExtraClass: `${String(o.overlayZoneExtraClass || '')} ${df.cls}`.trim(),
      });
      continue;
    }

    out.push(o);
  }
  return out;
}

