/**
 * PM2/crontab — 앱 미접속 서버 자동 텔레그램.
 *
 * - `telegramHqZoneTouchEnabled`(기본 ON): 고확률 롱/숏 진입존 터치 → PNG+메시지
 * - `telegramConfirmEnabled`: 레거시 롱/숏 확정 · ★타점 · TP (HQ OFF일 때만)
 * - `telegramMultiTfEnabled`: 레거시 HTF (HQ OFF일 때만)
 *
 * `Authorization: Bearer <TELEGRAM_MULTITF_CRON_SECRET>`
 *
 * 크론: `scripts/telegram-auto-alert-run.sh` (권장, 2~3분)
 */
async function runCron(req: NextRequest) {
  const expected = (process.env.TELEGRAM_MULTITF_CRON_SECRET || '').trim();
  if (!expected) {
    return NextResponse.json(
      { ok: false, error: 'TELEGRAM_MULTITF_CRON_SECRET not set' },
      { status: 503 }
    );
  }
  const bearer = req.headers.get('authorization')?.replace(/^Bearer\s+/i, '').trim() || '';
  const hdr = req.headers.get('x-telegram-cron-secret')?.trim() || '';
  if (bearer !== expected && hdr !== expected) {
    return NextResponse.json({ ok: false, error: 'unauthorized' }, { status: 401 });
  }

  const all = await readAllUserSettingsMap();
  const stats = await runTelegramAutoAlertAll(all);

  return NextResponse.json({
    ok: true,
    ...stats,
    note: 'hq=진입존터치(+PNG) · confirm/htf=레거시(HQ OFF시) · dedup=global eventKey',
  });
}

