export function scoreZoneExchangeTape(
  snapshot: MirageZoneExchangeSnapshot | null | undefined,
  centerPrice: number,
  role: ZoneRole
): { tapeScore: number | null; tapeLabelKo: string } {
  if (!snapshot?.trades?.length || !(centerPrice > 0)) {
    return { tapeScore: null, tapeLabelKo: '체결없음' };
  }
  const z = tradesAtPriceZone(snapshot.trades, centerPrice, 0.0035);
  if (z.tradeCount < 3) {
    return { tapeScore: null, tapeLabelKo: '표본부족' };
  }
  const bias = ruleBasedTapeBias(z.buyPressure, z.sellPressure);
  const expectBull = role === 'support' || role === 'ob_bull';
  const expectBear = role === 'resistance' || role === 'ob_bear';
  let tapeLabelKo = bias.label;
  if (expectBull && bias.score >= 58) tapeLabelKo = '매수우세';
  else if (expectBear && bias.score <= 42) tapeLabelKo = '매도우세';
  else if (expectBull && bias.score <= 42) tapeLabelKo = '매도압력';
  else if (expectBear && bias.score >= 58) tapeLabelKo = '매수압력';
  return { tapeScore: bias.score, tapeLabelKo };
}

