/**
 * 통합·분석 — 분·시·일·주·월(1m~1M) 전 TF 공통 기능.
 * 4h 참조 정책(`mergedDesk4hReference`)과 동일 경로.
 *
 * 공통 기능 목록 (전 TF):
 * - HQ 롱/숏 진입존 + 차트 존
 * - 스윙·중투 E/SL/TP · 추세선·채널
 * - CHoCH→OB 경로
 * - 되돌림 Fib 맵
 * - 마스터 선물 게이트
 * - 서버 진입존 터치 텔레(허용 TF 전부)
 */
import {
  MERGED_DESK_CHART_TIMEFRAMES,
  isMergedDeskChartTimeframe,
  type MergedDeskChartTimeframe,
} from '@/lib/mergedDesk4hReference';

export { MERGED_DESK_CHART_TIMEFRAMES, isMergedDeskChartTimeframe };
export type { MergedDeskChartTimeframe };

/** 텔레·크론·워처 — 통합분석 차트 TF와 동일 */
export const MERGED_DESK_SHARED_TELEGRAM_TFS = new Set<string>([...MERGED_DESK_CHART_TIMEFRAMES]);

export function isMergedDeskSharedFeatureTf(timeframe: string): boolean {
  return isMergedDeskChartTimeframe(timeframe);
}

/** 스윙 채널·추세선 — 전 TF 기본 ON (토글이 꺼져 있어도 엔진은 작도 가능) */
export const MERGED_DESK_SWING_CHANNEL_DEFAULT_ON = true;

/**
 * 통합·분석 UI — 글자 스트립/배너는 유지(사용자 지시 전 임의 숨김 금지).
 * 신규 정보는 차트 zone·선·추세선으로도 항상 작도.
 */
export const MERGED_DESK_CHART_DRAWING_ONLY = false;

/** 하단 스트립·배너 숨김 — 기본 OFF (임의 비표시 안 함) */
export function mergedDeskHideTextStrips(): boolean {
  return MERGED_DESK_CHART_DRAWING_ONLY;
}

/** 플로팅 HUD 숨김 — 기본 OFF */
export function mergedDeskHideFloatingTextHud(): boolean {
  return MERGED_DESK_CHART_DRAWING_ONLY;
}

/** 스윙 채널·추세선 전 TF 작도 */
export function mergedDeskAlwaysDrawSwingChannel(): boolean {
  return true;
}

