    const swingOverlays = swingDrawEnabled
      ? swingPack.overlays
      : swingPack.overlays.filter((o) => {
          const id = String(o.id || '');
          return (
            id.includes('channel') ||
            id.includes('swing') ||
            o.kind === 'channelBand' ||
            o.kind === 'trendLine'
          );
        });
    if (swingOverlays.length) {
      chartOverlays = dedupeMergedDeskOverlays([...chartOverlays, ...swingOverlays]);
