/**
 * 통합·분석 — HotZone(볼륨 레이더) + HQ/스윙 합류 → 핵심 롱/숏 진입 구간.
 * HOT_ZONE 모드 최적화를 4h 참조로 전 TF에 적용. 승률·수익 보장 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import { normalizeChartTimeframe } from '@/lib/constants';
import {
  buildVolumeHotZoneClustersFromArr,
  type HotZoneVolumeCluster,
} from '@/lib/hotZoneRadar';
import {
  hotZoneFillForSignal,
  resolveHotZoneClusterSignal,
} from '@/lib/monthDeskZoneSignalPalette';
import {
  MERGED_DESK_4H_REF_BAR_CAP,
  isMergedDeskChartTimeframe,
} from '@/lib/mergedDesk4hReference';
import { isMergedDeskSharedFeatureTf } from '@/lib/mergedDeskSharedTfFeatures';
import {
  mergedDeskLastCandleZoneTimes,
  mergedWorkCandles,
} from '@/lib/mergedAnalysisOverlayTimes';
import type { HqEntryZonesPack, HqEntryZone } from '@/lib/mergedDeskHqEntryZones';
import type { SwingMidEntryPack } from '@/lib/mergedDeskSwingMidEntry';

export type MergedDeskHotZoneEntry = {
  id: string;
  side: 'LONG' | 'SHORT';
  grade: 'A' | 'B';
  top: number;
  bot: number;
  mid: number;
  score: number;
  strength: number;
  labelKo: string;
  reasonKo: string;
  primary: boolean;
  touchedNow: boolean;
  sources: string[];
};

export type MergedDeskHotZoneEntryPack = {
  longEntries: MergedDeskHotZoneEntry[];
  shortEntries: MergedDeskHotZoneEntry[];
  all: MergedDeskHotZoneEntry[];
  overlays: OverlayItem[];
  summaryKo: string;
  whereLongKo: string;
  whereShortKo: string;
};

function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}

function fmt(p: number): string {
  if (!(p > 0)) return '—';
  if (p >= 1000) return p.toFixed(1);
  if (p >= 1) return p.toFixed(2);
  return p.toFixed(4);
}

function atr(candles: Candle[], end: number, period = 14): number {
  if (end < 1) return Math.abs(candles[end]?.close ?? 1) * 0.01;
  let sum = 0;
  let n = 0;
  const start = Math.max(1, end - period + 1);
  for (let i = start; i <= end; i++) {
    const c = candles[i]!;
    const p = candles[i - 1]!;
    sum += Math.max(c.high - c.low, Math.abs(c.high - p.close), Math.abs(c.low - p.close));
    n++;
  }
  return n > 0 ? sum / n : Math.abs(candles[end]?.close ?? 1) * 0.01;
}

function enrichHorizon(
  clusters: HotZoneVolumeCluster[],
  arr: Candle[],
  horizon: number
): void {
  if (arr.length < horizon + 20 || !clusters.length) return;
  const top = [...clusters].sort((a, b) => b.strength - a.strength).slice(0, 4);
  for (const z of top) {
    let longCnt = 0;
    let shortCnt = 0;
    for (let j = 0; j < arr.length - horizon; j++) {
      const c = arr[j]!;
      if (c.close < z.bot || c.close > z.top) continue;
      const ret = (arr[j + horizon]!.close - c.close) / Math.max(1e-9, c.close);
      if (ret >= 0) longCnt++;
      else shortCnt++;
    }
    const n = longCnt + shortCnt;
    if (n < 8) continue;
    z.longProb = longCnt / n;
    z.shortProb = shortCnt / n;
    z.probSampleN = n;
  }
}

function overlaps(aTop: number, aBot: number, bTop: number, bBot: number, tol: number): boolean {
  const top = Math.min(aTop, bTop);
  const bot = Math.max(aBot, bBot);
  return top - bot > -tol;
}

function hqBoost(
  side: 'LONG' | 'SHORT',
  top: number,
  bot: number,
  hq: HqEntryZonesPack | null | undefined,
  atrVal: number
): { boost: number; bits: string[]; sources: string[] } {
  if (!hq?.all?.length) return { boost: 0, bits: [], sources: [] };
  let boost = 0;
  const bits: string[] = [];
  const sources: string[] = [];
  for (const z of hq.all) {
    if (z.side !== side) continue;
    if (!overlaps(top, bot, z.top, z.bot, atrVal * 0.35)) continue;
    const add = z.grade === 'A' ? 18 : 12;
    boost += add;
    bits.push(`HQ${z.grade}`);
    sources.push('HQ');
    for (const s of z.sources) {
      if (!sources.includes(s)) sources.push(s);
    }
  }
  return { boost: Math.min(28, boost), bits, sources };
}

function swingBoost(
  side: 'LONG' | 'SHORT',
  top: number,
  bot: number,
  swing: SwingMidEntryPack | null | undefined,
  atrVal: number
): { boost: number; bits: string[] } {
  if (!swing?.active || swing.side !== side) return { boost: 0, bits: [] };
  if (!(swing.entryHigh > swing.entryLow)) return { boost: 0, bits: [] };
  if (!overlaps(top, bot, swing.entryHigh, swing.entryLow, atrVal * 0.4)) {
    return { boost: 0, bits: [] };
  }
  const go = swing.stance === 'ENTER_LONG' || swing.stance === 'ENTER_SHORT';
  return { boost: go ? 16 : 10, bits: [go ? '스윙진입' : '스윙대기'] };
}

function fromHqFallback(
  z: HqEntryZone,
  primarySide: 'LONG' | 'SHORT' | 'WAIT',
  atrVal: number,
  price: number
): MergedDeskHotZoneEntry {
  const mid = z.mid;
  const half = Math.max((z.top - z.bot) / 2, atrVal * 0.28);
  const top = mid + half;
  const bot = mid - half;
  const primary = primarySide === z.side;
  return {
    id: `merged-desk-hotzone-${z.side.toLowerCase()}-hq-${Math.round(mid * 100)}`,
    side: z.side,
    grade: z.grade,
    top,
    bot,
    mid,
    score: z.score,
    strength: clamp(z.score / 100, 0.35, 0.95),
    labelKo: primary
      ? `★${z.side === 'LONG' ? '롱진입' : '숏진입'} ${z.grade}`
      : `${z.side === 'LONG' ? '롱진입' : '숏진입'} ${z.grade}`,
    reasonKo: z.reasonKo,
    primary,
    touchedNow: z.touchedNow || (price >= bot && price <= top),
    sources: z.sources.length ? z.sources : ['HQ'],
  };
}

function emptyPack(): MergedDeskHotZoneEntryPack {
  return {
    longEntries: [],
    shortEntries: [],
    all: [],
    overlays: [],
    summaryKo: 'HotZone 진입 — 대기',
    whereLongKo: '롱진입 구간 없음 (관망)',
    whereShortKo: '숏진입 구간 없음 (관망)',
  };
}

/**
 * 통합분석 차트용 — 핵심 롱/숏 진입 HotZone (최대 각 2개).
 */
export function buildMergedDeskHotZoneEntryPack(params: {
  candles: Candle[];
  timeframe: string;
  hqEntryZones?: HqEntryZonesPack | null;
  swingMidEntry?: SwingMidEntryPack | null;
  masterSide?: 'LONG' | 'SHORT' | 'WAIT' | null;
  analyzeVerdict?: 'LONG' | 'SHORT' | null;
  currentPrice?: number | null;
}): MergedDeskHotZoneEntryPack {
  if (!isMergedDeskSharedFeatureTf(params.timeframe) && !isMergedDeskChartTimeframe(params.timeframe)) {
    return emptyPack();
  }

  const tf = normalizeChartTimeframe(params.timeframe);
  const candles = mergedWorkCandles(params.candles, tf);
  if (candles.length < 30) return emptyPack();

  const last = candles[candles.length - 1]!;
  const price =
    params.currentPrice && params.currentPrice > 0 ? params.currentPrice : last.close;
  const atrVal = atr(candles, candles.length - 1);
  const primarySide =
    params.swingMidEntry?.side === 'LONG' || params.swingMidEntry?.side === 'SHORT'
      ? params.swingMidEntry.side
      : params.masterSide === 'LONG' || params.masterSide === 'WAIT'
        ? params.masterSide === 'WAIT'
          ? 'WAIT'
          : 'LONG'
        : params.masterSide === 'SHORT'
          ? 'SHORT'
          : params.analyzeVerdict ?? 'WAIT';

  const verdict: 'LONG' | 'SHORT' | null =
    primarySide === 'LONG' || primarySide === 'SHORT'
      ? primarySide
      : params.analyzeVerdict ?? null;

  const lookback = Math.min(MERGED_DESK_4H_REF_BAR_CAP, candles.length, 220);
  const arr = candles.slice(-lookback);
  const resolution = 42;
  const thresholdPct = 76;
  const clusters = buildVolumeHotZoneClustersFromArr(arr, resolution, thresholdPct) ?? [];
  enrichHorizon(clusters, arr, 3);

  const recentBars = arr.slice(-8).map((c) => ({
    open: c.open,
    close: c.close,
    high: c.high,
    low: c.low,
  }));

  const maxH = Math.max(atrVal * 1.35, price * 0.012);
  const cands: MergedDeskHotZoneEntry[] = [];

  for (const z of clusters) {
    const sig = resolveHotZoneClusterSignal(
      {
        bot: z.bot,
        top: z.top,
        center: z.center,
        fullH: z.fullH,
        inside: z.inside,
        longProb: z.longProb,
        shortProb: z.shortProb,
        probSampleN: z.probSampleN,
      },
      recentBars,
      verdict
    );
    if (sig === 'WAIT') continue;

    let top = z.top;
    let bot = z.bot;
    if (top - bot > maxH) {
      const mid = z.center;
      top = mid + maxH / 2;
      bot = mid - maxH / 2;
    }
    if (!(top > bot)) continue;

    const hq = hqBoost(sig, top, bot, params.hqEntryZones, atrVal);
    const sw = swingBoost(sig, top, bot, params.swingMidEntry, atrVal);
    let score = 48 + Math.round(z.strength * 28);
    if (z.longProb != null && z.shortProb != null && (z.probSampleN ?? 0) >= 8) {
      const edge = Math.abs(z.longProb - z.shortProb);
      score += Math.round(edge * 22);
      if ((sig === 'LONG' && z.longProb >= z.shortProb) || (sig === 'SHORT' && z.shortProb >= z.longProb)) {
        score += 6;
      }
    }
    score += hq.boost + sw.boost;
    if (verdict === sig) score += 8;
    if (z.inside) score += 5;
    score = clamp(Math.round(score), 0, 99);
    if (score < 58) continue;

    const grade: 'A' | 'B' = score >= 72 ? 'A' : 'B';
    const mid = (top + bot) / 2;
    const touchedNow = price >= bot && price <= top;
    const bits = [
      '볼륨Hot',
      ...hq.bits,
      ...sw.bits,
      z.inside ? '내부' : '',
    ].filter(Boolean);
    const primary = primarySide === sig;
    cands.push({
      id: `merged-desk-hotzone-${sig.toLowerCase()}-${Math.round(mid * 100)}-${grade}`,
      side: sig,
      grade,
      top,
      bot,
      mid,
      score,
      strength: z.strength,
      labelKo: primary
        ? `★${sig === 'LONG' ? '롱진입' : '숏진입'} ${grade}`
        : `${sig === 'LONG' ? '롱진입' : '숏진입'} ${grade}`,
      reasonKo: bits.join(' · '),
      primary,
      touchedNow,
      sources: ['HotZone', ...hq.sources],
    });
  }

  // 볼륨 클러스터가 약하면 HQ를 HotZone 스타일로 승격
  if (cands.filter((c) => c.side === 'LONG').length === 0) {
    for (const z of params.hqEntryZones?.longZones ?? []) {
      cands.push(fromHqFallback(z, primarySide === 'WAIT' ? 'WAIT' : primarySide, atrVal, price));
    }
  }
  if (cands.filter((c) => c.side === 'SHORT').length === 0) {
    for (const z of params.hqEntryZones?.shortZones ?? []) {
      cands.push(fromHqFallback(z, primarySide === 'WAIT' ? 'WAIT' : primarySide, atrVal, price));
    }
  }

  // 스윙 ★ENTRY가 있으면 반드시 포함
  const swing = params.swingMidEntry;
  if (swing?.active && (swing.side === 'LONG' || swing.side === 'SHORT') && swing.entryHigh > swing.entryLow) {
    const side = swing.side;
    const exists = cands.some(
      (c) =>
        c.side === side &&
        overlaps(c.top, c.bot, swing.entryHigh, swing.entryLow, atrVal * 0.5)
    );
    if (!exists) {
      const mid = swing.entryMid || (swing.entryHigh + swing.entryLow) / 2;
      const go = swing.stance === 'ENTER_LONG' || swing.stance === 'ENTER_SHORT';
      cands.push({
        id: `merged-desk-hotzone-${side.toLowerCase()}-swing-${Math.round(mid * 100)}`,
        side,
        grade: swing.grade === 'A' || swing.grade === 'B' ? swing.grade : 'B',
        top: swing.entryHigh,
        bot: swing.entryLow,
        mid,
        score: clamp(58 + swing.confluence * 4, 60, 96),
        strength: 0.85,
        labelKo: `★${side === 'LONG' ? '롱진입' : '숏진입'} 핵심`,
        reasonKo: swing.whereKo || '스윙·중투 합류',
        primary: true,
        touchedNow: price >= swing.entryLow && price <= swing.entryHigh,
        sources: ['스윙', 'HotZone'],
      });
      if (go) {
        for (const c of cands) {
          if (c.side === side) c.primary = c.id.includes('swing') || c.primary;
        }
      }
    }
  }

  cands.sort((a, b) => {
    if (a.primary !== b.primary) return a.primary ? -1 : 1;
    return b.score - a.score;
  });

  const longEntries = cands.filter((c) => c.side === 'LONG').slice(0, 2);
  const shortEntries = cands.filter((c) => c.side === 'SHORT').slice(0, 2);
  const all = [...longEntries, ...shortEntries].sort((a, b) => {
    if (a.primary !== b.primary) return a.primary ? -1 : 1;
    return b.score - a.score;
  });

  const zoneTimes = mergedDeskLastCandleZoneTimes(candles, tf);
  const overlays: OverlayItem[] = [];

  for (const z of all) {
    const isLong = z.side === 'LONG';
    const fill = hotZoneFillForSignal(isLong ? 'LONG' : 'SHORT', z.touchedNow, z.strength);
    overlays.push({
      id: z.id,
      kind: isLong ? 'demandZone' : 'supplyZone',
      label: z.labelKo,
      labelTooltip: `${z.reasonKo} · ${fmt(z.bot)}~${fmt(z.top)} · 합류 ${z.sources.join('+')} (승률 아님)`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: zoneTimes.t1 as UTCTimestamp,
      time2: zoneTimes.t2 as UTCTimestamp,
      price1: z.top,
      price2: z.bot,
      confidence: z.score,
      color: fill,
      category: 'scenario',
      zonePulse: z.primary || z.touchedNow || z.grade === 'A',
      zoneFillPreserve: true,
      lineLabelColor: isLong ? '#bbf7d0' : '#fecaca',
      labelBackgroundColor: isLong ? 'rgba(6,78,59,0.95)' : 'rgba(127,29,29,0.95)',
      labelTextColor: '#f8fafc',
      overlayZoneExtraClass: [
        'merged-desk-hotzone-entry',
        'overlay-zone--hotzone-radar',
        'overlay-zone--monthdesk-hotzone-entry',
        isLong ? 'overlay-zone--hotzone-signal--long' : 'overlay-zone--hotzone-signal--short',
        z.primary ? 'merged-desk-hotzone-entry--primary' : '',
        z.touchedNow ? 'merged-desk-hotzone-entry--touch' : '',
      ]
        .filter(Boolean)
        .join(' '),
    });

    // 핵심 진입가 중앙선
    if (z.primary || z.grade === 'A') {
      overlays.push({
        id: `${z.id}-mid`,
        kind: 'keyLevel',
        label: isLong ? '롱 E' : '숏 E',
        x1: 0,
        y1: 0,
        x2: 1,
        y2: 0,
        time1: zoneTimes.t1 as UTCTimestamp,
        time2: zoneTimes.t2 as UTCTimestamp,
        price1: z.mid,
        price2: z.mid,
        confidence: z.score,
        color: isLong ? 'rgba(74,222,128,0.95)' : 'rgba(248,113,113,0.95)',
        category: 'scenario',
        lineLabelColor: isLong ? '#86efac' : '#fca5a5',
        labelBackgroundColor: 'rgba(8,12,28,0.9)',
        labelTextColor: '#f8fafc',
        overlayZoneExtraClass: 'merged-desk-hotzone-entry-mid merged-desk-trade-rail-prominent',
      });
    }
  }

  const whereLongKo =
    longEntries.length === 0
      ? '롱진입 구간 없음 (관망)'
      : longEntries
          .map(
            (z) =>
              `${z.labelKo} ${fmt(z.bot)}~${fmt(z.top)}${z.touchedNow ? ' ←터치' : ''} (${z.reasonKo})`
          )
          .join(' · ');

  const whereShortKo =
    shortEntries.length === 0
      ? '숏진입 구간 없음 (관망)'
      : shortEntries
          .map(
            (z) =>
              `${z.labelKo} ${fmt(z.bot)}~${fmt(z.top)}${z.touchedNow ? ' ←터치' : ''} (${z.reasonKo})`
          )
          .join(' · ');

  const best = all[0];
  const summaryKo = best
    ? `HotZone 진입 ${all.length} · 우선 ${best.labelKo} @ ${fmt(best.mid)} · ${best.reasonKo}`
    : 'HotZone 롱/숏 진입 — 합류 대기';

  return {
    longEntries,
    shortEntries,
    all,
    overlays,
    summaryKo,
    whereLongKo,
    whereShortKo,
  };
}

