// 볼륨 시그널이 WAIT여도 가격 대비 아래=롱후보 / 위=숏후보로 최소 1개씩 보강
if (!cands.length && clusters.length) {
  const sorted = [...clusters].sort((a, b) => b.strength - a.strength);
  for (const z of sorted.slice(0, 4)) {
    const mid = z.center;
    const side: 'LONG' | 'SHORT' = mid <= price ? 'LONG' : 'SHORT';
    let top = z.top;
    let bot = z.bot;
    if (top - bot > maxH) {
      top = mid + maxH / 2;
      bot = mid - maxH / 2;
    }
    const hq = hqBoost(side, top, bot, params.hqEntryZones, atrVal);
    const score = clamp(54 + Math.round(z.strength * 20) + hq.boost, 52, 88);
    cands.push({
      id: `merged-desk-hotzone-${side.toLowerCase()}-vol-${Math.round(mid * 100)}`,
      side,
      grade: score >= 72 ? 'A' : 'B',
      top,
      bot,
      mid,
      score,
      strength: z.strength,
      labelKo: `★${side === 'LONG' ? '롱진입' : '숏진입'} ${score >= 72 ? 'A' : 'B'}`,
      reasonKo: ['볼륨Hot', ...hq.bits].filter(Boolean).join(' · ') || '볼륨 밀집',
      primary: primarySide === side,
      touchedNow: price >= bot && price <= top,
      sources: ['HotZone', ...hq.sources],
    });
  }
}

// 볼륨 클러스터가 약하면 HQ를 HotZone 스타일로 승격
if (cands.filter((c) => c.side === 'LONG').length === 0) {
  for (const z of params.hqEntryZones?.longZones ?? []) {
    cands.push(fromHqFallback(z, primarySide, atrVal, price));
  }
}
if (cands.filter((c) => c.side === 'SHORT').length === 0) {
  for (const z of params.hqEntryZones?.shortZones ?? []) {
    cands.push(fromHqFallback(z, primarySide, atrVal, price));
  }
}

