  const lines: string[] = [];
  const seen = new Set<string>();
  const pushLine = (s: string) => {
    const t = s.trim();
    if (!t || seen.has(t)) return;
    seen.add(t);
    lines.push(t);
  };
  pushLine(ROLE_INTRO[role]);
  for (const e of evidence.slice(0, 5)) pushLine(e.textKo);

  const distanceKo = rel.inside
    ? '가격이 이 존 안에 있어요 (터치 중)'
    : rel.side === 'above'
