    warnLine = `무효화: 종가 ${fmt(top)} 돌파 시 막힘 실패로 볼 수 있음`;
  }

  return {
    title: ROLE_TITLE[role],
    enLabel,
    lines: lines.slice(0, 5),
    priceLine: `가격대 ${fmt(bot)} ~ ${fmt(top)}`,
    warnLine,
