/**
 * Bitget USDT-M 선물 최근 체결 (공개 API · 키 불필요).
 * side buy/sell → AggTrade.isBuyerMaker (매수 체결 = false).
 */
import type { AggTrade } from '@/lib/data/collectors/tradesCollector';

type BitgetFillRow = {
  tradeId?: string;
  price?: string;
  size?: string;
  side?: string;
  ts?: string;
};

export async function collectBitgetFuturesFills(
  symbol: string,
  options?: { limit?: number }
): Promise<AggTrade[]> {
  const lim = Math.min(100, Math.max(1, options?.limit ?? 100));
  const sym = symbol.toUpperCase().replace(/[^A-Z0-9]/g, '') || 'BTCUSDT';
  const q = new URLSearchParams({
    symbol: sym,
    productType: 'USDT-FUTURES',
    limit: String(lim),
  });
  const res = await fetch(`https://api.bitget.com/api/v2/mix/market/fills?${q}`, {
    cache: 'no-store',
  });
  if (!res.ok) throw new Error(`bitget fills ${res.status}`);
  const j = (await res.json()) as { code?: string; data?: BitgetFillRow[] };
  if (j.code && j.code !== '00000') throw new Error(`bitget fills code ${j.code}`);
  const rows = Array.isArray(j.data) ? j.data : [];
  return rows
    .map((t) => {
      const price = Number(t.price);
      const qty = Number(t.size);
      const ts = Number(t.ts);
      const side = String(t.side || '').toLowerCase();
      if (!(price > 0) || !(qty > 0) || !Number.isFinite(ts)) return null;
      return {
        time: ts,
        price,
        qty,
        // buy = taker buy → isBuyerMaker false
        isBuyerMaker: side === 'sell',
      } satisfies AggTrade;
    })
    .filter((x): x is AggTrade => !!x);
}

input.new_string:
export function mirageZonesFromOverlays(overlays: OverlayItem[]): MirageZoneIntelRequestZone[] {
  const out: MirageZoneIntelRequestZone[] = [];
  const seen = new Set<string>();
  for (const o of overlays) {
    const id = String(o.id || '');
    if (!id || seen.has(id)) continue;
    const kind = String(o.kind || '');
    const extra = String(o.overlayZoneExtraClass || '');
    const isMirage = isMergedDeskMirageTvZoneOverlay(o) && kind === 'zone';
    const isHot =
      id.startsWith('merged-desk-hotzone-') ||
      extra.includes('merged-desk-hotzone-entry') ||
      extra.includes('merged-desk-hotzone-pair');
    const isSupportLike =
      extra.includes('merged-desk-projected-support') ||
      extra.includes('merged-desk-downside-plan-support') ||
      extra.includes('merged-ares-bounce-path');
    if (!isMirage && !isHot && !isSupportLike) continue;
    if (
      kind !== 'zone' &&
      kind !== 'demandZone' &&
      kind !== 'supplyZone'
    ) {
      continue;
    }
    const p1 = Number(o.price1);
    const p2 = Number(o.price2);
    if (!Number.isFinite(p1) || !Number.isFinite(p2)) continue;
    const top = Math.max(p1, p2);
    const bot = Math.min(p1, p2);
    if (!(top > bot) || !(bot > 0)) continue;
    seen.add(id);
    out.push({
      id,
      center: (top + bot) / 2,
      top,
      bot,
      role: inferMirageZoneRole(o),
    });
  }
  return out;
}

