          : `매수·매도 혼조 (매수 ${buyPct}%)`,
    zoneBuyPct: buyPct,
    zoneSellPct: sellPct,
    sampleN,
  };
}

return NextResponse.json({
  ok: true,
  symbol,
  timeframe,
  currentPrice: market.currentPrice,
  tape: {
    buyPressure: vd.buyPressure,
