/**
 * TV 캡처형 구조 롱/숏 — EMA 리본(8/55) + EMA200 매크로 + structureMarksFu(BOS/CHOCH/MSB).
 * 과거 “잘 오르고/내리는” 구간에서 보이던 L·S 핀·현재 스탠스를 참고용으로 표시.
 * 확정 매매·고정 승률 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import { ema } from '@/lib/indicators';
import { structureMarksFu } from '@/lib/smcDeskOverlay';
import type { AtlasPulseMarker } from '@/lib/monthDeskAtlasPulseDesk';
import type { UTCTimestamp } from 'lightweight-charts';

const ID_PREFIX = 'merged-desk-tv-ls';
const CAT: OverlayItem['category'] = 'smcDesk';

export type TvStructureLsStance = 'LONG' | 'SHORT' | 'WAIT';

export type TvStructureLsSignal = {
  index: number;
  time: number;
  price: number;
  side: 'LONG' | 'SHORT';
  tag: 'BOS' | 'CHOCH' | 'MSB';
  reasonKo: string;
};

export type TvStructureLongShortPack = {
  overlays: OverlayItem[];
  markers: AtlasPulseMarker[];
  stance: TvStructureLsStance;
  summaryKo: string;
  signals: TvStructureLsSignal[];
  live: {
    entry: number;
    stopLoss: number;
    tp1: number;
    invalidation: number;
  } | null;
};

function lastFinite(arr: number[], i: number): number | null {
  const v = arr[i];
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

function atrAt(candles: Candle[], i: number, period = 14): number {
  const start = Math.max(1, i - period + 1);
  let sum = 0;
  let n = 0;
  for (let k = start; k <= i; k++) {
    const prev = candles[k - 1];
    const c = candles[k]!;
    const tr = prev
      ? Math.max(c.high - c.low, Math.abs(c.high - prev.close), Math.abs(c.low - prev.close))
      : c.high - c.low;
    sum += tr;
    n += 1;
  }
  return n > 0 ? sum / n : Math.max(candles[i]!.high - candles[i]!.low, 1e-8);
}

function recentMarkBefore(
  marks: Array<{ index: number; price: number; tag: 'BOS' | 'CHOCH' | 'MSB'; bias: 'bullish' | 'bearish' }>,
  i: number,
  maxAgeBars: number
) {
  let best: (typeof marks)[number] | null = null;
  for (let k = marks.length - 1; k >= 0; k--) {
    const m = marks[k]!;
    if (m.index > i) continue;
    if (i - m.index > maxAgeBars) break;
    best = m;
    break;
  }
  return best;
}

/**
 * 캡처 규칙 요약:
 * - 롱: 종가 > EMA200 + 리본 상승(EMA8≥EMA55) + 최근 상승 CHOCH/BOS/MSB + MA 리본 터치 후 반등 종가
 * - 숏: 종가 < EMA200 + 리본 하락 + 최근 하락 구조 + MA 리본 터치 후 거부 종가
 */
export function buildTvStructureLongShortPack(params: {
  candles: Candle[];
  swingPivot?: number;
  /** 과거 핀 최대 개수 */
  maxSignals?: number;
  /** 구조 마크 최대 */
  maxMarks?: number;
}): TvStructureLongShortPack {
  const candles = params.candles;
  const n = candles.length;
  const empty: TvStructureLongShortPack = {
    overlays: [],
    markers: [],
    stance: 'WAIT',
    summaryKo: 'TV구조 롱숏: 캔들 부족 — 관망(참고).',
    signals: [],
    live: null,
  };
  if (n < 80) return empty;

  const L = Math.max(2, Math.min(4, Math.round(params.swingPivot ?? 2)));
  const maxSignals = Math.max(8, Math.min(48, params.maxSignals ?? 28));
  const maxMarks = Math.max(24, Math.min(120, params.maxMarks ?? 80));
  const closes = candles.map((c) => c.close);
  const e8 = ema(closes, 8);
  const e21 = ema(closes, 21);
  const e55 = ema(closes, 55);
  const e200 = ema(closes, 200);
  const marks = structureMarksFu(candles, L, maxMarks);

  const signals: TvStructureLsSignal[] = [];
  let lastSigIdx = -999;

  for (let i = 60; i < n; i++) {
    const c = candles[i]!;
    const ma8 = lastFinite(e8, i);
    const ma21 = lastFinite(e21, i);
    const ma55 = lastFinite(e55, i);
    const ma200 = lastFinite(e200, i);
    if (ma8 == null || ma21 == null || ma55 == null || ma200 == null) continue;

    const ribbonBull = ma8 >= ma55;
    const macroBull = c.close > ma200;
    const macroBear = c.close < ma200;
    const mk = recentMarkBefore(marks, i, 28);
    if (!mk) continue;

    const atr = atrAt(candles, i, 14);
    const touchEps = Math.max(atr * 0.35, c.close * 0.0008);
    const touchedRibbon =
      c.low <= ma8 + touchEps ||
      c.low <= ma21 + touchEps ||
      c.low <= ma55 + touchEps ||
      c.high >= ma8 - touchEps ||
      c.high >= ma21 - touchEps ||
      c.high >= ma55 - touchEps;

    const bounceLong =
      touchedRibbon &&
      c.close >= ma8 &&
      c.close > c.open &&
      (c.low <= ma21 + touchEps || c.low <= ma55 + touchEps || c.low <= ma8 + touchEps);

    const rejectShort =
      touchedRibbon &&
      c.close <= ma8 &&
      c.close < c.open &&
      (c.high >= ma21 - touchEps || c.high >= ma55 - touchEps || c.high >= ma8 - touchEps);

    const longOk =
      macroBull &&
      ribbonBull &&
      mk.bias === 'bullish' &&
      (mk.tag === 'CHOCH' || mk.tag === 'BOS' || mk.tag === 'MSB') &&
      bounceLong;

    const shortOk =
      macroBear &&
      !ribbonBull &&
      mk.bias === 'bearish' &&
      (mk.tag === 'CHOCH' || mk.tag === 'BOS' || mk.tag === 'MSB') &&
      rejectShort;

    if (!longOk && !shortOk) continue;
    if (i - lastSigIdx < 3) continue;

    const side: 'LONG' | 'SHORT' = longOk ? 'LONG' : 'SHORT';
    // 동시 충족 시 매크로·구조 쪽이 더 강한 쪽만
    if (longOk && shortOk) continue;

    lastSigIdx = i;
    signals.push({
      index: i,
      time: c.time as number,
      price: c.close,
      side,
      tag: mk.tag,
      reasonKo:
        side === 'LONG'
          ? `EMA200↑·리본↑·${mk.tag}↑·MA터치 반등(참고)`
          : `EMA200↓·리본↓·${mk.tag}↓·MA터치 거부(참고)`,
    });
  }

  const trimmed = signals.slice(-maxSignals);
  const last = candles[n - 1]!;
  const iLast = n - 1;
  const ma8L = lastFinite(e8, iLast);
  const ma21L = lastFinite(e21, iLast);
  const ma55L = lastFinite(e55, iLast);
  const ma200L = lastFinite(e200, iLast);
  const mkLive = recentMarkBefore(marks, iLast, 36);
  const atrL = atrAt(candles, iLast, 14);

  let stance: TvStructureLsStance = 'WAIT';
  let live: TvStructureLongShortPack['live'] = null;

  if (ma8L != null && ma21L != null && ma55L != null && ma200L != null && mkLive) {
    const ribbonBull = ma8L >= ma55L;
    const macroBull = last.close > ma200L;
    const macroBear = last.close < ma200L;
    const nearRibbon =
      Math.abs(last.close - ma8L) <= atrL * 1.2 ||
      Math.abs(last.close - ma21L) <= atrL * 1.2 ||
      Math.abs(last.low - ma55L) <= atrL * 1.4 ||
      Math.abs(last.high - ma55L) <= atrL * 1.4;

    if (macroBull && ribbonBull && mkLive.bias === 'bullish' && nearRibbon) {
      stance = 'LONG';
      const entry = Math.min(last.close, ma8L, ma21L);
      const stopLoss = Math.min(last.low, ma55L) - atrL * 0.6;
      const risk = Math.max(entry - stopLoss, atrL * 0.5);
      live = {
        entry,
        stopLoss,
        tp1: entry + risk * 1.8,
        invalidation: stopLoss,
      };
    } else if (macroBear && !ribbonBull && mkLive.bias === 'bearish' && nearRibbon) {
      stance = 'SHORT';
      const entry = Math.max(last.close, ma8L, ma21L);
      const stopLoss = Math.max(last.high, ma55L) + atrL * 0.6;
      const risk = Math.max(stopLoss - entry, atrL * 0.5);
      live = {
        entry,
        stopLoss,
        tp1: entry - risk * 1.8,
        invalidation: stopLoss,
      };
    } else if (trimmed.length) {
      const lastSig = trimmed[trimmed.length - 1]!;
      if (iLast - lastSig.index <= 6) stance = lastSig.side;
    }
  }

  const overlays: OverlayItem[] = [];
  const markers: AtlasPulseMarker[] = [];

  for (const s of trimmed) {
    const isLong = s.side === 'LONG';
    overlays.push({
      id: `${ID_PREFIX}-pin-${s.side.toLowerCase()}-${s.time}`,
      kind: 'label',
      label: isLong ? 'L' : 'S',
      x1: 0,
      y1: 0,
      time1: s.time,
      price1: s.price,
      confidence: 52,
      color: isLong ? '#16A34A' : '#DC2626',
      lineLabelColor: isLong ? '#DCFCE7' : '#FEE2E2',
      labelBackgroundColor: isLong ? 'rgba(22,163,74,0.92)' : 'rgba(185,28,28,0.92)',
      labelTextColor: '#FFFFFF',
      category: CAT,
      structureBias: isLong ? 'bullish' : 'bearish',
      labelTooltip: `${s.reasonKo} · 참고용(확정 신호 아님)`,
    });
    markers.push({
      time: s.time as UTCTimestamp,
      position: isLong ? 'belowBar' : 'aboveBar',
      shape: 'square',
      color: isLong ? '#22C55E' : '#F87171',
      text: isLong ? 'L' : 'S',
      size: 1,
      id: `${ID_PREFIX}-mk-${s.side.toLowerCase()}-${s.time}`,
    });
  }

  // 최근 구조 레벨 가로선(캡처의 BOS/CHoCH 점선 느낌) — 최근 6개만
  const recentMarks = marks.slice(-6);
  for (const mk of recentMarks) {
    const c = candles[mk.index];
    if (!c) continue;
    const bull = mk.bias === 'bullish';
    const t1 = c.time as number;
    const t2 = last.time as number;
    overlays.push({
      id: `${ID_PREFIX}-lvl-${mk.tag}-${mk.index}`,
      kind: 'keyLevel',
      label: mk.tag,
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: mk.price,
      price2: mk.price,
      confidence: 48,
      color: bull ? 'rgba(34,197,94,0.55)' : 'rgba(248,113,113,0.55)',
      lineLabelColor: bull ? '#86EFAC' : '#FCA5A5',
      lineDash: mk.tag === 'CHOCH' ? '6 4' : '4 3',
      lineStrokeWidth: mk.tag === 'MSB' ? 2 : 1,
      category: CAT,
      structureBias: mk.bias,
      labelTooltip: `${mk.tag} ${bull ? '상승' : '하락'} 구조 레벨(종가 돌파 기준·참고)`,
      noProject: true,
    });
  }

  // 현재 스탠스 핀
  const stanceColor =
    stance === 'LONG' ? '#22C55E' : stance === 'SHORT' ? '#F87171' : '#94A3B8';
  overlays.push({
    id: `${ID_PREFIX}-stance`,
    kind: 'label',
    label: stance === 'LONG' ? 'TV·롱' : stance === 'SHORT' ? 'TV·숏' : 'TV·관망',
    x1: 0,
    y1: 0,
    time1: last.time as number,
    price1: last.close,
    confidence: 58,
    color: stanceColor,
    lineLabelColor: '#F8FAFC',
    labelBackgroundColor:
      stance === 'LONG'
        ? 'rgba(21,128,61,0.94)'
        : stance === 'SHORT'
          ? 'rgba(153,27,27,0.94)'
          : 'rgba(51,65,85,0.92)',
    labelTextColor: '#F8FAFC',
    category: CAT,
    labelTooltip:
      'EMA200+리본(8/55)+BOS/CHOCH/MSB 정렬 참고. 4h·1D에서 특히 의미. 투자 권유·확정 신호 아님.',
  });

  if (live && stance !== 'WAIT') {
    const isLong = stance === 'LONG';
    const tStart = candles[Math.max(0, n - 12)]!.time as number;
    const tEnd = last.time as number;
    const half = Math.max(atrL * 0.25, last.close * 0.0004);
    overlays.push({
      id: `${ID_PREFIX}-zone-${stance.toLowerCase()}`,
      kind: isLong ? 'demandZone' : 'supplyZone',
      label: isLong ? 'TV·롱존' : 'TV·숏존',
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.entry + half,
      price2: live.entry - half,
      confidence: 55,
      color: isLong ? 'rgba(34,197,94,0.22)' : 'rgba(248,113,113,0.22)',
      category: CAT,
      zoneFillPreserve: true,
      zoneSpanOnly: true,
      overlayZoneExtraClass: 'merged-desk-tv-ls-zone',
      labelTooltip: `참고 E ${live.entry.toFixed(2)} · SL ${live.stopLoss.toFixed(2)} · TP1 ${live.tp1.toFixed(2)}`,
    });
    // 짧은 E/SL/TP1 레일(가격선 대체용 keyLevel)
    const rail = (
      id: string,
      price: number,
      label: string,
      color: string,
      dash?: string
    ): OverlayItem => ({
      id: `${ID_PREFIX}-rail-${id}`,
      kind: 'keyLevel',
      label,
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: price,
      price2: price,
      confidence: 54,
      color,
      lineLabelColor: color,
      lineDash: dash,
      lineStrokeWidth: id === 'e' ? 2 : 1,
      category: CAT,
      noProject: true,
      labelTooltip: `${label} ${price.toFixed(2)} (참고)`,
    });
    overlays.push(rail('e', live.entry, 'E', isLong ? '#4ADE80' : '#FB7185'));
    overlays.push(rail('sl', live.stopLoss, 'SL', '#FBBF24', '5 4'));
    overlays.push(rail('tp1', live.tp1, 'TP1', '#38BDF8', '4 3'));
  }

  const bullN = trimmed.filter((s) => s.side === 'LONG').length;
  const bearN = trimmed.filter((s) => s.side === 'SHORT').length;
  const mkTxt = mkLive ? `${mkLive.tag}${mkLive.bias === 'bullish' ? '↑' : '↓'}` : '구조없음';
  const summaryKo = `TV구조 롱숏(참고): 스탠스 ${
    stance === 'LONG' ? '롱' : stance === 'SHORT' ? '숏' : '관망'
  } · 최근핀 L${bullN}/S${bearN} · 최근마크 ${mkTxt} · EMA200+리본+구조 정렬 — 확정 신호 아님`;

  return { overlays, markers, stance, summaryKo, signals: trimmed, live };
}

export function isTvStructureLsOverlayId(id: string | undefined | null): boolean {
  return String(id || '').startsWith(ID_PREFIX);
}

