input.contents:
/**
 * TV 캡처형 구조 롱/숏 — EMA 리본(8/55) + EMA200 + structureMarksFu(BOS/CHOCH/MSB).
 * + 돌파 / 안착 / 진입가능 · 「어디부터」 가격 작도 (참고·확정 매매 아님).
 */
import type { Candle, OverlayItem } from '@/types';
import { ema } from '@/lib/indicators';
import {
  structureMarksFu,
  resolveStructureMarkPhase,
  type StructureMarkPhase,
} from '@/lib/smcDeskOverlay';
import type { AtlasPulseMarker } from '@/lib/monthDeskAtlasPulseDesk';
import type { UTCTimestamp } from 'lightweight-charts';

const ID_PREFIX = 'merged-desk-tv-ls';
const CAT: OverlayItem['category'] = 'smcDesk';

export type TvStructureLsStance = 'LONG' | 'SHORT' | 'WAIT';

/** 돌파→안착→진입가능 게이트 (참고) */
export type TvStructureLsGate =
  | 'BREAKOUT'
  | 'SETTLING'
  | 'ENTER_READY'
  | 'WAIT'
  | 'FAILED';

export type TvStructureLsSignal = {
  index: number;
  time: number;
  price: number;
  side: 'LONG' | 'SHORT';
  tag: 'BOS' | 'CHOCH' | 'MSB';
  reasonKo: string;
};

export type TvStructureLsLive = {
  entry: number;
  stopLoss: number;
  tp1: number;
  invalidation: number;
  /** 구조 돌파 레벨(어디서 돌파했는지) */
  breakLevel: number;
  /** 실제 감시·진입 참고가(어디부터) */
  entryFrom: number;
  entryFromLabelKo: string;
  gate: TvStructureLsGate;
  gateKo: string;
  phase: StructureMarkPhase;
  side: 'LONG' | 'SHORT';
  tag: 'BOS' | 'CHOCH' | 'MSB';
  checklistKo: string[];
};

export type TvStructureLongShortPack = {
  overlays: OverlayItem[];
  markers: AtlasPulseMarker[];
  stance: TvStructureLsStance;
  summaryKo: string;
  signals: TvStructureLsSignal[];
  live: TvStructureLsLive | null;
};

function lastFinite(arr: number[], i: number): number | null {
  const v = arr[i];
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

function atrAt(candles: Candle[], i: number, period = 14): number {
  const start = Math.max(1, i - period + 1);
  let sum = 0;
  let n = 0;
  for (let k = start; k <= i; k++) {
    const prev = candles[k - 1];
    const c = candles[k]!;
    const tr = prev
      ? Math.max(c.high - c.low, Math.abs(c.high - prev.close), Math.abs(c.low - prev.close))
      : c.high - c.low;
    sum += tr;
    n += 1;
  }
  return n > 0 ? sum / n : Math.max(candles[i]!.high - candles[i]!.low, 1e-8);
}

function fmt(p: number): string {
  if (!(p > 0) || !Number.isFinite(p)) return '—';
  if (p >= 1000) return p.toFixed(1);
  if (p >= 1) return p.toFixed(2);
  return p.toFixed(4);
}

function recentMarkBefore(
  marks: Array<{ index: number; price: number; tag: 'BOS' | 'CHOCH' | 'MSB'; bias: 'bullish' | 'bearish' }>,
  i: number,
  maxAgeBars: number
) {
  let best: (typeof marks)[number] | null = null;
  for (let k = marks.length - 1; k >= 0; k--) {
    const m = marks[k]!;
    if (m.index > i) continue;
    if (i - m.index > maxAgeBars) break;
    best = m;
    break;
  }
  return best;
}

function phaseToGateBase(phase: StructureMarkPhase): TvStructureLsGate {
  if (phase === 'failed') return 'FAILED';
  if (phase === 'breakout') return 'BREAKOUT';
  if (phase === 'settling') return 'SETTLING';
  if (phase === 'confirmed') return 'SETTLING';
  return 'WAIT';
}

function gateKoOf(g: TvStructureLsGate): string {
  switch (g) {
    case 'BREAKOUT':
      return '돌파·감시';
    case 'SETTLING':
      return '안착중';
    case 'ENTER_READY':
      return '진입가능';
    case 'FAILED':
      return '무효·관망';
    default:
      return '대기';
  }
}

/**
 * 캡처 규칙 + 게이트:
 * - 돌파: 종가 구조 돌파 직후 → 레벨 위/아래 유지 감시
 * - 안착: 돌파 후 1~2봉+ 유지 → 안착
 * - 진입가능: 안착 + MA 리본 재접촉(되돌림) + 매크로·리본 정렬
 * - 「어디부터」: 돌파레벨 재시험 또는 EMA8/21 리본
 */
export function buildTvStructureLongShortPack(params: {
  candles: Candle[];
  swingPivot?: number;
  maxSignals?: number;
  maxMarks?: number;
}): TvStructureLongShortPack {
  const candles = params.candles;
  const n = candles.length;
  const empty: TvStructureLongShortPack = {
    overlays: [],
    markers: [],
    stance: 'WAIT',
    summaryKo: 'TV구조 롱숏: 캔들 부족 — 관망(참고).',
    signals: [],
    live: null,
  };
  if (n < 80) return empty;

  const L = Math.max(2, Math.min(4, Math.round(params.swingPivot ?? 2)));
  const maxSignals = Math.max(8, Math.min(48, params.maxSignals ?? 28));
  const maxMarks = Math.max(24, Math.min(120, params.maxMarks ?? 80));
  const closes = candles.map((c) => c.close);
  const e8 = ema(closes, 8);
  const e21 = ema(closes, 21);
  const e55 = ema(closes, 55);
  const e200 = ema(closes, 200);
  const marks = structureMarksFu(candles, L, maxMarks);

  const signals: TvStructureLsSignal[] = [];
  let lastSigIdx = -999;

  for (let i = 60; i < n; i++) {
    const c = candles[i]!;
    const ma8 = lastFinite(e8, i);
    const ma21 = lastFinite(e21, i);
    const ma55 = lastFinite(e55, i);
    const ma200 = lastFinite(e200, i);
    if (ma8 == null || ma21 == null || ma55 == null || ma200 == null) continue;

    const ribbonBull = ma8 >= ma55;
    const macroBull = c.close > ma200;
    const macroBear = c.close < ma200;
    const mk = recentMarkBefore(marks, i, 28);
    if (!mk) continue;

    const atr = atrAt(candles, i, 14);
    const touchEps = Math.max(atr * 0.35, c.close * 0.0008);
    const bounceLong =
      (c.low <= ma8 + touchEps || c.low <= ma21 + touchEps || c.low <= ma55 + touchEps) &&
      c.close >= ma8 &&
      c.close > c.open;
    const rejectShort =
      (c.high >= ma8 - touchEps || c.high >= ma21 - touchEps || c.high >= ma55 - touchEps) &&
      c.close <= ma8 &&
      c.close < c.open;

    const longOk = macroBull && ribbonBull && mk.bias === 'bullish' && bounceLong;
    const shortOk = macroBear && !ribbonBull && mk.bias === 'bearish' && rejectShort;
    if (!longOk && !shortOk) continue;
    if (longOk && shortOk) continue;
    if (i - lastSigIdx < 3) continue;

    const side: 'LONG' | 'SHORT' = longOk ? 'LONG' : 'SHORT';
    lastSigIdx = i;
    signals.push({
      index: i,
      time: c.time as number,
      price: c.close,
      side,
      tag: mk.tag,
      reasonKo:
        side === 'LONG'
          ? `EMA200↑·리본↑·${mk.tag}↑·MA터치 반등(참고)`
          : `EMA200↓·리본↓·${mk.tag}↓·MA터치 거부(참고)`,
    });
  }

  const trimmed = signals.slice(-maxSignals);
  const last = candles[n - 1]!;
  const iLast = n - 1;
  const ma8L = lastFinite(e8, iLast);
  const ma21L = lastFinite(e21, iLast);
  const ma55L = lastFinite(e55, iLast);
  const ma200L = lastFinite(e200, iLast);
  const mkLive = recentMarkBefore(marks, iLast, 40);
  const atrL = atrAt(candles, iLast, 14);

  let stance: TvStructureLsStance = 'WAIT';
  let live: TvStructureLsLive | null = null;

  if (ma8L != null && ma21L != null && ma55L != null && ma200L != null && mkLive) {
    const phase = resolveStructureMarkPhase(mkLive, candles, n);
    const ribbonBull = ma8L >= ma55L;
    const macroBull = last.close > ma200L;
    const macroBear = last.close < ma200L;
    const touchEps = Math.max(atrL * 0.4, last.close * 0.0009);
    const nearRibbon =
      Math.abs(last.close - ma8L) <= atrL * 1.25 ||
      Math.abs(last.close - ma21L) <= atrL * 1.25 ||
      last.low <= ma55L + touchEps ||
      last.high >= ma55L - touchEps;
    const retestLevel =
      mkLive.bias === 'bullish'
        ? last.low <= mkLive.price + touchEps * 2 && last.close > mkLive.price
        : last.high >= mkLive.price - touchEps * 2 && last.close < mkLive.price;

    const sideOkLong = mkLive.bias === 'bullish' && macroBull && ribbonBull;
    const sideOkShort = mkLive.bias === 'bearish' && macroBear && !ribbonBull;

    if (sideOkLong || sideOkShort) {
      const side: 'LONG' | 'SHORT' = sideOkLong ? 'LONG' : 'SHORT';
      stance = side;

      let gate = phaseToGateBase(phase);
      // 안착(settling/confirmed) + 리본/레벨 재접촉 → 진입가능
      if (
        gate === 'SETTLING' &&
        (nearRibbon || retestLevel) &&
        phase !== 'failed'
      ) {
        gate = 'ENTER_READY';
      }
      // 돌파 직후라도 이미 리본까지 눌림·유지면 조기 진입가능(참고)
      if (gate === 'BREAKOUT' && retestLevel && nearRibbon) {
        gate = 'ENTER_READY';
      }

      const breakLevel = mkLive.price;
      // 어디부터: 진입가능이면 리본·돌파레벨 중 보수적 쪽 / 돌파·안착중이면 돌파레벨 재시험
      let entryFrom: number;
      let entryFromLabelKo: string;
      if (side === 'LONG') {
        const ribbonEntry = Math.min(ma8L, ma21L);
        if (gate === 'ENTER_READY') {
          entryFrom = Math.max(breakLevel, Math.min(last.close, ribbonEntry));
          entryFromLabelKo = retestLevel
            ? `${mkLive.tag}돌파레벨 ${fmt(breakLevel)} 재시험·여기부터`
            : `리본(EMA8/21) ${fmt(ribbonEntry)} 부근·여기부터`;
        } else if (gate === 'BREAKOUT') {
          entryFrom = breakLevel;
          entryFromLabelKo = `${mkLive.tag} 돌파 ${fmt(breakLevel)} — 위 종가 유지 후 재시험부터`;
        } else {
          entryFrom = Math.max(breakLevel, ribbonEntry);
          entryFromLabelKo = `안착 중 · ${mkLive.tag} ${fmt(breakLevel)} 또는 리본 ${fmt(ribbonEntry)}부터`;
        }
      } else {
        const ribbonEntry = Math.max(ma8L, ma21L);
        if (gate === 'ENTER_READY') {
          entryFrom = Math.min(breakLevel, Math.max(last.close, ribbonEntry));
          entryFromLabelKo = retestLevel
            ? `${mkLive.tag}돌파레벨 ${fmt(breakLevel)} 재시험·여기부터`
            : `리본(EMA8/21) ${fmt(ribbonEntry)} 부근·여기부터`;
        } else if (gate === 'BREAKOUT') {
          entryFrom = breakLevel;
          entryFromLabelKo = `${mkLive.tag} 돌파 ${fmt(breakLevel)} — 아래 종가 유지 후 재시험부터`;
        } else {
          entryFrom = Math.min(breakLevel, ribbonEntry);
          entryFromLabelKo = `안착 중 · ${mkLive.tag} ${fmt(breakLevel)} 또는 리본 ${fmt(ribbonEntry)}부터`;
        }
      }

      const entry = entryFrom;
      const stopLoss =
        side === 'LONG'
          ? Math.min(last.low, ma55L, breakLevel) - atrL * 0.55
          : Math.max(last.high, ma55L, breakLevel) + atrL * 0.55;
      const risk = Math.max(Math.abs(entry - stopLoss), atrL * 0.5);
      const tp1 = side === 'LONG' ? entry + risk * 1.8 : entry - risk * 1.8;

      const checklistKo = [
        `${mkLive.tag} ${side === 'LONG' ? '상승' : '하락'} · 단계 ${
          phase === 'breakout' ? '돌파' : phase === 'settling' ? '안착중' : phase === 'confirmed' ? '구조안착' : phase === 'failed' ? '무효' : phase
        }`,
        gate === 'BREAKOUT'
          ? `돌파했으니 ${fmt(breakLevel)} ${side === 'LONG' ? '위' : '아래'} 종가 유지 감시`
          : gate === 'SETTLING'
            ? `안착 진행 — 아직 리본/레벨 재접촉 대기`
            : gate === 'ENTER_READY'
              ? `안착·재접촉 — 진입가능(참고) · ${entryFromLabelKo}`
              : gate === 'FAILED'
                ? '레벨 종가 이탈 — 관망'
                : '대기',
        `매크로 EMA200 ${macroBull ? '위' : '아래'} · 리본 ${ribbonBull ? '상승' : '하락'}`,
        `무효(참고): ${fmt(stopLoss)}`,
      ];

      live = {
        entry,
        stopLoss,
        tp1,
        invalidation: stopLoss,
        breakLevel,
        entryFrom,
        entryFromLabelKo,
        gate,
        gateKo: gateKoOf(gate),
        phase,
        side,
        tag: mkLive.tag,
        checklistKo,
      };
    } else if (trimmed.length) {
      const lastSig = trimmed[trimmed.length - 1]!;
      if (iLast - lastSig.index <= 6) stance = lastSig.side;
    }
  }

  const overlays: OverlayItem[] = [];
  const markers: AtlasPulseMarker[] = [];

  for (const s of trimmed) {
    const isLong = s.side === 'LONG';
    overlays.push({
      id: `${ID_PREFIX}-pin-${s.side.toLowerCase()}-${s.time}`,
      kind: 'label',
      label: isLong ? 'L' : 'S',
      x1: 0,
      y1: 0,
      time1: s.time,
      price1: s.price,
      confidence: 52,
      color: isLong ? '#16A34A' : '#DC2626',
      lineLabelColor: isLong ? '#DCFCE7' : '#FEE2E2',
      labelBackgroundColor: isLong ? 'rgba(22,163,74,0.92)' : 'rgba(185,28,28,0.92)',
      labelTextColor: '#FFFFFF',
      category: CAT,
      structureBias: isLong ? 'bullish' : 'bearish',
      labelTooltip: `${s.reasonKo} · 참고용(확정 신호 아님)`,
    });
    markers.push({
      time: s.time as UTCTimestamp,
      position: isLong ? 'belowBar' : 'aboveBar',
      shape: 'square',
      color: isLong ? '#22C55E' : '#F87171',
      text: isLong ? 'L' : 'S',
      size: 1,
      id: `${ID_PREFIX}-mk-${s.side.toLowerCase()}-${s.time}`,
    });
  }

  // 최근 구조 레벨 + 단계 라벨
  const recentMarks = marks.slice(-6);
  for (const mk of recentMarks) {
    const c = candles[mk.index];
    if (!c) continue;
    const bull = mk.bias === 'bullish';
    const phase = resolveStructureMarkPhase(mk, candles, n);
    const phaseTag =
      phase === 'breakout'
        ? '·돌파'
        : phase === 'settling'
          ? '·안착중'
          : phase === 'confirmed'
            ? '·안착'
            : phase === 'failed'
              ? '·무효'
              : '';
    const t1 = c.time as number;
    const t2 = last.time as number;
    overlays.push({
      id: `${ID_PREFIX}-lvl-${mk.tag}-${mk.index}`,
      kind: 'keyLevel',
      label: `${mk.tag}${phaseTag}`,
      x1: 0,
      y1: 0,
      time1: t1,
      time2: t2,
      price1: mk.price,
      price2: mk.price,
      confidence: 48,
      color: bull ? 'rgba(34,197,94,0.55)' : 'rgba(248,113,113,0.55)',
      lineLabelColor: bull ? '#86EFAC' : '#FCA5A5',
      lineDash: mk.tag === 'CHOCH' ? '6 4' : '4 3',
      lineStrokeWidth: mk.tag === 'MSB' || phase === 'confirmed' ? 2 : 1,
      category: CAT,
      structureBias: mk.bias,
      labelTooltip: `${mk.tag} ${bull ? '상승' : '하락'}${phaseTag} (종가 돌파 기준·참고)`,
      noProject: true,
    });
  }

  // 게이트 스탠스 라벨 (돌파/안착/진입가능)
  if (live) {
    const isLong = live.side === 'LONG';
    const gateLabel =
      live.gate === 'ENTER_READY'
        ? `진입가능·${isLong ? '롱' : '숏'}`
        : live.gate === 'BREAKOUT'
          ? `돌파·감시·${isLong ? '롱' : '숏'}`
          : live.gate === 'SETTLING'
            ? `안착중·${isLong ? '롱' : '숏'}`
            : live.gate === 'FAILED'
              ? '무효·관망'
              : `TV·${isLong ? '롱' : '숏'}`;
    const bg =
      live.gate === 'ENTER_READY'
        ? isLong
          ? 'rgba(22,163,74,0.96)'
          : 'rgba(220,38,38,0.96)'
        : live.gate === 'BREAKOUT'
          ? 'rgba(37,99,235,0.94)'
          : live.gate === 'SETTLING'
            ? 'rgba(234,88,12,0.94)'
            : 'rgba(51,65,85,0.92)';
    overlays.push({
      id: `${ID_PREFIX}-stance`,
      kind: 'label',
      label: gateLabel,
      x1: 0,
      y1: 0,
      time1: last.time as number,
      price1: last.close,
      confidence: 62,
      color: isLong ? '#22C55E' : '#F87171',
      lineLabelColor: '#F8FAFC',
      labelBackgroundColor: bg,
      labelTextColor: '#F8FAFC',
      category: CAT,
      zonePulse: live.gate === 'ENTER_READY',
      labelTooltip: live.checklistKo.join(' · ') + ' · 확정 신호 아님',
    });

    const tStart = candles[Math.max(0, n - 16)]!.time as number;
    const tEnd = last.time as number;

    // 돌파 레벨 강조선
    overlays.push({
      id: `${ID_PREFIX}-break-lvl`,
      kind: 'keyLevel',
      label: `${live.tag}돌파 ${fmt(live.breakLevel)}`,
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.breakLevel,
      price2: live.breakLevel,
      confidence: 60,
      color: isLong ? 'rgba(74,222,128,0.85)' : 'rgba(248,113,113,0.85)',
      lineLabelColor: isLong ? '#BBF7D0' : '#FECACA',
      lineDash: '2 3',
      lineStrokeWidth: 2,
      category: CAT,
      noProject: true,
      labelTooltip: `어디서 돌파했는지(참고): ${fmt(live.breakLevel)}`,
    });

    // 「여기부터」 진입 가능 가격선
    const fromColor =
      live.gate === 'ENTER_READY' ? (isLong ? '#4ADE80' : '#FB7185') : '#FBBF24';
    overlays.push({
      id: `${ID_PREFIX}-entry-from`,
      kind: 'keyLevel',
      label:
        live.gate === 'ENTER_READY'
          ? `여기부터 ${fmt(live.entryFrom)}`
          : live.gate === 'BREAKOUT'
            ? `재시험 ${fmt(live.entryFrom)}`
            : `감시 ${fmt(live.entryFrom)}`,
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.entryFrom,
      price2: live.entryFrom,
      confidence: 64,
      color: fromColor,
      lineLabelColor: fromColor,
      lineStrokeWidth: live.gate === 'ENTER_READY' ? 3 : 2,
      lineDash: live.gate === 'ENTER_READY' ? undefined : '5 4',
      category: CAT,
      noProject: true,
      zonePulse: live.gate === 'ENTER_READY',
      labelTooltip: live.entryFromLabelKo + ' · 참고·확정 아님',
    });

    const half = Math.max(atrL * 0.22, last.close * 0.00035);
    overlays.push({
      id: `${ID_PREFIX}-zone-${live.side.toLowerCase()}`,
      kind: isLong ? 'demandZone' : 'supplyZone',
      label:
        live.gate === 'ENTER_READY'
          ? `진입존·${isLong ? '롱' : '숏'}`
          : live.gate === 'BREAKOUT'
            ? `돌파감시존`
            : `안착감시존`,
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.entryFrom + half * (isLong ? 1.2 : 1.4),
      price2: live.entryFrom - half * (isLong ? 1.4 : 1.2),
      confidence: 58,
      color:
        live.gate === 'ENTER_READY'
          ? isLong
            ? 'rgba(34,197,94,0.28)'
            : 'rgba(248,113,113,0.28)'
          : 'rgba(251,191,36,0.18)',
      category: CAT,
      zoneFillPreserve: true,
      zoneSpanOnly: true,
      overlayZoneExtraClass: 'merged-desk-tv-ls-zone',
      zonePulse: live.gate === 'ENTER_READY',
      labelTooltip: live.entryFromLabelKo,
    });

    overlays.push({
      id: `${ID_PREFIX}-rail-e`,
      kind: 'keyLevel',
      label: 'E',
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.entry,
      price2: live.entry,
      confidence: 54,
      color: isLong ? '#4ADE80' : '#FB7185',
      lineLabelColor: isLong ? '#4ADE80' : '#FB7185',
      lineStrokeWidth: 2,
      category: CAT,
      noProject: true,
      labelTooltip: `참고 E ${fmt(live.entry)}`,
    });
    overlays.push({
      id: `${ID_PREFIX}-rail-sl`,
      kind: 'keyLevel',
      label: 'SL',
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.stopLoss,
      price2: live.stopLoss,
      confidence: 54,
      color: '#FBBF24',
      lineLabelColor: '#FBBF24',
      lineDash: '5 4',
      category: CAT,
      noProject: true,
      labelTooltip: `참고 SL·무효 ${fmt(live.stopLoss)}`,
    });
    overlays.push({
      id: `${ID_PREFIX}-rail-tp1`,
      kind: 'keyLevel',
      label: 'TP1',
      x1: 0,
      y1: 0,
      time1: tStart,
      time2: tEnd,
      price1: live.tp1,
      price2: live.tp1,
      confidence: 54,
      color: '#38BDF8',
      lineLabelColor: '#38BDF8',
      lineDash: '4 3',
      category: CAT,
      noProject: true,
      labelTooltip: `참고 TP1 ${fmt(live.tp1)}`,
    });

    // 「여기부터」 핀
    overlays.push({
      id: `${ID_PREFIX}-from-pin`,
      kind: 'label',
      label:
        live.gate === 'ENTER_READY'
          ? `여기부터 ${fmt(live.entryFrom)}`
          : live.gate === 'BREAKOUT'
            ? `돌파 ${fmt(live.breakLevel)}`
            : `안착감시 ${fmt(live.entryFrom)}`,
      x1: 0,
      y1: 0,
      time1: last.time as number,
      price1: live.entryFrom,
      confidence: 66,
      color: fromColor,
      lineLabelColor: '#0F172A',
      labelBackgroundColor: fromColor,
      labelTextColor: '#0F172A',
      category: CAT,
      labelTooltip: live.entryFromLabelKo,
    });
  } else {
    overlays.push({
      id: `${ID_PREFIX}-stance`,
      kind: 'label',
      label: stance === 'LONG' ? 'TV·롱' : stance === 'SHORT' ? 'TV·숏' : 'TV·관망',
      x1: 0,
      y1: 0,
      time1: last.time as number,
      price1: last.close,
      confidence: 50,
      color: '#94A3B8',
      lineLabelColor: '#F8FAFC',
      labelBackgroundColor: 'rgba(51,65,85,0.92)',
      labelTextColor: '#F8FAFC',
      category: CAT,
      labelTooltip: '구조·리본·EMA200 미정렬 — 관망(참고)',
    });
  }

  const bullN = trimmed.filter((s) => s.side === 'LONG').length;
  const bearN = trimmed.filter((s) => s.side === 'SHORT').length;
  const summaryKo = live
    ? `TV롱숏(참고): ${live.gateKo} · ${live.side === 'LONG' ? '롱' : '숏'} · ${live.tag} · ${live.entryFromLabelKo} · E ${fmt(live.entry)} · 확정 아님`
    : `TV구조 롱숏(참고): 스탠스 ${
        stance === 'LONG' ? '롱' : stance === 'SHORT' ? '숏' : '관망'
      } · 핀 L${bullN}/S${bearN} — 확정 신호 아님`;

  return { overlays, markers, stance, summaryKo, signals: trimmed, live };
}

export function isTvStructureLsOverlayId(id: string | undefined | null): boolean {
  return String(id || '').startsWith(ID_PREFIX);
}

