 * 1) CHOCH/MSB 우선 (단순 BOS 연속 돌파는 제외)
 * 2) 해당 봉 시점에서 구조 단계 = 안착중/구조안착 (돌파 직후·무효 제외)
 * 3) EMA200 + 리본(8/55) 정렬
 * 4) 돌파레벨 재시험 또는 EMA21/55 깊은 리본 터치 + 방향 종가
 * 5) 몸통 품질·최소 봉 간격·미래 1봉 무효화 필터(히스토리)
 */
export function buildTvStructureLongShortPack(params: {
  candles: Candle[];
  swingPivot?: number;
  maxSignals?: number;
  maxMarks?: number;
}): TvStructureLongShortPack {
  const candles = params.candles;
  const n = candles.length;
  const empty: TvStructureLongShortPack = {
    overlays: [],
    markers: [],
    stance: 'WAIT',
    summaryKo: 'TV구조 롱숏: 캔들 부족 — 관망(참고).',
    signals: [],
    live: null,
  };
  if (n < 80) return empty;

  const L = Math.max(2, Math.min(4, Math.round(params.swingPivot ?? 2)));
  /** 화면을 도배하지 않도록 소수만 */
  const maxSignals = Math.max(4, Math.min(12, params.maxSignals ?? 8));
  const maxMarks = Math.max(24, Math.min(120, params.maxMarks ?? 80));
  const minGapBars = 10;
  const closes = candles.map((c) => c.close);
  const e8 = ema(closes, 8);
  const e21 = ema(closes, 21);
  const e55 = ema(closes, 55);
  const e200 = ema(closes, 200);
  const marks = structureMarksFu(candles, L, maxMarks);

  const signals: TvStructureLsSignal[] = [];
  let lastSigIdx = -999;
  let lastSigSide: 'LONG' | 'SHORT' | null = null;

  for (let i = 80; i < n - 1; i++) {
    const c = candles[i]!;
    const ma8 = lastFinite(e8, i);
    const ma21 = lastFinite(e21, i);
    const ma55 = lastFinite(e55, i);
    const ma200 = lastFinite(e200, i);
    if (ma8 == null || ma21 == null || ma55 == null || ma200 == null) continue;

    const ribbonBull = ma8 >= ma55;
    const macroBull = c.close > ma200;
    const macroBear = c.close < ma200;
    /** 최근 구조 — CHOCH/MSB만 (BOS 난사 방지). 마크 후 2~14봉 안 */
    const mk = recentMarkBefore(marks, i, 14);
    if (!mk) continue;
    if (mk.tag === 'BOS') continue;
    const barsSince = i - mk.index;
    if (barsSince < 2 || barsSince > 14) continue;

    /** 그 봉까지의 캔들로 단계 판정 (미래 누수 없이 안착만) */
    const phase = resolveStructureMarkPhase(mk, candles, i + 1);
    if (phase !== 'settling' && phase !== 'confirmed') continue;

    const atr = atrAt(candles, i, 14);
    const touchEps = Math.max(atr * 0.28, c.close * 0.0006);
    const range = Math.max(c.high - c.low, 1e-9);
    const body = Math.abs(c.close - c.open);
    const bodyOk = body / range >= 0.42;

    const retestLong =
      mk.bias === 'bullish' &&
      c.low <= mk.price + touchEps * 1.5 &&
      c.close > mk.price &&
      c.close > c.open;
    const retestShort =
      mk.bias === 'bearish' &&
      c.high >= mk.price - touchEps * 1.5 &&
      c.close < mk.price &&
      c.close < c.open;

    /** EMA8만 스치는 약한 터치 제외 — 21/55 또는 레벨 재시험 */
    const deepRibbonLong =
      (c.low <= ma21 + touchEps || c.low <= ma55 + touchEps) &&
      c.close >= ma8 &&
      c.close > c.open &&
      c.close >= ma21;
    const deepRibbonShort =
      (c.high >= ma21 - touchEps || c.high >= ma55 - touchEps) &&
      c.close <= ma8 &&
      c.close < c.open &&
      c.close <= ma21;

    const longOk =
      macroBull &&
      ribbonBull &&
      mk.bias === 'bullish' &&
      bodyOk &&
      (retestLong || deepRibbonLong) &&
      c.close > ma200;
    const shortOk =
      macroBear &&
      !ribbonBull &&
      mk.bias === 'bearish' &&
      bodyOk &&
      (retestShort || deepRibbonShort) &&
      c.close < ma200;

    if (!longOk && !shortOk) continue;
    if (longOk && shortOk) continue;
    if (i - lastSigIdx < minGapBars) continue;

    const side: 'LONG' | 'SHORT' = longOk ? 'LONG' : 'SHORT';
    /** 같은 방향 연속 핀 억제 */
    if (lastSigSide === side && i - lastSigIdx < minGapBars * 2) continue;

    /** 다음 봉이 즉시 레벨을 종가로 무효화하면 히스토리 핀 제외 */
    const next = candles[i + 1];
    if (next) {
      if (side === 'LONG' && next.close < mk.price) continue;
      if (side === 'SHORT' && next.close > mk.price) continue;
    }

    lastSigIdx = i;
    lastSigSide = side;
    signals.push({
      index: i,
      time: c.time as number,
      price: c.close,
      side,
      tag: mk.tag,
      reasonKo:
        side === 'LONG'
          ? `${mk.tag}안착·재시험·EMA200↑·리본↑(고품질·참고)`
          : `${mk.tag}안착·재시험·EMA200↓·리본↓(고품질·참고)`,
    });
  }

  const trimmed = signals.slice(-maxSignals);

if (ma8L != null && ma21L != null && ma55L != null && ma200L != null && mkLive) {
  const phase = resolveStructureMarkPhase(mkLive, candles, n);
  const ribbonBull = ma8L >= ma55L;
  const macroBull = last.close > ma200L;
  const macroBear = last.close < ma200L;
