  const barsSince = iLast - mkLive.index;
  const deepRibbon =
    mkLive.bias === 'bullish'
      ? last.low <= ma21L + touchEps || last.low <= ma55L + touchEps
      : last.high >= ma21L - touchEps || last.high >= ma55L - touchEps;
  const retestLevel =
    mkLive.bias === 'bullish'
      ? last.low <= mkLive.price + touchEps * 1.5 && last.close > mkLive.price
      : last.high >= mkLive.price - touchEps * 1.5 && last.close < mkLive.price;
  const range = Math.max(last.high - last.low, 1e-9);
  const bodyOk = Math.abs(last.close - last.open) / range >= 0.38;

  /** 라이브도 CHOCH/MSB만 — BOS 단독은 감시만 */
  const structureOk = mkLive.tag === 'CHOCH' || mkLive.tag === 'MSB';
  const sideOkLong =
    structureOk && mkLive.bias === 'bullish' && macroBull && ribbonBull && last.close > ma200L;
  const sideOkShort =
    structureOk && mkLive.bias === 'bearish' && macroBear && !ribbonBull && last.close < ma200L;

  if (sideOkLong || sideOkShort) {
    const side: 'LONG' | 'SHORT' = sideOkLong ? 'LONG' : 'SHORT';
    stance = side;

    let gate = phaseToGateBase(phase);
    // 진입가능: 안착+깊은 재시험만 (돌파 직후 조기 진입 금지)
    const settleOk = phase === 'settling' || phase === 'confirmed';
    const pullbackOk = (retestLevel || deepRibbon) && bodyOk && barsSince >= 2 && barsSince <= 14;
    if (gate === 'SETTLING' && settleOk && pullbackOk) {
      gate = 'ENTER_READY';
    }
    if (gate === 'BREAKOUT') {
      // 돌파 직후는 감시만 — ENTER_READY로 올리지 않음
    }

    const breakLevel = mkLive.price;
    let entryFrom: number;
    let entryFromLabelKo: string;
    if (side === 'LONG') {
      const ribbonEntry = Math.min(ma21L, ma55L);
      if (gate === 'ENTER_READY') {
        entryFrom = Math.max(breakLevel, ribbonEntry);
        entryFromLabelKo = retestLevel
          ? `${mkLive.tag}안착 재시험 ${fmt(breakLevel)} · 여기부터(참고)`
          : `깊은리본(EMA21/55) ${fmt(ribbonEntry)} · 여기부터(참고)`;
      } else if (gate === 'BREAKOUT') {
        entryFrom = breakLevel;
        entryFromLabelKo = `${mkLive.tag} 돌파 ${fmt(breakLevel)} — 안착·재시험 전 관망`;
      } else {
        entryFrom = Math.max(breakLevel, ribbonEntry);
        entryFromLabelKo = `안착 대기 · ${mkLive.tag} ${fmt(breakLevel)} / 리본 ${fmt(ribbonEntry)}`;
      }
    } else {
      const ribbonEntry = Math.max(ma21L, ma55L);
      if (gate === 'ENTER_READY') {
        entryFrom = Math.min(breakLevel, ribbonEntry);
        entryFromLabelKo = retestLevel
          ? `${mkLive.tag}안착 재시험 ${fmt(breakLevel)} · 여기부터(참고)`
          : `깊은리본(EMA21/55) ${fmt(ribbonEntry)} · 여기부터(참고)`;
      } else if (gate === 'BREAKOUT') {
        entryFrom = breakLevel;
