        entryFromLabelKo = `안착 대기 · ${mkLive.tag} ${fmt(breakLevel)} / 리본 ${fmt(ribbonEntry)}`;
      }
    }

    const entry = entryFrom;
    const stopLoss =
      side === 'LONG'
        ? Math.min(last.low, ma55L, breakLevel) - atrL * 0.7
        : Math.max(last.high, ma55L, breakLevel) + atrL * 0.7;
    const risk = Math.max(Math.abs(entry - stopLoss), atrL * 0.6);
    /** 보수적 1차 목표 */
    const tp1 = side === 'LONG' ? entry + risk * 2.0 : entry - risk * 2.0;

    const checklistKo = [
      `${mkLive.tag} ${side === 'LONG' ? '상승' : '하락'} · ${
        phase === 'breakout' ? '돌파' : phase === 'settling' ? '안착중' : phase === 'confirmed' ? '구조안착' : phase === 'failed' ? '무효' : phase
      }`,
      gate === 'BREAKOUT'
        ? `돌파 직후 — 안착 전 진입 보류(참고)`
        : gate === 'SETTLING'
          ? `안착 중 — 깊은 리본/레벨 재시험 대기`
          : gate === 'ENTER_READY'
            ? `고품질 조건 — ${entryFromLabelKo}`
            : gate === 'FAILED'
              ? '레벨 종가 이탈 — 관망'
              : '대기',
      `EMA200 ${macroBull ? '위' : '아래'} · 리본 ${ribbonBull ? '상승' : '하락'} · ${barsSince}봉전 구조`,
      `무효(참고): ${fmt(stopLoss)} · 확정 매매 아님`,
    ];

    live = {
      entry,
      stopLoss,
      tp1,
      invalidation: stopLoss,
      breakLevel,
      entryFrom,
      entryFromLabelKo,
      gate,
      gateKo: gateKoOf(gate),
      phase,
      side,
      tag: mkLive.tag,
      checklistKo,
    };
  } else if (trimmed.length) {
    const lastSig = trimmed[trimmed.length - 1]!;
    if (iLast - lastSig.index <= 8) stance = lastSig.side;
  }
}

