    const next = candles[i + 1];
    if (next) {
      if (side === 'LONG' && next.close < mk.price) continue;
      if (side === 'SHORT' && next.close > mk.price) continue;
    }

    lastSigIdx = i;
    lastSigSide = side;
    signals.push({
      index: i,
