      const settleOk = phase === 'settling' || phase === 'confirmed';
      const pullbackOk = (retestLevel || deepRibbon) && bodyOk && barsSince >= 2 && barsSince <= 14;
      if (gate === 'SETTLING' && settleOk && pullbackOk) {
        gate = 'ENTER_READY';
