        if (gate === 'ENTER_READY') {
          entryFrom = Math.min(breakLevel, ribbonEntry);
          entryFromLabelKo = retestLevel
            ? `${mkLive.tag}안착 재시험 ${fmt(breakLevel)} · 여기부터(참고)`
            : `깊은리본(EMA21/55) ${fmt(ribbonEntry)} · 여기부터(참고)`;
        } else if (gate === 'BREAKOUT') {
          entryFrom = breakLevel;
          entryFromLabelKo = `${mkLive.tag} 돌파 ${fmt(breakLevel)} — 안착·재시험 전 관망`;
        } else {
          entryFrom = Math.min(breakLevel, ribbonEntry);
          entryFromLabelKo = `안착 대기 · ${mkLive.tag} ${fmt(breakLevel)} / 리본 ${fmt(ribbonEntry)}`;
        }
      }

      const entry = entryFrom;
      const stopLoss =
        side === 'LONG'
          ? Math.min(last.low, ma55L, breakLevel) - atrL * 0.7
          : Math.max(last.high, ma55L, breakLevel) + atrL * 0.7;
      const risk = Math.max(Math.abs(entry - stopLoss), atrL * 0.6);
      /** 보수적 1차 목표 */
      const tp1 = side === 'LONG' ? entry + risk * 2.0 : entry - risk * 2.0;

      const checklistKo = [
        `${mkLive.tag} ${side === 'LONG' ? '상승' : '하락'} · ${
