export function pickMergedDeskCoreConfirmConfirms(
  confirms: MergedDirectionConfirm[]
): MergedDirectionConfirm[] {
  /** 차트: 확정 + ST홀드 시나리오(strong) — 오르기 전 선행 표시 */
