/**
 * 주봉(1W) 스윙 지지·저항 → 분·시·일 차트에 공동 투영.
 * 주봉 기록 + 현재 TF 피벗이 겹치면 「공동」 라벨.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import { normalizeChartTimeframe } from '@/lib/constants';
import { collectSwingPivots } from '@/lib/mergedDeskCandleTrendline';

export const WEEKLY_SHARED_SR_ID_PREFIX = 'merged-desk-weekly-sr';

export type WeeklySharedSrHit = {
  bias: 'support' | 'resistance';
  low: number;
  high: number;
  mid: number;
  weeklyTime: number;
  weeklyIndex: number;
  jointWithChart: boolean;
  strength: number;
};

function fmt(p: number): string {
  if (!(p > 0) || !Number.isFinite(p)) return '—';
  if (p >= 1000) return p.toFixed(1);
  if (p >= 1) return p.toFixed(2);
  return p.toFixed(4);
}

function hugSupport(c: Candle): { low: number; high: number } {
  const bot = c.low;
  const bodyBot = Math.min(c.open, c.close);
  const range = Math.max(c.high - c.low, 1e-12);
  const top = bodyBot - bot < range * 0.18 ? bot + range * 0.45 : bodyBot;
  return { low: bot, high: Math.max(top, bot + range * 0.12) };
}

function hugResistance(c: Candle): { low: number; high: number } {
  const top = c.high;
  const bodyTop = Math.max(c.open, c.close);
  const range = Math.max(c.high - c.low, 1e-12);
  const bot = top - bodyTop < range * 0.18 ? top - range * 0.45 : bodyTop;
  return { low: Math.min(bot, top - range * 0.12), high: top };
}

function clusterKey(price: number, ref: number): number {
  const step = Math.max(ref * 0.0045, 1e-8);
  return Math.round(price / step);
}

function chartPivotNear(
  chartCandles: Candle[],
  chartTf: string,
  mid: number,
  side: 'support' | 'resistance'
): boolean {
  if (chartCandles.length < 24) return false;
  const { highs, lows } = collectSwingPivots(chartCandles, chartTf);
  const pivots = side === 'support' ? lows : highs;
  const tol = Math.max(mid * 0.006, 1e-8);
  return pivots.some((p) => Math.abs(p.price - mid) <= tol);
}

/**
 * 주봉 스윙에서 지지·저항 구간 추출 (가격 허그 = 정의봉 윅~바디).
 */
export function detectWeeklySharedSrHits(params: {
  weeklyCandles: Candle[];
  chartCandles: Candle[];
  chartTimeframe: string;
  maxPerSide?: number;
}): WeeklySharedSrHit[] {
  const weekly = params.weeklyCandles;
  const n = weekly.length;
  if (n < 16) return [];

  const chartTf = normalizeChartTimeframe(params.chartTimeframe);
  const maxPer = Math.max(1, Math.min(4, params.maxPerSide ?? 3));
  const last = weekly[n - 1]!;
  const price = last.close;
  const { highs, lows } = collectSwingPivots(weekly, '1w');

  type Raw = {
    bias: 'support' | 'resistance';
    low: number;
    high: number;
    mid: number;
    weeklyTime: number;
    weeklyIndex: number;
    age: number;
  };
  const raw: Raw[] = [];

  for (const p of lows) {
    const c = weekly[p.i];
    if (!c) continue;
    const hug = hugSupport(c);
    raw.push({
      bias: 'support',
      low: hug.low,
      high: hug.high,
      mid: (hug.low + hug.high) / 2,
      weeklyTime: Number(c.time),
      weeklyIndex: p.i,
      age: n - 1 - p.i,
    });
  }
  for (const p of highs) {
    const c = weekly[p.i];
    if (!c) continue;
    const hug = hugResistance(c);
    raw.push({
      bias: 'resistance',
      low: hug.low,
      high: hug.high,
      mid: (hug.low + hug.high) / 2,
      weeklyTime: Number(c.time),
      weeklyIndex: p.i,
      age: n - 1 - p.i,
    });
  }

  /** 클러스터 — 같은 가격대 중복 제거, 최근·강한 쪽 우선 */
  const best = new Map<string, Raw & { count: number }>();
  for (const r of raw) {
    const key = `${r.bias}:${clusterKey(r.mid, price)}`;
    const prev = best.get(key);
    if (!prev) {
      best.set(key, { ...r, count: 1 });
      continue;
    }
    prev.count += 1;
    if (r.age < prev.age) {
      prev.low = r.low;
      prev.high = r.high;
      prev.mid = r.mid;
      prev.weeklyTime = r.weeklyTime;
      prev.weeklyIndex = r.weeklyIndex;
      prev.age = r.age;
    }
  }

  const supports = [...best.values()]
    .filter((z) => z.bias === 'support' && z.high <= price * 1.01)
    .sort((a, b) => {
      const da = Math.abs(price - a.mid);
      const db = Math.abs(price - b.mid);
      return da - db || a.age - b.age;
    })
    .slice(0, maxPer);

  const resistances = [...best.values()]
    .filter((z) => z.bias === 'resistance' && z.low >= price * 0.99)
    .sort((a, b) => {
      const da = Math.abs(a.mid - price);
      const db = Math.abs(b.mid - price);
      return da - db || a.age - b.age;
    })
    .slice(0, maxPer);

  const hits: WeeklySharedSrHit[] = [];
  for (const z of [...supports, ...resistances]) {
    const joint = chartPivotNear(params.chartCandles, chartTf, z.mid, z.bias);
    const prox = 1 / (1 + Math.abs(price - z.mid) / Math.max(price, 1));
    const fresh = 1 / (1 + z.age / 24);
    hits.push({
      bias: z.bias,
      low: z.low,
      high: z.high,
      mid: z.mid,
      weeklyTime: z.weeklyTime,
      weeklyIndex: z.weeklyIndex,
      jointWithChart: joint,
      strength: Math.round((0.45 * prox + 0.35 * fresh + 0.2 * Math.min(1, z.count / 3) + (joint ? 0.15 : 0)) * 100),
    });
  }

  hits.sort((a, b) => b.strength - a.strength || a.bias.localeCompare(b.bias));
  return hits;
}

/** 차트 오버레이 — 형성 주봉 시각~현재 TF 마지막 봉 */
export function buildWeeklySharedSrOverlays(params: {
  weeklyCandles: Candle[];
  chartCandles: Candle[];
  chartTimeframe: string;
  maxPerSide?: number;
}): OverlayItem[] {
  const chart = params.chartCandles;
  if (chart.length < 2) return [];
  const hits = detectWeeklySharedSrHits(params);
  if (!hits.length) return [];

  const tEnd = Number(chart[chart.length - 1]!.time);
  const tChart0 = Number(chart[0]!.time);
  const out: OverlayItem[] = [];

  for (const h of hits) {
    const isSup = h.bias === 'support';
    /** 주봉 형성 시각이 차트 윈도우보다 왼쪽이면 차트 시작으로 클램프 */
    const t1 = Math.min(Math.max(h.weeklyTime, Number.isFinite(tChart0) ? tChart0 : h.weeklyTime), tEnd);
    const jointTag = h.jointWithChart ? '공동' : '1W';
    const label = isSup ? `${jointTag}지지` : `${jointTag}저항`;
    out.push({
      id: `${WEEKLY_SHARED_SR_ID_PREFIX}-${h.bias}-${h.weeklyIndex}-${Math.round(h.mid)}`,
      kind: isSup ? 'demandZone' : 'supplyZone',
      label,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 0,
      time1: t1 as UTCTimestamp,
      time2: tEnd as UTCTimestamp,
      price1: h.high,
      price2: h.low,
      confidence: Math.min(88, Math.max(48, h.strength)),
      color: isSup
        ? h.jointWithChart
          ? 'rgba(34,197,94,0.28)'
          : 'rgba(34,197,94,0.18)'
        : h.jointWithChart
          ? 'rgba(239,68,68,0.26)'
          : 'rgba(239,68,68,0.16)',
      category: 'smcDesk',
      structureBias: isSup ? 'bullish' : 'bearish',
      zoneFillPreserve: true,
      zoneSpanOnly: true,
      zoneFaceBase: label,
      zoneFaceSignal: h.jointWithChart ? 'JOINT' : '1W',
      zoneFaceLang: 'ko',
      overlayZoneExtraClass: `merged-desk-weekly-sr-zone ${
        isSup ? 'merged-desk-weekly-sr-support' : 'merged-desk-weekly-sr-resist'
      }${h.jointWithChart ? ' merged-desk-weekly-sr-joint' : ''}`,
      labelTooltip: [
        `주봉 ${isSup ? '지지' : '저항'} ${fmt(h.low)}~${fmt(h.high)}`,
        h.jointWithChart ? `현재 TF 피벗과 겹침(${jointTag})` : '주봉 기록 투영',
        `강도 ${h.strength}`,
      ].join(' · '),
      noProject: true,
    });
  }

  return out;
}

export function isWeeklySharedSrOverlayId(id: string | undefined | null): boolean {
  return String(id || '').startsWith(WEEKLY_SHARED_SR_ID_PREFIX);
}

