/**
 * 통합·분석 — 기능을 유지한 채 **하나의 방향 구름**으로 합쳐 작도.
 * 롱 구간 = 초록 구름, 숏 구간 = 빨강 구름 (이미지 1·2·3 의미).
 * ST 상·하한 + 마스터/스윙중투/종가게이트 편향. 글자 카드 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import type { MonthDeskBandFusionContext } from '@/lib/institutionalSuperBand';
import { buildMergedAdvancedStRibbonFillOverlays } from '@/lib/mergedAdvancedStRibbonFillOverlays';
import { buildMergedStCloudChartPack } from '@/lib/mergedAnalysisStCloudSignals';
import type { MasterFuturesDecision } from '@/lib/mergedDeskMasterFuturesDecision';
import type { SwingMidEntryPack } from '@/lib/mergedDeskSwingMidEntry';
import { mergedDeskShortTradeRailLabels } from '@/lib/mergedDeskChartOnlyUi';

export type MergedDeskUnifiedCloudBias = 'LONG' | 'SHORT' | 'NEUTRAL';

function resolveCloudBias(params: {
  master?: MasterFuturesDecision | null;
  swingMid?: SwingMidEntryPack | null;
  analyzeVerdict?: 'LONG' | 'SHORT' | null;
}): MergedDeskUnifiedCloudBias {
  const swing = params.swingMid;
  if (swing?.stance === 'ENTER_LONG' || (swing?.side === 'LONG' && swing.settleEnterAllowed !== false)) {
    return 'LONG';
  }
  if (swing?.stance === 'ENTER_SHORT' || (swing?.side === 'SHORT' && swing.settleEnterAllowed !== false)) {
    return 'SHORT';
  }
  if (params.master?.side === 'LONG' && params.master.entryAllowed) return 'LONG';
  if (params.master?.side === 'SHORT' && params.master.entryAllowed) return 'SHORT';
  if (params.master?.side === 'LONG') return 'LONG';
  if (params.master?.side === 'SHORT') return 'SHORT';
  if (params.analyzeVerdict === 'LONG' || params.analyzeVerdict === 'SHORT') return params.analyzeVerdict;
  return 'NEUTRAL';
}

/** 최근 구름 세그먼트에 통합 편향 색 강제 (꼬리·현재 구간) */
function applyBiasToCloudOverlays(
  overlays: OverlayItem[],
  bias: MergedDeskUnifiedCloudBias,
  enter: boolean
): OverlayItem[] {
  if (!overlays.length) return overlays;
  const shortLabel = mergedDeskShortTradeRailLabels();
  const n = overlays.length;
  const tailCount = Math.min(n, enter ? 8 : 5);

  return overlays.map((o, idx) => {
    const inTail = idx >= n - tailCount;
    const isLong =
      bias === 'LONG'
        ? true
        : bias === 'SHORT'
          ? false
          : o.structureBias === 'bullish' || String(o.label || '').includes('롱');

    const longFill = enter ? 'rgba(34,197,94,0.28)' : 'rgba(34,197,94,0.18)';
    const shortFill = enter ? 'rgba(239,68,68,0.26)' : 'rgba(239,68,68,0.16)';
    const fill =
      bias === 'NEUTRAL'
        ? o.color
        : inTail
          ? isLong
            ? longFill
            : shortFill
          : o.color;

    const dirLong = bias === 'NEUTRAL' ? o.structureBias === 'bullish' : isLong;

    return {
      ...o,
      id: String(o.id || '').replace('merged-ares-st-cloud', 'merged-unified-cloud'),
      label: shortLabel ? '' : dirLong ? '구름·롱' : '구름·숏',
      color: fill,
      structureBias: dirLong ? 'bullish' : 'bearish',
      confidence: enter && inTail ? 88 : Math.max(54, Number(o.confidence) || 52),
      overlayZoneExtraClass: [
        'merged-ares-st-cloud',
        'merged-unified-cloud',
        dirLong ? 'merged-unified-cloud--long' : 'merged-unified-cloud--short',
        enter && inTail ? 'merged-unified-cloud--enter' : '',
      ]
        .filter(Boolean)
        .join(' '),
      labelTooltip: dirLong
        ? '통합구름 · 롱 구간(초록) — 참고'
        : '통합구름 · 숏 구간(빨강) — 참고',
    };
  });
}

/**
 * 통합 분석 구름 팩 — ST 기하 + 마스터/스윙 색.
 */
export function buildMergedDeskUnifiedCloudPack(params: {
  candles: Candle[];
  timeframe: string;
  fusion: MonthDeskBandFusionContext | null | undefined;
  masterFutures?: MasterFuturesDecision | null;
  swingMid?: SwingMidEntryPack | null;
  analyzeVerdict?: 'LONG' | 'SHORT' | null;
}): {
  overlays: OverlayItem[];
  bias: MergedDeskUnifiedCloudBias;
  enter: boolean;
  summaryKo: string;
} {
  const bias = resolveCloudBias({
    master: params.masterFutures,
    swingMid: params.swingMid,
    analyzeVerdict: params.analyzeVerdict,
  });
  const enter =
    params.swingMid?.stance === 'ENTER_LONG' ||
    params.swingMid?.stance === 'ENTER_SHORT' ||
    (params.masterFutures?.entryAllowed === true &&
      (params.masterFutures.side === 'LONG' || params.masterFutures.side === 'SHORT'));

  const base = buildMergedStCloudChartPack({
    candles: params.candles,
    timeframe: params.timeframe,
    fusion: params.fusion,
  });

  let overlays = base.overlays.length
    ? base.overlays
    : buildMergedAdvancedStRibbonFillOverlays({
        candles: params.candles,
        timeframe: params.timeframe,
        fusion: params.fusion,
        longBandHex: '#22C55E',
        shortBandHex: '#EF4444',
      });

  overlays = applyBiasToCloudOverlays(overlays, bias, enter);

  const summaryKo =
    bias === 'LONG'
      ? enter
        ? '통합구름 · 롱(초록) ENTER'
        : '통합구름 · 롱(초록) 구간'
      : bias === 'SHORT'
        ? enter
          ? '통합구름 · 숏(빨강) ENTER'
          : '통합구름 · 숏(빨강) 구간'
        : '통합구름 · ST 방향 구간';

  return { overlays, bias, enter, summaryKo };
}

/** 회색·중복 채널 구름 제거 — 통합구름만 남김 */
export function filterOverlaysForUnifiedCloud(overlays: OverlayItem[]): OverlayItem[] {
  return overlays.filter((o) => {
    const id = String(o.id || '');
    if (id.startsWith('merged-unified-cloud') || id.startsWith('merged-ares-st-cloud')) return true;
    if (id.startsWith('merged-ares-ribbon')) return false;
    if (id.includes('merged-swing-channel-band')) return false;
    if (o.kind === 'channelBand' && o.category === 'chartPrimeTrendChannels') return false;
    return true;
  });
}

