  const downsideLayers = MERGED_DESK_DOWNSIDE_BOUNCE_PLAN_VISIBLE
    ? filterMergedDeskDownsideSupportOverlays(deskPack.overlays ?? [])
    : [];
  const entryLayers = (deskPack.overlays ?? []).filter((o) => {
