      extra.includes('merged-desk-hotzone-pair') ||
      extra.includes('merged-desk-hotzone-rail')
    );
  });
  const cloudLayers = unifiedCloudOn
    ? (deskPack.overlays ?? []).filter(isCloudOverlay)
    : [];

  const dedupe = (list: OverlayItem[]) => {
    const seen = new Set<string>();
    return list.filter((o) => {
      const k = String(o.id || '');
      if (!k || seen.has(k)) return false;
      seen.add(k);
      return true;
    });
