input.contents:
/**
 * 통합구름 칩 — ChartPrime 트렌드 채널과 동일 기하.
 * 위=빨강 저항 밴드 · 아래=초록 지지 밴드 · 흰=미래 경로 (참고·비보장).
 * SMC 작도와 무관 — 칩 ON일 때만 주입.
 */
import type { AnalyzeResponse, Candle, OverlayItem } from '@/types';
import {
  computeChartPrimeTrendChannelOverlays,
  computeSuggestedChartPrimePivotLength,
} from '@/lib/chartPrimeTrendChannels';
import { buildMonthDeskProjectedCandles } from '@/lib/monthDeskAdvancedChartPath';
import { sanitizeChartCandlesForSeries } from '@/lib/volumeHistogramIntelligence';
import { mergedWorkCandles } from '@/lib/mergedAnalysisOverlayTimes';

const CP_CLOUD_ID_PREFIX = 'merged-cp-cloud';
/** 이미지형: 상단 저항=빨강, 하단 지지=초록 */
const TOP_HEX = '#EF4444';
const BOTTOM_HEX = '#22C55E';
const CENTER_HEX = '#F8FAFC';

export function isMergedCpCloudOverlay(o: Pick<OverlayItem, 'id' | 'overlayZoneExtraClass'>): boolean {
  const id = String(o.id || '');
  const extra = String(o.overlayZoneExtraClass || '');
  return (
    id.startsWith(CP_CLOUD_ID_PREFIX) ||
    id.startsWith('merged-unified-cloud') ||
    id.startsWith('merged-ares-st-cloud') ||
    extra.includes('merged-cp-cloud') ||
    extra.includes('merged-unified-cloud') ||
    extra.includes('merged-ares-st-cloud')
  );
}

function remapCpToCloudOverlay(o: OverlayItem): OverlayItem {
  const id = String(o.id || '').replace(/^cptc-/, `${CP_CLOUD_ID_PREFIX}-`);
  const kind = String(o.kind || '');
  const isTop =
    id.includes('-top') ||
    id.includes('fill-top') ||
    (kind === 'channelBand' && String(o.color || '').includes('239'));
  const isBot =
    id.includes('-bot') ||
    id.includes('fill-bot') ||
    (kind === 'channelBand' && String(o.color || '').includes('34,197'));
  const isCenter = id.includes('-center');

  return {
    ...o,
    id,
    category: 'mergedCpCloud',
    zoneFillPreserve: kind === 'channelBand' ? true : o.zoneFillPreserve,
    structureBias: isTop ? 'bearish' : isBot ? 'bullish' : o.structureBias,
    color: isCenter ? 'rgba(248,250,252,0.92)' : o.color,
    lineStrokeWidth: isCenter ? 2.5 : o.lineStrokeWidth,
    lineDash: isCenter ? undefined : o.lineDash,
    overlayZoneExtraClass: [
      'merged-cp-cloud',
      'merged-unified-cloud',
      isTop ? 'merged-unified-cloud--short' : '',
      isBot ? 'merged-unified-cloud--long' : '',
      isCenter ? 'merged-cp-cloud--path' : '',
      String(o.overlayZoneExtraClass || ''),
    ]
      .filter(Boolean)
      .join(' '),
    label: '',
    labelTooltip: isTop
      ? '통합구름 · 상단 저항(빨강) — CP밴드 참고'
      : isBot
        ? '통합구름 · 하단 지지(초록) — CP밴드 참고'
        : isCenter
          ? '통합구름 · 중심·경로 — 참고'
          : '통합구름 · CP밴드 — 참고',
  };
}

/** 미래 흰 경로 — futurePaths 기반 고스트 캔들 연결선 (참고) */
function buildWhiteFuturePathOverlays(
  candles: Candle[],
  analysis: AnalyzeResponse | null | undefined,
  timeframe: string
): OverlayItem[] {
  if (candles.length < 5) return [];
  const ghost = buildMonthDeskProjectedCandles(candles, analysis
    ? { ...analysis, timeframe: analysis.timeframe || timeframe }
    : ({
        timeframe,
        verdict: 'LONG',
        currentPrice: candles[candles.length - 1]!.close,
        supportLevel: { price: candles[candles.length - 1]!.close * 0.97 },
        resistanceLevel: { price: candles[candles.length - 1]!.close * 1.05 },
      } as AnalyzeResponse));

  /** WAIT면 엔진이 빈 배열 — 짧은 중립 경로라도 표시 */
  let path = ghost;
  if (path.length < 2) {
    const last = candles[candles.length - 1]!;
    const barMs =
      candles.length >= 2
        ? Math.max(60_000, Number(last.time) - Number(candles[candles.length - 2]!.time))
        : 14_400_000;
    const close0 = Number(last.close);
    const atr = Math.max(close0 * 0.008, Math.abs(Number(last.high) - Number(last.low)));
    path = [];
    let prev = close0;
    for (let i = 1; i <= 10; i++) {
      const wobble = Math.sin(i * 1.3) * atr * 0.35;
      const close = close0 + (i / 10) * atr * 0.4 + wobble;
      path.push({
        time: Number(last.time) + barMs * i,
        open: prev,
        high: Math.max(prev, close) + atr * 0.15,
        low: Math.min(prev, close) - atr * 0.15,
        close,
        volume: 0,
      });
      prev = close;
    }
  }

  const out: OverlayItem[] = [];
  const anchor = candles[candles.length - 1]!;
  const pts = [
    { time: Number(anchor.time), price: Number(anchor.close) },
    ...path.map((c) => ({ time: Number(c.time), price: Number(c.close) })),
  ];

  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i]!;
    const b = pts[i + 1]!;
    if (![a.time, a.price, b.time, b.price].every(Number.isFinite)) continue;
    out.push({
      id: `${CP_CLOUD_ID_PREFIX}-future-path-${i}`,
      kind: 'trendLine',
      label: i === 0 ? '' : '',
      x1: 0,
      y1: 0.5,
      x2: 1,
      y2: 0.5,
      time1: a.time,
      time2: b.time,
      price1: a.price,
      price2: b.price,
      confidence: 55,
      color: 'rgba(248,250,252,0.88)',
      lineStrokeWidth: 2.25,
      noProject: true,
      category: 'mergedCpCloud',
      overlayZoneExtraClass: 'merged-cp-cloud merged-cp-cloud--path merged-unified-cloud',
      labelTooltip: '통합구름 · 미래 경로(흰선) — 시나리오 참고·비보장',
    });
  }
  return out;
}

/**
 * 통합구름 팩 — CP 밴드(빨강 상·초록 하) + 흰 미래 경로.
 */
export function buildMergedDeskUnifiedCloudPack(params: {
  candles: Candle[];
  timeframe: string;
  fusion?: unknown;
  masterFutures?: unknown;
  swingMid?: unknown;
  analyzeVerdict?: 'LONG' | 'SHORT' | null;
  analysis?: AnalyzeResponse | null;
}): {
  overlays: OverlayItem[];
  bias: 'LONG' | 'SHORT' | 'NEUTRAL';
  enter: boolean;
  summaryKo: string;
  projectedCandles: Candle[];
} {
  const safe = sanitizeChartCandlesForSeries(
    mergedWorkCandles(params.candles, params.timeframe),
    params.timeframe
  );
  if (safe.length < 24) {
    return {
      overlays: [],
      bias: 'NEUTRAL',
      enter: false,
      summaryKo: '통합구름 — 캔들 부족',
      projectedCandles: [],
    };
  }

  let min = Infinity;
  let max = -Infinity;
  for (const c of safe) {
    min = Math.min(min, c.low);
    max = Math.max(max, c.high);
  }
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) {
    return {
      overlays: [],
      bias: 'NEUTRAL',
      enter: false,
      summaryKo: '통합구름 — 가격 범위 없음',
      projectedCandles: [],
    };
  }

  const visIdx = (arr: Candle[], i: number) => Math.max(0, Math.min(arr.length - 1, Math.floor(i)));
  const visTime = (arr: Candle[], i: number) =>
    Number(arr[visIdx(arr, i)]?.time ?? arr[arr.length - 1]?.time ?? 0);

  const length = computeSuggestedChartPrimePivotLength(safe, params.timeframe);
  const cp = computeChartPrimeTrendChannelOverlays(safe, min, max, visTime, visIdx, {
    length,
    wait: true,
    extend: true,
    show: true,
    showFills: true,
    enableLiquid: false,
    channelWidthScale: 1,
    /** 이미지: 상단 빨강 · 하단 초록 (CP 기본과 반대 매핑) */
    topColor: TOP_HEX,
    bottomColor: BOTTOM_HEX,
    centerColor: CENTER_HEX,
  });

  const bandOverlays = (cp.overlays ?? []).map(remapCpToCloudOverlay);
  const pathOverlays = buildWhiteFuturePathOverlays(safe, params.analysis ?? null, params.timeframe);
  const projectedCandles = buildMonthDeskProjectedCandles(
    safe,
    params.analysis
      ? { ...params.analysis, timeframe: params.analysis.timeframe || params.timeframe }
      : null
  );

  const bias =
    params.analyzeVerdict === 'LONG' || params.analyzeVerdict === 'SHORT'
      ? params.analyzeVerdict
      : 'NEUTRAL';

  return {
    overlays: [...bandOverlays, ...pathOverlays],
    bias,
    enter: false,
    summaryKo: `통합구름 · CP밴드(빨강↑·초록↓) · 흰경로 ${pathOverlays.length}세그 — 참고`,
    projectedCandles,
  };
}

/** 회색·중복 채널 제거 — 통합 CP구름만 남김 */
export function filterOverlaysForUnifiedCloud(overlays: OverlayItem[]): OverlayItem[] {
  return overlays.filter((o) => {
    const id = String(o.id || '');
    if (isMergedCpCloudOverlay(o)) return true;
    if (id.startsWith('merged-ares-ribbon')) return false;
    if (id.includes('merged-swing-channel-band')) return false;
    /** 전역 CP와 중복 방지 — 통합구름 칩이 CP를 담당 */
    if (o.kind === 'channelBand' && o.category === 'chartPrimeTrendChannels') return false;
    if (id.startsWith('cptc-')) return false;
    return true;
  });
}

