function barStepMs(candles: Candle[]): number {
  if (candles.length < 2) return 14_400_000;
  const d = Number(candles[candles.length - 1]!.time) - Number(candles[candles.length - 2]!.time);
  return Number.isFinite(d) && d > 0 ? d : 14_400_000;
}

function lerpPrice(t0: number, p0: number, t1: number, p1: number, t: number): number {
  if (!Number.isFinite(t0) || !Number.isFinite(t1) || t1 === t0) return p1;
  const r = (t - t0) / (t1 - t0);
  return p0 + (p1 - p0) * r;
}

/**
 * 이미지형 큰 구간 — CP 채널을 차트 대부분(기본 82%) + 미래 약간까지 늘림.
 * 세로 폭도 키워 상·하 밴드가 넓게 보이게 함.
 */
function stretchCpCloudToWideSpan(
  overlays: OverlayItem[],
  candles: Candle[],
  opts?: { spanFrac?: number; futureBars?: number; widthBoost?: number }
): OverlayItem[] {
  const n = candles.length;
  if (n < 8 || !overlays.length) return overlays;
  const spanFrac = Math.max(0.55, Math.min(0.95, opts?.spanFrac ?? 0.82));
  const futureBars = Math.max(0, Math.min(48, opts?.futureBars ?? 16));
  const widthBoost = Math.max(1, Math.min(2.4, opts?.widthBoost ?? 1.65));
  const startIdx = Math.max(0, Math.floor(n * (1 - spanFrac)));
  const tStart = Number(candles[startIdx]!.time);
  const tLast = Number(candles[n - 1]!.time);
  const step = barStepMs(candles);
  const tEnd = tLast + step * futureBars;
  if (![tStart, tLast, tEnd].every(Number.isFinite) || tEnd <= tStart) return overlays;

  const mid = (candles[n - 1]!.high + candles[n - 1]!.low) / 2;

  return overlays.map((o) => {
    const kind = String(o.kind || '');
    if (kind === 'channelBand' && o.channelBand) {
      const cb = o.channelBand;
      const t0 = Number(cb.time1);
      const t1 = Number(cb.time2);
      const hi0 = lerpPrice(t0, cb.priceHigh1, t1, cb.priceHigh2, tStart);
      const hi1 = lerpPrice(t0, cb.priceHigh1, t1, cb.priceHigh2, tEnd);
      const lo0 = lerpPrice(t0, cb.priceLow1, t1, cb.priceLow2, tStart);
      const lo1 = lerpPrice(t0, cb.priceLow1, t1, cb.priceLow2, tEnd);
      const expand = (hi: number, lo: number) => {
        const c = (hi + lo) / 2;
        const half = (Math.abs(hi - lo) / 2) * widthBoost;
        return { hi: c + half, lo: c - half };
      };
      const a = expand(hi0, lo0);
      const b = expand(hi1, lo1);
      return {
        ...o,
        time1: tStart,
        time2: tEnd,
        price1: a.hi,
        price2: b.lo,
        x1: 0,
        x2: 1,
        channelBand: {
          time1: tStart,
          time2: tEnd,
          priceHigh1: a.hi,
          priceHigh2: b.hi,
          priceLow1: a.lo,
          priceLow2: b.lo,
        },
        noProject: false,
      };
    }
    if (kind === 'trendLine' || kind === 'keyLevel') {
      const id = String(o.id || '');
      if (id.includes('future-path')) return o;
      const t0 = Number(o.time1);
      const t1 = Number(o.time2);
      const p0 = Number(o.price1);
      const p1 = Number(o.price2);
      if (![t0, t1, p0, p1].every(Number.isFinite)) return o;
      let np0 = lerpPrice(t0, p0, t1, p1, tStart);
      let np1 = lerpPrice(t0, p0, t1, p1, tEnd);
      /** 상·하 외곽선만 폭 보강 */
      if (id.includes('-top') && !id.includes('mid') && !id.includes('zone')) {
        const lift = Math.abs(np0 - mid) * (widthBoost - 1) * 0.35;
        np0 += lift;
        np1 += lift;
      } else if (id.includes('-bot') && !id.includes('mid') && !id.includes('zone')) {
        const drop = Math.abs(np0 - mid) * (widthBoost - 1) * 0.35;
        np0 -= drop;
        np1 -= drop;
      }
      return {
        ...o,
        time1: tStart,
        time2: tEnd,
        price1: np0,
        price2: np1,
        x1: 0,
        x2: 1,
        lineStrokeWidth: Math.max(2, Number(o.lineStrokeWidth) || 2),
        noProject: false,
      };
    }
    return o;
  });
}

/** 미래 흰 경로 — futurePaths 기반 고스트 캔들 연결선 (참고) */
function buildWhiteFuturePathOverlays(
  candles: Candle[],
  analysis: AnalyzeResponse | null | undefined,
  timeframe: string
): OverlayItem[] {
  if (candles.length < 5) return [];
  const ghost = buildMonthDeskProjectedCandles(
    candles,
    analysis
      ? { ...analysis, timeframe: analysis.timeframe || timeframe }
      : null
  );

  /** WAIT·무분석이면 짧은 시나리오 경로라도 표시 (참고) */
  let path = ghost;
  if (path.length < 2) {
    const last = candles[candles.length - 1]!;
    const barMs =
      candles.length >= 2
        ? Math.max(60_000, Number(last.time) - Number(candles[candles.length - 2]!.time))
        : 14_400_000;
    const close0 = Number(last.close);
    const atr = Math.max(close0 * 0.008, Math.abs(Number(last.high) - Number(last.low)));
    path = [];
    let prev = close0;
    for (let i = 1; i <= 18; i++) {
      const wobble = Math.sin(i * 1.3) * atr * 0.35;
      const close = close0 + (i / 18) * atr * 0.55 + wobble;
      path.push({
        time: Number(last.time) + barMs * i,
        open: prev,
        high: Math.max(prev, close) + atr * 0.15,
        low: Math.min(prev, close) - atr * 0.15,
        close,
        volume: 0,
      });
      prev = close;
    }
  }

  const out: OverlayItem[] = [];
  const anchor = candles[candles.length - 1]!;
  const pts = [
    { time: Number(anchor.time), price: Number(anchor.close) },
    ...path.map((c) => ({ time: Number(c.time), price: Number(c.close) })),
  ];

  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i]!;
    const b = pts[i + 1]!;
    if (![a.time, a.price, b.time, b.price].every(Number.isFinite)) continue;
    out.push({
      id: `${CP_CLOUD_ID_PREFIX}-future-path-${i}`,
      kind: 'trendLine',
      label: i === 0 ? '' : '',
      x1: 0,
      y1: 0.5,
      x2: 1,
      y2: 0.5,
      time1: a.time,
      time2: b.time,
      price1: a.price,
      price2: b.price,
      confidence: 55,
      color: 'rgba(248,250,252,0.88)',
      lineStrokeWidth: 2.25,
      noProject: true,
      category: 'mergedCpCloud',
      overlayZoneExtraClass: 'merged-cp-cloud merged-cp-cloud--path merged-unified-cloud',
      labelTooltip: '통합구름 · 미래 경로(흰선) — 시나리오 참고·비보장',
    });
  }
  return out;
}

/**
 * 통합구름 팩 — CP 밴드(빨강 상·초록 하, 큰 구간) + 흰 미래 경로.
 */
export function buildMergedDeskUnifiedCloudPack(params: {
  candles: Candle[];
  timeframe: string;
  fusion?: unknown;
  masterFutures?: unknown;
  swingMid?: unknown;
  analyzeVerdict?: 'LONG' | 'SHORT' | null;
  analysis?: AnalyzeResponse | null;
}): {
  overlays: OverlayItem[];
  bias: 'LONG' | 'SHORT' | 'NEUTRAL';
  enter: boolean;
  summaryKo: string;
  projectedCandles: Candle[];
} {
  const safe = sanitizeChartCandlesForSeries(
    mergedWorkCandles(params.candles, params.timeframe),
    params.timeframe
  );
  if (safe.length < 24) {
    return {
      overlays: [],
      bias: 'NEUTRAL',
      enter: false,
      summaryKo: '통합구름 — 캔들 부족',
      projectedCandles: [],
    };
  }

  let min = Infinity;
  let max = -Infinity;
  for (const c of safe) {
    min = Math.min(min, c.low);
    max = Math.max(max, c.high);
  }
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) {
    return {
      overlays: [],
      bias: 'NEUTRAL',
      enter: false,
      summaryKo: '통합구름 — 가격 범위 없음',
      projectedCandles: [],
    };
  }

  const visIdx = (arr: Candle[], i: number) => Math.max(0, Math.min(arr.length - 1, Math.floor(i)));
  const visTime = (arr: Candle[], i: number) =>
    Number(arr[visIdx(arr, i)]?.time ?? arr[arr.length - 1]?.time ?? 0);

  /** 큰 구간용 — 긴 피벗 + 최대 채널 폭 (CP 엔진 상한) */
  const suggested = computeSuggestedChartPrimePivotLength(safe, params.timeframe);
  const length = Math.max(suggested, Math.min(30, Math.max(18, Math.floor(safe.length / 14))));
  const cp = computeChartPrimeTrendChannelOverlays(safe, min, max, visTime, visIdx, {
    length,
    wait: true,
    extend: true,
    show: true,
    showFills: true,
    enableLiquid: false,
    channelWidthScale: 1.35,
    topColor: TOP_HEX,
    bottomColor: BOTTOM_HEX,
    centerColor: CENTER_HEX,
  });

  const bandOverlays = stretchCpCloudToWideSpan(
    (cp.overlays ?? []).map(remapCpToCloudOverlay),
    safe,
    { spanFrac: 0.84, futureBars: 18, widthBoost: 1.75 }
  );
  const pathOverlays = buildWhiteFuturePathOverlays(safe, params.analysis ?? null, params.timeframe);
  const projectedCandles = buildMonthDeskProjectedCandles(
    safe,
    params.analysis
      ? { ...params.analysis, timeframe: params.analysis.timeframe || params.timeframe }
      : null
  );

  const bias =
    params.analyzeVerdict === 'LONG' || params.analyzeVerdict === 'SHORT'
      ? params.analyzeVerdict
      : 'NEUTRAL';

  return {
    overlays: [...bandOverlays, ...pathOverlays],
    bias,
    enter: false,
    summaryKo: `통합구름 · CP큰구간(빨강↑·초록↓) · 흰경로 — 참고`,
    projectedCandles,
  };
}

