/** 차트 우측 가격축 — 낭비 공간 줄이기 */
export function getChartPriceScaleLayout(opts: {
  mobileFs?: boolean;
  chartFullscreen?: boolean;
  mergedDesk?: boolean;
}): {
  minimumWidth: number;
  rightOffset: number;
  bitgetRightOffset: number;
  layoutFontSize?: number;
} {
  const compact = Boolean(opts.mobileFs || opts.chartFullscreen || opts.mergedDesk);
  return {
    /** 폰 FS: 가격축 숫자 읽기 쉽게 약간 넓게 */
    minimumWidth: opts.mobileFs ? 44 : compact ? 46 : 58,
    rightOffset: opts.mobileFs ? 2 : compact ? 5 : 10,
    bitgetRightOffset: opts.mobileFs ? 3 : compact ? 8 : 14,
    layoutFontSize: opts.mobileFs ? 11 : compact ? 11 : undefined,
  };
}

input.new_string:
/** 차트 우측 가격축 — 낭비 공간 줄이기 · axisFontSize로 숫자·축폭 사용자 조절 */
export function getChartPriceScaleLayout(opts: {
  mobileFs?: boolean;
  chartFullscreen?: boolean;
  mergedDesk?: boolean;
  /** 우측 가격축·축옆 라벨 글자 (차트 본문 SL/E/TP 라벨과 별개) */
  axisFontSize?: number;
}): {
  minimumWidth: number;
  rightOffset: number;
  bitgetRightOffset: number;
  layoutFontSize?: number;
} {
  const compact = Boolean(opts.mobileFs || opts.chartFullscreen || opts.mergedDesk);
  const userFs =
    opts.axisFontSize != null && Number.isFinite(opts.axisFontSize)
      ? Math.max(8, Math.min(16, Math.round(opts.axisFontSize)))
      : null;
  const layoutFontSize = userFs ?? (opts.mobileFs || compact ? 11 : undefined);
  const minimumWidth =
    layoutFontSize != null
      ? Math.max(32, Math.min(78, Math.round(layoutFontSize * (opts.mobileFs ? 3.6 : 4.2) + (opts.mobileFs ? 6 : 10))))
      : opts.mobileFs
        ? 44
        : compact
          ? 46
          : 58;
  return {
    minimumWidth,
    rightOffset: opts.mobileFs ? 2 : compact ? 5 : 10,
    bitgetRightOffset: opts.mobileFs ? 3 : compact ? 8 : 14,
    layoutFontSize,
  };
}

