/**
 * 브라우저 공유 마켓 캔들 캐시 — TF 전환 시 ChartView·prefetch가 같은 in-flight를 쓰고
 * 직전 응답을 즉시 화면에 붙인다 (빈 차트 깜빡임·중복 fetch 완화).
 */
import type { Candle } from '@/types';

export type ClientMarketSource = 'binance' | 'bitget';

type CacheEntry = {
  candles: Candle[];
  fetchedAt: number;
};

const TTL_MS = 48_000;
const MAX_ENTRIES = 48;
const dataCache = new Map<string, CacheEntry>();
const inflight = new Map<string, Promise<Candle[]>>();

export function clientMarketCacheKey(
  symbol: string,
  timeframe: string,
  source: ClientMarketSource = 'binance'
): string {
  return `${source}|${symbol}|${timeframe}`;
}

export function peekClientMarketCandles(
  symbol: string,
  timeframe: string,
  source: ClientMarketSource = 'binance'
): Candle[] | null {
  const key = clientMarketCacheKey(symbol, timeframe, source);
  const hit = dataCache.get(key);
  if (!hit) return null;
  if (Date.now() - hit.fetchedAt > TTL_MS) return null;
  return hit.candles;
}

export function putClientMarketCandles(
  symbol: string,
  timeframe: string,
  candles: Candle[],
  source: ClientMarketSource = 'binance'
): void {
  if (!candles.length) return;
  const key = clientMarketCacheKey(symbol, timeframe, source);
  dataCache.set(key, { candles, fetchedAt: Date.now() });
  if (dataCache.size > MAX_ENTRIES) {
    const oldest = dataCache.keys().next().value;
    if (oldest) dataCache.delete(oldest);
  }
}

function marketUrl(symbol: string, timeframe: string, source: ClientMarketSource): string {
  const base = source === 'bitget' ? '/api/market-bitget' : '/api/market';
  return `${base}?symbol=${encodeURIComponent(symbol)}&timeframe=${encodeURIComponent(timeframe)}`;
}

/**
 * 동일 (symbol,tf,source) in-flight 병합 + TTL 캐시.
 * AbortSignal이 있어도 캐시/다른 구독자용 promise는 유지한다.
 */
export async function fetchClientMarketCandles(opts: {
  symbol: string;
  timeframe: string;
  source?: ClientMarketSource;
  signal?: AbortSignal;
}): Promise<Candle[]> {
  const source = opts.source ?? 'binance';
  const key = clientMarketCacheKey(opts.symbol, opts.timeframe, source);
  const fresh = peekClientMarketCandles(opts.symbol, opts.timeframe, source);
  if (fresh?.length) return fresh;

  let pending = inflight.get(key);
  if (!pending) {
    pending = (async () => {
      try {
        const res = await fetch(marketUrl(opts.symbol, opts.timeframe, source), {
          credentials: 'same-origin',
          cache: 'no-store',
        });
        if (!res.ok) throw new Error(`market ${res.status}`);
        const payload = (await res.json()) as { ok?: boolean; candles?: Candle[]; error?: string };
