 */
function snapOverlayItemTimesToChartWindow(
  raw: OverlayItem,
  candles: Candle[],
  sourceCandles?: Candle[],
  timeframe?: string
): OverlayItem {
  const kind = String(raw.kind || '');
  const isZoneFace =
    kind === 'zone' ||
    kind === 'supplyZone' ||
    kind === 'demandZone' ||
    kind === 'box' ||
    Boolean(raw.channelBand);
  if (isZoneFace && candles.length >= 2) {
    const win = mergedDeskLastCandleZoneTimes(candles, timeframe || '4h');
    if (win) {
      const next: OverlayItem = {
        ...raw,
        time1: snapMergedOverlayTimeToCandles(Number(win.t1), candles),
        time2: snapMergedOverlayTimeToCandles(Number(win.t2), candles),
        x1: 0,
        x2: 1,
      };
      if (raw.channelBand) {
        const cb = raw.channelBand;
        next.channelBand = {
          ...cb,
          time1: snapMergedOverlayTimeToCandles(Number(win.t1), candles),
          time2: snapMergedOverlayTimeToCandles(Number(win.t2), candles),
        };
      }
      return next;
    }
  }
  if (!sourceCandles || sourceCandles.length < 2 || candles.length < 2) {
    return snapOverlayItemTimesToCandles(raw, candles);
  }
  const hasTime =
    typeof raw.time1 === 'number' ||
    typeof raw.time2 === 'number' ||
    (raw.channelBand && (raw.channelBand.time1 != null || raw.channelBand.time2 != null));
  if (!hasTime) return raw;
  const remap = (t: number) => remapMergedDeskSignalTimeToChart(t, candles, sourceCandles);
  const next: OverlayItem = { ...raw };
  if (typeof next.time1 === 'number') next.time1 = remap(next.time1) as UTCTimestamp;
  if (typeof next.time2 === 'number') next.time2 = remap(next.time2) as UTCTimestamp;
  if (next.channelBand) {
    const cb = next.channelBand;
    next.channelBand = {
      ...cb,
      time1: remap(Number(cb.time1)) as UTCTimestamp,
      time2: remap(Number(cb.time2)) as UTCTimestamp,
    };
  }
  return next;
}

