    return n < tFirst ? tFirst : null;
  };
  let next = item;
  const c1 = pull(item.time1);
  const c2 = pull(item.time2);
  if (c1 != null || c2 != null) {
    next = { ...next };
    if (c1 != null) next.time1 = c1 as UTCTimestamp;
    if (c2 != null) next.time2 = c2 as UTCTimestamp;
