/**
 * analyze·desk 엔진 time → 차트 setData 캔들 time (끝에서부터 인덱스 정렬 후 스냅).
 * 시계열 불일치 시 전부 마지막 봉으로 몰리는 현상 완화.
 */
export function remapMergedDeskSignalTimeToChart(
  t: number,
  chartCandles: Candle[],
  sourceCandles?: Candle[]
): number {
  if (!chartCandles.length || !Number.isFinite(t)) return t;
  const exact = chartCandles.find((c) => Number(c.time) === t);
  if (exact) return t;

  const src =
    sourceCandles && sourceCandles.length >= 2 ? sourceCandles : chartCandles;
  const srcIdx = candleIndexAtOrBeforeInSeries(src, t);
  const offsetFromEnd = src.length - 1 - srcIdx;
  const chartIdx = Math.max(0, Math.min(chartCandles.length - 1, chartCandles.length - 1 - offsetFromEnd));
  const mapped = Number(chartCandles[chartIdx]!.time);
  if (Number.isFinite(mapped)) return mapped;

  return Number(snapMergedOverlayTimeToCandles(t, chartCandles));
}

