/** zone 면 좌(분석 구간)~우(마지막 봉) — TF 무관 동일 봉 수 */
export function mergedDeskZoneSpanTimes(
  candles: Candle[]
): { t1: UTCTimestamp; t2: UTCTimestamp; startIdx: number; endIdx: number } | null {
  const n = candles.length;
  if (n < 2) return null;
  const endIdx = n - 1;
