    timeToX: params.timeToX,
    chartRightPx: params.chartRightPx,
    safeXLastBar: params.safeXLastBar,
  });
  if (!span) return null;
  const xRight = Math.min(params.chartRightPx, Math.max(params.safeXLastBar, span.xRight));
  return { xLeft: span.xLeft, xRight };
}

