/** setData에 올린 봉 수 — candleSeries 인덱스를 시리즈 logical에 맞춤 */
function candlestickSeriesBarCount(series: ISeriesApi<'Candlestick'>): number {
  try {
    let lo = 0;
    let hi = 1;
    while (series.dataByIndex(hi as unknown as Logical, MismatchDirection.NearestLeft) != null) {
      lo = hi;
      hi = hi * 2 + 1;
      if (hi > 250_000) break;
    }
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (series.dataByIndex(mid as unknown as Logical, MismatchDirection.NearestLeft) != null) lo = mid;
      else hi = mid - 1;
    }
    return lo + 1;
  } catch {
    return 0;
  }
}

input.new_string:
/** setData에 올린 봉 수 — candleSeries 인덱스를 시리즈 logical에 맞춤 */
function candlestickSeriesBarCount(series: ISeriesApi<'Candlestick'>): number {
  try {
    /**
     * NearestLeft는 범위 밖 인덱스에도 마지막 봉을 돌려 null이 안 됨 → 예전에 ~250k로 부풀어
     * logicalToCoordinate(마지막)이 어긋남. 정확 인덱스만 인정.
     */
    const at = (i: number) => {
      try {
        return series.dataByIndex(i as unknown as Logical, MismatchDirection.None);
      } catch {
        return null;
      }
    };
    if (at(0) == null) return 0;
    let lo = 0;
    let hi = 1;
    while (at(hi) != null) {
      lo = hi;
      hi = hi * 2 + 1;
      if (hi > 250_000) break;
    }
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if (at(mid) != null) lo = mid;
      else hi = mid - 1;
    }
    return lo + 1;
  } catch {
    return 0;
  }
}

