    if (Number.isFinite(xFirst) && xFirst >= 0) xLeft = Math.max(xFirst - barW * 0.48, xLeft);
  }
  if (!Number.isFinite(xLeft) || !Number.isFinite(xRight) || xRight <= xLeft) {
    return null;
  }
  return { xLeft, xRight };
}

