input.contents:
/**
 * 통합·분석 zone 차트 캡션 정리 — 면·기능은 유지, 라벨만 짧게·우선순위 적용.
 * 삭제 금지: overlays 제거하지 않음. face-minimal = 캡션만 숨김.
 * 전문 작도: 지지·저항 캡션 각 ≤1 (HQ/HotZone 우선), 나머지는 면만.
 */
import type { OverlayItem } from '@/types';
import {
  isMergedDeskAnalyzedCandleSpanOverlay,
  isMergedAnalysisDeskOverlayId,
} from '@/lib/mergedAnalysisOverlayIds';

const ZONE_KINDS = new Set([
  'zone',
  'box',
  'supplyZone',
  'demandZone',
  'fvg',
  'ob',
  'reactionZone',
  'bprZone',
]);

function isZoneFace(o: OverlayItem): boolean {
  return ZONE_KINDS.has(String(o.kind || '')) || !!o.channelBand;
}

/** 차트에 찍을 짧은 캡션 (툴팁은 원문 유지) */
export function compactMergedDeskZoneChartLabel(raw: string): string {
  let s = String(raw || '').trim();
  if (!s) return '';

  /** 시나리오 장문 → 번호·키워드만 */
  if (/^[①②③④⑤]/.test(s) || /반등 여력|되돌림 깊|진도|전량 매도|반등국면|시나리오/.test(s)) {
    const head = s.split(/[→·|]/)[0]?.trim() || s;
    const short = head.replace(/\s+/g, ' ').slice(0, 12);
    return short || '시나리오';
  }

  s = s.replace(/^핵심\s+/, '');
  s = s.replace(/★ENTRY\b/gi, '★진입');
  s = s.replace(/\bENTRY\b/gi, '진입');
  s = s.replace(/\bWAIT\b/gi, '대기');
  s = s.replace(/진입점/g, '진입');
  s = s.replace(/롱진입/g, '롱');
  s = s.replace(/숏진입/g, '숏');
  s = s.replace(/저항대/g, '저항');
  s = s.replace(/지지대/g, '지지');
  s = s.replace(/\s*·\s*(대기|대|터치|진입가능|진입)$/g, '');
  s = s.replace(/\s+/g, ' ').trim();

  /** 가격이 길면 정수만 */
  s = s.replace(/(\d{1,3}(?:,\d{3})+)(?:\.\d+)?/g, (_, n: string) => n.replace(/,/g, ''));
  s = s.replace(/(\d+\.\d{2,})/g, (m) => {
    const n = Number(m);
    return Number.isFinite(n) ? String(Math.round(n)) : m;
  });

  if (s.length > 12) s = `${s.slice(0, 11)}…`;
  return s;
}

function captionPriority(o: OverlayItem): number {
  const id = String(o.id || '');
  const extra = String(o.overlayZoneExtraClass || '');
  /** 차트에 남길 캡션 — HQ · 핵심 HotZone만 */
  if (id.startsWith('merged-desk-hq-') || extra.includes('merged-hq-entry-zone')) return 100;
  if (
    (id.startsWith('merged-desk-hotzone-') || extra.includes('merged-desk-hotzone-entry')) &&
    (extra.includes('merged-desk-hotzone-entry--primary') ||
      extra.includes('hotzone-entry--enter') ||
      String(o.label || '').includes('★'))
  ) {
    return 96;
  }
  if (id.startsWith('merged-desk-hotzone-') || extra.includes('merged-desk-hotzone-pair')) return 70;
  if (id.startsWith('merged-desk-core-sr') && extra.includes('--primary')) return 68;
  if (id.startsWith('merged-desk-core-sr') || extra.includes('merged-desk-core-sr')) return 55;
  /** 보조 면 — 캡션 숨김 (캔들 가독) */
  if (
    id.includes('-liq-band-') ||
    id.includes('-struct-band-') ||
    id.includes('-dir-verdict') ||
    id.includes('-consolidation') ||
    id.includes('-breakout') ||
    id.includes('-range') ||
    id.includes('-fvg') ||
    extra.includes('mlsp-tv-liq') ||
    extra.includes('mlsp-tv-struct') ||
    extra.includes('verdict-ribbon')
  ) {
    return 18;
  }
  if (extra.includes('merged-desk-pill-zone')) return 45;
  if (id.startsWith('merged-ares-mlsp-tv-')) return 40;
  if (extra.includes('bounce') || extra.includes('scenario') || /^[①②③④⑤]/.test(String(o.label || '')))
    return 22;
  if (id.endsWith('-pin') || o.kind === 'label') return 12;
  return 35;
}

function isDemandSide(o: OverlayItem): boolean {
  const id = String(o.id || '');
  const extra = String(o.overlayZoneExtraClass || '');
  const label = String(o.label || '');
  if (o.kind === 'demandZone') return true;
  if (o.kind === 'supplyZone') return false;
  if (/support|지지|demand|롱|long|below/i.test(`${id} ${extra} ${label}`)) return true;
  if (/resist|저항|supply|숏|short|above/i.test(`${id} ${extra} ${label}`)) return false;
  const p1 = Number(o.price1);
  const p2 = Number(o.price2);
  if (Number.isFinite(p1) && Number.isFinite(p2)) return Math.min(p1, p2) < Math.max(p1, p2);
  return true;
}

/** 전문 작도: 롱·숏 캡션 각 1개만 (캔들 위 라벨 스택 금지) */
const MAX_CAPTION_DEMAND = 1;
const MAX_CAPTION_SUPPLY = 1;

/**
 * zone 면은 전부 유지. 캡션만 축약·우선순위 캡.
 * 낮은 순위는 `merged-desk-zone-face-minimal`(캡션 CSS 숨김) + `merged-desk-zone-pro-soft`.
 */
export function applyMergedDeskZoneChartLabelClean(overlays: OverlayItem[]): OverlayItem[] {
  if (!overlays.length) return overlays;

  const zoneIdx: number[] = [];
  for (let i = 0; i < overlays.length; i++) {
    const o = overlays[i]!;
    if (!isZoneFace(o)) continue;
    if (!isMergedAnalysisDeskOverlayId(o.id) && !isMergedDeskAnalyzedCandleSpanOverlay(o)) continue;
    zoneIdx.push(i);
  }
  if (!zoneIdx.length) return overlays;

  const ranked = zoneIdx
    .map((i) => ({ i, pri: captionPriority(overlays[i]!), demand: isDemandSide(overlays[i]!) }))
    .sort((a, b) => b.pri - a.pri);

  const keepCaption = new Set<number>();
  let d = 0;
  let s = 0;
  for (const row of ranked) {
    if (row.pri < 60) continue; // HQ/HotZone/핵심만
    if (row.demand) {
      if (d >= MAX_CAPTION_DEMAND) continue;
      d += 1;
    } else {
      if (s >= MAX_CAPTION_SUPPLY) continue;
      s += 1;
    }
    keepCaption.add(row.i);
  }

  return overlays.map((raw, i) => {
    if (!zoneIdx.includes(i)) {
      const id = String(raw.id || '');
      const label = String(raw.label || '');
      const kind = String(raw.kind || '');
      /** BOS/ChoCH·장문 핀 라벨 숨김 (면/기능 유지) */
      if (
        kind === 'bos' ||
        kind === 'choch' ||
        kind === 'label' ||
        id.includes('-struct-') ||
        id.endsWith('-pin')
      ) {
        return {
          ...raw,
          label: '',
          labelTooltip: String(raw.labelTooltip || label),
          overlayZoneExtraClass: `${String(raw.overlayZoneExtraClass || '')} merged-desk-zone-face-minimal`.trim(),
        };
      }
      if (
        (id.startsWith('merged-') || id.startsWith('atlas-pulse-')) &&
        label.length > 14 &&
        (kind === 'keyLevel' || kind === 'scenario')
      ) {
        const compact = compactMergedDeskZoneChartLabel(label);
        if (compact && compact !== label) {
          return {
            ...raw,
            label: compact,
            labelTooltip: String(raw.labelTooltip || label),
          };
        }
      }
      return raw;
    }

    const extra = String(raw.overlayZoneExtraClass || '');
    const full = String(raw.label || '').trim();
    const compact = compactMergedDeskZoneChartLabel(full);
    const showCap = keepCaption.has(i);
    const isHero =
      extra.includes('merged-hq-entry-zone') ||
      extra.includes('merged-desk-hotzone-entry--primary') ||
      (extra.includes('merged-desk-hotzone-entry') && String(raw.label || '').includes('★'));

    if (!showCap) {
      return {
        ...raw,
        label: '',
        labelTooltip: String(raw.labelTooltip || full),
        overlayZoneExtraClass: `${extra
          .replace(/\bmerged-desk-zone-caption-clean\b/g, '')
          .trim()} merged-desk-zone-face-minimal merged-desk-zone-pro-soft`.trim(),
      };
    }

    return {
      ...raw,
      label: compact || full,
      labelTooltip: String(raw.labelTooltip || full),
      overlayZoneExtraClass: `${extra
        .replace(/\bmerged-desk-zone-face-minimal\b/g, '')
        .replace(/\bmerged-desk-zone-pro-soft\b/g, '')
        .trim()} merged-desk-zone-caption-clean${isHero ? ' merged-desk-zone-pro-hero' : ''}`.trim(),
    };
  });
}

