/**
 * 통합·분석 차트 — zone 면·라벨 정리 (15m 공유 분석, 전 TF 동일).
 * 전문 작도: 보조 면은 연하게, 캡션은 HQ/HotZone만.
 */
import type { Candle, OverlayItem } from '@/types';
import type { MergedTradeSignal } from '@/lib/mergedAnalysisTradeLayer';
import { mergedDeskLastCandleZoneBars } from '@/lib/mergedAnalysisOverlayTimes';
import { applyMergedDeskZoneChartLabelClean } from '@/lib/mergedDeskZoneChartLabelClean';

const SWING_FUSION_ZONE_IDS = new Set([
  'merged-swing-fusion-risk',
  'merged-swing-fusion-reward-tp1',
  'merged-swing-fusion-reward-ext',
  'merged-swing-fusion-entry-pocket',
]);

function softenRgba(color: unknown, alpha: number): string | undefined {
  const s = String(color || '');
  const m = s.match(/rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)(?:\s*,\s*([\d.]+))?\s*\)/i);
  if (!m) return undefined;
  const r = Number(m[1]);
  const g = Number(m[2]);
  const b = Number(m[3]);
  return `rgba(${r},${g},${b},${alpha})`;
}

function isSecondaryMirageFace(id: string, extra: string): boolean {
  return (
    id.includes('-liq-band-') ||
    id.includes('-struct-band-') ||
    id.includes('-dir-verdict') ||
    id.includes('-consolidation') ||
    id.includes('-breakout') ||
    id.includes('-range') ||
    id.includes('-fvg') ||
    extra.includes('verdict-ribbon') ||
    extra.includes('mlsp-tv-liq') ||
    extra.includes('mlsp-tv-struct')
  );
}

/** 스윙 fusion 면 제거(가로선만) · regime 밴드 축소 · zone 라벨 최소화 */
export function polishMergedDeskChartOverlays(
  overlays: OverlayItem[],
  candles: Candle[],
  timeframe: string,
  trade?: MergedTradeSignal | null
): OverlayItem[] {
  if (!overlays.length || candles.length < 2) return overlays;

  const close = Number(candles[candles.length - 1]?.close);
  const width = mergedDeskLastCandleZoneBars(timeframe);
  const tail = candles.slice(-Math.min(width + 12, candles.length));
  let tLo = Infinity;
  let tHi = -Infinity;
  for (const c of tail) {
    tLo = Math.min(tLo, c.low);
    tHi = Math.max(tHi, c.high);
  }
  if (Number.isFinite(close) && close > 0) {
    const corridor = trade
      ? [trade.entry, trade.stopLoss, trade.tp1, trade.tp2, trade.tp3, close].filter(
          (p) => Number.isFinite(p) && p > 0
        )
      : [close];
    if (corridor.length) {
      tLo = Math.min(tLo, ...corridor);
      tHi = Math.max(tHi, ...corridor);
    }
  }
  const pad = Math.max((tHi - tLo) * 0.06, Math.abs(close) * 0.004, 8);
  const bandTop = tHi + pad;
  const bandBot = tLo - pad;

  const polished = overlays
    .filter((o) => !SWING_FUSION_ZONE_IDS.has(String(o.id || '')))
    .map((raw) => {
      const id = String(raw.id || '');
      const extra = String(raw.overlayZoneExtraClass || '');
      const kind = String(raw.kind || '');

      if (id.startsWith('merged-swing-regime-')) {
        return {
          ...raw,
          label: '',
          price1: bandTop,
          price2: bandBot,
          color: extra.includes('short')
            ? 'rgba(239,68,68,0.03)'
            : 'rgba(34,197,94,0.03)',
          overlayZoneExtraClass: `${extra} merged-desk-regime-compact`.trim(),
        };
      }

      /** 보조 Mirage 면 — 연한 fill, 캡션 숨김 (캔들 가독) */
      if (isSecondaryMirageFace(id, extra)) {
        const soft = softenRgba(raw.color, 0.08) ?? raw.color;
        return {
          ...raw,
          label: '',
          color: soft,
          zoneFillPreserve: true,
          overlayZoneExtraClass: `${extra} merged-desk-zone-face-minimal merged-desk-zone-pro-soft`.trim(),
        };
      }

      if (
        extra.includes('merged-desk-core-sr') ||
        extra.includes('merged-desk-hotzone-entry') ||
        extra.includes('merged-desk-hotzone-rail') ||
        id.startsWith('merged-desk-hotzone-rail-')
      ) {
        return raw;
      }

      if (extra.includes('merged-ares-critical-zone') || extra.includes('merged-ares-key-zone')) {
        const soft = softenRgba(raw.color, 0.1) ?? raw.color;
        return {
          ...raw,
          color: soft,
          overlayZoneExtraClass: `${extra} merged-desk-zone-face-restored merged-desk-zone-pro-soft`.trim(),
        };
      }

      if (
        (id.startsWith('pulse-pro-') || id.startsWith('atlas-pulse-')) &&
        (kind === 'zone' || kind === 'biasBand')
      ) {
        return {
          ...raw,
          label: '',
          overlayZoneExtraClass: `${extra} merged-desk-zone-face-minimal merged-desk-zone-pro-soft`.trim(),
        };
      }

      if (id.startsWith('month-desk-strike-') && id.includes('zone')) {
        return {
          ...raw,
          overlayZoneExtraClass: `${extra} merged-desk-strike-zone-compact`.trim(),
        };
      }

      if (id.startsWith('merged-swing-fusion-') && kind === 'keyLevel') {
        return {
          ...raw,
          lineStrokeWidth: Math.max(2, Number(raw.lineStrokeWidth) || 2),
          overlayZoneExtraClass: `${extra} merged-desk-swing-level-line`.trim(),
          labelBackgroundColor: 'rgba(15,23,42,0.94)',
          labelTextColor: '#f8fafc',
        };
      }

      if (id.startsWith('merged-ares-line-') || id.startsWith('merged-desk-trade-rail-')) {
        return {
          ...raw,
          lineStrokeWidth: Math.max(2, Number(raw.lineStrokeWidth) || 2),
          overlayZoneExtraClass: `${extra} merged-desk-trade-rail-prominent`.trim(),
        };
      }

      return raw;
    });

  return applyMergedDeskZoneChartLabelClean(polished);
}

/* HotZone / HQ — 전문 작도: 네온·알약 과다 금지, 얇은 면 + 우측 짧은 캡션 */
.chart-wrap--merged-analysis .overlay-zone.merged-desk-hotzone-entry,
.chart-wrap--merged-analysis .overlay-zone.merged-desk-pill-zone,
.chart-wrap--merged-analysis .overlay-zone.merged-hq-entry-zone{
  border:1.5px solid rgba(148,163,184,0.45)!important;
  box-shadow:none!important;
  z-index:5!important;
  border-radius:4px!important;
