.chart-wrap--merged-analysis .overlay-zone.merged-desk-pill-zone.overlay-zone--hotzone-signal--long,
.chart-wrap--merged-analysis .overlay-zone.merged-hq-entry-zone.overlay-zone--hotzone-signal--long{
  border-color:rgba(74,222,128,0.55)!important;
  background:rgba(34,197,94,0.12)!important;
  box-shadow:none!important;
