input.contents:
/**
 * 통합·분석 차트 — zone 면·라벨 정리 (15m 공유 분석, 전 TF 동일).
 * 핵심 $$ 돈구간(HQ·HotZone·핵심지지)만 보이게 — 나머지는 면·라벨 숨김(삭제 아님).
 */
import type { Candle, OverlayItem } from '@/types';
import type { MergedTradeSignal } from '@/lib/mergedAnalysisTradeLayer';
import { mergedDeskLastCandleZoneBars } from '@/lib/mergedAnalysisOverlayTimes';
import { applyMergedDeskZoneChartLabelClean } from '@/lib/mergedDeskZoneChartLabelClean';

const SWING_FUSION_ZONE_IDS = new Set([
  'merged-swing-fusion-risk',
  'merged-swing-fusion-reward-tp1',
  'merged-swing-fusion-reward-ext',
  'merged-swing-fusion-entry-pocket',
]);

const ZONE_KINDS = new Set([
  'zone',
  'box',
  'supplyZone',
  'demandZone',
  'fvg',
  'ob',
  'reactionZone',
  'bprZone',
]);

function isZoneFace(o: OverlayItem): boolean {
  return ZONE_KINDS.has(String(o.kind || '')) || !!o.channelBand;
}

/** HQ · HotZone($$) · 핵심지지 — 차트에 남길 돈구간 */
export function isMergedDeskMoneyZoneKeepFace(
  o: Pick<OverlayItem, 'id' | 'kind' | 'overlayZoneExtraClass' | 'label'>
): boolean {
  const id = String(o.id || '');
  const extra = String(o.overlayZoneExtraClass || '');
  if (id.startsWith('merged-desk-hq-') || extra.includes('merged-hq-entry-zone')) return true;
  if (id.startsWith('merged-desk-hotzone-') || extra.includes('merged-desk-hotzone-entry')) {
    if (extra.includes('merged-desk-hotzone-rail')) return false;
    return true;
  }
  /** 핵심 지지 1순위만 */
  if (
    (id.startsWith('merged-desk-core-sr-sup') || extra.includes('merged-desk-core-sr--support')) &&
    (extra.includes('--primary') || extra.includes('--near') || id.includes('-1-'))
  ) {
    return true;
  }
  return false;
}

function hideZoneFaceCompletely(raw: OverlayItem): OverlayItem {
  const tip = String(raw.labelTooltip || raw.label || raw.zoneFaceBase || '');
  const extra = String(raw.overlayZoneExtraClass || '');
  return {
    ...raw,
    label: '',
    zoneFaceBase: undefined,
    zoneFaceSignal: undefined,
    color: 'rgba(0,0,0,0)',
    zoneFillPreserve: true,
    labelTooltip: tip,
    overlayZoneExtraClass: `${extra
      .replace(/\bmerged-desk-zone-caption-clean\b/g, '')
      .replace(/\bmerged-desk-zone-pro-hero\b/g, '')
      .replace(/\bmerged-desk-pill-zone\b/g, '')
      .trim()} merged-desk-zone-face-minimal merged-desk-zone-face-hidden`.trim(),
  };
}

function moneyZoneCaption(raw: OverlayItem): string {
  const id = String(raw.id || '');
  const extra = String(raw.overlayZoneExtraClass || '');
  const prev = String(raw.label || raw.zoneFaceBase || '');
  if (id.startsWith('merged-desk-hq-') || extra.includes('merged-hq-entry-zone')) {
    const grade = /grade-([AB])|[- ]([AB])\b/i.exec(`${extra} ${prev}`)?.[1] || /[AB]/.exec(prev)?.[0] || 'A';
    if (extra.includes('merged-hq-long') || raw.kind === 'demandZone' || /롱|long/i.test(prev)) {
      return `★롱 ${grade}`;
    }
    return `★숏 ${grade}`;
  }
  if (id.includes('hotzone-below') || extra.includes('hotzone-signal--long') || raw.kind === 'demandZone') {
    return prev.includes('★') ? '★$$지지' : '$$지지';
  }
  if (id.includes('hotzone-above') || extra.includes('hotzone-signal--short') || raw.kind === 'supplyZone') {
    return prev.includes('★') ? '★$$저항' : '$$저항';
  }
  if (extra.includes('core-sr--support') || id.includes('core-sr-sup')) return '$$지지';
  return prev || '$$';
}

/** 스윙 fusion 면 제거 · 돈구간만 표시 · 라벨 정리 */
export function polishMergedDeskChartOverlays(
  overlays: OverlayItem[],
  candles: Candle[],
  timeframe: string,
  trade?: MergedTradeSignal | null
): OverlayItem[] {
  if (!overlays.length || candles.length < 2) return overlays;

  const close = Number(candles[candles.length - 1]?.close);
  const width = mergedDeskLastCandleZoneBars(timeframe);
  const tail = candles.slice(-Math.min(width + 12, candles.length));
  let tLo = Infinity;
  let tHi = -Infinity;
  for (const c of tail) {
    tLo = Math.min(tLo, c.low);
    tHi = Math.max(tHi, c.high);
  }
  if (Number.isFinite(close) && close > 0) {
    const corridor = trade
      ? [trade.entry, trade.stopLoss, trade.tp1, trade.tp2, trade.tp3, close].filter(
          (p) => Number.isFinite(p) && p > 0
        )
      : [close];
    if (corridor.length) {
      tLo = Math.min(tLo, ...corridor);
      tHi = Math.max(tHi, ...corridor);
    }
  }
  const pad = Math.max((tHi - tLo) * 0.06, Math.abs(close) * 0.004, 8);
  const bandTop = tHi + pad;
  const bandBot = tLo - pad;

  let keptDemand = 0;
  let keptSupply = 0;

  const polished = overlays
    .filter((o) => !SWING_FUSION_ZONE_IDS.has(String(o.id || '')))
    .map((raw) => {
      const id = String(raw.id || '');
      const extra = String(raw.overlayZoneExtraClass || '');
      const kind = String(raw.kind || '');

      if (id.startsWith('merged-swing-regime-')) {
        return {
          ...raw,
          label: '',
          price1: bandTop,
          price2: bandBot,
          color: 'rgba(0,0,0,0)',
          overlayZoneExtraClass: `${extra} merged-desk-regime-compact merged-desk-zone-face-hidden`.trim(),
        };
      }

      /** 채널 밴드 면 숨김 · 상단저항/하단지지 라벨 제거(선만) */
      if (id.startsWith('merged-swing-channel') || extra.includes('merged-swing-channel')) {
        if (kind === 'channelBand' || isZoneFace(raw)) {
          return hideZoneFaceCompletely(raw);
        }
        return {
          ...raw,
          label: '',
          labelTooltip: String(raw.labelTooltip || raw.label || ''),
        };
      }

      /** 비-zone 구조 핀·BOS 라벨 숨김 */
      if (kind === 'bos' || kind === 'choch' || kind === 'label' || id.endsWith('-pin')) {
        return {
          ...raw,
          label: '',
          zoneFaceBase: undefined,
          overlayZoneExtraClass: `${extra} merged-desk-zone-face-minimal`.trim(),
        };
      }

      if (!isZoneFace(raw)) {
        if (id.startsWith('merged-ares-line-') || id.startsWith('merged-desk-trade-rail-')) {
          return {
            ...raw,
            lineStrokeWidth: Math.max(2, Number(raw.lineStrokeWidth) || 2),
            overlayZoneExtraClass: `${extra} merged-desk-trade-rail-prominent`.trim(),
          };
        }
        return raw;
      }

      /** 핵심 $$ 돈구간만 유지 */
      if (!isMergedDeskMoneyZoneKeepFace(raw)) {
        return hideZoneFaceCompletely(raw);
      }

      const isDemand =
        raw.kind === 'demandZone' ||
        id.includes('hotzone-below') ||
        id.includes('hq-long') ||
        extra.includes('hotzone-signal--long') ||
        extra.includes('merged-hq-long') ||
        extra.includes('core-sr--support');

      if (isDemand) {
        keptDemand += 1;
        if (keptDemand > 2) return hideZoneFaceCompletely(raw);
      } else {
        keptSupply += 1;
        if (keptSupply > 2) return hideZoneFaceCompletely(raw);
      }

      const cap = moneyZoneCaption(raw);
      return {
        ...raw,
        label: cap,
        zoneFaceBase: cap,
        zoneFaceSignal: undefined,
        labelTooltip: String(raw.labelTooltip || cap),
        overlayZoneExtraClass: `${extra
          .replace(/\bmerged-desk-zone-face-minimal\b/g, '')
          .replace(/\bmerged-desk-zone-face-hidden\b/g, '')
          .replace(/\bmerged-desk-zone-pro-soft\b/g, '')
          .trim()} merged-desk-zone-caption-clean merged-desk-zone-pro-hero merged-desk-money-zone-keep`.trim(),
      };
    });

  return applyMergedDeskZoneChartLabelClean(polished);
}

