export function resolveMergedDeskVisibleBars(
  timeframe: string,
  seriesBarCount: number
): number {
  const n = Math.max(1, seriesBarCount);
  if (!isMergedDeskChartTimeframe(timeframe)) {
    return Math.min(visibleLimit(timeframe), n);
  }
  const tf = normalizeChartTimeframe(timeframe);
  /** 1d/1w/1M — 4h에서 저장한 96봉을 그대로 쓰면 일봉은 3개월만 보여 2017 전량이 안 보임 */
  const htfDefault =
    tf === '1M' ? 120 : tf === '1w' ? 160 : tf === '1d' ? 220 : null;
  const shared = readMergedDeskSharedChartView();
  if (htfDefault != null) {
    const sharedBars = shared?.visibleBars;
    /** HTF는 공유값이 너무 작으면(분·시봉 줌) TF 기본으로 보정 */
    if (sharedBars && sharedBars >= Math.min(htfDefault, 48)) {
      return Math.min(Math.max(sharedBars, htfDefault), n);
    }
    return Math.min(htfDefault, n);
  }
  if (shared?.visibleBars) {
    return Math.min(shared.visibleBars, n);
  }
  return Math.min(MERGED_DESK_DEFAULT_VISIBLE_BARS, n);
}

