 * **최근 가시 구간만** 메움 — 전 구간 fill은 TF 전환 시 메인스레드를 막음.
 */
function fillMissingChartCandleSlots(rows: Candle[], stepSec: number, maxFill = 2_500): Candle[] {
  if (rows.length < 2 || stepSec <= 0) return rows;
  const tailStart = Math.max(1, rows.length - 520);
  if (tailStart > 1) {
    const head = rows.slice(0, tailStart);
    const tail = fillMissingChartCandleSlots(rows.slice(tailStart - 1), stepSec, maxFill);
    return head.slice(0, -1).concat(tail);
  }
  const out: Candle[] = [rows[0]!];
  let filled = 0;
  for (let i = 1; i < rows.length; i++) {
    const prev = out[out.length - 1]!;
    const curr = rows[i]!;
    const prevT = Number(prev.time);
    const currT = Number(curr.time);
    if (!(currT > prevT)) {
      out.push(curr);
      continue;
    }
    const gap = currT - prevT;
    if (gap > stepSec * 1.35 && filled < maxFill) {
      let t = prevT + stepSec;
      const px = Number(prev.close);
      /** 한 갭당 과도한 평봉 방지 (전환 가속) */
      let gapFill = 0;
      const gapCap = 80;
      while (t < currT - stepSec * 0.35 && filled < maxFill && gapFill < gapCap) {
        out.push({
          time: t,
          open: px,
          high: px,
          low: px,
          close: px,
          volume: 0,
        });
        t += stepSec;
        filled += 1;
        gapFill += 1;
      }
    }
    out.push(curr);
  }
  return out;
}

