function axisPriceLinePriority(title: string): number {
  const t = String(title || '');
  if (/진입E|손절SL|익절TP[123]|무효/.test(t)) return 10_000 + t.length;
  if (/하방지지|상방저항|\$\$\$\$|돈구간/.test(t)) return 500 + t.length;
