export function buildMergedDeskStructureRocketsForChart(params: {
  structureRockets: ReadonlyArray<{ time?: number; direction?: 'LONG' | 'SHORT' }>;
  chartCandles: Candle[];
  sourceCandles?: Candle[];
  chartBias?: 'LONG' | 'SHORT' | null;
}): MergedDeskRocketRow[] {
