/**
 * 차트 선택 TF(분·시·일·주·월) 캔들로 구조 로켓 생성.
 * 공유 15m analyze 로켓만 있으면 일·주·월에서 한 봉에 뭉개지거나 사라짐.
 */
export function buildMergedDeskChartTfStructureRockets(
  chartCandles: Candle[],
  timeframe: string
): MergedDeskRocketRow[] {
  const tf = normalizeChartTimeframe(timeframe);
  const series = mergedInstitutionalBandCandlesSlice(chartCandles, tf);
  if (series.length < 12) return [];
  const { L } = mergedDesk4hReferencePivotWindowForTf(tf);
  const maxMarks = Math.max(10, structureRocketMergeMax(tf));
  const marks = structureMarksFu(series, L, maxMarks);
  const n = series.length;
  const out: MergedDeskRocketRow[] = [];
  for (const mk of marks) {
    const phase = resolveStructureMarkPhase(mk, series, n);
    if (phase === 'failed') continue;
    const t = Number(series[mk.index]?.time);
    if (!Number.isFinite(t)) continue;
    out.push({
      time: t,
      direction: mk.bias === 'bullish' ? 'LONG' : 'SHORT',
      tier: 'structure',
    });
  }
  return filterMergedDeskSignalsToChartWindow(out, chartCandles);
}

/** 통합·분석 차트 로켓 — 15m analyze 스냅 + **차트 TF 구조** (일·주·월 포함 공동) */
