/** TF별 봉 주기(초) - 거래소 정렬 기준 근사 */
const TF_PERIOD_SEC: Record<string, number> = {
  '1m': 60,
  '3m': 180,
  '5m': 300,
  '15m': 15 * 60,
  '1h': 3600,
  '4h': 4 * 3600,
  '1d': 86400,
  '1w': 7 * 86400,
  '1M': 30 * 86400,
  '1Y': 365 * 86400,
};

/** Bitget 선물 일·주·월 시가 오프셋 (UTC 16:00) */
const BITGET_HTF_OPEN_OFFSET_SEC = 16 * 3600;

export function timeframePeriodSec(tf: string): number {
  return TF_PERIOD_SEC[tf] ?? 3600;
}

function getNextWeeklyCloseTime(nowSec: number): number {
  // Binance 주봉 경계: 월요일 00:00 UTC (KST 월 09:00)
  const d = new Date(nowSec * 1000);
  const day = d.getUTCDay(); // 0=Sun,1=Mon
  const daysFromMonday = (day + 6) % 7;
  const weekStartMs = Date.UTC(
    d.getUTCFullYear(),
    d.getUTCMonth(),
    d.getUTCDate() - daysFromMonday,
    0, 0, 0, 0
  );
  const nextWeekStartSec = Math.floor(weekStartMs / 1000) + 7 * 86400;
  return nextWeekStartSec > nowSec ? nextWeekStartSec : nextWeekStartSec + 7 * 86400;
}

function getNextMonthlyCloseTime(nowSec: number): number {
  // Binance 월봉 경계: 매월 1일 00:00 UTC
  const d = new Date(nowSec * 1000);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  const nextMonthStart = Date.UTC(y, m + 1, 1, 0, 0, 0, 0);
  return Math.floor(nextMonthStart / 1000);
}

function getNextYearlyCloseTime(nowSec: number): number {
  const d = new Date(nowSec * 1000);
  const y = d.getUTCFullYear();
  const nextYearStart = Date.UTC(y + 1, 0, 1, 0, 0, 0, 0);
  return Math.floor(nextYearStart / 1000);
}

/** Bitget 일봉: UTC 16:00 마감 */
function getNextBitgetDailyCloseTime(nowSec: number): number {
  const aligned = nowSec - BITGET_HTF_OPEN_OFFSET_SEC;
  const dayIdx = Math.floor(aligned / 86400);
  let close = dayIdx * 86400 + BITGET_HTF_OPEN_OFFSET_SEC + 86400;
  if (close <= nowSec) close += 86400;
  return close;
}

/** Bitget 주봉: 월요일 UTC 16:00 마감 */
function getNextBitgetWeeklyCloseTime(nowSec: number): number {
  const d = new Date(nowSec * 1000);
  const day = d.getUTCDay();
  const daysFromMonday = (day + 6) % 7;
  const weekOpenMs = Date.UTC(
    d.getUTCFullYear(),
    d.getUTCMonth(),
    d.getUTCDate() - daysFromMonday,
    16, 0, 0, 0
  );
  let closeSec = Math.floor(weekOpenMs / 1000) + 7 * 86400;
  if (closeSec <= nowSec) closeSec += 7 * 86400;
  // 월요일이지만 아직 16:00 전이면 이번 주 월 16:00이 마감(직전 주봉)
  const thisWeekOpenSec = Math.floor(weekOpenMs / 1000);
  if (nowSec < thisWeekOpenSec) return thisWeekOpenSec;
  return closeSec;
}

/** Bitget 월봉: 매월 1일 UTC 16:00 마감 */
function getNextBitgetMonthlyCloseTime(nowSec: number): number {
  const d = new Date(nowSec * 1000);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  let closeSec = Math.floor(Date.UTC(y, m + 1, 1, 16, 0, 0, 0) / 1000);
  const thisMonthOpen = Math.floor(Date.UTC(y, m, 1, 16, 0, 0, 0) / 1000);
  if (nowSec < thisMonthOpen) return thisMonthOpen;
  if (closeSec <= nowSec) {
    closeSec = Math.floor(Date.UTC(y, m + 2, 1, 16, 0, 0, 0) / 1000);
  }
  return closeSec;
}

/**
 * 기준 시각(초 단위 UTC) 기준으로 각 TF별 다음 봉 마감 시각 계산.
 * - 분/시간: period 기반
 * - 일: Bitget UTC 16:00 (차트 소스)
 * - 주/월: Bitget 월요일·1일 UTC 16:00
 * - 년: 1월 1일 00:00 UTC
 */
export function nextCandleCloseUnixSec(nowSec: number, tf: string): number {
  if (tf === '1d') return getNextBitgetDailyCloseTime(nowSec);
  if (tf === '1w') return getNextBitgetWeeklyCloseTime(nowSec);
  if (tf === '1M') return getNextBitgetMonthlyCloseTime(nowSec);
  if (tf === '1Y') return getNextYearlyCloseTime(nowSec);
  const periodSec = timeframePeriodSec(tf);
  const currentOpen = Math.floor(nowSec / periodSec) * periodSec;
  const nextClose = currentOpen + periodSec;
  return nextClose > nowSec ? nextClose : nextClose + periodSec;
}

export function candleCloseRemainSec(nowSec: number, tf: string): number {
  return Math.max(0, Math.floor(nextCandleCloseUnixSec(nowSec, tf) - nowSec));
}

/** UI용: 3:42 · 1:12:05 · 2d 5h */
export function formatCandleCloseRemain(remainSec: number): string {
  const s = Math.max(0, Math.floor(remainSec));
  if (s < 3600) {
    const m = Math.floor(s / 60);
    const r = s % 60;
    return `${m}:${String(r).padStart(2, '0')}`;
  }
  if (s < 86400) {
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const r = s % 60;
    return `${h}:${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
  }
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  return `${d}d ${h}h`;
}

/**
 * 종가마감 보드용(기존): 주·월은 Binance UTC 00:00, 일은 period 정렬.
 * TF 칩 카운트다운은 `nextCandleCloseUnixSec`(Bitget HTF) 사용.
 */
function getNextCloseTime(nowSec: number, tf: string, periodSec: number): number {
  if (tf === '1w') return getNextWeeklyCloseTime(nowSec);
  if (tf === '1M') return getNextMonthlyCloseTime(nowSec);
  if (tf === '1Y') return getNextYearlyCloseTime(nowSec);
  const currentOpen = Math.floor(nowSec / periodSec) * periodSec;
  const nextClose = currentOpen + periodSec;
  return nextClose > nowSec ? nextClose : nextClose + periodSec;
}

