 * onPartial: recent 즉시 · onUpgrade: full/백그라운드 갱신.
 * maxAgeMs: 실시간 폴링용 — 캐시가 이보다 오래되면 네트워크 재조회(TTL 무시).
 */
export async function fetchClientMarketCandles(opts: {
  symbol: string;
  timeframe: string;
  source?: ClientMarketSource;
  signal?: AbortSignal;
  onPartial?: (candles: Candle[]) => void;
  /** full·SWR 갱신 완료 시 (차트 idle 적용용) */
  onUpgrade?: (candles: Candle[]) => void;
  /** 실시간 폴링: 캐시 age가 이 값(ms) 초과면 강제 fetch */
  maxAgeMs?: number;
}): Promise<Candle[]> {
  const source = opts.source ?? 'binance';
  const tf = normalizeChartTimeframe(opts.timeframe) || opts.timeframe;
  const key = clientMarketCacheKey(opts.symbol, tf, source);
  const htf = isListingFullHistoryTf(tf);
  const removePartial = addPartialWaiter(key, { onPartial: opts.onPartial });
  const liveMaxAge = typeof opts.maxAgeMs === 'number' && opts.maxAgeMs >= 0 ? opts.maxAgeMs : null;

  try {
    const hit = dataCache.get(key);

    /** 실시간 폴링 — 신선하면 캐시, 아니면 아래로 내려가 네트워크 */
    if (liveMaxAge != null && hit?.candles.length) {
      if (Date.now() - hit.fetchedAt <= liveMaxAge) {
        return hit.candles;
      }
      /* fall through: force network */
    } else if (hit?.candles.length) {
      const fresh = Date.now() - hit.fetchedAt <= entryTtlMs(tf, hit.depth);

      if (hit.depth === 'full') {
        if (!fresh) {
          addUpgradeListener(key, opts.onUpgrade);
          scheduleBackgroundRefresh(opts.symbol, tf, source, htf, key);
        }
        return hit.candles;
      }

      if (!htf) {
        if (!fresh) {
          addUpgradeListener(key, opts.onUpgrade);
          scheduleBackgroundRefresh(opts.symbol, tf, source, false, key);
        }
        return hit.candles;
      }

      /** HTF recent만 있음 → 즉시 반환, full은 백그라운드 (전환 대기 제거) */
      opts.onPartial?.(hit.candles);
      addUpgradeListener(key, opts.onUpgrade);
      scheduleHtfFullUpgrade(opts.symbol, tf, source, key);
      return hit.candles;
    }

async function loadCandles(live = false) {
  try {
    const applySeries = (raw: Candle[], fitIfNeeded: boolean, bumpOverlay = true) => {
      if (cancelled || ac.signal.aborted) return;
      const nextCandles = sanitizeFast(raw);
      setMarketError('');
      setCandles(nextCandles);
      if (fitIfNeeded) {
        const key = `${symbol}|${timeframe}`;
        if (lastFittedRef.current !== key) {
          lastFittedRef.current = key;
          const c = chartRef.current;
          const ser = seriesRef.current;
          if (c && ser) {
            lastMarketFitContextRef.current = { symbol, timeframe };
            applyFocusLatestBars(c, ser, nextCandles.length, timeframe);
          }
        }
      }
      setLastUpdate(new Date().toLocaleTimeString('ko-KR', { hour12: false }));
      if (bumpOverlay) setOverlayTick((v) => v + 1);
    };

    const scheduleUpgrade = (full: Candle[]) => {
      if (cancelled || ac.signal.aborted) return;
      if (full.length <= startedWithCacheLen && startedWithCacheLen > 0) return;
      const applyFull = () => {
        if (cancelled || ac.signal.aborted) return;
        applySeries(full, false, false);
      };
      if (typeof window !== 'undefined' && 'requestIdleCallback' in window) {
        fullIdleIsRic = true;
        fullIdleId = window.requestIdleCallback(applyFull, { timeout: 600 });
      } else {
        fullIdleIsRic = false;
        fullIdleId = window.setTimeout(applyFull, 64) as unknown as number;
      }
    };

    let partialLen = 0;
    const raw = await fetchClientMarketCandles({
      symbol,
      timeframe,
      source,
      signal: ac.signal,
      /** Bitget 등 WS 없는 모드 — 폴링이 5분 캐시에 막히지 않게 */
      maxAgeMs: live ? 2_000 : undefined,
      onPartial: (partial) => {
        partialLen = partial.length;
        applySeries(partial, true, startedWithCacheLen === 0);
      },
      onUpgrade: scheduleUpgrade,
    });
    if (cancelled || ac.signal.aborted) return;
    /** 초기 캐시 히트 최적화만 — 실시간 폴링은 마지막 봉 OHLC 갱신 필수 */
    if (
      !live &&
      startedWithCacheLen > 0 &&
      raw.length === startedWithCacheLen &&
      partialLen === 0
    ) {
      return;
    }
    if (partialLen > 0 && raw.length <= partialLen) {
      /* recent만 반환됨 · full은 onUpgrade */
      return;
    }
    if (partialLen > 0 && raw.length > partialLen) {
      scheduleUpgrade(raw);
      return;
    }
    applySeries(raw, !live, startedWithCacheLen === 0 || live);
  } catch (e: any) {
    if (e?.name === 'AbortError') return;
    if (!cancelled) setMarketError(e?.message || 'market error');
  }
}

