          }
          return next;
        }
        if (norm.time > last.time) {
          const next = prev.concat(
            bitgetVolumePackOn
              ? {
                  time: norm.time,
                  open: norm.open,
                  high: norm.high,
                  low: norm.low,
                  close: norm.close,
                  volume: last.volume > 0 ? 0 : norm.volume,
                }
              : norm
          );
