/** Bitget 일봉: UTC 16:00 마감 (거래소 참고) */
function getNextBitgetDailyCloseTime(nowSec: number): number {
  const aligned = nowSec - BITGET_HTF_OPEN_OFFSET_SEC;
  const dayIdx = Math.floor(aligned / 86400);
  let close = dayIdx * 86400 + BITGET_HTF_OPEN_OFFSET_SEC + 86400;
  if (close <= nowSec) close += 86400;
  return close;
}

function getNextBitgetWeeklyCloseTime(nowSec: number): number {
  const d = new Date(nowSec * 1000);
  const day = d.getUTCDay();
  const daysFromMonday = (day + 6) % 7;
  const thisMondayOpen = Math.floor(
    Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() - daysFromMonday, 16, 0, 0, 0) / 1000
  );
  if (nowSec < thisMondayOpen) return thisMondayOpen;
  return thisMondayOpen + 7 * 86400;
}

/** Bitget 월봉: 매월 1일 UTC 16:00 마감 */
function getNextBitgetMonthlyCloseTime(nowSec: number): number {
  const d = new Date(nowSec * 1000);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  let closeSec = Math.floor(Date.UTC(y, m + 1, 1, 16, 0, 0, 0) / 1000);
  const thisMonthOpen = Math.floor(Date.UTC(y, m, 1, 16, 0, 0, 0) / 1000);
  if (nowSec < thisMonthOpen) return thisMonthOpen;
  if (closeSec <= nowSec) {
    closeSec = Math.floor(Date.UTC(y, m + 2, 1, 16, 0, 0, 0) / 1000);
  }
  return closeSec;
}

/** KST 달력 필드 (getUTC* = KST wall clock) */
function kstDateParts(nowSec: number) {
  const d = new Date((nowSec + KST_OFFSET_SEC) * 1000);
  return {
    y: d.getUTCFullYear(),
    m: d.getUTCMonth(),
    day: d.getUTCDate(),
    dow: d.getUTCDay(),
  };
}

/** KST y-m-d 00:00 → unix(UTC) */
function kstMidnightUnixSec(y: number, m: number, day: number): number {
  return Math.floor(Date.UTC(y, m, day, 0, 0, 0, 0) / 1000) - KST_OFFSET_SEC;
}

/** 분·시·4h: 한국시간 벽시계에 period 정렬 */
function nextKstPeriodCloseSec(nowSec: number, periodSec: number): number {
  const local = nowSec + KST_OFFSET_SEC;
  const openLocal = Math.floor(local / periodSec) * periodSec;
  const closeLocal = openLocal + periodSec;
  return closeLocal - KST_OFFSET_SEC;
}

function nextKstDailyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const todayOpen = kstMidnightUnixSec(p.y, p.m, p.day);
  if (nowSec < todayOpen) return todayOpen;
  return todayOpen + 86400;
}

function nextKstWeeklyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const daysFromMonday = (p.dow + 6) % 7;
  const thisMonOpen = kstMidnightUnixSec(p.y, p.m, p.day - daysFromMonday);
  if (nowSec < thisMonOpen) return thisMonOpen;
  return thisMonOpen + 7 * 86400;
}

function nextKstMonthlyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const thisOpen = kstMidnightUnixSec(p.y, p.m, 1);
  if (nowSec < thisOpen) return thisOpen;
  return kstMidnightUnixSec(p.y, p.m + 1, 1);
}

function nextKstYearlyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const thisOpen = kstMidnightUnixSec(p.y, 0, 1);
  if (nowSec < thisOpen) return thisOpen;
  return kstMidnightUnixSec(p.y + 1, 0, 1);
}

/**
 * TF 칩 봉 마감 — **한국시간(KST)** 벽시계 기준.
 * 분·시·4h / 일 00:00 / 주 월요일 00:00 / 월·년 1일 00:00 KST.
 */
export function nextCandleCloseUnixSec(nowSec: number, tf: string): number {
  if (tf === '1d') return nextKstDailyCloseSec(nowSec);
  if (tf === '1w') return nextKstWeeklyCloseSec(nowSec);
  if (tf === '1M') return nextKstMonthlyCloseSec(nowSec);
  if (tf === '1Y') return nextKstYearlyCloseSec(nowSec);
  return nextKstPeriodCloseSec(nowSec, timeframePeriodSec(tf));
}

export function candleCloseRemainSec(nowSec: number, tf: string): number {
  return Math.max(0, Math.floor(nextCandleCloseUnixSec(nowSec, tf) - nowSec));
}

/** UI용: 3:42 · 1:12:05 · 2d 5h */
export function formatCandleCloseRemain(remainSec: number): string {
  const s = Math.max(0, Math.floor(remainSec));
  if (s < 3600) {
    const m = Math.floor(s / 60);
    const r = s % 60;
    return `${m}:${String(r).padStart(2, '0')}`;
  }
  if (s < 86400) {
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const r = s % 60;
    return `${h}:${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
  }
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  return `${d}d ${h}h`;
}

/**
 * 종가마감 보드용(기존): 주·월은 Binance UTC 00:00, 일은 period 정렬.
 * TF 칩 카운트다운은 `nextCandleCloseUnixSec`(KST) 사용.
 */
function getNextCloseTime(nowSec: number, tf: string, periodSec: number): number {
  if (tf === '1w') return getNextWeeklyCloseTime(nowSec);
  if (tf === '1M') return getNextMonthlyCloseTime(nowSec);
  if (tf === '1Y') return getNextYearlyCloseTime(nowSec);
  const currentOpen = Math.floor(nowSec / periodSec) * periodSec;
  const nextClose = currentOpen + periodSec;
  return nextClose > nowSec ? nextClose : nextClose + periodSec;
}

