function getNextMonthlyCloseTime(nowSec: number): number {
  // Binance 월봉 경계: 매월 1일 00:00 UTC
  const d = new Date(nowSec * 1000);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  const nextMonthStart = Date.UTC(y, m + 1, 1, 0, 0, 0, 0);
  return Math.floor(nextMonthStart / 1000);
}

function getNextYearlyCloseTime(nowSec: number): number {
  const d = new Date(nowSec * 1000);
  const y = d.getUTCFullYear();
  const nextYearStart = Date.UTC(y + 1, 0, 1, 0, 0, 0, 0);
  return Math.floor(nextYearStart / 1000);
}

/** KST 달력 필드 (getUTC* = KST wall clock) */
function kstDateParts(nowSec: number) {
  const d = new Date((nowSec + KST_OFFSET_SEC) * 1000);
  return {
    y: d.getUTCFullYear(),
    m: d.getUTCMonth(),
    day: d.getUTCDate(),
    dow: d.getUTCDay(),
  };
}

/** KST y-m-d 00:00 → unix(UTC) */
function kstMidnightUnixSec(y: number, m: number, day: number): number {
  return Math.floor(Date.UTC(y, m, day, 0, 0, 0, 0) / 1000) - KST_OFFSET_SEC;
}

/** 분·시·4h: 한국시간 벽시계에 period 정렬 */
function nextKstPeriodCloseSec(nowSec: number, periodSec: number): number {
  const local = nowSec + KST_OFFSET_SEC;
  const openLocal = Math.floor(local / periodSec) * periodSec;
  const closeLocal = openLocal + periodSec;
  return closeLocal - KST_OFFSET_SEC;
}

function nextKstDailyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const todayOpen = kstMidnightUnixSec(p.y, p.m, p.day);
  if (nowSec < todayOpen) return todayOpen;
  return todayOpen + 86400;
}

function nextKstWeeklyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const daysFromMonday = (p.dow + 6) % 7;
  const thisMonOpen = kstMidnightUnixSec(p.y, p.m, p.day - daysFromMonday);
  if (nowSec < thisMonOpen) return thisMonOpen;
  return thisMonOpen + 7 * 86400;
}

function nextKstMonthlyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const thisOpen = kstMidnightUnixSec(p.y, p.m, 1);
  if (nowSec < thisOpen) return thisOpen;
  return kstMidnightUnixSec(p.y, p.m + 1, 1);
}

function nextKstYearlyCloseSec(nowSec: number): number {
  const p = kstDateParts(nowSec);
  const thisOpen = kstMidnightUnixSec(p.y, 0, 1);
  if (nowSec < thisOpen) return thisOpen;
  return kstMidnightUnixSec(p.y + 1, 0, 1);
}

