  const touch = st === 'TOUCH';

  const eColor = go
    ? long
      ? '#4ADE80'
      : '#F87171'
    : touch
      ? long
        ? 'rgba(74,222,128,0.85)'
        : 'rgba(248,113,113,0.85)'
      : long
        ? 'rgba(74,222,128,0.55)'
        : 'rgba(248,113,113,0.55)';
  const slColor = go ? '#F87171' : touch ? 'rgba(248,113,113,0.8)' : 'rgba(248,113,113,0.45)';
