  const invColor = go ? '#FACC15' : touch ? 'rgba(250,204,21,0.85)' : 'rgba(250,204,21,0.45)';

  const eWidth: 1 | 2 | 3 | 4 = go ? 3 : touch ? 2 : 1;
  const eStyle: 'solid' | 'dashed' | 'dotted' = go ? 'solid' : touch ? 'solid' : 'dashed';
