      lineWidth: eWidth,
      lineStyle: eStyle,
      axisLabel: true,
    },
    {
      price: precision.stopLoss,
      color: slColor,
      title: `${sideTag}$$$$손절`,
      lineWidth: go ? 2 : 1,
      lineStyle: otherStyle,
      axisLabel: true,
