/**
 * Hot존 위치 — 짧은 존 박스 대신 전폭 가격선(중·상·하).
 * MA식 지속 반영. 참고용 · 확정 매매 아님.
 */
export function buildMergedDeskHotZoneBandPriceLines(
  below: MergedDeskHotZoneEntry | null | undefined,
  above: MergedDeskHotZoneEntry | null | undefined
): AtlasPulsePriceLine[] {
  const out: AtlasPulsePriceLine[] = [];
  const pushBand = (z: MergedDeskHotZoneEntry, isLong: boolean) => {
    const tag = isLong ? '$$$$롱·Hot' : '$$$$숏·Hot';
    const midColor = isLong ? '#4ADE80' : '#F87171';
    const edgeColor = isLong ? 'rgba(74,222,128,0.5)' : 'rgba(248,113,113,0.5)';
    const st =
      z.status === 'ENTER' ? '진입' : z.status === 'TOUCH' ? '터치' : z.primary ? '주시' : '대';
    out.push({
      price: z.mid,
      color: midColor,
      title: `${tag}·${st}`,
      lineWidth: z.primary || z.status === 'ENTER' || z.status === 'TOUCH' ? 2 : 1,
      lineStyle: z.status === 'ENTER' ? 'solid' : 'dashed',
      axisLabel: true,
    });
    if (z.top > z.mid && Math.abs(z.top - z.mid) / z.mid > 0.00025) {
      out.push({
        price: z.top,
        color: edgeColor,
        title: `${tag}상`,
        lineWidth: 1,
        lineStyle: 'dotted',
        axisLabel: true,
      });
    }
    if (z.bot < z.mid && Math.abs(z.mid - z.bot) / z.mid > 0.00025) {
      out.push({
        price: z.bot,
        color: edgeColor,
        title: `${tag}하`,
        lineWidth: 1,
        lineStyle: 'dotted',
        axisLabel: true,
      });
    }
  };
  if (below) pushBand(below, true);
  if (above) pushBand(above, false);
  return out;
}

