      color: long ? 'rgba(34,197,94,0.22)' : 'rgba(239,68,68,0.22)',
      category: 'scenario',
      labelTooltip: `${sideTag} 진입 ${fmt(plan.entry)} · SL ${fmt(plan.stopLoss)} · TP1 ${fmt(plan.tp1)} · ${plan.sourceKo} · ${plan.statusKo}`,
