input.contents:
/**
 * 통합·분석 — 이미지형 파란/빨간 평행 추세 채널.
 * 스윙 고점 기울기 + 저점 폭으로 평행 복도 2본(단기·장기).
 * 참고용 · 확정 매매·승률 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import {
  collectSwingPivots,
  pickSwingPivotPair,
  type CandlePivot,
} from '@/lib/mergedDeskCandleTrendline';
import { mergedWorkCandles } from '@/lib/mergedAnalysisOverlayTimes';
import { sanitizeChartCandlesForSeries } from '@/lib/volumeHistogramIntelligence';
import { mergedDesk4hReferencePivotWindowForTf } from '@/lib/mergedDesk4hReference';

export type MergedDeskBlueRedChannelPack = {
  overlays: OverlayItem[];
  summaryKo: string;
};

function work(candles: Candle[], timeframe: string): Candle[] {
  return sanitizeChartCandlesForSeries(mergedWorkCandles(candles, timeframe), timeframe);
}

function pivotHigh(candles: Candle[], i: number, L: number, R: number): boolean {
  const h = candles[i]!.high;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || candles[j]!.high >= h) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= candles.length || candles[j]!.high > h) return false;
  }
  return true;
}

function pivotLow(candles: Candle[], i: number, L: number, R: number): boolean {
  const lo = candles[i]!.low;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || candles[j]!.low <= lo) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= candles.length || candles[j]!.low < lo) return false;
  }
  return true;
}

function collectPivotsInLookback(
  candles: Candle[],
  timeframe: string,
  lookback: number
): { highs: CandlePivot[]; lows: CandlePivot[] } {
  const { L, R } = mergedDesk4hReferencePivotWindowForTf(timeframe);
  const start = Math.max(L, candles.length - lookback);
  const highs: CandlePivot[] = [];
  const lows: CandlePivot[] = [];
  for (let i = start + L; i < candles.length - R; i++) {
    if (pivotHigh(candles, i, L, R)) {
      highs.push({ i, price: candles[i]!.high, time: Number(candles[i]!.time) });
    }
    if (pivotLow(candles, i, L, R)) {
      lows.push({ i, price: candles[i]!.low, time: Number(candles[i]!.time) });
    }
  }
  return { highs, lows };
}

function pickPair(pivots: CandlePivot[], minBars: number): [CandlePivot, CandlePivot] | null {
  if (pivots.length < 2) return null;
  const p2 = pivots[pivots.length - 1]!;
  for (let k = pivots.length - 2; k >= 0; k--) {
    const p1 = pivots[k]!;
    if (p2.i - p1.i >= minBars) return [p1, p2];
  }
  return [pivots[pivots.length - 2]!, p2];
}

function lineAt(p1: CandlePivot, p2: CandlePivot, idx: number): number {
  const slope = (p2.price - p1.price) / Math.max(1, p2.i - p1.i);
  return p1.price + slope * (idx - p1.i);
}

/**
 * 고점 2개로 기울기 잡고, 저점과의 거리로 폭을 정해 평행 채널.
 * 하락 → 빨강, 상승 → 파랑 (이미지 톤).
 */
function buildOneParallelChannel(params: {
  candles: Candle[];
  highs: CandlePivot[];
  lows: CandlePivot[];
  idPrefix: string;
  labelKo: string;
  minBars: number;
  /** 폭 분위(0~1). 높을수록 넓은 외곽 채널 */
  widthPct: number;
  forceBearFill?: boolean;
}): OverlayItem[] {
  const { candles, highs, lows, idPrefix, labelKo, minBars, widthPct } = params;
  const hiPair = pickPair(highs, minBars);
  const loPair = pickPair(lows, minBars);
  if (!hiPair || candles.length < 8) return [];

  const [h1, h2] = hiPair;
  const slope = (h2.price - h1.price) / Math.max(1, h2.i - h1.i);
  const descending = slope < 0;
  const iEnd = candles.length - 1;
  const tEnd = Number(candles[iEnd]!.time);

  const dists: number[] = [];
  for (const lo of lows) {
    if (lo.i < h1.i) continue;
    const up = lineAt(h1, h2, lo.i);
    const d = up - lo.price;
    if (d > 0) dists.push(d);
  }
  dists.sort((a, b) => a - b);
  let width =
    dists.length > 0
      ? dists[Math.min(dists.length - 1, Math.floor(dists.length * widthPct))]!
      : Math.abs(h2.price) * 0.02;
  if (!(width > 0)) {
    if (loPair) {
      width = Math.max(
        Math.abs(lineAt(h1, h2, loPair[0].i) - loPair[0].price),
        Math.abs(lineAt(h1, h2, loPair[1].i) - loPair[1].price),
        Math.abs(h2.price) * 0.012
      );
    } else {
      width = Math.abs(h2.price) * 0.018;
    }
  }

  const tStart = Math.min(h1.time, loPair?.[0]?.time ?? h1.time);
  const iStart = Math.min(h1.i, loPair?.[0]?.i ?? h1.i);
  const up1 = lineAt(h1, h2, iStart);
  const up2 = lineAt(h1, h2, iEnd);
  const lo1 = up1 - width;
  const lo2 = up2 - width;

  const useBear = params.forceBearFill != null ? params.forceBearFill : descending;
  const fill = useBear ? 'rgba(239,68,68,0.16)' : 'rgba(59,130,246,0.18)';
  const edgeUp = useBear ? 'rgba(248,113,113,0.85)' : 'rgba(96,165,250,0.9)';
  const edgeLo = useBear ? 'rgba(185,28,28,0.75)' : 'rgba(37,99,235,0.8)';
  const dirKo = descending ? '하락' : '상승';
  const tip = `${labelKo} · ${dirKo} 평행채널 · 스윙피벗(참고·비보장)`;

  const band: OverlayItem = {
    id: `${idPrefix}-band`,
    kind: 'channelBand',
    label: useBear ? `빨간 ${dirKo}채널` : `파란 ${dirKo}채널`,
    x1: 0,
    y1: 0.5,
    x2: 1,
    y2: 0.5,
    time1: tStart as UTCTimestamp,
    time2: tEnd as UTCTimestamp,
    price1: Math.max(up1, up2),
    price2: Math.min(lo1, lo2),
    confidence: 70,
    color: fill,
    category: 'chartPrimeTrendChannels',
    structureBias: descending ? 'bearish' : 'bullish',
    zoneFillPreserve: true,
    channelBand: {
      time1: tStart,
      time2: tEnd,
      priceHigh1: up1,
      priceHigh2: up2,
      priceLow1: lo1,
      priceLow2: lo2,
    },
    overlayZoneExtraClass:
      'merged-desk-rb-channel merged-swing-channel merged-desk-blue-red-channel',
    labelTooltip: tip,
    lineLabelColor: useBear ? '#fecaca' : '#bfdbfe',
  };

  const edge = (
    id: string,
    label: string,
    p1: number,
    p2: number,
    color: string
  ): OverlayItem => ({
    id,
    kind: 'trendLine',
    label,
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 1,
    time1: tStart as UTCTimestamp,
    price1: p1,
    time2: tEnd as UTCTimestamp,
    price2: p2,
    confidence: 72,
    color,
    category: 'chartPrimeTrendChannels',
    lineStrokeWidth: 2,
    lineDash: '5 4',
    noProject: true,
    overlayZoneExtraClass:
      'merged-desk-rb-channel merged-swing-channel merged-desk-blue-red-channel',
    labelTooltip: tip,
    lineLabelColor: '#e2e8f0',
  });

  return [
    band,
    edge(`${idPrefix}-upper`, `${labelKo}상`, up1, up2, edgeUp),
    edge(`${idPrefix}-lower`, `${labelKo}하`, lo1, lo2, edgeLo),
  ];
}

/**
 * 단기(빨간/파란) + 장기(보완색) 평행채널 2본.
 * 통합·분석 차트에 이미지형 대각 띠로 표시.
 */
export function buildMergedDeskBlueRedChannels(
  candles: Candle[],
  timeframe: string
): MergedDeskBlueRedChannelPack {
  const safe = work(candles, timeframe);
  if (safe.length < 24) {
    return { overlays: [], summaryKo: '파란·빨간 채널 — 봉 부족' };
  }

  const shortLb = Math.min(safe.length - 2, Math.max(36, Math.floor(safe.length * 0.28)));
  const longLb = Math.min(safe.length - 2, Math.max(72, Math.floor(safe.length * 0.55)));

  const short = collectPivotsInLookback(safe, timeframe, shortLb);
  const long = collectPivotsInLookback(safe, timeframe, longLb);

  /** 단기: 기울기 따라 빨강(하락)/파랑(상승) */
  const shortCh = buildOneParallelChannel({
    candles: safe,
    highs: short.highs,
    lows: short.lows,
    idPrefix: 'merged-desk-rb-short',
    labelKo: '단기채널',
    minBars: 5,
    widthPct: 0.55,
  });

  /** 장기: 보완색 — 단기와 같은 방향이면 반대 팔레트로 겹침(이미지의 파란+빨간 복도) */
  const shortSlope =
    short.highs.length >= 2
      ? (() => {
          const p = pickPair(short.highs, 5);
          if (!p) return 0;
          return (p[1].price - p[0].price) / Math.max(1, p[1].i - p[0].i);
        })()
      : 0;
  const longCh = buildOneParallelChannel({
    candles: safe,
    highs: long.highs,
    lows: long.lows,
    idPrefix: 'merged-desk-rb-long',
    labelKo: '장기채널',
    minBars: 8,
    widthPct: 0.72,
    /** 단기 하락이면 장기는 파랑 면, 단기 상승이면 장기는 빨강 면 */
    forceBearFill: !(shortSlope < 0),
  });

  const overlays = [...longCh, ...shortCh];
  if (!overlays.length) {
    /** 폴백 — 기존 피벗 채널 */
    const { highs, lows } = collectSwingPivots(candles, timeframe);
    const hi = pickSwingPivotPair(highs, timeframe);
    if (hi) {
      const fb = buildOneParallelChannel({
        candles: safe,
        highs,
        lows,
        idPrefix: 'merged-desk-rb-fb',
        labelKo: '스윙채널',
        minBars: 6,
        widthPct: 0.6,
      });
      return {
        overlays: fb,
        summaryKo: fb.length
          ? `파란·빨간 채널 ${fb.filter((o) => o.kind === 'channelBand').length}본(폴백)`
          : '파란·빨간 채널 — 피벗 부족',
      };
    }
    return { overlays: [], summaryKo: '파란·빨간 채널 — 피벗 부족' };
  }

  const nBand = overlays.filter((o) => o.kind === 'channelBand').length;
  return {
    overlays,
    summaryKo: `파란·빨간 평행채널 ${nBand}본 · 단기+장기(참고)`,
  };
}

