import { buildMergedDeskBlueRedChannels } from './lib/mergedDeskBlueRedChannels.ts';
import type { Candle } from './types';
const now = Math.floor(Date.now()/1000);
const candles: Candle[] = [];
let p = 65000;
for (let i=0;i<200;i++) {
  const t = now - (200-i)*3600;
  const drift = -8 + (i>140?4:0);
  p = p + drift + (Math.sin(i/7)*20);
  const o=p, c=p+drift, h=Math.max(o,c)+40, l=Math.min(o,c)-40;
  candles.push({time:t, open:o, high:h, low:l, close:c, volume:1000+i});
}
