input.contents:
/**
 * 통합·분석 — 파란/빨간 평행채널 → 돌파/돌파가능/지지가능 + 머니엣지.
 * 종가·ATR 기준 조건부 판별 · 확정 수익·승률 보장 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import type { AtlasPulsePriceLine } from '@/lib/monthDeskAtlasPulseDesk';
import {
  calcTradeRewardRisk,
  strengthenUnifiedDeskTradePlan,
} from '@/lib/mergedDeskUnifiedTradeRails';
import {
  buildMergedDeskBlueRedChannels,
  stampMergedDeskBlueRedMoneyCaptions,
  type MergedDeskChannelGeom,
  type MergedDeskChannelHorizon,
} from '@/lib/mergedDeskBlueRedChannels';

export type MergedDeskChannelMoneyStatus = 'WAIT' | 'TOUCH' | 'ENTER' | 'INVALID';

/** 상·하단 엣지 상태 — 차트 라벨·축선에 그대로 씀 */
export type MergedDeskChannelEdgeState =
  | '돌파'
  | '돌파가능'
  | '지지가능'
  | '저항가능'
  | '중가';

export type MergedDeskChannelEdgeRead = {
  geom: MergedDeskChannelGeom;
  upper: MergedDeskChannelEdgeState;
  lower: MergedDeskChannelEdgeState;
  /** 띠에 붙일 짧은 한글 */
  captionKo: string;
  pos: number;
};

export type MergedDeskChannelMoneyPlan = {
  direction: 'LONG' | 'SHORT';
  entry: number;
  stopLoss: number;
  tp1: number;
  tp2: number;
  tp3: number;
  invalidationPrice: number;
  invalidationKo: string;
  rr: number;
  status: MergedDeskChannelMoneyStatus;
  statusKo: string;
  entryAllowed: boolean;
  reasonsKo: string[];
  confluence: boolean;
  edge: 'lower' | 'upper';
  /** bounce | breakout */
  mode: 'bounce' | 'breakout';
  edgeStateKo: MergedDeskChannelEdgeState;
  horizonKo: string;
  sourceKo: string;
};

export type MergedDeskChannelMoneyEdgePack = {
  overlays: OverlayItem[];
  plan: MergedDeskChannelMoneyPlan | null;
  priceLines: AtlasPulsePriceLine[];
  summaryKo: string;
  geoms: MergedDeskChannelGeom[];
  edgeReads: MergedDeskChannelEdgeRead[];
};

function fmt(p: number): string {
  if (!(p > 0) || !Number.isFinite(p)) return '—';
  if (p >= 1000) return p.toFixed(0);
  if (p >= 1) return p.toFixed(1);
  return p.toFixed(3);
}

function atrApprox(candles: Candle[]): number {
  const n = candles.length;
  if (n < 5) {
    const c = Number(candles[n - 1]?.close) || 0;
    return c > 0 ? c * 0.008 : 0;
  }
  const start = Math.max(1, n - 14);
  let sum = 0;
  let cnt = 0;
  for (let i = start; i < n; i++) {
    const h = Number(candles[i]!.high);
    const l = Number(candles[i]!.low);
    const pc = Number(candles[i - 1]!.close);
    if (![h, l, pc].every(Number.isFinite)) continue;
    sum += Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
    cnt += 1;
  }
  if (cnt <= 0) {
    const c = Number(candles[n - 1]?.close) || 0;
    return c > 0 ? c * 0.008 : 0;
  }
  return sum / cnt;
}

function statusKoOf(s: MergedDeskChannelMoneyStatus): string {
  if (s === 'ENTER') return '진입';
  if (s === 'TOUCH') return '터치';
  if (s === 'INVALID') return '무효';
  return '대기';
}

function horizonKey(horizonKo: string): MergedDeskChannelHorizon {
  if (horizonKo === '장기') return 'long';
  if (horizonKo === '스윙') return 'fb';
  return 'short';
}

function tipPos(close: number, g: MergedDeskChannelGeom): number {
  if (!(g.width > 0)) return 0.5;
  return (close - g.tipLower) / g.width;
}

/**
 * 채널 상·하단: 돌파(이미) / 돌파가능 / 지지가능 / 저항가능 / 중가
 * — 종가 우선, 고·저는 근접·가능 판별에 사용.
 */
export function classifyMergedDeskChannelEdges(
  candles: Candle[],
  g: MergedDeskChannelGeom,
  atr: number
): MergedDeskChannelEdgeRead | null {
  const last = candles[candles.length - 1];
  if (!last) return null;
  const close = Number(last.close);
  const open = Number(last.open);
  const high = Number(last.high);
  const low = Number(last.low);
  if (![close, open, high, low].every((x) => Number.isFinite(x) && x > 0)) return null;
  if (!(g.width > 0) || !(g.tipUpper > g.tipLower)) return null;

  const buf = Math.max(atr * 0.12, g.width * 0.04);
  const pad = Math.max(atr * 0.2, g.width * 0.08);
  const pos = tipPos(close, g);
  const bull = close > open;
  const bear = close < open;

  /** 상단 */
  let upper: MergedDeskChannelEdgeState = '중가';
  if (close > g.tipUpper + buf) {
    upper = '돌파';
  } else if (
    high >= g.tipUpper - pad * 0.35 &&
    close <= g.tipUpper + buf &&
    (pos >= 0.82 || high >= g.tipUpper)
  ) {
    /** 종가는 안·경계 · 고가가 상단 위협 → 돌파가능 (이미 종가 돌파면 위에서 잡힘) */
    upper = close >= g.tipUpper - buf * 0.5 && bear ? '저항가능' : '돌파가능';
    if (bear && high >= g.tipUpper - pad * 0.2 && close < g.tipUpper) upper = '저항가능';
    if (!bear && (high >= g.tipUpper || pos >= 0.88)) upper = '돌파가능';
  } else if (pos >= 0.72 || high >= g.tipUpper - pad) {
    upper = bear && close < (high + low) / 2 ? '저항가능' : '돌파가능';
  }

  /** 하단 */
  let lower: MergedDeskChannelEdgeState = '중가';
  if (close < g.tipLower - buf) {
    lower = '돌파';
  } else if (
    low <= g.tipLower + pad * 0.35 &&
    close >= g.tipLower - buf &&
    (pos <= 0.22 || low <= g.tipLower)
  ) {
    if (bull && close > (high + low) / 2) lower = '지지가능';
    else if (bear && close <= g.tipLower + buf) lower = '돌파가능';
    else lower = '지지가능';
  } else if (pos <= 0.28 || low <= g.tipLower + pad) {
    lower = bull || close >= g.tipLower ? '지지가능' : '돌파가능';
  }

  /** 띠 캡션 우선순위: 돌파 > 지지가능 > 돌파가능 > 저항가능 */
  let captionKo = '중가';
  if (upper === '돌파') captionKo = '상돌파';
  else if (lower === '돌파') captionKo = '하돌파';
  else if (lower === '지지가능') captionKo = '지지가능';
  else if (upper === '돌파가능') captionKo = '상돌파가능';
  else if (lower === '돌파가능') captionKo = '하돌파가능';
  else if (upper === '저항가능') captionKo = '저항가능';
  else if (upper !== '중가' || lower !== '중가') {
    captionKo = lower !== '중가' ? lower : upper;
  }

  return { geom: g, upper, lower, captionKo, pos };
}

type EdgeCandidate = {
  direction: 'LONG' | 'SHORT';
  edge: 'lower' | 'upper';
  mode: 'bounce' | 'breakout';
  edgeStateKo: MergedDeskChannelEdgeState;
  geom: MergedDeskChannelGeom;
  near: boolean;
  reject: boolean;
  score: number;
  reasons: string[];
};

function scoreFromEdgeRead(
  candles: Candle[],
  read: MergedDeskChannelEdgeRead,
  atr: number
): EdgeCandidate[] {
  const g = read.geom;
  const last = candles[candles.length - 1]!;
  const close = Number(last.close);
  const open = Number(last.open);
  const high = Number(last.high);
  const low = Number(last.low);
  const pad = Math.max(atr * 0.15, g.width * 0.08);
  const out: EdgeCandidate[] = [];

  /** 하방 돌파(이미) → 숏 추종 후보 */
  if (read.lower === '돌파') {
    out.push({
      direction: 'SHORT',
      edge: 'lower',
      mode: 'breakout',
      edgeStateKo: '돌파',
      geom: g,
      near: true,
      reject: false,
      score: 58 + (g.horizon === 'short' ? 8 : 4) + (g.descending ? 6 : 0),
      reasons: [`${g.horizonKo}채널 하단·하돌파(종가)`, '돌파 추종(조건부·재테스트 확인)'],
    });
  }

  /** 상방 돌파(이미) → 롱 추종 후보 */
  if (read.upper === '돌파') {
    out.push({
      direction: 'LONG',
      edge: 'upper',
      mode: 'breakout',
      edgeStateKo: '돌파',
      geom: g,
      near: true,
      reject: false,
      score: 58 + (g.horizon === 'short' ? 8 : 4) + (!g.descending ? 6 : 0),
      reasons: [`${g.horizonKo}채널 상단·상돌파(종가)`, '돌파 추종(조건부·재테스트 확인)'],
    });
  }

  /** 지지가능 — 하단 바운스 롱 */
  if (read.lower === '지지가능') {
    const rejectLong =
      low <= g.tipLower + pad * 1.2 &&
      close > open &&
      close >= g.tipLower - atr * 0.05 &&
      close > (low + high) / 2;
    const bias = g.descending ? 0.9 : 1.15;
    out.push({
      direction: 'LONG',
      edge: 'lower',
      mode: 'bounce',
      edgeStateKo: '지지가능',
      geom: g,
      near: true,
      reject: rejectLong,
      score: (rejectLong ? 48 : 28) * bias + (1 - Math.min(1, Math.max(0, read.pos))) * 16,
      reasons: [
        `${g.horizonKo}채널 하단·지지가능`,
        rejectLong ? '거절봉(조건부)' : '하단 근접·지지 후보',
      ],
    });
  }

  /** 저항가능 — 상단 페이드 숏 */
  if (read.upper === '저항가능') {
    const rejectShort =
      high >= g.tipUpper - pad * 1.2 &&
      close < open &&
      close <= g.tipUpper + atr * 0.05 &&
      close < (low + high) / 2;
    const bias = g.descending ? 1.15 : 0.9;
    out.push({
      direction: 'SHORT',
      edge: 'upper',
      mode: 'bounce',
      edgeStateKo: '저항가능',
      geom: g,
      near: true,
      reject: rejectShort,
      score: (rejectShort ? 48 : 28) * bias + Math.min(1, Math.max(0, read.pos)) * 16,
      reasons: [
        `${g.horizonKo}채널 상단·저항가능`,
        rejectShort ? '거절봉(조건부)' : '상단 근접·저항 후보',
      ],
    });
  }

  /** 돌파가능 — 대기/터치만 (ENTER 금지에 가깝게 낮은 점수·WAIT) */
  if (read.upper === '돌파가능') {
    out.push({
      direction: 'LONG',
      edge: 'upper',
      mode: 'breakout',
      edgeStateKo: '돌파가능',
      geom: g,
      near: true,
      reject: false,
      score: 24 + (g.horizon === 'short' ? 4 : 2),
      reasons: [`${g.horizonKo}채널 상단·상돌파가능`, '종가 돌파·거래량 확인 전 대기'],
    });
  }
  if (read.lower === '돌파가능') {
    out.push({
      direction: 'SHORT',
      edge: 'lower',
      mode: 'breakout',
      edgeStateKo: '돌파가능',
      geom: g,
      near: true,
      reject: false,
      score: 24 + (g.horizon === 'short' ? 4 : 2),
      reasons: [`${g.horizonKo}채널 하단·하돌파가능`, '종가 이탈·확인 전 대기'],
    });
  }

  return out;
}

function buildPlanFromEdge(
  edge: EdgeCandidate,
  longGeom: MergedDeskChannelGeom | null,
  atr: number,
  close: number
): MergedDeskChannelMoneyPlan | null {
  const g = edge.geom;
  const w = g.width;
  const buf = Math.max(atr * 0.25, w * 0.06);

  let entry = close;
  let stopLoss = 0;
  let tp1 = 0;
  let tp2 = 0;
  let tp3 = 0;

  if (edge.mode === 'breakout' && edge.edgeStateKo === '돌파') {
    /** 돌파 추종 — 엣지 재테스트형 */
    if (edge.direction === 'LONG') {
      entry = Math.max(close, g.tipUpper);
      stopLoss = g.tipUpper - buf;
      tp1 = entry + w * 0.55;
      tp2 = entry + w * 0.95;
      tp3 = longGeom && longGeom.tipUpper > tp2 ? longGeom.tipUpper : entry + w * 1.4;
      if (!(stopLoss < entry && tp1 > entry)) return null;
    } else {
      entry = Math.min(close, g.tipLower);
      stopLoss = g.tipLower + buf;
      tp1 = entry - w * 0.55;
      tp2 = entry - w * 0.95;
      tp3 = longGeom && longGeom.tipLower < tp2 ? longGeom.tipLower : entry - w * 1.4;
      if (!(stopLoss > entry && tp1 < entry)) return null;
    }
  } else if (edge.mode === 'breakout' && edge.edgeStateKo === '돌파가능') {
    /** 돌파가능 — 대기 타점만 (엣지 밖 확인가) */
    if (edge.direction === 'LONG') {
      entry = g.tipUpper + buf * 0.35;
      stopLoss = g.tipUpper - buf;
      tp1 = entry + w * 0.5;
      tp2 = entry + w * 0.85;
      tp3 = entry + w * 1.25;
      if (!(stopLoss < entry && tp1 > entry)) return null;
    } else {
      entry = g.tipLower - buf * 0.35;
      stopLoss = g.tipLower + buf;
      tp1 = entry - w * 0.5;
      tp2 = entry - w * 0.85;
      tp3 = entry - w * 1.25;
      if (!(stopLoss > entry && tp1 < entry)) return null;
    }
  } else if (edge.direction === 'LONG') {
    entry = Math.max(close, Math.min(g.tipLower + buf * 0.35, g.tipMid));
    if (edge.reject) entry = Math.max(close, g.tipLower);
    stopLoss = g.tipLower - buf;
    tp1 = g.tipMid;
    tp2 = g.tipUpper;
    tp3 = longGeom && longGeom.tipUpper > tp2 ? longGeom.tipUpper : tp2 + w * 0.55;
    if (!(stopLoss < entry && tp1 > entry)) return null;
  } else {
    entry = Math.min(close, Math.max(g.tipUpper - buf * 0.35, g.tipMid));
    if (edge.reject) entry = Math.min(close, g.tipUpper);
    stopLoss = g.tipUpper + buf;
    tp1 = g.tipMid;
    tp2 = g.tipLower;
    tp3 = longGeom && longGeom.tipLower < tp2 ? longGeom.tipLower : tp2 - w * 0.55;
    if (!(stopLoss > entry && tp1 < entry)) return null;
  }

  const strengthened = strengthenUnifiedDeskTradePlan({
    direction: edge.direction,
    entry,
    stopLoss,
    tp1,
    tp2,
    tp3,
    invalidationKo: `종가 ${fmt(stopLoss)} 이탈 시 채널 무효`,
    sourceKo: '채널머니',
    alignedWithChart: true,
    warningsKo: [...edge.reasons, `${edge.edgeStateKo} · 확정 수익 아님`].slice(0, 5),
  });

  const rr =
    calcTradeRewardRisk(strengthened.entry, strengthened.stopLoss, strengthened.tp1) || 0;
  if (rr < 1.15) return null;

  const confluence =
    !!longGeom &&
    ((edge.direction === 'LONG' && !longGeom.descending) ||
      (edge.direction === 'SHORT' && longGeom.descending) ||
      (edge.direction === 'LONG' && tipPos(close, longGeom) <= 0.35) ||
      (edge.direction === 'SHORT' && tipPos(close, longGeom) >= 0.65));

  let status: MergedDeskChannelMoneyStatus = 'WAIT';
  if (edge.edgeStateKo === '돌파가능') {
    status = 'WAIT';
  } else if (edge.edgeStateKo === '돌파' && rr >= 1.35) {
    status = confluence || edge.score >= 60 ? 'ENTER' : 'TOUCH';
  } else if (edge.reject && rr >= 1.5 && (confluence || edge.score >= 48)) {
    status = 'ENTER';
  } else if (edge.near && (edge.edgeStateKo === '지지가능' || edge.edgeStateKo === '저항가능')) {
    status = rr >= 1.35 ? 'TOUCH' : 'WAIT';
  } else if (edge.near) {
    status = 'WAIT';
  } else {
    return null;
  }

  if (status === 'ENTER' && rr < 1.5 && edge.edgeStateKo !== '돌파') status = 'TOUCH';
  if (!confluence && status === 'ENTER' && edge.score < 55 && edge.edgeStateKo !== '돌파') {
    status = 'TOUCH';
  }

  const reasonsKo = [
    ...edge.reasons,
    confluence ? '단기·장기 채널 정렬' : '단기 엣지 단독(장기 확인 권장)',
    `상태=${edge.edgeStateKo} · RR≈${rr.toFixed(1)} · ${statusKoOf(status)}`,
  ];

  return {
    direction: strengthened.direction === 'NEUTRAL' ? edge.direction : strengthened.direction,
    entry: strengthened.entry,
    stopLoss: strengthened.stopLoss,
    tp1: strengthened.tp1,
    tp2: strengthened.tp2,
    tp3: strengthened.tp3,
    invalidationPrice: strengthened.stopLoss,
    invalidationKo: strengthened.invalidationKo,
    rr,
    status,
    statusKo: statusKoOf(status),
    entryAllowed: status === 'ENTER',
    reasonsKo,
    confluence,
    edge: edge.edge,
    mode: edge.mode,
    edgeStateKo: edge.edgeStateKo,
    horizonKo: g.horizonKo,
    sourceKo: '채널머니',
  };
}

function structurePriceLines(
  edgeReads: MergedDeskChannelEdgeRead[]
): AtlasPulsePriceLine[] {
  const short =
    edgeReads.find((r) => r.geom.horizon === 'short') ?? edgeReads[0];
  if (!short) return [];
  const g = short.geom;
  const upTitle =
    short.upper === '중가' ? `${g.horizonKo}채널상` : `${g.horizonKo}상·${short.upper}`;
  const loTitle =
    short.lower === '중가' ? `${g.horizonKo}채널하` : `${g.horizonKo}하·${short.lower}`;
  const upHot = short.upper === '돌파' || short.upper === '돌파가능' || short.upper === '저항가능';
  const loHot = short.lower === '돌파' || short.lower === '돌파가능' || short.lower === '지지가능';

  return [
    {
      price: g.tipUpper,
      color: g.useBearFill ? 'rgba(248,113,113,0.85)' : 'rgba(96,165,250,0.85)',
      title: upTitle,
      lineWidth: upHot ? 2 : 1,
      lineStyle: short.upper === '돌파' ? 'solid' : 'dashed',
      axisLabel: true,
    },
    {
      price: g.tipMid,
      color: 'rgba(226,232,240,0.55)',
      title: `${g.horizonKo}채널중`,
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    },
    {
      price: g.tipLower,
      color: g.useBearFill ? 'rgba(185,28,28,0.85)' : 'rgba(37,99,235,0.85)',
      title: loTitle,
      lineWidth: loHot ? 2 : 1,
      lineStyle: short.lower === '돌파' ? 'solid' : 'dashed',
      axisLabel: true,
    },
  ];
}

/**
 * 채널 띠 → 돌파/지지 상태 + 머니엣지 플랜 + 구조 가격선.
 */
export function buildMergedDeskChannelMoneyEdgePack(
  candles: Candle[],
  timeframe: string
): MergedDeskChannelMoneyEdgePack {
  const pack = buildMergedDeskBlueRedChannels(candles, timeframe);
  const geoms = pack.geoms;
  if (!geoms.length || candles.length < 12) {
    return {
      overlays: pack.overlays,
      plan: null,
      priceLines: [],
      summaryKo: pack.summaryKo || '채널머니 — 봉/피벗 부족',
      geoms: [],
      edgeReads: [],
    };
  }

  const close = Number(candles[candles.length - 1]?.close) || 0;
  const atr = atrApprox(candles);
  const longG = geoms.find((g) => g.horizon === 'long') ?? null;

  const edgeReads = geoms
    .map((g) => classifyMergedDeskChannelEdges(candles, g, atr))
    .filter((r): r is MergedDeskChannelEdgeRead => !!r);

  const candidates: EdgeCandidate[] = [];
  for (const read of edgeReads) {
    candidates.push(...scoreFromEdgeRead(candles, read, atr));
  }
  candidates.sort((a, b) => b.score - a.score);

  /** 단기·장기 동방이면 단기 가산 */
  let best = candidates[0] ?? null;
  const shortCand = candidates.filter((c) => c.geom.horizon === 'short');
  const longCand = candidates.filter((c) => c.geom.horizon === 'long');
  if (shortCand[0] && longCand[0] && shortCand[0].direction === longCand[0].direction) {
    best = {
      ...shortCand[0],
      score: shortCand[0].score + 12,
      reasons: [...shortCand[0].reasons, '장기에지 동방'],
    };
  }

  const plan = best ? buildPlanFromEdge(best, longG, atr, close) : null;
  const structLines = structurePriceLines(edgeReads);

  /** 단기·장기 띠에 상태 캡션 */
  const captionByHorizon: Partial<Record<MergedDeskChannelHorizon, string>> = {};
  for (const read of edgeReads) {
    captionByHorizon[read.geom.horizon] = read.captionKo;
  }
  if (plan) {
    const hk = horizonKey(plan.horizonKo);
    const dirKo = plan.direction === 'LONG' ? '롱' : '숏';
    const moneyTag =
      plan.status === 'ENTER'
        ? `${plan.edgeStateKo}·${dirKo}진입`
        : plan.status === 'TOUCH'
          ? `${plan.edgeStateKo}·${dirKo}터치`
          : `${plan.edgeStateKo}·${dirKo}대기`;
    captionByHorizon[hk] = moneyTag;
  }

  const stamped = stampMergedDeskBlueRedMoneyCaptions(pack, captionByHorizon);
  const shortRead = edgeReads.find((r) => r.geom.horizon === 'short') ?? edgeReads[0];
  const stateSummary = shortRead
    ? `상=${shortRead.upper} · 하=${shortRead.lower}`
    : '상태없음';

  if (!plan) {
    return {
      overlays: stamped.overlays,
      plan: null,
      priceLines: structLines,
      summaryKo: `${pack.summaryKo} · ${stateSummary}`,
      geoms,
      edgeReads,
    };
  }

  return {
    overlays: stamped.overlays,
    plan,
    priceLines: structLines,
    summaryKo: `채널머니 · ${plan.horizonKo} · ${plan.edgeStateKo} · ${plan.direction === 'LONG' ? '롱' : '숏'} · ${plan.statusKo} · RR≈${plan.rr.toFixed(1)}${
      plan.confluence ? ' · 정렬' : ''
    } · ${stateSummary}`,
    geoms,
    edgeReads,
  };
}

