input.contents:
/**
 * 통합·분석 — 파란/빨간 평행 추세 채널 (업그레이드).
 * 스윙피벗 품질·터치수·폭 정규화 · 단기(주)·장기(보조) 계층.
 * geometry는 채널머니와 공유 · 확정 매매·승률 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import {
  collectSwingPivots,
  pickSwingPivotPair,
  type CandlePivot,
} from '@/lib/mergedDeskCandleTrendline';
import { mergedWorkCandles } from '@/lib/mergedAnalysisOverlayTimes';
import { sanitizeChartCandlesForSeries } from '@/lib/volumeHistogramIntelligence';
import { mergedDesk4hReferencePivotWindowForTf } from '@/lib/mergedDesk4hReference';

export type MergedDeskChannelHorizon = 'short' | 'long' | 'fb';

export type MergedDeskChannelGeom = {
  horizon: MergedDeskChannelHorizon;
  horizonKo: '단기' | '장기' | '스윙';
  descending: boolean;
  useBearFill: boolean;
  tipUpper: number;
  tipLower: number;
  tipMid: number;
  width: number;
  tStart: number;
  tEnd: number;
  up1: number;
  up2: number;
  lo1: number;
  lo2: number;
  /** 0~100 — 피벗·터치·폭 품질 */
  quality: number;
  touchHigh: number;
  touchLow: number;
  /** 주 채널(단기) vs 보조(장기) */
  primary: boolean;
  slopePct: number;
};

export type MergedDeskBlueRedChannelPack = {
  overlays: OverlayItem[];
  geoms: MergedDeskChannelGeom[];
  summaryKo: string;
};

function work(candles: Candle[], timeframe: string): Candle[] {
  return sanitizeChartCandlesForSeries(mergedWorkCandles(candles, timeframe), timeframe);
}

function pivotHigh(candles: Candle[], i: number, L: number, R: number): boolean {
  const h = candles[i]!.high;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || candles[j]!.high >= h) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= candles.length || candles[j]!.high > h) return false;
  }
  return true;
}

function pivotLow(candles: Candle[], i: number, L: number, R: number): boolean {
  const lo = candles[i]!.low;
  for (let j = i - L; j < i; j++) {
    if (j < 0 || candles[j]!.low <= lo) return false;
  }
  for (let j = i + 1; j <= i + R; j++) {
    if (j >= candles.length || candles[j]!.low < lo) return false;
  }
  return true;
}

function collectPivotsInLookback(
  candles: Candle[],
  timeframe: string,
  lookback: number
): { highs: CandlePivot[]; lows: CandlePivot[] } {
  const { L, R } = mergedDesk4hReferencePivotWindowForTf(timeframe);
  const start = Math.max(L, candles.length - lookback);
  const highs: CandlePivot[] = [];
  const lows: CandlePivot[] = [];
  for (let i = start + L; i < candles.length - R; i++) {
    if (pivotHigh(candles, i, L, R)) {
      highs.push({ i, price: candles[i]!.high, time: Number(candles[i]!.time) });
    }
    if (pivotLow(candles, i, L, R)) {
      lows.push({ i, price: candles[i]!.low, time: Number(candles[i]!.time) });
    }
  }
  return { highs, lows };
}

/** 최근 피벗쌍 중 span·기울기 안정 점수 높은 쌍 */
function pickBestPair(
  pivots: CandlePivot[],
  minBars: number,
  preferRecent = true
): [CandlePivot, CandlePivot] | null {
  if (pivots.length < 2) return null;
  let best: [CandlePivot, CandlePivot] | null = null;
  let bestScore = -1;
  const last = pivots[pivots.length - 1]!;
  for (let a = 0; a < pivots.length - 1; a++) {
    for (let b = a + 1; b < pivots.length; b++) {
      const p1 = pivots[a]!;
      const p2 = pivots[b]!;
      const span = p2.i - p1.i;
      if (span < minBars) continue;
      const slope = Math.abs((p2.price - p1.price) / span);
      const recentBoost = preferRecent ? 1 + (p2.i / Math.max(1, last.i)) * 0.35 : 1;
      const spanScore = Math.min(1.4, span / (minBars * 3));
      const score = spanScore * recentBoost * (1 / (1 + slope / (Math.abs(p2.price) * 0.002 + 1e-9)));
      if (score > bestScore) {
        bestScore = score;
        best = [p1, p2];
      }
    }
  }
  if (best) return best;
  return [pivots[pivots.length - 2]!, pivots[pivots.length - 1]!];
}

function lineAt(p1: CandlePivot, p2: CandlePivot, idx: number): number {
  const slope = (p2.price - p1.price) / Math.max(1, p2.i - p1.i);
  return p1.price + slope * (idx - p1.i);
}

function countTouches(
  candles: Candle[],
  iStart: number,
  iEnd: number,
  upFn: (i: number) => number,
  loFn: (i: number) => number,
  tol: number
): { hi: number; lo: number } {
  let hi = 0;
  let lo = 0;
  const step = Math.max(1, Math.floor((iEnd - iStart) / 80));
  for (let i = iStart; i <= iEnd; i += step) {
    const c = candles[i];
    if (!c) continue;
    const u = upFn(i);
    const l = loFn(i);
    if (Math.abs(c.high - u) <= tol || (c.high >= u - tol && c.high <= u + tol * 1.5)) hi += 1;
    if (Math.abs(c.low - l) <= tol || (c.low <= l + tol && c.low >= l - tol * 1.5)) lo += 1;
  }
  return { hi, lo };
}

type ChannelBuild = {
  overlays: OverlayItem[];
  geom: MergedDeskChannelGeom;
};

function buildOneParallelChannel(params: {
  candles: Candle[];
  highs: CandlePivot[];
  lows: CandlePivot[];
  idPrefix: string;
  horizon: MergedDeskChannelHorizon;
  horizonKo: '단기' | '장기' | '스윙';
  minBars: number;
  widthPct: number;
  forceBearFill?: boolean;
  moneyCaptionKo?: string | null;
  primary: boolean;
  /** 보조 채널 라벨 숨김 */
  hideBandLabel?: boolean;
}): ChannelBuild | null {
  const { candles, highs, lows, idPrefix, horizon, horizonKo, minBars, widthPct, primary } =
    params;
  const hiPair = pickBestPair(highs, minBars);
  const loPair = pickBestPair(lows, minBars);
  if (!hiPair || candles.length < 8) return null;

  const [h1, h2] = hiPair;
  const slope = (h2.price - h1.price) / Math.max(1, h2.i - h1.i);
  const descending = slope < 0;
  const iEnd = candles.length - 1;
  const tEnd = Number(candles[iEnd]!.time);
  const midPx = Math.abs(h2.price) || 1;
  const slopePct = (slope / midPx) * 100;

  /** 저점 거리로 폭 + 고점 잔차 보정 */
  const dists: number[] = [];
  for (const lo of lows) {
    if (lo.i < h1.i) continue;
    const up = lineAt(h1, h2, lo.i);
    const d = up - lo.price;
    if (d > 0) dists.push(d);
  }
  dists.sort((a, b) => a - b);
  let width =
    dists.length > 0
      ? dists[Math.min(dists.length - 1, Math.floor(dists.length * widthPct))]!
      : midPx * 0.02;
  if (!(width > 0) && loPair) {
    width = Math.max(
      Math.abs(lineAt(h1, h2, loPair[0].i) - loPair[0].price),
      Math.abs(lineAt(h1, h2, loPair[1].i) - loPair[1].price),
      midPx * 0.012
    );
  }
  if (!(width > 0)) width = midPx * 0.018;
  /** 과도하게 넓은 채널 클램프 */
  width = Math.min(width, midPx * 0.085);
  width = Math.max(width, midPx * 0.006);

  const tStart = Math.min(h1.time, loPair?.[0]?.time ?? h1.time);
  const iStart = Math.min(h1.i, loPair?.[0]?.i ?? h1.i);
  const up1 = lineAt(h1, h2, iStart);
  const up2 = lineAt(h1, h2, iEnd);
  const lo1 = up1 - width;
  const lo2 = up2 - width;
  const tipUpper = up2;
  const tipLower = lo2;
  const tipMid = (tipUpper + tipLower) / 2;

  const tol = Math.max(width * 0.08, midPx * 0.0012);
  const touches = countTouches(
    candles,
    iStart,
    iEnd,
    (i) => lineAt(h1, h2, i),
    (i) => lineAt(h1, h2, i) - width,
    tol
  );

  let quality = 42;
  quality += Math.min(22, touches.hi * 4 + touches.lo * 4);
  quality += Math.min(12, highs.length + lows.length);
  quality += Math.abs(slopePct) > 0.002 && Math.abs(slopePct) < 0.35 ? 8 : 0;
  if (width / midPx > 0.055) quality -= 8;
  if (width / midPx < 0.01) quality -= 4;
  quality = Math.max(20, Math.min(96, Math.round(quality)));

  const useBear = params.forceBearFill != null ? params.forceBearFill : descending;
  /** 주 채널 진하게 · 보조는 옅게(겹침 가독성) */
  const fill = primary
    ? useBear
      ? 'rgba(239,68,68,0.30)'
      : 'rgba(59,130,246,0.32)'
    : useBear
      ? 'rgba(239,68,68,0.14)'
      : 'rgba(59,130,246,0.15)';
  const edgeUp = useBear ? '#F87171' : '#60A5FA';
  const edgeLo = useBear ? '#B91C1C' : '#2563EB';
  const dirKo = descending ? '하락' : '상승';
  const money = String(params.moneyCaptionKo || '').trim();
  const captionKo = params.hideBandLabel
    ? ''
    : money
      ? `${horizonKo}${dirKo}·${money}`
      : `${horizonKo}${dirKo}채널`;
  const tip = [
    `${horizonKo}${dirKo}채널`,
    `품질${quality}`,
    `터치 상${touches.hi}/하${touches.lo}`,
    primary ? '주채널' : '보조채널',
    money || '',
    '참고·비보장',
  ]
    .filter(Boolean)
    .join(' · ');

  const geom: MergedDeskChannelGeom = {
    horizon,
    horizonKo,
    descending,
    useBearFill: useBear,
    tipUpper,
    tipLower,
    tipMid,
    width,
    tStart,
    tEnd,
    up1,
    up2,
    lo1,
    lo2,
    quality,
    touchHigh: touches.hi,
    touchLow: touches.lo,
    primary,
    slopePct,
  };

  const band: OverlayItem = {
    id: `${idPrefix}-band`,
    kind: 'channelBand',
    label: captionKo,
    zoneFaceBase: captionKo || undefined,
    x1: 0,
    y1: 0.5,
    x2: 1,
    y2: 0.5,
    time1: tStart,
    time2: tEnd,
    price1: Math.max(up1, up2),
    price2: Math.min(lo1, lo2),
    confidence: quality,
    color: fill,
    category: 'chartPrimeTrendChannels',
    structureBias: descending ? 'bearish' : 'bullish',
    zoneFillPreserve: true,
    channelBand: {
      time1: tStart,
      time2: tEnd,
      priceHigh1: up1,
      priceHigh2: up2,
      priceLow1: lo1,
      priceLow2: lo2,
    },
    overlayZoneExtraClass: [
      'merged-desk-rb-channel',
      'merged-swing-channel',
      'merged-desk-blue-red-channel',
      primary ? 'merged-desk-rb-primary' : 'merged-desk-rb-secondary',
    ].join(' '),
    labelTooltip: tip,
    lineLabelColor: useBear ? '#fecaca' : '#bfdbfe',
    labelBackgroundColor: primary
      ? useBear
        ? 'rgba(127,29,29,0.92)'
        : 'rgba(30,58,138,0.92)'
      : useBear
        ? 'rgba(127,29,29,0.55)'
        : 'rgba(30,58,138,0.55)',
    labelTextColor: '#f8fafc',
  };

  const strokeW = primary ? 2.25 : 1.25;
  const edge = (
    id: string,
    edgeTag: '상' | '하',
    p1: number,
    p2: number,
    color: string
  ): OverlayItem => ({
    id,
    kind: 'trendLine',
    label: primary ? `${horizonKo}${edgeTag}` : '',
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 1,
    time1: tStart,
    price1: p1,
    time2: tEnd,
    price2: p2,
    confidence: quality,
    color,
    category: 'chartPrimeTrendChannels',
    lineStrokeWidth: strokeW,
    lineDash: primary ? '6 4' : '3 5',
    noProject: true,
    overlayZoneExtraClass: [
      'merged-desk-rb-channel',
      'merged-swing-channel',
      'merged-desk-blue-red-channel',
      primary ? 'merged-desk-rb-primary' : 'merged-desk-rb-secondary',
    ].join(' '),
    labelTooltip: tip,
    lineLabelColor: '#e2e8f0',
  });

  const overlays: OverlayItem[] = [
    band,
    edge(`${idPrefix}-upper`, '상', up1, up2, edgeUp),
    edge(`${idPrefix}-lower`, '하', lo1, lo2, edgeLo),
  ];

  /** 주 채널만 중선(점선) — 축 가격선 대신 대각 중선으로 중가 표시 */
  if (primary) {
    overlays.push({
      id: `${idPrefix}-mid`,
      kind: 'trendLine',
      label: '',
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 1,
      time1: tStart,
      price1: (up1 + lo1) / 2,
      time2: tEnd,
      price2: (up2 + lo2) / 2,
      confidence: quality,
      color: 'rgba(226,232,240,0.45)',
      category: 'chartPrimeTrendChannels',
      lineStrokeWidth: 1,
      lineDash: '2 6',
      noProject: true,
      overlayZoneExtraClass:
        'merged-desk-rb-channel merged-desk-rb-primary merged-desk-rb-mid',
      labelTooltip: tip,
    });
  }

  return { geom, overlays };
}

function applyMoneyCaptionToOverlays(
  overlays: OverlayItem[],
  geom: MergedDeskChannelGeom,
  moneyCaptionKo: string | null | undefined,
  opts?: { clear?: boolean }
): OverlayItem[] {
  if (opts?.clear) {
    return overlays.map((o) =>
      o.kind === 'channelBand'
        ? { ...o, label: '', zoneFaceBase: undefined }
        : o
    );
  }
  const money = String(moneyCaptionKo || '').trim();
  if (!money) return overlays;
  const dirKo = geom.descending ? '하락' : '상승';
  const captionKo = geom.primary
    ? `★${geom.horizonKo}${dirKo}·${money}`
    : `${geom.horizonKo}${dirKo}·${money}`;
  return overlays.map((o) => {
    if (o.kind !== 'channelBand') return o;
    return {
      ...o,
      label: captionKo,
      zoneFaceBase: captionKo,
      labelTooltip: `${String(o.labelTooltip || '')} · ${money}`.trim(),
      labelBackgroundColor: geom.primary
        ? geom.useBearFill
          ? 'rgba(127,29,29,0.95)'
          : 'rgba(30,58,138,0.95)'
        : o.labelBackgroundColor,
    };
  });
}

export function buildMergedDeskBlueRedChannels(
  candles: Candle[],
  timeframe: string,
  opts?: {
    moneyCaptionByHorizon?: Partial<Record<MergedDeskChannelHorizon, string>>;
    /** 보조 채널 라벨 숨김(우선상태 1개 정책) */
    hideSecondaryLabel?: boolean;
  }
): MergedDeskBlueRedChannelPack {
  const safe = work(candles, timeframe);
  if (safe.length < 24) {
    return { overlays: [], geoms: [], summaryKo: '파란·빨간 채널 — 봉 부족' };
  }

  const shortLb = Math.min(safe.length - 2, Math.max(40, Math.floor(safe.length * 0.3)));
  const longLb = Math.min(safe.length - 2, Math.max(80, Math.floor(safe.length * 0.58)));

  const short = collectPivotsInLookback(safe, timeframe, shortLb);
  const long = collectPivotsInLookback(safe, timeframe, longLb);
  const caps = opts?.moneyCaptionByHorizon;
  const hideSec = opts?.hideSecondaryLabel !== false;

  const shortBuilt = buildOneParallelChannel({
    candles: safe,
    highs: short.highs,
    lows: short.lows,
    idPrefix: 'merged-desk-rb-short',
    horizon: 'short',
    horizonKo: '단기',
    minBars: 5,
    widthPct: 0.52,
    moneyCaptionKo: caps?.short,
    primary: true,
  });

  const shortSlope =
    short.highs.length >= 2
      ? (() => {
          const p = pickBestPair(short.highs, 5);
          if (!p) return 0;
          return (p[1].price - p[0].price) / Math.max(1, p[1].i - p[0].i);
        })()
      : 0;

  const longBuilt = buildOneParallelChannel({
    candles: safe,
    highs: long.highs,
    lows: long.lows,
    idPrefix: 'merged-desk-rb-long',
    horizon: 'long',
    horizonKo: '장기',
    minBars: 8,
    widthPct: 0.7,
    /** 단기와 반대 팔레트로 복도 대비 */
    forceBearFill: !(shortSlope < 0),
    moneyCaptionKo: hideSec ? null : caps?.long,
    primary: false,
    hideBandLabel: hideSec,
  });

  const built = [longBuilt, shortBuilt].filter(Boolean) as ChannelBuild[];
  if (!built.length) {
    const { highs, lows } = collectSwingPivots(candles, timeframe);
    const hi = pickSwingPivotPair(highs, timeframe);
    if (hi) {
      const fb = buildOneParallelChannel({
        candles: safe,
        highs,
        lows,
        idPrefix: 'merged-desk-rb-fb',
        horizon: 'fb',
        horizonKo: '스윙',
        minBars: 6,
        widthPct: 0.58,
        moneyCaptionKo: caps?.fb,
        primary: true,
      });
      if (fb) {
        return {
          overlays: fb.overlays,
          geoms: [fb.geom],
          summaryKo: `스윙채널 1본 · 품질${fb.geom.quality}`,
        };
      }
    }
    return { overlays: [], geoms: [], summaryKo: '파란·빨간 채널 — 피벗 부족' };
  }

  const overlays = built.flatMap((b) => b.overlays);
  const geoms = built.map((b) => b.geom);
  const qAvg = Math.round(geoms.reduce((s, g) => s + g.quality, 0) / geoms.length);
  return {
    overlays,
    geoms,
    summaryKo: `파란·빨간채널 ${geoms.length}본 · 품질≈${qAvg} · 주=단기`,
  };
}

/** 우선 캡션만 주 채널에 · 보조는 비움 */
export function stampMergedDeskBlueRedMoneyCaptions(
  pack: MergedDeskBlueRedChannelPack,
  captionByHorizon: Partial<Record<MergedDeskChannelHorizon, string>>,
  opts?: { primaryOnly?: boolean }
): MergedDeskBlueRedChannelPack {
  if (!pack.overlays.length) return pack;
  const primaryOnly = opts?.primaryOnly !== false;
  const overlays = pack.overlays.map((o) => {
    const id = String(o.id || '');
    let horizon: MergedDeskChannelHorizon | null = null;
    if (id.includes('-short-')) horizon = 'short';
    else if (id.includes('-long-')) horizon = 'long';
    else if (id.includes('-fb-')) horizon = 'fb';
    if (!horizon || o.kind !== 'channelBand') return o;
    const geom = pack.geoms.find((g) => g.horizon === horizon);
    if (!geom) return o;
    if (primaryOnly && !geom.primary) {
      return applyMoneyCaptionToOverlays([o], geom, null, { clear: true })[0]!;
    }
    const cap = captionByHorizon[horizon];
    if (!cap) {
      if (primaryOnly && geom.primary) return o;
      return applyMoneyCaptionToOverlays([o], geom, null, { clear: true })[0]!;
    }
    return applyMoneyCaptionToOverlays([o], geom, cap)[0]!;
  });
  return { ...pack, overlays };
}

