function fmt(p: number): string {
  if (!(p > 0) || !Number.isFinite(p)) return '—';
  if (p >= 1000) return p.toFixed(0);
  if (p >= 1) return p.toFixed(1);
  return p.toFixed(3);
}

function atrApprox(candles: Candle[]): number {
  const n = candles.length;
  if (n < 5) {
    const c = Number(candles[n - 1]?.close) || 0;
    return c > 0 ? c * 0.008 : 0;
  }
  const start = Math.max(1, n - 14);
  let sum = 0;
  let cnt = 0;
  for (let i = start; i < n; i++) {
    const h = Number(candles[i]!.high);
    const l = Number(candles[i]!.low);
    const pc = Number(candles[i - 1]!.close);
    if (![h, l, pc].every(Number.isFinite)) continue;
    sum += Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
    cnt += 1;
  }
  if (cnt <= 0) {
    const c = Number(candles[n - 1]?.close) || 0;
    return c > 0 ? c * 0.008 : 0;
  }
  return sum / cnt;
}

function volRatio(candles: Candle[]): number {
  const n = candles.length;
  if (n < 8) return 1;
  const last = Number(candles[n - 1]?.volume) || 0;
  let sum = 0;
  let cnt = 0;
  for (let i = Math.max(0, n - 21); i < n - 1; i++) {
    const v = Number(candles[i]?.volume);
    if (Number.isFinite(v) && v >= 0) {
      sum += v;
      cnt += 1;
    }
  }
  if (cnt <= 0 || !(last > 0)) return 1;
  return last / (sum / cnt);
}

function statusKoOf(s: MergedDeskChannelMoneyStatus): string {
  if (s === 'ENTER') return '진입';
  if (s === 'TOUCH') return '터치';
  if (s === 'INVALID') return '무효';
  return '대기';
}

function horizonKey(horizonKo: string): MergedDeskChannelHorizon {
  if (horizonKo === '장기') return 'long';
  if (horizonKo === '스윙') return 'fb';
  return 'short';
}

function tipPos(close: number, g: MergedDeskChannelGeom): number {
  if (!(g.width > 0)) return 0.5;
  return (close - g.tipLower) / g.width;
}

function countBreakBars(
  candles: Candle[],
  level: number,
  side: 'above' | 'below',
  buf: number,
  maxLook = 3
): number {
  let n = 0;
  for (let k = 1; k <= maxLook; k++) {
    const c = candles[candles.length - k];
    if (!c) break;
    const close = Number(c.close);
    if (!Number.isFinite(close)) break;
    const ok = side === 'above' ? close > level + buf : close < level - buf;
    if (!ok) break;
    n += 1;
  }
  return n;
}

export function classifyMergedDeskChannelEdges(
  candles: Candle[],
  g: MergedDeskChannelGeom,
  atr: number,
  volR: number
): MergedDeskChannelEdgeRead | null {
  const last = candles[candles.length - 1];
  if (!last) return null;
  const close = Number(last.close);
  const open = Number(last.open);
  const high = Number(last.high);
  const low = Number(last.low);
  if (![close, open, high, low].every((x) => Number.isFinite(x) && x > 0)) return null;
  if (!(g.width > 0) || !(g.tipUpper > g.tipLower)) return null;

  const buf = Math.max(atr * 0.1, g.width * 0.035);
  const pad = Math.max(atr * 0.18, g.width * 0.07);
  const pos = tipPos(close, g);
  const bull = close > open;
  const bear = close < open;
  const body = Math.abs(close - open);
  const range = Math.max(1e-9, high - low);
  const bodyRatio = body / range;

  let upper: MergedDeskChannelEdgeState = '중가';
  const upBreakBars = countBreakBars(candles, g.tipUpper, 'above', buf * 0.6, 3);
  if (upBreakBars >= 1 && close > g.tipUpper + buf) {
    upper = '돌파';
  } else if (high >= g.tipUpper - pad * 0.4 && close <= g.tipUpper + buf) {
    if (bear && bodyRatio > 0.35 && high >= g.tipUpper - pad * 0.15) upper = '저항가능';
    else if (pos >= 0.78 || high >= g.tipUpper) upper = '돌파가능';
    else if (pos >= 0.7) upper = '돌파가능';
  } else if (pos >= 0.72) {
    upper = bear && bodyRatio > 0.4 ? '저항가능' : '돌파가능';
  }

  let lower: MergedDeskChannelEdgeState = '중가';
  const loBreakBars = countBreakBars(candles, g.tipLower, 'below', buf * 0.6, 3);
  if (loBreakBars >= 1 && close < g.tipLower - buf) {
    lower = '돌파';
  } else if (low <= g.tipLower + pad * 0.4 && close >= g.tipLower - buf) {
    if (bull && bodyRatio > 0.35 && close > (high + low) / 2) lower = '지지가능';
    else if (bear && close <= g.tipLower + buf) lower = '돌파가능';
    else lower = '지지가능';
  } else if (pos <= 0.28) {
    lower = bull || close >= g.tipLower ? '지지가능' : '돌파가능';
  }

  /** 거래량 약하면 돌파를 돌파가능으로 강등 */
  if (upper === '돌파' && volR < 0.85 && upBreakBars < 2) upper = '돌파가능';
  if (lower === '돌파' && volR < 0.85 && loBreakBars < 2) lower = '돌파가능';

  let captionKo = '중가';
  if (upper === '돌파') captionKo = '상돌파';
  else if (lower === '돌파') captionKo = '하돌파';
  else if (lower === '지지가능') captionKo = '지지가능';
  else if (upper === '저항가능') captionKo = '저항가능';
  else if (upper === '돌파가능') captionKo = '상돌파가능';
  else if (lower === '돌파가능') captionKo = '하돌파가능';

  const confirmedBars = Math.max(
    upper === '돌파' ? upBreakBars : 0,
    lower === '돌파' ? loBreakBars : 0
  );

  return {
    geom: g,
    upper,
    lower,
    captionKo,
    pos,
    volRatio: volR,
    confirmedBars,
  };
}

type EdgeCandidate = {
  direction: 'LONG' | 'SHORT';
  edge: 'lower' | 'upper';
  mode: 'bounce' | 'breakout';
  edgeStateKo: MergedDeskChannelEdgeState;
  geom: MergedDeskChannelGeom;
  near: boolean;
  reject: boolean;
  score: number;
  reasons: string[];
};

function scoreFromEdgeRead(
  candles: Candle[],
  read: MergedDeskChannelEdgeRead,
  atr: number
): EdgeCandidate[] {
  const g = read.geom;
  const last = candles[candles.length - 1]!;
  const close = Number(last.close);
  const open = Number(last.open);
  const high = Number(last.high);
  const low = Number(last.low);
  const pad = Math.max(atr * 0.15, g.width * 0.08);
  const qBoost = (g.quality - 50) * 0.25;
  const volBoost = read.volRatio >= 1.15 ? 10 : read.volRatio >= 0.95 ? 4 : -4;
  const out: EdgeCandidate[] = [];

  if (read.lower === '돌파') {
    out.push({
      direction: 'SHORT',
      edge: 'lower',
      mode: 'breakout',
      edgeStateKo: '돌파',
      geom: g,
      near: true,
      reject: false,
      score:
        62 +
        qBoost +
        volBoost +
        read.confirmedBars * 6 +
        (g.primary ? 10 : 0) +
        (g.descending ? 6 : 0),
      reasons: [
        `${g.horizonKo} 하돌파(종가×${read.confirmedBars})`,
        read.volRatio >= 1.1 ? '거래량 확대' : '거래량 보통',
      ],
    });
  }
  if (read.upper === '돌파') {
    out.push({
      direction: 'LONG',
      edge: 'upper',
      mode: 'breakout',
      edgeStateKo: '돌파',
      geom: g,
      near: true,
      reject: false,
      score:
        62 +
        qBoost +
        volBoost +
        read.confirmedBars * 6 +
        (g.primary ? 10 : 0) +
        (!g.descending ? 6 : 0),
      reasons: [
        `${g.horizonKo} 상돌파(종가×${read.confirmedBars})`,
        read.volRatio >= 1.1 ? '거래량 확대' : '거래량 보통',
      ],
    });
  }

  if (read.lower === '지지가능') {
    const rejectLong =
      low <= g.tipLower + pad * 1.2 &&
      close > open &&
      close >= g.tipLower - atr * 0.05 &&
      close > (low + high) / 2;
    out.push({
      direction: 'LONG',
      edge: 'lower',
      mode: 'bounce',
      edgeStateKo: '지지가능',
      geom: g,
      near: true,
      reject: rejectLong,
      score:
        (rejectLong ? 52 : 32) * (g.descending ? 0.92 : 1.12) +
        qBoost +
        (g.primary ? 8 : 0) +
        (1 - Math.min(1, Math.max(0, read.pos))) * 14,
      reasons: [
        `${g.horizonKo} 하단·지지가능`,
        rejectLong ? '거절봉' : '하단 근접',
        `터치품질 ${g.touchLow}`,
      ],
    });
  }

  if (read.upper === '저항가능') {
    const rejectShort =
      high >= g.tipUpper - pad * 1.2 &&
      close < open &&
      close <= g.tipUpper + atr * 0.05 &&
      close < (low + high) / 2;
    out.push({
      direction: 'SHORT',
      edge: 'upper',
      mode: 'bounce',
      edgeStateKo: '저항가능',
      geom: g,
      near: true,
      reject: rejectShort,
      score:
        (rejectShort ? 52 : 32) * (g.descending ? 1.12 : 0.92) +
        qBoost +
        (g.primary ? 8 : 0) +
        Math.min(1, Math.max(0, read.pos)) * 14,
      reasons: [
        `${g.horizonKo} 상단·저항가능`,
        rejectShort ? '거절봉' : '상단 근접',
        `터치품질 ${g.touchHigh}`,
      ],
    });
  }

  if (read.upper === '돌파가능') {
    out.push({
      direction: 'LONG',
      edge: 'upper',
      mode: 'breakout',
      edgeStateKo: '돌파가능',
      geom: g,
      near: true,
      reject: false,
      score: 22 + (g.primary ? 6 : 0) + qBoost * 0.5,
      reasons: [`${g.horizonKo} 상돌파가능`, '종가 확인 전 대기'],
    });
  }
  if (read.lower === '돌파가능') {
    out.push({
      direction: 'SHORT',
      edge: 'lower',
      mode: 'breakout',
      edgeStateKo: '돌파가능',
      geom: g,
      near: true,
      reject: false,
      score: 22 + (g.primary ? 6 : 0) + qBoost * 0.5,
      reasons: [`${g.horizonKo} 하돌파가능`, '종가 확인 전 대기'],
    });
  }

  return out;
}

function pickPrimaryDecision(
  candidates: EdgeCandidate[],
  edgeReads: MergedDeskChannelEdgeRead[]
): MergedDeskChannelPrimaryDecision | null {
  if (!candidates.length) {
    const primaryRead =
      edgeReads.find((r) => r.geom.primary) ?? edgeReads[0] ?? null;
    if (!primaryRead) return null;
    return {
      stateKo: '중가',
      horizon: primaryRead.geom.horizon,
      horizonKo: primaryRead.geom.horizonKo,
      edge: primaryRead.pos <= 0.5 ? 'lower' : 'upper',
      direction: 'NEUTRAL',
      mode: 'wait',
      captionKo: '중가관망',
      score: 0,
      reasonsKo: ['채널 중가 · 엣지 대기'],
    };
  }

  const best = candidates[0]!;
  const dirKo =
    best.direction === 'LONG' ? '롱' : best.direction === 'SHORT' ? '숏' : '';
  const stance =
    best.edgeStateKo === '돌파가능'
      ? '대기'
      : best.edgeStateKo === '돌파'
        ? '추종'
        : best.reject
          ? '반응'
          : '대기';

  return {
    stateKo: best.edgeStateKo,
    horizon: best.geom.horizon,
    horizonKo: best.geom.horizonKo,
    edge: best.edge,
    direction: best.direction,
    mode: best.mode,
    captionKo: `${best.edgeStateKo}·${dirKo}${stance}`,
    score: best.score,
    reasonsKo: best.reasons,
  };
}

function buildPlanFromEdge(
  edge: EdgeCandidate,
  longGeom: MergedDeskChannelGeom | null,
  atr: number,
  close: number,
  volR: number
): MergedDeskChannelMoneyPlan | null {
  const g = edge.geom;
  const w = g.width;
  const buf = Math.max(atr * 0.25, w * 0.055);

  let entry = close;
  let stopLoss = 0;
  let tp1 = 0;
  let tp2 = 0;
  let tp3 = 0;

  if (edge.mode === 'breakout' && edge.edgeStateKo === '돌파') {
    if (edge.direction === 'LONG') {
      entry = Math.max(close, g.tipUpper);
      stopLoss = g.tipUpper - buf;
      tp1 = entry + w * 0.5;
      tp2 = entry + w * 0.9;
      tp3 = longGeom && longGeom.tipUpper > tp2 ? longGeom.tipUpper : entry + w * 1.35;
    } else {
      entry = Math.min(close, g.tipLower);
      stopLoss = g.tipLower + buf;
      tp1 = entry - w * 0.5;
      tp2 = entry - w * 0.9;
      tp3 = longGeom && longGeom.tipLower < tp2 ? longGeom.tipLower : entry - w * 1.35;
    }
  } else if (edge.mode === 'breakout' && edge.edgeStateKo === '돌파가능') {
    if (edge.direction === 'LONG') {
      entry = g.tipUpper + buf * 0.4;
      stopLoss = g.tipMid;
      tp1 = entry + w * 0.45;
      tp2 = entry + w * 0.8;
      tp3 = entry + w * 1.2;
    } else {
      entry = g.tipLower - buf * 0.4;
      stopLoss = g.tipMid;
      tp1 = entry - w * 0.45;
      tp2 = entry - w * 0.8;
      tp3 = entry - w * 1.2;
    }
  } else if (edge.direction === 'LONG') {
    entry = Math.max(close, Math.min(g.tipLower + buf * 0.3, g.tipMid));
    if (edge.reject) entry = Math.max(close, g.tipLower);
    stopLoss = g.tipLower - buf;
    tp1 = g.tipMid;
    tp2 = g.tipUpper;
    tp3 = longGeom && longGeom.tipUpper > tp2 ? longGeom.tipUpper : tp2 + w * 0.5;
  } else {
    entry = Math.min(close, Math.max(g.tipUpper - buf * 0.3, g.tipMid));
    if (edge.reject) entry = Math.min(close, g.tipUpper);
    stopLoss = g.tipUpper + buf;
    tp1 = g.tipMid;
    tp2 = g.tipLower;
    tp3 = longGeom && longGeom.tipLower < tp2 ? longGeom.tipLower : tp2 - w * 0.5;
  }

  const geoOk =
    edge.direction === 'LONG'
      ? stopLoss < entry && tp1 > entry
      : stopLoss > entry && tp1 < entry;
  if (!geoOk) return null;

  const strengthened = strengthenUnifiedDeskTradePlan({
    direction: edge.direction,
    entry,
    stopLoss,
    tp1,
    tp2,
    tp3,
    invalidationKo: `종가 ${fmt(stopLoss)} 이탈 시 채널 무효`,
    sourceKo: '채널머니',
    alignedWithChart: true,
    warningsKo: [...edge.reasons, `${edge.edgeStateKo} · 확정 수익 아님`].slice(0, 5),
  });

  const rr =
    calcTradeRewardRisk(strengthened.entry, strengthened.stopLoss, strengthened.tp1) || 0;
  if (rr < 1.2) return null;

  const confluence =
    !!longGeom &&
    ((edge.direction === 'LONG' && !longGeom.descending) ||
      (edge.direction === 'SHORT' && longGeom.descending) ||
      (edge.direction === 'LONG' && tipPos(close, longGeom) <= 0.38) ||
      (edge.direction === 'SHORT' && tipPos(close, longGeom) >= 0.62));

  let status: MergedDeskChannelMoneyStatus = 'WAIT';
  if (edge.edgeStateKo === '돌파가능') status = 'WAIT';
  else if (edge.edgeStateKo === '돌파' && rr >= 1.35 && (volR >= 0.95 || confluence)) {
    status = edge.score >= 68 || confluence ? 'ENTER' : 'TOUCH';
  } else if (edge.reject && rr >= 1.5 && (confluence || edge.score >= 50)) status = 'ENTER';
  else if (
    edge.near &&
    (edge.edgeStateKo === '지지가능' || edge.edgeStateKo === '저항가능')
  ) {
    status = rr >= 1.35 ? 'TOUCH' : 'WAIT';
  } else if (edge.near) status = 'WAIT';
  else return null;

  if (status === 'ENTER' && rr < 1.5 && edge.edgeStateKo !== '돌파') status = 'TOUCH';
  if (!confluence && status === 'ENTER' && edge.score < 58 && edge.edgeStateKo !== '돌파') {
    status = 'TOUCH';
  }

  return {
    direction: strengthened.direction === 'NEUTRAL' ? edge.direction : strengthened.direction,
    entry: strengthened.entry,
    stopLoss: strengthened.stopLoss,
    tp1: strengthened.tp1,
    tp2: strengthened.tp2,
    tp3: strengthened.tp3,
    invalidationPrice: strengthened.stopLoss,
    invalidationKo: strengthened.invalidationKo,
    rr,
    status,
    statusKo: statusKoOf(status),
    entryAllowed: status === 'ENTER',
    reasonsKo: [
      ...edge.reasons,
      confluence ? '단기·장기 정렬' : '단기 단독(장기 확인)',
      `상태=${edge.edgeStateKo} · RR≈${rr.toFixed(1)} · ${statusKoOf(status)}`,
    ],
    confluence,
    edge: edge.edge,
    mode: edge.mode,
    edgeStateKo: edge.edgeStateKo,
    horizonKo: g.horizonKo,
    sourceKo: '채널머니',
  };
}

/** 축선 최소화 — 핫 엣지 1~2본만 (중선 제거) */
function slimStructurePriceLines(
  primary: MergedDeskChannelPrimaryDecision,
  geoms: MergedDeskChannelGeom[]
): AtlasPulsePriceLine[] {
  const g =
    geoms.find((x) => x.horizon === primary.horizon) ??
    geoms.find((x) => x.primary) ??
    geoms[0];
  if (!g) return [];

  const hotUpper =
    primary.edge === 'upper' ||
    primary.stateKo === '돌파' ||
    primary.stateKo === '돌파가능' ||
    primary.stateKo === '저항가능';
  const hotLower =
    primary.edge === 'lower' ||
    primary.stateKo === '돌파' ||
    primary.stateKo === '돌파가능' ||
    primary.stateKo === '지지가능';

  const lines: AtlasPulsePriceLine[] = [];
  if (hotUpper || primary.stateKo === '중가') {
    const isBreak = primary.stateKo === '돌파' && primary.edge === 'upper';
    lines.push({
      price: g.tipUpper,
      color: g.useBearFill ? 'rgba(248,113,113,0.9)' : 'rgba(96,165,250,0.9)',
      title:
        primary.edge === 'upper' && primary.stateKo !== '중가'
          ? `채널상·${primary.stateKo}`
          : '채널상',
      lineWidth: primary.edge === 'upper' ? 2 : 1,
      lineStyle: isBreak ? 'solid' : 'dashed',
      axisLabel: true,
    });
  }
  if (hotLower) {
    const isBreak = primary.stateKo === '돌파' && primary.edge === 'lower';
    lines.push({
      price: g.tipLower,
      color: g.useBearFill ? 'rgba(185,28,28,0.9)' : 'rgba(37,99,235,0.9)',
      title:
        primary.edge === 'lower' && primary.stateKo !== '중가'
          ? `채널하·${primary.stateKo}`
          : '채널하',
      lineWidth: primary.edge === 'lower' ? 2 : 1,
      lineStyle: isBreak ? 'solid' : 'dashed',
      axisLabel: true,
    });
  }
  return lines;
}

export function buildMergedDeskChannelMoneyEdgePack(
  candles: Candle[],
  timeframe: string
): MergedDeskChannelMoneyEdgePack {
  const pack = buildMergedDeskBlueRedChannels(candles, timeframe, {
    hideSecondaryLabel: true,
  });
  const geoms = pack.geoms;
  if (!geoms.length || candles.length < 12) {
    return {
      overlays: pack.overlays,
      plan: null,
      priceLines: [],
      summaryKo: pack.summaryKo || '채널머니 — 봉/피벗 부족',
      geoms: [],
      edgeReads: [],
      primary: null,
    };
  }

  const close = Number(candles[candles.length - 1]?.close) || 0;
  const atr = atrApprox(candles);
  const volR = volRatio(candles);
  const longG = geoms.find((g) => g.horizon === 'long') ?? null;

  const edgeReads = geoms
    .map((g) => classifyMergedDeskChannelEdges(candles, g, atr, volR))
    .filter((r): r is MergedDeskChannelEdgeRead => !!r);

  const candidates: EdgeCandidate[] = [];
  for (const read of edgeReads) {
    candidates.push(...scoreFromEdgeRead(candles, read, atr));
  }
  candidates.sort((a, b) => b.score - a.score);

  /** 단기·장기 동방 가산 */
  const shortCand = candidates.filter((c) => c.geom.horizon === 'short');
  const longCand = candidates.filter((c) => c.geom.horizon === 'long');
  if (shortCand[0] && longCand[0] && shortCand[0].direction === longCand[0].direction) {
    shortCand[0] = {
      ...shortCand[0],
      score: shortCand[0].score + 14,
      reasons: [...shortCand[0].reasons, '장기에지 동방'],
    };
    candidates.sort((a, b) => b.score - a.score);
  }

  const primary = pickPrimaryDecision(candidates, edgeReads);
  const best = candidates[0] ?? null;
  const plan =
    best && primary && primary.direction !== 'NEUTRAL'
      ? buildPlanFromEdge(best, longG, atr, close, volR)
      : null;

  /** 우선 캡션 1개만 주 채널에 */
  const captionByHorizon: Partial<Record<MergedDeskChannelHorizon, string>> = {};
  if (primary) {
    const hk = primary.horizon;
    captionByHorizon[hk] = primary.captionKo;
    /** 주 채널이 아니면 단기(주)에도 동일 우선상태 표기 */
    if (hk !== 'short' && geoms.some((g) => g.horizon === 'short' && g.primary)) {
      captionByHorizon.short = primary.captionKo;
      captionByHorizon[hk] = undefined;
    }
  }

  const stamped = stampMergedDeskBlueRedMoneyCaptions(pack, captionByHorizon, {
    primaryOnly: true,
  });

  const structLines = primary ? slimStructurePriceLines(primary, geoms) : [];

  const summaryKo = primary
    ? `채널★ ${primary.horizonKo}·${primary.captionKo}${
        plan ? ` · ${plan.statusKo}·${plan.rr.toFixed(1)}R` : ''
      } · vol×${volR.toFixed(2)}`
    : pack.summaryKo;

  return {
    overlays: stamped.overlays,
    plan,
    priceLines: structLines,
    summaryKo,
    geoms,
    edgeReads,
    primary,
  };
}

