 */
function buildChannelTradeSetVisuals(
  plan: MergedDeskChannelMoneyPlan,
  candles: Candle[]
): { overlays: OverlayItem[]; priceLines: AtlasPulsePriceLine[] } {
  if (!(plan.entry > 0) || !(plan.stopLoss > 0) || !(plan.tp1 > 0)) {
    return { overlays: [], priceLines: [] };
  }
  const n = candles.length;
  const t2 = Number(candles[n - 1]?.time) || 0;
  const t1 = Number(candles[Math.max(0, n - 12)]?.time) || t2;
  if (!(t2 > 0)) return { overlays: [], priceLines: [] };

  const isLong = plan.direction === 'LONG';
  const dirKo = isLong ? '롱' : '숏';
  const sideTag = isLong ? '▲' : '▼';
  const go = plan.status === 'ENTER' && plan.entryAllowed;
  const touch = plan.status === 'TOUCH';
  const stance = plan.statusKo;

  const priceLines: AtlasPulsePriceLine[] = [
    {
      price: plan.entry,
      color: go ? '#FACC15' : touch ? '#EAB308' : '#CA8A04',
      title: `${sideTag}진입E·${dirKo}·채널·${stance}`,
      lineWidth: go ? 3 : 2,
      lineStyle: go || touch ? 'solid' : 'dashed',
      axisLabel: true,
    },
    {
      price: plan.stopLoss,
      color: '#F87171',
      title: `손절SL·채널`,
      lineWidth: 2,
      lineStyle: 'dashed',
      axisLabel: true,
    },
  ];
  if (plan.tp1 > 0) {
    priceLines.push({
      price: plan.tp1,
      color: '#86EFAC',
      title: `익절TP1·채널`,
      lineWidth: 2,
      lineStyle: 'dotted',
      axisLabel: true,
    });
  }
  if (plan.tp2 > 0) {
    priceLines.push({
      price: plan.tp2,
      color: '#7DD3FC',
      title: `익절TP2·채널`,
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    });
  }
  if (plan.tp3 > 0) {
    priceLines.push({
      price: plan.tp3,
      color: '#A78BFA',
      title: `익절TP3·채널`,
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    });
  }
  priceLines.push({
    price: plan.invalidationPrice > 0 ? plan.invalidationPrice : plan.stopLoss,
    color: 'rgba(250,204,21,0.8)',
    title: `무효·채널`,
    lineWidth: 1,
    lineStyle: 'dashed',
    axisLabel: true,
  });

  const lo = Math.min(plan.tp1, plan.tp3 > 0 ? plan.tp3 : plan.tp1);
  const hi = Math.max(plan.tp1, plan.tp3 > 0 ? plan.tp3 : plan.tp2 > 0 ? plan.tp2 : plan.tp1);
  const zoneLabel = isLong ? '롱상승목표존' : '숏하락목표존';
  const overlays: OverlayItem[] = [
    {
      id: 'merged-desk-rb-tp-zone',
      kind: 'reactionZone',
      label: zoneLabel,
      zoneFaceBase: zoneLabel,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 1,
      time1: t1,
      time2: t2,
      price1: hi,
      price2: lo,
      confidence: Math.min(90, 55 + Math.round(plan.rr * 8)),
      color: isLong ? 'rgba(56,189,248,0.22)' : 'rgba(248,113,113,0.2)',
      category: 'chartPrimeTrendChannels',
      structureBias: isLong ? 'bullish' : 'bearish',
      zoneFillPreserve: true,
      overlayZoneExtraClass:
        'merged-desk-rb-tp-zone merged-desk-rb-channel merged-desk-money-zone-keep merged-desk-zone-pro-hero',
      labelTooltip: [
        zoneLabel,
