export function buildMergedDeskChannelMoneyEdgePack(
  candles: Candle[],
  timeframe: string
): MergedDeskChannelMoneyEdgePack {
  const pack = buildMergedDeskBlueRedChannels(candles, timeframe, {
    hideSecondaryLabel: true,
  });
  const geoms = pack.geoms;
  if (!geoms.length || candles.length < 12) {
    return {
      overlays: pack.overlays,
      plan: null,
      priceLines: [],
      summaryKo: pack.summaryKo || '채널머니 — 봉/피벗 부족',
      geoms: [],
      edgeReads: [],
      primary: null,
    };
  }

  const close = Number(candles[candles.length - 1]?.close) || 0;
  const atr = atrApprox(candles);
  const volR = volRatio(candles);
  const longG = geoms.find((g) => g.horizon === 'long') ?? null;

  const edgeReads = geoms
    .map((g) => classifyMergedDeskChannelEdges(candles, g, atr, volR))
    .filter((r): r is MergedDeskChannelEdgeRead => !!r);

  const candidates: EdgeCandidate[] = [];
  for (const read of edgeReads) {
    candidates.push(...scoreFromEdgeRead(candles, read, atr));
  }
  candidates.sort((a, b) => b.score - a.score);

  /** 단기·장기 동방 가산 */
  const shortCand = candidates.filter((c) => c.geom.horizon === 'short');
  const longCand = candidates.filter((c) => c.geom.horizon === 'long');
  if (shortCand[0] && longCand[0] && shortCand[0].direction === longCand[0].direction) {
    shortCand[0] = {
      ...shortCand[0],
      score: shortCand[0].score + 14,
      reasons: [...shortCand[0].reasons, '장기에지 동방'],
    };
    candidates.sort((a, b) => b.score - a.score);
  }

  const primary = pickPrimaryDecision(candidates, edgeReads);
  const best = candidates[0] ?? null;
  const plan =
    best && primary && primary.direction !== 'NEUTRAL'
      ? buildPlanFromEdge(best, longG, atr, close, volR)
      : null;

  const tradeSet = plan ? buildChannelTradeSetVisuals(plan, candles) : null;

  /** 우선 캡션 1개 — 매매세트 있으면 E/SL/TP 암시 */
  const captionByHorizon: Partial<Record<MergedDeskChannelHorizon, string>> = {};
  if (plan && primary) {
    const primaryGeom = geoms.find((g) => g.primary) ?? geoms[0]!;
    const dirKo = plan.direction === 'LONG' ? '롱' : '숏';
    captionByHorizon[primaryGeom.horizon] =
      `${plan.edgeStateKo}·${dirKo}${plan.statusKo}·E/SL/TP`;
  } else if (primary) {
    const primaryGeom = geoms.find((g) => g.primary) ?? geoms[0]!;
    captionByHorizon[primaryGeom.horizon] = primary.captionKo;
  }

  const stamped = stampMergedDeskBlueRedMoneyCaptions(pack, captionByHorizon, {
    primaryOnly: true,
  });

  const structLines = primary ? slimStructurePriceLines(primary, geoms) : [];
  /** 매매세트 선이 있으면 구조선은 핫 엣지 1본만(중복 축 라벨 감소) */
  const slimStruct =
    tradeSet && tradeSet.priceLines.length
      ? structLines.filter((l) => /돌파|지지|저항/.test(String(l.title || '')))
      : structLines;

  const summaryKo = plan
    ? `채널세트 · ${plan.horizonKo} · ${plan.edgeStateKo} · ${
        plan.direction === 'LONG' ? '롱' : '숏'
      } · E${fmt(plan.entry)} SL${fmt(plan.stopLoss)} TP1${fmt(plan.tp1)} · ${plan.statusKo} · ${plan.rr.toFixed(1)}R`
    : primary
      ? `채널★ ${primary.horizonKo}·${primary.captionKo} · vol×${volR.toFixed(2)}`
      : pack.summaryKo;

  return {
    overlays: [...stamped.overlays, ...(tradeSet?.overlays ?? [])],
    plan,
    priceLines: [...(tradeSet?.priceLines ?? []), ...slimStruct],
    summaryKo,
    geoms,
    edgeReads,
    primary,
  };
}

