/**
 * 채널게이트 매매 세트 — E/SL/TP 전폭선 + 게이트 스포트라이트 + 목표존.
 * 돌파가능·대기일 때 “◆채널게이트”로 일반 타점과 구분.
 */
function buildChannelTradeSetVisuals(
  plan: MergedDeskChannelMoneyPlan,
  candles: Candle[],
  atr: number
): { overlays: OverlayItem[]; priceLines: AtlasPulsePriceLine[] } {
  if (!(plan.entry > 0) || !(plan.stopLoss > 0) || !(plan.tp1 > 0)) {
    return { overlays: [], priceLines: [] };
  }
  const n = candles.length;
  const t2 = Number(candles[n - 1]?.time) || 0;
  const t1 = Number(candles[Math.max(0, n - 16)]?.time) || t2;
  if (!(t2 > 0)) return { overlays: [], priceLines: [] };

  const isLong = plan.direction === 'LONG';
  const dirKo = isLong ? '롱' : '숏';
  const sideTag = isLong ? '▲' : '▼';
  const go = plan.status === 'ENTER' && plan.entryAllowed;
  const touch = plan.status === 'TOUCH';
  const stance = plan.statusKo;
  const waitingBreak =
    plan.edgeStateKo === '돌파가능' || (plan.status === 'WAIT' && plan.mode === 'breakout');
  const gateOn = waitingBreak || plan.edgeStateKo === '돌파';

  const entryTitle = gateOn
    ? waitingBreak
      ? `◆채널게이트·${dirKo}진입·${fmt(plan.entry)}`
      : `◆채널게이트·${dirKo}돌파·${fmt(plan.entry)}`
    : `${sideTag}진입E·${dirKo}·채널·${stance}`;

  const priceLines: AtlasPulsePriceLine[] = [
    {
      price: plan.entry,
      color: gateOn ? (isLong ? '#FDE047' : '#FB7185') : go ? '#FACC15' : touch ? '#EAB308' : '#CA8A04',
      title: entryTitle,
      lineWidth: gateOn || go ? 4 : 2,
      lineStyle: 'solid',
      axisLabel: true,
    },
    {
      price: plan.stopLoss,
      color: '#F87171',
      title: gateOn ? `◆게이트손절·${fmt(plan.stopLoss)}` : `손절SL·채널`,
      lineWidth: 2,
      lineStyle: 'dashed',
      axisLabel: true,
    },
  ];
  if (plan.tp1 > 0) {
    priceLines.push({
      price: plan.tp1,
      color: '#4ADE80',
      title: gateOn ? `◆게이트TP1·${fmt(plan.tp1)}` : `익절TP1·채널`,
      lineWidth: 2,
      lineStyle: 'dotted',
      axisLabel: true,
    });
  }
  if (plan.tp2 > 0) {
    priceLines.push({
      price: plan.tp2,
      color: '#38BDF8',
      title: gateOn ? `◆게이트TP2·${fmt(plan.tp2)}` : `익절TP2·채널`,
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    });
  }
  if (plan.tp3 > 0) {
    priceLines.push({
      price: plan.tp3,
      color: '#C084FC',
      title: gateOn ? `◆게이트TP3·${fmt(plan.tp3)}` : `익절TP3·채널`,
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    });
  }
  priceLines.push({
    price: plan.invalidationPrice > 0 ? plan.invalidationPrice : plan.stopLoss,
    color: 'rgba(250,204,21,0.85)',
    title: gateOn ? `◆게이트무효` : `무효·채널`,
    lineWidth: 1,
    lineStyle: 'dashed',
    axisLabel: true,
  });

  const lo = Math.min(plan.tp1, plan.tp3 > 0 ? plan.tp3 : plan.tp1);
  const hi = Math.max(plan.tp1, plan.tp3 > 0 ? plan.tp3 : plan.tp2 > 0 ? plan.tp2 : plan.tp1);
  const spotPad = Math.max(atr * 0.18, Math.abs(plan.entry) * 0.0012);
  const overlays: OverlayItem[] = [];

  /** 게이트 스포트라이트 — 진입가 얇은 황금 띠 */
  if (gateOn) {
    overlays.push({
      id: 'merged-desk-rb-gate-spot',
      kind: 'reactionZone',
      label: waitingBreak
        ? `◆채널게이트 · ${dirKo}돌파대기`
        : `◆채널게이트 · ${dirKo}돌파`,
      zoneFaceBase: `◆채널게이트`,
      x1: 0,
      y1: 0,
      x2: 1,
      y2: 1,
      time1: t1,
      time2: t2,
      price1: plan.entry + spotPad,
      price2: plan.entry - spotPad,
      confidence: 88,
      color: isLong ? 'rgba(253,224,71,0.2)' : 'rgba(251,113,133,0.18)',
      category: 'chartPrimeTrendChannels',
      structureBias: isLong ? 'bullish' : 'bearish',
      zoneFillPreserve: true,
      overlayZoneExtraClass: [
        'merged-desk-rb-gate-spot',
        'merged-desk-rb-channel',
        'merged-desk-money-zone-keep',
        'merged-desk-zone-pro-hero',
        isLong ? 'merged-desk-rb-gate--long' : 'merged-desk-rb-gate--short',
      ].join(' '),
      labelTooltip: [
        '◆ 채널게이트',
        waitingBreak
          ? `종가 ${fmt(plan.entry)} ${isLong ? '상향' : '하향'} 돌파 확인 시 ${dirKo} 진입 후보`
          : `돌파 추종 ${dirKo} · E ${fmt(plan.entry)}`,
        `손절 ${fmt(plan.stopLoss)} · TP1 ${fmt(plan.tp1)}`,
        '확정 수익·승률 아님',
      ].join(' · '),
      labelBackgroundColor: isLong ? 'rgba(253,224,71,0.95)' : 'rgba(244,63,94,0.92)',
      labelTextColor: isLong ? '#0f172a' : '#fff1f2',
    });
  }

  overlays.push({
    id: 'merged-desk-rb-tp-zone',
    kind: 'reactionZone',
    label: isLong ? '◆게이트상승목표' : '◆게이트하락목표',
    zoneFaceBase: isLong ? '게이트상승목표' : '게이트하락목표',
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 1,
    time1: t1,
    time2: t2,
    price1: hi,
    price2: lo,
    confidence: Math.min(90, 55 + Math.round(plan.rr * 8)),
    color: isLong ? 'rgba(56,189,248,0.2)' : 'rgba(248,113,113,0.18)',
    category: 'chartPrimeTrendChannels',
    structureBias: isLong ? 'bullish' : 'bearish',
    zoneFillPreserve: true,
    overlayZoneExtraClass:
      'merged-desk-rb-tp-zone merged-desk-rb-gate-tp merged-desk-rb-channel merged-desk-money-zone-keep merged-desk-zone-pro-hero',
    labelTooltip: [
      isLong ? '롱 상승 목표존' : '숏 하락 목표존',
      `E ${fmt(plan.entry)} · SL ${fmt(plan.stopLoss)}`,
      `TP1~3 · RR≈${plan.rr.toFixed(1)}`,
      '채널폭 측정이동 · 참고',
    ].join(' · '),
    labelBackgroundColor: isLong ? 'rgba(8,47,73,0.92)' : 'rgba(127,29,29,0.92)',
    labelTextColor: '#f8fafc',
  });

  overlays.push({
    id: 'merged-desk-rb-entry-pin',
    kind: 'keyLevel',
    label: gateOn
      ? waitingBreak
        ? `◆${dirKo}진입게이트 ${fmt(plan.entry)}`
        : `◆${dirKo}게이트돌파 ${fmt(plan.entry)}`
      : `${sideTag}진입E ${fmt(plan.entry)}`,
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 0,
    time1: t1,
    time2: t2,
    price1: plan.entry,
    price2: plan.entry,
    confidence: 92,
    color: gateOn ? (isLong ? '#FDE047' : '#FB7185') : '#FACC15',
    category: 'chartPrimeTrendChannels',
    lineStrokeWidth: gateOn ? 3.5 : 2,
    lineDash: undefined,
    noProject: true,
    overlayZoneExtraClass: [
      'merged-desk-rb-entry-pin',
      'merged-desk-rb-gate-rail',
      'merged-desk-rb-channel',
      'merged-desk-trade-rail-prominent',
      isLong ? 'merged-desk-rb-gate--long' : 'merged-desk-rb-gate--short',
    ].join(' '),
    labelTooltip: waitingBreak
      ? `채널게이트 · 종가 ${fmt(plan.entry)} ${isLong ? '위' : '아래'} = ${dirKo} 진입 후보`
      : `채널 ${dirKo} 진입 ${fmt(plan.entry)}`,
    lineLabelColor: isLong ? '#0f172a' : '#fff1f2',
    labelBackgroundColor: isLong ? 'rgba(253,224,71,0.96)' : 'rgba(244,63,94,0.94)',
    labelTextColor: isLong ? '#0f172a' : '#fff1f2',
  });

  return { overlays, priceLines };
}

