   * - 돌파가능 → WAIT · 돌파 전 · 진입 금지
   * - 돌파실패 → INVALID · 진입 금지
   * - 지지/저항 바운스 → TOUCH/ENTER (기존)
   */
  let status: MergedDeskChannelMoneyStatus = 'WAIT';
  if (edge.edgeStateKo === '돌파실패') {
    status = 'INVALID';
  } else if (edge.edgeStateKo === '안착확정' && rr >= 1.05) {
    status = 'ENTER';
  } else if (edge.edgeStateKo === '돌파' || edge.edgeStateKo === '돌파가능') {
