          ? `채널상·${primary.stateKo}`
          : '채널상',
      lineWidth: primary.edge === 'upper' ? 2 : 1,
      lineStyle: isBreak ? 'solid' : 'dashed',
      axisLabel: true,
    });
  }
  if (hotLower) {
    const isBreak = primary.stateKo === '돌파' && primary.edge === 'lower';
    lines.push({
      price: g.tipLower,
      color: g.useBearFill ? 'rgba(185,28,28,0.9)' : 'rgba(37,99,235,0.9)',
      title:
        primary.edge === 'lower' && primary.stateKo !== '중가'
          ? `채널하·${primary.stateKo}`
          : '채널하',
      lineWidth: primary.edge === 'lower' ? 2 : 1,
      lineStyle: isBreak ? 'solid' : 'dashed',
      axisLabel: true,
    });
  }
  return lines;
}

const waitingBreak =
  plan.edgeStateKo === '돌파가능' || (plan.status === 'WAIT' && plan.mode === 'breakout');
const gateOn = waitingBreak || plan.edgeStateKo === '돌파';

const entryTitle = gateOn
  ? waitingBreak
    ? `◆채널게이트·${dirKo}진입·${fmt(plan.entry)}`
    : `◆채널게이트·${dirKo}돌파·${fmt(plan.entry)}`
  : `${sideTag}진입E·${dirKo}·채널·${stance}`;

const priceLines: AtlasPulsePriceLine[] = [
  {
    price: plan.entry,
    color: gateOn ? (isLong ? '#FDE047' : '#FB7185') : go ? '#FACC15' : touch ? '#EAB308' : '#CA8A04',
    title: entryTitle,
    lineWidth: gateOn || go ? 4 : 2,
    lineStyle: 'solid',
    axisLabel: true,
  },

  const breakoutSet = ch.mode === 'breakout' || ch.edgeStateKo === '돌파' || ch.edgeStateKo === '돌파가능';
  const canTake =
    !swingLocked &&
    (!draft ||
      draft.status === 'WAIT' ||
      draft.source === 'unified' ||
      draft.source === 'none' ||
      (breakoutSet && draft.source === 'hotZone'));
  if (
    canTake &&
    (ch.status === 'ENTER' ||
      ch.status === 'TOUCH' ||
      (ch.status === 'WAIT' && breakoutSet))
  ) {
    const strengthened = strengthenUnifiedDeskTradePlan({
      direction: ch.direction,
      entry: ch.entry,
      stopLoss: ch.stopLoss,
      tp1: ch.tp1,
      tp2: ch.tp2,
      tp3: ch.tp3,
      invalidationKo: ch.invalidationKo,
      sourceKo: '채널머니세트',
      alignedWithChart: true,
      warningsKo: [
        ...(ch.reasonsKo ?? []),
        ch.edgeStateKo ? `채널엣지=${ch.edgeStateKo}` : '',
        ch.mode === 'breakout' ? '모드=돌파추종·목표존' : '모드=지지/저항바운스·목표존',
        `손절 ${ch.stopLoss > 0 ? ch.stopLoss.toFixed(0) : '—'} · TP1 ${ch.tp1 > 0 ? ch.tp1.toFixed(0) : '—'}`,
      ]
        .filter(Boolean)
        .slice(0, 6),
    });
    const status: MergedDeskActivePlanStatus =
      ch.status === 'ENTER' ? 'ENTER' : ch.status === 'TOUCH' ? 'TOUCH' : 'WAIT';
    draft = {
      direction: ch.direction,
      entry: strengthened.entry,
      stopLoss: strengthened.stopLoss,
      tp1: strengthened.tp1,
      tp2: strengthened.tp2,
      tp3: strengthened.tp3,
      invalidationPrice: ch.invalidationPrice > 0 ? ch.invalidationPrice : strengthened.stopLoss,
      invalidationKo: strengthened.invalidationKo,
      rr: ch.rr || calcTradeRewardRisk(strengthened.entry, strengthened.stopLoss, strengthened.tp1) || 0,
      status,
      statusKo: statusKoOf(status),
      source: 'channel',
      sourceKo: `채널머니·${ch.edgeStateKo || '엣지'}`,
      entryAllowed: status === 'ENTER' && ch.entryAllowed,
      asUnifiedPlan: strengthened,
    };
  }
}

