'use client';

/**
 * 통합모드 전용 차트설정 패널 — 기존 ChartView「차트 설정」과 분리.
 */
import { useCallback, useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import {
  defaultSettings,
  loadSettings,
  saveSettings,
  type UserSettings,
} from '@/lib/settings';
