import {
  MERGED_DESK_CHART_DISPLAY_TICK_EVENT,
  OPEN_MERGED_DESK_CHART_SETTINGS_EVENT,
  resetMergedDeskChartDisplayAll,
} from '@/lib/mergedDeskChartDisplaySettings';

type LabelAlign = 'left' | 'center' | 'right';
type PricePos = 'left' | 'center' | 'right';

const PANEL_UI_KEY = 'ailongshort-merged-desk-chart-settings-ui-v1';
const ZONE_LABEL_POSITION_KEY = 'ailongshort-zone-label-position';
const ZONE_LABEL_H_SHIFT_KEY = 'ailongshort-zone-label-h-shift';

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
};

function Chip(props: {
  active?: boolean;
  onClick: () => void;
  title?: string;
  children: ReactNode;
  style?: CSSProperties;
}) {
  return (
    <button
      type="button"
      className={`tool-chip tool-chip-button ${props.active ? 'tool-chip-active' : ''}`}
      onClick={props.onClick}
      title={props.title}
      style={{ padding: '6px 11px', fontSize: 11, ...props.style }}
    >
      {props.children}
    </button>
  );
}

function Section({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section style={{ marginBottom: 16 }}>
      <div
        style={{
          fontSize: 11,
          fontWeight: 800,
          letterSpacing: '0.04em',
          color: '#93c5fd',
          marginBottom: 8,
          textTransform: 'uppercase' as const,
        }}
      >
        {title}
      </div>
      {children}
    </section>
  );
}

function readZonePos(): PricePos {
  if (typeof window === 'undefined') return 'right';
  try {
    const raw = window.localStorage.getItem(ZONE_LABEL_POSITION_KEY);
    if (raw === 'left' || raw === 'center' || raw === 'right') return raw;
  } catch {
    /* ignore */
  }
  return 'right';
}

function readZoneHShift(): number {
  if (typeof window === 'undefined') return 0;
  try {
    const n = parseInt(window.localStorage.getItem(ZONE_LABEL_H_SHIFT_KEY) || '0', 10);
    return Number.isFinite(n) ? Math.max(-200, Math.min(200, n)) : 0;
  } catch {
    return 0;
  }
}

function bumpDisplayTick() {
  if (typeof window === 'undefined') return;
  window.dispatchEvent(new Event(MERGED_DESK_CHART_DISPLAY_TICK_EVENT));
  window.dispatchEvent(new Event(SETTINGS_CHANGED_EVENT));
}

export function MergedDeskChartSettingsPanel({ open, onOpenChange }: Props) {
  const [settings, setSettings] = useState<UserSettings>(() => loadSettings());
  const [zoneLabelPosition, setZoneLabelPositionState] = useState<PricePos>(readZonePos);
  const [zoneLabelHShift, setZoneLabelHShiftState] = useState(readZoneHShift);
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
  const dragRef = useRef<{ ox: number; oy: number; sx: number; sy: number } | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    try {
      const raw = window.localStorage.getItem(PANEL_UI_KEY);
      if (raw) {
        const j = JSON.parse(raw) as { x?: number; y?: number };
        if (typeof j.x === 'number' && typeof j.y === 'number') setPos({ x: j.x, y: j.y });
      }
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const sync = () => {
      setSettings(loadSettings());
      setZoneLabelPositionState(readZonePos());
      setZoneLabelHShiftState(readZoneHShift());
    };
    window.addEventListener(SETTINGS_CHANGED_EVENT, sync);
    window.addEventListener(MERGED_DESK_CHART_DISPLAY_TICK_EVENT, sync);
    return () => {
      window.removeEventListener(SETTINGS_CHANGED_EVENT, sync);
      window.removeEventListener(MERGED_DESK_CHART_DISPLAY_TICK_EVENT, sync);
    };
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const onOpen = () => onOpenChange(true);
    window.addEventListener(OPEN_MERGED_DESK_CHART_SETTINGS_EVENT, onOpen);
    return () => window.removeEventListener(OPEN_MERGED_DESK_CHART_SETTINGS_EVENT, onOpen);
  }, [onOpenChange]);

  const apply = useCallback((patch: Partial<UserSettings>) => {
    const next = saveSettings(patch);
    setSettings(next);
    bumpDisplayTick();
  }, []);

  const setZoneLabelPosition = (p: PricePos) => {
    setZoneLabelPositionState(p);
    try {
      window.localStorage.setItem(ZONE_LABEL_POSITION_KEY, p);
    } catch {
      /* ignore */
    }
    bumpDisplayTick();
  };

  const setZoneLabelHShift = (value: number) => {
    const v = Math.max(-200, Math.min(200, Math.round(value)));
    setZoneLabelHShiftState(v);
    try {
      if (v === 0) window.localStorage.removeItem(ZONE_LABEL_H_SHIFT_KEY);
      else window.localStorage.setItem(ZONE_LABEL_H_SHIFT_KEY, String(v));
    } catch {
      /* ignore */
    }
    bumpDisplayTick();
  };

  const startDrag = (e: React.MouseEvent) => {
    if (e.button !== 0) return;
    const el = panelRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    dragRef.current = {
      ox: e.clientX,
      oy: e.clientY,
      sx: pos?.x ?? rect.left,
      sy: pos?.y ?? rect.top,
    };
    e.preventDefault();
  };

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const onMove = (e: MouseEvent) => {
      const d = dragRef.current;
      if (!d) return;
      const next = {
        x: Math.max(8, d.sx + (e.clientX - d.ox)),
        y: Math.max(8, d.sy + (e.clientY - d.oy)),
      };
      setPos(next);
    };
    const onUp = () => {
      if (!dragRef.current) return;
      dragRef.current = null;
      setPos((cur) => {
        if (!cur) return cur;
        try {
          window.localStorage.setItem(PANEL_UI_KEY, JSON.stringify(cur));
        } catch {
          /* ignore */
        }
        return cur;
      });
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, []);

  const onFullReset = () => {
    const ok =
      typeof window === 'undefined' ||
      window.confirm(
        '통합모드 차트 설정을 전부 초기화할까요?\n글자·위치·좌우·존색·표시 항목이 기본값으로 돌아갑니다.'
      );
    if (!ok) return;
    const next = resetMergedDeskChartDisplayAll();
    setSettings(next);
    setZoneLabelPositionState('right');
    setZoneLabelHShiftState(0);
    bumpDisplayTick();
  };

  if (!open || typeof document === 'undefined') return null;

  const alignDefault: LabelAlign =
    settings.chartMergedDeskLabelAlignDefault === 'left' ||
    settings.chartMergedDeskLabelAlignDefault === 'center'
      ? settings.chartMergedDeskLabelAlignDefault
      : 'right';
  const fontSize = Math.max(8, Math.min(22, Number(settings.overlayLabelFontSize) || 11));
  const scaleFs = Math.max(8, Math.min(22, Number(settings.chartScaleFontSize) || 12));

  const panelStyle: CSSProperties = pos
    ? {
        position: 'fixed',
        left: pos.x,
        top: pos.y,
        right: 'auto',
        bottom: 'auto',
      }
    : {
        position: 'fixed',
        right: 16,
        top: 72,
      };

  return createPortal(
    <div
      ref={panelRef}
      className="merged-desk-chart-settings-panel"
      role="dialog"
      aria-label="통합모드 차트설정"
      style={panelStyle}
    >
      <header className="merged-desk-chart-settings-panel__head">
        <button
          type="button"
          className="tool-chip tool-chip-button"
          onMouseDown={startDrag}
          title="드래그로 패널 이동"
          style={{ cursor: 'grab', padding: '4px 8px', fontSize: 10 }}
        >
          ↕
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 800, fontSize: 14, color: '#e0f2fe' }}>통합모드 차트설정</div>
          <div style={{ fontSize: 10, color: '#94a3b8', marginTop: 1 }}>표시 항목 · 글자 · 위치 · 존색</div>
        </div>
        <Chip
          onClick={onFullReset}
          title="전부 기본값"
          style={{ fontWeight: 800, borderColor: 'rgba(248,113,113,0.5)', color: '#fecaca' }}
        >
          초기화
        </Chip>
        <Chip onClick={() => onOpenChange(false)}>닫기</Chip>
      </header>

      <div className="merged-desk-chart-settings-panel__body">
        <Section title="넣을 항목">
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
            {(
              [
                ['기관밴드', 'chartMergedInstitutionalBandEnabled'],
                ['연합밴드', 'chartMonthDeskFusionDeskBandEnabled'],
                ['파란빨간채널', 'chartMergedDeskBlueRedChannelsEnabled'],
                ['스윙작도', 'chartMergedDeskSwingDrawEnabled'],
                ['SMC작도', 'chartMergedDeskSuperAiEnabled'],
                ['통합구름', 'chartMergedDeskUnifiedCloudEnabled'],
                ['btccion', 'chartMergedDeskBtccionDrawEnabled'],
                ['ZoneAI', 'chartMergedDeskZoneBattleHudEnabled'],
                ['Bitget Vol', 'chartMonthDeskBitgetCandles'],
              ] as const
            ).map(([label, key]) => (
              <Chip
                key={key}
                active={settings[key] !== false}
                onClick={() => apply({ [key]: settings[key] === false } as Partial<UserSettings>)}
              >
                {label}
              </Chip>
            ))}
            <Chip
              active={!settings.chartBulkHideLabels}
              onClick={() => apply({ chartBulkHideLabels: !settings.chartBulkHideLabels })}
            >
              라벨표시
            </Chip>
            <Chip
              active={!settings.chartBulkHideZones}
              onClick={() => apply({ chartBulkHideZones: !settings.chartBulkHideZones })}
            >
              존표시
            </Chip>
            <Chip
              active={!settings.chartBulkHideHLines}
              onClick={() => apply({ chartBulkHideHLines: !settings.chartBulkHideHLines })}
            >
              가로선표시
            </Chip>
            <Chip
              active={settings.chartMirageZoneFaceLang === 'en'}
              onClick={() =>
                apply({
                  chartMirageZoneFaceLang: settings.chartMirageZoneFaceLang === 'en' ? 'ko' : 'en',
                })
              }
            >
              EN라벨
            </Chip>
            <Chip
              active={settings.chartMirageZoneFaceCompact !== false}
              onClick={() =>
                apply({ chartMirageZoneFaceCompact: settings.chartMirageZoneFaceCompact === false })
              }
            >
              짧은라벨
            </Chip>
          </div>
        </Section>

        <Section title="글자 크기">
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
            <span style={{ fontSize: 11, color: '#94a3b8', minWidth: 64 }}>차트 라벨</span>
