  let lo = 0;
  const step = Math.max(1, Math.floor((iEnd - iStart) / 80));
  for (let i = iStart; i <= iEnd; i += step) {
    const c = candles[i];
    if (!c) continue;
    const u = upFn(i);
    const l = loFn(i);
    if (Math.abs(c.high - u) <= tol || (c.high >= u - tol && c.high <= u + tol * 1.5)) hi += 1;
    if (Math.abs(c.low - l) <= tol || (c.low <= l + tol && c.low >= l - tol * 1.5)) lo += 1;
  }
  return { hi, lo };
}

