export type SwingPoint = CandlePivot & { kind: 'high' | 'low' };

/** 최근 구간 ATR — 스윙 유의성·터치 허용오차 기준 */
function recentAtr(candles: Candle[], period = 14): number {
  const n = candles.length;
  if (n < 3) return 0;
  const start = Math.max(1, n - period);
  let sum = 0;
  let cnt = 0;
  for (let i = start; i < n; i++) {
    const c = candles[i]!;
    const p = candles[i - 1]!;
    sum += Math.max(c.high - c.low, Math.abs(c.high - p.close), Math.abs(c.low - p.close));
    cnt += 1;
  }
  return cnt ? sum / cnt : 0;
}

/**
 * 프랙탈 피벗 → 고·저 교대 스윙 시퀀스.
 * 같은 방향이 연속이면 더 극단만 남기고, ATR 미만 잔파동은 스윙으로 인정하지 않는다.
 */
function buildSwingSequence(
  candles: Candle[],
  timeframe: string,
  lookback: number,
  atr: number
): SwingPoint[] {
  const { L, R } = mergedDesk4hReferencePivotWindowForTf(timeframe);
  const start = Math.max(L, candles.length - lookback);
  const raw: SwingPoint[] = [];
  for (let i = start; i < candles.length - R; i++) {
    if (i - L < 0) continue;
    const c = candles[i]!;
    if (pivotHigh(candles, i, L, R)) {
      raw.push({ i, price: c.high, time: Number(c.time), kind: 'high' });
    }
    if (pivotLow(candles, i, L, R)) {
      raw.push({ i, price: c.low, time: Number(c.time), kind: 'low' });
    }
  }
  raw.sort((a, b) => a.i - b.i);

  const minLeg = atr > 0 ? atr * 0.55 : 0;
  const seq: SwingPoint[] = [];
  for (const p of raw) {
    const last = seq[seq.length - 1];
    if (!last) {
      seq.push(p);
      continue;
    }
    if (last.kind === p.kind) {
      const moreExtreme = p.kind === 'high' ? p.price > last.price : p.price < last.price;
      if (moreExtreme) seq[seq.length - 1] = p;
      continue;
    }
    if (Math.abs(p.price - last.price) < minLeg) continue;
    seq.push(p);
  }
  return seq;
}

/** 스윙 시퀀스에서 최근 n개의 고 또는 저 */
function lastSwings(seq: SwingPoint[], kind: 'high' | 'low', count: number): SwingPoint[] {
  const all = seq.filter((s) => s.kind === kind);
  return all.slice(Math.max(0, all.length - count));
}

type Rail = {
  p1: SwingPoint;
  p2: SwingPoint;
  slope: number;
  touches: number;
  /** 레일 바깥으로 삐져나간 총량 (ATR 배수) */
  violation: number;
  score: number;
  at: (i: number) => number;
};

function railAt(p1: CandlePivot, slope: number, i: number): number {
  return p1.price + slope * (i - p1.i);
}

/**
 * 스윙 앵커쌍 중 실제로 가격을 담는 레일 선택.
 * 터치가 많고 위반(뚫고 나간 양)이 적은 쌍이 이긴다.
 */
function pickRail(
  candles: Candle[],
  pts: SwingPoint[],
  side: 'high' | 'low',
  minBars: number,
  tol: number,
  atr: number,
  iEnd: number
): Rail | null {
  if (pts.length < 2) return null;
  const atrSafe = Math.max(atr, 1e-9);
  let best: Rail | null = null;

  for (let a = 0; a < pts.length - 1; a++) {
    for (let b = a + 1; b < pts.length; b++) {
      const p1 = pts[a]!;
      const p2 = pts[b]!;
      const span = p2.i - p1.i;
      if (span < minBars) continue;
      const slope = (p2.price - p1.price) / span;

      let violation = 0;
      let touches = 0;
      let lastTouch = -99;
      for (let i = p1.i; i <= iEnd; i++) {
        const c = candles[i];
        if (!c) continue;
        const line = railAt(p1, slope, i);
        const out = side === 'high' ? c.high - line : line - c.low;
        if (out > tol) {
          violation += out;
        } else if (out > -tol && i - lastTouch >= 2) {
          touches += 1;
          lastTouch = i;
        }
      }

      const spanScore = Math.min(1.5, span / (minBars * 2));
      const recency = 1 + (p2.i / Math.max(1, iEnd)) * 0.4;
      const score = (touches * 1.6 + spanScore * 4) * recency - (violation / atrSafe) * 1.2;
      if (!best || score > best.score) {
        best = {
          p1,
          p2,
          slope,
          touches,
          violation: violation / atrSafe,
          score,
          at: (i: number) => railAt(p1, slope, i),
        };
      }
    }
  }
  return best;
}

/** 기준 레일에서 가장 멀리 떨어진 반대편 스윙 — 평행 레일 앵커 */
function farthestOffset(
  pts: SwingPoint[],
  baseAt: (i: number) => number,
  side: 'above' | 'below'
): { offset: number; anchor: SwingPoint } | null {
  let best: { offset: number; anchor: SwingPoint } | null = null;
  for (const p of pts) {
    const d = side === 'above' ? p.price - baseAt(p.i) : baseAt(p.i) - p.price;
    if (!Number.isFinite(d) || d <= 0) continue;
    if (!best || d > best.offset) best = { offset: d, anchor: p };
  }
  return best;
}

/** 최종 상·하 레일 기준 터치 재집계 (연속봉 중복 제외) */
function countRailTouches(
  candles: Candle[],
  iStart: number,
  iEnd: number,
  upFn: (i: number) => number,
  loFn: (i: number) => number,
  tol: number
): { hi: number; lo: number } {
  let hi = 0;
  let lo = 0;
  let lastHi = -99;
  let lastLo = -99;
  for (let i = Math.max(0, iStart); i <= iEnd; i++) {
    const c = candles[i];
    if (!c) continue;
    if (Math.abs(c.high - upFn(i)) <= tol && i - lastHi >= 2) {
      hi += 1;
      lastHi = i;
    }
    if (Math.abs(c.low - loFn(i)) <= tol && i - lastLo >= 2) {
      lo += 1;
      lastLo = i;
    }
  }
  return { hi, lo };
}

