  moneyCaptionKo?: string | null;
  primary: boolean;
  /** 보조 채널 라벨 숨김 */
  hideBandLabel?: boolean;
  style: MergedDeskRbStyle;
}): ChannelBuild | null {
  const { candles, highs, lows, idPrefix, horizon, horizonKo, minBars, widthPct, primary, style } =
    params;
  const hiPair = pickBestPair(highs, minBars);
  const loPair = pickBestPair(lows, minBars);
  if (!hiPair || candles.length < 8) return null;

  const [h1, h2] = hiPair;
  const slope = (h2.price - h1.price) / Math.max(1, h2.i - h1.i);
  const descending = slope < 0;
  const iEnd = candles.length - 1;
  const tEnd = Number(candles[iEnd]!.time);
  const midPx = Math.abs(h2.price) || 1;
  const slopePct = (slope / midPx) * 100;

  /** 저점 거리로 폭 + 고점 잔차 보정 */
  const dists: number[] = [];
  for (const lo of lows) {
    if (lo.i < h1.i) continue;
    const up = lineAt(h1, h2, lo.i);
    const d = up - lo.price;
    if (d > 0) dists.push(d);
  }
  dists.sort((a, b) => a - b);
  let width =
    dists.length > 0
      ? dists[Math.min(dists.length - 1, Math.floor(dists.length * widthPct))]!
      : midPx * 0.02;
  if (!(width > 0) && loPair) {
    width = Math.max(
      Math.abs(lineAt(h1, h2, loPair[0].i) - loPair[0].price),
      Math.abs(lineAt(h1, h2, loPair[1].i) - loPair[1].price),
      midPx * 0.012
    );
  }
  if (!(width > 0)) width = midPx * 0.018;
  /** 과도하게 넓은 채널 클램프 */
