/**
 * 통합·분석 — 파란·빨간 띠 눌림 진입 zone.
 *
 * 채널(스윙 기준) 되돌림 구간을 타점 zone으로 만들고,
 * 기관밴드 방향 · $$$$ 머니존 겹침 · 로켓 방향 · 거래량(흡수·RVOL·테이커)을
 * 합류 점수로 합산한다. 확정 수익·승률이 아니라 조건부 근거 점수다.
 */
import type { Candle, OverlayItem } from '@/types';
import type { AtlasPulsePriceLine } from '@/lib/monthDeskAtlasPulseDesk';
import type { MergedDeskChannelGeom } from '@/lib/mergedDeskBlueRedChannels';
import type { MonthDeskMoneyZone, MonthDeskMoneyZoneHud } from '@/lib/monthDeskMoneyZone';
import { mergedWorkCandles } from '@/lib/mergedAnalysisOverlayTimes';
import {
  candleBodyRatioOfRange,
  sanitizeChartCandlesForSeries,
  smaTotalVolumeAt,
  volumeCandleDirectionBias,
} from '@/lib/volumeHistogramIntelligence';
import {
  computeInstitutionalSuperTrendMeta,
  getLastInstitutionalBandEdges,
} from '@/lib/institutionalSuperBand';

export type ChannelPullbackSide = 'LONG' | 'SHORT';
export type ChannelPullbackStatus = 'WAIT' | 'NEAR' | 'READY' | 'INVALID';

export type ChannelPullbackReason = {
  ko: string;
  points: number;
  ok: boolean;
};

export type MergedDeskChannelPullbackEntry = {
  side: ChannelPullbackSide;
  horizonKo: string;
  /** 눌림 타점 zone */
  zoneTop: number;
  zoneBot: number;
  zoneMid: number;
  entry: number;
  stopLoss: number;
  tp1: number;
  tp2: number;
  tp3: number;
  invalidation: number;
  rr: number;
  /** 0~100 합류 점수 */
  score: number;
  grade: 'A' | 'B' | 'C';
  status: ChannelPullbackStatus;
  statusKo: string;
  labelKo: string;
  tooltipKo: string;
  reasons: ChannelPullbackReason[];
  /** 현재가에서 zone 중심까지 ATR 배수 */
  distanceAtr: number;
  /** zone 좌측 시작 시각(되돌림 시작 봉) */
  timeStart: number;
  timeEnd: number;
};

export type MergedDeskChannelPullbackEntryPack = {
  overlays: OverlayItem[];
  priceLines: AtlasPulsePriceLine[];
  entry: MergedDeskChannelPullbackEntry | null;
  summaryKo: string;
};

const EMPTY_PACK: MergedDeskChannelPullbackEntryPack = {
  overlays: [],
  priceLines: [],
  entry: null,
  summaryKo: '눌림 타점 — 근거 부족',
};

function work(candles: Candle[], timeframe: string): Candle[] {
  return sanitizeChartCandlesForSeries(mergedWorkCandles(candles, timeframe), timeframe);
}

function atrOf(candles: Candle[], period = 14): number {
  const n = candles.length;
  if (n < 3) return 0;
  let sum = 0;
  let cnt = 0;
  for (let i = Math.max(1, n - period); i < n; i++) {
    const c = candles[i]!;
    const p = candles[i - 1]!;
    sum += Math.max(c.high - c.low, Math.abs(c.high - p.close), Math.abs(c.low - p.close));
    cnt += 1;
  }
  return cnt ? sum / cnt : 0;
}

function fmtPrice(p: number): string {
  if (!Number.isFinite(p) || p <= 0) return '—';
  if (p >= 1000) return p.toFixed(0);
  if (p >= 1) return p.toFixed(1);
  return p.toFixed(4);
}

/** 결정 채널 — primary 우선, 없으면 품질 최고 */
function pickDecisionGeom(geoms: MergedDeskChannelGeom[]): MergedDeskChannelGeom | null {
  if (!geoms.length) return null;
  const primary = geoms.find((g) => g.primary);
  if (primary) return primary;
  return [...geoms].sort((a, b) => b.quality - a.quality)[0] ?? null;
}

/** zone과 겹치는 같은 방향 머니 풀 */
function overlappingMoneyPool(
  hud: MonthDeskMoneyZoneHud | null | undefined,
  side: ChannelPullbackSide,
  top: number,
  bot: number,
  atr: number
): { pool: MonthDeskMoneyZone; overlap: boolean } | null {
  if (!hud) return null;
  const pools = [hud.long, hud.short, ...(hud.pools ?? [])].filter(
    (p): p is MonthDeskMoneyZone => !!p && p.side === side
  );
  let near: { pool: MonthDeskMoneyZone; overlap: boolean } | null = null;
  for (const p of pools) {
    const pTop = Math.max(p.priceTop, p.priceBot);
    const pBot = Math.min(p.priceTop, p.priceBot);
    if (pTop >= bot && pBot <= top) return { pool: p, overlap: true };
    const gap = pBot > top ? pBot - top : bot - pTop;
    if (atr > 0 && gap <= atr * 1.5 && !near) near = { pool: p, overlap: false };
  }
  return near;
}

/** 최근 봉에서 zone 근처 거래량 근거 (흡수·RVOL·테이커) */
function volumeEvidence(
  candles: Candle[],
  side: ChannelPullbackSide,
  top: number,
  bot: number,
  lookback = 14
): { rvol: number; absorption: boolean; takerAligned: boolean } {
  const n = candles.length;
  let rvolMax = 0;
  let absorption = false;
  let takerAligned = false;
  for (let i = Math.max(1, n - lookback); i < n; i++) {
    const c = candles[i];
    if (!c) continue;
    /** zone에 닿은 봉만 근거로 인정 */
    if (c.low > top || c.high < bot) continue;
    const sma = smaTotalVolumeAt(candles, i, 20);
    const rvol = sma > 0 ? Math.max(0, Number(c.volume) || 0) / sma : 0;
    if (rvol > rvolMax) rvolMax = rvol;
    const bodyRatio = candleBodyRatioOfRange(c);
    if (rvol >= 1.35 && bodyRatio != null && bodyRatio <= 0.24) absorption = true;
    const vol = Math.max(0, Number(c.volume) || 0);
    const tb = Number((c as Candle & { takerBuyBaseVolume?: number }).takerBuyBaseVolume);
    if (vol > 0 && Number.isFinite(tb)) {
      const ratio = tb / vol;
      if (side === 'LONG' ? ratio >= 0.6 : ratio <= 0.4) takerAligned = true;
    } else if (volumeCandleDirectionBias(c) === (side === 'LONG' ? 'long' : 'short')) {
      takerAligned = true;
    }
  }
  return { rvol: rvolMax, absorption, takerAligned };
}

/** 되돌림이 시작된 봉 — zone에 마지막으로 닿은 지점, 없으면 최근 구간 */
function pullbackStartTime(
  candles: Candle[],
  top: number,
  bot: number,
  fallbackBars: number
): number {
  const n = candles.length;
  for (let i = n - 1; i >= Math.max(0, n - 80); i--) {
    const c = candles[i];
    if (!c) continue;
    if (c.low <= top && c.high >= bot) return Number(c.time);
  }
  const idx = Math.max(0, n - 1 - fallbackBars);
  return Number(candles[idx]?.time ?? candles[0]?.time ?? 0);
}

export function buildMergedDeskChannelPullbackEntryPack(params: {
  candles: Candle[];
  timeframe: string;
  geoms: MergedDeskChannelGeom[];
  moneyHud?: MonthDeskMoneyZoneHud | null;
  rocketDirection?: ChannelPullbackSide | null;
}): MergedDeskChannelPullbackEntryPack {
  const { timeframe, geoms, moneyHud, rocketDirection } = params;
  const safe = work(params.candles, timeframe);
  if (safe.length < 30) return EMPTY_PACK;

  const geom = pickDecisionGeom(geoms);
  if (!geom) return EMPTY_PACK;

  const iEnd = safe.length - 1;
  const close = Number(safe[iEnd]!.close);
  const atr = atrOf(safe, 14);
  if (!(close > 0) || !(atr > 0)) return EMPTY_PACK;

  const side: ChannelPullbackSide = geom.descending ? 'SHORT' : 'LONG';
  const width = Math.max(geom.width, atr * 0.8);
  const rail = side === 'LONG' ? geom.tipLower : geom.tipUpper;

  /** 되돌림 타점 폭 — 채널 폭의 일부, ATR로 하한 */
  const band = Math.max(atr * 0.45, Math.min(width * 0.3, atr * 1.35));
  const zoneTop = side === 'LONG' ? rail + band * 0.9 : rail + band * 0.45;
  const zoneBot = side === 'LONG' ? rail - band * 0.45 : rail - band * 0.9;
  const zoneMid = (zoneTop + zoneBot) / 2;

  const entry = zoneMid;
  const slPad = Math.max(atr * 0.7, width * 0.12);
  const stopLoss = side === 'LONG' ? zoneBot - slPad : zoneTop + slPad;
  const invalidation =
    side === 'LONG' ? geom.tipLower - width * 0.35 : geom.tipUpper + width * 0.35;

  const tp1 = geom.tipMid;
  const tp2 = side === 'LONG' ? geom.tipUpper : geom.tipLower;
  const tp3 = side === 'LONG' ? geom.tipUpper + width * 0.6 : geom.tipLower - width * 0.6;

  const risk = Math.abs(entry - stopLoss);
  const reward = Math.abs(tp2 - entry);
  const rr = risk > 0 ? reward / risk : 0;

  /** 근거 합산 */
  const reasons: ChannelPullbackReason[] = [];
  let score = 0;

  const qPts = Math.round((Math.max(0, Math.min(96, geom.quality)) / 96) * 22);
  score += qPts;
  reasons.push({
    ko: `채널 품질 ${geom.quality} · 터치 상${geom.touchHigh}/하${geom.touchLow}`,
    points: qPts,
    ok: geom.quality >= 55,
  });

  const containment = geom.containment ?? 0;
  const structOk = containment >= 0.78 && geom.touchHigh >= 2 && geom.touchLow >= 2;
  const structPts = structOk ? 10 : containment >= 0.6 ? 5 : 0;
  score += structPts;
  reasons.push({
    ko: `구조 포함률 ${(containment * 100).toFixed(0)}%`,
    points: structPts,
    ok: structOk,
  });

  const bandMeta = computeInstitutionalSuperTrendMeta(safe);
  const bandEdges = getLastInstitutionalBandEdges(safe);
  const bandDir = bandMeta?.lastDir === 'long' ? 'LONG' : bandMeta?.lastDir === 'short' ? 'SHORT' : null;
  const bandAligned = bandDir === side;
  let bandPts = bandAligned ? 16 : bandDir ? -8 : 0;
  const bandEdgeInZone =
    !!bandEdges &&
    ((bandEdges.lower <= zoneTop && bandEdges.lower >= zoneBot) ||
      (bandEdges.upper <= zoneTop && bandEdges.upper >= zoneBot));
  if (bandAligned && bandEdgeInZone) bandPts += 6;
  score += bandPts;
  reasons.push({
    ko: bandDir
      ? `기관밴드 ${bandDir === 'LONG' ? '롱' : '숏'}${bandAligned ? ' 정렬' : ' 역행'}${bandEdgeInZone ? ' · 밴드선 zone 내' : ''}`
      : '기관밴드 판정 없음',
    points: bandPts,
    ok: bandAligned,
  });

  const money = overlappingMoneyPool(moneyHud, side, zoneTop, zoneBot, atr);
  const moneyPts = money?.overlap ? 16 : money ? 8 : 0;
  score += moneyPts;
  reasons.push({
    ko: money
      ? `$$$$ ${side === 'LONG' ? '롱' : '숏'}존 ${money.overlap ? '겹침' : '근접'} · ${money.pool.headlineKo}`
      : '$$$$ 존 겹침 없음',
    points: moneyPts,
    ok: !!money?.overlap,
  });

  const rocketOk = rocketDirection === side;
  const rocketPts = rocketOk ? 10 : rocketDirection ? -5 : 0;
  score += rocketPts;
  reasons.push({
    ko: rocketDirection
      ? `로켓 ${rocketDirection === 'LONG' ? '🚀 롱' : '📉 숏'}${rocketOk ? ' 일치' : ' 반대'}`
      : '로켓 신호 없음',
    points: rocketPts,
    ok: rocketOk,
  });

  const vol = volumeEvidence(safe, side, zoneTop, zoneBot);
  let volPts = 0;
  if (vol.absorption) volPts += 10;
  if (vol.rvol >= 1.8) volPts += 4;
  if (vol.takerAligned) volPts += 4;
  score += volPts;
  reasons.push({
    ko: vol.absorption
      ? `zone 흡수 확인 · RVOL ${vol.rvol.toFixed(1)}×${vol.takerAligned ? ' · 테이커 일치' : ''}`
      : vol.rvol > 0
        ? `zone 거래량 RVOL ${vol.rvol.toFixed(1)}×`
        : 'zone 접촉 거래량 없음',
    points: volPts,
    ok: vol.absorption || vol.rvol >= 1.8,
  });

  const brokeAgainst =
    (side === 'LONG' && geom.breakout === 'down') || (side === 'SHORT' && geom.breakout === 'up');
  if (brokeAgainst) {
    const pen = Math.min(25, 10 + (geom.breakoutBars ?? 0) * 5);
    score -= pen;
    reasons.push({
      ko: `채널 ${side === 'LONG' ? '하단' : '상단'} 이탈 ${geom.breakoutBars ?? 0}봉 — 무효화 확인 필요`,
      points: -pen,
      ok: false,
    });
  }

  score = Math.max(0, Math.min(100, Math.round(score)));

  const distanceAtr = Math.abs(close - zoneMid) / atr;
  let status: ChannelPullbackStatus;
  if (brokeAgainst && (geom.breakoutBars ?? 0) >= 2) status = 'INVALID';
  else if (close <= zoneTop && close >= zoneBot) status = 'READY';
  else if (distanceAtr <= 1.5) status = 'NEAR';
  else status = 'WAIT';

  const statusKo =
    status === 'READY'
      ? '눌림 도달'
      : status === 'NEAR'
        ? '접근'
        : status === 'INVALID'
          ? '무효'
          : '대기';
  const grade: 'A' | 'B' | 'C' = score >= 72 ? 'A' : score >= 52 ? 'B' : 'C';
  const sideKo = side === 'LONG' ? '롱' : '숏';
  const labelKo = `눌림${sideKo}·${grade}${score}`;

  const timeEnd = Number(safe[iEnd]!.time);
  const timeStart = pullbackStartTime(safe, zoneTop, zoneBot, 26);

  const tooltipKo = [
    `${geom.horizonKo}채널 ${side === 'LONG' ? '상승' : '하락'} — 눌림 ${sideKo} 타점`,
    `상태 ${statusKo} · 합류 ${score}점(${grade}) · 현재가에서 ${distanceAtr.toFixed(1)}ATR`,
    `zone ${fmtPrice(zoneBot)}~${fmtPrice(zoneTop)}`,
    `E ${fmtPrice(entry)} · SL ${fmtPrice(stopLoss)} · TP1 ${fmtPrice(tp1)} · TP2 ${fmtPrice(tp2)}`,
    `무효 ${fmtPrice(invalidation)} · R:R ≈ ${rr.toFixed(2)}`,
    '',
    ...reasons.map((r) => `${r.ok ? '○' : '×'} ${r.ko} (${r.points >= 0 ? '+' : ''}${r.points})`),
    '',
    '조건부 근거 점수 — 확정 수익·승률 아님. 마감 확인 후 대응.',
  ].join('\n');

  const entryPack: MergedDeskChannelPullbackEntry = {
    side,
    horizonKo: geom.horizonKo,
    zoneTop,
    zoneBot,
    zoneMid,
    entry,
    stopLoss,
    tp1,
    tp2,
    tp3,
    invalidation,
    rr,
    score,
    grade,
    status,
    statusKo,
    labelKo,
    tooltipKo,
    reasons,
    distanceAtr,
    timeStart,
    timeEnd,
  };

  const isLong = side === 'LONG';
  const faceHex = isLong ? '#22C55E' : '#EF4444';
  const alpha = status === 'READY' ? 0.3 : status === 'NEAR' ? 0.22 : 0.14;
  const fill = isLong
    ? `rgba(34,197,94,${alpha})`
    : `rgba(239,68,68,${alpha})`;

  const zoneOverlay: OverlayItem = {
    id: 'merged-desk-rb-pullback-entry-zone',
    kind: 'zone',
    label: labelKo,
    zoneFaceBase: labelKo,
    zoneFaceSignal: statusKo,
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 0,
    time1: timeStart,
    time2: timeEnd,
    price1: zoneTop,
    price2: zoneBot,
    confidence: Math.max(20, Math.min(96, score)),
    color: fill,
    category: 'zones',
    structureBias: isLong ? 'bullish' : 'bearish',
    zoneFillPreserve: true,
    zonePulse: status === 'READY',
    overlayZoneExtraClass: [
      'merged-desk-rb-pullback-entry',
      'merged-desk-rb-channel',
      isLong ? 'merged-desk-rb-pullback-long' : 'merged-desk-rb-pullback-short',
      `merged-desk-rb-pullback-${status.toLowerCase()}`,
      'merged-desk-zone-caption-clean',
    ].join(' '),
    labelTooltip: tooltipKo,
    lineLabelColor: faceHex,
    labelBackgroundColor: isLong ? 'rgba(6,78,59,0.92)' : 'rgba(127,29,29,0.92)',
    labelTextColor: '#f8fafc',
  };

  const priceLines: AtlasPulsePriceLine[] = [
    {
      price: entry,
      color: faceHex,
      title: `눌림진입E ${labelKo}`,
      lineWidth: 2,
      lineStyle: 'solid',
      axisLabel: true,
    },
    {
      price: stopLoss,
      color: '#F87171',
      title: '눌림손절SL',
      lineWidth: 1,
      lineStyle: 'dashed',
      axisLabel: true,
    },
    {
      price: tp1,
      color: '#38BDF8',
      title: '눌림익절TP1',
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    },
    {
      price: tp2,
      color: '#34D399',
      title: '눌림익절TP2',
      lineWidth: 1,
      lineStyle: 'dotted',
      axisLabel: true,
    },
    {
      price: invalidation,
      color: '#FBBF24',
      title: '눌림무효',
      lineWidth: 1,
      lineStyle: 'dashed',
      axisLabel: true,
    },
  ].filter((l) => Number.isFinite(l.price) && l.price > 0);

  return {
    overlays: [zoneOverlay],
    priceLines,
    entry: entryPack,
    summaryKo: `눌림 ${sideKo} ${statusKo} · ${grade}${score} · zone ${fmtPrice(zoneBot)}~${fmtPrice(zoneTop)} · R:R≈${rr.toFixed(2)}`,
  };
}

input.new_string:
/** 파란·빨간 띠 — 최소 품질(이하 채널 숨김, 0=전부) */
chartMergedDeskRbMinQuality: number;
/** 파란·빨간 띠 눌림 진입 zone (기관밴드·$$$$·로켓·거래량 합류) */
chartMergedDeskRbPullbackEntryEnabled: boolean;
/** 눌림 타점 — E/SL/TP/무효 가격선 표시 */
chartMergedDeskRbPullbackLinesEnabled: boolean;
/** 눌림 타점 — 이 점수 미만이면 작도하지 않음 */
chartMergedDeskRbPullbackMinScore: number;

input.old_string:
const liveRb =
  fromPackRb.length > 0
    ? fromPackRb
    : buildMergedDeskChannelMoneyEdgePack(deskCandles, timeframe).overlays;
const blueRedChannelLayers = blueRedChannelsOn
  ? applyMergedDeskRbStyleToOverlays(liveRb)
  : [];

input.new_string:
const rbLive =
  fromPackRb.length > 0 && !pullbackEntryOn
    ? null
    : buildMergedDeskChannelMoneyEdgePack(deskCandles, timeframe);
const liveRb = fromPackRb.length > 0 ? fromPackRb : (rbLive?.overlays ?? []);
const blueRedChannelLayers = blueRedChannelsOn
  ? applyMergedDeskRbStyleToOverlays(liveRb)
  : [];

/** 눌림 타점 — 채널 되돌림 + 기관밴드·$$$$·로켓·거래량 합류 */
const pullbackPack =
  pullbackEntryOn && rbLive?.geoms.length
    ? buildMergedDeskChannelPullbackEntryPack({
        candles: deskCandles,
        timeframe,
        geoms: rbLive.geoms,
        moneyHud: detectMonthDeskMoneyZones(deskCandles, timeframe),
        rocketDirection: structureRocketDirectionOnLastCandle(
          analysis?.structureRocketSignals,
          deskCandles,
          timeframe
        ),
      })
    : null;
const pullbackLayers =
  pullbackPack?.entry && pullbackPack.entry.score >= pullbackMinScore
    ? pullbackPack.overlays
    : [];

import { applyMergedDeskRbStyleToOverlays } from '@/lib/mergedDeskBlueRedChannels';
import { buildMergedDeskChannelPullbackEntryPack } from '@/lib/mergedDeskChannelPullbackEntry';
import { detectMonthDeskMoneyZones } from '@/lib/monthDeskMoneyZone';
import { structureRocketDirectionOnLastCandle } from '@/lib/mtfStructureRocket';

