input.old_string:
type Rail = {
  p1: SwingPoint;
  p2: SwingPoint;
  slope: number;
  touches: number;
  /** 레일 바깥으로 삐져나간 총량 (ATR 배수) */
  violation: number;
  score: number;
  at: (i: number) => number;
};

function railAt(p1: CandlePivot, slope: number, i: number): number {
  return p1.price + slope * (i - p1.i);
}

/**
 * 스윙 앵커쌍 중 실제로 가격을 담는 레일 선택.
 * 터치가 많고 위반(뚫고 나간 양)이 적은 쌍이 이긴다.
 */
function pickRail(
  candles: Candle[],
  pts: SwingPoint[],
  side: 'high' | 'low',
  minBars: number,
  tol: number,
  atr: number,
  iEnd: number
): Rail | null {
  if (pts.length < 2) return null;
  const atrSafe = Math.max(atr, 1e-9);
  let best: Rail | null = null;

  for (let a = 0; a < pts.length - 1; a++) {
    for (let b = a + 1; b < pts.length; b++) {
      const p1 = pts[a]!;
      const p2 = pts[b]!;
      const span = p2.i - p1.i;
      if (span < minBars) continue;
      const slope = (p2.price - p1.price) / span;

      let violation = 0;
      let touches = 0;
      let lastTouch = -99;
      for (let i = p1.i; i <= iEnd; i++) {
        const c = candles[i];
        if (!c) continue;
        const line = railAt(p1, slope, i);
        const out = side === 'high' ? c.high - line : line - c.low;
        if (out > tol) {
          violation += out;
        } else if (out > -tol && i - lastTouch >= 2) {
          touches += 1;
          lastTouch = i;
        }
      }

      const spanScore = Math.min(1.5, span / (minBars * 2));
      const recency = 1 + (p2.i / Math.max(1, iEnd)) * 0.4;
      const score = (touches * 1.6 + spanScore * 4) * recency - (violation / atrSafe) * 1.2;
      if (!best || score > best.score) {
        best = {
          p1,
          p2,
          slope,
          touches,
          violation: violation / atrSafe,
          score,
          at: (i: number) => railAt(p1, slope, i),
        };
      }
    }
  }
  return best;
}

/** 기준 레일에서 가장 멀리 떨어진 반대편 스윙 — 평행 레일 앵커 */
function farthestOffset(
  pts: SwingPoint[],
  baseAt: (i: number) => number,
  side: 'above' | 'below'
): { offset: number; anchor: SwingPoint } | null {
  let best: { offset: number; anchor: SwingPoint } | null = null;
  for (const p of pts) {
    const d = side === 'above' ? p.price - baseAt(p.i) : baseAt(p.i) - p.price;
    if (!Number.isFinite(d) || d <= 0) continue;
    if (!best || d > best.offset) best = { offset: d, anchor: p };
  }
  return best;
}

/** 최종 상·하 레일 기준 터치 재집계 (연속봉 중복 제외) */
function countRailTouches(
  candles: Candle[],
  iStart: number,
  iEnd: number,
  upFn: (i: number) => number,
  loFn: (i: number) => number,
  tol: number
): { hi: number; lo: number } {
  let hi = 0;
  let lo = 0;
  let lastHi = -99;
  let lastLo = -99;
  for (let i = Math.max(0, iStart); i <= iEnd; i++) {
    const c = candles[i];
    if (!c) continue;
    if (Math.abs(c.high - upFn(i)) <= tol && i - lastHi >= 2) {
      hi += 1;
      lastHi = i;
    }
    if (Math.abs(c.low - loFn(i)) <= tol && i - lastLo >= 2) {
      lo += 1;
      lastLo = i;
    }
  }
  return { hi, lo };
}

