input.contents:
/**
 * 파란·빨간 띠 — 핵심 돌파/안착 세트.
 * 돌파해야 할 자리 · 돌파 후 안착 자리 · 캔들 색 · 봉 위아래 이모티콘.
 * 확정 수익·승률 보장 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import type { UTCTimestamp } from 'lightweight-charts';
import type { AtlasPulseMarker, AtlasPulsePriceLine } from '@/lib/monthDeskAtlasPulseDesk';
import type { MonthDeskSettleCandleCell } from '@/lib/monthDeskSettleCandlePaint';
import {
  buildMergedDeskChannelMoneyEdgePack,
  type MergedDeskChannelEdgeRead,
  type MergedDeskChannelMoneyPlan,
  type MergedDeskChannelPrimaryDecision,
} from '@/lib/mergedDeskChannelMoneyEdge';
import type { MergedDeskChannelGeom } from '@/lib/mergedDeskBlueRedChannels';
import { loadSettings } from '@/lib/settings';

export type MergedDeskRbCoreBreakSet = {
  overlays: OverlayItem[];
  priceLines: AtlasPulsePriceLine[];
  markers: AtlasPulseMarker[];
  settlePaint: Map<number, MonthDeskSettleCandleCell>;
  summaryKo: string;
};

function atrApprox(candles: Candle[]): number {
  const n = candles.length;
  if (n < 5) {
    const c = Number(candles[n - 1]?.close) || 0;
    return c > 0 ? c * 0.008 : 0;
  }
  const start = Math.max(1, n - 14);
  let sum = 0;
  let cnt = 0;
  for (let i = start; i < n; i++) {
    const h = Number(candles[i]!.high);
    const l = Number(candles[i]!.low);
    const pc = Number(candles[i - 1]!.close);
    if (![h, l, pc].every(Number.isFinite)) continue;
    sum += Math.max(h - l, Math.abs(h - pc), Math.abs(l - pc));
    cnt += 1;
  }
  if (cnt <= 0) {
    const c = Number(candles[n - 1]?.close) || 0;
    return c > 0 ? c * 0.008 : 0;
  }
  return sum / cnt;
}

function fmt(p: number): string {
  if (!(p > 0) || !Number.isFinite(p)) return '—';
  if (p >= 1000) return p.toFixed(0);
  if (p >= 1) return p.toFixed(1);
  return p.toFixed(3);
}

type CorePhase = 'pre' | 'break' | 'settle' | 'confirm' | 'fail';

function phaseFromEdge(
  stateKo: string,
  settle: 'none' | 'attempt' | 'settled' | 'failed'
): CorePhase | null {
  if (settle === 'failed' || stateKo === '돌파실패') return 'fail';
  if (settle === 'settled' || stateKo === '안착확정') return 'confirm';
  if (settle === 'attempt' || stateKo === '돌파') return 'break';
  if (stateKo === '돌파가능') return 'pre';
  return null;
}

/** 돌파 이후 봉들을 훑어 돌파봉·안착봉·실패봉 인덱스를 찾는다 */
function scanBreakBars(
  candles: Candle[],
  level: number,
  side: 'above' | 'below',
  buf: number,
  look = 12
): { breakIdx: number; outsideIdxs: number[]; failIdx: number } {
  const n = candles.length;
  const outside = (c: number) => (side === 'above' ? c > level + buf : c < level - buf);
  const insideHard = (c: number) =>
    side === 'above' ? c < level - buf * 0.35 : c > level + buf * 0.35;

  let breakIdx = -1;
  const outsideIdxs: number[] = [];
  let failIdx = -1;
  const from = Math.max(1, n - look);
  for (let i = from; i < n; i++) {
    const c = Number(candles[i]?.close);
    if (!Number.isFinite(c)) continue;
    if (outside(c)) {
      if (breakIdx < 0) breakIdx = i;
      outsideIdxs.push(i);
    } else if (breakIdx >= 0 && insideHard(c) && failIdx < 0) {
      failIdx = i;
    }
  }
  return { breakIdx, outsideIdxs, failIdx };
}

function putPaint(
  m: Map<number, MonthDeskSettleCandleCell>,
  candles: Candle[],
  idx: number,
  phase: MonthDeskSettleCandlePhase,
  bias: 'bullish' | 'bearish'
) {
  if (idx < 0 || idx >= candles.length) return;
  const t = Number(candles[idx]?.time);
  if (!Number.isFinite(t)) return;
  const rank = (p: MonthDeskSettleCandlePhase) =>
    p === 'failed'
      ? 0
      : p === 'breakoutWeak'
        ? 1
        : p === 'breakout'
          ? 2
          : p === 'retest'
            ? 3
            : p === 'settling'
              ? 4
              : 5;
  const prev = m.get(t);
  if (!prev || rank(phase) >= rank(prev.phase)) m.set(t, { phase, bias });
}

type MonthDeskSettleCandlePhase = MonthDeskSettleCandleCell['phase'];

function emojiFor(phase: CorePhase, isLong: boolean): { text: string; color: string; position: 'aboveBar' | 'belowBar' } {
  switch (phase) {
    case 'pre':
      return {
        text: isLong ? '⚡↑' : '⚡↓',
        color: '#FDE047',
        position: isLong ? 'aboveBar' : 'belowBar',
      };
    case 'break':
      return {
        text: isLong ? '🚀' : '📉',
        color: isLong ? '#FACC15' : '#FB923C',
        position: isLong ? 'aboveBar' : 'belowBar',
      };
    case 'settle':
      return {
        text: '◆',
        color: '#F97316',
        position: isLong ? 'belowBar' : 'aboveBar',
      };
    case 'confirm':
      return {
        text: isLong ? '✅' : '✅',
        color: isLong ? '#4ADE80' : '#FB7185',
        position: isLong ? 'belowBar' : 'aboveBar',
      };
    case 'fail':
    default:
      return {
        text: '❌',
        color: '#94A3B8',
        position: isLong ? 'aboveBar' : 'belowBar',
      };
  }
}

/**
 * 핵심 zone · 가격선 · 캔들색 · 이모티콘 마커를 한 세트로 만든다.
 * plan/primary가 없으면 빈 세트.
 */
export function buildMergedDeskRbCoreBreakSet(params: {
  candles: Candle[];
  timeframe: string;
  geoms: MergedDeskChannelGeom[];
  edgeReads: MergedDeskChannelEdgeRead[];
  plan: MergedDeskChannelMoneyPlan | null;
  primary: MergedDeskChannelPrimaryDecision | null;
  /** zone / 선 / 마커 / 캔들색 각각 ON */
  showZones?: boolean;
  showMarkers?: boolean;
  showCandlePaint?: boolean;
}): MergedDeskRbCoreBreakSet {
  const empty: MergedDeskRbCoreBreakSet = {
    overlays: [],
    priceLines: [],
    markers: [],
    settlePaint: new Map(),
    summaryKo: '',
  };
  const { candles, plan, primary, geoms, edgeReads } = params;
  const n = candles.length;
  if (n < 8 || !primary || primary.direction === 'NEUTRAL') return empty;

  const showZones = params.showZones !== false;
  const showMarkers = params.showMarkers !== false;
  const showCandlePaint = params.showCandlePaint !== false;

  const g =
    geoms.find((x) => x.horizon === primary.horizon) ??
    geoms.find((x) => x.primary) ??
    geoms[0];
  if (!g) return empty;

  const atr = atrApprox(candles);
  const buf = Math.max(atr * 0.1, g.width * 0.035);
  const isLong = primary.direction === 'LONG';
  const side: 'above' | 'below' = primary.edge === 'upper' ? 'above' : 'below';
  const level = primary.edge === 'upper' ? g.tipUpper : g.tipLower;
  if (!(level > 0)) return empty;

  const read =
    edgeReads.find((r) => r.geom.horizon === g.horizon) ??
    edgeReads.find((r) => r.geom.id === g.id) ??
    null;
  const settlePhase =
    primary.edge === 'upper' ? read?.upperSettle ?? 'none' : read?.lowerSettle ?? 'none';
  const corePhase =
    phaseFromEdge(primary.stateKo, settlePhase) ??
    (plan?.edgeStateKo ? phaseFromEdge(plan.edgeStateKo, settlePhase) : null);
  if (!corePhase && primary.mode !== 'breakout' && primary.mode !== 'bounce') return empty;

  const phase: CorePhase = corePhase ?? 'pre';
  const scan = scanBreakBars(candles, level, side, buf, 14);
  const t2 = Number(candles[n - 1]?.time) || 0;
  const t1 = Number(candles[Math.max(0, n - 20)]?.time) || t2;
  if (!(t2 > 0)) return empty;

  const overlays: OverlayItem[] = [];
  const priceLines: AtlasPulsePriceLine[] = [];
  const markers: AtlasPulseMarker[] = [];
  const settlePaint = new Map<number, MonthDeskSettleCandleCell>();
  const bias: 'bullish' | 'bearish' = isLong ? 'bullish' : 'bearish';
  const pad = Math.max(atr * 0.22, Math.abs(level) * 0.0015, g.width * 0.06);

  /** 1) 돌파 핵심 가격선 — 전폭 */
  if (showZones) {
    const lineColor =
      phase === 'fail'
        ? 'rgba(148,163,184,0.8)'
        : phase === 'confirm'
          ? isLong
            ? 'rgba(74,222,128,0.95)'
            : 'rgba(251,113,133,0.95)'
          : phase === 'break' || phase === 'settle'
            ? '#FACC15'
            : isLong
              ? 'rgba(96,165,250,0.95)'
              : 'rgba(248,113,113,0.95)';
    const titleKo =
      phase === 'pre'
        ? `핵심돌파대기·${fmt(level)}`
        : phase === 'break'
          ? `핵심돌파·안착대기·${fmt(level)}`
          : phase === 'settle'
            ? `핵심안착중·${fmt(level)}`
            : phase === 'confirm'
              ? `핵심안착확정·${fmt(level)}`
              : `핵심돌파실패·${fmt(level)}`;
    priceLines.push({
      price: level,
      color: lineColor,
      title: titleKo,
      lineWidth: phase === 'confirm' || phase === 'break' ? 3 : 2,
      lineStyle: phase === 'fail' ? 'dotted' : phase === 'pre' ? 'dashed' : 'solid',
      axisLabel: true,
    });

    /** 2) 돌파해야 할 얇은 zone (레일 바깥 쪽) */
    const breakLo = side === 'above' ? level : level - pad;
    const breakHi = side === 'above' ? level + pad : level;
    overlays.push({
      id: 'merged-desk-rb-core-break-zone',
      kind: 'zone',
      category: 'scenario',
      label: phase === 'pre' ? '핵심·돌파자리' : '핵심·돌파선',
      zoneFaceBase: '핵심돌파',
      zoneFaceSignal:
        phase === 'pre'
          ? '대기'
          : phase === 'break'
            ? '돌파'
            : phase === 'confirm'
              ? '안착'
              : phase === 'fail'
                ? '실패'
                : '안착중',
      time1: t1,
      time2: t2,
      price1: breakHi,
      price2: breakLo,
      color:
        phase === 'fail'
          ? 'rgba(100,116,139,0.22)'
          : phase === 'confirm'
            ? isLong
              ? 'rgba(34,197,94,0.22)'
              : 'rgba(244,63,94,0.22)'
            : 'rgba(250,204,21,0.28)',
      labelBackgroundColor:
        phase === 'confirm'
          ? isLong
            ? 'rgba(22,101,52,0.94)'
            : 'rgba(159,18,57,0.94)'
          : phase === 'fail'
            ? 'rgba(71,85,105,0.94)'
            : 'rgba(202,138,4,0.95)',
      labelTextColor: '#f8fafc',
      confidence: 0.86,
      overlayZoneExtraClass: [
        'merged-desk-rb-core-break-zone',
        'merged-desk-rb-channel',
        'merged-desk-money-zone-keep',
        'merged-desk-zone-pro-hero',
        phase === 'fail'
          ? 'merged-desk-rb-core--fail'
          : phase === 'confirm'
            ? 'merged-desk-rb-core--ok'
            : 'merged-desk-rb-core--hot',
      ].join(' '),
      labelTooltip: [
        `${g.horizonKo || '채널'} 핵심 돌파 자리`,
        `레벨 ${fmt(level)} · ${isLong ? '롱(상단)' : '숏(하단)'}`,
        phase === 'pre'
          ? '종가가 이 선을 넘기 전 — 돌파 대기'
          : phase === 'break'
            ? '돌파됨 · 안착(다봉/재테스트) 전'
            : phase === 'confirm'
              ? '안착확정 · 조건부 참고'
              : phase === 'fail'
                ? '돌파 후 복귀 = 실패'
                : '안착 진행 중',
        '확정 수익·승률 보장 아님',
      ].join('\n'),
    });

    /** 3) 돌파 후 안착 zone — 레일 바깥 유지 구간 */
    if (phase === 'break' || phase === 'settle' || phase === 'confirm' || phase === 'fail') {
      const holdLo = side === 'above' ? level : level - pad * 1.6;
      const holdHi = side === 'above' ? level + pad * 1.6 : level;
      overlays.push({
        id: 'merged-desk-rb-core-settle-zone',
        kind: 'zone',
        category: 'scenario',
        label: phase === 'fail' ? '핵심·안착실패' : phase === 'confirm' ? '핵심·안착확정' : '핵심·안착자리',
        zoneFaceBase: '핵심안착',
        zoneFaceSignal:
          phase === 'fail' ? '실패' : phase === 'confirm' ? '확정' : '대기',
        time1: t1,
        time2: t2,
        price1: holdHi,
        price2: holdLo,
        color:
          phase === 'fail'
            ? 'rgba(100,116,139,0.18)'
            : phase === 'confirm'
              ? isLong
                ? 'rgba(34,197,94,0.2)'
                : 'rgba(244,63,94,0.2)'
              : 'rgba(249,115,22,0.22)',
        labelBackgroundColor:
          phase === 'confirm'
            ? isLong
              ? 'rgba(21,128,61,0.95)'
              : 'rgba(190,24,93,0.95)'
            : phase === 'fail'
              ? 'rgba(71,85,105,0.92)'
              : 'rgba(194,65,12,0.94)',
        labelTextColor: '#f8fafc',
        confidence: 0.84,
        overlayZoneExtraClass: [
          'merged-desk-rb-core-settle-zone',
          'merged-desk-rb-channel',
          'merged-desk-money-zone-keep',
          phase === 'fail' ? 'merged-desk-rb-core--fail' : 'merged-desk-rb-core--settle',
        ].join(' '),
        labelTooltip: [
          '돌파 후 안착해야 할 자리',
          '종가가 이 구간 밖(돌파 방향)에 유지되어야 안착',
          '재테스트 후 홀드도 안착으로 본다',
          '확정 수익·승률 보장 아님',
        ].join('\n'),
      });
    }
  }

  /** 4) 캔들 색 — 돌파·안착·실패 봉 */
  if (showCandlePaint) {
    if (scan.breakIdx >= 0) {
      putPaint(settlePaint, candles, scan.breakIdx, 'breakout', bias);
      for (const i of scan.outsideIdxs) {
        if (i === scan.breakIdx) continue;
        if (phase === 'confirm' && i === scan.outsideIdxs[scan.outsideIdxs.length - 1]) {
          putPaint(settlePaint, candles, i, 'confirmed', bias);
        } else {
          putPaint(settlePaint, candles, i, 'settling', bias);
        }
      }
    }
    if (scan.failIdx >= 0 || phase === 'fail') {
      const fi = scan.failIdx >= 0 ? scan.failIdx : n - 1;
      putPaint(settlePaint, candles, fi, 'failed', bias);
    }
    if (phase === 'pre') {
      /** 대기: 마지막 봉만 약한 돌파 예고색 */
      putPaint(settlePaint, candles, n - 1, 'breakoutWeak', bias);
    }
  }

  /** 5) 봉 위·아래 이모티콘 */
  if (showMarkers) {
    const markAt = (idx: number, ph: CorePhase, idSuffix: string) => {
      if (idx < 0 || idx >= n) return;
      const t = Number(candles[idx]?.time);
      if (!Number.isFinite(t)) return;
      const em = emojiFor(ph, isLong);
      markers.push({
        time: t as UTCTimestamp,
        position: em.position,
        shape: 'circle',
        color: em.color,
        text: em.text,
        size: ph === 'confirm' || ph === 'fail' ? 2 : 1,
        id: `merged-desk-rb-core-mk-${idSuffix}-${t}`,
      });
    };

    if (phase === 'pre') {
      markAt(n - 1, 'pre', 'pre');
    } else {
      if (scan.breakIdx >= 0) markAt(scan.breakIdx, 'break', 'break');
      if (phase === 'break' || phase === 'settle') {
        markAt(n - 1, phase === 'break' ? 'break' : 'settle', 'now');
      }
      if (phase === 'confirm') {
        const lastOut = scan.outsideIdxs[scan.outsideIdxs.length - 1] ?? n - 1;
        markAt(lastOut, 'confirm', 'ok');
      }
      if (phase === 'fail') {
        markAt(scan.failIdx >= 0 ? scan.failIdx : n - 1, 'fail', 'fail');
      }
    }
  }

  const dirKo = isLong ? '롱' : '숏';
  const summaryKo = `핵심세트 · ${g.horizonKo || '채널'} · ${dirKo} · ${
    phase === 'pre'
      ? '돌파대기'
      : phase === 'break'
        ? '돌파·안착대기'
        : phase === 'settle'
          ? '안착중'
          : phase === 'confirm'
            ? '안착확정'
            : '돌파실패'
  } · ${fmt(level)}`;

  return { overlays, priceLines, markers, settlePaint, summaryKo };
}

/** 설정 반영 · MoneyEdge 결과로 핵심 세트 생성 */
export function buildMergedDeskRbCoreBreakSetFromMoney(params: {
  candles: Candle[];
  timeframe: string;
  geoms: MergedDeskChannelGeom[];
  edgeReads: MergedDeskChannelEdgeRead[];
  plan: MergedDeskChannelMoneyPlan | null;
  primary: MergedDeskChannelPrimaryDecision | null;
}): MergedDeskRbCoreBreakSet {
  let showZones = true;
  let showMarkers = true;
  let showCandlePaint = true;
  try {
    const s = loadSettings();
    showZones = s.chartMergedDeskRbCoreZonesEnabled !== false;
    showMarkers = s.chartMergedDeskRbCoreMarkersEnabled !== false;
    showCandlePaint = s.chartMergedDeskRbCoreCandlePaintEnabled !== false;
  } catch {
    /* ignore */
  }
  if (!showZones && !showMarkers && !showCandlePaint) {
    return {
      overlays: [],
      priceLines: [],
      markers: [],
      settlePaint: new Map(),
      summaryKo: '',
    };
  }
  return buildMergedDeskRbCoreBreakSet({
    ...params,
    showZones,
    showMarkers,
    showCandlePaint,
  });
}

/** ChartView용 — 통합모드에서 채널 핵심 안착 캔들색만 뽑기 */
export function collectMergedDeskRbCoreSettleCandlePaint(
  candles: Candle[],
  timeframe: string
): Map<number, MonthDeskSettleCandleCell> | null {
  try {
    const s = loadSettings();
    if (s.chartMergedDeskRbCoreCandlePaintEnabled === false) return null;
    if (s.chartMergedDeskBlueRedChannelsEnabled === false) return null;
  } catch {
    /* ignore */
  }
  if (candles.length < 8) return null;
  const pack = buildMergedDeskChannelMoneyEdgePack(candles, timeframe);
  if (!pack.primary || !pack.geoms.length) return null;
  const core = buildMergedDeskRbCoreBreakSetFromMoney({
    candles,
    timeframe,
    geoms: pack.geoms,
    edgeReads: pack.edgeReads,
    plan: pack.plan,
    primary: pack.primary,
  });
  return core.settlePaint.size > 0 ? core.settlePaint : null;
}

