/**
 * 채널 구간 전체를 훑어 과거에 떴어야 할 돌파·안착·실패 자리를 모은다.
 * 에피소드: 안→밖(돌파) → 2봉+ 밖(안착확정) 또는 안 복귀(실패)
 */
function scanHistoricalCoreEvents(
  candles: Candle[],
  g: MergedDeskChannelGeom,
  buf: number,
  settleBars = 2
): HistEvent[] {
  const n = candles.length;
  if (n < 4) return [];
  let i0 = 0;
  for (let i = 0; i < n; i++) {
    if (Number(candles[i]!.time) >= g.tStart) {
      i0 = Math.max(0, i - 1);
      break;
    }
  }
  /** 채널 시작 전 조금 + 끝까지 — 과거 자리 전부 */
  const from = Math.max(1, i0);
  const out: HistEvent[] = [];

  for (const side of ['above', 'below'] as const) {
    const isLong = side === 'above';
    let runOutside = 0;
    let breakIdx = -1;
    let confirmed = false;

    for (let i = from; i < n; i++) {
      const close = Number(candles[i]?.close);
      if (!Number.isFinite(close)) continue;
      const level = railAtBar(g, candles, i, side === 'above' ? 'upper' : 'lower');
      if (!(level > 0)) continue;
      const outside = side === 'above' ? close > level + buf : close < level - buf;
      const insideHard = side === 'above' ? close < level - buf * 0.35 : close > level + buf * 0.35;

      if (outside) {
        if (breakIdx < 0) {
          breakIdx = i;
          out.push({ idx: i, phase: 'break', side, isLong });
          runOutside = 1;
          confirmed = false;
        } else {
          runOutside += 1;
          if (!confirmed && runOutside >= settleBars) {
            out.push({ idx: i, phase: 'confirm', side, isLong });
            confirmed = true;
          } else if (confirmed && runOutside === settleBars + 1) {
            /** 안착 직후 한 봉은 안착중 표시(중복 최소화) */
            out.push({ idx: i, phase: 'settle', side, isLong });
          }
        }
      } else if (breakIdx >= 0) {
        if (insideHard) {
          out.push({ idx: i, phase: 'fail', side, isLong });
        }
        breakIdx = -1;
        runOutside = 0;
        confirmed = false;
      }
    }
  }

  /** 같은 봉에 여러 이벤트가 겹치면 실패 > 확정 > 돌파 > 안착 순으로 하나만 */
  const rank: Record<CorePhase, number> = {
    fail: 4,
    confirm: 3,
    break: 2,
    settle: 1,
    pre: 0,
  };
  const byIdx = new Map<number, HistEvent>();
  for (const ev of out) {
    const prev = byIdx.get(ev.idx);
    if (!prev || rank[ev.phase] >= rank[prev.phase]) byIdx.set(ev.idx, ev);
  }
  return [...byIdx.values()].sort((a, b) => a.idx - b.idx);
}

