/**
 * AI 파랑·빨강 띠 — Zone 패널(전투·수급·돌파) 증거를 채널 면(zone)으로 합류.
 * 차트에 % 숫자 나열 금지 · 면 색·짧은 zoneFace 토큰만. 확정 수익·승률 보장 아님.
 */
import type { Candle, OverlayItem } from '@/types';
import type { SmcZoneBattleVerdict } from '@/lib/assets353SmcZoneConflictIntel';
import { pickNearestSmcZoneBattle } from '@/lib/assets353SmcZoneConflictIntel';
import { computeZoneBattleForTfRange } from '@/lib/assets353SmcZoneBattleMtf';
import type {
  MergedDeskChannelEdgeRead,
  MergedDeskChannelPrimaryDecision,
} from '@/lib/mergedDeskChannelMoneyEdge';
import type { MergedDeskChannelGeom } from '@/lib/mergedDeskBlueRedChannels';
import { MERGED_DESK_RIGHT_FUTURE_BARS } from '@/lib/mergedDeskSharedChartView';

export type RbAiZoneFaceState =
  | 'breakoutPossible'
  | 'breakoutAttempt'
  | 'settled'
  | 'failRiskHigh'
  | 'volumeHeavy'
  | 'sellHeavy'
  | 'buyHeavy'
  | 'holdSupport'
  | 'holdResist'
  | 'battleLong'
  | 'battleShort'
  | 'battleMixed';

export type MergedDeskRbAiZoneFacePack = {
  overlays: OverlayItem[];
  states: RbAiZoneFaceState[];
  battle: SmcZoneBattleVerdict | null;
  summaryKo: string;
  /** MoneyEdge 후보 가점에 쓰는 힌트 */
  scoreBoost: number;
  scoreReasonsKo: string[];
};

const STATE_SIGNAL_KO: Record<RbAiZoneFaceState, string> = {
  breakoutPossible: '돌파가능',
  breakoutAttempt: '돌파중',
  settled: '안착',
  failRiskHigh: '실패위험',
  volumeHeavy: '거래과다',
  sellHeavy: '매도강',
  buyHeavy: '매수강',
  holdSupport: '지지면',
  holdResist: '저항면',
  battleLong: '롱우세',
  battleShort: '숏우세',
  battleMixed: '혼조',
};

function barStepMs(candles: Candle[]): number {
  const n = candles.length;
  if (n < 2) return 3_600_000;
  const d = Number(candles[n - 1]!.time) - Number(candles[n - 2]!.time);
  return Number.isFinite(d) && d > 0 ? d : 3_600_000;
}

function faceFill(states: RbAiZoneFaceState[], descending: boolean): string {
  if (states.includes('failRiskHigh')) return 'rgba(185,28,28,0.28)';
  if (states.includes('breakoutPossible') || states.includes('breakoutAttempt')) {
    return descending ? 'rgba(244,63,94,0.26)' : 'rgba(59,130,246,0.26)';
  }
  if (states.includes('settled')) {
    return descending ? 'rgba(244,63,94,0.2)' : 'rgba(34,197,94,0.22)';
  }
  if (states.includes('sellHeavy')) return 'rgba(239,68,68,0.24)';
  if (states.includes('buyHeavy')) return 'rgba(34,197,94,0.22)';
  if (states.includes('volumeHeavy')) return 'rgba(234,179,8,0.22)';
  if (states.includes('battleShort')) return 'rgba(248,113,113,0.2)';
  if (states.includes('battleLong')) return 'rgba(96,165,250,0.22)';
  return descending ? 'rgba(248,113,113,0.16)' : 'rgba(96,165,250,0.16)';
}

function resolveBattle(params: {
  candles: Candle[];
  timeframe: string;
  tipLower: number;
  tipUpper: number;
  zoneBattle?: SmcZoneBattleVerdict | null;
  zoneBattles?: SmcZoneBattleVerdict[] | null;
  mtfAggregate?: SmcZoneBattleVerdict | null;
}): SmcZoneBattleVerdict | null {
  if (params.mtfAggregate) return params.mtfAggregate;
  if (params.zoneBattle) return params.zoneBattle;
  if (params.zoneBattles?.length) {
    const nearest = pickNearestSmcZoneBattle(params.candles, params.zoneBattles);
    if (nearest) return nearest;
  }
  return computeZoneBattleForTfRange(
    params.candles,
    params.timeframe,
    params.tipLower,
    params.tipUpper,
    {}
  );
}

function deriveStates(params: {
  primary: MergedDeskChannelPrimaryDecision | null;
  edgeReads: MergedDeskChannelEdgeRead[];
  battle: SmcZoneBattleVerdict | null;
  volRatio: number;
}): RbAiZoneFaceState[] {
  const out: RbAiZoneFaceState[] = [];
  const edgeKo = params.primary?.stateKo;
  const read = params.edgeReads.find((r) => r.geom.horizon === params.primary?.horizon);

  if (edgeKo === '돌파가능') out.push('breakoutPossible');
  if (edgeKo === '돌파') out.push('breakoutAttempt');
  if (edgeKo === '안착확정') out.push('settled');
  if (edgeKo === '돌파실패') out.push('failRiskHigh');
  if (edgeKo === '지지가능') out.push('holdSupport');
  if (edgeKo === '저항가능') out.push('holdResist');

  if (read?.upperSettle === 'failed' || read?.lowerSettle === 'failed') {
    if (!out.includes('failRiskHigh')) out.push('failRiskHigh');
  }

  const b = params.battle;
  if (b) {
    if (b.breakoutPct >= 55 && !out.includes('breakoutPossible') && edgeKo !== '돌파실패') {
      out.push('breakoutPossible');
    }
    if (b.sellStrength === 'strong') out.push('sellHeavy');
    if (b.buyStrength === 'strong') out.push('buyHeavy');
    if (b.dominant === 'LONG') out.push('battleLong');
    else if (b.dominant === 'SHORT') out.push('battleShort');
    else out.push('battleMixed');

    const volReason = b.reasonsKo.some((r) => /거래량|수급|매도|매수/.test(r));
    if (volReason && params.volRatio >= 1.45) out.push('volumeHeavy');

    /** 돌파% 높은데 반대 강도 강하면 실패위험 */
    if (
      b.breakoutPct >= 50 &&
      ((b.dominant === 'LONG' && b.sellStrength === 'strong') ||
        (b.dominant === 'SHORT' && b.buyStrength === 'strong'))
    ) {
      if (!out.includes('failRiskHigh')) out.push('failRiskHigh');
    }
  }

  if (params.volRatio >= 1.8 && !out.includes('volumeHeavy')) out.push('volumeHeavy');

  /** 우선순위 — 실패·돌파·수급 위주 (최대 4) */
  const rank: RbAiZoneFaceState[] = [
    'failRiskHigh',
    'breakoutAttempt',
    'breakoutPossible',
    'settled',
    'sellHeavy',
    'buyHeavy',
    'volumeHeavy',
    'holdSupport',
    'holdResist',
    'battleLong',
    'battleShort',
    'battleMixed',
  ];
  const uniq = [...new Set(out)];
  return rank.filter((s) => uniq.includes(s)).slice(0, 4);
}

function scoreBoostFromEvidence(
  states: RbAiZoneFaceState[],
  primary: MergedDeskChannelPrimaryDecision | null,
  battle: SmcZoneBattleVerdict | null
): { boost: number; reasonsKo: string[] } {
  let boost = 0;
  const reasonsKo: string[] = [];
  if (!primary || primary.direction === 'NEUTRAL') return { boost: 0, reasonsKo };

  if (states.includes('volumeHeavy')) {
    boost += 6;
    reasonsKo.push('거래과다·채널합류');
  }
  if (states.includes('breakoutPossible')) {
    boost += 8;
    reasonsKo.push('돌파가능·자동분석');
  }
  if (states.includes('failRiskHigh')) {
    boost -= 12;
    reasonsKo.push('돌파실패위험');
  }
  if (battle) {
    if (primary.direction === 'LONG' && battle.dominant === 'LONG') {
      boost += 7;
      reasonsKo.push('Zone전투·롱우세');
    } else if (primary.direction === 'SHORT' && battle.dominant === 'SHORT') {
      boost += 7;
      reasonsKo.push('Zone전투·숏우세');
    } else if (
      (primary.direction === 'LONG' && battle.dominant === 'SHORT') ||
      (primary.direction === 'SHORT' && battle.dominant === 'LONG')
    ) {
      boost -= 8;
      reasonsKo.push('Zone전투·역방향');
    }
    if (primary.direction === 'LONG' && states.includes('sellHeavy')) {
      boost -= 6;
      reasonsKo.push('매도강·롱주의');
    }
    if (primary.direction === 'SHORT' && states.includes('buyHeavy')) {
      boost -= 6;
      reasonsKo.push('매수강·숏주의');
    }
  }
  return { boost, reasonsKo: reasonsKo.slice(0, 5) };
}

/**
 * 채널 tip 구간 + Zone 전투/수급 → AI 채널 면(zone) 오버레이.
 */
export function buildMergedDeskRbAiZoneFacePack(params: {
  candles: Candle[];
  timeframe: string;
  geoms: MergedDeskChannelGeom[];
  edgeReads: MergedDeskChannelEdgeRead[];
  primary: MergedDeskChannelPrimaryDecision | null;
  volRatio: number;
  zoneBattle?: SmcZoneBattleVerdict | null;
  zoneBattles?: SmcZoneBattleVerdict[] | null;
  mtfAggregate?: SmcZoneBattleVerdict | null;
}): MergedDeskRbAiZoneFacePack {
  const empty: MergedDeskRbAiZoneFacePack = {
    overlays: [],
    states: [],
    battle: null,
    summaryKo: '',
    scoreBoost: 0,
    scoreReasonsKo: [],
  };
  const { candles, geoms, primary } = params;
  if (candles.length < 12 || !geoms.length) return empty;

  const g =
    (primary ? geoms.find((x) => x.horizon === primary.horizon) : null) ??
    geoms.find((x) => x.primary) ??
    geoms[0]!;
  const tipUpper = g.tipUpper;
  const tipLower = g.tipLower;
  if (!(tipUpper > tipLower)) return empty;

  const battle = resolveBattle({
    candles,
    timeframe: params.timeframe,
    tipLower,
    tipUpper,
    zoneBattle: params.zoneBattle,
    zoneBattles: params.zoneBattles,
    mtfAggregate: params.mtfAggregate,
  });

  const states = deriveStates({
    primary,
    edgeReads: params.edgeReads,
    battle,
    volRatio: params.volRatio,
  });
  if (!states.length) return { ...empty, battle };

  const { boost, reasonsKo } = scoreBoostFromEvidence(states, primary, battle);
  const n = candles.length;
  const t2 = Number(candles[n - 1]!.time);
  const lookback = Math.min(48, Math.max(16, Math.floor(n * 0.18)));
  const t1 = Number(candles[Math.max(0, n - 1 - lookback)]!.time);
  /** 우측 예측 여백까지 면 연장(시각용 time2) */
  const t2Pad = t2 + barStepMs(candles) * Math.min(8, MERGED_DESK_RIGHT_FUTURE_BARS);

  const primaryState = states[0]!;
  const signalKo = states.map((s) => STATE_SIGNAL_KO[s]).join('·');
  const detailParts = [
    battle?.detailKo,
    battle?.headlineKo,
    primary?.captionKo,
    ...reasonsKo,
    ...(battle?.reasonsKo ?? []).slice(0, 4),
    `vol×${params.volRatio.toFixed(2)}`,
    '확정 수익·승률 보장 아님',
  ].filter(Boolean);

  const overlays: OverlayItem[] = [
    {
      id: `merged-desk-rb-ai-face-${g.horizon}-${primaryState}`,
      kind: 'zone',
      category: 'chartPrimeTrendChannels',
      label: '',
      zoneFaceBase: 'AI채널면',
      zoneFaceSignal: signalKo.slice(0, 18),
      zoneFaceDetailKo: detailParts.join('\n'),
      time1: t1,
      time2: t2Pad,
      price1: tipUpper,
      price2: tipLower,
      color: faceFill(states, g.useBearFill || g.descending),
      confidence: Math.min(
        0.92,
        0.55 +
          (battle ? Math.abs(battle.longPct - battle.shortPct) / 200 : 0) +
          (params.volRatio >= 1.5 ? 0.08 : 0)
      ),
      zoneFillPreserve: true,
      zonePulse: states.includes('breakoutPossible') || states.includes('failRiskHigh'),
      structureBias:
        primary?.direction === 'LONG'
          ? 'bullish'
          : primary?.direction === 'SHORT'
            ? 'bearish'
            : battle?.dominant === 'LONG'
              ? 'bullish'
              : battle?.dominant === 'SHORT'
                ? 'bearish'
                : undefined,
      overlayZoneExtraClass: [
        'merged-desk-rb-ai-face',
        'merged-desk-rb-channel',
        'merged-desk-money-zone-keep',
        'merged-desk-zone-pro-hero',
        ...states.map((s) => `merged-desk-rb-ai-face--${s}`),
      ].join(' '),
      labelTooltip: detailParts.join('\n'),
    },
  ];

  /** 수급 강한 쪽만 얇은 엣지 면 (글자 없이 색만) */
  if (states.includes('sellHeavy') || states.includes('buyHeavy')) {
    const sell = states.includes('sellHeavy');
    const bandH = (tipUpper - tipLower) * 0.22;
    overlays.push({
      id: `merged-desk-rb-ai-edge-${sell ? 'sell' : 'buy'}`,
      kind: 'zone',
      category: 'chartPrimeTrendChannels',
      label: '',
      zoneFaceBase: sell ? '매도면' : '매수면',
      zoneFaceSignal: sell ? '매도강' : '매수강',
      zoneFaceDetailKo: sell
        ? '채널 상단 매도 수급 우세(Zone전투·자동분석)'
        : '채널 하단 매수 수급 우세(Zone전투·자동분석)',
      time1: t1,
      time2: t2Pad,
      price1: sell ? tipUpper : tipLower + bandH,
      price2: sell ? tipUpper - bandH : tipLower,
      color: sell ? 'rgba(239,68,68,0.32)' : 'rgba(34,197,94,0.3)',
      confidence: 0.8,
      zoneFillPreserve: true,
      overlayZoneExtraClass: [
        'merged-desk-rb-ai-face',
        'merged-desk-rb-ai-edge',
        'merged-desk-rb-channel',
        'merged-desk-money-zone-keep',
        sell ? 'merged-desk-rb-ai-face--sellHeavy' : 'merged-desk-rb-ai-face--buyHeavy',
      ].join(' '),
    });
  }

  const summaryKo = `AI채널면 · ${signalKo}${
    battle ? ` · L${Math.round(battle.longPct)}/S${Math.round(battle.shortPct)}/돌파${Math.round(battle.breakoutPct)}` : ''
  }`;

  return {
    overlays,
    states,
    battle,
    summaryKo,
    scoreBoost: boost,
    scoreReasonsKo: reasonsKo,
  };
}

