  /** 이긴 구조(단기|장기)를 면 강조로 승격 — 라벨도 그쪽에 게이트 캡션 */
  const decisionHorizon: MergedDeskChannelHorizon =
    primary?.horizon ?? best?.geom.horizon ?? 'short';
  const promoted = promoteMergedDeskChannelPrimary(pack, decisionHorizon);
  const geoms = promoted.geoms;

  /** primary 확정 후 AI면 재계산(상태·면 정렬) */
  if (aiFaceOn) {
    aiFace = buildMergedDeskRbAiZoneFacePack({
      candles,
      timeframe,
      geoms,
      edgeReads,
      primary,
      volRatio: volR,
      zoneBattle: opts?.zoneBattle,
      zoneBattles: opts?.zoneBattles,
      mtfAggregate: opts?.mtfAggregate,
    });
  }

  const tradeSet = plan ? buildChannelTradeSetVisuals(plan, candles, atr) : null;

  /** 핵심 돌파/안착 zone · 캔들색 · 이모티콘 — 채널 게이트와 한 세트 */
  const core = buildMergedDeskRbCoreBreakSetFromMoney({
    candles,
    timeframe,
    geoms,
    edgeReads,
    plan,
    primary,
  });

  /** 게이트 캡션 = 결정 호라이즌만. 다른 쪽은 구조 라벨 유지 */
  const captionByHorizon: Partial<Record<MergedDeskChannelHorizon, string>> = {};
  if (plan && primary) {
    const dirKo = plan.direction === 'LONG' ? '롱' : '숏';
    captionByHorizon[decisionHorizon] =
      plan.edgeStateKo === '안착확정'
        ? `◆안착확정·${dirKo}진입·${fmt(plan.entry)}`
        : plan.edgeStateKo === '돌파실패'
          ? `◆돌파실패·진입금지`
          : plan.edgeStateKo === '돌파'
            ? `◆돌파·안착대기·진입금지`
            : plan.edgeStateKo === '돌파가능'
              ? `◆돌파전대기·${fmt(plan.entry)}`
              : `${plan.edgeStateKo}·${dirKo}${plan.statusKo}·E${fmt(plan.entry)}`;
  } else if (primary) {
    captionByHorizon[decisionHorizon] = primary.captionKo;
  }

  const stamped = stampMergedDeskBlueRedMoneyCaptions(promoted, captionByHorizon, {
    keepStructureOnOthers: true,
  });

  const structLines = primary ? slimStructurePriceLines(primary, geoms) : [];
  /** 매매세트 선이 있으면 구조선은 핫 엣지 1본만(중복 축 라벨 감소) */
  const slimStruct =
    tradeSet && tradeSet.priceLines.length
      ? structLines.filter((l) => /돌파|지지|저항/.test(String(l.title || '')))
      : structLines;

  const aiSum = aiFace?.summaryKo ? ` · ${aiFace.summaryKo}` : '';
  const summaryKo = plan
    ? `◆채널게이트 · ${plan.horizonKo} · ${plan.edgeStateKo} · ${
        plan.direction === 'LONG' ? '롱' : '숏'
      } · E${fmt(plan.entry)} SL${fmt(plan.stopLoss)} TP1${fmt(plan.tp1)} · ${plan.statusKo} · ${plan.rr.toFixed(1)}R${
        inConfluence ? ' · 중착' : ''
      }${core.summaryKo ? ` · ${core.summaryKo}` : ''}${aiSum}`
    : primary
      ? `채널★ ${primary.horizonKo}·${primary.captionKo} · vol×${volR.toFixed(2)}${
          conf ? ` · 중착${(conf.overlapPct * 100).toFixed(0)}%` : ''
        }${core.summaryKo ? ` · ${core.summaryKo}` : ''}${aiSum}`
      : pack.summaryKo;

  return {
    overlays: [
      ...stamped.overlays,
      ...(aiFace?.overlays ?? []),
      ...(tradeSet?.overlays ?? []),
      ...core.overlays,
    ],
    plan,
    priceLines: [...(tradeSet?.priceLines ?? []), ...slimStruct, ...core.priceLines],
    markers: core.markers,
    settlePaint: core.settlePaint,
    core,
    summaryKo,
    geoms,
    edgeReads,
    primary,
    aiFaceSummaryKo: aiFace?.summaryKo || '',
  };
}

chartMergedDeskRbCoreZonesEnabled: boolean;
/** 파랑·빨강 띠 — Zone패널(전투·수급·돌파) 합류 AI 채널 면 */
chartMergedDeskRbAiZoneFaceEnabled: boolean;

