/**
 * 와이코프 교재 도식(StockCharts 스타일) + 지금 자리 핫스팟.
 * 클릭 시 이미지 · 차트 하방초록/상방빨강 깜빡임.
 */
import type { OverlayItem } from '@/types';
import type { MergedDeskWyckoffRead, WyckoffEvent, WyckoffPhase } from '@/lib/mergedDeskWyckoffCycle';

export type WyckoffSchematicId =
  | 'accumulation-1'
  | 'accumulation-2'
  | 'distribution-1'
  | 'distribution-2'
  | 'price-cycle';

export type WyckoffBlinkPin = {
  id: string;
  side: 'low' | 'high';
  time: number;
  price: number;
  label: string;
  primary: boolean;
};

const HOTSPOTS: Record<WyckoffSchematicId, Record<string, { left: number; top: number }>> = {
  'accumulation-1': {
    PS: { left: 14, top: 46 },
    SC: { left: 18, top: 74 },
