    confidence,
    support: range.low,
    resist: range.high,
    rangeStartIdx: range.startIdx,
    rangeEndIdx: range.endIdx,
    eventIdx,
    eventTime: Number(evBar.time),
    eventPrice,
    spring: spring || springIdx >= 0,
    utad: utad || utadIdx >= 0,
  };
}

