'use client';

import type { MergedDeskWyckoffRead } from '@/lib/mergedDeskWyckoffCycle';
import {
  resolveWyckoffHotspotKey,
  resolveWyckoffSchematicId,
  wyckoffSchematicHotspot,
  wyckoffSchematicSrc,
} from '@/lib/mergedDeskWyckoffSchematic';
import styles from './MergedAnalysisDesk.module.css';

type Props = {
  read: MergedDeskWyckoffRead;
  onClose: () => void;
};

export function MergedDeskSchematicViewer({ read, onClose }: Props) {
  const sid = resolveWyckoffSchematicId(read);
  const key = resolveWyckoffHotspotKey(read);
  const spot = wyckoffSchematicHotspot(sid, key);
  const title = read.eventEn || read.eventKo || read.headlineKo;
  const lowish =
    read.event === 'ST' ||
    read.event === 'SC' ||
    read.event === 'Spring' ||
    read.event === 'LPS' ||
    read.event === 'SOW' ||
    read.event === 'PS';

  return (
    <div className={styles.schematicBackdrop} role="dialog" aria-label="와이코프 도식" onClick={onClose}>
      <div className={styles.schematicPanel} onClick={(e) => e.stopPropagation()}>
        <div className={styles.schematicHead}>
          <strong>지금 자리 · {title}</strong>
          <button type="button" className={styles.schematicClose} onClick={onClose}>
            닫기
          </button>
        </div>
        <p className={styles.schematicHint}>
          교재 도식 위 깜빡임 = 현재 이벤트 근사. 차트는 하방 초록 · 상방 빨강. 확정 아님.
        </p>
        <div className={styles.schematicImgWrap}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={wyckoffSchematicSrc(sid)} alt={read.headlineKo} className={styles.schematicImg} />
          {spot && (
            <span
              className={`${styles.schematicHot} ${lowish ? styles.schematicHotGreen : styles.schematicHotRed}`}
              style={{ left: `${spot.left}%`, top: `${spot.top}%` }}
            >
              <span className={styles.schematicHotRing} />
              <span className={styles.schematicHotLab}>{title}</span>
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

