/**
 * 통합·분석 — 차트 상단 사이클·학파 ‘지금 자리’.
 * 와이코프 TR 작도 + 다학파 합류 + 학파별 교재 도식. 확정 예측·승률 보장 아님.
 */
import type { AnalyzeResponse, Candle, OverlayItem } from '@/types';
import type { AtlasPulsePriceLine } from '@/lib/monthDeskAtlasPulseDesk';
import type { MergedSmcLeadingContext } from '@/lib/mergedAnalysisSmcLeading';
import {
  buildMergedDeskWyckoffPack,
  type MergedDeskWyckoffRead,
} from '@/lib/mergedDeskWyckoffCycle';
import {
  buildMergedDeskElliottPack,
  type MergedDeskElliottRead,
} from '@/lib/mergedDeskElliottWave';
import {
  detectMergedDeskSchoolSeats,
  type MergedDeskSchoolSeat,
  type SchoolSeatKind,
} from '@/lib/mergedDeskSchoolSeat';
import type { ClickableSchool, SchoolSchematicPin } from '@/lib/mergedDeskSchoolSchematicCatalog';
import { buildSchoolSchematicBlinks, buildSchoolSchematicPins } from '@/lib/mergedDeskSchoolSchematicResolve';

export type CycleProgressKind = SchoolSeatKind;
export type CycleProgressTone = MergedDeskSchoolSeat['tone'];
export type MergedDeskCycleCandidate = MergedDeskSchoolSeat;

export type MergedDeskCycleProgressPack = {
  primary: MergedDeskCycleCandidate | null;
  others: MergedDeskCycleCandidate[];
  wyckoff: MergedDeskWyckoffRead | null;
  elliott: MergedDeskElliottRead | null;
  schematics: Partial<Record<ClickableSchool, SchoolSchematicPin>>;
  overlays: OverlayItem[];
  priceLines: AtlasPulsePriceLine[];
  nowKo: string;
};

export function buildMergedDeskCycleProgressPack(params: {
  candles: Candle[];
  timeframe: string;
  enabled?: boolean;
  analysis?: AnalyzeResponse | null;
  smcLeading?: MergedSmcLeadingContext | null;
}): MergedDeskCycleProgressPack {
  const empty: MergedDeskCycleProgressPack = {
    primary: null,
    others: [],
    wyckoff: null,
    elliott: null,
    schematics: {},
    overlays: [],
    priceLines: [],
    nowKo: '',
  };
  if (params.enabled === false || params.candles.length < 24) return empty;

  const wk = buildMergedDeskWyckoffPack({
    candles: params.candles,
    timeframe: params.timeframe,
    enabled: true,
  });
  const ew = buildMergedDeskElliottPack(params.candles);
  const seats = detectMergedDeskSchoolSeats({
    candles: params.candles,
    wyckoff: wk.read,
    elliott: ew.read,
    analysis: params.analysis,
    smcLeading: params.smcLeading,
  });
  const primary = seats.find((s) => s.kind === 'seat') ?? seats[0] ?? null;
  const rest = seats.filter((s) => s !== primary);
  const pinOrder: SchoolSeatKind[] = [
    'wyckoff',
    'elliott',
    'dow',
    'classical',
    'harmonic',
    'smc',
    'ichimoku',
    'chan',
    'fib',
    'vsa',
    'brooks',
    'wolfe',
    'pitchfork',
    'profile',
    'pnf',
    'nison',
    'turtle',
    'macro',
  ];
  const others = [
    ...pinOrder.map((k) => rest.find((s) => s.kind === k)).filter((s): s is MergedDeskSchoolSeat => !!s),
    ...rest.filter((s) => !pinOrder.includes(s.kind)),
  ];
  const schematics = buildSchoolSchematicPins({
    candles: params.candles,
    seats,
    wyckoff: wk.read,
    elliott: ew.read,
  });
  const extraBlinks = buildSchoolSchematicBlinks(schematics, params.candles);

  return {
    primary,
    others,
    wyckoff: wk.read,
    elliott: ew.read,
    schematics,
    overlays: [...wk.overlays, ...ew.overlays, ...extraBlinks],
    priceLines: wk.priceLines,
    nowKo: primary?.headlineKo ?? '',
  };
}

'use client';

import { useMemo, useState } from 'react';
import type { MergedDeskElliottRead } from '@/lib/mergedDeskElliottWave';
import type { ElliottSchematicId } from '@/lib/mergedDeskElliottWave';
import { elliottHotspotKey } from '@/lib/mergedDeskElliottSchematic';
import {
  schoolFigures,
  schoolHint,
  schoolSchematicHotspot,
  type ClickableSchool,
  type SchoolSchematicPin,
} from '@/lib/mergedDeskSchoolSchematicCatalog';
import styles from './MergedAnalysisDesk.module.css';

type Props = {
  school: ClickableSchool;
  pin?: SchoolSchematicPin | null;
  elliott?: MergedDeskElliottRead | null;
  onClose: () => void;
};

export function MergedDeskSchematicViewer({ school, pin, elliott, onClose }: Props) {
  const figures = schoolFigures(school);
  const [figOverride, setFigOverride] = useState<string | null>(null);
  const figId = figOverride ?? pin?.figureId ?? figures[0]?.id ?? '';
  const fig = figures.find((f) => f.id === figId) ?? figures[0] ?? null;

  const model = useMemo(() => {
    if (!fig) return null;
    const title = pin?.titleEn || pin?.headlineKo || fig.tabKo;
    let key = pin?.hotspotKey ?? '';
    if (school === 'elliott' && elliott) {
      key = elliottHotspotKey(elliott, fig.id as ElliottSchematicId);
    }
    return {
      title,
      hint: schoolHint(school),
      src: fig.src,
      alt: pin?.headlineKo || fig.tabKo,
      spot: key ? schoolSchematicHotspot(school, fig.id, key) : null,
      lowish: pin?.eventLow ?? true,
      explain: pin?.explainKo ?? ['현재 자리는 미검출. 교재 도식만 표시. 확정 아님.'],
      caption: fig.captionKo,
    };
  }, [fig, pin, school, elliott]);

  if (!model) return null;

  return (
    <div
      className={styles.schematicBackdrop}
      role="dialog"
      aria-label={`${school} 도식`}
      onClick={onClose}
    >
      <div className={styles.schematicPanel} onClick={(e) => e.stopPropagation()}>
        <div className={styles.schematicHead}>
          <strong>지금 자리 · {model.title}</strong>
          <button type="button" className={styles.schematicClose} onClick={onClose}>
            닫기
          </button>
        </div>
        <p className={styles.schematicHint}>{model.hint}</p>
        {figures.length > 1 && (
          <div className={styles.schematicTabs}>
            {figures.map((f) => (
              <button
                key={f.id}
                type="button"
                className={`${styles.schematicTab} ${fig?.id === f.id ? styles.schematicTabOn : ''}`}
                onClick={() => setFigOverride(f.id)}
              >
                {f.tabKo}
              </button>
            ))}
          </div>
        )}
        <div className={styles.schematicImgWrap}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={model.src} alt={model.alt} className={styles.schematicImg} />
          {model.spot && (
            <span
              className={`${styles.schematicHot} ${model.lowish ? styles.schematicHotGreen : styles.schematicHotRed}`}
              style={{ left: `${model.spot.left}%`, top: `${model.spot.top}%` }}
            >
              <span className={styles.schematicHotRing} />
              <span className={styles.schematicHotLab}>{model.title}</span>
            </span>
          )}
        </div>
        {model.caption ? <p className={styles.schematicCaption}>{model.caption}</p> : null}
        {model.explain.length > 0 && (
          <ul className={styles.schematicExplain}>
            {model.explain.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

