): { left: number; top: number } | null {
  if (school === 'wyckoff') {
    const hit = wyckoffSchematicHotspot(figureId as WyckoffSchematicId, key);
    if (hit) return hit;
    for (const k of WYCKOFF_FALLBACK_KEYS) {
