  if (school === 'elliott') {
    return elliottSchematicHotspot(figureId as Parameters<typeof elliottSchematicHotspot>[0], key);
  }
  const map = HOT[`${school}/${figureId}`];
  if (!map) return null;
  if (map[key]) return map[key]!;
  const first = Object.values(map)[0];
  return first ?? null;
}

