'use client';

import { useMemo, useState } from 'react';
import type { MergedDeskElliottRead } from '@/lib/mergedDeskElliottWave';
import type { ElliottSchematicId } from '@/lib/mergedDeskElliottWave';
import { elliottHotspotKey } from '@/lib/mergedDeskElliottSchematic';
import {
  schoolFigures,
  schoolHint,
  schoolSchematicHotspot,
  type ClickableSchool,
  type SchoolSchematicPin,
} from '@/lib/mergedDeskSchoolSchematicCatalog';
import { formatSchematicPrice } from '@/lib/mergedDeskSchematicSeatPrice';
import styles from './MergedAnalysisDesk.module.css';

type Props = {
  school: ClickableSchool;
  pin?: SchoolSchematicPin | null;
  elliott?: MergedDeskElliottRead | null;
  lastPrice?: number | null;
  onClose: () => void;
};

export function MergedDeskSchematicViewer({ school, pin, elliott, lastPrice, onClose }: Props) {
  const figures = schoolFigures(school);
  const [figOverride, setFigOverride] = useState<string | null>(null);
  const figId = figOverride ?? pin?.figureId ?? figures[0]?.id ?? '';
  const fig = figures.find((f) => f.id === figId) ?? figures[0] ?? null;

  const model = useMemo(() => {
    if (!fig) return null;
    const title = pin?.titleEn || pin?.headlineKo || fig.tabKo;
    let key = pin?.hotspotKey ?? '';
    if (school === 'elliott' && elliott) {
      key = elliottHotspotKey(elliott, fig.id as ElliottSchematicId);
    }
    const spot = schoolSchematicHotspot(school, fig.id, key || '_');
    const spotPx = pin?.eventPrice;
    const nowPx = Number.isFinite(lastPrice as number)
      ? Number(lastPrice)
      : Number.isFinite(pin?.lastPrice)
        ? Number(pin!.lastPrice)
        : spotPx;
    const side = pin?.seatSide ?? (pin?.eventLow ? 'long' : pin ? 'short' : 'wait');
    const seatKo = pin?.seatKo ?? (side === 'long' ? '롱 자리' : side === 'short' ? '숏 자리' : '대기');
    return {
      title,
      hint: schoolHint(school),
      src: fig.src,
      alt: pin?.headlineKo || fig.tabKo,
      spot,
      lowish: side === 'long' || (side === 'wait' && (pin?.eventLow ?? true)),
      side,
      seatKo,
      spotPx,
      nowPx,
      invalKo: pin?.invalKo ?? '확정 진입 아님 · 조건부 해석.',
      explain: pin?.explainKo ?? ['현재 자리는 미검출. 교재 도식만 표시. 확정 아님.'],
      caption: fig.captionKo,
    };
  }, [fig, pin, school, elliott, lastPrice]);

  if (!model) return null;

  const sideClass =
    model.side === 'long'
      ? styles.schematicSeatLong
      : model.side === 'short'
        ? styles.schematicSeatShort
        : styles.schematicSeatWait;

  return (
    <div
      className={styles.schematicBackdrop}
      role="dialog"
      aria-label={`${school} 도식`}
      onClick={onClose}
    >
      <div className={styles.schematicPanel} onClick={(e) => e.stopPropagation()}>
        <div className={styles.schematicHead}>
          <strong>
            지금 자리 · {model.title}
            {Number.isFinite(model.spotPx) ? ` · ${formatSchematicPrice(model.spotPx!)}` : ''}
          </strong>
          <button type="button" className={styles.schematicClose} onClick={onClose}>
            닫기
          </button>
        </div>
        <p className={styles.schematicHint}>
          {model.hint} 도식 점 = 분석가 · 아래 띠 = 롱/숏 후보(확정 아님).
        </p>
        {figures.length > 1 && (
          <div className={styles.schematicTabs}>
            {figures.map((f) => (
              <button
                key={f.id}
                type="button"
                className={`${styles.schematicTab} ${fig?.id === f.id ? styles.schematicTabOn : ''}`}
                onClick={() => setFigOverride(f.id)}
              >
                {f.tabKo}
              </button>
            ))}
          </div>
        )}
        <div className={styles.schematicImgWrap}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={model.src} alt={model.alt} className={styles.schematicImg} />
          {model.spot && (
            <span
              className={`${styles.schematicHot} ${
                model.side === 'long'
                  ? styles.schematicHotGreen
                  : model.side === 'short'
                    ? styles.schematicHotRed
                    : styles.schematicHotWait
              }`}
              style={{ left: `${model.spot.left}%`, top: `${model.spot.top}%` }}
            >
              <span className={styles.schematicHotRing} />
              <span className={`${styles.schematicHotCard} ${sideClass}`}>
                <span className={styles.schematicHotName}>{model.title}</span>
                <span className={styles.schematicHotPx}>
                  {Number.isFinite(model.spotPx) ? formatSchematicPrice(model.spotPx!) : '—'}
                </span>
                <span className={styles.schematicHotSide}>{model.seatKo}</span>
              </span>
            </span>
          )}
        </div>
        <div className={`${styles.schematicSeatBar} ${sideClass}`}>
          <span className={styles.schematicSeatTag}>{model.seatKo}</span>
          <span>
            분석가{' '}
            <strong>{Number.isFinite(model.spotPx) ? formatSchematicPrice(model.spotPx!) : '—'}</strong>
          </span>
          <span>
            지금가{' '}
            <strong>{Number.isFinite(model.nowPx) ? formatSchematicPrice(model.nowPx!) : '—'}</strong>
          </span>
          <span className={styles.schematicSeatInval}>{model.invalKo}</span>
        </div>
        {model.caption ? <p className={styles.schematicCaption}>{model.caption}</p> : null}
        {model.explain.length > 0 && (
          <ul className={styles.schematicExplain}>
            {model.explain.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

