/**
 * 도식·차트 매수/매도 ZONE — 최근 캔들·ATR·HotZone으로 좁힘.
 * 전체 TR·넓은 피보 구간은 쓰지 않음. 확정 진입 아님.
 */
import type { Candle } from '@/types';
import { atrSeries } from '@/lib/indicators';

export type PriceBand = { lo: number; hi: number };

export function lastAtr(candles: Candle[] | undefined, period = 14): number {
  if (!candles || candles.length < 8) return 0;
  const s = atrSeries(candles, Math.min(period, candles.length - 1));
  const v = s[s.length - 1] ?? 0;
  return Number.isFinite(v) && v > 0 ? v : 0;
}

function band(a: number, b: number): PriceBand {
  return { lo: Math.min(a, b), hi: Math.max(a, b) };
}

function intersect(a: PriceBand, b: PriceBand): PriceBand | null {
  const lo = Math.max(a.lo, b.lo);
  const hi = Math.min(a.hi, b.hi);
  if (!(hi > lo)) return null;
  return { lo, hi };
}

function clampHeight(b: PriceBand, cap: number): PriceBand {
  const h = b.hi - b.lo;
  if (h <= cap) return b;
  const mid = (b.lo + b.hi) / 2;
  return { lo: mid - cap / 2, hi: mid + cap / 2 };
}

/** 최근 봉 기준 국소 공급(매도) / 수요(매수) 얇은 띠. */
export function localCandleBand(
  candles: Candle[],
  last: number,
  side: 'buy' | 'sell',
  atr: number
): PriceBand {
  const slice = candles.slice(-12);
  const cap = Math.max(
    atr > 0 ? atr * 0.85 : Math.abs(last) * 0.004,
    Math.abs(last) * 0.0015
  );
  const maxCap = Math.min(cap, Math.abs(last) * 0.0075);
  if (side === 'sell') {
    const hi = Math.max(...slice.map((c) => c.high), last);
    return band(hi - maxCap, hi);
  }
  const lo = Math.min(...slice.map((c) => c.low), last);
  return band(lo, lo + maxCap);
}

/**
 * 넓은 피보/TR을 국소 캔들·HotZone과 교집합.
 * 교집합 없으면 국소 띠만. 높이는 ATR·0.75% 캡.
 */
export function tightenZoneBand(params: {
  lo?: number;
  hi?: number;
  candles?: Candle[];
  last: number;
  side: 'buy' | 'sell';
  hot?: PriceBand | null;
}): PriceBand | undefined {
  const last = params.last;
  if (!Number.isFinite(last)) return undefined;
  const candles = params.candles ?? [];
  const atr = lastAtr(candles) || Math.abs(last) * 0.004;
  const cap = Math.min(Math.max(atr * 0.95, Math.abs(last) * 0.002), Math.abs(last) * 0.0075);
  const local = candles.length >= 8 ? localCandleBand(candles, last, params.side, atr) : null;

  const cands: PriceBand[] = [];
  if (params.hot && params.hot.hi > params.hot.lo) cands.push(params.hot);
  if (Number.isFinite(params.lo) && Number.isFinite(params.hi) && params.hi! > params.lo!) {
    cands.push({ lo: params.lo!, hi: params.hi! });
  }
  if (local) cands.push(local);

  let z: PriceBand | null = null;
  if (params.hot && local) z = intersect(params.hot, local);
  if (!z && Number.isFinite(params.lo) && Number.isFinite(params.hi) && local) {
    z = intersect({ lo: params.lo!, hi: params.hi! }, local);
  }
  if (!z && params.hot) z = params.hot;
  if (!z && local) z = local;
  if (!z && cands[0]) z = cands[0];
  if (!z) {
    return params.side === 'sell'
      ? band(last, last + cap * 0.35)
      : band(last - cap * 0.35, last);
  }
  return clampHeight(z, cap);
}

/**
 * 최근 캔들 스윙 형태 ↔ 교재 도식 자리 유사도.
 * 정규화 RMSE + 다리 방향. 확정 카운트 아님.
 */
import type { Candle } from '@/types';
import { detectZigzagPivots } from '@/lib/candleAnalysisElliottMvp';
import type { MergedDeskElliottRead } from '@/lib/mergedDeskElliottWave';
import type { MergedDeskWyckoffRead } from '@/lib/mergedDeskWyckoffCycle';
import {
  listSchoolHotspots,
  type ClickableSchool,
  type SchoolSchematicPin,
} from '@/lib/mergedDeskSchoolSchematicCatalog';

export type SchematicTwin = {
  key: string;
  left: number;
  top: number;
  score: number;
  labelKo: string;
  engine: boolean;
};

export type SchematicShapeHit = {
  school: ClickableSchool;
  figureId: string;
  hotspotKey: string;
  left: number;
  top: number;
  score: number;
  labelKo: string;
  similarKo: string;
  twins: SchematicTwin[];
};

const LAB: Record<string, string> = {
  p0: '시작',
  '1': '파동1',
  '2': '파동2 눌림',
  '3': '파동3',
  '4': '파동4 눌림',
  '5': '파동5',
  A: 'A조정',
  B: 'B반등',
  C: 'C하락',
  w3: '3파확장',
  w5: '5파확장',
  w1: '1파확장',
  '4x': '확장 W4',
  '5x': '확장 W5',
  PS: 'PS',
  SC: 'SC',
  AR: 'AR',
  ST_A: 'Phase A ST',
  ST_B: 'Phase B ST',
  SPRING: '스프링',
  TEST: '테스트',
  LPS: 'LPS',
  SOS: 'SOS',
  BU: 'BU',
  E: 'Phase E',
  PSY: 'PSY',
  BC: 'BC',
  UTAD: 'UTAD',
  LPSY: 'LPSY',
  SOW: 'SOW',
  SOW_B: 'Phase B SOW',
  UT_B: 'Phase B UT',
  ACC: '축적',
  MARKUP: '마크업',
  DIST: '분배',
  MARKDOWN: '마크다운',
  HH2: 'HH',
  HL2: 'HL 눌림',
  HH3: 'HH3',
  LH2: 'LH',
  LL2: 'LL',
  LH3: 'LH3',
  NOW: '지금',
  BREAK: '돌파',
  HEAD: '헤드',
  LS: '왼어깨',
  RS: '오른어깨',
  NECK: '넥라인',
  P1: 'P1',
  P2: 'P2',
  T1: 'T1',
  T2: 'T2',
  APEX: '꼭지',
  COIL: '수축',
  FLAG: '깃발',
  POLE: '폴',
  BRK: '이탈',
  HANDLE: '핸들',
  CUP: '컵',
  D: 'D PRZ',
  X: 'X',
  BOS: 'BOS',
  CHOCH: 'CHoCH',
  FVG: 'FVG',
  OB: 'OB',
  SWEEP: '스윕',
  PO3: 'PO3',
  H1: 'H1',
  H2: 'H2',
  TR: '타이트TR',
  PB: '눌림',
  TREND: '추세다리',
  r382: '0.382',
  r50: '0.50',
  r618: '0.618',
  r786: '0.786',
  e100: '1.0확장',
  e127: '1.272',
  e162: '1.618',
  ABOVE: '위',
  BELOW: '아래',
  INSIDE: '안',
  POC: 'POC',
  VAH: 'VAH',
  VAL: 'VAL',
  hammer: '망치',
  star: '유성',
  engulf: '장악',
  doji: '도지',
  morning: '샛별',
};

export function schematicHotspotLabelKo(key: string): string {
  return LAB[key] ?? key;
}

function resample(ys: number[], n: number): number[] {
  if (ys.length === 0) return Array(n).fill(0.5);
  if (ys.length === 1) return Array(n).fill(ys[0]);
  const out: number[] = [];
  for (let i = 0; i < n; i++) {
    const t = (i / Math.max(1, n - 1)) * (ys.length - 1);
    const j = Math.floor(t);
    const f = t - j;
    const a = ys[j]!;
    const b = ys[Math.min(ys.length - 1, j + 1)]!;
    out.push(a + (b - a) * f);
  }
  return out;
}

function scoreSeries(live: number[], tmpl: number[]): number {
  const n = Math.min(8, Math.max(3, Math.min(live.length, tmpl.length)));
  if (live.length < 2 || tmpl.length < 2) return 0;
  const a = resample(live.slice(-Math.max(n, live.length)), n);
  const b = resample(tmpl.slice(-Math.max(n, tmpl.length)), n);
  let sse = 0;
  let dir = 0;
  for (let i = 0; i < n; i++) sse += (a[i]! - b[i]!) ** 2;
  for (let i = 1; i < n; i++) {
    const da = a[i]! - a[i - 1]!;
    const db = b[i]! - b[i - 1]!;
    if (Math.abs(da) < 1e-9 && Math.abs(db) < 1e-9) dir += 1;
    else if (da === 0 || db === 0) dir += 0.4;
    else if (Math.sign(da) === Math.sign(db)) dir += 1;
  }
  const rmse = Math.sqrt(sse / n);
  const shape = 1 - Math.min(1, rmse * 1.35);
  const dirHit = dir / Math.max(1, n - 1);
  return Math.round(100 * (0.58 * shape + 0.42 * dirHit));
}

function liveNormYs(candles: Candle[] | undefined, elliott?: MergedDeskElliottRead | null): number[] {
  const prices: number[] = [];
  const L = elliott?.levels;
  if (L) {
    prices.push(L.p0, L.p1, L.p2);
    if (L.p3 != null) prices.push(L.p3);
    if (L.p4 != null) prices.push(L.p4);
    if (L.p5 != null) prices.push(L.p5);
    if (L.a != null) prices.push(L.a);
    if (L.b != null) prices.push(L.b);
    if (L.c != null) prices.push(L.c);
  } else if (candles && candles.length >= 24) {
    detectZigzagPivots(candles, 4, 4)
      .slice(-8)
      .forEach((p) => prices.push(p.price));
  }
  if (candles?.length) prices.push(candles[candles.length - 1]!.close);
  const finite = prices.filter((p) => Number.isFinite(p));
  if (finite.length < 2) return [];
  const lo = Math.min(...finite);
  const hi = Math.max(...finite);
  const span = hi - lo || 1;
  return finite.map((p) => (p - lo) / span);
}

function tmplNormYs(spots: Array<{ top: number }>, endIdx: number): number[] {
  const slice = spots.slice(0, endIdx + 1);
  const ys = slice.map((s) => 1 - s.top / 100);
  const lo = Math.min(...ys);
  const hi = Math.max(...ys);
  const span = hi - lo || 1;
  return ys.map((y) => (y - lo) / span);
}

export function matchSchematicShape(params: {
  school: ClickableSchool;
  figureId: string;
  candles?: Candle[];
  pin?: SchoolSchematicPin | null;
  elliott?: MergedDeskElliottRead | null;
  wyckoff?: MergedDeskWyckoffRead | null;
}): SchematicShapeHit | null {
  const spots = listSchoolHotspots(params.school, params.figureId);
  if (!spots.length) return null;
  const live = liveNormYs(params.candles, params.school === 'elliott' ? params.elliott : null);
  const engineKey = params.pin?.hotspotKey ?? '';
  const twins: SchematicTwin[] = spots.map((s, i) => {
    let score = live.length >= 2 ? scoreSeries(live, tmplNormYs(spots, i)) : 40;
    if (engineKey && s.key === engineKey) score = Math.min(100, score + 22);
    if (params.elliott && params.school === 'elliott') {
      const w = params.elliott.wave;
      if (s.key === w || (w === '4' && s.key === '4x') || (w === '5' && s.key === '5x')) {
        score = Math.min(100, score + 18);
      }
    }
    if (params.wyckoff && params.school === 'wyckoff') {
      const ev = String(params.wyckoff.event || '');
      if (ev && s.key.toUpperCase().includes(ev.toUpperCase().slice(0, 3))) {
        score = Math.min(100, score + 12);
      }
    }
    return {
      key: s.key,
      left: s.left,
      top: s.top,
      score,
      labelKo: schematicHotspotLabelKo(s.key),
      engine: !!engineKey && s.key === engineKey,
    };
  });
  twins.sort((a, b) => b.score - a.score);
  const best = twins[0]!;
  const alt = twins[1];
  const similarKo =
    best.score < 38
      ? `유사 낮음 · 가까운 자리 ${best.labelKo} (${best.score}%)`
      : `지금 캔들 ≈ ${best.labelKo} (${best.score}%)${alt ? ` · 차선 ${alt.labelKo} ${alt.score}%` : ''}`;
  return {
    school: params.school,
    figureId: params.figureId,
    hotspotKey: best.key,
    left: best.left,
    top: best.top,
    score: best.score,
    labelKo: best.labelKo,
    similarKo,
    twins: twins.sort((a, b) => a.left - b.left || a.top - b.top),
  };
}

