/**
 * 차트 스윙 ↔ 교재 도식: 자리 유사 + 국소 ZONE.
 * X=도식 핫스팟, Y=실제 가격을 도식 고저에 비율 투영. 확정 아님.
 */
import type { Candle } from '@/types';
import { detectZigzagPivots } from '@/lib/candleAnalysisElliottMvp';
import type { MergedDeskElliottRead } from '@/lib/mergedDeskElliottWave';
import type { MergedDeskWyckoffRead } from '@/lib/mergedDeskWyckoffCycle';
import {
  listSchoolHotspots,
  type ClickableSchool,
  type SchoolSchematicPin,
} from '@/lib/mergedDeskSchoolSchematicCatalog';
import { formatSchematicPrice, type SchematicSeatRole } from '@/lib/mergedDeskSchematicSeatPrice';
import { matchSchematicShape, type SchematicShapeHit } from '@/lib/mergedDeskSchematicShapeMatch';
import { tightenZoneBand, type PriceBand } from '@/lib/mergedDeskSchematicTightZone';

export type SchematicVerdict = '빅롱' | '롱' | '숏' | '폭락' | '대기';

export type SchematicRatioPt = { x: number; y: number; label: string; price: number; key?: string };

export type SchematicZoneBox = {
  left: number;
  top: number;
  width: number;
  height: number;
  lo: number;
  hi: number;
};

export type SchematicRatioOverlay = {
  plot: { left: number; top: number; width: number; height: number };
  path: SchematicRatioPt[];
  now: SchematicRatioPt;
  match: SchematicShapeHit | null;
  buyZone?: SchematicZoneBox;
  sellZone?: SchematicZoneBox;
  bounceY?: number;
  dumpY?: number;
  bounceTo?: number;
  dumpTo?: number;
  verdict: SchematicVerdict;
  verdictKo: string;
};

const PLOT = { left: 8, top: 12, width: 86, height: 76 };

function yOf(price: number, lo: number, hi: number): number {
  const span = hi - lo || 1;
  const t = Math.max(0, Math.min(1, (price - lo) / span));
  return PLOT.top + (1 - t) * PLOT.height;
}

export function resolveSchematicVerdict(
  pin: SchoolSchematicPin | null | undefined,
  elliott?: MergedDeskElliottRead | null,
  wyckoff?: MergedDeskWyckoffRead | null,
  lastPrice?: number
): SchematicVerdict {
  if (wyckoff?.macro === 'markup' || wyckoff?.event === 'SOS' || (wyckoff?.macro === 'accumulation' && wyckoff.phase === 'E')) {
    return '빅롱';
  }
  if (elliott?.bias === 'bullish' && elliott.extension === 'w3' && (elliott.wave === '3' || elliott.wave === '5')) {
    const L = elliott.levels;
    if (L?.p0 != null && L.p5 != null && lastPrice != null) {
      const pos = (lastPrice - L.p0) / Math.max(1e-9, L.p5 - L.p0);
      if (pos >= 0.72) return '빅롱';
    } else return '빅롱';
  }
  if (wyckoff?.macro === 'markdown' || elliott?.wave === 'C' || elliott?.wave === 'A') {
    if (elliott?.bias === 'bullish' && (elliott.wave === 'A' || elliott.wave === 'C')) return '폭락';
    if (elliott?.bias === 'bearish' && (elliott.wave === 'A' || elliott.wave === 'C')) return '롱';
    if (wyckoff?.macro === 'markdown') return '폭락';
  }
  const role = pin?.seatRole as SchematicSeatRole | undefined;
  if (role === 'pullback-long' || role === 'run-up') return '롱';
  if (role === 'rally-short') return '숏';
  if (role === 'run-down') return '폭락';
  if (pin?.seatSide === 'long') return '롱';
  if (pin?.seatSide === 'short') return '숏';
  return '대기';
}

function liveSwingPts(
  elliott?: MergedDeskElliottRead | null,
  candles?: Candle[],
  last?: number
): Array<{ key: string; price: number; label: string }> {
  const pts: Array<{ key: string; price: number; label: string }> = [];
  const L = elliott?.levels;
  if (L) {
    pts.push({ key: 'p0', price: L.p0, label: '0' });
    pts.push({ key: '1', price: L.p1, label: '1' });
    pts.push({ key: '2', price: L.p2, label: '2' });
    if (L.p3 != null) pts.push({ key: '3', price: L.p3, label: '3' });
    if (L.p4 != null) pts.push({ key: '4', price: L.p4, label: '4' });
    if (L.p5 != null) pts.push({ key: '5', price: L.p5, label: '5' });
    if (L.a != null) pts.push({ key: 'A', price: L.a, label: 'A' });
    if (L.b != null) pts.push({ key: 'B', price: L.b, label: 'B' });
    if (L.c != null) pts.push({ key: 'C', price: L.c, label: 'C' });
  } else if (candles && candles.length >= 24) {
    detectZigzagPivots(candles, 4, 4)
      .slice(-8)
      .forEach((p, i) => pts.push({ key: `z${i}`, price: p.price, label: String(i + 1) }));
  }
  if (last != null && Number.isFinite(last)) pts.push({ key: 'now', price: last, label: '지금' });
  return pts.filter((p) => Number.isFinite(p.price));
}

function mapPriceToTop(price: number, loP: number, hiP: number, loTop: number, hiTop: number): number {
  const t = Math.max(0, Math.min(1, (price - loP) / (hiP - loP || 1)));
  return loTop + t * (hiTop - loTop);
}

function smallZoneBox(
  matchLeft: number,
  matchTop: number,
  lo: number,
  hi: number,
  topOf: (p: number) => number
): SchematicZoneBox {
  const yHi = topOf(hi);
  const yLo = topOf(lo);
  const top = Math.min(yHi, yLo);
  const height = Math.max(5.5, Math.min(11, Math.abs(yLo - yHi)));
  const width = 12;
  return {
    left: Math.max(2, Math.min(86, matchLeft - width / 2)),
    top: Math.max(4, Math.min(88, top === matchTop ? matchTop - height / 2 : top)),
    width,
    height,
    lo,
    hi,
  };
}

export function buildSchematicRatioOverlay(params: {
  school?: ClickableSchool | null;
  figureId?: string;
  pin?: SchoolSchematicPin | null;
  elliott?: MergedDeskElliottRead | null;
  wyckoff?: MergedDeskWyckoffRead | null;
  candles?: Candle[];
  lastPrice?: number | null;
  buyBand?: PriceBand | null;
  sellBand?: PriceBand | null;
}): SchematicRatioOverlay | null {
  const last =
    Number.isFinite(params.lastPrice as number)
      ? Number(params.lastPrice)
      : params.candles?.length
        ? params.candles[params.candles.length - 1]!.close
        : params.pin?.eventPrice;
  if (!Number.isFinite(last)) return null;

  const school = params.school ?? params.pin?.school ?? null;
  const figureId = params.figureId ?? params.pin?.figureId ?? '';
  const match =
    school && figureId
      ? matchSchematicShape({
          school,
          figureId,
          candles: params.candles,
          pin: params.pin,
          elliott: params.elliott,
          wyckoff: params.wyckoff,
        })
      : null;

  const spots = school && figureId ? listSchoolHotspots(school, figureId) : [];
  const swings = liveSwingPts(params.elliott, params.candles, last);
  const pairN = Math.min(spots.length, Math.max(0, swings.length - (swings[swings.length - 1]?.key === 'now' ? 1 : 0)));
  const paired: SchematicRatioPt[] = [];
  for (let i = 0; i < pairN; i++) {
    const s = spots[i]!;
    const p = swings[i]!;
    paired.push({ x: s.left, y: s.top, label: p.label, price: p.price, key: s.key });
  }

  const prices = paired.map((p) => p.price);
  prices.push(last!);
  const pin = params.pin;
  if (pin?.zoneLow != null) prices.push(pin.zoneLow);
  if (pin?.zoneHigh != null) prices.push(pin.zoneHigh);
  if (pin?.bounceTo != null) prices.push(pin.bounceTo);
  if (pin?.dumpTo != null) prices.push(pin.dumpTo);
  const loP = Math.min(...prices);
  const hiP = Math.max(...prices);
  const pad = (hiP - loP) * 0.06 || Math.abs(last!) * 0.008;
  const yLo = loP - pad;
  const yHi = hiP + pad;

  const tbTops = paired.length ? paired.map((p) => p.y) : spots.map((s) => s.top);
  const loTop = tbTops.length ? Math.max(...tbTops) : 78;
  const hiTop = tbTops.length ? Math.min(...tbTops) : 14;
  const topOf = (price: number) => mapPriceToTop(price, yLo, yHi, loTop, hiTop);

  const path: SchematicRatioPt[] = paired.map((p) => ({
    ...p,
    y: topOf(p.price),
  }));

  const nowSpot = match ?? (spots[spots.length - 1] ? { left: spots[spots.length - 1]!.left, top: spots[spots.length - 1]!.top } : null);
  const now: SchematicRatioPt = {
    x: nowSpot?.left ?? 88,
    y: topOf(last!),
    label: match?.labelKo ?? '지금',
    price: last!,
    key: match?.hotspotKey,
  };

  const sellish =
    pin?.seatRole === 'rally-short' || (pin?.seatSide === 'short' && pin.seatRole !== 'run-down');
  let buyZone: SchematicZoneBox | undefined;
  let sellZone: SchematicZoneBox | undefined;
  const zLo = pin?.zoneLow;
  const zHi = pin?.zoneHigh;
  if (zLo != null && zHi != null && zHi > zLo) {
    const box = smallZoneBox(now.x, match?.top ?? now.y, zLo, zHi, topOf);
    if (sellish) sellZone = box;
    else buyZone = box;
  } else {
    const side = sellish ? 'sell' : 'buy';
    const t = tightenZoneBand({
      candles: params.candles,
      last: last!,
      side,
      hot: sellish ? params.sellBand : params.buyBand,
    });
    if (t) {
      const box = smallZoneBox(now.x, match?.top ?? now.y, t.lo, t.hi, topOf);
      if (sellish) sellZone = box;
      else buyZone = box;
    }
  }

  const verdict = resolveSchematicVerdict(pin, params.elliott, params.wyckoff, last);
  return {
    plot: PLOT,
    path,
    now,
    match,
    buyZone,
    sellZone,
    bounceY: pin?.bounceTo != null ? topOf(pin.bounceTo) : undefined,
    dumpY: pin?.dumpTo != null ? topOf(pin.dumpTo) : undefined,
    bounceTo: pin?.bounceTo,
    dumpTo: pin?.dumpTo,
    verdict,
    verdictKo: match
      ? `${verdict} · ${match.similarKo} · ${formatSchematicPrice(last!)}`
      : `${verdict} · 지금 ${formatSchematicPrice(last!)}`,
  };
}

'use client';

import { useMemo, useState } from 'react';
import type { Candle } from '@/types';
import type { MergedDeskElliottRead } from '@/lib/mergedDeskElliottWave';
import type { MergedDeskWyckoffRead } from '@/lib/mergedDeskWyckoffCycle';
import type { ElliottSchematicId } from '@/lib/mergedDeskElliottWave';
import { elliottHotspotKey } from '@/lib/mergedDeskElliottSchematic';
import {
  schoolFigures,
  schoolHint,
  type ClickableSchool,
  type SchoolSchematicPin,
} from '@/lib/mergedDeskSchoolSchematicCatalog';
import { formatSchematicPrice } from '@/lib/mergedDeskSchematicSeatPrice';
import { buildSchematicRatioOverlay } from '@/lib/mergedDeskSchematicRatioOverlay';
import type { PriceBand } from '@/lib/mergedDeskSchematicTightZone';
import styles from './MergedAnalysisDesk.module.css';

type Props = {
  school: ClickableSchool;
  pin?: SchoolSchematicPin | null;
  elliott?: MergedDeskElliottRead | null;
  wyckoff?: MergedDeskWyckoffRead | null;
  candles?: Candle[];
  lastPrice?: number | null;
  buyBand?: PriceBand | null;
  sellBand?: PriceBand | null;
  onClose: () => void;
};

export function MergedDeskSchematicViewer({
  school,
  pin,
  elliott,
  wyckoff,
  candles,
  lastPrice,
  buyBand,
  sellBand,
  onClose,
}: Props) {
  const figures = schoolFigures(school);
  const [figOverride, setFigOverride] = useState<string | null>(null);
  const figId = figOverride ?? pin?.figureId ?? figures[0]?.id ?? '';
  const fig = figures.find((f) => f.id === figId) ?? figures[0] ?? null;

  const overlay = useMemo(
    () =>
      buildSchematicRatioOverlay({
        school,
        figureId: fig?.id,
        pin,
        elliott: school === 'elliott' ? elliott : null,
        wyckoff: school === 'wyckoff' ? wyckoff : null,
        candles,
        lastPrice,
        buyBand,
        sellBand,
      }),
    [pin, elliott, wyckoff, candles, lastPrice, school, fig?.id, buyBand, sellBand]
  );

  const model = useMemo(() => {
    if (!fig) return null;
    let key = pin?.hotspotKey ?? '';
    if (school === 'elliott' && elliott) {
      key = elliottHotspotKey(elliott, fig.id as ElliottSchematicId);
    }
    const nowPx = overlay?.now.price ?? lastPrice ?? pin?.lastPrice ?? pin?.eventPrice;
    const verdict = overlay?.verdict ?? '대기';
    return {
      title: overlay?.match?.labelKo || pin?.titleEn || pin?.headlineKo || fig.tabKo,
      hint: schoolHint(school),
      src: fig.src,
      alt: pin?.headlineKo || fig.tabKo,
      engineKey: key,
      seatKo: pin?.seatKo ?? overlay?.verdict ?? '대기',
      verdict,
      nowPx,
      zoneLow: overlay?.buyZone?.lo ?? overlay?.sellZone?.lo ?? pin?.zoneLow,
      zoneHigh: overlay?.buyZone?.hi ?? overlay?.sellZone?.hi ?? pin?.zoneHigh,
      bounceTo: pin?.bounceTo,
      dumpTo: pin?.dumpTo,
      bounceKo: pin?.bounceKo,
      invalKo: pin?.invalKo ?? '확정 진입 아님 · 조건부 해석.',
      explain: pin?.explainKo ?? ['현재 자리는 미검출. 교재 도식만 표시. 확정 아님.'],
      caption: fig.captionKo,
      similarKo: overlay?.match?.similarKo ?? '',
    };
  }, [fig, pin, school, elliott, lastPrice, overlay]);

  if (!model) return null;

  const sideClass =
    model.verdict === '빅롱' || model.verdict === '롱'
      ? styles.schematicSeatLong
      : model.verdict === '숏' || model.verdict === '폭락'
        ? styles.schematicSeatShort
        : styles.schematicSeatWait;

  const hasZone = Number.isFinite(model.zoneLow) && Number.isFinite(model.zoneHigh);
  const poly = overlay?.path.map((p) => `${p.x},${p.y}`).join(' ');
  const match = overlay?.match;
  const sellBox = overlay?.sellZone;
  const buyBox = overlay?.buyZone;

  return (
    <div
      className={styles.schematicBackdrop}
      role="dialog"
      aria-label={`${school} 도식`}
      onClick={onClose}
    >
      <div className={styles.schematicPanel} onClick={(e) => e.stopPropagation()}>
        <div className={styles.schematicHead}>
          <strong>
            결론 · {model.verdict}
            {Number.isFinite(model.nowPx) ? ` · ${formatSchematicPrice(model.nowPx!)}` : ''}
          </strong>
          <button type="button" className={styles.schematicClose} onClick={onClose}>
            닫기
          </button>
        </div>
        <p className={styles.schematicHint}>
