              >
                {f.tabKo}
              </button>
            ))}
          </div>
        )}
        <div className={styles.schematicImgWrap}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={model.src} alt={model.alt} className={styles.schematicImg} />
          {overlay && (
            <svg className={styles.schematicRatioSvg} viewBox="0 0 100 100" preserveAspectRatio="none">
              {poly && <polyline points={poly} className={styles.schematicLivePath} fill="none" />}
              {overlay.path.map((p) => (
                <circle key={`${p.label}-${p.x}`} cx={p.x} cy={p.y} r="0.7" className={styles.schematicLiveDot} />
              ))}
              {overlay.bounceY != null && match && (
                <line
                  x1={Math.max(2, match.left - 8)}
                  x2={Math.min(98, match.left + 8)}
                  y1={overlay.bounceY}
                  y2={overlay.bounceY}
                  className={styles.schematicBounceLine}
                />
              )}
              {overlay.dumpY != null && match && (
                <line
                  x1={Math.max(2, match.left - 8)}
                  x2={Math.min(98, match.left + 8)}
                  y1={overlay.dumpY}
                  y2={overlay.dumpY}
                  className={styles.schematicDumpLine}
                />
              )}
            </svg>
          )}
          {buyBox && (
            <span
              className={styles.schematicZoneBoxBuy}
              style={{
                left: `${buyBox.left}%`,
                top: `${buyBox.top}%`,
                width: `${buyBox.width}%`,
                height: `${buyBox.height}%`,
              }}
            >
              <span className={styles.schematicZoneBoxLab}>
                매수ZONE {formatSchematicPrice(buyBox.lo)}–{formatSchematicPrice(buyBox.hi)}
              </span>
            </span>
          )}
          {sellBox && (
            <span
              className={styles.schematicZoneBoxSell}
              style={{
                left: `${sellBox.left}%`,
                top: `${sellBox.top}%`,
                width: `${sellBox.width}%`,
                height: `${sellBox.height}%`,
              }}
            >
              <span className={styles.schematicZoneBoxLab}>
                매도ZONE {formatSchematicPrice(sellBox.lo)}–{formatSchematicPrice(sellBox.hi)}
              </span>
            </span>
          )}
          {match?.twins.map((t) => {
            const on = t.key === match.hotspotKey;
            return (
              <span
                key={t.key}
                className={`${styles.schematicTwin} ${on ? styles.schematicTwinOn : ''} ${
                  t.engine && !on ? styles.schematicTwinEngine : ''
                }`}
                style={{ left: `${t.left}%`, top: `${t.top}%` }}
                title={`${t.labelKo} · 유사 ${t.score}%${t.engine ? ' · 엔진카운트' : ''}`}
              >
                {(on || t.score >= 58 || t.engine) && (
                  <span className={styles.schematicTwinLab}>
                    {on ? `≈${t.labelKo} ${t.score}%` : t.engine ? `엔진 ${t.labelKo}` : t.labelKo}
                  </span>
                )}
              </span>
            );
          })}
          {match && overlay && (
            <span
              className={`${styles.schematicHot} ${
                model.verdict === '롱' || model.verdict === '빅롱'
                  ? styles.schematicHotGreen
                  : model.verdict === '숏' || model.verdict === '폭락'
                    ? styles.schematicHotRed
                    : styles.schematicHotWait
              }`}
              style={{ left: `${match.left}%`, top: `${match.top}%` }}
            >
              <span className={styles.schematicHotRing} />
              <span className={`${styles.schematicHotCard} ${sideClass}`}>
                <span className={styles.schematicHotName}>지금 캔들 ≈ {match.labelKo}</span>
                <span className={styles.schematicHotPx}>{formatSchematicPrice(overlay.now.price)}</span>
                <span className={styles.schematicHotSide}>
                  {model.verdict} · 유사 {match.score}%
                </span>
              </span>
            </span>
          )}
        </div>
        <div className={`${styles.schematicSeatBar} ${sideClass}`}>
          <span className={styles.schematicSeatTag}>{model.verdict}</span>
          <span>
            유사자리 <strong>{match?.labelKo ?? '—'}</strong>
            {match ? ` ${match.score}%` : ''}
          </span>
          <span>
            지금가 <strong>{Number.isFinite(model.nowPx) ? formatSchematicPrice(model.nowPx!) : '—'}</strong>
          </span>
          {hasZone && (
            <span>
              {sellBox && !buyBox ? '매도ZONE' : '매수ZONE'}{' '}
              <strong>
                {formatSchematicPrice(model.zoneLow!)}–{formatSchematicPrice(model.zoneHigh!)}
              </strong>
            </span>
          )}
          {Number.isFinite(model.bounceTo) && (
            <span>
              {model.bounceKo || '반등 목표'} <strong>{formatSchematicPrice(model.bounceTo!)}</strong>
            </span>
          )}
          {Number.isFinite(model.dumpTo) && (
            <span>
              폭락목표 <strong>{formatSchematicPrice(model.dumpTo!)}</strong>
            </span>
          )}
          <span className={styles.schematicSeatInval}>{model.invalKo}</span>
        </div>
        {model.caption ? <p className={styles.schematicCaption}>{model.caption}</p> : null}
        {model.explain.length > 0 && (
          <ul className={styles.schematicExplain}>
            {model.explain.map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

