/** 표시 문구로 묶음 — 존 캡션·흰 가로선 글자·축 라벨이 같은 말이면 같이 ON/OFF */
export function chartTextHideLabelKey(label: string): string {
  const t = String(label || '')
    .trim()
    .replace(/^흰글자·/, '')
    .replace(/^축·/, '')
    .replace(/^◆+/g, '')
    .replace(/\s+/g, '')
    .replace(/[·•]/g, '');
  if (!t) return '';
  return `text:${t.slice(0, 48)}`;
}

function textKeyMatches(hiddenKey: string, labelKey: string): boolean {
  if (!hiddenKey.startsWith('text:') || !labelKey.startsWith('text:')) return hiddenKey === labelKey;
  const a = hiddenKey.slice(5);
  const b = labelKey.slice(5);
  if (!a || !b) return false;
  if (a === b) return true;
  if (a.length >= 4 && b.startsWith(a)) return true;
  if (b.length >= 4 && a.startsWith(b)) return true;
  return false;
}

input.new_string:
/** 표시 문구로 묶음. `흰글자·` = 우측 흰 글자만, 그 외 = 노란/알약 캡션 */
export function chartTextHideLabelKey(label: string): string {
  const raw = String(label || '').trim();
  const white = raw.startsWith('흰글자·');
  const t = raw
    .replace(/^흰글자·/, '')
    .replace(/^노랑·/, '')
    .replace(/^축·/, '')
    .replace(/^◆+/g, '')
    .replace(/\s+/g, '')
    .replace(/[·•]/g, '');
  if (!t) return '';
  return `${white ? 'textw' : 'text'}:${t.slice(0, 48)}`;
}

function textKeyKind(key: string): 'white' | 'pill' | '' {
  if (key.startsWith('textw:')) return 'white';
  if (key.startsWith('text:')) return 'pill';
  return '';
}

function textKeyMatches(hiddenKey: string, labelKey: string): boolean {
  const hk = textKeyKind(hiddenKey);
  const lk = textKeyKind(labelKey);
  if (!hk || !lk || hk !== lk) return false;
  const a = hiddenKey.slice(hk === 'white' ? 6 : 5);
  const b = labelKey.slice(lk === 'white' ? 6 : 5);
  if (!a || !b) return false;
  if (a === b) return true;
  /** 흰글자는 $$$$롱-65 / $$$$롱-01 을 따로 둠 — 접두 병합 금지 */
  if (hk === 'white') return false;
  if (a.length >= 4 && b.startsWith(a)) return true;
  if (b.length >= 4 && a.startsWith(b)) return true;
  return false;
