function liveSwingPts(
  elliott?: MergedDeskElliottRead | null,
  candles?: Candle[],
  last?: number
): Array<{ key: string; price: number; label: string }> {
  const pts: Array<{ key: string; price: number; label: string }> = [];
  const L = elliott?.levels;
  if (L) {
    pts.push({ key: 'p0', price: L.p0, label: '0' });
    pts.push({ key: '1', price: L.p1, label: '1' });
    pts.push({ key: '2', price: L.p2, label: '2' });
    if (L.p3 != null) pts.push({ key: '3', price: L.p3, label: '3' });
    if (L.p4 != null) pts.push({ key: '4', price: L.p4, label: '4' });
    if (L.p5 != null) pts.push({ key: '5', price: L.p5, label: '5' });
    if (L.a != null) pts.push({ key: 'A', price: L.a, label: 'A' });
    if (L.b != null) pts.push({ key: 'B', price: L.b, label: 'B' });
    if (L.c != null) pts.push({ key: 'C', price: L.c, label: 'C' });
  } else if (candles && candles.length >= 24) {
    detectZigzagPivots(candles, 4, 4)
      .slice(-8)
      .forEach((p, i) => pts.push({ key: `z${i}`, price: p.price, label: String(i + 1) }));
  }
  if (last != null && Number.isFinite(last)) pts.push({ key: 'now', price: last, label: '지금' });
  return pts.filter((p) => Number.isFinite(p.price));
}

