const PANEL_PANE_LIFT_KEY = 'ailongshort-merged-desk-chart-settings-panes-v1';

type PaneLiftState = {
  yellowOpen: boolean;
  whiteOpen: boolean;
  yellowH: number;
  whiteH: number;
};

const DEFAULT_PANE_LIFT: PaneLiftState = {
  yellowOpen: true,
  whiteOpen: true,
  yellowH: 240,
  whiteH: 420,
};

function clampPaneH(n: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, Math.round(n)));
}

function readPaneLift(): PaneLiftState {
  if (typeof window === 'undefined') return DEFAULT_PANE_LIFT;
  try {
    const raw = window.localStorage.getItem(PANEL_PANE_LIFT_KEY);
    if (!raw) return DEFAULT_PANE_LIFT;
    const j = JSON.parse(raw) as Partial<PaneLiftState>;
    return {
      yellowOpen: j.yellowOpen !== false,
      whiteOpen: j.whiteOpen !== false,
      yellowH: clampPaneH(Number(j.yellowH) || DEFAULT_PANE_LIFT.yellowH, 120, 560),
      whiteH: clampPaneH(Number(j.whiteH) || DEFAULT_PANE_LIFT.whiteH, 200, 780),
    };
  } catch {
    return DEFAULT_PANE_LIFT;
  }
}

