  const top = Math.min(yHi, yLo);
  const height = Math.max(5.5, Math.min(11, Math.abs(yLo - yHi)));
  const width = 12;
  return {
    left: Math.max(2, Math.min(86, matchLeft - width / 2)),
    top: Math.max(4, Math.min(88, top === matchTop ? matchTop - height / 2 : top)),
    width,
    height,
    lo,
    hi,
  };
}

