function mapPriceToTop(price: number, loP: number, hiP: number, loTop: number, hiTop: number): number {
  const t = Math.max(0, Math.min(1, (price - loP) / (hiP - loP || 1)));
  return loTop + t * (hiTop - loTop);
}

const BUY_FACE_KEY = /^(AR|SOW|SOW_B|SC|PS|SPRING|LPS|TEST|HL2|T1|T2|VAL|LOW|BELOW|PB|BOT|TROUGH)$/i;
const SELL_FACE_KEY = /^(PSY|BC|UT|UT_B|UTAD|LPSY|SOS|HH2|HH3|P1|P2|VAH|HIGH|ABOVE|HEAD|RS|CREST|TOP)$/i;

function faceAnchor(
  spots: Array<{ key: string; left: number; top: number }>,
  side: 'buy' | 'sell'
): Array<{ left: number; top: number }> {
  if (!spots.length) return [];
  const re = side === 'buy' ? BUY_FACE_KEY : SELL_FACE_KEY;
  const hit = spots.filter((s) => re.test(s.key));
  if (hit.length) return hit;
  const sorted = [...spots].sort((a, b) => a.top - b.top);
  const n = Math.max(1, Math.ceil(sorted.length / 3));
  return side === 'sell' ? sorted.slice(0, n) : sorted.slice(-n);
}

/** 도식 지지/저항 자리에 매수·매도 면. 가격은 라벨용, 박스는 교재 자리. */
function schematicFaceBox(
  spots: Array<{ key: string; left: number; top: number }>,
  side: 'buy' | 'sell',
  lo: number,
  hi: number
): SchematicZoneBox {
  const used = faceAnchor(spots, side);
  const lefts = used.map((s) => s.left);
  const tops = used.map((s) => s.top);
  const left = Math.max(3, (lefts.length ? Math.min(...lefts) : 12) - 5);
  const right = Math.min(96, (lefts.length ? Math.max(...lefts) : 70) + 10);
  const midTop = tops.length ? (Math.min(...tops) + Math.max(...tops)) / 2 : side === 'buy' ? 72 : 22;
  const span = tops.length ? Math.max(...tops) - Math.min(...tops) : 0;
  const height = Math.max(12, Math.min(20, span + 10));
  const top = Math.max(5, Math.min(82, midTop - height / 2));
  return {
    left,
    top,
    width: Math.max(22, right - left),
    height,
    lo,
    hi,
  };
}

