input.new_string:
type OverlayFlags = {
  showLine: boolean;
  showZones: boolean;
  showLabs: boolean;
  opacity: number;
};

type FigureKind = 'plain' | 'seat' | 'compare' | 'overlay';

function SchematicFigure({
  src,
  alt,
  overlay,
  nowPhrase,
  sideClass,
  verdict,
  kind,
  flags,
}: {
  src: string;
  alt: string;
  overlay: SchematicRatioOverlay | null;
  nowPhrase: string;
  sideClass: string;
  verdict: string;
  kind: FigureKind;
  flags: OverlayFlags;
}) {
  const trailPoly = overlay?.trail.map((p) => `${p.x},${p.y}`).join(' ');
  const poly = overlay?.path.map((p) => `${p.x},${p.y}`).join(' ');
  const match = overlay?.match;
  const nowPt = overlay?.now;
  const sellBox = overlay?.sellZone;
  const buyBox = overlay?.buyZone;
  const hideTextbook = kind === 'compare';
  const showCompare = kind === 'compare' || kind === 'overlay';
  const showSeat = kind === 'seat' || kind === 'overlay' || kind === 'compare';
  const layerOpacity = kind === 'seat' ? 1 : Math.max(0.15, Math.min(1, flags.opacity / 100));

  return (
    <div className={`${styles.schematicImgWrap} ${hideTextbook ? styles.schematicImgWrapBare : ''}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={src} alt={hideTextbook ? '' : alt} className={hideTextbook ? styles.schematicImgGhost : styles.schematicImg} />
      {overlay && showSeat && (
        <div className={styles.schematicOverlayLayer} style={{ opacity: layerOpacity }}>
          {showCompare && flags.showLine && (
            <svg className={styles.schematicRatioSvg} viewBox="0 0 100 100" preserveAspectRatio="none">
              {trailPoly && (
                <polyline points={trailPoly} className={styles.schematicTrailPath} fill="none" />
              )}
              {poly && (
                <>
                  <polyline points={poly} className={styles.schematicLivePathHalo} fill="none" />
                  <polyline points={poly} className={styles.schematicLivePath} fill="none" />
                </>
              )}
              {overlay.trail.map((p) => {
                const isNow = p.key != null && p.key === nowPt?.key;
                const onPath = overlay.path.some((q) => q.key === p.key);
                return (
                  <circle
                    key={`p-${p.key ?? p.label}-${p.x}`}
                    cx={p.x}
                    cy={p.y}
                    r={isNow ? 2.05 : onPath ? 1.05 : 0.8}
                    className={
                      isNow
                        ? styles.schematicNowDot
                        : onPath
                          ? styles.schematicLiveDot
                          : styles.schematicTrailDot
                    }
                  />
                );
              })}
              {nowPt && (
                <g className={styles.schematicNowCross}>
                  <line x1={nowPt.x - 6.2} x2={nowPt.x + 6.2} y1={nowPt.y} y2={nowPt.y} />
                  <line x1={nowPt.x} x2={nowPt.x} y1={nowPt.y - 6.2} y2={nowPt.y + 6.2} />
                </g>
              )}
              {overlay.bounceY != null && match && (
                <line
                  x1={Math.max(2, match.left - 8)}
                  x2={Math.min(98, match.left + 8)}
                  y1={overlay.bounceY}
                  y2={overlay.bounceY}
                  className={styles.schematicBounceLine}
                />
              )}
              {overlay.dumpY != null && match && (
                <line
                  x1={Math.max(2, match.left - 8)}
                  x2={Math.min(98, match.left + 8)}
                  y1={overlay.dumpY}
                  y2={overlay.dumpY}
                  className={styles.schematicDumpLine}
                />
              )}
            </svg>
          )}
          {kind === 'seat' && nowPt && (
            <svg className={styles.schematicRatioSvg} viewBox="0 0 100 100" preserveAspectRatio="none">
              <g className={styles.schematicNowCross}>
                <line x1={nowPt.x - 6.2} x2={nowPt.x + 6.2} y1={nowPt.y} y2={nowPt.y} />
                <line x1={nowPt.x} x2={nowPt.x} y1={nowPt.y - 6.2} y2={nowPt.y + 6.2} />
              </g>
              <circle cx={nowPt.x} cy={nowPt.y} r={2.05} className={styles.schematicNowDot} />
            </svg>
          )}
          {showCompare &&
            flags.showLabs &&
            overlay.trail.map((p) => {
              if (!p.key) return null;
              const isNow = p.key === nowPt?.key;
              const onPath = overlay.path.some((q) => q.key === p.key);
              return (
                <span
                  key={`lab-${p.key}`}
                  className={
                    isNow
                      ? styles.schematicSpotLabNow
                      : onPath
                        ? styles.schematicSpotLab
                        : styles.schematicSpotLabSoon
                  }
                  style={{ left: `${p.x}%`, top: `${p.y}%` }}
                >
                  {isNow ? `지금 ≈ ${nowPhrase}` : p.label}
                </span>
              );
            })}
          {showCompare && flags.showZones && sellBox && (
            <span
              className={styles.schematicZoneBoxSell}
              style={{
                left: `${sellBox.left}%`,
                top: `${sellBox.top}%`,
                width: `${sellBox.width}%`,
                height: `${sellBox.height}%`,
              }}
            >
              <span className={styles.schematicZoneBoxLab}>
                매도ZONE {formatSchematicPrice(sellBox.lo)}–{formatSchematicPrice(sellBox.hi)}
              </span>
            </span>
          )}
          {showCompare && flags.showZones && buyBox && (
            <span
              className={styles.schematicZoneBoxBuy}
              style={{
                left: `${buyBox.left}%`,
                top: `${buyBox.top}%`,
                width: `${buyBox.width}%`,
                height: `${buyBox.height}%`,
              }}
            >
              <span className={styles.schematicZoneBoxLab}>
                매수ZONE {formatSchematicPrice(buyBox.lo)}–{formatSchematicPrice(buyBox.hi)}
              </span>
            </span>
          )}
          {showCompare && (
            <div className={styles.schematicWhereHud}>
              <span>지금 ≈ {nowPhrase || '—'}</span>
              {buyBox ? (
                <span className={styles.schematicWhereBuy}>
                  매수ZONE {formatSchematicPrice(buyBox.lo)}–{formatSchematicPrice(buyBox.hi)}
                </span>
              ) : null}
              {sellBox ? (
                <span className={styles.schematicWhereSell}>
                  매도ZONE {formatSchematicPrice(sellBox.lo)}–{formatSchematicPrice(sellBox.hi)}
                </span>
              ) : null}
            </div>
          )}
          {(kind === 'seat' || (showCompare && flags.showLabs)) && match && (
            <span
              className={`${styles.schematicHot} ${
                verdict === '롱' || verdict === '빅롱'
                  ? styles.schematicHotGreen
                  : verdict === '숏' || verdict === '폭락'
                    ? styles.schematicHotRed
                    : styles.schematicHotWait
              }`}
              style={{ left: `${nowPt?.x ?? match.left}%`, top: `${nowPt?.y ?? match.top}%` }}
            >
              <span className={styles.schematicHotRing} />
              <span className={`${styles.schematicHotCard} ${sideClass}`}>
                <span className={styles.schematicHotName}>지금 ≈ {nowPhrase || '—'}</span>
                {kind !== 'seat' ? (
                  <>
                    <span className={styles.schematicHotPx}>{formatSchematicPrice(overlay.now.price)}</span>
                    <span className={styles.schematicHotSide}>{verdict}</span>
                  </>
                ) : null}
              </span>
            </span>
          )}
        </div>
      )}
    </div>
  );
}

