  const t1 = Number(candles[Math.max(0, n - 16)]?.time) || tLast;
  const t2 = tLast > 0 ? mergedDeskRbFutureTime2(candles, tLast, n - 1) : 0;
  if (!(t2 > 0) || !(close > 0)) return { overlays: [], priceLines: [] };

  const isLong = stance.side === 'LONG';
  const isShort = stance.side === 'SHORT';
  const color = isLong ? '#22C55E' : isShort ? '#EF4444' : '#94A3B8';
  const fill = isLong
    ? 'rgba(34,197,94,0.2)'
    : isShort
      ? 'rgba(239,68,68,0.18)'
      : 'rgba(148,163,184,0.16)';
  const bg = isLong ? 'rgba(20,83,45,0.95)' : isShort ? 'rgba(127,29,29,0.95)' : 'rgba(51,65,85,0.94)';
