  pulse?: boolean;
  confidence?: number;
}): OverlayItem {
  return {
    id: p.id,
    kind: 'zone',
    category: 'chartPrimeTrendChannels',
    label: `${p.faceBase}·${p.faceSignal}`,
    zoneFaceBase: p.faceBase,
    zoneFaceSignal: p.faceSignal,
    zoneFaceDetailKo: p.detailKo,
    zoneFaceLang: 'ko',
    x1: 0,
