    if (!(bs > 0)) return 1;
    return Math.max(0.36, Math.min(1.6, bs / MERGED_DESK_DEFAULT_BAR_SPACING));
  } catch {
    return 1;
  }
}, [isMergedAnalysisDesk, overlayTick, lsRocketBarGeomSig]);

