/** 마지막 developing 봉 BOS/CHoCH — 구조 로켓 🚀/📉 선반영 */
export function augmentMergedDeskRocketRows(
  rockets: MergedDeskRocketRow[],
  candles: Candle[],
  timeframe: string,
  analysis?: AnalyzeResponse | null
): MergedDeskRocketRow[] {
  if (candles.length < 12) return rockets;
  const lastT = Number(candles[candles.length - 1]?.time);
  if (!Number.isFinite(lastT)) return rockets;

  const out = [...rockets];
  const hasLong = out.some((r) => r.time === lastT && r.direction === 'LONG');
  const hasShort = out.some((r) => r.time === lastT && r.direction === 'SHORT');

  const ctx = detectMergedSmcLeadingContext({ candles, timeframe, analysis });
  const devMark = ctx.marks.find((m) => m.developing && m.index === candles.length - 1);
  if (devMark?.bias === 'bullish' && !hasLong && !hasShort) {
    out.push({ time: lastT, direction: 'LONG', tier: 'structure' });
  } else if (devMark?.bias === 'bearish' && !hasLong && !hasShort) {
    out.push({ time: lastT, direction: 'SHORT', tier: 'structure' });
  }

  const deduped = new Map<string, MergedDeskRocketRow>();
  for (const r of out) {
    const key = `${r.time}|${r.direction}`;
    if (!deduped.has(key)) deduped.set(key, r);
  }
  const sorted = [...deduped.values()].sort((a, b) => a.time - b.time);
  return filterMergedDeskSignalsToChartWindow(sorted, candles);
}

