import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

const COOKIE = 'ailongshort-site';
const DEV_SESSION_SECRET = 'ailongshort-dev-session-secret';

function base64UrlToUtf8(b64url: string): string {
  const b64 = b64url.replace(/-/g, '+').replace(/_/g, '/');
  const pad = b64 + '==='.slice((b64.length + 3) % 4);
  const bin = atob(pad);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

async function hmacSha256Hex(secret: string, message: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const mac = await crypto.subtle.sign('HMAC', key, enc.encode(message));
  return [...new Uint8Array(mac)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/** Edge — lib/appSiteAuth.ts Node HMAC 과 동일한 hex */
async function verifySiteAuthCookieEdge(token: string, secret: string): Promise<boolean> {
  if (!token.includes('.')) return false;
  const dot = token.lastIndexOf('.');
  const b64 = token.slice(0, dot);
  const sig = token.slice(dot + 1);
  if (!b64 || !sig || !/^[0-9a-f]+$/i.test(sig)) return false;
  try {
    const payload = base64UrlToUtf8(b64);
    const expected = await hmacSha256Hex(secret, payload);
    if (expected.length !== sig.length) return false;
    let ok = true;
    for (let i = 0; i < expected.length; i++) {
      if (expected.charCodeAt(i) !== sig.charCodeAt(i)) ok = false;
    }
    if (!ok) return false;
    const { exp } = JSON.parse(payload) as { exp?: number };
    return typeof exp === 'number' && Date.now() < exp;
  } catch {
    return false;
  }
}

const AUTH_WHITELIST_PREFIXES = [
  '/api/auth/verify-briefing',
  '/api/auth/logout',
  '/api/auth/session',
  '/api/visitors',
];

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  if (!pathname.startsWith('/api/')) return NextResponse.next();
  if (pathname.startsWith('/api/cron/')) {
    return NextResponse.next();
  }
  if (pathname.startsWith('/api/analyze')) {
    const want = (
      process.env.INTERNAL_ANALYZE_SECRET || process.env.TELEGRAM_MULTITF_CRON_SECRET || ''
    ).trim();
    if (want && request.headers.get('x-internal-analyze-secret') === want) {
      return NextResponse.next();
    }
  }
  if (AUTH_WHITELIST_PREFIXES.some((p) => pathname === p || pathname.startsWith(`${p}/`))) {
    return NextResponse.next();
  }
  const secret = process.env.APP_SESSION_SECRET?.trim() || DEV_SESSION_SECRET;
  if (
    process.env.NODE_ENV === 'production' &&
    (!process.env.APP_SESSION_SECRET?.trim() || secret === DEV_SESSION_SECRET)
  ) {
    return NextResponse.json(
      {
        error: 'APP_SESSION_SECRET 미설정 — 운영 환경에서는 반드시 지정하세요.',
        code: 'SITE_AUTH_MISCONFIGURED',
      },
      { status: 503 }
    );
  }
  const raw = request.cookies.get(COOKIE)?.value;
  if (!raw || !(await verifySiteAuthCookieEdge(raw, secret))) {
    return NextResponse.json(
      { error: '로그인이 필요합니다.', code: 'SITE_AUTH_REQUIRED' },
      { status: 401 }
    );
  }
  return NextResponse.next();
}

export const config = {
  matcher: ['/api/:path*'],
};

const fs = require('fs');
const path = require('path');
const roots = ['lib', 'app', 'middleware.ts', 'next.config.mjs', 'tsconfig.json', 'deploy_today.py'];
const empty = [];
function walk(p) {
  const st = fs.statSync(p);
  if (st.isDirectory()) {
    if (p.includes('node_modules') || p.includes('.next')) return;
    for (const n of fs.readdirSync(p)) walk(path.join(p, n));
    return;
  }
  if (!/\.(ts|tsx|js|mjs|py)$/.test(p)) return;
  const t = fs.readFileSync(p, 'utf8').trim();
  if (t.length < 8) empty.push({ p, n: t.length });
}
for (const r of roots) {
  const abs = path.isAbsolute(r) ? r : path.join('d:/apps/ailongshort', r);
  if (fs.existsSync(abs)) walk(abs);
}
console.log(empty.map((x) => `${x.n}\t${x.p}`).join('\n'));
console.log('count', empty.length);

