  if (!mergedDeskRocketBarSupportsDirection(bar, direction, volMed)) continue;
  out.push({
    time: t,
    direction,
    tier: 'structure',
  });
  lastIdx = mk.index;
  if (out.length >= MERGED_DESK_CHART_TF_ROCKET_MAX) break;
}

