export function dedupeMergedDeskRocketsOnePerBar<T extends { time: number; direction: 'LONG' | 'SHORT' }>(
  rows: ReadonlyArray<T>,
  chartBias?: 'LONG' | 'SHORT' | null
): T[] {
  const byBar = new Map<number, T>();
  for (const r of rows) {
    const t = Number(r.time);
    if (!Number.isFinite(t)) continue;
    const prev = byBar.get(t);
    if (!prev) {
      byBar.set(t, r);
      continue;
    }
    if (prev.direction === r.direction) continue;
    const pick = chartBias ?? prev.direction;
    byBar.set(t, r.direction === pick ? r : prev);
  }
  return [...byBar.values()].sort((a, b) => a.time - b.time);
}

input.new_string:
export function dedupeMergedDeskRocketsOnePerBar<T extends { time: number; direction: 'LONG' | 'SHORT' }>(
  rows: ReadonlyArray<T>,
  chartBias?: 'LONG' | 'SHORT' | null,
  candles?: Array<{ time?: number; open?: number; close?: number }>
): T[] {
  const byBar = new Map<number, T>();
  const barByT = new Map<number, { open: number; close: number }>();
  if (candles?.length) {
    for (const c of candles) {
      const t = Number(c.time);
      if (!Number.isFinite(t)) continue;
      barByT.set(t, { open: Number(c.open), close: Number(c.close) });
    }
  }
  for (const r of rows) {
    const t = Number(r.time);
    if (!Number.isFinite(t)) continue;
    const prev = byBar.get(t);
    if (!prev) {
      byBar.set(t, r);
      continue;
    }
    if (prev.direction === r.direction) continue;
    const bar = barByT.get(t);
    const bodyPick =
      bar && Number.isFinite(bar.close) && Number.isFinite(bar.open)
        ? bar.close >= bar.open
          ? 'LONG'
          : 'SHORT'
        : null;
    const pick = chartBias ?? bodyPick ?? prev.direction;
    byBar.set(t, r.direction === pick ? r : prev);
  }
  return [...byBar.values()].sort((a, b) => a.time - b.time);
}

