function snapRocketsOnePerChartBar<T extends { time: number; direction: 'LONG' | 'SHORT' }>(
  rows: ReadonlyArray<T>,
  candles: Candle[] | undefined,
  bias?: 'LONG' | 'SHORT' | null
): T[] {
  if (!rows.length) return [];
  if (!candles?.length) {
    const byT = new Map<number, T>();
    for (const r of rows) {
      const t = Number(r.time);
      if (!Number.isFinite(t)) continue;
      const prev = byT.get(t);
      if (!prev || (bias && r.direction === bias)) byT.set(t, r);
    }
    return [...byT.values()].sort((a, b) => a.time - b.time);
  }
  const byBar = new Map<number, T>();
  for (const r of rows) {
    const bo = candleOpenContainingTime(candles, Number(r.time));
    if (bo == null) continue;
    const next = (bo === r.time ? r : { ...r, time: bo }) as T;
    const prev = byBar.get(bo);
    if (!prev) {
      byBar.set(bo, next);
      continue;
    }
    if (prev.direction === next.direction) continue;
    const bar = candles.find((c) => Number(c.time) === bo);
    const bodyPick =
      bar && Number.isFinite(Number(bar.close)) && Number.isFinite(Number(bar.open))
        ? Number(bar.close) >= Number(bar.open)
          ? 'LONG'
          : 'SHORT'
        : null;
    const pick = bias ?? bodyPick ?? prev.direction;
    byBar.set(bo, next.direction === pick ? next : prev);
  }
  return [...byBar.values()].sort((a, b) => a.time - b.time);
}

