#!/usr/bin/env python3
"""Download entire /root/ailongshort → local. Keeps .env.local. Skips node_modules/.next/.git."""
from __future__ import annotations

import importlib.util
import os
import stat
import sys

import paramiko

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
REMOTE = "/root/ailongshort"
SKIP_DIR = {
    "node_modules",
    ".next",
    ".git",
    ".turbo",
    ".vps_restore_tmp",
    ".vps_full_tmp",
    "__pycache__",
}
SKIP_FILE = {".env.local"}
SELF_NAME = "_sync_full_from_vps_once.py"


def load_creds():
    for name in ("deploy_today.py", os.path.join("scripts", "_deploy_chart_speed.py")):
        path = os.path.join(ROOT, name)
        if not os.path.isfile(path):
            continue
        spec = importlib.util.spec_from_file_location("d", path)
        mod = importlib.util.module_from_spec(spec)
        assert spec.loader
        spec.loader.exec_module(mod)
        return mod
    raise SystemExit("no creds file")


def download_dir(sftp, rdir: str, ldir: str, fails: list[str]) -> int:
    n = 0
    try:
        entries = sftp.listdir_attr(rdir)
    except IOError as e:
        print(f"[listdir-fail] {rdir} {e}", flush=True)
        return 0
    for attr in entries:
        name = attr.filename
        if name in (".", ".."):
            continue
        rpath = f"{rdir}/{name}"
        lpath = os.path.join(ldir, name)
        is_dir = stat.S_ISDIR(attr.st_mode)
        if is_dir:
            if name in SKIP_DIR:
                continue
            os.makedirs(lpath, exist_ok=True)
            n += download_dir(sftp, rpath, lpath, fails)
            continue
        if name in SKIP_FILE or name == SELF_NAME:
            continue
        os.makedirs(ldir, exist_ok=True)
        try:
            if os.path.isfile(lpath):
                try:
                    os.chmod(lpath, 0o666)
                except OSError:
                    pass
                try:
                    os.remove(lpath)
                except OSError:
                    pass
            sftp.get(rpath, lpath)
        except Exception as e:
            print(f"[fail] {rpath} {e}", flush=True)
            fails.append(rpath)
            continue
        n += 1
        if n % 80 == 0:
            print(f"[..] {n} files under {rdir}", flush=True)
    return n


def retry_fails(sftp, fails: list[str]) -> list[str]:
    still = []
    for rpath in fails:
        rel = rpath[len(REMOTE) :].lstrip("/")
        lpath = os.path.join(ROOT, *rel.split("/"))
        os.makedirs(os.path.dirname(lpath), exist_ok=True)
        try:
            if os.path.isfile(lpath):
                try:
                    os.chmod(lpath, 0o666)
                except OSError:
                    pass
                try:
                    os.remove(lpath)
                except OSError:
                    pass
            sftp.get(rpath, lpath)
            print(f"[retry-ok] {rel}", flush=True)
        except Exception as e:
            print(f"[retry-fail] {rel} {e}", flush=True)
            still.append(rpath)
    return still


def main() -> int:
    d = load_creds()
    host = getattr(d, "HOST", "167.179.119.140")
    user = getattr(d, "USER", "root")
    password = d.PASSWORD
    port = getattr(d, "PORT", 22)
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    ssh.connect(host, port=port, username=user, password=password, timeout=30)
    sftp = ssh.open_sftp()
    fails: list[str] = []
    total = download_dir(sftp, REMOTE, ROOT, fails)
    print(f"[pass1] {total} files  fails={len(fails)}", flush=True)
    if fails:
        still = retry_fails(sftp, fails)
        print(f"[pass2] still={len(still)}", flush=True)
        fails = still
    sftp.close()
    ssh.close()
    cv = os.path.join(ROOT, "app", "components", "ChartView.tsx")
    if os.path.isfile(cv):
        b = open(cv, "rb").read()
        print(
            f"[check] ChartView bytes={len(b)} lines={b.count(10)} pack={b'mergedDeskPack' in b}",
            flush=True,
        )
    print(f"[done] ok={total} fail={len(fails)}", flush=True)
    if fails:
        for p in fails:
            print(f"  FAIL {p}", flush=True)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

