function seatZone(
  id: string,
  label: string,
  kind: 'dump1' | 'bounce2' | 'rally1' | 'drop2',
  form: Candle,
  candles: Candle[],
  color: string,
  bg: string,
  tip: string
): OverlayItem {
  const hugLow = kind === 'dump1' || kind === 'bounce2';
  const range = Math.max(1e-8, Number(form.high) - Number(form.low));
  const h = Math.max(range * 0.42, Math.abs(Number(form.close)) * 0.0012);
  const lo = hugLow ? Number(form.low) : Number(form.high) - h;
  const hi = hugLow ? Number(form.low) + h : Number(form.high);
  const span = mergedDeskAnalyzedZoneSpanTimes(candles, {
    id,
    time1: Number(form.time),
    price1: hi,
    price2: lo,
  });
  const t1 = span?.t1 ?? Number(form.time);
  const t2 = span?.t2 ?? Number(candles[candles.length - 1]?.time || form.time);
  return {
    id,
    kind: hugLow ? 'demandZone' : 'supplyZone',
    category: 'chartPrimeTrendChannels',
    label,
    zoneFaceBase: label,
    zoneFaceSignal: hugLow ? '수요구간' : '공급구간',
    zoneFaceDetailKo: tip,
    zoneFaceLang: 'ko',
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 0,
    time1: t1,
    time2: t2,
    price1: hi,
    price2: lo,
    confidence: 86,
    color,
    labelBackgroundColor: bg,
    labelTextColor: '#f8fafc',
    overlayZoneExtraClass: [
      'merged-desk-advvol-seat-zone',
      `merged-desk-advvol-seat--${kind}`,
      hugLow ? 'overlay-zone--hotzone-signal--long' : 'overlay-zone--hotzone-signal--short',
      'merged-desk-money-zone-keep',
    ].join(' '),
    labelTooltip: tip,
    zoneFillPreserve: true,
    zoneSpanOnly: false,
    structureBias: hugLow ? 'bullish' : 'bearish',
    noProject: true,
  };
}

