export type MoneyZoneLiveReaction = 'SUPPORT_HOLD' | 'RESIST_REJECT' | 'NONE';

/**
 * 지금 봉 반응: 위에서 찍고 버티면 지지(롱), 아래에서 맞고 밀리면 저항(숏).
 * 선언 방향(위=숏/아래=롱)보다 우선.
 */
export function detectMoneyZoneLiveReaction(
  candles: Candle[],
  top: number,
  bot: number
): MoneyZoneLiveReaction {
  const n = candles.length;
  if (n < 8 || !(top > bot)) return 'NONE';
  const last = candles[n - 1]!;
  const close = Number(last.close);
  const mid = (top + bot) / 2;
  const atr = atrRecent(candles, 14) || Math.abs(close) * 0.004;
  const pad = Math.max(atr * 0.22, (top - bot) * 0.15);
  let taggedLow = 0;
  let taggedHigh = 0;
  let fromAbove = false;
  let fromBelow = false;
  const recFrom = Math.max(0, n - 10);
  const priorFrom = Math.max(0, n - 18);
  for (let i = priorFrom; i < recFrom; i++) {
    const c = candles[i]!;
    if (Number(c.high) > top + atr * 0.45) fromAbove = true;
    if (Number(c.low) < bot - atr * 0.45) fromBelow = true;
  }
  for (let i = recFrom; i < n; i++) {
    const c = candles[i]!;
    const lo = Number(c.low);
    const hi = Number(c.high);
    if (lo <= top + pad && lo >= bot - pad * 1.35) taggedLow += 1;
    if (hi >= bot - pad && hi <= top + pad) taggedHigh += 1;
    if (i < recFrom + 2) {
      if (hi > top + atr * 0.45) fromAbove = true;
      if (lo < bot - atr * 0.45) fromBelow = true;
    }
  }
  const prev = candles[Math.max(0, n - 3)]!;
  const rising = close > Number(prev.close);
  const falling = close < Number(prev.close);
  const bounceBar = close > Number(last.open) || close >= mid;

  if (
    taggedLow >= 1 &&
    close >= bot - pad &&
    (fromAbove || Number(last.low) <= top + pad) &&
    (bounceBar || rising || close >= mid)
  ) {
    return 'SUPPORT_HOLD';
  }
  if (
    taggedHigh >= 1 &&
    close <= top + pad &&
    (fromBelow || Number(last.high) >= bot - pad) &&
    (!bounceBar || falling || close <= mid) &&
    close <= mid + pad
  ) {
    return 'RESIST_REJECT';
  }
  return 'NONE';
}

export function resolveMoneyZoneSideFromLive(
  candles: Candle[],
  top: number,
  bot: number,
  declared: 'LONG' | 'SHORT' | null
): 'LONG' | 'SHORT' | null {
  const live = detectMoneyZoneLiveReaction(candles, top, bot);
  if (live === 'SUPPORT_HOLD') return 'LONG';
  if (live === 'RESIST_REJECT') return 'SHORT';
  return declared;
}

