        name = attr.filename
        if name in (".", ".."):
            continue
        rpath = f"{rdir}/{name}"
        lpath = os.path.join(ldir, name)
        if stat.S_ISDIR(attr.st_mode):
            if name in SKIP_DIR:
                continue
            os.makedirs(lpath, exist_ok=True)
            n += download_dir(sftp, rpath, lpath, fails)
            continue
        try:
            get_file(sftp, rpath, lpath)
        except Exception as e:
            print(f"[fail] {rpath} {e}", flush=True)
            fails.append(rpath)
            continue
        n += 1
        if n % 50 == 0:
            print(f"[..] {n} under {rdir}", flush=True)
    return n


def main() -> int:
    d = load_creds()
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    ssh.connect(d.HOST, port=getattr(d, "PORT", 22), username=d.USER, password=d.PASSWORD, timeout=30)
    sftp = ssh.open_sftp()
    fails: list[str] = []
    total = 0
    for tree in TREES:
        c = download_dir(sftp, f"{REMOTE}/{tree}", os.path.join(ROOT, tree), fails)
        print(f"[tree] {tree} +{c}", flush=True)
        total += c
    sftp.close()
    ssh.close()
    cv = os.path.join(ROOT, "app", "components", "ChartView.tsx")
    if os.path.isfile(cv):
        b = open(cv, "rb").read()
        print(
            f"[check] ChartView bytes={len(b)} lines={b.count(10)} pack={b'mergedDeskPack' in b} rkRange={b'mergedDeskRocketRange' in b} hideMoney={b'핵심 타점만 under' in b}",
            flush=True,
        )
    print(f"[done] ok={total} fail={len(fails)}", flush=True)
    for p in fails[:20]:
        print(f"  FAIL {p}", flush=True)
    return 1 if fails else 0


if __name__ == "__main__":
    sys.exit(main())

