'use client';

import { forwardRef, useEffect, useState, type ComponentProps } from 'react';
import type { ChartSnapshotRef } from './ChartView';

type ChartViewProps = ComponentProps<typeof import('./ChartView').default>;

/** 모듈 평가 즉시 컴파일 시작 — 첫 페인트는 셸, 차트는 청크 */
const chartViewChunk = () => import('./ChartView');

const ChartViewLazy = forwardRef<ChartSnapshotRef, ChartViewProps>(function ChartViewLazy(props, ref) {
  const [Comp, setComp] = useState<typeof import('./ChartView').default | null>(null);
  useEffect(() => {
    let alive = true;
    void chartViewChunk().then((m) => {
      if (alive) setComp(() => m.default);
    });
    return () => {
      alive = false;
    };
  }, []);
  if (!Comp) {
    return (
      <div
        className="chart-wrap"
        style={{
          minHeight: 420,
          background: '#0b1220',
          color: '#94a3b8',
          padding: 16,
          fontSize: 13,
        }}
      >
        차트 엔진 올리는 중…
      </div>
    );
  }
  return <Comp {...props} ref={ref} />;
});

export default ChartViewLazy;

