      const spreadScore = Math.min(1.5, spread / (minBars * 2)) * 3;
      const recency = (Math.max(upper.lastTouch, lower.lastTouch) / Math.max(1, iEnd)) * 2.5;
      /** 폭이 넓을수록 아무 캔들이나 담기므로 감점 — 밀착한 채널이 이긴다 */
