      const half = maxSpan / 2;
      return {
        ...raw,
        price1: mid + half,
        price2: mid - half,
        zoneFillPreserve: true,
        overlayZoneExtraClass: `${extra} merged-desk-hotzone-hunt`.trim(),
      };
    }
  }
  return raw;
}

