/** 통로 안에서 최근 봉이 이미 하락/상승 중인지 — 기울기 반전을 기다리지 않음 */
function detectCorridorPath(
  rows: Candle[],
  g: { tipUpper: number; tipLower: number; tipMid?: number } | null
): 'up' | 'down' | 'chop' {
  const n = rows.length;
  if (n < 5) return 'chop';
  const win = rows.slice(-4);
  const closes = win.map((c) => Number(c.close));
  const highs = win.map((c) => Number(c.high));
  const lows = win.map((c) => Number(c.low));
  if (closes.some((x) => !(x > 0))) return 'chop';
  let downSteps = 0;
  let upSteps = 0;
  for (let i = 1; i < closes.length; i++) {
    if (closes[i]! < closes[i - 1]!) downSteps += 1;
    else if (closes[i]! > closes[i - 1]!) upSteps += 1;
  }
  const lowerHighs = highs[3]! < highs[1]! && highs[2]! <= highs[0]! * 1.001;
  const higherLows = lows[3]! > lows[1]! && lows[2]! >= lows[0]! * 0.999;
  const mid = g ? (g.tipUpper + g.tipLower) / 2 : closes[3]!;
  const inLower = closes[3]! <= mid;
  const inUpper = closes[3]! >= mid;
  const netDn = closes[3]! < closes[0]!;
  const netUp = closes[3]! > closes[0]!;
  if (downSteps >= 2 && netDn && (lowerHighs || inLower)) return 'down';
  if (upSteps >= 2 && netUp && (higherLows || inUpper)) return 'up';
  return 'chop';
}

