/** HotZone 가격 고정 — 안착 유지, 밀리면 삭제. 틱마다 위아래 점프 금지 */
type HzLock = {
  top: number;
  bot: number;
  mid: number;
  time1?: number;
};
const hzLocks = new Map<string, HzLock>();

function persistHotZoneBand(
  tf: string,
  side: 'LONG' | 'SHORT',
  next: MergedDeskHotZoneEntry | null,
  price: number,
  atrVal: number
): MergedDeskHotZoneEntry | null {
  const key = `${tf}|${side}`;
  const prev = hzLocks.get(key);
  const slip = Math.max(atrVal * 0.28, Math.abs(price) * 0.0012);
  if (prev) {
    const slipped = side === 'LONG' ? price < prev.bot - slip : price > prev.top + slip;
    if (slipped) {
      hzLocks.delete(key);
      if (!next) return null;
      const settling = price >= next.bot - slip && price <= next.top + slip;
      if (!settling) return null;
    } else {
      const kept: MergedDeskHotZoneEntry = next
        ? {
            ...next,
            top: prev.top,
            bot: prev.bot,
            mid: prev.mid,
            time1: prev.time1 ?? next.time1,
            id: `merged-desk-hotzone-${side === 'LONG' ? 'below' : 'above'}-${Math.round(prev.mid * 100)}`,
          }
        : {
            id: `merged-desk-hotzone-${side === 'LONG' ? 'below' : 'above'}-${Math.round(prev.mid * 100)}`,
            side,
            grade: 'B',
            top: prev.top,
            bot: prev.bot,
            mid: prev.mid,
            score: 70,
            strength: 0.6,
            labelKo: side === 'LONG' ? '$$$$롱' : '$$$$숏',
            reasonKo: '안착유지',
            primary: side === 'LONG',
            touchedNow: price >= prev.bot && price <= prev.top,
            status: price >= prev.bot && price <= prev.top ? 'TOUCH' : 'WAIT',
            statusKo: price >= prev.bot && price <= prev.top ? '터치' : '대',
            sources: ['HotZone'],
            time1: prev.time1,
          };
      hzLocks.set(key, {
        top: prev.top,
        bot: prev.bot,
        mid: prev.mid,
        time1: kept.time1,
      });
      return kept;
    }
  }
  if (!next) return null;
  hzLocks.set(key, { top: next.top, bot: next.bot, mid: next.mid, time1: next.time1 });
  return next;
}

