    if (bearBar && g && close <= g.tipLower + span * 0.06) shortN += 12;
  }

  if (atResist) {
    if (bearBar && g && high >= g.tipUpper - span * 0.14) {
      shortN += 28;
      railShort = true;
    }
    if (prevBear && bearBar) {
      shortN += 8;
      railShort = true;
    }
    if (upperKo.includes('저항') || upperKo.includes('안착')) {
      shortN += 22;
      railShort = true;
    }
    if ((upSettle === 'settled' || upSettle === 'attempt') && bearBar) {
      shortN += 18;
      railShort = true;
    }
    if (params.primaryEdge === 'upper' && params.primaryDir === 'SHORT') {
      shortN += 10;
      railShort = true;
    }
    if (bullBar && g && close >= g.tipUpper - span * 0.06) longN += 12;
  }

  /** 테두리 이탈·통로 안 경로를 기울기보다 먼저 — 이미 밑이면 즉시 빨강 */
  const belowRail = Boolean(g && close > 0 && close < g.tipLower);
  const aboveRail = Boolean(g && close > 0 && close > g.tipUpper);
  const wickUnder = Boolean(g && low < g.tipLower && close <= g.tipMid);
  const wickOver = Boolean(g && high > g.tipUpper && close >= g.tipMid);
  const breakDn = g?.breakout === 'down' || (g?.breakoutBars ?? 0) >= 1 && g?.breakout === 'down';
  const breakUp = g?.breakout === 'up';
  const path = detectCorridorPath(rows, g);

  let side: MergedDeskRbCorridorPaintSide;
  let trigger: MergedDeskRbCorridorPaintTrigger = 'slope';
  if (belowRail || breakDn || wickUnder) {
    side = 'short';
    trigger = 'break-down';
  } else if (aboveRail || breakUp || wickOver) {
    side = 'long';
    trigger = 'break-up';
  } else if (path === 'down') {
    side = 'short';
    trigger = 'path';
  } else if (path === 'up') {
    side = 'long';
    trigger = 'path';
  } else if (shortN >= longN + 4) {
    side = 'short';
    trigger = vs && vs.side === 'down' ? 'flow' : st === 'SHORT' ? 'stance' : 'slope';
  } else if (longN >= shortN + 4) {
    side = 'long';
    trigger = vs && vs.side === 'up' ? 'flow' : st === 'LONG' ? 'stance' : 'slope';
  } else if (g) {
    side = g.descending ? 'short' : 'long';
    trigger = 'slope';
  } else {
    side = longN >= shortN ? 'long' : 'short';
    trigger = 'slope';
  }
  if (side === 'long' && railLong && trigger !== 'break-down') trigger = 'rail-bounce';
  else if (side === 'short' && railShort && trigger !== 'break-up') trigger = 'rail-drop';

  const locKo = atSupport ? '하단지지' : atResist ? '상단저항' : belowRail ? '테두리하단이탈' : '통로중가';
  const trigKo =
    trigger === 'break-down'
      ? '하단이탈·하락전환'
      : trigger === 'break-up'
        ? '상단이탈·상승전환'
        : trigger === 'path'
          ? '통로경로'
          : trigger === 'rail-bounce'
            ? '하단반등'
            : trigger === 'rail-drop'
              ? '상단하락'
              : trigger === 'stance'
                ? '마스터방향'
                : trigger === 'flow'
                  ? '수급방향'
                  : '통로기울기';
  const summaryKo = `${side === 'long' ? '상승통로·초록' : '하락통로·빨강'} · ${locKo} · ${trigKo}`;

  return {
    side,
    bear: side === 'short',
    trigger,
    atSupport,
    atResist,
    summaryKo,
  };
}

