}

function buildPriceLines(e: MergedDeskRbRailBounceEntry): AtlasPulsePriceLine[] {
  const isLong = e.side === 'LONG';
  const faceHex = isLong ? '#4ADE80' : '#FB7185';
  return [
    {
      price: e.railPrice,
      color: faceHex,
      title: e.labelKo,
      lineWidth: 2 as const,
      lineStyle: 'dashed' as const,
      axisLabel: true,
    },
    {
      price: e.entry,
      color: faceHex,
      title: isLong ? '반등E' : '저항E',
