  }
  if (id.startsWith('merged-desk-hotzone-') || extra.includes('merged-desk-hotzone-pair')) return 90;
  if (id.startsWith('merged-desk-core-sr') && (extra.includes('--support') || extra.includes('--primary')))
    return 88;
  if (id.startsWith('merged-desk-core-sr') || extra.includes('merged-desk-core-sr')) return 40;
  /** 비-돈구간 — 캡션 금지 */
  return 10;
}

function isDemandSide(o: OverlayItem): boolean {
  const id = String(o.id || '');
  const extra = String(o.overlayZoneExtraClass || '');
  const label = String(o.label || '');
  if (o.kind === 'demandZone') return true;
  if (o.kind === 'supplyZone') return false;
  if (/support|지지|demand|롱|long|below|ob\s*l|obl/i.test(`${id} ${extra} ${label}`)) return true;
  if (/resist|저항|supply|숏|short|above|ob\s*s|obs/i.test(`${id} ${extra} ${label}`)) return false;
  const p1 = Number(o.price1);
  const p2 = Number(o.price2);
  if (Number.isFinite(p1) && Number.isFinite(p2)) return Math.min(p1, p2) < Math.max(p1, p2);
  return true;
}

function hideCaptionFields(raw: OverlayItem, tip?: string): OverlayItem {
  const extra = String(raw.overlayZoneExtraClass || '');
  if (extra.includes('merged-desk-zone-face-hidden')) {
    return {
      ...raw,
      label: '',
      zoneFaceBase: undefined,
      zoneFaceSignal: undefined,
    };
  }
  return {
    ...raw,
    label: '',
    zoneFaceBase: undefined,
    zoneFaceSignal: undefined,
    labelTooltip: tip ?? String(raw.labelTooltip || raw.label || raw.zoneFaceBase || ''),
    overlayZoneExtraClass: `${extra
      .replace(/\bmerged-desk-zone-caption-clean\b/g, '')
      .replace(/\bmerged-desk-zone-pro-hero\b/g, '')
      .trim()} merged-desk-zone-face-minimal merged-desk-zone-pro-soft`.trim(),
  };
}

const MAX_CAPTION_DEMAND = 4;
const MAX_CAPTION_SUPPLY = 4;
/** 같은 문구·가격이 이 비율 안이면 중복 */
const DUP_PRICE_FRAC = 0.0045;

/**
 * zone 면은 전부 유지. 캡션만 축약·우선순위·가격/문구 중복 제거.
 */
export function applyMergedDeskZoneChartLabelClean(overlays: OverlayItem[]): OverlayItem[] {
  if (!overlays.length) return overlays;

  const zoneIdx: number[] = [];
  for (let i = 0; i < overlays.length; i++) {
    const o = overlays[i]!;
    if (!isZoneFace(o)) continue;
    if (!isMergedAnalysisDeskOverlayId(o.id) && !isMergedDeskAnalyzedCandleSpanOverlay(o)) continue;
    zoneIdx.push(i);
  }

  const ranked = zoneIdx
    .map((i) => ({ i, pri: captionPriority(overlays[i]!), demand: isDemandSide(overlays[i]!) }))
    .sort((a, b) => b.pri - a.pri);

  const keepCaption = new Set<number>();
  /** money-zone-keep · assets/세력 ZONE · 파란/빨간 채널 · Hot · 레일반등 캡션은 무조건 유지 */
  for (const i of zoneIdx) {
    const id = String(overlays[i]!.id || '');
    const extra = String(overlays[i]!.overlayZoneExtraClass || '');
    if (extra.includes('merged-desk-rb-core-face-off') || extra.includes('merged-desk-zone-face-hidden')) {
      continue;
    }
    if (
      extra.includes('merged-desk-money-zone-keep') ||
      extra.includes('merged-desk-zone-pro-hero') ||
      extra.includes('merged-desk-asset-auto-zone') ||
      extra.includes('merged-desk-ai-force-zone') ||
      extra.includes('merged-desk-rb-channel') ||
      extra.includes('merged-desk-rb-rail-bounce') ||
      extra.includes('merged-desk-rb-pullback') ||
      extra.includes('merged-desk-hotzone') ||
      id.includes('rb-rail-bounce') ||
      id.includes('rb-pullback') ||
      id.startsWith('merged-desk-hotzone-') ||
      id.startsWith('merged-desk-asset-') ||
      id.startsWith('merged-desk-ai-buy-') ||
      id.startsWith('merged-desk-ai-sell-') ||
      id.startsWith('merged-desk-ai-defense-') ||
      id.startsWith('merged-desk-rb-')
    ) {
      keepCaption.add(i);
    }
  }
  let d = 0;
  let s = 0;
  for (const row of ranked) {
    if (keepCaption.has(row.i)) {
      if (row.demand) d += 1;
      else s += 1;
      continue;
    }
    if (row.pri < 88) continue; // $$ 돈구간만
    if (row.demand) {
      if (d >= MAX_CAPTION_DEMAND) continue;
      d += 1;
    } else {
      if (s >= MAX_CAPTION_SUPPLY) continue;
      s += 1;
    }
    keepCaption.add(row.i);
  }

  /** 1차: 우선순위 캡 적용 */
  let next = overlays.map((raw, i) => {
    const extra0 = String(raw.overlayZoneExtraClass || '');
    if (extra0.includes('merged-desk-zone-face-hidden') || extra0.includes('merged-desk-rb-core-face-off')) {
      return hideCaptionFields(raw, String(raw.labelTooltip || raw.label || raw.zoneFaceBase || ''));
    }

    const id = String(raw.id || '');
    const kind = String(raw.kind || '');
    const tip = String(raw.labelTooltip || raw.label || raw.zoneFaceBase || '');

    if (!zoneIdx.includes(i)) {
      if (
        kind === 'bos' ||
        kind === 'choch' ||
        kind === 'label' ||
        id.includes('-struct-') ||
        id.endsWith('-pin') ||
        id.includes('ChoCH') ||
        id.includes('choch') ||
        id.includes('-bos-')
      ) {
        return hideCaptionFields(raw, tip);
      }
      return raw;
    }

    if (!keepCaption.has(i)) {
      return hideCaptionFields(raw, tip);
    }

    const full = captionText(raw);
    const extra = String(raw.overlayZoneExtraClass || '');
    /** 레일 반등·눌림 타점 — 채널 축약 분기보다 먼저, 라벨·시그널 유지 */
    if (
      id.includes('rb-rail-bounce') ||
      id.includes('rb-pullback') ||
      extra.includes('merged-desk-rb-rail-bounce') ||
      extra.includes('merged-desk-rb-pullback')
    ) {
      const face =
        String(raw.zoneFaceBase || '').trim() ||
        String(raw.label || '').trim() ||
        full ||
        (extra.includes('short') || /저항/.test(full) ? '★레일저항' : '★레일반등');
      const signal = String(raw.zoneFaceSignal || '').trim();
      return {
        ...raw,
        label: face,
        zoneFaceBase: face,
        zoneFaceSignal: signal || undefined,
        labelTooltip: tip || face,
        overlayZoneExtraClass: `${extra
          .replace(/\bmerged-desk-zone-face-minimal\b/g, '')
          .replace(/\bmerged-desk-zone-face-hidden\b/g, '')
          .replace(/\bmerged-desk-zone-pro-soft\b/g, '')
          .trim()} merged-desk-zone-caption-clean merged-desk-zone-pro-hero merged-desk-money-zone-keep`.trim(),
      };
    }
    /** Hot지지/저항 — 면 우측 라인 캡션 유지 */
    if (id.startsWith('merged-desk-hotzone-') || extra.includes('merged-desk-hotzone')) {
      const isLong =
        extra.includes('hotzone-signal--long') || String(raw.structureBias || '') === 'bullish';
      const face =
        String(raw.zoneFaceBase || '').trim() ||
        String(raw.label || '').split('·')[0]?.trim() ||
        (isLong ? 'Hot지지' : 'Hot저항');
      const signal =
        String(raw.zoneFaceSignal || '').trim() ||
        (/진입|터치|대기/.test(String(raw.label || ''))
          ? String(raw.label || '').split('·')[1]?.trim()
          : '') ||
        (isLong ? '반등' : '저항');
      return {
        ...raw,
        label: `${face} · ${signal}`.trim(),
        zoneFaceBase: face,
        zoneFaceSignal: signal || undefined,
        labelTooltip: tip || `${face} · ${signal}`,
        overlayZoneExtraClass: `${extra
          .replace(/\bmerged-desk-zone-face-minimal\b/g, '')
          .replace(/\bmerged-desk-zone-face-hidden\b/g, '')
          .replace(/\bmerged-desk-zone-pro-soft\b/g, '')
          .trim()} merged-desk-zone-caption-clean merged-desk-zone-pro-hero merged-desk-money-zone-keep`.trim(),
      };
    }
    /** 파란·빨간 평행채널 — 캡션 축약 없이 원문 유지 */
    if (
      id.startsWith('merged-desk-rb-') ||
      extra.includes('merged-desk-rb-channel') ||
      extra.includes('merged-desk-blue-red-channel')
    ) {
      const cap = full || String(raw.label || '').trim() || '채널';
      return {
        ...raw,
        label: cap,
        zoneFaceBase: cap,
        zoneFaceSignal: undefined,
        labelTooltip: tip || cap,
        overlayZoneExtraClass: `${extra
          .replace(/\bmerged-desk-zone-face-minimal\b/g, '')
          .replace(/\bmerged-desk-zone-pro-soft\b/g, '')
          .trim()} merged-desk-zone-caption-clean merged-desk-rb-channel-keep`.trim(),
      };
    }

    const compact = compactMergedDeskZoneChartLabel(full);
    const isHero =
      extra.includes('merged-desk-money-zone-keep') ||
      extra.includes('merged-hq-entry-zone') ||
      extra.includes('merged-desk-hotzone-entry--primary') ||
      (extra.includes('merged-desk-hotzone-entry') &&
        (String(raw.label || '').includes('★') || String(raw.label || '').includes('$$')));

    return {
      ...raw,
      label: compact || full,
      zoneFaceBase: compact || full || undefined,
      zoneFaceSignal: undefined,
      labelTooltip: tip || full,
      overlayZoneExtraClass: `${extra
        .replace(/\bmerged-desk-zone-face-minimal\b/g, '')
        .replace(/\bmerged-desk-zone-pro-soft\b/g, '')
        .trim()} merged-desk-zone-caption-clean${isHero ? ' merged-desk-zone-pro-hero' : ''}`.trim(),
    };
  });

  /** 2차: 보이는 캡션끼리 가격·문구 중복 제거 (OB L×2, L$58×2 등) */
  const visible: Array<{ i: number; key: string; mid: number; pri: number }> = [];
  for (let i = 0; i < next.length; i++) {
    const o = next[i]!;
    const extra = String(o.overlayZoneExtraClass || '');
    if (extra.includes('merged-desk-zone-face-minimal')) continue;
    if (!isZoneFace(o) && o.kind !== 'bos' && o.kind !== 'choch' && o.kind !== 'label') continue;
    const text = captionText(o);
    if (!text) continue;
    const mid = zoneMid(o);
    if (!Number.isFinite(mid) || mid <= 0) continue;
    visible.push({
      i,
      key: normalizeMergedDeskZoneCaptionKey(text),
      mid,
      pri: captionPriority(o),
    });
  }

  visible.sort((a, b) => b.pri - a.pri || a.mid - b.mid);
  const kept: Array<{ key: string; mid: number }> = [];
  const hideDup = new Set<number>();

  for (const row of visible) {
    const hit = kept.find((k) => {
      const near = Math.abs(k.mid - row.mid) / row.mid <= DUP_PRICE_FRAC;
      if (!near) return false;
      /** 같은 키(OB L) 또는 둘 다 짧은 유동성/구조 토큰 */
      if (k.key === row.key) return true;
      /** zn / 존 계열은 근처면 무조건 중복 */
      if ((k.key === 'zn' || row.key === 'zn') && near) return true;
      /** obl / l## 근처 혼재도 하나로 */
      const bothLong =
        (/^ob?l/.test(k.key) || /^l\d/.test(k.key)) &&
        (/^ob?l/.test(row.key) || /^l\d/.test(row.key));
      const bothShort =
        (/^ob?s/.test(k.key) || /^s\d/.test(k.key)) &&
        (/^ob?s/.test(row.key) || /^s\d/.test(row.key));
      return bothLong || bothShort;
    });
    if (hit) {
      hideDup.add(row.i);
      continue;
    }
    kept.push({ key: row.key, mid: row.mid });
  }

  if (hideDup.size) {
    next = next.map((raw, i) => {
      if (!hideDup.has(i)) return raw;
      const id = String(raw.id || '');
      const extra = String(raw.overlayZoneExtraClass || '');
      /** 파란·빨간 채널 캡션은 중복 제거 대상에서 제외 */
      if (
        id.startsWith('merged-desk-rb-') ||
        extra.includes('merged-desk-rb-channel') ||
        extra.includes('merged-desk-blue-red-channel')
      ) {
        return raw;
      }
      return hideCaptionFields(raw);
    });
  }

  return next;
}

/** 라벨 ON이면 반등·Hot·돈구간 면 글자는 개별 숨김보다 우선(zone 라인에 강제 표시) */
const forceBounceZoneFaceLabel =
  mergedDeskOverlayLabelsOn &&
  (isRbNamedFaceZone ||
    isHotZoneNamedFace ||
    isPillZoneFace ||
    zoneExtraEarly.includes('merged-desk-rb-rail-bounce') ||
    zoneExtraEarly.includes('merged-desk-rb-pullback') ||
    zoneExtraEarly.includes('merged-desk-hotzone') ||
    zoneExtraEarly.includes('merged-desk-money-zone-keep') ||
    /★?(레일)?(반등|저항)|Hot지지|Hot저항|\$\$\$\$/.test(
      String(mergedFaceCaptionText || '')
    ));

