input.contents:
/**
 * 파랑빨강띠 반등·저항 강도 등급.
 * 약 / 중 / 강 / 초강력 — 조건부 참고(확정 수익·승률 아님).
 */
export type MergedDeskRbBounceGrade = 'weak' | 'mid' | 'strong' | 'ultra';

export type MergedDeskRbBounceStrength = {
  grade: MergedDeskRbBounceGrade;
  /** 약반등 | 중반등 | 강반등 | 초강력반등 (숏이면 저항) */
  labelKo: string;
  shortKo: '약' | '중' | '강' | '초강';
  score: number;
  reasons: string[];
};

function clampScore(n: number): number {
  return Math.max(0, Math.min(100, Math.round(n)));
}

/**
 * 레일 터치·회복·POC·트리거로 반등/저항 강도 산출.
 */
export function gradeMergedDeskRbBounceStrength(params: {
  side: 'LONG' | 'SHORT';
  baseScore: number;
  status?: 'READY' | 'NEAR' | 'HOLD' | 'WAIT' | string | null;
  paintTrigger?: string | null;
  atRail?: boolean;
  wickHold?: boolean;
  bullOrBearBar?: boolean;
  reboundBody?: boolean;
  pocAligned?: boolean;
  distAtr?: number | null;
}): MergedDeskRbBounceStrength {
  const side = params.side;
  const isLong = side === 'LONG';
  let score = clampScore(params.baseScore);
  const reasons: string[] = [`기초 ${score}`];

  if (params.paintTrigger === 'rail-bounce' && isLong) {
    score += 12;
    reasons.push('레일반등 트리거 +12');
  }
  if (params.paintTrigger === 'rail-drop' && !isLong) {
    score += 12;
    reasons.push('레일저항 트리거 +12');
  }
  if (params.atRail) {
    score += 8;
    reasons.push('레일밀착 +8');
  }
  if (params.wickHold) {
    score += 10;
    reasons.push('윅홀드 +10');
  }
  if (params.bullOrBearBar) {
    score += 8;
    reasons.push(isLong ? '양봉회복 +8' : '음봉거부 +8');
  }
  if (params.reboundBody) {
    score += 8;
    reasons.push(isLong ? '몸통반등 +8' : '몸통거부 +8');
  }
  if (params.pocAligned) {
    score += 6;
    reasons.push('POC정렬 +6');
  }
  if (params.status === 'READY') {
    score += 10;
    reasons.push('존도달 +10');
  } else if (params.status === 'NEAR' || params.status === 'HOLD') {
    score += 5;
    reasons.push('근접/홀드 +5');
  }
  const dist = Number(params.distAtr);
  if (Number.isFinite(dist) && dist <= 0.35) {
    score += 6;
    reasons.push('초밀착 +6');
  }

  score = clampScore(score);

  let grade: MergedDeskRbBounceGrade = 'weak';
  if (score >= 86) grade = 'ultra';
  else if (score >= 70) grade = 'strong';
  else if (score >= 55) grade = 'mid';

  const noun = isLong ? '반등' : '저항';
  const shortKo: MergedDeskRbBounceStrength['shortKo'] =
    grade === 'ultra' ? '초강' : grade === 'strong' ? '강' : grade === 'mid' ? '중' : '약';
  const labelKo =
    grade === 'ultra'
      ? isLong
        ? '★초강력반등'
        : '★초강력저항'
      : `★${shortKo}${noun}`;

  return { grade, labelKo, shortKo, score, reasons };
}

