const keepCaption = new Set<number>();
let d = 0;
let s = 0;
for (const row of ranked) {
  const extra = String(overlays[row.i]!.overlayZoneExtraClass || '');
  if (extra.includes('merged-desk-rb-core-face-off') || extra.includes('merged-desk-zone-face-hidden')) {
    continue;
  }
  /** pri 0 = 채널 제외분만 스킵. 일반 zone은 최소 1개 보장 위해 통과 */
  if (row.pri < 0) continue;
  if (row.demand) {
    if (d >= MAX_CAPTION_DEMAND) continue;
    d += 1;
  } else {
    if (s >= MAX_CAPTION_SUPPLY) continue;
    s += 1;
  }
  keepCaption.add(row.i);
}

/** 폴백: 지지/저항 후보가 비면 가장 가까운 면을 1개 강제 유지 */
if (d === 0 || s === 0) {
  for (const row of ranked) {
    const extra = String(overlays[row.i]!.overlayZoneExtraClass || '');
    if (extra.includes('merged-desk-zone-face-hidden')) continue;
    if (keepCaption.has(row.i)) continue;
    if (row.demand && d === 0) {
      keepCaption.add(row.i);
      d = 1;
    } else if (!row.demand && s === 0) {
      keepCaption.add(row.i);
      s = 1;
    }
    if (d > 0 && s > 0) break;
  }
}

/** 레일반등 zone이 있으면 해당 방향 캡션을 그것으로 교체(강도 라벨 우선) */
for (const i of zoneIdx) {
  const id = String(overlays[i]!.id || '');
  const extra = String(overlays[i]!.overlayZoneExtraClass || '');
  if (!id.includes('rb-rail-bounce') && !extra.includes('merged-desk-rb-rail-bounce')) continue;
  const demand = isDemandSide(overlays[i]!);
  for (const k of [...keepCaption]) {
    if (zoneIdx.includes(k) && isDemandSide(overlays[k]!) === demand && k !== i) {
      keepCaption.delete(k);
    }
  }
  keepCaption.add(i);
}

