/**
 * Confirmed prediction freeze. Future candles may add outcome only.
 */
import { EAGLE1_ENGINE_VERSION } from '@/lib/eagle1/rawTypes';

export type Eagle1FrozenPrediction = {
  signal_id: string;
  timestamp: number;
  engine_version: string;
  price: number;
  timeframe: string;
  symbol: string;
  features: Record<string, unknown>;
  poc: number | null;
  zones: Array<{ id: string; lower: number; upper: number }>;
  scores: { long: number; short: number; confidence: number };
  entry: number | null;
  sl: number | null;
  tp: [number | null, number | null, number | null];
  reasons: string[];
  invalidation: string | null;
  direction: 'LONG' | 'SHORT' | 'WAIT';
};

export type Eagle1OutcomeRecord = {
  signal_id: string;
  mfe: number | null;
  mae: number | null;
  result: 'open' | 'tp' | 'sl' | 'invalid' | 'expired';
  updated_at: number;
};

export function freezePrediction(input: Omit<Eagle1FrozenPrediction, 'engine_version'> & { engine_version?: string }): Eagle1FrozenPrediction {
  const row: Eagle1FrozenPrediction = {
    ...input,
    engine_version: input.engine_version || EAGLE1_ENGINE_VERSION,
    zones: input.zones.map((z) => ({ ...z })),
    scores: { ...input.scores },
    tp: [...input.tp],
    reasons: [...input.reasons],
    features: { ...input.features },
  };
  return Object.freeze(row) as Eagle1FrozenPrediction;
}

export function attachOutcome(
  prediction: Eagle1FrozenPrediction,
  outcome: Omit<Eagle1OutcomeRecord, 'signal_id'>
): { prediction: Eagle1FrozenPrediction; outcome: Eagle1OutcomeRecord } {
  return {
    prediction,
    outcome: {
      signal_id: prediction.signal_id,
      ...outcome,
    },
  };
}

export function predictionsEqualFrozen(a: Eagle1FrozenPrediction, b: Eagle1FrozenPrediction): boolean {
  return JSON.stringify(a) === JSON.stringify(b);
}

/**
 * Time-series split. Random shuffle is forbidden.
 */

export type Eagle1ChronoSplit = {
  trainEnd: number;
  valEnd: number;
  holdoutEnd: number;
  train: number[];
  validation: number[];
  holdout: number[];
};

export function chronologicalSplit(
  length: number,
  ratios?: { train?: number; validation?: number }
): Eagle1ChronoSplit {
  const n = Math.max(0, Math.floor(length));
  const trainR = ratios?.train ?? 0.6;
  const valR = ratios?.validation ?? 0.2;
  const trainEnd = Math.floor(n * trainR);
  const valEnd = Math.floor(n * (trainR + valR));
  const train: number[] = [];
  const validation: number[] = [];
  const holdout: number[] = [];
  for (let i = 0; i < n; i++) {
    if (i < trainEnd) train.push(i);
    else if (i < valEnd) validation.push(i);
    else holdout.push(i);
  }
  return { trainEnd, valEnd, holdoutEnd: n, train, validation, holdout };
}

export function isChronological(indices: number[]): boolean {
  for (let i = 1; i < indices.length; i++) {
    if (indices[i] <= indices[i - 1]) return false;
  }
  return true;
}

export function rejectShuffledSplit(split: Eagle1ChronoSplit): string | null {
  if (!isChronological(split.train) || !isChronological(split.validation) || !isChronological(split.holdout)) {
    return 'split indices are not chronological';
  }
  const lastTrain = split.train.length ? split.train[split.train.length - 1] : -1;
  const firstVal = split.validation[0];
  const lastVal = split.validation.length ? split.validation[split.validation.length - 1] : lastTrain;
  const firstHold = split.holdout[0];
  if (firstVal != null && lastTrain >= firstVal) return 'train overlaps validation';
  if (firstHold != null && lastVal >= firstHold) return 'validation overlaps holdout';
  return null;
}

/**
 * Causal FVG — only candles in [0, endExclusive).
 * Mitigation may use bars after formation that are already known.
 */
export type Eagle1CausalFvg = {
  bias: 'bullish' | 'bearish';
  index: number;
  low: number;
  high: number;
  valid: boolean;
  known_at: number;
};

export function detectFvgCausal(
  candles: Array<{ high: number; low: number }>,
  endExclusive: number
): Eagle1CausalFvg[] {
  const n = Math.max(0, Math.min(candles.length, Math.floor(endExclusive)));
  const fvg: Eagle1CausalFvg[] = [];
  const overlaps = (c: { high: number; low: number }, lo: number, hi: number) =>
    c.low <= hi && c.high >= lo;
  for (let i = 2; i < n; i++) {
    const c1 = candles[i - 2];
    const c3 = candles[i];
    if (c1.high < c3.low) {
      const gapLo = c1.high;
      const gapHi = c3.low;
      let mitigated = false;
      for (let j = i + 1; j < n; j++) {
        if (overlaps(candles[j], gapLo, gapHi)) {
          mitigated = true;
          break;
        }
      }
      fvg.push({ bias: 'bullish', index: i, low: gapLo, high: gapHi, valid: !mitigated, known_at: i });
    }
    if (c1.low > c3.high) {
      const gapLo = c3.high;
      const gapHi = c1.low;
      let mitigated = false;
      for (let j = i + 1; j < n; j++) {
        if (overlaps(candles[j], gapLo, gapHi)) {
          mitigated = true;
          break;
        }
      }
      fvg.push({ bias: 'bearish', index: i, low: gapLo, high: gapHi, valid: !mitigated, known_at: i });
    }
  }
  return fvg;
}

/** Hindsight: mitigation uses the full series (repaint of historical valid). */
export function detectFvgHindsight(candles: Array<{ high: number; low: number }>): Eagle1CausalFvg[] {
  return detectFvgCausal(candles, candles.length);
}

export function serializeFvgFrozen(rows: Eagle1CausalFvg[]): string {
  return JSON.stringify(
    rows.map((r) => ({
      bias: r.bias,
      index: r.index,
      low: r.low,
      high: r.high,
      known_at: r.known_at,
    }))
  );
}

import { detectFvgCausal, serializeFvgFrozen } from '@/lib/eagle1/causalFvg';
import { freezePrediction, predictionsEqualFrozen, attachOutcome } from '@/lib/eagle1/predictionSnapshot';
import { chronologicalSplit, rejectShuffledSplit } from '@/lib/eagle1/chronologicalSplit';
import { EAGLE1_ENGINE_VERSION } from '@/lib/eagle1/rawTypes';

export type Eagle1RepaintAudit = {
  passed: boolean;
  confirmedSignalBlocked: boolean;
  failures: string[];
  checks: Record<string, boolean>;
  engine_version: string;
  calculated_at: number;
};

function syntheticCandles(n: number) {
  const out: Array<{ open: number; high: number; low: number; close: number; time: number }> = [];
  let px = 100;
  for (let i = 0; i < n; i++) {
    const close = px + ((i % 7) - 3) * 0.4 + (i % 11 === 0 ? 2 : 0);
    const open = px;
    const high = Math.max(open, close) + 0.3;
    const low = Math.min(open, close) - 0.3;
    out.push({ open, high, low, close, time: i * 900 });
    px = close;
  }
  return out;
}

export function runRepaintAudit(candles?: Array<{ high: number; low: number }>): Eagle1RepaintAudit {
  const failures: string[] = [];
  const checks: Record<string, boolean> = {};
  const series = candles && candles.length >= 30 ? candles : syntheticCandles(80);

  const checkpoints = [20, 40, 60].filter((i) => i < series.length - 2);
  let prefixParity = true;
  for (const t of checkpoints) {
    const a = serializeFvgFrozen(detectFvgCausal(series, t + 1));
    const again = serializeFvgFrozen(detectFvgCausal(series, t + 1));
    if (a !== again) {
      prefixParity = false;
      failures.push(`causal FVG not deterministic at t=${t}`);
    }
    const later = detectFvgCausal(series, series.length);
    const pastFrozen = serializeFvgFrozen(later.filter((f) => f.index <= t && f.known_at <= t));
    const liveAtT = serializeFvgFrozen(detectFvgCausal(series, t + 1));
    if (pastFrozen !== liveAtT) {
      prefixParity = false;
      failures.push(`causal FVG past rows changed after future bars at t=${t}`);
    }
  }
  checks.prefix_replay_parity = prefixParity;

  const snap = freezePrediction({
    signal_id: 'audit-1',
    timestamp: 1,
    price: 100,
    timeframe: '15m',
    symbol: 'BTCUSDT',
    features: { rsi: 50 },
    poc: 100,
    zones: [{ id: 'z1', lower: 99, upper: 101 }],
    scores: { long: 1, short: 0, confidence: 10 },
    entry: 100,
    sl: 99,
    tp: [102, 103, 104],
    reasons: ['audit'],
    invalidation: '99',
    direction: 'WAIT',
  });
  const bundled = attachOutcome(snap, { mfe: 1, mae: 0.2, result: 'tp', updated_at: 2 });
  let freezeOk = predictionsEqualFrozen(snap, bundled.prediction);
  try {
    (snap as { price: number }).price = 999;
    freezeOk = false;
    failures.push('frozen prediction mutated');
  } catch {
    freezeOk = freezeOk && snap.price === 100;
  }
  if (bundled.prediction.price !== 100) {
    freezeOk = false;
    failures.push('outcome write mutated prediction');
  }
  checks.frozen_prediction = freezeOk;

  const split = chronologicalSplit(100);
  const splitErr = rejectShuffledSplit(split);
  const shuffled = { ...split, train: [...split.train].reverse() };
  const shuffleCaught = rejectShuffledSplit(shuffled) != null;
  checks.chrono_split = !splitErr && shuffleCaught;
  if (splitErr) failures.push(splitErr);
  if (!shuffleCaught) failures.push('shuffled split was not rejected');

  const passed = failures.length === 0;
  return {
    passed,
    confirmedSignalBlocked: !passed,
    failures,
    checks,
    engine_version: EAGLE1_ENGINE_VERSION,
    calculated_at: Date.now(),
  };
}

import type { Eagle1RepaintAudit } from '@/lib/eagle1/repaintAudit';

export type Eagle1RepaintGate = {
  confirmedSignalBlocked: boolean;
  code: 'ok' | 'REPAINT_AUDIT_FAIL';
  reason: string;
};

export function evaluateRepaintGate(audit: Eagle1RepaintAudit | null | undefined): Eagle1RepaintGate {
  if (!audit) {
    return {
      confirmedSignalBlocked: false,
      code: 'ok',
      reason: '리페인트 감사 파일 없음 — 런타임 causal 검사만 사용',
    };
  }
  if (!audit.passed || audit.confirmedSignalBlocked) {
    return {
      confirmedSignalBlocked: true,
      code: 'REPAINT_AUDIT_FAIL',
      reason: audit.failures.join('; ') || 'REPAINT_AUDIT_FAIL',
    };
  }
  return { confirmedSignalBlocked: false, code: 'ok', reason: 'ok' };
}

