#!/usr/bin/env node
/**
 * non-repaint-validator required tests.
 * Writes data/eagle1/repaint-audit.json
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const fail = [];

function assert(cond, msg) {
  if (!cond) fail.push(msg);
}

function synthetic(n) {
  const out = [];
  let px = 100;
  for (let i = 0; i < n; i++) {
    const close = px + ((i % 7) - 3) * 0.4 + (i % 11 === 0 ? 2 : 0);
    const open = px;
    out.push({
      high: Math.max(open, close) + 0.3,
      low: Math.min(open, close) - 0.3,
    });
    px = close;
  }
  return out;
}

function detectFvgCausal(candles, endExclusive) {
  const n = Math.min(candles.length, endExclusive);
  const fvg = [];
  const overlaps = (c, lo, hi) => c.low <= hi && c.high >= lo;
  for (let i = 2; i < n; i++) {
    const c1 = candles[i - 2];
    const c3 = candles[i];
    if (c1.high < c3.low) {
      const gapLo = c1.high;
      const gapHi = c3.low;
      let mitigated = false;
      for (let j = i + 1; j < n; j++) {
        if (overlaps(candles[j], gapLo, gapHi)) {
          mitigated = true;
          break;
        }
      }
      fvg.push({ bias: 'bullish', index: i, low: gapLo, high: gapHi, known_at: i, valid: !mitigated });
    }
  }
  return fvg;
}

function ser(rows) {
  return JSON.stringify(rows.map((r) => ({ bias: r.bias, index: r.index, low: r.low, high: r.high, known_at: r.known_at })));
}

const series = synthetic(80);
for (const t of [20, 40, 60]) {
  const live = ser(detectFvgCausal(series, t + 1));
  const later = detectFvgCausal(series, series.length).filter((f) => f.index <= t && f.known_at <= t);
  assert(live === ser(later), `prefix replay mismatch t=${t}`);
}

const frozen = Object.freeze({
  signal_id: 'a',
  price: 100,
  entry: 100,
  sl: 99,
  tp: [101, 102, 103],
});
const outcome = { signal_id: frozen.signal_id, mfe: 1, mae: 0.2 };
assert(frozen.price === 100 && outcome.signal_id === 'a', 'outcome must not replace freeze identity');
try {
  frozen.price = 1;
} catch {
  /* ok */
}
assert(frozen.price === 100, 'frozen prediction mutated');

function chronoSplit(n) {
  const trainEnd = Math.floor(n * 0.6);
  const valEnd = Math.floor(n * 0.8);
  const train = [];
  const val = [];
  const hold = [];
  for (let i = 0; i < n; i++) {
    if (i < trainEnd) train.push(i);
    else if (i < valEnd) val.push(i);
    else hold.push(i);
  }
  return { train, val, hold };
}
function isChrono(a) {
  for (let i = 1; i < a.length; i++) if (a[i] <= a[i - 1]) return false;
  return true;
}
const sp = chronoSplit(100);
assert(isChrono(sp.train) && isChrono(sp.val) && isChrono(sp.hold), 'chrono split failed');
assert(sp.train[sp.train.length - 1] < sp.val[0], 'train/val overlap');
assert(!isChrono([...sp.train].reverse()), 'shuffle detector broken');

const zone = { lower: 99, upper: 101 };
const laterZone = { ...zone };
assert(laterZone.lower === zone.lower && laterZone.upper === zone.upper, 'zone bounds must stay frozen');

const passed = fail.length === 0;
const report = {
  passed,
  confirmedSignalBlocked: !passed,
  failures: fail,
  checks: {
    prefix_replay_parity: !fail.some((f) => String(f).includes('prefix')),
    frozen_prediction: !fail.some((f) => String(f).includes('frozen')),
    chrono_split: !fail.some((f) => String(f).includes('chrono') || String(f).includes('overlap')),
  },
  engine_version: 'eagle1-phase1-0.1.0',
  calculated_at: Date.now(),
};
const dir = path.join(ROOT, 'data', 'eagle1');
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, 'repaint-audit.json'), JSON.stringify(report, null, 2), 'utf8');

if (!passed) {
  console.error('REPAINT SELFTEST FAIL');
  for (const f of fail) console.error(' -', f);
  process.exit(1);
}
console.error('REPAINT SELFTEST OK');

/**
 * Inherit confirmed zone bounds. New evidence may change status, never slide prices.
 */

import { atrAt, type Eagle1Bar } from './structureEngine';
import type { Eagle1Zone } from './zoneEngine';

export function inheritFrozenZones(params: {
  fresh: Eagle1Zone[];
  prev: Eagle1Zone[] | undefined;
  candles: Eagle1Bar[];
  endExclusive: number;
}): Eagle1Zone[] {
  const prev = params.prev ?? [];
  const atr = atrAt(params.candles, params.endExclusive) || 0;
  const byId = new Map(prev.filter((z) => z.frozen).map((z) => [z.zone_id, z]));
  const usedPrev = new Set<string>();
  const out: Eagle1Zone[] = [];

  for (const z of params.fresh) {
    if (z.source_type === 'poc') {
      const oldPoc = prev.find((p) => p.source_type === 'poc' && p.frozen && p.status !== 'BROKEN' && p.status !== 'INVALID' && p.status !== 'DELETED');
      if (oldPoc && atr > 0 && Math.abs(z.midpoint - oldPoc.midpoint) <= atr * 0.5) {
        usedPrev.add(oldPoc.zone_id);
        out.push({
          ...z,
          zone_id: oldPoc.zone_id,
          lower: oldPoc.lower,
          upper: oldPoc.upper,
          midpoint: oldPoc.midpoint,
          frozen: true,
          created_at: oldPoc.created_at,
          reason: `${z.reason} (확정 가격 고정)`,
        });
        continue;
      }
      if (oldPoc && atr > 0 && Math.abs(z.midpoint - oldPoc.midpoint) > atr * 0.5) {
        out.push({
          ...oldPoc,
          status: 'INVALID',
          reason: 'POC 유의미 이동 — 기존 존 무효, 신규 존 생성',
        });
        out.push({
          ...z,
          zone_id: `poc:reloc:${z.created_at}`,
          frozen: true,
          reason: 'POC 재배치(신규 존)',
        });
        continue;
      }
    }
    const old = byId.get(z.zone_id);
    if (old) {
      usedPrev.add(old.zone_id);
      out.push({
        ...z,
        lower: old.lower,
        upper: old.upper,
        midpoint: old.midpoint,
        frozen: true,
        created_at: old.created_at,
      });
      continue;
    }
    out.push(z);
  }

  for (const old of prev) {
    if (usedPrev.has(old.zone_id)) continue;
    if (old.status === 'DELETED') continue;
    if (old.status === 'BROKEN' || old.status === 'INVALID') {
      out.push(old);
    }
  }
  return out;
}

export function confirmedZoneBoundsMoved(before: Eagle1Zone, after: Eagle1Zone): boolean {
  if (!before.frozen) return false;
  return before.lower !== after.lower || before.upper !== after.upper;
}

/**
 * Setup-family expectancy from causal prefix replay. No shuffle, no future bars at T.
 */

import { detectStructureCausal, type Eagle1Bar } from './structureEngine';
import { detectZonesCausal } from './zoneEngine';
import { chronologicalSplit } from './chronologicalSplit';

export type SetupFamily =
  | 'poc_hold'
  | 'poc_reclaim'
  | 'ob_retest'
  | 'fvg_retest'
  | 'sweep_reversal'
  | 'pullback';

export type SetupOutcome = {
  family: SetupFamily;
  regime: string;
  direction: 'LONG' | 'SHORT';
  index: number;
  tpFirst: boolean;
  slFirst: boolean;
  mfe: number;
  mae: number;
  netR: number;
};

export type FamilyStats = {
  family: SetupFamily;
  sampleSize: number;
  tpBeforeSlRate: number | null;
  slFirstRate: number | null;
  medianMfe: number | null;
  medianMae: number | null;
  netExpectancy: number | null;
};

export type ExpectancyCatalog = {
  symbol: string;
  timeframe: string;
  families: FamilyStats[];
  holdoutCalibrationError: number | null;
  calculated_at: number;
  bar_count: number;
};

const MIN_STAT = 30;

function median(xs: number[]): number | null {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
}

function classifyFamily(params: {
  structureState: string;
  pocState: string;
  inOb: boolean;
  inFvg: boolean;
}): SetupFamily {
  if (params.inFvg) return 'fvg_retest';
  if (params.inOb) return 'ob_retest';
  if (params.pocState === 'RECLAIMED' || params.pocState === 'CLOSED_ABOVE') return 'poc_reclaim';
  if (params.pocState === 'APPROACH' || params.pocState === 'RETEST' || params.pocState === 'HOLD_SUCCESS') {
    return 'poc_hold';
  }
  if (params.structureState === 'SWEEP' || params.structureState === 'SHIFT') return 'sweep_reversal';
  return 'pullback';
}

function simulateForward(params: {
  candles: Eagle1Bar[];
  start: number;
  direction: 'LONG' | 'SHORT';
  entry: number;
  sl: number;
  tp: number;
  horizon: number;
}): { tpFirst: boolean; slFirst: boolean; mfe: number; mae: number; netR: number } {
  const { candles, start, direction, entry, sl, tp, horizon } = params;
  const risk = Math.abs(entry - sl) || 1;
  let mfe = 0;
  let mae = 0;
  let tpFirst = false;
  let slFirst = false;
  const end = Math.min(candles.length, start + 1 + horizon);
  for (let i = start + 1; i < end; i++) {
    const b = candles[i]!;
    if (direction === 'LONG') {
      mae = Math.max(mae, Math.max(0, entry - b.low) / risk);
      mfe = Math.max(mfe, Math.max(0, b.high - entry) / risk);
      const hitSl = b.low <= sl;
      const hitTp = b.high >= tp;
      if (hitSl && hitTp) {
        slFirst = true;
        break;
      }
      if (hitSl) {
        slFirst = true;
        break;
      }
      if (hitTp) {
        tpFirst = true;
        break;
      }
    } else {
      mae = Math.max(mae, Math.max(0, b.high - entry) / risk);
      mfe = Math.max(mfe, Math.max(0, entry - b.low) / risk);
      const hitSl = b.high >= sl;
      const hitTp = b.low <= tp;
      if (hitSl && hitTp) {
        slFirst = true;
        break;
      }
      if (hitSl) {
        slFirst = true;
        break;
      }
      if (hitTp) {
        tpFirst = true;
        break;
      }
    }
  }
  const netR = tpFirst ? mfe - 0.04 : slFirst ? -mae - 0.04 : 0;
  return { tpFirst, slFirst, mfe, mae, netR };
}

export function walkSetupOutcomes(params: {
  candles: Eagle1Bar[];
  stride?: number;
  horizon?: number;
  maxPrefixes?: number;
  swingLeft?: number;
}): SetupOutcome[] {
  const candles = params.candles;
  const stride = Math.max(8, params.stride ?? 24);
  const horizon = params.horizon ?? 24;
  const swingLeft = params.swingLeft ?? 3;
  const maxPrefixes = params.maxPrefixes ?? 80;
  const out: SetupOutcome[] = [];
  if (candles.length < 80) return out;
  const start = 60;
  const last = candles.length - horizon - 2;
  const indices: number[] = [];
  for (let i = start; i < last; i += stride) indices.push(i);
  const picked = indices.length > maxPrefixes ? indices.slice(-maxPrefixes) : indices;
  for (const t of picked) {
    const structure = detectStructureCausal(candles, t, swingLeft);
    const zones = detectZonesCausal({ candles, timeframe: 'walk', structure, endExclusive: t });
    const lastBar = candles[t - 1];
    if (!lastBar) continue;
    const locHigh = Math.max(...candles.slice(Math.max(0, t - 20), t).map((c) => c.high));
    const locLow = Math.min(...candles.slice(Math.max(0, t - 20), t).map((c) => c.low));
    const span = locHigh - locLow;
    if (!(span > 0)) continue;
    const pos = (lastBar.close - locLow) / span;
    const preferLong = pos < 0.45 || structure.state === 'SHIFT' && structure.events.slice(-1)[0]?.bias === 'bullish';
    const shift = [...structure.events].reverse().find((e) => e.kind === 'CHOCH' || e.kind === 'BOS');
    const direction: 'LONG' | 'SHORT' =
      shift?.bias === 'bearish' ? 'SHORT' : shift?.bias === 'bullish' ? 'LONG' : preferLong ? 'LONG' : 'SHORT';
    const ob = zones.zones.find((z) => z.source_type === 'ob' && z.bias === (direction === 'LONG' ? 'bullish' : 'bearish'));
    const fvg = zones.zones.find((z) => z.source_type === 'fvg' && z.bias === (direction === 'LONG' ? 'bullish' : 'bearish'));
    const inOb = !!(ob && lastBar.close <= ob.upper && lastBar.close >= ob.lower);
    const inFvg = !!(fvg && lastBar.close <= fvg.upper && lastBar.close >= fvg.lower);
    const family = classifyFamily({
      structureState: structure.state,
      pocState: zones.profile.pocState,
      inOb,
      inFvg,
    });
    const entry = lastBar.close;
    const sl =
      direction === 'LONG'
        ? structure.lastSwingLow?.price ?? lastBar.low
        : structure.lastSwingHigh?.price ?? lastBar.high;
    const tp =
      direction === 'LONG'
        ? structure.lastSwingHigh?.price ?? lastBar.high
        : structure.lastSwingLow?.price ?? lastBar.low;
    if (direction === 'LONG' && !(tp > entry && sl < entry)) continue;
    if (direction === 'SHORT' && !(tp < entry && sl > entry)) continue;
    const sim = simulateForward({ candles, start: t - 1, direction, entry, sl, tp, horizon });
    out.push({
      family,
      regime: structure.regime,
      direction,
      index: t - 1,
      ...sim,
    });
  }
  return out;
}

export function summarizeFamilies(rows: SetupOutcome[]): FamilyStats[] {
  const names: SetupFamily[] = ['poc_hold', 'poc_reclaim', 'ob_retest', 'fvg_retest', 'sweep_reversal', 'pullback'];
  return names.map((family) => {
    const xs = rows.filter((r) => r.family === family);
    const n = xs.length;
    const tp = xs.filter((r) => r.tpFirst).length;
    const sl = xs.filter((r) => r.slFirst).length;
    return {
      family,
      sampleSize: n,
      tpBeforeSlRate: n >= MIN_STAT ? tp / n : null,
      slFirstRate: n >= MIN_STAT ? sl / n : null,
      medianMfe: n >= MIN_STAT ? median(xs.map((r) => r.mfe)) : null,
      medianMae: n >= MIN_STAT ? median(xs.map((r) => r.mae)) : null,
      netExpectancy: n >= MIN_STAT ? xs.reduce((a, r) => a + r.netR, 0) / n : null,
    };
  });
}

export function pickFamilyStats(catalog: ExpectancyCatalog | null | undefined, family: SetupFamily): FamilyStats | null {
  return catalog?.families.find((f) => f.family === family) ?? null;
}

export function calibrationError(rows: SetupOutcome[]): number | null {
  if (rows.length < MIN_STAT) return null;
  const split = chronologicalSplit(rows.length);
  const train = split.train.map((i) => rows[i]!).filter(Boolean);
  const hold = split.holdout.map((i) => rows[i]!).filter(Boolean);
  if (train.length < MIN_STAT || hold.length < 10) return null;
  const pTrain = train.filter((r) => r.tpFirst).length / train.length;
  const pHold = hold.filter((r) => r.tpFirst).length / hold.length;
  return Math.abs(pTrain - pHold);
}

export function buildExpectancyCatalog(params: {
  candles: Eagle1Bar[];
  symbol: string;
  timeframe: string;
  stride?: number;
  maxPrefixes?: number;
}): ExpectancyCatalog {
  const rows = walkSetupOutcomes({
    candles: params.candles,
    stride: params.stride,
    maxPrefixes: params.maxPrefixes,
  });
  return {
    symbol: params.symbol,
    timeframe: params.timeframe,
    families: summarizeFamilies(rows),
    holdoutCalibrationError: calibrationError(rows),
    calculated_at: Date.now(),
    bar_count: params.candles.length,
  };
}

/**
 * Match current snapshot to past outcomes — regime first. Never use raw AI score as probability.
 */

import type { SetupFamily, SetupOutcome } from './zoneExpectancy';
import type { Eagle1Regime, StructureState } from './structureEngine';

export type SimilarityQuery = {
  regime: Eagle1Regime;
  state: StructureState;
  family: SetupFamily;
  direction: 'LONG' | 'SHORT';
};

export type SimilarityReport = {
  sampleSize: number;
  calibratedProbability: number | null;
  calibratedLabel: '검증확률' | '통계 부족';
  tpBeforeSlRate: number | null;
  slFirstRate: number | null;
  medianMfe: number | null;
  medianMae: number | null;
  netExpectancy: number | null;
  calibrationError: number | null;
  filter: string;
};

const MIN = 30;

function med(xs: number[]): number | null {
  if (!xs.length) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m]! : (s[m - 1]! + s[m]!) / 2;
}

export function matchSimilarOutcomes(rows: SetupOutcome[], q: SimilarityQuery): SimilarityReport {
  const empty = (filter: string, n = 0): SimilarityReport => ({
    sampleSize: n,
    calibratedProbability: null,
    calibratedLabel: '통계 부족',
    tpBeforeSlRate: null,
    slFirstRate: null,
    medianMfe: null,
    medianMae: null,
    netExpectancy: null,
    calibrationError: null,
    filter,
  });
  if (!rows.length) return empty('데이터 없음');

  let pool = rows.filter((r) => r.regime === q.regime && r.direction === q.direction && r.family === q.family);
  let filter = `레짐 ${q.regime} + ${q.family} + ${q.direction}`;
  if (pool.length < MIN) {
    pool = rows.filter((r) => r.regime === q.regime && r.direction === q.direction);
    filter = `레짐 ${q.regime} + ${q.direction}`;
  }
  if (pool.length < MIN) {
    pool = rows.filter((r) => r.direction === q.direction && r.family === q.family);
    filter = `${q.family} + ${q.direction}`;
  }
  if (pool.length < MIN) return empty(filter, pool.length);

  const tp = pool.filter((r) => r.tpFirst).length;
  const sl = pool.filter((r) => r.slFirst).length;
  const p = tp / pool.length;
  return {
    sampleSize: pool.length,
    calibratedProbability: p,
    calibratedLabel: '검증확률',
    tpBeforeSlRate: p,
    slFirstRate: sl / pool.length,
    medianMfe: med(pool.map((r) => r.mfe)),
    medianMae: med(pool.map((r) => r.mae)),
    netExpectancy: pool.reduce((a, r) => a + r.netR, 0) / pool.length,
    calibrationError: null,
    filter,
  };
}

/**
 * HTF → LTF confirmation sequence. Missing HTF → 데이터 없음, no fake alignment.
 */

import type { StructureSnapshot } from './structureEngine';

export type MtfSequenceReport = {
  htfRegime: string;
  htfState: string;
  ltfState: string;
  aligned: boolean | null;
  sequence: string[];
  note: string;
};

export function evaluateMtfSequence(params: {
  htf: StructureSnapshot | null | undefined;
  ltf: StructureSnapshot;
}): MtfSequenceReport {
  const ltf = params.ltf;
  if (!params.htf) {
    return {
      htfRegime: '데이터 없음',
      htfState: '데이터 없음',
      ltfState: ltf.state,
      aligned: null,
      sequence: [],
      note: '상위 TF 구조 없음 — 정렬 단정 금지',
    };
  }
  const htf = params.htf;
  const htfBias = [...htf.events].reverse().find((e) => e.kind === 'CHOCH' || e.kind === 'BOS' || e.kind === 'SWEEP');
  const ltfBias = [...ltf.events].reverse().find((e) => e.kind === 'CHOCH' || e.kind === 'BOS' || e.kind === 'SWEEP');
  const seq: string[] = [];
  if (htfBias?.kind === 'SWEEP') seq.push(`4H/상위 유동성털기(${htfBias.bias === 'bullish' ? '아래' : '위'})`);
  if (htfBias?.kind === 'CHOCH' || htfBias?.kind === 'BOS') {
    seq.push(`상위 ${htfBias.kind === 'CHOCH' ? '추세전환' : '구조돌파'}`);
  }
  if (ltf.state === 'SHIFT' || ltf.state === 'RETEST' || ltf.state === 'CONFIRMED') {
    seq.push(`하위 ${ltf.state === 'SHIFT' ? '추세전환' : ltf.state === 'RETEST' ? '재확인' : '확정'}`);
  }
  let aligned: boolean | null = null;
  if (htfBias && ltfBias) {
    aligned = htfBias.bias === ltfBias.bias;
  } else if (htf.regime === 'BULL' || htf.regime === 'STRONG_BULL') {
    aligned = ltfBias?.bias !== 'bearish';
  } else if (htf.regime === 'BEAR' || htf.regime === 'STRONG_BEAR') {
    aligned = ltfBias?.bias !== 'bullish';
  }
  return {
    htfRegime: htf.regime,
    htfState: htf.state,
    ltfState: ltf.state,
    aligned,
    sequence: seq,
    note: aligned === false ? '상위/하위 충돌 — 확정 억제' : aligned === true ? '상위→하위 시퀀스 정합' : '정렬 판단 보류',
  };
}

/**
 * Trade management after a frozen plan. Original path points never follow price.
 */

import type { Eagle1Bar } from './structureEngine';

export type TradeManageState =
  | 'NONE'
  | 'OPEN'
  | 'TP1_HIT'
  | 'BREAKEVEN'
  | 'TP2_HIT'
  | 'TP3_HIT'
  | 'INVALIDATED';

export type FrozenPathPoint = {
  time: number;
  price: number;
  label: string;
};

export type FrozenTrade = {
  identity: string;
  direction: 'LONG' | 'SHORT';
  entry: number;
  sl: number;
  tp1: number;
  tp2: number | null;
  tp3: number | null;
  state: TradeManageState;
  path: FrozenPathPoint[];
  altPath: FrozenPathPoint[];
  pathState: '진행중' | '이탈주의' | '무효';
  openedAt: number;
};

export function planIdentity(params: {
  direction: 'LONG' | 'SHORT';
  entry: number;
  sl: number;
}): string {
  return `${params.direction}:${Math.round(params.entry * 10) / 10}:${Math.round(params.sl * 10) / 10}`;
}

export function buildFrozenPath(params: {
  lastTime: number;
  tfSec: number;
  direction: 'LONG' | 'SHORT';
  entry: number;
  sl: number;
  tp1: number;
  tp2: number | null;
  tp3: number | null;
}): { path: FrozenPathPoint[]; altPath: FrozenPathPoint[] } {
  const step = Math.max(60, params.tfSec);
  const path: FrozenPathPoint[] = [
    { time: params.lastTime, price: params.entry, label: '진입' },
    { time: params.lastTime + step, price: params.tp1, label: '목표1' },
  ];
  if (params.tp2 != null) path.push({ time: params.lastTime + step * 3, price: params.tp2, label: '목표2' });
  if (params.tp3 != null) path.push({ time: params.lastTime + step * 6, price: params.tp3, label: '목표3' });
  const altPath: FrozenPathPoint[] = [
    { time: params.lastTime, price: params.entry, label: '진입' },
    { time: params.lastTime + step * 2, price: params.sl, label: '무효가격' },
  ];
  return { path, altPath };
}

function hitBothSameBar(direction: 'LONG' | 'SHORT', bar: Eagle1Bar, sl: number, tp: number): 'sl' | 'tp' | null {
  if (direction === 'LONG') {
    const slHit = bar.low <= sl;
    const tpHit = bar.high >= tp;
    if (slHit && tpHit) return 'sl';
    if (slHit) return 'sl';
    if (tpHit) return 'tp';
  } else {
    const slHit = bar.high >= sl;
    const tpHit = bar.low <= tp;
    if (slHit && tpHit) return 'sl';
    if (slHit) return 'sl';
    if (tpHit) return 'tp';
  }
  return null;
}

export function pathStateFromPrice(params: {
  close: number;
  direction: 'LONG' | 'SHORT';
  sl: number;
  entry: number;
  tradeState: TradeManageState;
}): FrozenTrade['pathState'] {
  if (params.tradeState === 'INVALIDATED') return '무효';
  if (params.tradeState === 'TP3_HIT') return '진행중';
  const against =
    params.direction === 'LONG'
      ? params.close < params.entry && params.close > params.sl
      : params.close > params.entry && params.close < params.sl;
  if (against) return '이탈주의';
  return '진행중';
}

export function advanceFrozenTrade(params: {
  prev: FrozenTrade | null | undefined;
  candles: Eagle1Bar[];
  endExclusive?: number;
  candidate: {
    direction: 'LONG' | 'SHORT';
    entry: number;
    sl: number;
    tp1: number;
    tp2: number | null;
    tp3: number | null;
    lastTime: number;
    tfSec: number;
    confirm: boolean;
  };
}): FrozenTrade | null {
  const n = Math.min(params.candles.length, params.endExclusive ?? params.candles.length);
  const last = params.candles[n - 1];
  if (!last) return null;
  const id = planIdentity(params.candidate);
  let trade = params.prev && params.prev.identity === id ? { ...params.prev } : null;

  if (!trade) {
    if (!params.candidate.confirm) return params.prev ?? null;
    const built = buildFrozenPath({
      lastTime: params.candidate.lastTime,
      tfSec: params.candidate.tfSec,
      direction: params.candidate.direction,
      entry: params.candidate.entry,
      sl: params.candidate.sl,
      tp1: params.candidate.tp1,
      tp2: params.candidate.tp2,
      tp3: params.candidate.tp3,
    });
    trade = {
      identity: id,
      direction: params.candidate.direction,
      entry: params.candidate.entry,
      sl: params.candidate.sl,
      tp1: params.candidate.tp1,
      tp2: params.candidate.tp2,
      tp3: params.candidate.tp3,
      state: 'OPEN',
      path: built.path,
      altPath: built.altPath,
      pathState: '진행중',
      openedAt: params.candidate.lastTime,
    };
  }

  const from = params.candles.findIndex((c) => c.time >= trade!.openedAt);
  const start = from >= 0 ? from : Math.max(0, n - 8);
  for (let i = start; i < n; i++) {
    const bar = params.candles[i]!;
    if (trade.state === 'INVALIDATED' || trade.state === 'TP3_HIT') break;
    const nextTp =
      trade.state === 'OPEN' || trade.state === 'BREAKEVEN'
        ? trade.tp1
        : trade.state === 'TP1_HIT'
          ? trade.tp2
          : trade.tp3;
    const slNow = trade.state === 'TP1_HIT' || trade.state === 'BREAKEVEN' ? trade.entry : trade.sl;
    if (nextTp == null) continue;
    const hit = hitBothSameBar(trade.direction, bar, slNow, nextTp);
    if (hit === 'sl') {
      trade = { ...trade, state: 'INVALIDATED' };
      break;
    }
    if (hit === 'tp') {
      if (trade.state === 'OPEN' || trade.state === 'BREAKEVEN') {
        trade = { ...trade, state: 'TP1_HIT' };
      } else if (trade.state === 'TP1_HIT') {
        trade = { ...trade, state: 'TP2_HIT' };
      } else if (trade.state === 'TP2_HIT') {
        trade = { ...trade, state: 'TP3_HIT' };
      }
    }
  }

  const close = last.close;
  return {
    ...trade,
    pathState: pathStateFromPrice({
      close,
      direction: trade.direction,
      sl: trade.sl,
      entry: trade.entry,
      tradeState: trade.state,
    }),
  };
}

export function pathPointsUnchanged(a: FrozenPathPoint[], b: FrozenPathPoint[]): boolean {
  if (a.length !== b.length) return false;
  return a.every((p, i) => p.time === b[i]!.time && p.price === b[i]!.price && p.label === b[i]!.label);
}

/**
 * Server-only freeze + stats JSON. Pipeline stays filesystem-free.
 */
import fs from 'fs';
import path from 'path';
import { EAGLE1_META_DIR } from './historicalDatabase';
import type { Eagle1Zone } from './zoneEngine';
import type { FrozenTrade } from './tradeManage';
import type { ExpectancyCatalog } from './zoneExpectancy';
import type { SetupOutcome } from './zoneExpectancy';

export type Eagle1FreezeFile = {
  symbol: string;
  timeframe: string;
  zones: Eagle1Zone[];
  trade: FrozenTrade | null;
  updated_at: number;
};

function freezePath(symbol: string, timeframe: string, root: string): string {
  const dir = path.join(root, EAGLE1_META_DIR, 'freeze');
  fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, `${symbol}_${timeframe}.json`);
}

function statsPath(symbol: string, timeframe: string, root: string): string {
  const dir = path.join(root, EAGLE1_META_DIR, 'stats');
  fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, `${symbol}_${timeframe}.json`);
}

function outcomesPath(symbol: string, timeframe: string, root: string): string {
  const dir = path.join(root, EAGLE1_META_DIR, 'stats');
  fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, `${symbol}_${timeframe}_outcomes.json`);
}

export function loadEagle1Freeze(symbol: string, timeframe: string, root = process.cwd()): Eagle1FreezeFile | null {
  try {
    const file = freezePath(symbol, timeframe, root);
    if (!fs.existsSync(file)) return null;
    const raw = JSON.parse(fs.readFileSync(file, 'utf8')) as Eagle1FreezeFile;
    if (!raw || !Array.isArray(raw.zones)) return null;
    return raw;
  } catch {
    return null;
  }
}

export function saveEagle1Freeze(row: Eagle1FreezeFile, root = process.cwd()): void {
  const file = freezePath(row.symbol, row.timeframe, root);
  fs.writeFileSync(file, JSON.stringify(row, null, 2), 'utf8');
}

export function loadExpectancyCatalog(
  symbol: string,
  timeframe: string,
  root = process.cwd()
): ExpectancyCatalog | null {
  try {
    const file = statsPath(symbol, timeframe, root);
    if (!fs.existsSync(file)) return null;
    return JSON.parse(fs.readFileSync(file, 'utf8')) as ExpectancyCatalog;
  } catch {
    return null;
  }
}

export function saveExpectancyCatalog(cat: ExpectancyCatalog, root = process.cwd()): void {
  const file = statsPath(cat.symbol, cat.timeframe, root);
  fs.writeFileSync(file, JSON.stringify(cat, null, 2), 'utf8');
}

export function loadSetupOutcomes(symbol: string, timeframe: string, root = process.cwd()): SetupOutcome[] {
  try {
    const file = outcomesPath(symbol, timeframe, root);
    if (!fs.existsSync(file)) return [];
    const raw = JSON.parse(fs.readFileSync(file, 'utf8')) as { rows?: SetupOutcome[] };
    return Array.isArray(raw.rows) ? raw.rows : [];
  } catch {
    return [];
  }
}

export function saveSetupOutcomes(
  symbol: string,
  timeframe: string,
  rows: SetupOutcome[],
  root = process.cwd()
): void {
  const file = outcomesPath(symbol, timeframe, root);
  fs.writeFileSync(file, JSON.stringify({ symbol, timeframe, rows, n: rows.length }, null, 2), 'utf8');
}

