      reason: '아래쪽 유동성',
      status: 'CONFIRMED',
      test_count: 0,
      last_test_at: null,
      bias: 'bullish',
      tier: 'C',
      frozen: true,
    });
  }

  const frozen0 = zones.map((z) => (z.status === 'PENDING' ? z : freezeZone(z)));
  const frozen = inheritFrozenZones({
    fresh: frozen0,
    prev: params.prevFrozen,
    candles,
    endExclusive: n,
  }).filter((z) => z.status !== 'DELETED');
  const clusters = clusterZones(frozen);
  const lastPx = candles[n - 1]?.close ?? 0;
  const { support, resist } = capSupportResist(clusters);
  return {
    zones: frozen,
    clusters,
    recommended: pickRecommendedCluster(support, resist, lastPx, structure),
    displaySupport: support,
    displayResist: resist,
    profile,
  };
}

function clusterScore(c: ZoneCluster): number {
  const t = c.tier === 'S' ? 4 : c.tier === 'A' ? 3 : c.tier === 'B' ? 2 : 1;
  return t * 10 + c.components.length;
}

function capSupportResist(clusters: ZoneCluster[]): { support: ZoneCluster[]; resist: ZoneCluster[] } {
  const support = clusters
    .filter((c) => c.bias === 'bullish' || (c.bias === 'neutral' && c.sources.includes('poc')))
    .sort((a, b) => clusterScore(b) - clusterScore(a))
    .slice(0, 3);
  const resist = clusters
    .filter((c) => c.bias === 'bearish')
    .sort((a, b) => clusterScore(b) - clusterScore(a))
    .slice(0, 3);
  return { support, resist };
}

export function pickRecommendedCluster(
  support: ZoneCluster[],
  resist: ZoneCluster[],
  price: number,
  structure: StructureSnapshot
): ZoneCluster | null {
  const preferLong = structure.regime === 'BULL' || structure.regime === 'STRONG_BULL' || structure.state === 'SHIFT';
  const pool = preferLong && support.length ? support : resist.length ? resist : support;
  if (!pool.length || !(price > 0)) return pool[0] ?? null;
  return [...pool].sort((a, b) => {
    const da = Math.min(Math.abs(price - a.lower), Math.abs(price - a.upper), price >= a.lower && price <= a.upper ? 0 : 1e9);
    const db = Math.min(Math.abs(price - b.lower), Math.abs(price - b.upper), price >= b.lower && price <= b.upper ? 0 : 1e9);
    return da - db || clusterScore(b) - clusterScore(a);
  })[0] ?? null;
}

function sourceKo(s: ZoneSource): string {
  if (s === 'poc') return 'POC';
  if (s === 'ob') return '주문구간';
  if (s === 'fvg') return '가격빈틈';
  if (s === 'bpr') return '균형';
  if (s === 'breaker') return '돌파전환';
  if (s === 'demand') return '매수수요';
  if (s === 'supply') return '매도공급';
  if (s === 'hvn') return '고거래';
  if (s === 'liquidity') return '유동성';
  return s;
}

export function clusterZones(zones: Eagle1Zone[]): ZoneCluster[] {
  const live = zones.filter((z) => z.status !== 'INVALID' && z.status !== 'DELETED' && z.status !== 'BROKEN');
  const used = new Set<string>();
  const clusters: ZoneCluster[] = [];
  for (const z of live) {
    if (used.has(z.zone_id)) continue;
    const group = [z];
    used.add(z.zone_id);
    for (const o of live) {
      if (used.has(o.zone_id)) continue;
      if (z.bias !== 'neutral' && o.bias !== 'neutral' && z.bias !== o.bias) continue;
      if (overlapRatio(z.lower, z.upper, o.lower, o.upper) >= 0.35) {
        group.push(o);
        used.add(o.zone_id);
      }
    }
    const lower = Math.min(...group.map((g) => g.lower));
    const upper = Math.max(...group.map((g) => g.upper));
    const bull = group.filter((g) => g.bias === 'bullish').length;
    const bear = group.filter((g) => g.bias === 'bearish').length;
    const bias: ZoneCluster['bias'] = bull > bear ? 'bullish' : bear > bull ? 'bearish' : 'neutral';
    const tier = group.some((g) => g.tier === 'S') ? 'S' : group.some((g) => g.tier === 'A') ? 'A' : group.some((g) => g.tier === 'B') ? 'B' : 'C';
    const sources = [...new Set(group.map((g) => g.source_type))];
    const mix = sources.map(sourceKo).slice(0, 4).join('+');
    clusters.push({
      cluster_id: `cl:${group.map((g) => g.zone_id).join('+')}`,
      labelKo:
        bias === 'bullish'
          ? `핵심 매수구간${mix ? ` · ${mix}` : ''}`
          : bias === 'bearish'
            ? `핵심 매도구간${mix ? ` · ${mix}` : ''}`
            : `핵심 구간${mix ? ` · ${mix}` : ''}`,
      lower,
      upper,
      bias,
      components: group,
      tier,
      sources,
    });
  }
  return clusters.sort((a, b) => clusterScore(b) - clusterScore(a));
}

export function confirmedBoundsImmutable(before: Eagle1Zone, after: Eagle1Zone): boolean {
  if (before.status === 'PENDING' || !before.frozen) return true;
  return before.lower === after.lower && before.upper === after.upper && before.zone_id === after.zone_id;
}

export function zoneVisibleInDefaultUi(z: Eagle1Zone): boolean {
  return z.status !== 'BROKEN' && z.status !== 'INVALID' && z.status !== 'DELETED' && z.tier !== 'C';
}

/**
 * Eagle1 zones → chart overlays. Formation time → last candle. No whale cards.
 */

import type { OverlayItem } from '@/types';
import type { Eagle1ChartMode } from './chartUx';
import type { Eagle1Zone, ZoneCluster } from './zoneEngine';
import { zoneVisibleInDefaultUi } from './zoneEngine';

function kindOf(z: Eagle1Zone): OverlayItem['kind'] {
  if (z.source_type === 'fvg') return 'fvg';
  if (z.source_type === 'ob' || z.source_type === 'breaker') return 'ob';
  if (z.source_type === 'bpr') return 'bprZone';
  if (z.bias === 'bullish' || z.source_type === 'demand' || z.source_type === 'val') return 'demandZone';
  if (z.bias === 'bearish' || z.source_type === 'supply' || z.source_type === 'vah') return 'supplyZone';
  return 'zone';
}

function colorOf(z: Eagle1Zone): string {
  if (z.bias === 'bullish' || z.source_type === 'demand' || z.source_type === 'val') return 'rgba(16,185,129,0.16)';
  if (z.bias === 'bearish' || z.source_type === 'supply' || z.source_type === 'vah') return 'rgba(244,63,94,0.16)';
  if (z.source_type === 'poc') return 'rgba(250,204,21,0.14)';
  return 'rgba(148,163,184,0.12)';
}

function labelOf(z: Eagle1Zone): string {
  if (z.source_type === 'poc') return '최다거래가격';
  if (z.source_type === 'ob') return z.bias === 'bullish' ? '핵심 매수구간' : '핵심 매도구간';
  if (z.source_type === 'fvg') return '가격빈틈';
  if (z.source_type === 'bpr') return '균형가격구간';
  if (z.source_type === 'breaker') return '돌파전환구간';
  if (z.source_type === 'demand') return '매수수요';
  if (z.source_type === 'supply') return '매도공급';
  if (z.source_type === 'liquidity') return z.bias === 'bullish' ? '아래쪽 유동성' : '위쪽 유동성';
  if (z.source_type === 'hvn') return '고거래량';
  if (z.source_type === 'vah') return 'VAH';
  if (z.source_type === 'val') return 'VAL';
  return z.reason.split('·')[0]!.trim();
}

function toOverlay(z: Eagle1Zone, lastTime: number, id: string): OverlayItem {
  return {
    id,
    kind: kindOf(z),
    label: labelOf(z),
    x1: 0,
    y1: 0,
    x2: 1,
    y2: 1,
    time1: z.created_at,
    time2: lastTime,
    price1: z.upper,
    price2: z.lower,
    priceFrozen1: z.upper,
    priceFrozen2: z.lower,
    confidence: Math.round(z.strength * 100),
    color: colorOf(z),
    category: 'zones',
    noProject: true,
    overlayZoneExtraClass: `eagle1-zone eagle1-zone--${z.source_type}`,
    labelTooltip: z.reason,
  };
}

export function eagle1ZonesToOverlays(params: {
  zones?: Eagle1Zone[] | null;
  clusters?: ZoneCluster[] | null;
  recommended?: ZoneCluster | null;
  lastTime: number;
  mode: Eagle1ChartMode;
}): OverlayItem[] {
  const lastTime = params.lastTime;
  if (!(lastTime > 0)) return [];
  const mode = params.mode || 'practical';
  const zones = params.zones ?? [];
  const out: OverlayItem[] = [];

  if (mode === 'practical') {
    const poc = zones.find((z) => z.source_type === 'poc' && zoneVisibleInDefaultUi(z));
    if (poc) out.push(toOverlay(poc, lastTime, 'eagle1-poc'));
    const rec = params.recommended;
    if (rec) {
      out.push({
        id: 'eagle1-cluster-main',
        kind: rec.bias === 'bearish' ? 'supplyZone' : 'demandZone',
        label: rec.labelKo.split('·')[0]!.trim(),
        x1: 0,
        y1: 0,
        x2: 1,
        y2: 1,
        time1: Math.min(...rec.components.map((c) => c.created_at)),
        time2: lastTime,
        price1: rec.upper,
        price2: rec.lower,
        priceFrozen1: rec.upper,
        priceFrozen2: rec.lower,
        confidence: 80,
        color: rec.bias === 'bearish' ? 'rgba(244,63,94,0.18)' : 'rgba(16,185,129,0.18)',
        category: 'zones',
        noProject: true,
        overlayZoneExtraClass: 'eagle1-zone eagle1-zone--cluster',
        labelTooltip: rec.components.map((c) => c.reason).join(' / '),
      });
    }
    return out;
  }

  const live = zones.filter((z) =>
    mode === 'research' ? z.status !== 'DELETED' : zoneVisibleInDefaultUi(z)
  );
  const ranked = [...live].sort((a, b) => {
    const ta = a.tier === 'S' ? 0 : a.tier === 'A' ? 1 : a.tier === 'B' ? 2 : 3;
    const tb = b.tier === 'S' ? 0 : b.tier === 'A' ? 1 : b.tier === 'B' ? 2 : 3;
    return ta - tb;
  });
  const cap = mode === 'research' ? ranked : ranked.slice(0, 10);
  for (const z of cap) {
    const prefix =
      z.source_type === 'poc'
        ? 'eagle1-poc'
        : z.source_type === 'ob'
          ? 'eagle1-ob'
          : z.source_type === 'fvg'
            ? 'eagle1-fvg'
            : z.source_type === 'bpr'
              ? 'eagle1-bpr'
              : z.source_type === 'breaker'
                ? 'eagle1-breaker'
                : z.source_type === 'liquidity'
                  ? 'eagle1-liq'
                  : `eagle1-${z.source_type}`;
    out.push(toOverlay(z, lastTime, `${prefix}-${z.zone_id.replace(/[^a-zA-Z0-9:_-]/g, '')}`));
  }
  return out;
}

