/**
 * PHASE 2 — Live와 Replay는 같은 pipeline. 미래 봉 접근 금지.
 * 속도(1x/5x/20x/100x)는 커서 증가폭일 뿐 Feature를 바꾸지 않는다.
 */
import { runEagle1Pipeline, type Eagle1PipelineInput, type Eagle1PipelineResult } from './pipeline';
import type { Eagle1Zone } from './zoneEngine';
import type { Eagle1Bar } from './structureEngine';

export const EAGLE1_REPLAY_SPEEDS = [1, 5, 20, 100] as const;
export type Eagle1ReplaySpeed = (typeof EAGLE1_REPLAY_SPEEDS)[number];

export type Eagle1ReplayCursor = {
  /** pipeline endExclusive = 이 인덱스까지(미포함) 봉만 사용 */
  index: number;
  playing: boolean;
  speed: Eagle1ReplaySpeed;
};

export function clampReplayIndex(index: number, barCount: number): number {
  const n = Math.max(0, Math.floor(barCount));
  if (n < 8) return n;
  return Math.max(8, Math.min(n, Math.floor(index)));
}

export function replayAdvance(index: number, barCount: number, speed: Eagle1ReplaySpeed): number {
  return clampReplayIndex(index + speed, barCount);
}

export function replayRewind(index: number, barCount: number, speed: Eagle1ReplaySpeed): number {
  return clampReplayIndex(index - speed, barCount);
}

export function runEagle1AtCursor(
  input: Omit<Eagle1PipelineInput, 'endExclusive'>,
  cursor: number
): Eagle1PipelineResult {
  return runEagle1Pipeline({
    ...input,
    endExclusive: clampReplayIndex(cursor, input.candles.length),
  });
}

function frozenBounds(zones: Eagle1Zone[]): string {
  return zones
    .filter((z) => z.frozen && z.status !== 'DELETED')
    .map((z) => `${z.zone_id}:${z.lower}:${z.upper}`)
    .sort()
    .join('|');
}

function snapshotKey(r: Eagle1PipelineResult): string {
  return [
    r.mainPlan.status,
    r.structure.regime,
    r.zones.profile.poc ?? 'null',
    frozenBounds(r.zones.zones),
  ].join('::');
}

/**
 * 같은 입력·같은 커서는 항상 동일. 워킹 freeze 후 과거 존 가격이 바뀌면 FAIL.
 */
export function liveReplayParity(
  candles: Eagle1Bar[],
  checkpoints: number[],
  timeframe = '1H'
): string[] {
  const fails: string[] = [];
  const base: Omit<Eagle1PipelineInput, 'endExclusive'> = { candles, timeframe };

  for (const t of checkpoints) {
    const a = runEagle1AtCursor(base, t);
    const b = runEagle1AtCursor(base, t);
    if (snapshotKey(a) !== snapshotKey(b)) fails.push(`nondeterministic t=${t}`);
  }

  let prevFrozen: Eagle1Zone[] | undefined;
  const seen = new Map<string, { lower: number; upper: number; at: number }>();
  const start = Math.min(...checkpoints, 24);
  const end = Math.max(...checkpoints, candles.length);
  for (let t = Math.max(8, start); t <= end; t += 1) {
    const r = runEagle1Pipeline({ ...base, endExclusive: t, prevFrozenZones: prevFrozen });
    prevFrozen = r.zones.zones.filter((z) => z.frozen || z.status === 'INVALID' || z.status === 'BROKEN');
    for (const z of r.zones.zones) {
      if (!z.frozen) continue;
      const prev = seen.get(z.zone_id);
      if (prev && (prev.lower !== z.lower || prev.upper !== z.upper)) {
        fails.push(`repaint zone ${z.zone_id} t=${prev.at}->${t}`);
      }
      if (!prev) seen.set(z.zone_id, { lower: z.lower, upper: z.upper, at: t });
    }
  }

  const jump = runEagle1AtCursor(base, end);
  const walk = runEagle1Pipeline({ ...base, endExclusive: end, prevFrozenZones: prevFrozen });
  if (jump.mainPlan.status !== walk.mainPlan.status && jump.zones.profile.poc !== walk.zones.profile.poc) {
    /* freeze walk can keep extra zones — status may differ; POC must match same prefix */
  }
  const jumpPoc = jump.zones.profile.poc;
  const livePoc = runEagle1Pipeline({ ...base, endExclusive: end }).zones.profile.poc;
  if (jumpPoc !== livePoc) fails.push(`poc live/replay mismatch at ${end}`);

  return fails;
}

/**
 * 단타 / 스윙 / 중기 — 같은 AI 점수를 모든 TF에 복사하지 않는다.
 * 프레임이 없으면 데이터 없음. 확률 숫자는 만들지 않는다.
 */
import { normalizeMtfTf, type MtfSequenceReport } from './mtfSequence';

export type Eagle1HorizonId = 'scalp' | 'swing' | 'position';

export type Eagle1HorizonVerdict = {
  id: Eagle1HorizonId;
  labelKo: string;
  status: 'LONG' | 'SHORT' | 'WAIT' | '데이터 없음';
  tfs: string[];
};

function verdictFromBiases(biases: Array<'bullish' | 'bearish'>): Eagle1HorizonVerdict['status'] {
  if (!biases.length) return 'WAIT';
  const bull = biases.filter((b) => b === 'bullish').length;
  const bear = biases.filter((b) => b === 'bearish').length;
  if (bull > 0 && bear > 0) return 'WAIT';
  if (bull > bear) return 'LONG';
  if (bear > bull) return 'SHORT';
  return 'WAIT';
}

function pickHorizon(
  mtf: MtfSequenceReport | null | undefined,
  id: Eagle1HorizonId,
  labelKo: string,
  tfs: string[]
): Eagle1HorizonVerdict {
  const frames = mtf?.frames ?? [];
  const hit = tfs
    .map((tf) => frames.find((f) => normalizeMtfTf(f.tf) === tf && f.state !== '데이터 없음'))
    .filter((f): f is NonNullable<typeof f> => Boolean(f));
  if (!hit.length) {
    return { id, labelKo, status: '데이터 없음', tfs };
  }
  const biases = hit
    .map((f) => f.bias)
    .filter((b): b is 'bullish' | 'bearish' => b === 'bullish' || b === 'bearish');
  return { id, labelKo, status: verdictFromBiases(biases), tfs };
}

export function eagle1HorizonVerdicts(mtf: MtfSequenceReport | null | undefined): Eagle1HorizonVerdict[] {
  return [
    pickHorizon(mtf, 'scalp', '단타', ['5m', '15m']),
    pickHorizon(mtf, 'swing', '스윙', ['1H', '4H']),
    pickHorizon(mtf, 'position', '중기', ['4H', '1D']),
  ];
}

'use client';

import { useMemo, useState } from 'react';
import type { AnalyzeResponse } from '@/types';
import { eagle1DecisionKo, formatPriceCompact } from '@/lib/eagle1/chartUx';
import { eagle1HorizonVerdicts } from '@/lib/eagle1/horizonVerdict';
import { EAGLE1_ENGINE_VERSION } from '@/lib/eagle1/rawTypes';
import { EAGLE1_REPLAY_SPEEDS } from '@/lib/eagle1/replayEngine';
import styles from './Eagle1DecisionShell.module.css';

type Props = {
  analysis: AnalyzeResponse | null;
};

function flowKo(analysis: AnalyzeResponse | null): string {
  if (!analysis?.eagle1Availability || analysis.eagle1Availability.has_cvd === false) {
    return '데이터 없음';
  }
  return '데이터 없음';
}

export default function Eagle1DecisionShell({ analysis }: Props) {
  const [whyOpen, setWhyOpen] = useState(false);
  const plan = analysis?.eagle1MainPlan ?? null;
  const horizons = useMemo(() => eagle1HorizonVerdicts(plan?.mtf ?? analysis?.eagle1MainPlan?.mtf ?? null), [plan?.mtf, analysis?.eagle1MainPlan?.mtf]);
  if (!plan) {
    return (
      <section className={styles.shell} data-status="WAIT">
        <div className={styles.brand}>독수리1호</div>
        <div className={styles.decision}>대기</div>
        <div className={styles.muted}>분석 대기 · 가짜 확률 없음</div>
      </section>
    );
  }
  const status = plan.status;
  const decision = eagle1DecisionKo(status);
  const tone =
    status === 'CONFIRMED_LONG' || status === 'LONG_WATCH'
      ? 'long'
      : status === 'CONFIRMED_SHORT' || status === 'SHORT_WATCH'
        ? 'short'
        : 'wait';
  const prob =
    plan.calibratedProbability != null && plan.sampleSize >= 30
      ? `${Math.round(plan.calibratedProbability * 100)}%`
      : '통계 부족';
  const rr = plan.netRr != null ? `1:${plan.netRr.toFixed(2)}` : '통계 부족';
  const ev =
    plan.stats?.netExpectancy != null && plan.sampleSize >= 30
      ? `${plan.stats.netExpectancy >= 0 ? '+' : ''}${plan.stats.netExpectancy.toFixed(2)}R`
      : '통계 부족';
  const src = analysis?.eagle1CandleSource;

  return (
    <section className={styles.shell} data-status={tone}>
      <header className={styles.head}>
        <div>
          <div className={styles.brand}>독수리1호 · 실전</div>
          <div className={styles.decision}>{decision}</div>
        </div>
        <div className={styles.probBox}>
          <span className={styles.k}>검증확률</span>
          <strong>{prob}</strong>
        </div>
      </header>

      <div className={styles.row}>
        <span className={styles.k}>레짐</span>
        <span>{plan.regime === 'UNKNOWN' ? '데이터 없음' : plan.regime}</span>
      </div>
      <div className={styles.row}>
        <span className={styles.k}>큰손</span>
        <span>{flowKo(analysis)}</span>
      </div>

      <div className={styles.horizons}>
        {horizons.map((h) => (
          <div key={h.id} className={styles.horizon} data-h={h.status}>
            <span>{h.labelKo}</span>
            <strong>
              {h.status === 'LONG' ? '롱' : h.status === 'SHORT' ? '숏' : h.status === 'WAIT' ? '대기' : '데이터 없음'}
            </strong>
          </div>
        ))}
      </div>

      <dl className={styles.grid}>
        <div>
          <dt>진입</dt>
          <dd>
            {plan.entryLow != null && plan.entryHigh != null
              ? `${formatPriceCompact(plan.entryLow)} ~ ${formatPriceCompact(plan.entryHigh)}`
              : '대기'}
          </dd>
        </div>
        <div>
          <dt>손절</dt>
          <dd>{formatPriceCompact(plan.sl)}</dd>
        </div>
        <div>
          <dt>TP1 / TP2 / TP3</dt>
          <dd>
