/**
 * PHASE 10/11 — Internal ML. No external LLM. Chronological fit only.
 * Raw longScore is never a probability. n<30 → 통계 부족.
 */
import type { SetupFamily, SetupOutcome } from './zoneExpectancy';
import { chronologicalSplit, rejectShuffledSplit } from './chronologicalSplit';
import { EAGLE1_MIN_STAT_SAMPLE } from './noFakeNumbers';
import type { Eagle1Regime } from './structureEngine';

export type Eagle1MlTask =
  | 'direction'
  | 'zone_hold'
  | 'zone_break'
  | 'breakout'
  | 'reaction_magnitude';

export type Eagle1MlQuery = {
  regime: Eagle1Regime | string;
  family: SetupFamily;
  direction: 'LONG' | 'SHORT';
  grossRr: number | null;
  asOfIndex?: number;
};

export type Eagle1MlTaskResult = {
  task: Eagle1MlTask;
  sampleSize: number;
  trainN: number;
  holdoutN: number;
  probability: number | null;
  calibratedProbability: number | null;
  expectedMoveR: number | null;
  calibrationError: number | null;
  label: '검증확률' | '통계 부족';
  note: string;
};

export type Eagle1MlReport = {
  available: boolean;
  backend: 'logistic-ts';
  tasks: Eagle1MlTaskResult[];
  directionProbability: number | null;
  calibratedProbability: number | null;
  calibratedLabel: '검증확률' | '통계 부족';
  expectedMoveR: number | null;
  note: string;
};

const MIN = EAGLE1_MIN_STAT_SAMPLE;
const HOLD_MIN = 10;
const CALIB_MAX = 0.2;

function causal(rows: SetupOutcome[], asOfIndex?: number): SetupOutcome[] {
  const ordered = [...rows].sort((a, b) => a.index - b.index);
  if (asOfIndex == null || !Number.isFinite(asOfIndex)) return ordered;
  return ordered.filter((r) => r.index < asOfIndex);
}

function encode(row: { regime: string; family: string; direction: string; grossRr: number | null }): number[] {
  const rr = row.grossRr != null && Number.isFinite(row.grossRr) ? Math.min(4, Math.max(0, row.grossRr)) / 4 : 0.5;
  return [
    row.direction === 'LONG' ? 1 : 0,
    String(row.regime).includes('BULL') ? 1 : 0,
    String(row.regime).includes('BEAR') ? 1 : 0,
    row.family === 'ob_retest' ? 1 : 0,
    row.family === 'fvg_retest' ? 1 : 0,
    row.family.startsWith('poc') ? 1 : 0,
    row.family === 'sweep_reversal' ? 1 : 0,
    rr,
  ];
}

function sigmoid(z: number): number {
  if (z > 20) return 1;
  if (z < -20) return 0;
  return 1 / (1 + Math.exp(-z));
}

function fitLogistic(X: number[][], y: number[]): { w: number[]; b: number } {
  const d = X[0]?.length ?? 0;
  const w = Array(d).fill(0);
  let b = 0;
  const lr = 0.25;
  const steps = 64;
  const n = X.length || 1;
  for (let s = 0; s < steps; s++) {
    const gw = Array(d).fill(0);
    let gb = 0;
    for (let i = 0; i < X.length; i++) {
      const xi = X[i]!;
      let z = b;
      for (let j = 0; j < d; j++) z += w[j]! * xi[j]!;
      const e = sigmoid(z) - y[i]!;
      for (let j = 0; j < d; j++) gw[j] += e * xi[j]!;
      gb += e;
    }
    for (let j = 0; j < d; j++) w[j] -= (lr * gw[j]!) / n;
    b -= (lr * gb) / n;
  }
  return { w, b };
}

function predictOne(model: { w: number[]; b: number }, x: number[]): number {
  let z = model.b;
  for (let j = 0; j < model.w.length; j++) z += model.w[j]! * (x[j] ?? 0);
  return sigmoid(z);
}

function emptyTask(task: Eagle1MlTask, n: number, note: string): Eagle1MlTaskResult {
  return {
    task,
    sampleSize: n,
    trainN: 0,
    holdoutN: 0,
    probability: null,
    calibratedProbability: null,
    expectedMoveR: null,
    calibrationError: null,
    label: '통계 부족',
    note,
  };
}

function emptyReport(note: string): Eagle1MlReport {
  return {
    available: false,
    backend: 'logistic-ts',
    tasks: [],
    directionProbability: null,
    calibratedProbability: null,
    calibratedLabel: '통계 부족',
    expectedMoveR: null,
    note,
  };
}

function runBinaryTask(
  task: Eagle1MlTask,
  rows: SetupOutcome[],
  yOf: (r: SetupOutcome) => number,
  query: Eagle1MlQuery
): Eagle1MlTaskResult {
  if (rows.length < MIN) return emptyTask(task, rows.length, '통계 부족');
  const split = chronologicalSplit(rows.length);
  const shuffleErr = rejectShuffledSplit(split);
  if (shuffleErr) return emptyTask(task, rows.length, '통계 부족');
  const train = split.train.map((i) => rows[i]!).filter(Boolean);
  const hold = split.holdout.map((i) => rows[i]!).filter(Boolean);
  if (train.length < MIN) return emptyTask(task, rows.length, '통계 부족');
  const X = train.map((r) => encode(r));
  const y = train.map(yOf);
  const model = fitLogistic(X, y);
  const qx = encode({
    regime: query.regime,
    family: query.family,
    direction: query.direction,
    grossRr: query.grossRr,
  });
  const raw = predictOne(model, qx);
  let calibrated: number | null = null;
  let err: number | null = null;
  if (hold.length >= HOLD_MIN) {
    const pHold = hold.map(yOf).reduce((a, b) => a + b, 0) / hold.length;
    const pTrain = y.reduce((a, b) => a + b, 0) / y.length;
    err = Math.abs(pTrain - pHold);
    calibrated = err <= CALIB_MAX ? pHold : null;
  }
  const mag = train.map((r) => r.mfe).sort((a, b) => a - b);
  const mid = mag[Math.floor(mag.length / 2)] ?? null;
  return {
    task,
    sampleSize: rows.length,
    trainN: train.length,
    holdoutN: hold.length,
    probability: raw,
    calibratedProbability: calibrated,
    expectedMoveR: task === 'reaction_magnitude' ? mid : null,
    calibrationError: err,
    label: calibrated != null ? '검증확률' : '통계 부족',
    note: calibrated != null ? `홀드아웃 ${hold.length}` : '통계 부족',
  };
}

export function runInternalMl(rows: SetupOutcome[], query: Eagle1MlQuery): Eagle1MlReport {
  const pool = causal(rows, query.asOfIndex);
  if (pool.length < MIN) return emptyReport(pool.length ? '통계 부족' : '데이터 없음');

  const holdFam = new Set(['poc_hold', 'poc_reclaim', 'ob_retest', 'fvg_retest']);
  const direction = runBinaryTask('direction', pool, (r) => (r.tpFirst ? 1 : 0), query);
  const zoneHold = runBinaryTask(
    'zone_hold',
    pool.filter((r) => holdFam.has(r.family)),
    (r) => (r.tpFirst ? 1 : 0),
    query
  );
  const zoneBreak = runBinaryTask('zone_break', pool, (r) => (r.slFirst ? 1 : 0), query);
  const breakout = runBinaryTask('breakout', pool, (r) => (r.mfe >= 1.5 ? 1 : 0), query);
  const magnitude = runBinaryTask('reaction_magnitude', pool, (r) => (r.mfe >= 1 ? 1 : 0), query);

  const calibrated = direction.calibratedProbability;
  return {
    available: true,
    backend: 'logistic-ts',
    tasks: [direction, zoneHold, zoneBreak, breakout, magnitude],
    directionProbability: direction.probability,
    calibratedProbability: calibrated,
    calibratedLabel: calibrated != null ? '검증확률' : '통계 부족',
    expectedMoveR: magnitude.expectedMoveR,
    note: calibrated != null ? '내부 로지스틱 · 홀드아웃 보정' : '내부 로지스틱 · 통계 부족',
  };
}

export function mlShellKo(report: Eagle1MlReport | null | undefined): string {
  if (!report) return '데이터 없음';
  if (!report.available || report.calibratedLabel === '통계 부족') {
    return report.note || '통계 부족';
  }
  return report.note;
}

/**
 * Independent expert votes. Confidence is a heuristic score, never UI 검증확률.
 */
import type { StructureSnapshot } from './structureEngine';
import type { ZoneEngineResult } from './zoneEngine';
import type { Eagle1RiskPlan } from './riskEngine';
import type { SimilarityReport } from './historicalSimilarity';
import type { Eagle1MlReport } from './internalMl';
import type { Eagle1MoneyPressure } from './moneyPressureBand';
import { moneyFlowSide } from './moneyPressureBand';

export type ExpertVoteKind = 'LONG' | 'SHORT' | 'NEUTRAL';

export type ExpertName =
  | 'Structure'
  | 'POC'
  | 'BigMoney'
  | 'Microstructure'
  | 'Derivatives'
  | 'Zone'
  | 'Historical'
  | 'ML'
  | 'Risk';

export type ExpertVote = {
  name: ExpertName;
  vote: ExpertVoteKind;
  /** 0-1 heuristic. Not a historical probability. */
  score: number;
  note: string;
};

export function voteExperts(params: {
  structure: StructureSnapshot;
  zones: ZoneEngineResult;
  risk: Eagle1RiskPlan;
  moneyPressure?: Eagle1MoneyPressure | null;
  similarity?: SimilarityReport | null;
  ml?: Eagle1MlReport | null;
  hasDerivatives?: boolean;
}): ExpertVote[] {
  const lastShift = [...params.structure.events].reverse().find((e) => e.kind === 'CHOCH' || e.kind === 'BOS');
  const structureVote: ExpertVoteKind =
    lastShift?.bias === 'bullish' ? 'LONG' : lastShift?.bias === 'bearish' ? 'SHORT' : 'NEUTRAL';
  const poc = params.zones.profile.pocState;
  const pocVote: ExpertVoteKind =
    poc === 'RECLAIMED' || poc === 'CLOSED_ABOVE' ? 'LONG' : poc === 'LOST' || poc === 'CLOSED_BELOW' ? 'SHORT' : 'NEUTRAL';
  const flow = moneyFlowSide(params.moneyPressure?.state);
  const moneyVote: ExpertVoteKind = flow === 'long' ? 'LONG' : flow === 'short' ? 'SHORT' : 'NEUTRAL';
  const microVote: ExpertVoteKind =
    params.moneyPressure?.absorbed && moneyVote !== 'NEUTRAL' ? moneyVote : moneyVote;
  const derivVote: ExpertVoteKind = 'NEUTRAL';
  const rec = params.zones.recommended;
  const rx = params.zones.reaction;
  let zoneVote: ExpertVoteKind = rec?.bias === 'bullish' ? 'LONG' : rec?.bias === 'bearish' ? 'SHORT' : 'NEUTRAL';
  if (rx?.kind === 'HOLD' || rx?.kind === 'RECLAIM' || rx?.kind === 'RETEST') {
    zoneVote = rx.bias === 'bearish' ? 'SHORT' : 'LONG';
  }
  const sim = params.similarity;
  const histVote: ExpertVoteKind =
    sim && sim.sampleSize >= 30 && sim.calibratedProbability != null
      ? sim.calibratedProbability >= 0.5
        ? params.risk.direction ?? 'NEUTRAL'
        : params.risk.direction === 'LONG'
          ? 'SHORT'
          : params.risk.direction === 'SHORT'
            ? 'LONG'
            : 'NEUTRAL'
      : 'NEUTRAL';
  const mlVote: ExpertVoteKind =
    params.ml?.calibratedProbability != null
      ? params.ml.calibratedProbability >= 0.5
        ? params.risk.direction ?? 'NEUTRAL'
        : 'NEUTRAL'
      : 'NEUTRAL';
  const riskVote: ExpertVoteKind =
    params.risk.rrGate === 'reject' || params.risk.rrGate === 'none' ? 'NEUTRAL' : params.risk.direction ?? 'NEUTRAL';

  return [
    { name: 'Structure', vote: structureVote, score: structureVote === 'NEUTRAL' ? 0.3 : 0.7, note: lastShift ? `${lastShift.kind}` : '데이터 없음' },
    { name: 'POC', vote: pocVote, score: pocVote === 'NEUTRAL' ? 0.3 : 0.65, note: poc },
    { name: 'BigMoney', vote: moneyVote, score: moneyVote === 'NEUTRAL' ? 0.25 : 0.6, note: params.moneyPressure?.stateKo || '데이터 없음' },
    {
      name: 'Microstructure',
      vote: microVote,
      score: params.moneyPressure?.absorbed ? 0.7 : 0.4,
      note: params.moneyPressure?.note || '데이터 없음',
    },
    {
      name: 'Derivatives',
      vote: derivVote,
      score: 0,
      note: params.hasDerivatives ? '파생 입력' : '데이터 없음',
    },
    { name: 'Zone', vote: zoneVote, score: zoneVote === 'NEUTRAL' ? 0.3 : 0.65, note: rec?.labelKo || rx?.kind || '데이터 없음' },
    {
      name: 'Historical',
      vote: histVote,
      score: sim && sim.sampleSize >= 30 ? 0.8 : 0.2,
      note: sim?.calibratedLabel || '통계 부족',
    },
    { name: 'ML', vote: mlVote, score: params.ml?.calibratedProbability != null ? 0.7 : 0.15, note: params.ml?.note || '통계 부족' },
    { name: 'Risk', vote: riskVote, score: params.risk.rrGate === 'prioritize' ? 0.8 : params.risk.rrGate === 'confirm_candidate' ? 0.6 : 0.2, note: params.risk.rrGate },
  ];
}

/**
 * PHASE 11 — Consensus + calibration + OOD.
 * UI 검증확률 ≠ AI score. Holdout never trains weights.
 */
import type { SetupOutcome } from './zoneExpectancy';
import { chronologicalSplit, rejectShuffledSplit } from './chronologicalSplit';
import { EAGLE1_MIN_STAT_SAMPLE } from './noFakeNumbers';
import type { ExpertVote } from './expertModels';
import type { SimilarityReport } from './historicalSimilarity';
import type { Eagle1MlReport } from './internalMl';
import type { Eagle1Regime } from './structureEngine';

export type Eagle1Ood = {
  flagged: boolean;
  label: 'UNKNOWN MARKET' | 'ok';
  reasons: string[];
};

export type Eagle1ConsensusReport = {
  longScore: number;
  shortScore: number;
  agreementScore: number;
  /** Heuristic 0-100. Never shown as 검증확률. */
  aiScore: number;
  calibratedProbability: number | null;
  calibratedLabel: '검증확률' | '통계 부족';
  sampleSize: number;
  votes: ExpertVote[];
  ood: Eagle1Ood;
  weightsNote: string;
  note: string;
};

const MIN = EAGLE1_MIN_STAT_SAMPLE;

function expertWeight(v: ExpertVote, trainN: number): number {
  if (v.name === 'Derivatives' && v.note === '데이터 없음') return 0;
  if (v.name === 'Historical' || v.name === 'ML') {
    return trainN >= MIN && v.vote !== 'NEUTRAL' ? 1.4 : 0.6;
  }
  if (v.vote === 'NEUTRAL') return 0.4;
  return 1;
}

export function detectOod(params: {
  regime: Eagle1Regime;
  sampleSize: number;
  similarity?: SimilarityReport | null;
  spreadBps?: number | null;
  agreementScore: number;
  qualityBlocked?: boolean;
}): Eagle1Ood {
  const reasons: string[] = [];
  if (params.regime === 'UNKNOWN' || params.regime === 'VOLATILITY_EXPANSION') reasons.push('레짐 불명/급변동');
  if (params.sampleSize < MIN) reasons.push('표본 부족');
  if (params.similarity && params.similarity.sampleSize > 0 && params.similarity.sampleSize < MIN) {
    reasons.push('유사국면 표본 부족');
  }
  if (params.similarity?.filter.includes('완화') && (params.similarity.sampleSize < 40 || params.similarity.calibratedProbability == null)) {
    reasons.push('유사도 낮음');
  }
  if (params.spreadBps != null && params.spreadBps > 12) reasons.push('스프레드 이상');
  if (params.agreementScore < 12) reasons.push('모델 합의 부족');
  if (params.qualityBlocked) reasons.push('데이터 품질');
  return {
    flagged: reasons.length > 0,
    label: reasons.length > 0 ? 'UNKNOWN MARKET' : 'ok',
    reasons,
  };
}

export function runConsensus(params: {
  votes: ExpertVote[];
  outcomes?: SetupOutcome[];
  asOfIndex?: number;
  similarity?: SimilarityReport | null;
  ml?: Eagle1MlReport | null;
  regime: Eagle1Regime;
  spreadBps?: number | null;
  qualityBlocked?: boolean;
}): Eagle1ConsensusReport {
  const ordered = [...(params.outcomes ?? [])].sort((a, b) => a.index - b.index);
  const causal =
    params.asOfIndex != null && Number.isFinite(params.asOfIndex)
      ? ordered.filter((r) => r.index < params.asOfIndex!)
      : ordered;
  const split = chronologicalSplit(causal.length);
  const shuffleErr = causal.length ? rejectShuffledSplit(split) : null;
  const trainN = shuffleErr ? 0 : split.train.length;

  let longW = 0;
  let shortW = 0;
  for (const v of params.votes) {
    const w = expertWeight(v, trainN) * v.score;
    if (v.vote === 'LONG') longW += w;
    else if (v.vote === 'SHORT') shortW += w;
  }
  const tot = longW + shortW;
  const longScore = tot > 0 ? (100 * longW) / tot : 50;
  const shortScore = tot > 0 ? (100 * shortW) / tot : 50;
  const agreementScore = Math.abs(longScore - shortScore);
  const aiScore = Math.max(longScore, shortScore);

  const simP = params.similarity?.calibratedProbability ?? null;
  const simN = params.similarity?.sampleSize ?? 0;
  const mlP = params.ml?.calibratedProbability ?? null;
  const calibratedProbability =
    simP != null && simN >= MIN ? simP : mlP != null && (params.ml?.tasks[0]?.holdoutN ?? 0) >= 10 ? mlP : null;
  const sampleSize = Math.max(simN, causal.length);

  const ood = detectOod({
    regime: params.regime,
    sampleSize,
    similarity: params.similarity,
    spreadBps: params.spreadBps,
    agreementScore,
    qualityBlocked: params.qualityBlocked,
  });

  return {
    longScore,
    shortScore,
    agreementScore,
    aiScore,
    calibratedProbability: ood.flagged ? null : calibratedProbability,
    calibratedLabel: !ood.flagged && calibratedProbability != null ? '검증확률' : '통계 부족',
    sampleSize,
    votes: params.votes,
    ood,
    weightsNote: trainN >= MIN ? `학습표본 ${trainN} · 홀드아웃 가중 미사용` : '동일가중 · 통계 부족',
    note: ood.flagged
      ? `UNKNOWN MARKET · ${ood.reasons[0]}`
      : calibratedProbability != null
        ? `합의 ${agreementScore.toFixed(0)} · 검증확률 사용`
        : `합의 ${agreementScore.toFixed(0)} · 통계 부족`,
  };
}

export function consensusShellKo(report: Eagle1ConsensusReport | null | undefined): string {
  if (!report) return '데이터 없음';
  if (report.ood.flagged) return report.note;
  return report.note;
}

/**
 * PHASE 13 — Smart path. Geometry freezes at confirm. Not a prophecy.
 */
import { buildFrozenPath, type FrozenPathPoint, type FrozenTrade } from './tradeManage';
import type { Eagle1RiskPlan } from './riskEngine';
import { EAGLE1_MIN_STAT_SAMPLE } from './noFakeNumbers';

export type Eagle1PathScenario = {
  id: 'main' | 'alt' | 'invalid';
  labelKo: string;
  state: '진행중' | '이탈주의' | '무효' | '대기';
  points: FrozenPathPoint[];
  probability: number | null;
  note: string;
};

export type Eagle1SmartPath = {
  main: Eagle1PathScenario;
  alt: Eagle1PathScenario;
  invalid: Eagle1PathScenario;
  frozen: boolean;
};

function emptyScenario(id: Eagle1PathScenario['id'], labelKo: string): Eagle1PathScenario {
  return {
    id,
    labelKo,
    state: '대기',
    points: [],
    probability: null,
    note: '데이터 없음',
  };
}

export function buildSmartPath(params: {
  lastTime: number;
  tfSec: number;
  direction: 'LONG' | 'SHORT' | null;
  risk: Eagle1RiskPlan;
  trade?: FrozenTrade | null;
  sampleSize?: number;
  calibratedProbability?: number | null;
}): Eagle1SmartPath {
  const dir = params.direction ?? params.risk.direction;
  const entry =
    params.risk.entryLow != null && params.risk.entryHigh != null
      ? (params.risk.entryLow + params.risk.entryHigh) / 2
      : null;
  const sl = params.risk.executableSl;
  const n = params.sampleSize ?? 0;
  const p = n >= EAGLE1_MIN_STAT_SAMPLE ? params.calibratedProbability ?? null : null;
  const pNote = p != null ? '표본 보정' : '통계 부족';

  if (!dir || entry == null || sl == null || params.risk.tp1 == null) {
    return {
      main: emptyScenario('main', '주경로'),
      alt: { ...emptyScenario('alt', '대체경로'), note: '반대 셋업이 따로 확정되기 전엔 대기' },
      invalid: emptyScenario('invalid', '무효'),
      frozen: false,
    };
  }

  const built = params.trade
    ? { path: params.trade.path, altPath: params.trade.altPath }
    : buildFrozenPath({
        lastTime: params.lastTime,
        tfSec: params.tfSec,
        direction: dir,
        entry,
        sl,
        tp1: params.risk.tp1,
        tp2: params.risk.tp2,
        tp3: params.risk.tp3,
      });

  const state = params.trade?.pathState ?? '진행중';
  return {
    main: {
      id: 'main',
      labelKo: '주경로',
      state,
      points: built.path,
      probability: p,
      note: `${dir === 'LONG' ? '위쪽' : '아래쪽'} 구조 목표 · ${pNote}`,
    },
    alt: {
      id: 'alt',
      labelKo: '대체경로',
      state: state === '무효' ? '진행중' : '대기',
      points: [],
      probability: p != null ? Math.max(0, 1 - p) : null,
      note: '무효 후에도 반대 셋업이 따로 확정되기 전엔 대기',
    },
    invalid: {
      id: 'invalid',
      labelKo: '무효',
      state: state === '무효' ? '무효' : '대기',
      points: built.altPath,
      probability: null,
      note: '구조 손절선 — 확률 단정 없음',
    },
    frozen: Boolean(params.trade),
  };
}

export function smartPathShellKo(path: Eagle1SmartPath | null | undefined): string {
  if (!path) return '데이터 없음';
  const p = path.main.probability != null ? `검증확률 ${Math.round(path.main.probability * 100)}%` : '통계 부족';
  return `${path.main.labelKo} ${path.main.state} · ${p}`;
}

/**
 * PHASE 14 — Walk-forward backtest. Holdout never updates weights.
 */
import type { SetupOutcome } from './zoneExpectancy';
import { chronologicalSplit, rejectShuffledSplit } from './chronologicalSplit';
import { EAGLE1_MIN_STAT_SAMPLE } from './noFakeNumbers';

export type Eagle1WalkFold = {
  fold: number;
  trainN: number;
  testN: number;
  netEv: number | null;
  profitFactor: number | null;
  maxDd: number | null;
  tpBeforeSlRate: number | null;
  usedForWeights: boolean;
};

export type Eagle1WalkForwardReport = {
  folds: Eagle1WalkFold[];
  holdoutN: number;
  holdoutNetEv: number | null;
  holdoutPf: number | null;
  holdoutMaxDd: number | null;
  holdoutCalibration: number | null;
  holdoutUsedForWeights: false;
  sampleSize: number;
  label: '검증확률' | '통계 부족';
  note: string;
};

const MIN = EAGLE1_MIN_STAT_SAMPLE;

function metrics(rows: SetupOutcome[]): { netEv: number | null; pf: number | null; maxDd: number | null; tp: number | null } {
  const n = rows.length;
  if (n < MIN) return { netEv: null, pf: null, maxDd: null, tp: null };
  const nets = rows.map((r) => r.netR);
  const netEv = nets.reduce((a, b) => a + b, 0) / n;
  const wins = nets.filter((x) => x > 0).reduce((a, b) => a + b, 0);
  const losses = Math.abs(nets.filter((x) => x < 0).reduce((a, b) => a + b, 0));
  const pf = losses > 0 ? wins / losses : wins > 0 ? null : null;
  let eq = 0;
  let peak = 0;
  let maxDd = 0;
  for (const x of nets) {
    eq += x;
    if (eq > peak) peak = eq;
    maxDd = Math.max(maxDd, peak - eq);
  }
  const tp = rows.filter((r) => r.tpFirst).length / n;
  return { netEv, pf, maxDd, tp };
}

export function walkForwardBacktest(rows: SetupOutcome[]): Eagle1WalkForwardReport {
  const ordered = [...rows].sort((a, b) => a.index - b.index);
  const empty: Eagle1WalkForwardReport = {
    folds: [],
    holdoutN: 0,
    holdoutNetEv: null,
    holdoutPf: null,
    holdoutMaxDd: null,
    holdoutCalibration: null,
    holdoutUsedForWeights: false,
    sampleSize: ordered.length,
    label: '통계 부족',
    note: ordered.length ? '통계 부족' : '데이터 없음',
  };
  if (ordered.length < MIN) return empty;

  const split = chronologicalSplit(ordered.length);
  const bad = rejectShuffledSplit(split);
  if (bad) return { ...empty, note: '통계 부족' };

  const trainVal = [...split.train, ...split.validation].map((i) => ordered[i]!).filter(Boolean);
  const hold = split.holdout.map((i) => ordered[i]!).filter(Boolean);
  const folds: Eagle1WalkFold[] = [];
  const step = Math.max(MIN, Math.floor(trainVal.length / 3));
  let fold = 0;
  for (let end = MIN; end <= trainVal.length; end += step) {
    const train = trainVal.slice(0, Math.max(MIN, end - Math.floor(step / 2)));
    const test = trainVal.slice(train.length, end);
    if (test.length < 8) continue;
    const m = metrics(test);
    folds.push({
      fold: fold++,
      trainN: train.length,
      testN: test.length,
      netEv: m.netEv,
      profitFactor: m.pf,
      maxDd: m.maxDd,
      tpBeforeSlRate: m.tp,
      usedForWeights: true,
    });
  }

  const holdM = metrics(hold);
  const trainM = metrics(trainVal);
  const calib =
    trainM.tp != null && holdM.tp != null ? Math.abs(trainM.tp - holdM.tp) : null;
  const ok = hold.length >= 10 && holdM.netEv != null;
  return {
    folds,
    holdoutN: hold.length,
    holdoutNetEv: holdM.netEv,
    holdoutPf: holdM.pf,
    holdoutMaxDd: holdM.maxDd,
    holdoutCalibration: calib,
    holdoutUsedForWeights: false,
    sampleSize: ordered.length,
    label: ok ? '검증확률' : '통계 부족',
    note: ok
      ? `홀드아웃 ${hold.length} · 가중 미사용 · EV ${holdM.netEv!.toFixed(2)}R`
      : '통계 부족',
  };
}

export function walkForwardShellKo(report: Eagle1WalkForwardReport | null | undefined): string {
  if (!report) return '데이터 없음';
  return report.note;
}

/**
 * PHASE 16 — Statistics dashboard. Measured rows only. UI never invents %.
 */
import { EAGLE1_ENGINE_VERSION } from './rawTypes';
import { EAGLE1_MIN_STAT_SAMPLE } from './noFakeNumbers';
import type { SimilarityReport } from './historicalSimilarity';
import type { Eagle1MlReport } from './internalMl';
import type { Eagle1ConsensusReport } from './consensusEngine';
import type { Eagle1WalkForwardReport } from './walkForwardBacktest';
import type { Eagle1SnapshotStats } from './predictionSnapshot';
import type { ExpertVote } from './expertModels';

export type Eagle1StatRow = {
  key: string;
  labelKo: string;
  value: string;
};

export type Eagle1StatsDashboard = {
  rows: Eagle1StatRow[];
  models: Array<{ name: string; vote: string; note: string }>;
  engineVersion: string;
  sampleSize: number;
  label: '검증확률' | '통계 부족';
};

function pctOrShort(p: number | null | undefined, n: number): string {
  if (n < EAGLE1_MIN_STAT_SAMPLE || p == null || !Number.isFinite(p)) return '통계 부족';
  return `${Math.round(p * 100)}%`;
}

export function buildStatsDashboard(params: {
  similarity?: SimilarityReport | null;
  ml?: Eagle1MlReport | null;
  consensus?: Eagle1ConsensusReport | null;
  walkForward?: Eagle1WalkForwardReport | null;
  snapshotStats?: Eagle1SnapshotStats | null;
  votes?: ExpertVote[];
}): Eagle1StatsDashboard {
  const n = Math.max(
    params.similarity?.sampleSize ?? 0,
    params.walkForward?.sampleSize ?? 0,
    params.snapshotStats?.sampleSize ?? 0
  );
  const rows: Eagle1StatRow[] = [
    { key: 'sample', labelKo: '표본', value: n > 0 ? `표본 ${n}` : '데이터 없음' },
    {
      key: 'calibrated',
      labelKo: '검증확률',
      value: pctOrShort(params.consensus?.calibratedProbability ?? params.similarity?.calibratedProbability, n),
    },
    {
      key: 'ai',
      labelKo: 'AI점수',
      value: params.consensus ? `${params.consensus.aiScore.toFixed(0)} (확률 아님)` : '데이터 없음',
    },
    {
      key: 'tp',
      labelKo: 'TP선도달',
      value: pctOrShort(params.similarity?.tpBeforeSlRate ?? params.snapshotStats?.tpBeforeSlRate, n),
    },
    {
      key: 'ev',
      labelKo: '순기대',
      value:
        n >= EAGLE1_MIN_STAT_SAMPLE && params.similarity?.netExpectancy != null
          ? `${params.similarity.netExpectancy >= 0 ? '+' : ''}${params.similarity.netExpectancy.toFixed(2)}R`
          : '통계 부족',
    },
    {
      key: 'mfe',
      labelKo: 'MFE중앙',
      value:
        n >= EAGLE1_MIN_STAT_SAMPLE && params.similarity?.medianMfe != null
          ? `${params.similarity.medianMfe.toFixed(2)}R`
          : '통계 부족',
    },
    {
      key: 'wf',
      labelKo: '워크포워드',
      value: params.walkForward?.note || '데이터 없음',
    },
    {
      key: 'ml',
      labelKo: '내부ML',
      value: params.ml?.note || '데이터 없음',
    },
    {
      key: 'ood',
      labelKo: 'OOD',
      value: params.consensus?.ood.flagged ? params.consensus.note : '정상',
    },
    { key: 'ver', labelKo: '엔진', value: EAGLE1_ENGINE_VERSION },
  ];
  return {
    rows,
    models: (params.votes ?? params.consensus?.votes ?? []).map((v) => ({
      name: v.name,
      vote: v.vote,
      note: v.note,
    })),
    engineVersion: EAGLE1_ENGINE_VERSION,
    sampleSize: n,
    label: n >= EAGLE1_MIN_STAT_SAMPLE && (params.consensus?.calibratedProbability != null || params.similarity?.calibratedProbability != null)
      ? '검증확률'
      : '통계 부족',
  };
}

/**
 * PHASE 17 — Telegram report formatter. Engine does not depend on send success.
 */
import { EAGLE1_ENGINE_VERSION } from './rawTypes';
import { eagle1DecisionKo, formatPriceCompact } from './chartUx';
import type { Eagle1MainPlan } from './signalEngine';
import type { Eagle1ConsensusReport } from './consensusEngine';
import type { Eagle1SmartPath } from './smartPath';

export type Eagle1TelegramPayload = {
  symbol?: string;
  timeframe?: string;
  plan: Eagle1MainPlan;
  consensus?: Eagle1ConsensusReport | null;
  smartPath?: Eagle1SmartPath | null;
  previousVersion?: string | null;
};

export function formatEagle1TelegramReport(p: Eagle1TelegramPayload): string {
  try {
    const plan = p.plan;
    const d = eagle1DecisionKo(plan.status);
    const entry =
      plan.entryLow != null && plan.entryHigh != null
        ? `${formatPriceCompact(plan.entryLow)}~${formatPriceCompact(plan.entryHigh)}`
        : '대기';
    const prob =
      plan.calibratedProbability != null && plan.sampleSize >= 30
        ? `${Math.round(plan.calibratedProbability * 100)}%`
        : '통계 부족';
    const rr = plan.netRr != null ? `1:${plan.netRr.toFixed(2)}` : '통계 부족';
    const ver =
      p.previousVersion && p.previousVersion !== EAGLE1_ENGINE_VERSION
        ? `${p.previousVersion} → ${EAGLE1_ENGINE_VERSION}`
        : EAGLE1_ENGINE_VERSION;
    const ood = p.consensus?.ood.flagged ? `\nOOD: ${p.consensus.note}` : '';
    const path = p.smartPath ? `\n경로: ${p.smartPath.main.labelKo} ${p.smartPath.main.state}` : '';
    return [
      `독수리1호 ${p.symbol ?? 'BTCUSDT'} ${p.timeframe ?? ''}`.trim(),
      `${d}`,
      `진입 ${entry}`,
      `손절 ${formatPriceCompact(plan.sl)}`,
      `목표 ${formatPriceCompact(plan.tp1)} / ${formatPriceCompact(plan.tp2)} / ${formatPriceCompact(plan.tp3)}`,
      `RR ${rr} · 검증확률 ${prob}`,
      `무효 ${plan.invalidation || '데이터 없음'}`,
      `버전 ${ver}${ood}${path}`,
      '확정 수익·투자 권유 아님',
    ].join('\n');
  } catch {
    return '데이터 없음';
  }
}

/** Never throws into the trading pipeline. */
export function safeEagle1TelegramReport(p: Eagle1TelegramPayload): string {
  try {
    return formatEagle1TelegramReport(p);
  } catch {
    return '데이터 없음';
  }
}

